#[derive(Debug, Clone)]
struct MachineDiagnostic(ncc_diagnostics::CanonicalDiagnostic);

impl MachineDiagnostic {
    fn new(code: &str, message: impl Into<String>) -> Self {
        Self(
            ncc_diagnostics::stage0_registered_diagnostic(
                ncc_diagnostics::DiagnosticSeverity::Error,
                code,
                message,
            )
            .with_domain(ncc_diagnostics::DiagnosticDomain::Machine),
        )
    }

    fn registered(code: &str, message: impl Into<String>) -> Self {
        Self::new(code, message)
    }

    fn canonical(&self) -> &ncc_diagnostics::CanonicalDiagnostic {
        &self.0
    }

    fn attach_file(&mut self, file: &str) {
        if self.0.file.is_empty() {
            self.0.file = file.to_string();
        }
    }
}

impl std::ops::Deref for MachineDiagnostic {
    type Target = ncc_diagnostics::CanonicalDiagnostic;

    fn deref(&self) -> &Self::Target {
        self.canonical()
    }
}

