pub(crate) fn run_machine_command(args: &[String]) -> Result<(), Box<dyn Error>> {
    if args.is_empty() || is_help(args.first()) {
        println!("{}", machine_help());
        return Ok(());
    }
    match args[0].as_str() {
        "doctor" => run_doctor(&args[1..]),
        "targets" => run_targets(&args[1..]),
        "target" => run_target(&args[1..]),
        "registers" => run_registers(&args[1..]),
        "instructions" => run_instructions(&args[1..]),
        "asm-complete" => run_asm_complete(&args[1..]),
        "vex" => run_vex(&args[1..]),
        "evex" => run_evex(&args[1..]),
        "avx512" => run_avx512(&args[1..]),
        "virtualization" | "vmx-svm" => run_virtualization(&args[1..]),
        "kernel-system" | "kernel" => super::machine_kernel::run_kernel_system_command(&args[1..]),
        "parity" => run_parity(&args[1..]),
        "cross-arch" => run_cross_arch(&args[1..]),
        "instruction-coverage" => run_instruction_coverage(&args[1..]),
        "encoding-coverage" => run_encoding_coverage(&args[1..]),
        "features" => run_features(&args[1..]),
        "cpu-profile" => run_cpu_profile(&args[1..]),
        "abi" => run_abi(&args[1..]),
        "interop" | "n-interop" | "compiler-interop" => run_machine_interop(&args[1..]),
        "check" => run_check(&args[1..]),
        "stdin" | "pipe" => run_machine_stdin(&args[1..]),
        "report" => run_report(&args[1..]),
        "emit-ir" => run_emit_ir(&args[1..]),
        "emit-asm" => run_emit_asm(&args[1..]),
        "emit-bytes" => run_emit_bytes(&args[1..]),
        "run-bytes" => run_run_bytes(&args[1..]),
        "__run-bytes-child" => run_run_bytes_child(&args[1..]),
        "emit-object" => run_emit_object(&args[1..], "elf"),
        "emit-elf" => run_emit_object(&args[1..], "elf"),
        "emit-coff" => run_emit_object(&args[1..], "coff"),
        "emit-macho" => run_emit_object(&args[1..], "macho"),
        "emit-wasm" => run_emit_object(&args[1..], "wasm"),
        "verify-object" => run_verify_object(&args[1..]),
        "debug-info" => run_debug_info(&args[1..]),
        "debug-bridge" => run_machine_debug_bridge(&args[1..]),
        "debug-attach" => run_machine_debug_attach(&args[1..]),
        "unwind-info" => run_unwind_info(&args[1..]),
        "debug-report" => run_debug_report(&args[1..]),
        "unwind-report" => run_unwind_report(&args[1..]),
        "link-smoke" => run_link_smoke(&args[1..]),
        "link" => run_phase12_link(&args[1..]),
        "build-exe" => run_phase12_build_exe(&args[1..]),
        "build-shared" => run_phase12_build_shared(&args[1..]),
        "build-staticlib" => run_phase12_build_staticlib(&args[1..]),
        "archive" => run_phase12_archive(&args[1..]),
        "verify-link" => run_phase12_verify_link(&args[1..]),
        "link-report" => run_phase12_link_report(&args[1..]),
        "link-map" => run_phase12_link_map(&args[1..]),
        "link-doctor" => run_phase12_link_doctor(&args[1..]),
        "board-template" => super::machine_board::run_board_template(&args[1..]),
        "certify-board" => super::machine_board::run_certify_board(&args[1..]),
        "verify-board-certificate" => {
            super::machine_board::run_verify_board_certificate(&args[1..])
        }
        "third-party-objects" | "third-party-matrix" => run_phase13_third_party_objects(&args[1..]),
        "external-tools" => run_phase13_external_tools(&args[1..]),
        "external-compat" => run_phase13_external_compat(&args[1..]),
        "fuzz" => run_phase14_fuzz(&args[1..]),
        "target-family-gate" => run_target_family_gate(&args[1..]),
        "target-admission" => run_target_admission(&args[1..]),
        "disasm" => run_disasm(&args[1..]),
        "disasm-object" => run_disasm(&args[1..]),
        "disasm-report" => run_disasm(&args[1..]),
        "disasm-bytes" => run_disasm_bytes(&args[1..]),
        "roundtrip" => run_roundtrip(&args[1..]),
        "roundtrip-object" => run_roundtrip(&args[1..]),
        "roundtrip-bytes" => run_roundtrip(&args[1..]),
        "roundtrip-report" => run_roundtrip(&args[1..]),
        "macro-report" => run_phase10_macro_report(&args[1..]),
        "directive-report" => run_phase10_directive_report(&args[1..]),
        "expand" => run_phase10_expand(&args[1..]),
        "ctfe-report" => run_phase10_ctfe_report(&args[1..]),
        "include-report" => run_phase10_include_report(&args[1..]),
        "incbin-report" => run_phase10_incbin_report(&args[1..]),
        "asm-dialect" => run_asm_dialect(&args[1..]),
        "export-asm" => run_export_asm(&args[1..]),
        "import-asm" => run_import_asm(&args[1..]),
        "asm-migrate" => run_asm_migrate(&args[1..]),
        "asm-import-back" => run_asm_import_back(&args[1..]),
        other => Err(format!(
            "[E_MACHINE_CLI_001] unknown machine command '{}'\n{}",
            other,
            machine_help()
        )
        .into()),
    }
}

pub(crate) fn check_machine_source_path(path: &str) -> Result<(), Box<dyn Error>> {
    let audit = audit_machine_file(path)?;
    if audit.has_errors() {
        Err(diagnostics_summary(&audit.diagnostics).into())
    } else {
        Ok(())
    }
}

fn is_help(arg: Option<&String>) -> bool {
    matches!(arg.map(String::as_str), Some("-h" | "--help" | "help"))
}

fn machine_help() -> &'static str {
    "Usage: machine <doctor|check|stdin|pipe|report|emit-ir|emit-asm|emit-bytes|run-bytes|emit-object|emit-elf|emit-coff|emit-macho|verify-object|debug-info|debug-bridge|debug-attach|unwind-info|debug-report|unwind-report|disasm|disasm-object|disasm-bytes|disasm-report|link|build-exe|build-shared|build-staticlib|archive|verify-link|link-report|link-map|link-doctor|board-template|certify-board|verify-board-certificate|third-party-objects|external-tools|external-compat|fuzz|target|targets|target-admission|abi|interop|registers|instructions|asm-complete|vex|evex|avx512|virtualization|kernel-system|parity|cross-arch|instruction-coverage|encoding-coverage|features|cpu-profile|roundtrip|macro-report|directive-report|expand|ctfe-report|include-report|incbin-report|asm-dialect|export-asm|import-asm|asm-migrate|asm-import-back> [args]\n\
     Examples:\n\
       ncc machine doctor --json\n\
       ncc machine virtualization --json\n\
       ncc machine virtualization probe-backends --json\n\
       ncc machine virtualization probe-host --json\n\
       ncc machine virtualization certify-host --out hardware-certificate.json\n\
       ncc machine virtualization verify-certificate hardware-certificate.json --require-bare-metal\n\
       ncc machine virtualization certify-backend --provider kvm --out kvm-certificate.json\n\
       ncc machine virtualization verify-backend-certificate kvm-certificate.json\n\
       ncc machine virtualization probe-iommu --json\n\
       ncc machine virtualization certify-viommu --out viommu-certificate.json\n\
       ncc machine virtualization certify-vfio --group 12 --device 0000:03:00.0 --out vfio-control.json\n\
       ncc machine virtualization certify-vfio --group 12 --device 0000:03:00.0 --exercise vfio-dma-exercise.json --out vfio-physical.json\n\
       ncc machine virtualization verify-iommu-certificate vfio-physical.json\n\
       ncc machine virtualization prepare-guest --boot bzimage --kernel bzImage --initrd initrd.img --disk root.img --cmdline \"console=ttyS0 root=/dev/vda\" --bundle guest-bundle\n\
       ncc machine virtualization boot-guest --boot bzimage --kernel bzImage --initrd initrd.img --disk root.img --cmdline \"console=ttyS0 root=/dev/vda\" --bundle guest-run --mmio-trace-out guest-run/mmio.json\n\
       ncc machine virtualization verify-guest-certificate guest-certificate.json\n\
       ncc machine virtualization certify-migration --memory-mib 16 --vcpus 4 --bundle migration-bundle\n\
       ncc machine virtualization verify-migration-certificate migration-certificate.json\n\
       ncc machine asm-complete doctor --json\n\
       ncc machine check examples/machine/add_two_sysv64.nm\n\
       type program.nm | ncc machine stdin check --syntax nm\n\
       Get-Content -Raw program.asm | ncc machine stdin emit-object --syntax nasm --target x86_64-pc-windows-msvc --out program.obj\n\
       cat program.s | ncc machine stdin build-exe --syntax gas-att --target x86_64-unknown-linux-gnu --out program\n\
       cat module.wasm | ncc machine stdin disasm --syntax wasm --json\n\
       ncc machine emit-bytes examples/machine/add_two_sysv64.nm --out target/tmp/add_two.bin\n\
       ncc machine run-bytes examples/machine/jit_return42_x86_64.nm --expect-return 42 --timeout-ms 5000 --json\n\
       ncc machine emit-object examples/machine/add_two_sysv64.nm --target x86_64-unknown-linux-gnu --out target/tmp/add_two.o\n\
       ncc machine disasm target/tmp/add_two.o --json\n\
       ncc machine debug-info target/tmp/add_two.o --json\n\
       ncc machine debug-bridge examples/machine/native/debug_unwind_elf64_x86_64.nm --trace --json\n\
       ncc machine debug-attach probe --json\n\
       ncc machine macro-report examples/machine/native/macro_basic_x86_64.nm --json\n\
       ncc machine expand examples/machine/native/macro_params_x86_64.nm --json\n\
       ncc machine asm-dialect doctor --json\n\
       ncc machine import-asm examples/machine/dialects/nasm/profile_closed.asm --syntax nasm --out target/tmp/nasm_imported.nm --json\n\
       ncc machine asm-import-back examples/machine/native/macro_basic_x86_64.nm --syntax nasm --json\n\
       ncc machine link target/tmp/a.o target/tmp/b.o --target x86_64-unknown-linux-gnu --out target/tmp/linked --map target/tmp/linked.map --json\n\
       ncc machine verify-link target/tmp/linked --json\n\
       ncc machine third-party-objects --json --out-dir target/tmp/machine_third_party_objects\n\
       ncc machine external-tools --json\n\
       ncc machine external-compat validate target/tmp/add_two.o --profile elf64 --json\n\
       ncc machine fuzz all --smoke --json\n\
       ncc machine target-admission doctor --json\n\
       ncc machine target-admission avr-atmega328p-none-elf --json\n\
       ncc machine parity --json\n\
       ncc machine cross-arch doctor --json\n\
       ncc machine interop examples/09_ffi/machine_interop_bridge.n --target x86_64-unknown-linux-gnu --json\n\
       ncc machine link-smoke examples/machine/add_two_sysv64.nm --json\n\
       ncc machine link-smoke examples/machine/native/link_final_linux_exit42.nm --target x86_64-unknown-linux-gnu --system-loader --expect-exit 42 --json\n\
       ncc machine board-template --target aarch64-unknown-none --out board.json --json\n\
       ncc machine certify-board --manifest board.json --bundle target/board-certification --json\n\
       ncc machine certify-board --manifest board.json --bundle target/board-validation --validate-only --json\n\
       ncc machine verify-board-certificate target/board-certification --signing-key-env NCC_BOARD_HMAC_KEY --json"
}

fn run_doctor(args: &[String]) -> Result<(), Box<dyn Error>> {
    let payload = machine_doctor_json();
    if has_flag(args, "--json") {
        print_json(&payload)?;
    } else {
        println!("machine doctor: OK");
        println!("status: machine_native_asm_total_closed");
        println!("conformance_level: Machine native ASM total closure");
        println!("primary_target: x86_64-unknown-linux-gnu");
        println!("asm_complete_total: true");
        println!("fn_fa_forbidden: true");
        println!("target_artifacts: x86_64, i386, armv7/thumb2, aarch64, riscv32, riscv64, wasm32");
        println!("cross_arch_parity: closed");
    }
    Ok(())
}

