fn run_asm_complete(args: &[String]) -> Result<(), Box<dyn Error>> {
    if args.is_empty() || is_help(args.first()) {
        println!(
            "Usage: machine asm-complete <doctor|absolute|native-doctor|toolchain|assemble|disasm-object|roundtrip-authority|parity> [--json]\n\
             ASM-complete reports the declared absolute nC Machine ASM contract and external authority evidence."
        );
        return Ok(());
    }
    match args[0].as_str() {
        "doctor" => {
            let payload = machine_asm_complete_doctor_json();
            if has_flag(args, "--json") {
                print_json(&payload)?;
            } else {
                println!("machine asm-complete doctor: audit surface OK");
                println!("current_conformance: Machine Level 6 preserved");
                println!("asm_complete_claim: closed");
                println!("absolute_scope_status: closed_declared_machine_profiles");
                println!("level_7_status: closed_roundtrip_phase7");
                println!("level_8_status: closed_cross_arch_parity_total");
                println!("level_9_status: closed_industrial_asm_audit");
            }
            Ok(())
        }
        "absolute" | "absolute-coverage" | "asm-absolute" => {
            let payload = machine_asm_absolute_complete_json();
            if has_flag(args, "--json") {
                print_json(&payload)?;
            } else {
                println!("machine asm-complete absolute: closed");
                println!("scope: declared nC Machine ASM profiles");
                println!("x86_64: prefixes, rare addressing, VEX, AVX2, EVEX, AVX-512");
                println!("aarch64: deep profile + catalog gates");
                println!("riscv64: deep profile + catalog gates");
            }
            Ok(())
        }
        "native-doctor" => {
            let payload = machine_native_assembler_phase1_json();
            print_json(&payload)?;
            Ok(())
        }
        "toolchain" | "verify-toolchain" => {
            let payload = machine_asm_authority_toolchain_json();
            print_json(&payload)?;
            Ok(())
        }
        "assemble" => run_asm_authority_assemble(&args[1..]),
        "disasm-object" => run_asm_authority_disasm_object(&args[1..]),
        "roundtrip-authority" => run_asm_authority_roundtrip(&args[1..]),
        "parity" => run_asm_authority_parity(&args[1..]),
        other => Err(format!(
            "[E_MACHINE_CLI_001] unknown machine asm-complete command '{}'",
            other
        )
        .into()),
    }
}

