fn run_asm_authority_assemble(args: &[String]) -> Result<(), Box<dyn Error>> {
    let path = first_non_flag(args).ok_or("machine asm-complete assemble expects a .nm file")?;
    let target = option_value(args, "--target").unwrap_or("x86_64-unknown-linux-gnu");
    let tool = option_value(args, "--tool").unwrap_or("clang");
    let out = option_value(args, "--out").unwrap_or("target/tmp/machine_authority/out.o");
    let audit = audit_machine_file(path)?;
    if audit.has_errors() {
        return Err(diagnostics_summary(&audit.diagnostics).into());
    }
    let payload = assemble_with_authority(&audit, target, tool, out)?;
    print_json(&payload)?;
    Ok(())
}

