fn run_asm_authority_roundtrip(args: &[String]) -> Result<(), Box<dyn Error>> {
    let path = first_non_flag(args)
        .ok_or("machine asm-complete roundtrip-authority expects a .nm file")?;
    let target = option_value(args, "--target").unwrap_or("x86_64-unknown-linux-gnu");
    let tool = option_value(args, "--tool").unwrap_or("llvm-mc");
    let audit = audit_machine_file(path)?;
    if audit.has_errors() {
        return Err(diagnostics_summary(&audit.diagnostics).into());
    }
    let root = Path::new("target/tmp/machine_authority_roundtrip");
    fs::create_dir_all(root)?;
    let stem = source_stem(path);
    let object_path = root.join(format!("{}_{}.o", stem, sanitize_tool_name(tool)));
    let object = assemble_with_authority(&audit, target, tool, &object_path.display().to_string())?;
    if object["status"] != "passed" {
        print_json(&json!({
            "status": "blocked",
            "source": path,
            "target": target,
            "tool": tool,
            "assemble": object
        }))?;
        return Ok(());
    }
    let disasm = disasm_object_with_authority(&object_path.display().to_string(), "llvm-objdump")?;
    let disasm_fallback = if disasm["status"] == "passed" {
        disasm
    } else {
        disasm_object_with_authority(&object_path.display().to_string(), "objdump")?
    };
    print_json(&json!({
        "status": if disasm_fallback["status"] == "passed" { "passed" } else { "blocked_disasm" },
        "source": path,
        "target": target,
        "tool": tool,
        "object": object,
        "disasm": disasm_fallback,
        "roundtrip_claim": "authority_assemble_and_disasm_retained",
        "official_source": ".nm"
    }))?;
    Ok(())
}

fn run_asm_authority_parity(args: &[String]) -> Result<(), Box<dyn Error>> {
    let path = first_non_flag(args).ok_or("machine asm-complete parity expects a .nm file")?;
    let target = option_value(args, "--target").unwrap_or("x86_64-unknown-linux-gnu");
    let audit = audit_machine_file(path)?;
    if audit.has_errors() {
        return Err(diagnostics_summary(&audit.diagnostics).into());
    }
    let required_tools = authority_tools_for_target(target);
    let root = Path::new("target/tmp/machine_authority_parity");
    fs::create_dir_all(root)?;
    let stem = source_stem(path);
    let mut rows = Vec::new();
    for tool in required_tools {
        let object_path = root.join(format!("{}_{}_{}.o", stem, target_family_key(target), tool));
        let assembled =
            assemble_with_authority(&audit, target, tool, &object_path.display().to_string())?;
        let disasm = if assembled["status"] == "passed" {
            disasm_object_with_authority(&object_path.display().to_string(), "llvm-objdump")
                .or_else(|_| {
                    disasm_object_with_authority(&object_path.display().to_string(), "objdump")
                })?
        } else {
            json!({
                "status": "not_run",
                "reason": "assembly did not pass"
            })
        };
        rows.push(json!({
            "tool": tool,
            "assemble": assembled,
            "disasm": disasm
        }));
    }
    let passed = rows
        .iter()
        .filter(|row| row["assemble"]["status"] == "passed")
        .count();
    let blocked = rows
        .iter()
        .filter(|row| row["assemble"]["status"] != "passed")
        .count();
    print_json(&json!({
        "status": if passed > 0 && blocked == 0 { "passed" } else if passed > 0 { "partial" } else { "blocked" },
        "source": path,
        "target": target,
        "official_source": ".nm",
        "parity_claim": "external_authorities_can_materialize_and_disassemble_contract",
        "tools_total": rows.len(),
        "tools_passed": passed,
        "tools_blocked": blocked,
        "tools": rows
    }))?;
    Ok(())
}

