fn phase12_pe_internal_open_uri_thunk(
    base_va: u64,
    dynamic_targets: &HashMap<String, u64>,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let shell_execute = *dynamic_targets.get("ShellExecuteA").ok_or(
        "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] internal openUri thunk requires ShellExecuteA",
    )?;
    let mut bytes = vec![
        0x48, 0x83, 0xec, 0x38, // sub rsp, 56
        0x49, 0x89, 0xc8, // mov r8, rcx ; lpFile = uri
        0x31, 0xc9, // xor ecx, ecx ; hwnd = NULL
        0x31, 0xd2, // xor edx, edx ; lpOperation = NULL/default
        0x45, 0x31, 0xc9, // xor r9d, r9d ; lpParameters = NULL
        0x48, 0xc7, 0x44, 0x24, 0x20, 0x00, 0x00, 0x00,
        0x00, // mov qword ptr [rsp + 32], 0 ; lpDirectory = NULL
        0x48, 0xc7, 0x44, 0x24, 0x28, 0x01, 0x00, 0x00,
        0x00, // mov qword ptr [rsp + 40], 1 ; SW_SHOWNORMAL
    ];
    phase12_pe_push_call_rel32(&mut bytes, base_va, shell_execute)?;
    bytes.extend_from_slice(&[
        0x48, 0x83, 0xf8, 0x20, // cmp rax, 32
        0x0f, 0x9f, 0xc0, // setg al
        0x0f, 0xb6, 0xc0, // movzx eax, al
        0x48, 0x83, 0xc4, 0x38, // add rsp, 56
        0xc3, // ret
    ]);
    Ok(bytes)
}

