fn phase12_pe_internal_media_key_thunk(
    base_va: u64,
    dynamic_targets: &HashMap<String, u64>,
    vk: u8,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let keybd_event = *dynamic_targets.get("keybd_event").ok_or(
        "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] internal media thunk requires keybd_event",
    )?;
    let mut bytes = vec![
        0x48, 0x83, 0xec, 0x28, // sub rsp, 40
        0xb9, vk, 0x00, 0x00, 0x00, // mov ecx, vk
        0x31, 0xd2, // xor edx, edx ; scan code
        0x45, 0x31, 0xc0, // xor r8d, r8d ; key down
        0x45, 0x31, 0xc9, // xor r9d, r9d
    ];
    phase12_pe_push_call_rel32(&mut bytes, base_va, keybd_event)?;
    bytes.extend_from_slice(&[
        0xb9, vk, 0x00, 0x00, 0x00, // mov ecx, vk
        0x31, 0xd2, // xor edx, edx ; scan code
        0x41, 0xb8, 0x02, 0x00, 0x00, 0x00, // mov r8d, KEYEVENTF_KEYUP
        0x45, 0x31, 0xc9, // xor r9d, r9d
    ]);
    phase12_pe_push_call_rel32(&mut bytes, base_va, keybd_event)?;
    bytes.extend_from_slice(&[
        0xb8, 0x01, 0x00, 0x00, 0x00, // mov eax, 1
        0x48, 0x83, 0xc4, 0x28, // add rsp, 40
        0xc3, // ret
    ]);
    Ok(bytes)
}

