fn phase12_pe_internal_window_extent_thunk(
    base_va: u64,
    dynamic_targets: &HashMap<String, u64>,
    width: bool,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let get_rect = phase12_pe_win32_target(dynamic_targets, "windowExtent", "GetClientRect")?;
    let mut bytes = vec![
        0x48, 0x83, 0xec, 0x38, // sub rsp, 56
        0x48, 0x8d, 0x54, 0x24, 0x20, // lea rdx, [rsp+32]
    ];
    phase12_pe_push_call_rel32(&mut bytes, base_va, get_rect)?;
    bytes.extend_from_slice(&[0x85, 0xc0, 0x74, 0x00]); // test eax,eax; jz zero
    let jz_zero = bytes.len() - 1;
    if width {
        bytes.extend_from_slice(&[
            0x8b, 0x44, 0x24, 0x28, // mov eax, [rsp+40] ; right
            0x2b, 0x44, 0x24, 0x20, // sub eax, [rsp+32] ; left
        ]);
    } else {
        bytes.extend_from_slice(&[
            0x8b, 0x44, 0x24, 0x2c, // mov eax, [rsp+44] ; bottom
            0x2b, 0x44, 0x24, 0x24, // sub eax, [rsp+36] ; top
        ]);
    }
    bytes.extend_from_slice(&[0x48, 0x63, 0xc0, 0xeb, 0x00]); // movsxd rax,eax; jmp done
    let jmp_done = bytes.len() - 1;
    let zero = bytes.len();
    bytes.extend_from_slice(&[0x31, 0xc0]);
    let done = bytes.len();
    phase12_pe_patch_rel8(&mut bytes, jz_zero, zero)?;
    phase12_pe_patch_rel8(&mut bytes, jmp_done, done)?;
    bytes.extend_from_slice(&[0x48, 0x83, 0xc4, 0x38, 0xc3]);
    Ok(bytes)
}

