fn phase12_pe_internal_current_monitor_refresh_hz_thunk(
    base_va: u64,
    dynamic_targets: &HashMap<String, u64>,
    owner: &str,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let monitor_from_window = phase12_pe_win32_target(dynamic_targets, owner, "MonitorFromWindow")?;
    let get_monitor_info = phase12_pe_win32_target(dynamic_targets, owner, "GetMonitorInfoW")?;
    let create_dc = phase12_pe_win32_target(dynamic_targets, owner, "CreateDCW")?;
    let delete_dc = phase12_pe_win32_target(dynamic_targets, owner, "DeleteDC")?;
    let get_device_caps = phase12_pe_win32_target(dynamic_targets, owner, "GetDeviceCaps")?;
    let mut bytes = vec![
        0x53, 0x56, // push rbx/rsi
        0x48, 0x81, 0xec, 0xb8, 0, 0, 0, // shadow + MONITORINFOEXW
        0x48, 0x89, 0xcb, // rbx=hwnd
        0xc7, 0x84, 0x24, 0xa0, 0, 0, 0, 60, 0, 0, 0, // 60 Hz fallback
        0x48, 0x89, 0xd9, 0xba, 2, 0, 0, 0, // MONITOR_DEFAULTTONEAREST
    ];
    phase12_pe_push_call_rel32(&mut bytes, base_va, monitor_from_window)?;
    bytes.extend_from_slice(&[0x48, 0x85, 0xc0, 0x0f, 0x84, 0, 0, 0, 0]);
    let jz_done_monitor = bytes.len() - 4;
    bytes.extend_from_slice(&[
        0xc7, 0x44, 0x24, 0x30, 104, 0, 0, 0, // MONITORINFOEXW.cbSize
        0x48, 0x89, 0xc1, 0x48, 0x8d, 0x54, 0x24, 0x30,
    ]);
    phase12_pe_push_call_rel32(&mut bytes, base_va, get_monitor_info)?;
    bytes.extend_from_slice(&[0x85, 0xc0, 0x0f, 0x84, 0, 0, 0, 0]);
    let jz_done_info = bytes.len() - 4;
    bytes.extend_from_slice(&[
        0x48, 0x8d, 0x4c, 0x24, 0x58, // MONITORINFOEXW.szDevice
        0x48, 0x89, 0xca, // same specific display device for driver and device
        0x45, 0x31, 0xc0, 0x45, 0x31, 0xc9,
    ]);
    phase12_pe_push_call_rel32(&mut bytes, base_va, create_dc)?;
    bytes.extend_from_slice(&[0x48, 0x89, 0xc6, 0x48, 0x85, 0xc0, 0x0f, 0x84, 0, 0, 0, 0]);
    let jz_done_dc = bytes.len() - 4;
    bytes.extend_from_slice(&[0x48, 0x89, 0xf1, 0xba, 116, 0, 0, 0]);
    phase12_pe_push_call_rel32(&mut bytes, base_va, get_device_caps)?;
    bytes.extend_from_slice(&[
        0x83, 0xf8, 1, 0x7e, 7, // invalid VREFRESH values are 0/1
        0x89, 0x84, 0x24, 0xa0, 0, 0, 0, 0x48, 0x89, 0xf1,
    ]);
    phase12_pe_push_call_rel32(&mut bytes, base_va, delete_dc)?;
    let done = bytes.len();
    for branch in [jz_done_monitor, jz_done_info, jz_done_dc] {
        phase12_pe_patch_rel32(&mut bytes, branch, done)?;
    }
    bytes.extend_from_slice(&[
        0x8b, 0x84, 0x24, 0xa0, 0, 0, 0, 0x48, 0x81, 0xc4, 0xb8, 0, 0, 0, 0x5e, 0x5b, 0xc3,
    ]);
    Ok(bytes)
}

fn phase12_pe_internal_window_state_thunk(
    base_va: u64,
    dynamic_targets: &HashMap<String, u64>,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let iconic = phase12_pe_win32_target(dynamic_targets, "windowState", "IsIconic")?;
    let zoomed = phase12_pe_win32_target(dynamic_targets, "windowState", "IsZoomed")?;
    let mut bytes = vec![
        0x53, 0x48, 0x83, 0xec, 0x20, // save hwnd + shadow
        0x48, 0x89, 0xcb,
    ];
    phase12_pe_push_call_rel32(&mut bytes, base_va, iconic)?;
    bytes.extend_from_slice(&[
        0x85, 0xc0, 0x74, 0, // jz check_zoomed
        0xb8, 1, 0, 0, 0, 0xeb, 0, // jmp done
    ]);
    let jz_zoomed = bytes.len() - 8;
    let jmp_done = bytes.len() - 1;
    let check_zoomed = bytes.len();
    phase12_pe_patch_rel8(&mut bytes, jz_zoomed, check_zoomed)?;
    bytes.extend_from_slice(&[0x48, 0x89, 0xd9]);
    phase12_pe_push_call_rel32(&mut bytes, base_va, zoomed)?;
    bytes.extend_from_slice(&[0x85, 0xc0, 0x0f, 0x95, 0xc0, 0x0f, 0xb6, 0xc0, 0x01, 0xc0]);
    let done = bytes.len();
    phase12_pe_patch_rel8(&mut bytes, jmp_done, done)?;
    bytes.extend_from_slice(&[0x48, 0x83, 0xc4, 0x20, 0x5b, 0xc3]);
    Ok(bytes)
}

fn phase12_pe_internal_window_set_state_thunk(
    base_va: u64,
    dynamic_targets: &HashMap<String, u64>,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let is_window = phase12_pe_win32_target(dynamic_targets, "windowSetState", "IsWindow")?;
    let show = phase12_pe_win32_target(dynamic_targets, "windowSetState", "ShowWindow")?;
    let mut bytes = vec![
        0x53, 0x56, // push rbx/rsi
        0x48, 0x83, 0xec, 0x28, // align + shadow
        0x48, 0x89, 0xcb, 0x89, 0xd6, // hwnd/state
        0x48, 0x89, 0xd9,
    ];
    phase12_pe_push_call_rel32(&mut bytes, base_va, is_window)?;
    bytes.extend_from_slice(&[0x85, 0xc0, 0x74, 0]); // false
    let jz_false = bytes.len() - 1;
    bytes.extend_from_slice(&[0x83, 0xfe, 2, 0x77, 0]); // state > 2 => false
    let ja_false = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0xba, 9, 0, 0, 0, // SW_RESTORE
        0x85, 0xf6, 0x74, 0, // state 0 => call
    ]);
    let je_call_zero = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0xba, 6, 0, 0, 0, // SW_MINIMIZE
        0x83, 0xfe, 1, 0x74, 0, // state 1 => call
    ]);
    let je_call_one = bytes.len() - 1;
    bytes.extend_from_slice(&[0xba, 3, 0, 0, 0]); // SW_MAXIMIZE
    let call = bytes.len();
    phase12_pe_patch_rel8(&mut bytes, je_call_zero, call)?;
    phase12_pe_patch_rel8(&mut bytes, je_call_one, call)?;
    bytes.extend_from_slice(&[0x48, 0x89, 0xd9]);
    phase12_pe_push_call_rel32(&mut bytes, base_va, show)?;
    bytes.extend_from_slice(&[0xb8, 1, 0, 0, 0, 0xeb, 0]);
    let jmp_done = bytes.len() - 1;
    let false_label = bytes.len();
    phase12_pe_patch_rel8(&mut bytes, jz_false, false_label)?;
    phase12_pe_patch_rel8(&mut bytes, ja_false, false_label)?;
    bytes.extend_from_slice(&[0x31, 0xc0]);
    let done = bytes.len();
    phase12_pe_patch_rel8(&mut bytes, jmp_done, done)?;
    bytes.extend_from_slice(&[0x48, 0x83, 0xc4, 0x28, 0x5e, 0x5b, 0xc3]);
    Ok(bytes)
}

