fn phase12_pe_internal_window_read_message_thunk(
    base_va: u64,
    dynamic_targets: &HashMap<String, u64>,
    owner: &str,
    peek_symbol: &str,
    message: u32,
    translate_symbol: Option<&str>,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let peek = phase12_pe_win32_target(dynamic_targets, owner, peek_symbol)?;
    let translate = translate_symbol
        .map(|symbol| phase12_pe_win32_target(dynamic_targets, owner, symbol))
        .transpose()?;
    let mut bytes = vec![
        0x48, 0x83, 0xec, 0x68, // sub rsp, 104
        0x48, 0x89, 0xca, // mov rdx, rcx ; HWND
        0x48, 0x8d, 0x4c, 0x24, 0x28, // lea rcx, [rsp+40] ; MSG
        0x41, 0xb8, // mov r8d, message
    ];
    bytes.extend_from_slice(&message.to_le_bytes());
    bytes.extend_from_slice(&[0x41, 0xb9]); // mov r9d, message
    bytes.extend_from_slice(&message.to_le_bytes());
    bytes.extend_from_slice(&[
        0xc7, 0x44, 0x24, 0x20, 0x01, 0x00, 0x00, 0x00, // PM_REMOVE
    ]);
    phase12_pe_push_call_rel32(&mut bytes, base_va, peek)?;
    bytes.extend_from_slice(&[0x85, 0xc0, 0x74, 0x00]); // test eax,eax; jz none
    let jz_none = bytes.len() - 1;
    if let Some(translate) = translate {
        bytes.extend_from_slice(&[0x48, 0x8d, 0x4c, 0x24, 0x28]); // &MSG
        phase12_pe_push_call_rel32(&mut bytes, base_va, translate)?;
    }
    bytes.extend_from_slice(&[
        0x48, 0x8b, 0x44, 0x24, 0x38, // mov rax, [rsp+56] ; MSG.wParam
        0xeb, 0x00, // jmp done
    ]);
    let jmp_done = bytes.len() - 1;
    let none = bytes.len();
    bytes.extend_from_slice(&[0x31, 0xc0]); // xor eax,eax
    let done = bytes.len();
    phase12_pe_patch_rel8(&mut bytes, jz_none, none)?;
    phase12_pe_patch_rel8(&mut bytes, jmp_done, done)?;
    bytes.extend_from_slice(&[0x48, 0x83, 0xc4, 0x68, 0xc3]);
    Ok(bytes)
}

fn phase12_pe_internal_str_eq_thunk(
    base_va: u64,
    dynamic_targets: &HashMap<String, u64>,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let strcmp = phase12_pe_win32_target(dynamic_targets, "strEq", "strcmp")?;
    let mut bytes = vec![
        0x48, 0x39, 0xd1, // cmp rcx, rdx
        0x74, 0x00, // je equal
    ];
    let je_equal = bytes.len() - 1;
    bytes.extend_from_slice(&[0x48, 0x85, 0xc9, 0x74, 0x00]); // test rcx,rcx; jz false
    let jz_false_left = bytes.len() - 1;
    bytes.extend_from_slice(&[0x48, 0x85, 0xd2, 0x74, 0x00]); // test rdx,rdx; jz false
    let jz_false_right = bytes.len() - 1;
    bytes.extend_from_slice(&[0x48, 0x83, 0xec, 0x28]);
    phase12_pe_push_call_rel32(&mut bytes, base_va, strcmp)?;
    bytes.extend_from_slice(&[
        0x48, 0x83, 0xc4, 0x28, // add rsp, 40
        0x85, 0xc0, // test eax,eax
        0x0f, 0x94, 0xc0, // sete al
        0x0f, 0xb6, 0xc0, // movzx eax,al
        0xc3,
    ]);
    let equal = bytes.len();
    bytes.extend_from_slice(&[0xb8, 0x01, 0x00, 0x00, 0x00, 0xc3]);
    let false_value = bytes.len();
    bytes.extend_from_slice(&[0x31, 0xc0, 0xc3]);
    phase12_pe_patch_rel8(&mut bytes, je_equal, equal)?;
    phase12_pe_patch_rel8(&mut bytes, jz_false_left, false_value)?;
    phase12_pe_patch_rel8(&mut bytes, jz_false_right, false_value)?;
    Ok(bytes)
}

fn phase12_pe_internal_str_substring_thunk(
    base_va: u64,
    dynamic_targets: &HashMap<String, u64>,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let malloc = phase12_pe_win32_target(dynamic_targets, "strSubstring", "malloc")?;
    let mut bytes = vec![
        0x53, // push rbx
        0x56, // push rsi
        0x57, // push rdi
        0x48, 0x83, 0xec, 0x20, // sub rsp, 32
        0x48, 0x89, 0xcb, // mov rbx, rcx
        0x48, 0x89, 0xd6, // mov rsi, rdx
        0x4c, 0x89, 0xc7, // mov rdi, r8
        0x48, 0x85, 0xdb, // test rbx,rbx
        0x74, 0x00, // jz fail
    ];
    let jz_null = bytes.len() - 1;
    bytes.extend_from_slice(&[0x48, 0x85, 0xf6, 0x79, 0x00]); // test rsi,rsi; jns start_ok
    let jns_start = bytes.len() - 1;
    bytes.extend_from_slice(&[0x48, 0x31, 0xf6]); // xor rsi,rsi
    let start_ok = bytes.len();
    bytes.extend_from_slice(&[0x48, 0x85, 0xff, 0x79, 0x00]); // test rdi,rdi; jns len_ok
    let jns_len = bytes.len() - 1;
    bytes.extend_from_slice(&[0x48, 0x31, 0xff]); // xor rdi,rdi
    let len_ok = bytes.len();
    bytes.extend_from_slice(&[0x48, 0x8d, 0x4f, 0x01]); // lea rcx,[rdi+1]
    phase12_pe_push_call_rel32(&mut bytes, base_va, malloc)?;
    bytes.extend_from_slice(&[0x48, 0x85, 0xc0, 0x74, 0x00]); // test rax,rax; jz fail
    let jz_alloc = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x49, 0x89, 0xc1, // mov r9,rax
        0x49, 0x89, 0xda, // mov r10,rbx
        0x49, 0x01, 0xf2, // add r10,rsi
        0x31, 0xc9, // xor ecx,ecx
    ]);
    let copy_loop = bytes.len();
    bytes.extend_from_slice(&[0x48, 0x39, 0xf9, 0x73, 0x00]); // cmp rcx,rdi; jae done
    let jae_done = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x41, 0x8a, 0x14, 0x0a, // mov dl,[r10+rcx]
        0x84, 0xd2, // test dl,dl
        0x74, 0x00, // jz done
    ]);
    let jz_done = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x41, 0x88, 0x14, 0x09, // mov [r9+rcx],dl
        0x48, 0xff, 0xc1, // inc rcx
        0xeb, 0x00, // jmp copy_loop
    ]);
    let jmp_loop = bytes.len() - 1;
    let copy_done = bytes.len();
    bytes.extend_from_slice(&[
        0x41, 0xc6, 0x04, 0x09, 0x00, // mov byte [r9+rcx],0
        0x4c, 0x89, 0xc8, // mov rax,r9
        0xeb, 0x00, // jmp epilogue
    ]);
    let jmp_epilogue = bytes.len() - 1;
    let fail = bytes.len();
    bytes.extend_from_slice(&[0x31, 0xc0]);
    let epilogue = bytes.len();
    bytes.extend_from_slice(&[
        0x48, 0x83, 0xc4, 0x20, // add rsp,32
        0x5f, 0x5e, 0x5b, 0xc3,
    ]);
    for (branch, target) in [
        (jz_null, fail),
        (jns_start, start_ok),
        (jns_len, len_ok),
        (jz_alloc, fail),
        (jae_done, copy_done),
        (jz_done, copy_done),
        (jmp_loop, copy_loop),
        (jmp_epilogue, epilogue),
    ] {
        phase12_pe_patch_rel8(&mut bytes, branch, target)?;
    }
    Ok(bytes)
}

