    phase12_pe_patch_rel8(&mut bytes, jz_fail_client, fail)?;
    phase12_pe_patch_rel8(&mut bytes, jmp_done, done)?;
    bytes.extend_from_slice(&[0x48, 0x83, 0xc4, 0x30, 0x5b, 0xc3]);
