    let jle_fail_size = bytes.len() - 4;
    bytes.extend_from_slice(&[0x89, 0xc7, 0x48, 0x98, 0x48, 0x8d, 0x0c, 0]);
    phase12_pe_push_call_rel32(&mut bytes, base_va, malloc)?;
    bytes.extend_from_slice(&[
        0x48, 0x89, 0x44, 0x24, 0x30, 0x48, 0x85, 0xc0, 0x0f, 0x84, 0, 0, 0, 0,
    ]);
    let jz_fail_alloc = bytes.len() - 4;
    bytes.extend_from_slice(&[
        0xb9, 0xe9, 0xfd, 0, 0, 0xba, 8, 0, 0, 0, 0x49, 0x89, 0xd8, 0x49, 0xc7, 0xc1, 0xff, 0xff,
        0xff, 0xff, 0x48, 0x8b, 0x44, 0x24, 0x30, 0x48, 0x89, 0x44, 0x24, 0x20, 0x48, 0x89, 0x7c,
        0x24, 0x28,
    ]);
    phase12_pe_push_call_rel32(&mut bytes, base_va, convert)?;
    bytes.extend_from_slice(&[0x85, 0xc0, 0x0f, 0x8e, 0, 0, 0, 0]);
    let jle_free_fail = bytes.len() - 4;
    bytes.extend_from_slice(&[
        0x48, 0x85, 0xf6, 0x74, 5, 0x8d, 0x47, 0xff, 0x89, 0x06, 0x48, 0x8b, 0x44, 0x24, 0x30,
        0xe9, 0, 0, 0, 0,
    ]);
    let jmp_epilogue_success = bytes.len() - 4;
    let free_fail = bytes.len();
    phase12_pe_patch_rel32(&mut bytes, jle_free_fail, free_fail)?;
    bytes.extend_from_slice(&[0x48, 0x8b, 0x4c, 0x24, 0x30]);
