fn phase12_pe_push_call_rel32(
    bytes: &mut Vec<u8>,
    base_va: u64,
    target_va: u64,
) -> Result<(), Box<dyn Error>> {
    let call_va = base_va + bytes.len() as u64;
    let next = call_va + 5;
    let disp = target_va as i128 - next as i128;
    if disp < i32::MIN as i128 || disp > i32::MAX as i128 {
        return Err(
            "[E_MACHINE_LINK_PCREL_RANGE_001] internal PE thunk call does not fit i32".into(),
        );
    }
    bytes.push(0xe8);
    bytes.extend_from_slice(&(disp as i32).to_le_bytes());
    Ok(())
}

fn phase12_pe_push_reset_viewport_origin(
    bytes: &mut Vec<u8>,
    base_va: u64,
    set_viewport_origin_va: u64,
) -> Result<(), Box<dyn Error>> {
    // RCX already contains the DC. SetViewportOrgEx(dc, 0, 0, NULL) is
    // required after switching to MM_TEXT: SetMapMode does not reset the
    // viewport origin left by MM_ANISOTROPIC fit/fill transforms.
    bytes.extend_from_slice(&[
        0x31, 0xd2, // xor edx,edx (x)
        0x45, 0x31, 0xc0, // xor r8d,r8d (y)
        0x45, 0x31, 0xc9, // xor r9d,r9d (previous origin pointer)
    ]);
    phase12_pe_push_call_rel32(bytes, base_va, set_viewport_origin_va)
}

fn phase12_pe_push_lea_rip32(
    bytes: &mut Vec<u8>,
    base_va: u64,
    modrm: u8,
    target_va: u64,
) -> Result<(), Box<dyn Error>> {
    let inst_va = base_va + bytes.len() as u64;
    let next = inst_va + 7;
    let disp = target_va as i128 - next as i128;
    if disp < i32::MIN as i128 || disp > i32::MAX as i128 {
        return Err(
            "[E_MACHINE_LINK_PCREL_RANGE_001] internal PE thunk RIP-relative target does not fit i32"
                .into(),
        );
    }
    bytes.extend([0x48, 0x8d, modrm]);
    bytes.extend_from_slice(&(disp as i32).to_le_bytes());
    Ok(())
}

fn phase12_pe_patch_rel8(
    bytes: &mut [u8],
    disp_offset: usize,
    target_offset: usize,
) -> Result<(), Box<dyn Error>> {
    let next = disp_offset + 1;
    let disp = target_offset as isize - next as isize;
    if disp < i8::MIN as isize || disp > i8::MAX as isize {
        return Err(
            "[E_MACHINE_LINK_PCREL_RANGE_001] internal PE thunk branch does not fit i8".into(),
        );
    }
    bytes[disp_offset] = disp as i8 as u8;
    Ok(())
}

fn phase12_pe_patch_rel32(
    bytes: &mut [u8],
    disp_offset: usize,
    target_offset: usize,
) -> Result<(), Box<dyn Error>> {
    let next = disp_offset + 4;
    let disp = target_offset as i128 - next as i128;
    if disp < i32::MIN as i128 || disp > i32::MAX as i128 {
        return Err(
            "[E_MACHINE_LINK_PCREL_RANGE_001] internal PE thunk branch does not fit i32".into(),
        );
    }
    bytes[disp_offset..disp_offset + 4].copy_from_slice(&(disp as i32).to_le_bytes());
    Ok(())
}

fn phase12_pe_internal_write_thunk(
    base_va: u64,
    dynamic_targets: &HashMap<String, u64>,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let get_std_handle = *dynamic_targets.get("GetStdHandle").ok_or(
        "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] internal write thunk requires GetStdHandle",
    )?;
    let write_file = *dynamic_targets
        .get("WriteFile")
        .ok_or("[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] internal write thunk requires WriteFile")?;

    // write(fd, bytes, count): preserve the byte pointer and exact length,
    // map fd 2 to STDERR and every other descriptor to STDOUT, then enter
    // Win32 directly. The thunk is independent from the UCRT/MSVCRT ABI.
    let mut bytes = vec![
        0x48, 0x83, 0xec, 0x48, // sub rsp, 72
        0x48, 0x89, 0x54, 0x24, 0x28, // mov [rsp + 40], rdx
        0x4c, 0x89, 0x44, 0x24, 0x30, // mov [rsp + 48], r8
        0x83, 0xf9, 0x02, // cmp ecx, 2
        0xb9, 0xf5, 0xff, 0xff, 0xff, // mov ecx, -11 (STD_OUTPUT_HANDLE)
        0x75, 0x05, // jne handle_ready
        0xb9, 0xf4, 0xff, 0xff, 0xff, // mov ecx, -12 (STD_ERROR_HANDLE)
    ];
    phase12_pe_push_call_rel32(&mut bytes, base_va, get_std_handle)?;
    bytes.extend_from_slice(&[
        0x48, 0x89, 0xc1, // mov rcx, rax
        0x48, 0x8b, 0x54, 0x24, 0x28, // mov rdx, [rsp + 40]
        0x44, 0x8b, 0x44, 0x24, 0x30, // mov r8d, [rsp + 48]
        0x4c, 0x8d, 0x4c, 0x24, 0x38, // lea r9, [rsp + 56]
        0x48, 0xc7, 0x44, 0x24, 0x20, 0x00, 0x00, 0x00, 0x00, // overlapped = NULL
    ]);
    phase12_pe_push_call_rel32(&mut bytes, base_va, write_file)?;
    bytes.extend_from_slice(&[
        0x85, 0xc0, // test eax, eax
        0x75, 0x09, // jne success
        0x48, 0xc7, 0xc0, 0xff, 0xff, 0xff, 0xff, // mov rax, -1
        0xeb, 0x04, // jmp done
        0x8b, 0x44, 0x24, 0x38, // success: mov eax, [rsp + 56]
        0x48, 0x83, 0xc4, 0x48, // done: add rsp, 72
        0xc3, // ret
    ]);
    Ok(bytes)
}

fn phase12_pe_internal_memcpy_thunk() -> Vec<u8> {
    vec![
        0x48, 0x89, 0xc8, // mov rax, rcx
        0x4d, 0x85, 0xc0, // test r8, r8
        0x74, 0x11, // je done
        0x44, 0x8a, 0x0a, // loop: mov r9b, [rdx]
        0x44, 0x88, 0x09, // mov [rcx], r9b
        0x48, 0xff, 0xc2, // inc rdx
        0x48, 0xff, 0xc1, // inc rcx
        0x49, 0xff, 0xc8, // dec r8
        0x75, 0xef, // jne loop
        0xc3, // done: ret
    ]
}

fn phase12_pe_internal_strlen_thunk() -> Vec<u8> {
    vec![
        0x31, 0xc0, // xor eax, eax
        0x80, 0x3c, 0x01, 0x00, // loop: cmp byte ptr [rcx + rax], 0
        0x74, 0x05, // je done
        0x48, 0xff, 0xc0, // inc rax
        0xeb, 0xf5, // jmp loop
        0xc3, // done: ret
    ]
}

fn phase12_pe_internal_memset_thunk() -> Vec<u8> {
    vec![
        0x48, 0x89, 0xc8, // mov rax, rcx
        0x4d, 0x85, 0xc0, // test r8, r8
        0x74, 0x0a, // je done
        0x88, 0x11, // loop: mov [rcx], dl
        0x48, 0xff, 0xc1, // inc rcx
        0x49, 0xff, 0xc8, // dec r8
        0x75, 0xf6, // jne loop
        0xc3, // done: ret
    ]
}

fn phase12_pe_internal_memmove_thunk() -> Vec<u8> {
    let mut bytes = vec![
        0x48, 0x89, 0xc8, // mov rax, rcx
        0x4d, 0x85, 0xc0, // test r8, r8
        0x74, 0x00, // je done
    ];
    let je_done = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x48, 0x39, 0xd1, // cmp rcx, rdx
        0x72, 0x00, // jb forward
    ]);
    let jb_forward = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x49, 0x89, 0xd1, // mov r9, rdx
        0x4d, 0x01, 0xc1, // add r9, r8
        0x4c, 0x39, 0xc9, // cmp rcx, r9
        0x73, 0x00, // jae forward
    ]);
    let jae_forward = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x4c, 0x01, 0xc1, // add rcx, r8
        0x4c, 0x01, 0xc2, // add rdx, r8
    ]);
    let backward = bytes.len();
    bytes.extend_from_slice(&[
        0x48, 0xff, 0xc9, // dec rcx
        0x48, 0xff, 0xca, // dec rdx
        0x44, 0x8a, 0x0a, // mov r9b, [rdx]
        0x44, 0x88, 0x09, // mov [rcx], r9b
        0x49, 0xff, 0xc8, // dec r8
        0x75, 0x00, // jne backward
    ]);
    let jne_backward = bytes.len() - 1;
    bytes.extend_from_slice(&[0xeb, 0x00]); // jmp done
    let jmp_done = bytes.len() - 1;

    let forward = bytes.len();
    let forward_loop = bytes.len();
    bytes.extend_from_slice(&[
        0x44, 0x8a, 0x0a, // mov r9b, [rdx]
        0x44, 0x88, 0x09, // mov [rcx], r9b
        0x48, 0xff, 0xc2, // inc rdx
        0x48, 0xff, 0xc1, // inc rcx
        0x49, 0xff, 0xc8, // dec r8
        0x75, 0x00, // jne forward_loop
    ]);
    let jne_forward = bytes.len() - 1;
    let done = bytes.len();
    bytes.push(0xc3);

    phase12_pe_patch_rel8(&mut bytes, je_done, done).expect("memmove je must fit");
    phase12_pe_patch_rel8(&mut bytes, jb_forward, forward).expect("memmove jb must fit");
    phase12_pe_patch_rel8(&mut bytes, jae_forward, forward).expect("memmove jae must fit");
    phase12_pe_patch_rel8(&mut bytes, jne_backward, backward)
        .expect("memmove backward loop must fit");
    phase12_pe_patch_rel8(&mut bytes, jmp_done, done).expect("memmove done must fit");
    phase12_pe_patch_rel8(&mut bytes, jne_forward, forward_loop)
        .expect("memmove forward loop must fit");
    bytes
}

fn phase12_pe_internal_printf_thunk(
    base_va: u64,
    dynamic_targets: &HashMap<String, u64>,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let get_std_handle = *dynamic_targets.get("GetStdHandle").ok_or(
        "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] internal printf thunk requires GetStdHandle",
    )?;
    let write_file = *dynamic_targets
        .get("WriteFile")
        .ok_or("[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] internal printf thunk requires WriteFile")?;

    let mut bytes = vec![
        0x53, // push rbx
        0x56, // push rsi
        0x57, // push rdi
        0x48, 0x83, 0xec, 0x30, // sub rsp, 48
        0x48, 0x89, 0xce, // mov rsi, rcx
        0x48, 0x89, 0xcb, // mov rbx, rcx
        0x80, 0x3e, 0x25, // cmp byte ptr [rsi], '%'
        0x75, 0x00, // jne choose_done
    ];
    let jne_fmt = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x80, 0x7e, 0x01, 0x73, // cmp byte ptr [rsi + 1], 's'
        0x75, 0x00, // jne choose_done
    ]);
    let jne_s = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x48, 0x85, 0xd2, // test rdx, rdx
        0x74, 0x00, // je choose_done
    ]);
    let je_null = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x48, 0x89, 0xd3, // mov rbx, rdx
    ]);
    let choose_done = bytes.len();
    phase12_pe_patch_rel8(&mut bytes, jne_fmt, choose_done)?;
    phase12_pe_patch_rel8(&mut bytes, jne_s, choose_done)?;
    phase12_pe_patch_rel8(&mut bytes, je_null, choose_done)?;

    bytes.extend_from_slice(&[
        0x48, 0xc7, 0xc1, 0xf5, 0xff, 0xff, 0xff, // mov rcx, -11
    ]);
    phase12_pe_push_call_rel32(&mut bytes, base_va, get_std_handle)?;
    bytes.extend_from_slice(&[
        0x48, 0x89, 0xc7, // mov rdi, rax
        0x45, 0x31, 0xc0, // xor r8d, r8d
    ]);
    let len_loop = bytes.len();
    bytes.extend_from_slice(&[
        0x42, 0x80, 0x3c, 0x03, 0x00, // cmp byte ptr [rbx + r8], 0
        0x74, 0x00, // je len_done
    ]);
    let je_len_done = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x49, 0xff, 0xc0, // inc r8
        0xeb, 0x00, // jmp len_loop
    ]);
    let jmp_len_loop = bytes.len() - 1;
    let len_done = bytes.len();
    phase12_pe_patch_rel8(&mut bytes, je_len_done, len_done)?;
    phase12_pe_patch_rel8(&mut bytes, jmp_len_loop, len_loop)?;
    bytes.extend_from_slice(&[
        0x48, 0x89, 0xf9, // mov rcx, rdi
        0x48, 0x89, 0xda, // mov rdx, rbx
        0x4c, 0x8d, 0x4c, 0x24, 0x28, // lea r9, [rsp + 40]
        0x48, 0xc7, 0x44, 0x24, 0x20, 0x00, 0x00, 0x00, 0x00, // mov qword ptr [rsp + 32], 0
    ]);
    phase12_pe_push_call_rel32(&mut bytes, base_va, write_file)?;
    bytes.extend_from_slice(&[
        0x48, 0x83, 0xc4, 0x30, // add rsp, 48
        0x5f, // pop rdi
        0x5e, // pop rsi
        0x5b, // pop rbx
        0xc3, // ret
    ]);
    Ok(bytes)
}

fn phase12_pe_base_relocations(
    image: &Phase12LinkedImage,
    image_base: u64,
    text_va: u64,
    rodata_va: Option<u64>,
    data_va: Option<u64>,
    bss_va: Option<u64>,
    section_vas: &BTreeMap<String, u64>,
) -> Result<Vec<(u32, u16)>, Box<dyn Error>> {
    let mut relocations = Vec::new();
    for rel in &image.relocations {
        let relocation_type = match rel.kind.as_str() {
            "abs64" => PE_BASE_RELOCATION_DIR64,
            "coff-addr32" => PE_BASE_RELOCATION_HIGHLOW,
            _ => continue,
        };
        let place = if let Some(base) = section_vas.get(&rel.section) {
            base + rel.offset as u64
        } else {
            phase12_relocation_place_va(rel, text_va, rodata_va, data_va, bss_va)?
        };
        if place < image_base {
            return Err(
                "[E_MACHINE_LINK_RELOCATION_TARGET_001] PE base relocation is below image base"
                    .into(),
            );
        }
        let rva = place - image_base;
        if rva > u32::MAX as u64 {
            return Err(
                "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] PE base relocation RVA exceeds u32"
                    .into(),
            );
        }
        relocations.push((rva as u32, relocation_type));
    }
    relocations.sort_unstable();
    relocations.dedup();
    Ok(relocations)
}

fn phase12_pe_base_relocation_bytes(relocations: &[(u32, u16)], default_page_rva: u32) -> Vec<u8> {
    let mut pages = BTreeMap::<u32, Vec<u16>>::new();
    for (rva, relocation_type) in relocations {
        let page = rva & !0xfff;
        let offset = (rva & 0xfff) as u16;
        pages
            .entry(page)
            .or_default()
            .push(*relocation_type | offset);
    }
    if pages.is_empty() {
        pages.entry(default_page_rva & !0xfff).or_default().push(0);
    }

    let mut bytes = Vec::new();
    for (page, mut entries) in pages {
        entries.sort_unstable();
        entries.dedup();
        if entries.len() % 2 != 0 {
            entries.push(0);
        }
        let block_size = 8 + entries.len() * 2;
        bytes.extend_from_slice(&page.to_le_bytes());
        bytes.extend_from_slice(&(block_size as u32).to_le_bytes());
        for entry in entries {
            bytes.extend_from_slice(&entry.to_le_bytes());
        }
    }
    phase12_vec_align(&mut bytes, 4);
    bytes
}

fn phase12_vec_align(bytes: &mut Vec<u8>, align: usize) {
    let target = align_to(bytes.len(), align.max(1));
    bytes.resize(target, 0);
}

fn phase12_elf64_image_base(arch: &str, target: &str) -> u64 {
    match (arch, target) {
        ("aarch64", "aarch64-unknown-none") => 0x4000_0000,
        ("riscv64", "riscv64-unknown-elf") => 0x8020_0000,
        _ => 0x0040_0000,
    }
}

fn phase12_elf32_image_base(arch: &str, target: &str) -> u64 {
    match (arch, target) {
        ("riscv32", "riscv32imac-unknown-elf") => 0x8040_0000,
        (_, target) if target.contains("unknown-none") || target.contains("unknown-elf") => {
            0x0001_0000
        }
        _ => 0x0804_8000,
    }
}

#[derive(Clone, Copy, Debug)]
struct Phase12FreestandingBootDataLayout {
    boot_info_offset: usize,
    framebuffer_offset: usize,
    platform_offset: usize,
    fdt_ptr_offset: usize,
    hart_ptr_offset: Option<usize>,
    topology_offset: usize,
    memory_map_offset: usize,
    boot_stack_offset: usize,
    boot_stack_size: usize,
}

const PHASE12_FREESTANDING_MEMORY_REGION_CAPACITY: usize = 256;
const PHASE12_FREESTANDING_CPU_CAPACITY: usize = 256;
const PHASE12_FREESTANDING_BOOT_STACK_SIZE: usize = 64 * 1024;

fn phase12_is_qemu_virt_freestanding(arch: &str, target: &str) -> bool {
    matches!(
        (arch, target),
        ("aarch64", "aarch64-unknown-none")
            | ("riscv64", "riscv64-unknown-elf")
            | ("riscv32", "riscv32imac-unknown-elf")
    )
}

fn phase12_reserve_freestanding_boot_data(
    data: &mut Vec<u8>,
    arch: &str,
    target: &str,
) -> Option<Phase12FreestandingBootDataLayout> {
    if !phase12_is_qemu_virt_freestanding(arch, target) {
        return None;
    }
    let boot_info_offset = align_to(data.len(), 16);
    data.resize(boot_info_offset + 88, 0);
    let framebuffer_offset = align_to(data.len(), 8);
    data.resize(framebuffer_offset + 32, 0);
    let platform_offset = align_to(data.len(), 8);
    let platform_entries = if arch.starts_with("riscv") { 3 } else { 2 };
    data.resize(platform_offset + 16 + platform_entries * 32, 0);
    let fdt_ptr_offset = platform_offset + 16 + 8;
    let hart_ptr_offset = arch
        .starts_with("riscv")
        .then_some(platform_offset + 16 + 32 + 8);
    let topology_offset = align_to(data.len(), 8);
    data.resize(
        topology_offset + 32 + PHASE12_FREESTANDING_CPU_CAPACITY * 48,
        0,
    );
    let memory_map_offset = align_to(data.len(), 8);
    data.resize(
        memory_map_offset + PHASE12_FREESTANDING_MEMORY_REGION_CAPACITY * 32,
        0,
    );
    let boot_stack_offset = align_to(data.len(), 16);
    data.resize(boot_stack_offset + PHASE12_FREESTANDING_BOOT_STACK_SIZE, 0);
    Some(Phase12FreestandingBootDataLayout {
        boot_info_offset,
        framebuffer_offset,
        platform_offset,
        fdt_ptr_offset,
        hart_ptr_offset,
        topology_offset,
        memory_map_offset,
        boot_stack_offset,
        boot_stack_size: PHASE12_FREESTANDING_BOOT_STACK_SIZE,
    })
}

fn phase12_materialize_freestanding_boot_data(
    data: &mut [u8],
    layout: Phase12FreestandingBootDataLayout,
    arch: &str,
    target: &str,
    data_va: u64,
    image_base: u64,
) -> Result<(), Box<dyn Error>> {
    let boot_info_va = data_va + layout.boot_info_offset as u64;
    let platform_va = data_va + layout.platform_offset as u64;
    let memory_map_va = data_va + layout.memory_map_offset as u64;
    let topology_va = data_va + layout.topology_offset as u64;
    let framebuffer_va = data_va + layout.framebuffer_offset as u64;
    if !matches!(arch, "aarch64" | "riscv64" | "riscv32") {
        return Err(format!(
            "[E_MACHINE_LINK_TARGET_001] no physical firmware boot data layout for {arch} ({target})"
        )
        .into());
    }

    data[layout.boot_info_offset..layout.boot_info_offset + 8].copy_from_slice(b"NCCBOO1\0");
    write_u64(data, layout.boot_info_offset + 8, 1);
    write_u64(data, layout.boot_info_offset + 16, 0x4);
    write_u64(data, layout.boot_info_offset + 24, memory_map_va);
    write_u64(data, layout.boot_info_offset + 32, 0);
    write_u64(data, layout.boot_info_offset + 40, framebuffer_va);
    write_u64(data, layout.boot_info_offset + 48, 0);
    write_u64(data, layout.boot_info_offset + 56, platform_va);
    write_u64(data, layout.boot_info_offset + 64, 0);
    write_u64(data, layout.boot_info_offset + 72, image_base);
    write_u64(data, layout.boot_info_offset + 80, 0);

    data[layout.platform_offset..layout.platform_offset + 8].copy_from_slice(b"NCCPLT1\0");
    write_u32(data, layout.platform_offset + 8, 1);
    write_u32(
        data,
        layout.platform_offset + 12,
        if arch.starts_with("riscv") { 3 } else { 2 },
    );
    let fdt_entry = layout.platform_offset + 16;
    write_u32(data, fdt_entry, 6);
    write_u32(data, fdt_entry + 4, 0x69);
    write_u64(data, fdt_entry + 8, 0);
    write_u64(data, fdt_entry + 16, 0);
    write_u64(data, fdt_entry + 24, 0);
    if arch.starts_with("riscv") {
        let hart_entry = fdt_entry + 32;
        write_u32(data, hart_entry, 7);
        write_u32(data, hart_entry + 4, 0x29);
        write_u64(data, hart_entry + 8, 0);
        write_u64(data, hart_entry + 16, 1);
        write_u64(data, hart_entry + 24, 0);
    }
    let topology_entry = fdt_entry + if arch.starts_with("riscv") { 64 } else { 32 };
    write_u32(data, topology_entry, 10);
    write_u32(data, topology_entry + 4, 0x7);
    write_u64(data, topology_entry + 8, topology_va);
    write_u64(
        data,
        topology_entry + 16,
        (32 + PHASE12_FREESTANDING_CPU_CAPACITY * 48) as u64,
    );
    write_u64(data, topology_entry + 24, 1);

    data[layout.topology_offset..layout.topology_offset + 8].copy_from_slice(b"NCCCPU1\0");
    write_u32(data, layout.topology_offset + 8, 1);
    write_u32(data, layout.topology_offset + 12, 0);
    write_u64(data, layout.topology_offset + 16, 0);
    write_u64(data, layout.topology_offset + 24, 0);

    let stack_top = data_va
        .checked_add(layout.boot_stack_offset as u64)
        .and_then(|base| base.checked_add(layout.boot_stack_size as u64))
        .ok_or("[E_MACHINE_LINK_LAYOUT_OVERFLOW_001] physical boot stack overflow")?;
    if stack_top & 15 != 0 || boot_info_va & 7 != 0 || framebuffer_va & 7 != 0 {
        return Err("[E_MACHINE_LINK_LAYOUT_001] physical firmware data lost ABI alignment".into());
    }
    Ok(())
}

fn phase12_elf64_os_executable_bytes(
    image: &Phase12LinkedImage,
    target: &str,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let arch = image.arch.as_str();
    if !matches!(arch, "x86_64" | "aarch64" | "riscv64") {
        return Err(format!(
            "[E_MACHINE_LINK_TARGET_001] ELF64 executable finalizer does not support arch {arch}"
        )
        .into());
    }
    let runtime_thunks = phase12_elf_runtime_thunks(&image.dynamic_imports);
    let imports = phase12_elf_loader_import_symbols(&image.dynamic_imports);
    if !imports.is_empty() && !phase12_elf64_dynamic_imports_supported(arch, target) {
        return Err(format!(
            "[E_MACHINE_LINK_DYNAMIC_RELOCATION_FORBIDDEN_001] dynamic ELF executable imports for {arch} require a Linux dynamic-loader target"
        )
        .into());
    }

    #[derive(Clone)]
    struct Blob {
        name: String,
        align: usize,
        data: Vec<u8>,
        offset: usize,
        sh_type: u32,
        sh_flags: u64,
        segment: &'static str,
    }

    struct SectionRecord {
        name: String,
        sh_type: u32,
        sh_flags: u64,
        addr: u64,
        offset: usize,
        size: usize,
        align: usize,
    }

    let dynamic = !imports.is_empty();
    let got_symbols = phase12_got_relocation_symbols(image);
    let base = phase12_elf64_image_base(arch, target);
    let mut text = image.text.clone();
    let mut rodata = image.rodata.clone();
    let mut data = image.data.clone();
    let runtime_layout = phase12_elf64_reserve_runtime_thunks(&mut text, &runtime_thunks);
    let entry_wrapper = phase12_elf64_reserve_entry_wrapper(&mut text, arch, target);
    let read_line_buffer_offset = if runtime_thunks.read_line {
        let offset = align_to(data.len(), 16);
        data.resize(offset + 4096, 0);
        Some(offset)
    } else {
        None
    };
    let boot_data_layout = phase12_reserve_freestanding_boot_data(&mut data, arch, target);
    let mut text_blobs = Vec::<Blob>::new();
    let mut ro_blobs = Vec::<Blob>::new();
    let mut data_blobs = Vec::<Blob>::new();
    let mut debug_blobs = Vec::<Blob>::new();
    if dynamic {
        ro_blobs.push(Blob {
            name: ".interp".to_string(),
            align: 1,
            data: phase12_elf64_interpreter_bytes(arch),
            offset: 0,
            sh_type: 1,
            sh_flags: 0x2,
            segment: "ro",
        });
        let dynstr = phase12_elf_dynstr_bytes(&imports);
        let dynsym = phase12_elf_dynsym_bytes(&imports, &dynstr);
        ro_blobs.push(Blob {
            name: ".dynstr".to_string(),
            align: 1,
            data: dynstr,
            offset: 0,
            sh_type: 3,
            sh_flags: 0x2,
            segment: "ro",
        });
        ro_blobs.push(Blob {
            name: ".dynsym".to_string(),
            align: 8,
            data: dynsym,
            offset: 0,
            sh_type: 11,
            sh_flags: 0x2,
            segment: "ro",
        });
        ro_blobs.push(Blob {
            name: ".hash".to_string(),
            align: 4,
            data: phase12_elf_hash_bytes(&imports),
            offset: 0,
            sh_type: 5,
            sh_flags: 0x2,
            segment: "ro",
        });
        ro_blobs.push(Blob {
            name: ".rela.plt".to_string(),
            align: 8,
            data: vec![0; imports.len() * 24],
            offset: 0,
            sh_type: 4,
            sh_flags: 0x2,
            segment: "ro",
        });
        text_blobs.push(Blob {
            name: ".plt".to_string(),
            align: 16,
            data: vec![0; phase12_elf64_plt_len(arch, imports.len())],
            offset: 0,
            sh_type: 1,
            sh_flags: 0x6,
            segment: "text",
        });
        data_blobs.push(Blob {
            name: ".got.plt".to_string(),
            align: 8,
            data: vec![0; phase12_elf64_got_plt_len(imports.len())],
            offset: 0,
            sh_type: 1,
            sh_flags: 0x3,
            segment: "data",
        });
    }
    let got_index = if !got_symbols.is_empty() {
        let index = data_blobs.len();
        data_blobs.push(Blob {
            name: ".got".to_string(),
            align: 8,
            data: vec![0; got_symbols.len() * 8],
            offset: 0,
            sh_type: 1,
            sh_flags: 0x3,
            segment: "data",
        });
        Some(index)
    } else {
        None
    };
    if dynamic {
        data_blobs.push(Blob {
            name: ".dynamic".to_string(),
            align: 8,
            data: vec![0; phase12_elf64_dynamic_entry_count(arch) * 16],
            offset: 0,
            sh_type: 6,
            sh_flags: 0x3,
            segment: "data",
        });
    }
    let text_index = text_blobs.len();
    text_blobs.push(Blob {
        name: ".text".to_string(),
        align: image.text_align.max(16),
        data: text.clone(),
        offset: 0,
        sh_type: 1,
        sh_flags: 0x6,
        segment: "text",
    });
    let rodata_index = if !rodata.is_empty() {
        let index = ro_blobs.len();
        ro_blobs.push(Blob {
            name: ".rodata".to_string(),
            align: image.rodata_align.max(8),
            data: rodata.clone(),
            offset: 0,
            sh_type: 1,
            sh_flags: 0x2,
            segment: "ro",
        });
        Some(index)
    } else {
        None
    };
    let data_index = if !data.is_empty() {
        let index = data_blobs.len();
        data_blobs.push(Blob {
            name: ".data".to_string(),
            align: image.data_align.max(8),
            data: data.clone(),
            offset: 0,
            sh_type: 1,
            sh_flags: 0x3,
            segment: "data",
        });
        Some(index)
    } else {
        None
    };
    for section in &image.sections {
        let blob = Blob {
            name: section.name.clone(),
            align: section.align.max(1),
            data: section.data.clone(),
            offset: 0,
            sh_type: 1,
            sh_flags: if section.kind == "debug" { 0 } else { 0x2 },
            segment: if section.kind == "debug" {
                "debug"
            } else {
                "ro"
            },
        };
        match section.kind.as_str() {
            "text" => text_blobs.push(blob),
            "data" => data_blobs.push(Blob {
                sh_flags: 0x3,
                segment: "data",
                ..blob
            }),
            "debug" => debug_blobs.push(blob),
            _ => ro_blobs.push(blob),
        }
    }

    let has_ro_segment = !ro_blobs.is_empty();
    let has_data_segment = !data_blobs.is_empty() || image.bss_size > 0;
    let phnum =
        1 + usize::from(has_ro_segment) + usize::from(has_data_segment) + usize::from(dynamic) * 2;
    let mut cursor = 64 + phnum * 56;
    for blob in &mut text_blobs {
        cursor = align_to(cursor, blob.align);
        blob.offset = cursor;
        cursor += blob.data.len();
    }
    let text_file_end = cursor;
    let ro_segment_offset = if has_ro_segment {
        cursor = align_to(cursor, 0x1000);
        let start = cursor;
        for blob in &mut ro_blobs {
            cursor = align_to(cursor, blob.align);
            blob.offset = cursor;
            cursor += blob.data.len();
        }
        Some(start)
    } else {
        None
    };
    let ro_file_end = cursor;
    let data_segment_offset = if has_data_segment {
        cursor = align_to(cursor, 0x1000);
        let start = cursor;
        for blob in &mut data_blobs {
            cursor = align_to(cursor, blob.align);
            blob.offset = cursor;
            cursor += blob.data.len();
        }
        Some(start)
    } else {
        None
    };
    let data_file_end = cursor;
    for blob in &mut debug_blobs {
        cursor = align_to(cursor, blob.align);
        blob.offset = cursor;
        cursor += blob.data.len();
    }
    let mut offsets = HashMap::<String, usize>::new();
    for blob in text_blobs
        .iter()
        .chain(ro_blobs.iter())
        .chain(data_blobs.iter())
        .chain(debug_blobs.iter())
    {
        offsets.insert(blob.name.clone(), blob.offset);
    }
    let text_va = base + (*offsets.get(".text").unwrap() as u64);
    let rodata_va = offsets.get(".rodata").map(|offset| base + *offset as u64);
    let data_va = offsets.get(".data").map(|offset| base + *offset as u64);
    if let Some(layout) = boot_data_layout {
        phase12_materialize_freestanding_boot_data(
            &mut data,
            layout,
            arch,
            target,
            data_va
                .ok_or("[E_MACHINE_LINK_LAYOUT_001] freestanding boot contract requires .data")?,
            base,
        )?;
    }
    let bss_offset = data_segment_offset
        .map(|offset| align_to(data_file_end.max(offset), image.bss_align.max(1)))
        .unwrap_or_else(|| align_to(text_file_end, image.bss_align.max(1)));
    let bss_va = (image.bss_size > 0).then_some(base + bss_offset as u64);
    let symbol_vas =
        phase12_linked_symbol_vas(image, text_va, rodata_va, data_va, bss_va, &BTreeMap::new());
    let user_entry_va = symbol_vas.get(&image.entry).copied().ok_or_else(|| {
        format!(
            "[E_MACHINE_LINK_ENTRY_MISSING_001] entry symbol '{}' was not laid out",
            image.entry
        )
    })?;
    let mut entry_va = entry_wrapper
        .map(|(offset, _)| text_va + offset as u64)
        .unwrap_or(user_entry_va);
    if matches!(arch, "armv7" | "armv7em") {
        entry_va |= 1;
    }
    let got_va = offsets.get(".got").map(|offset| base + *offset as u64);
    let got_targets = phase12_got_target_vas(&got_symbols, got_va);
    let mut dynamic_targets = HashMap::new();

    if dynamic {
        let dynstr_off = *offsets.get(".dynstr").unwrap();
        let dynsym_off = *offsets.get(".dynsym").unwrap();
        let hash_off = *offsets.get(".hash").unwrap();
        let rela_off = *offsets.get(".rela.plt").unwrap();
        let plt_off = *offsets.get(".plt").unwrap();
        let got_off = *offsets.get(".got.plt").unwrap();
        let dynamic_off = *offsets.get(".dynamic").unwrap();

        let dynstr_va = base + dynstr_off as u64;
        let dynsym_va = base + dynsym_off as u64;
        let hash_va = base + hash_off as u64;
        let rela_va = base + rela_off as u64;
        let plt_va = base + plt_off as u64;
        let got_va = base + got_off as u64;
        let dynamic_va = base + dynamic_off as u64;

        let plt = phase12_elf64_plt_bytes_for_arch(arch, imports.len(), plt_va, got_va)?;
        let got = phase12_elf64_got_plt_bytes_for_arch(arch, imports.len(), dynamic_va, plt_va)?;
        let rela = phase12_elf64_rela_plt_bytes(&imports, got_va, target);
        let dynstr_blob = ro_blobs
            .iter()
            .find(|blob| blob.name == ".dynstr")
            .map(|blob| blob.data.as_slice())
            .unwrap_or_default();
        let dynamic_entries = phase12_elf64_dynamic_entries_for_arch(
            arch,
            dynstr_blob,
            dynstr_va,
            dynsym_va,
            hash_va,
            rela_va,
            got_va,
            rela.len(),
        );
        let dynamic_bytes = phase12_elf_dynamic_bytes(&dynamic_entries);
        for (index, symbol) in imports.iter().enumerate() {
            dynamic_targets.insert(
                symbol.clone(),
                phase12_elf64_plt_entry_va(arch, plt_va, index),
            );
        }
        phase12_elf64_materialize_entry_wrapper(
            &mut text,
            arch,
            target,
            entry_wrapper,
            entry_va,
            user_entry_va,
            &dynamic_targets,
            boot_data_layout,
            data_va,
        )?;
        phase12_elf64_materialize_runtime_thunks(
            &mut text,
            &runtime_layout,
            &runtime_thunks,
            text_va,
            data_va,
            read_line_buffer_offset,
            &mut dynamic_targets,
        )?;
        if let Some(index) = got_index {
            data_blobs[index].data = phase12_elf_got_bytes(
                &got_symbols,
                &symbol_vas,
                &dynamic_targets,
                &image.null_symbols,
            )?;
        }
        phase12_apply_linked_relocations(
            &mut text,
            &mut rodata,
            &mut data,
            image,
            text_va,
            rodata_va,
            data_va,
            bss_va,
            &symbol_vas,
            &dynamic_targets,
            &got_targets,
        )?;

        for blob in &mut ro_blobs {
            if blob.name == ".rela.plt" {
                blob.data = rela.clone();
            } else if rodata_index.is_some() && blob.name == ".rodata" {
                blob.data = rodata.clone();
            }
        }
        for blob in &mut text_blobs {
            if blob.name == ".plt" {
                blob.data = plt.clone();
            } else if blob.name == ".text" {
                blob.data = text.clone();
            }
        }
        for blob in &mut data_blobs {
            match blob.name.as_str() {
                ".got.plt" => blob.data = got.clone(),
                ".dynamic" => blob.data = dynamic_bytes.clone(),
                ".data" => blob.data = data.clone(),
                _ => {}
            }
        }
    } else {
        phase12_elf64_materialize_entry_wrapper(
            &mut text,
            arch,
            target,
            entry_wrapper,
            entry_va,
            user_entry_va,
            &dynamic_targets,
            boot_data_layout,
            data_va,
        )?;
        if let Some(index) = got_index {
            data_blobs[index].data = phase12_elf_got_bytes(
                &got_symbols,
                &symbol_vas,
                &dynamic_targets,
                &image.null_symbols,
            )?;
        }
        phase12_apply_linked_relocations(
            &mut text,
            &mut rodata,
            &mut data,
            image,
            text_va,
            rodata_va,
            data_va,
            bss_va,
            &symbol_vas,
            &dynamic_targets,
            &got_targets,
        )?;
        text_blobs[text_index].data = text;
        if let Some(index) = rodata_index {
            ro_blobs[index].data = rodata;
        }
        if let Some(index) = data_index {
            data_blobs[index].data = data;
        }
    }

    let mut records = Vec::<SectionRecord>::new();
    for blob in text_blobs
        .iter()
        .chain(ro_blobs.iter())
        .chain(data_blobs.iter())
        .chain(debug_blobs.iter())
    {
        records.push(SectionRecord {
            name: blob.name.clone(),
            sh_type: blob.sh_type,
            sh_flags: blob.sh_flags,
            addr: if blob.segment == "debug" {
                0
            } else {
                base + blob.offset as u64
            },
            offset: blob.offset,
            size: blob.data.len(),
            align: blob.align,
        });
    }
    if image.bss_size > 0 {
        records.push(SectionRecord {
            name: ".bss".to_string(),
            sh_type: 8,
            sh_flags: 0x3,
            addr: base + bss_offset as u64,
            offset: bss_offset,
            size: image.bss_size,
            align: image.bss_align.max(1),
        });
    }
    let mut shstr = vec![0_u8];
    let mut sh_names = BTreeMap::<String, u32>::new();
    for record in &records {
        let off = shstr.len() as u32;
        shstr.extend_from_slice(record.name.as_bytes());
        shstr.push(0);
        sh_names.insert(record.name.clone(), off);
    }
    let shstr_name = shstr.len() as u32;
    shstr.extend_from_slice(b".shstrtab\0");
    let shstr_offset = align_to(cursor, 1);
    cursor = shstr_offset + shstr.len();
    let shoff = align_to(cursor, 8);
    let shnum = records.len() + 2;
    let total_file_size = shoff + shnum * 64;
    let mut out = vec![0_u8; total_file_size];
    out[0..4].copy_from_slice(b"\x7fELF");
    out[4] = 2;
    out[5] = 1;
    out[6] = 1;
    out[7] = 0;
    write_u16(&mut out, 16, 2);
    let (machine, flags) = phase12_elf_machine_flags(arch);
    write_u16(&mut out, 18, machine);
    write_u32(&mut out, 20, 1);
    write_u64(&mut out, 24, entry_va);
    write_u64(&mut out, 32, 64);
    write_u64(&mut out, 40, shoff as u64);
    write_u32(&mut out, 48, flags);
    write_u16(&mut out, 52, 64);
    write_u16(&mut out, 54, 56);
    write_u16(&mut out, 56, phnum as u16);
    write_u16(&mut out, 58, 64);
    write_u16(&mut out, 60, shnum as u16);
    write_u16(&mut out, 62, (records.len() + 1) as u16);

    let mut phoff = 64;
    phase12_write_elf64_phdr(
        &mut out,
        phoff,
        1,
        5,
        0,
        base,
        text_file_end as u64,
        text_file_end as u64,
        0x1000,
    );
    phoff += 56;
    if let Some(ro_start) = ro_segment_offset {
        phase12_write_elf64_phdr(
            &mut out,
            phoff,
            1,
            4,
            ro_start as u64,
            base + ro_start as u64,
            (ro_file_end - ro_start) as u64,
            (ro_file_end - ro_start) as u64,
            0x1000,
        );
        phoff += 56;
    }
    if let Some(data_start) = data_segment_offset {
        let filesz = data_file_end - data_start;
        let memsz = if image.bss_size == 0 {
            filesz
        } else {
            bss_offset
                .saturating_add(image.bss_size)
                .saturating_sub(data_start)
        };
        phase12_write_elf64_phdr(
            &mut out,
            phoff,
            1,
            6,
            data_start as u64,
            base + data_start as u64,
            filesz as u64,
            memsz as u64,
            0x1000,
        );
        phoff += 56;
    }
    if dynamic {
        let interp_off = *offsets.get(".interp").unwrap();
        phase12_write_elf64_phdr(
            &mut out,
            phoff,
            3,
            4,
            interp_off as u64,
            base + interp_off as u64,
            ro_blobs
                .iter()
                .find(|blob| blob.name == ".interp")
                .unwrap()
                .data
                .len() as u64,
            ro_blobs
                .iter()
                .find(|blob| blob.name == ".interp")
                .unwrap()
                .data
                .len() as u64,
            1,
        );
        phoff += 56;
        let dynamic_off = *offsets.get(".dynamic").unwrap();
        let dynamic_len = data_blobs
            .iter()
            .find(|blob| blob.name == ".dynamic")
            .unwrap()
            .data
            .len();
        phase12_write_elf64_phdr(
            &mut out,
            phoff,
            2,
            6,
            dynamic_off as u64,
            base + dynamic_off as u64,
            dynamic_len as u64,
            dynamic_len as u64,
            8,
        );
    }

    for blob in text_blobs
        .into_iter()
        .chain(ro_blobs)
        .chain(data_blobs)
        .chain(debug_blobs)
    {
        let end = blob.offset + blob.data.len();
        out[blob.offset..end].copy_from_slice(&blob.data);
    }
    out[shstr_offset..shstr_offset + shstr.len()].copy_from_slice(&shstr);
    let shstr_index = records.len() + 1;
    for (idx, record) in records.iter().enumerate() {
        let off = shoff + (idx + 1) * 64;
        write_u32(&mut out, off, *sh_names.get(&record.name).unwrap_or(&0));
        write_u32(&mut out, off + 4, record.sh_type);
        write_u64(&mut out, off + 8, record.sh_flags);
        write_u64(&mut out, off + 16, record.addr);
        write_u64(&mut out, off + 24, record.offset as u64);
        write_u64(&mut out, off + 32, record.size as u64);
        write_u64(&mut out, off + 48, record.align.max(1) as u64);
        write_u64(
            &mut out,
            off + 56,
            phase12_elf64_section_entsize(&record.name, record.sh_type),
        );
    }
    let off = shoff + shstr_index * 64;
    write_u32(&mut out, off, shstr_name);
    write_u32(&mut out, off + 4, 3);
    write_u64(&mut out, off + 24, shstr_offset as u64);
    write_u64(&mut out, off + 32, shstr.len() as u64);
    write_u64(&mut out, off + 48, 1);
    Ok(out)
}

fn phase12_elf64_section_entsize(name: &str, sh_type: u32) -> u64 {
    match sh_type {
        4 => 24,
        6 => 16,
        9 => 8,
        11 => 24,
        _ if name == ".hash" => 4,
        _ if name == ".got" || name == ".got.plt" => 8,
        _ => 0,
    }
}

fn phase12_elf32_os_executable_bytes(
    image: &Phase12LinkedImage,
    target: &str,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let arch = image.arch.as_str();
    if !matches!(arch, "i386" | "riscv32" | "armv7" | "armv7em") {
        return Err(format!(
            "[E_MACHINE_LINK_TARGET_001] ELF32 executable finalizer does not support arch {arch}"
        )
        .into());
    }
    let imports = &image.dynamic_imports;
    if !imports.is_empty() && arch != "i386" {
        return Err(format!(
            "[E_MACHINE_LINK_DYNAMIC_RELOCATION_FORBIDDEN_001] ELF32 dynamic imports for {arch} require an OS dynamic loader ABI"
        )
        .into());
    }

    #[derive(Clone)]
    struct Blob {
        name: String,
        align: usize,
        data: Vec<u8>,
        offset: usize,
        sh_type: u32,
        sh_flags: u32,
        segment: &'static str,
    }

    struct SectionRecord {
        name: String,
        sh_type: u32,
        sh_flags: u32,
        addr: u32,
        offset: usize,
        size: usize,
        align: usize,
    }

    let base = phase12_elf32_image_base(arch, target);
    let page_align = 0x1000_usize;
    let dynamic = !imports.is_empty();
    let got_symbols = phase12_got_relocation_symbols(image);
    let needs_got_base = image
        .relocations
        .iter()
        .any(|relocation| phase12_relocation_needs_got_base(&relocation.kind));
    let mut text = image.text.clone();
    let mut rodata = image.rodata.clone();
    let mut data = image.data.clone();
    let entry_wrapper = phase12_elf32_reserve_entry_wrapper(&mut text, arch, target);
    let boot_data_layout = phase12_reserve_freestanding_boot_data(&mut data, arch, target);
    let mut text_blobs = vec![Blob {
        name: ".text".to_string(),
        align: image.text_align.max(16),
        data: text.clone(),
        offset: 0,
        sh_type: 1,
        sh_flags: 0x6,
        segment: "text",
    }];
    let mut ro_blobs = Vec::<Blob>::new();
    let mut data_blobs = Vec::<Blob>::new();
    let mut debug_blobs = Vec::<Blob>::new();
    if dynamic {
        ro_blobs.push(Blob {
            name: ".interp".to_string(),
            align: 1,
            data: b"/lib/ld-linux.so.2\0".to_vec(),
            offset: 0,
            sh_type: 1,
            sh_flags: 0x2,
            segment: "ro",
        });
        let dynstr = phase12_elf_dynstr_bytes(imports);
        let dynsym = phase12_elf32_dynsym_bytes(imports, &dynstr);
        ro_blobs.push(Blob {
            name: ".dynstr".to_string(),
            align: 1,
            data: dynstr,
            offset: 0,
            sh_type: 3,
            sh_flags: 0x2,
            segment: "ro",
        });
        ro_blobs.push(Blob {
            name: ".dynsym".to_string(),
            align: 4,
            data: dynsym,
            offset: 0,
            sh_type: 11,
            sh_flags: 0x2,
            segment: "ro",
        });
        ro_blobs.push(Blob {
            name: ".hash".to_string(),
            align: 4,
            data: phase12_elf_hash_bytes(imports),
            offset: 0,
            sh_type: 5,
            sh_flags: 0x2,
            segment: "ro",
        });
        ro_blobs.push(Blob {
            name: ".rel.plt".to_string(),
            align: 4,
            data: vec![0; imports.len() * 8],
            offset: 0,
            sh_type: 9,
            sh_flags: 0x2,
            segment: "ro",
        });
        text_blobs.push(Blob {
            name: ".plt".to_string(),
            align: 16,
            data: vec![0; 16 + imports.len() * 16],
            offset: 0,
            sh_type: 1,
            sh_flags: 0x6,
            segment: "text",
        });
        data_blobs.push(Blob {
            name: ".got.plt".to_string(),
            align: 4,
            data: vec![0; 12 + imports.len() * 4],
            offset: 0,
            sh_type: 1,
            sh_flags: 0x3,
            segment: "data",
        });
        data_blobs.push(Blob {
            name: ".dynamic".to_string(),
            align: 4,
            data: vec![0; 14 * 8],
            offset: 0,
            sh_type: 6,
            sh_flags: 0x3,
            segment: "data",
        });
    }
    if !rodata.is_empty() {
        ro_blobs.push(Blob {
            name: ".rodata".to_string(),
            align: image.rodata_align.max(4),
            data: rodata.clone(),
            offset: 0,
            sh_type: 1,
            sh_flags: 0x2,
            segment: "ro",
        });
    }
    let got_index = if !needs_got_base {
        None
    } else {
        let index = data_blobs.len();
        data_blobs.push(Blob {
            name: ".got".to_string(),
            align: 4,
            data: vec![0; (got_symbols.len() * 4).max(4)],
            offset: 0,
            sh_type: 1,
            sh_flags: 0x3,
            segment: "data",
        });
        Some(index)
    };
    let data_index = if data.is_empty() {
        None
    } else {
        let index = data_blobs.len();
        data_blobs.push(Blob {
            name: ".data".to_string(),
            align: image.data_align.max(4),
            data: data.clone(),
            offset: 0,
            sh_type: 1,
            sh_flags: 0x3,
            segment: "data",
        });
        Some(index)
    };
    for section in &image.sections {
        let blob = Blob {
            name: section.name.clone(),
            align: section.align.max(1),
            data: section.data.clone(),
            offset: 0,
            sh_type: 1,
            sh_flags: if section.kind == "debug" { 0 } else { 0x2 },
            segment: if section.kind == "debug" {
                "debug"
            } else {
                "ro"
            },
        };
        match section.kind.as_str() {
            "text" => text_blobs.push(blob),
            "data" => data_blobs.push(Blob {
                sh_flags: 0x3,
                segment: "data",
                ..blob
            }),
            "debug" => debug_blobs.push(blob),
            _ => ro_blobs.push(blob),
        }
    }

    let has_ro_segment = !ro_blobs.is_empty();
    let has_data_segment = !data_blobs.is_empty() || image.bss_size > 0;
    let phnum =
        1 + usize::from(has_ro_segment) + usize::from(has_data_segment) + usize::from(dynamic) * 2;
    let mut cursor = 52 + phnum * 32;
    for blob in &mut text_blobs {
        cursor = align_to(cursor, blob.align);
        blob.offset = cursor;
        cursor += blob.data.len();
    }
    let text_file_end = cursor;
    let ro_segment_offset = if has_ro_segment {
        cursor = align_to(cursor, page_align);
        let start = cursor;
        for blob in &mut ro_blobs {
            cursor = align_to(cursor, blob.align);
            blob.offset = cursor;
            cursor += blob.data.len();
        }
        Some(start)
    } else {
        None
    };
    let ro_file_end = cursor;
    let data_segment_offset = if has_data_segment {
        cursor = align_to(cursor, page_align);
        let start = cursor;
        for blob in &mut data_blobs {
            cursor = align_to(cursor, blob.align);
            blob.offset = cursor;
            cursor += blob.data.len();
        }
        Some(start)
    } else {
        None
    };
    let data_file_end = cursor;
    for blob in &mut debug_blobs {
        cursor = align_to(cursor, blob.align);
        blob.offset = cursor;
        cursor += blob.data.len();
    }

    let mut offsets = HashMap::<String, usize>::new();
    for blob in text_blobs
        .iter()
        .chain(ro_blobs.iter())
        .chain(data_blobs.iter())
        .chain(debug_blobs.iter())
    {
        offsets.insert(blob.name.clone(), blob.offset);
    }
    let text_va = base + (*offsets.get(".text").unwrap() as u64);
    let rodata_va = offsets.get(".rodata").map(|offset| base + *offset as u64);
    let data_va = offsets.get(".data").map(|offset| base + *offset as u64);
    if let Some(layout) = boot_data_layout {
        phase12_materialize_freestanding_boot_data(
            &mut data,
            layout,
            arch,
            target,
            data_va
                .ok_or("[E_MACHINE_LINK_LAYOUT_001] freestanding boot contract requires .data")?,
            base,
        )?;
    }
    let bss_offset = data_segment_offset
        .map(|offset| align_to(data_file_end.max(offset), image.bss_align.max(1)))
        .unwrap_or_else(|| align_to(text_file_end, image.bss_align.max(1)));
    let bss_va = (image.bss_size > 0).then_some(base + bss_offset as u64);
    let symbol_vas =
        phase12_linked_symbol_vas(image, text_va, rodata_va, data_va, bss_va, &BTreeMap::new());
    let user_entry_va = symbol_vas.get(&image.entry).copied().ok_or_else(|| {
        format!(
            "[E_MACHINE_LINK_ENTRY_MISSING_001] entry symbol '{}' was not laid out",
            image.entry
        )
    })?;
    let entry_va = entry_wrapper
        .map(|(offset, _)| text_va + offset as u64)
        .unwrap_or(user_entry_va);
    if entry_va > u32::MAX as u64 {
        return Err("[E_MACHINE_LINK_ENTRY_RANGE_001] ELF32 entry exceeds u32".into());
    }
    let got_va = offsets.get(".got").map(|offset| base + *offset as u64);
    let mut got_targets = phase12_elf32_got_target_vas(&got_symbols, got_va);
    if let Some(got_base) = got_va {
        got_targets.insert("_GLOBAL_OFFSET_TABLE_".to_string(), got_base);
        got_targets.insert("__GLOBAL_OFFSET_TABLE_".to_string(), got_base);
    }
    let mut dynamic_targets = HashMap::new();
    if dynamic {
        let dynstr_off = *offsets.get(".dynstr").unwrap();
        let dynsym_off = *offsets.get(".dynsym").unwrap();
        let hash_off = *offsets.get(".hash").unwrap();
        let rel_off = *offsets.get(".rel.plt").unwrap();
        let plt_off = *offsets.get(".plt").unwrap();
        let got_plt_off = *offsets.get(".got.plt").unwrap();
        let dynamic_off = *offsets.get(".dynamic").unwrap();

        let dynstr_va = base + dynstr_off as u64;
        let dynsym_va = base + dynsym_off as u64;
        let hash_va = base + hash_off as u64;
        let rel_va = base + rel_off as u64;
        let plt_va = base + plt_off as u64;
        let got_plt_va = base + got_plt_off as u64;
        let dynamic_va = base + dynamic_off as u64;

        let plt = phase12_elf32_plt_bytes(imports.len(), plt_va, got_plt_va)?;
        let got_plt = phase12_elf32_got_plt_bytes(imports.len(), dynamic_va, plt_va)?;
        let rel = phase12_elf32_rel_plt_bytes(imports, got_plt_va, target)?;
        let dynstr_len = ro_blobs
            .iter()
            .find(|blob| blob.name == ".dynstr")
            .map(|blob| blob.data.len())
            .unwrap_or_default();
        let dynamic_entries = vec![
            (
                "DT_NEEDED",
                phase12_cstr_offset(
                    ro_blobs
                        .iter()
                        .find(|blob| blob.name == ".dynstr")
                        .map(|blob| blob.data.as_slice())
                        .unwrap_or_default(),
                    "libc.so.6",
                )
                .unwrap_or(1) as u32,
            ),
            ("DT_HASH", hash_va as u32),
            ("DT_STRTAB", dynstr_va as u32),
            ("DT_SYMTAB", dynsym_va as u32),
            ("DT_STRSZ", dynstr_len as u32),
            ("DT_SYMENT", 16),
            ("DT_PLTGOT", got_plt_va as u32),
            ("DT_PLTRELSZ", rel.len() as u32),
            ("DT_PLTREL", 17),
            ("DT_JMPREL", rel_va as u32),
            ("DT_REL", rel_va as u32),
            ("DT_RELSZ", rel.len() as u32),
            ("DT_RELENT", 8),
            ("DT_NULL", 0),
        ];
        let dynamic_bytes = phase12_elf32_dynamic_bytes(&dynamic_entries);
        for (index, symbol) in imports.iter().enumerate() {
            dynamic_targets.insert(symbol.clone(), plt_va + 16 + (index as u64 * 16));
        }
        if let Some(index) = got_index {
            data_blobs[index].data = phase12_elf32_got_bytes(
                &got_symbols,
                &symbol_vas,
                &dynamic_targets,
                &image.null_symbols,
            )?;
        }
        for blob in &mut ro_blobs {
            if blob.name == ".rel.plt" {
                blob.data = rel.clone();
            }
        }
        for blob in &mut text_blobs {
            if blob.name == ".plt" {
                blob.data = plt.clone();
            }
        }
        for blob in &mut data_blobs {
            match blob.name.as_str() {
                ".got.plt" => blob.data = got_plt.clone(),
                ".dynamic" => blob.data = dynamic_bytes.clone(),
                _ => {}
            }
        }
    } else if let Some(index) = got_index {
        data_blobs[index].data = phase12_elf32_got_bytes(
            &got_symbols,
            &symbol_vas,
            &dynamic_targets,
            &image.null_symbols,
        )?;
    }
    phase12_elf32_materialize_entry_wrapper(
        &mut text,
        arch,
        target,
        entry_wrapper,
        entry_va,
        user_entry_va,
        boot_data_layout,
        data_va,
    )?;
    phase12_apply_linked_relocations(
        &mut text,
        &mut rodata,
        &mut data,
        image,
        text_va,
        rodata_va,
        data_va,
        bss_va,
        &symbol_vas,
        &dynamic_targets,
        &got_targets,
    )?;
    text_blobs[0].data = text;
    if let Some(blob) = ro_blobs.iter_mut().find(|blob| blob.name == ".rodata") {
        blob.data = rodata;
    }
    if let Some(index) = data_index {
        data_blobs[index].data = data;
    }

    let mut records = Vec::<SectionRecord>::new();
    for blob in text_blobs
        .iter()
        .chain(ro_blobs.iter())
        .chain(data_blobs.iter())
        .chain(debug_blobs.iter())
    {
        let addr = if blob.segment == "debug" {
            0
        } else {
            u32::try_from(base + blob.offset as u64).map_err(|_| {
                "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] ELF32 section address exceeds u32"
            })?
        };
        records.push(SectionRecord {
            name: blob.name.clone(),
            sh_type: blob.sh_type,
            sh_flags: blob.sh_flags,
            addr,
            offset: blob.offset,
            size: blob.data.len(),
            align: blob.align,
        });
    }
    if image.bss_size > 0 {
        records.push(SectionRecord {
            name: ".bss".to_string(),
            sh_type: 8,
            sh_flags: 0x3,
            addr: u32::try_from(base + bss_offset as u64).map_err(|_| {
                "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] ELF32 bss address exceeds u32"
            })?,
            offset: bss_offset,
            size: image.bss_size,
            align: image.bss_align.max(1),
        });
    }

    let mut shstr = vec![0_u8];
    let mut sh_names = BTreeMap::<String, u32>::new();
    for record in &records {
        let off = shstr.len() as u32;
        shstr.extend_from_slice(record.name.as_bytes());
        shstr.push(0);
        sh_names.insert(record.name.clone(), off);
    }
    let shstr_name = shstr.len() as u32;
    shstr.extend_from_slice(b".shstrtab\0");
    let shstr_offset = align_to(cursor, 1);
    cursor = shstr_offset + shstr.len();
    let shoff = align_to(cursor, 4);
    let shnum = records.len() + 2;
    let total_file_size = shoff + shnum * 40;
    let mut out = vec![0_u8; total_file_size];
    out[0..4].copy_from_slice(b"\x7fELF");
    out[4] = 1;
    out[5] = 1;
    out[6] = 1;
    out[7] = 0;
    write_u16(&mut out, 16, 2);
    let (machine, flags) = phase12_elf_machine_flags(arch);
    write_u16(&mut out, 18, machine);
    write_u32(&mut out, 20, 1);
    let encoded_entry_va = if matches!(arch, "armv7" | "armv7em") {
        entry_va | 1
    } else {
        entry_va
    };
    write_u32(&mut out, 24, encoded_entry_va as u32);
    write_u32(&mut out, 28, 52);
    write_u32(&mut out, 32, shoff as u32);
    write_u32(&mut out, 36, flags);
    write_u16(&mut out, 40, 52);
    write_u16(&mut out, 42, 32);
    write_u16(&mut out, 44, phnum as u16);
    write_u16(&mut out, 46, 40);
    write_u16(&mut out, 48, shnum as u16);
    write_u16(&mut out, 50, (records.len() + 1) as u16);

    let mut phoff = 52;
    phase12_write_elf32_phdr(
        &mut out,
        phoff,
        1,
        0,
        base as u32,
        text_file_end as u32,
        text_file_end as u32,
        5,
        page_align as u32,
    );
    phoff += 32;
    if let Some(start) = ro_segment_offset {
        phase12_write_elf32_phdr(
            &mut out,
            phoff,
            1,
            start as u32,
            (base + start as u64) as u32,
            (ro_file_end - start) as u32,
            (ro_file_end - start) as u32,
            4,
            page_align as u32,
        );
        phoff += 32;
    }
    if let Some(start) = data_segment_offset {
        let filesz = data_file_end - start;
        let memsz = if image.bss_size == 0 {
            filesz
        } else {
            bss_offset
                .saturating_add(image.bss_size)
                .saturating_sub(start)
        };
        phase12_write_elf32_phdr(
            &mut out,
            phoff,
            1,
            start as u32,
            (base + start as u64) as u32,
            filesz as u32,
            memsz as u32,
            6,
            page_align as u32,
        );
        phoff += 32;
    }
    if dynamic {
        let interp_off = *offsets.get(".interp").unwrap();
        let interp_len = ro_blobs
            .iter()
            .find(|blob| blob.name == ".interp")
            .unwrap()
            .data
            .len();
        phase12_write_elf32_phdr(
            &mut out,
            phoff,
            3,
            interp_off as u32,
            (base + interp_off as u64) as u32,
            interp_len as u32,
            interp_len as u32,
            4,
            1,
        );
        phoff += 32;
        let dynamic_off = *offsets.get(".dynamic").unwrap();
        let dynamic_len = data_blobs
            .iter()
            .find(|blob| blob.name == ".dynamic")
            .unwrap()
            .data
            .len();
        phase12_write_elf32_phdr(
            &mut out,
            phoff,
            2,
            dynamic_off as u32,
            (base + dynamic_off as u64) as u32,
            dynamic_len as u32,
            dynamic_len as u32,
            6,
            4,
        );
    }

    for blob in text_blobs
        .iter()
        .chain(ro_blobs.iter())
        .chain(data_blobs.iter())
        .chain(debug_blobs.iter())
    {
        out[blob.offset..blob.offset + blob.data.len()].copy_from_slice(&blob.data);
    }
    out[shstr_offset..shstr_offset + shstr.len()].copy_from_slice(&shstr);
    let section_indices = records
        .iter()
        .enumerate()
        .map(|(index, record)| (record.name.as_str(), (index + 1) as u32))
        .collect::<BTreeMap<_, _>>();
    let mut section_offset = shoff + 40;
    for record in &records {
        let (link, info, entry_size) = match record.name.as_str() {
            ".dynsym" => (*section_indices.get(".dynstr").unwrap_or(&0), 1, 16),
            ".hash" => (*section_indices.get(".dynsym").unwrap_or(&0), 0, 4),
            ".rel.plt" => (
                *section_indices.get(".dynsym").unwrap_or(&0),
                *section_indices.get(".got.plt").unwrap_or(&0),
                8,
            ),
            ".dynamic" => (*section_indices.get(".dynstr").unwrap_or(&0), 0, 8),
            _ => (0, 0, 0),
        };
        write_elf32_section_header(
            &mut out,
            section_offset,
            *sh_names.get(&record.name).unwrap(),
            record.sh_type,
            record.sh_flags,
            record.offset,
            record.size,
            link,
            info,
            record.align as u32,
            entry_size,
        );
        write_u32(&mut out, section_offset + 12, record.addr);
        section_offset += 40;
    }
    write_elf32_section_header(
        &mut out,
        section_offset,
        shstr_name,
        3,
        0,
        shstr_offset,
        shstr.len(),
        0,
        0,
        1,
        0,
    );
    Ok(out)
}

fn phase12_elf_machine_flags(arch: &str) -> (u16, u32) {
    match arch {
        "i386" => (3, 0),
        "armv7" | "armv7em" => (40, ncc_machine::EF_ARM_EABI_VER5),
        "aarch64" => (183, 0),
        "riscv32" => (243, 0x01),
        "riscv64" => (243, 0x04),
        _ => (62, 0),
    }
}

#[derive(Clone, Default)]
struct Phase12ElfRuntimeThunks {
    read_int: bool,
    read_line: bool,
    str_eq: bool,
    sleep_symbols: Vec<String>,
}

impl Phase12ElfRuntimeThunks {
    fn has_sleep(&self) -> bool {
        !self.sleep_symbols.is_empty()
    }

    fn any(&self) -> bool {
        self.read_int || self.read_line || self.str_eq || self.has_sleep()
    }
}

#[derive(Default)]
struct Phase12Elf64RuntimeThunkLayout {
    read_int: Option<(usize, usize)>,
    read_line: Option<(usize, usize)>,
    str_eq: Option<(usize, usize)>,
    sleep_ms: Option<(usize, usize)>,
}

fn phase12_elf_runtime_thunks(requested: &[String]) -> Phase12ElfRuntimeThunks {
    let mut spec = Phase12ElfRuntimeThunks::default();
    let mut sleep_symbols = BTreeSet::new();
    for symbol in requested {
        match symbol.as_str() {
            "readInt" => spec.read_int = true,
            "readLine" => spec.read_line = true,
            "strEq" => spec.str_eq = true,
            "sleep" | "sleepMs" | "threadSleep" => {
                sleep_symbols.insert(symbol.clone());
            }
            _ => {}
        }
    }
    spec.sleep_symbols = sleep_symbols.into_iter().collect();
    spec
}

fn phase12_elf_loader_import_symbols(requested: &[String]) -> Vec<String> {
    let mut imports = requested.iter().cloned().collect::<BTreeSet<_>>();
    let uses_read_int = imports.remove("readInt");
    let uses_read_line = imports.remove("readLine");
    let uses_str_eq = imports.remove("strEq");
    let uses_sleep = imports.remove("sleep");
    let uses_sleep_ms = imports.remove("sleepMs");
    let uses_thread_sleep = imports.remove("threadSleep");
    if uses_read_int || uses_read_line {
        imports.insert("getchar".to_string());
    }
    if uses_str_eq {
        imports.insert("strcmp".to_string());
    }
    if uses_sleep || uses_sleep_ms || uses_thread_sleep {
        imports.insert("usleep".to_string());
    }
    imports.into_iter().collect()
}

fn phase12_elf64_reserve_runtime_thunks(
    text: &mut Vec<u8>,
    spec: &Phase12ElfRuntimeThunks,
) -> Phase12Elf64RuntimeThunkLayout {
    let mut layout = Phase12Elf64RuntimeThunkLayout::default();
    if !spec.any() {
        return layout;
    }
    let start = align_to(text.len(), 16);
    text.resize(start, 0x90);
    if spec.read_int {
        let offset = text.len();
        let len = phase12_elf64_internal_read_int_thunk_len();
        text.resize(offset + len, 0x90);
        layout.read_int = Some((offset, len));
    }
    if spec.read_line {
        let offset = text.len();
        let len = phase12_elf64_internal_read_line_thunk_len();
        text.resize(offset + len, 0x90);
        layout.read_line = Some((offset, len));
    }
    if spec.str_eq {
        let offset = text.len();
        let len = phase12_elf64_internal_str_eq_thunk_len();
        text.resize(offset + len, 0x90);
        layout.str_eq = Some((offset, len));
    }
    if spec.has_sleep() {
        let offset = text.len();
        let len = phase12_elf64_internal_sleep_ms_thunk_len();
        text.resize(offset + len, 0x90);
        layout.sleep_ms = Some((offset, len));
    }
    layout
}

const PHASE12_AARCH64_QEMU_SUCCESS: &[u8] = b"nC kernel AArch64 kmain\n";
const PHASE12_AARCH64_QEMU_FAILURE: &[u8] = b"nC kernel AArch64 main failed\n";
const PHASE12_RISCV64_QEMU_SUCCESS: &[u8] = b"nC kernel RISC-V64 kmain\n";
const PHASE12_RISCV64_QEMU_FAILURE: &[u8] = b"nC kernel RISC-V64 main failed\n";
const PHASE12_RISCV32_QEMU_SUCCESS: &[u8] = b"nC kernel RISC-V32 kmain\n";
const PHASE12_RISCV32_QEMU_FAILURE: &[u8] = b"nC kernel RISC-V32 main failed\n";

fn phase12_push_u32_word(bytes: &mut Vec<u8>, word: u32) {
    bytes.extend_from_slice(&word.to_le_bytes());
}

fn phase12_aarch64_load_u64(bytes: &mut Vec<u8>, rd: u32, value: u64) {
    phase12_push_u32_word(bytes, 0xd280_0000 | (((value as u32) & 0xffff) << 5) | rd);
    for hw in 1..=3_u32 {
        let imm = ((value >> (hw * 16)) & 0xffff) as u32;
        phase12_push_u32_word(bytes, 0xf280_0000 | (hw << 21) | (imm << 5) | rd);
    }
}

fn phase12_aarch64_branch_word(
    opcode: u32,
    bits: u32,
    from_va: u64,
    to_va: u64,
) -> Result<u32, Box<dyn Error>> {
    let displacement = to_va as i128 - from_va as i128;
    if displacement % 4 != 0 {
        return Err("[E_MACHINE_LINK_PCREL_RANGE_001] AArch64 branch is not word aligned".into());
    }
    let words = displacement / 4;
    let minimum = -(1_i128 << (bits - 1));
    let maximum = (1_i128 << (bits - 1)) - 1;
    if words < minimum || words > maximum {
        return Err("[E_MACHINE_LINK_PCREL_RANGE_001] AArch64 boot branch is out of range".into());
    }
    Ok(opcode | ((words as i64 as u64 as u32) & ((1_u32 << bits) - 1)))
}

fn phase12_aarch64_compare_branch_word(
    opcode: u32,
    rt: u32,
    from_va: u64,
    to_va: u64,
) -> Result<u32, Box<dyn Error>> {
    let displacement = to_va as i128 - from_va as i128;
    if displacement % 4 != 0 {
        return Err(
            "[E_MACHINE_LINK_PCREL_RANGE_001] AArch64 compare branch is not word aligned".into(),
        );
    }
    let words = displacement / 4;
    if !(-(1_i128 << 18)..=(1_i128 << 18) - 1).contains(&words) {
        return Err(
            "[E_MACHINE_LINK_PCREL_RANGE_001] AArch64 compare branch is out of range".into(),
        );
    }
    Ok(opcode | (((words as i64 as u64 as u32) & 0x7ffff) << 5) | (rt & 0x1f))
}

fn phase12_aarch64_uart_bytes(bytes: &mut Vec<u8>, message: &[u8]) {
    for byte in message {
        phase12_push_u32_word(bytes, 0xd280_0000 | ((*byte as u32) << 5) | 11);
        phase12_push_u32_word(bytes, 0x3900_0000 | (10 << 5) | 11);
    }
}

fn phase12_aarch64_qemu_entry_wrapper_bytes(
    wrapper_va: u64,
    user_entry_va: u64,
    boot_info_va: u64,
    fdt_ptr_va: u64,
    boot_stack_top_va: u64,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let mut bytes = Vec::new();
    phase12_push_u32_word(&mut bytes, 0xaa00_03f3); // mov x19, x0 (QEMU FDT)
    for word in [
        0xd538_1049, // mrs x9, cpacr_el1
        0xd280_006a, // mov x10, #3
        0xd36c_ad4a, // lsl x10, x10, #20
        0xaa0a_0129, // orr x9, x9, x10
        0xd518_1049, // msr cpacr_el1, x9
        0xd503_3fdf, // isb
    ] {
        phase12_push_u32_word(&mut bytes, word);
    }
    phase12_aarch64_load_u64(&mut bytes, 9, boot_stack_top_va);
    phase12_push_u32_word(&mut bytes, 0x9100_013f); // add sp, x9, #0
    phase12_aarch64_load_u64(&mut bytes, 9, ncc_machine::KERNEL_BOOT_INFO_MAGIC);
    phase12_push_u32_word(&mut bytes, 0xca09_0029); // eor x9, x1, x9
    let direct_boot_offset = bytes.len();
    phase12_push_u32_word(&mut bytes, 0); // cbz x9, direct boot_info path
    phase12_aarch64_load_u64(&mut bytes, 0, boot_info_va);
    phase12_aarch64_load_u64(&mut bytes, 10, fdt_ptr_va);
    phase12_push_u32_word(&mut bytes, 0xf900_0153); // str x19, [x10]
    let direct_boot_target = bytes.len();
    let call_va = wrapper_va + bytes.len() as u64;
    phase12_push_u32_word(
        &mut bytes,
        phase12_aarch64_branch_word(0x9400_0000, 26, call_va, user_entry_va)?,
    );
    phase12_aarch64_load_u64(&mut bytes, 10, 0x0900_0000);
    let cbnz_offset = bytes.len();
    phase12_push_u32_word(&mut bytes, 0);
    phase12_aarch64_uart_bytes(&mut bytes, PHASE12_AARCH64_QEMU_SUCCESS);
    let success_jump_offset = bytes.len();
    phase12_push_u32_word(&mut bytes, 0);
    let failure_offset = bytes.len();
    phase12_aarch64_uart_bytes(&mut bytes, PHASE12_AARCH64_QEMU_FAILURE);
    let park_offset = bytes.len();
    phase12_push_u32_word(&mut bytes, 0xd503_207f); // wfi
    phase12_push_u32_word(&mut bytes, 0x17ff_ffff); // b back to wfi

    let cbnz_va = wrapper_va + cbnz_offset as u64;
    let cbnz = phase12_aarch64_compare_branch_word(
        0xb500_0000,
        0,
        cbnz_va,
        wrapper_va + failure_offset as u64,
    )?;
    bytes[cbnz_offset..cbnz_offset + 4].copy_from_slice(&cbnz.to_le_bytes());
    let jump_va = wrapper_va + success_jump_offset as u64;
    let jump =
        phase12_aarch64_branch_word(0x1400_0000, 26, jump_va, wrapper_va + park_offset as u64)?;
    bytes[success_jump_offset..success_jump_offset + 4].copy_from_slice(&jump.to_le_bytes());
    let direct_boot_va = wrapper_va + direct_boot_offset as u64;
    let direct_boot = phase12_aarch64_compare_branch_word(
        0xb400_0000,
        9,
        direct_boot_va,
        wrapper_va + direct_boot_target as u64,
    )?;
    bytes[direct_boot_offset..direct_boot_offset + 4].copy_from_slice(&direct_boot.to_le_bytes());
    Ok(bytes)
}

fn phase12_riscv_lui(rd: u32, imm20: u32) -> u32 {
    ((imm20 & 0x000f_ffff) << 12) | (rd << 7) | 0x37
}

fn phase12_riscv_addi(rd: u32, rs1: u32, imm: i32) -> u32 {
    (((imm as u32) & 0x0fff) << 20) | (rs1 << 15) | (rd << 7) | 0x13
}

fn phase12_riscv_load_u32(bytes: &mut Vec<u8>, rd: u32, value: u64, xlen: u32) {
    let value = value as u32;
    let hi = value.wrapping_add(0x800) >> 12;
    let lo = value.wrapping_sub(hi << 12) as i32;
    phase12_push_u32_word(bytes, phase12_riscv_lui(rd, hi));
    phase12_push_u32_word(bytes, phase12_riscv_addi(rd, rd, lo));
    if xlen == 64 {
        phase12_push_u32_word(
            bytes,
            (32 << 20) | (rd << 15) | (1 << 12) | (rd << 7) | 0x13,
        );
        phase12_push_u32_word(
            bytes,
            (32 << 20) | (rd << 15) | (5 << 12) | (rd << 7) | 0x13,
        );
    }
}

fn phase12_riscv_store(rs2: u32, rs1: u32, offset: i32, funct3: u32) -> u32 {
    let imm = (offset as u32) & 0x0fff;
    ((imm >> 5) << 25) | (rs2 << 20) | (rs1 << 15) | (funct3 << 12) | ((imm & 0x1f) << 7) | 0x23
}

fn phase12_riscv_jal_word(rd: u32, displacement: i64) -> Result<u32, Box<dyn Error>> {
    if displacement % 2 != 0 || !(-1_048_576..=1_048_574).contains(&displacement) {
        return Err("[E_MACHINE_LINK_PCREL_RANGE_001] RISC-V JAL is out of range".into());
    }
    let imm = (displacement as i32 as u32) & 0x001f_ffff;
    Ok(((imm >> 20) & 1) << 31
        | ((imm >> 1) & 0x3ff) << 21
        | ((imm >> 11) & 1) << 20
        | ((imm >> 12) & 0xff) << 12
        | (rd << 7)
        | 0x6f)
}

fn phase12_riscv_branch_word(
    rs1: u32,
    rs2: u32,
    funct3: u32,
    displacement: i64,
) -> Result<u32, Box<dyn Error>> {
    if displacement % 2 != 0 || !(-4096..=4094).contains(&displacement) {
        return Err("[E_MACHINE_LINK_PCREL_RANGE_001] RISC-V branch is out of range".into());
    }
    let imm = (displacement as i32 as u32) & 0x1fff;
    Ok(((imm >> 12) & 1) << 31
        | ((imm >> 5) & 0x3f) << 25
        | (rs2 << 20)
        | (rs1 << 15)
        | ((funct3 & 0x7) << 12)
        | ((imm >> 1) & 0xf) << 8
        | ((imm >> 11) & 1) << 7
        | 0x63)
}

fn phase12_riscv_uart_bytes(bytes: &mut Vec<u8>, message: &[u8]) {
    for byte in message {
        phase12_push_u32_word(bytes, phase12_riscv_addi(6, 0, *byte as i32));
        phase12_push_u32_word(bytes, phase12_riscv_store(6, 5, 0, 0));
    }
}

fn phase12_riscv_qemu_entry_wrapper_bytes(
    xlen: u32,
    wrapper_va: u64,
    user_entry_va: u64,
    boot_info_va: u64,
    fdt_ptr_va: u64,
    hart_ptr_va: u64,
    boot_stack_top_va: u64,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let mut bytes = Vec::new();
    phase12_push_u32_word(&mut bytes, phase12_riscv_addi(8, 10, 0)); // s0 = hart
    phase12_push_u32_word(&mut bytes, phase12_riscv_addi(9, 11, 0)); // s1 = FDT
    phase12_push_u32_word(&mut bytes, (0x100 << 20) | (2 << 12) | (5 << 7) | 0x73);
    phase12_riscv_load_u32(&mut bytes, 6, 0x6000, xlen);
    phase12_push_u32_word(
        &mut bytes,
        (6 << 20) | (5 << 15) | (6 << 12) | (5 << 7) | 0x33,
    );
    phase12_push_u32_word(&mut bytes, (0x100 << 20) | (5 << 15) | (1 << 12) | 0x73);
    phase12_riscv_load_u32(&mut bytes, 2, boot_stack_top_va, xlen);
    phase12_riscv_load_u32(&mut bytes, 10, boot_info_va, xlen);
    phase12_riscv_load_u32(&mut bytes, 5, fdt_ptr_va, xlen);
    if xlen == 64 {
        phase12_push_u32_word(&mut bytes, phase12_riscv_store(9, 5, 0, 3));
    } else {
        phase12_push_u32_word(&mut bytes, phase12_riscv_store(9, 5, 0, 2));
        phase12_push_u32_word(&mut bytes, phase12_riscv_store(0, 5, 4, 2));
    }
    phase12_riscv_load_u32(&mut bytes, 5, hart_ptr_va, xlen);
    if xlen == 64 {
        phase12_push_u32_word(&mut bytes, phase12_riscv_store(8, 5, 0, 3));
    } else {
        phase12_push_u32_word(&mut bytes, phase12_riscv_store(8, 5, 0, 2));
        phase12_push_u32_word(&mut bytes, phase12_riscv_store(0, 5, 4, 2));
        phase12_push_u32_word(&mut bytes, phase12_riscv_addi(11, 0, 0)); // high half of i64 boot_info
    }
    let call_va = wrapper_va + bytes.len() as u64;
    phase12_push_u32_word(
        &mut bytes,
        phase12_riscv_jal_word(1, user_entry_va as i64 - call_va as i64)?,
    );
    phase12_riscv_load_u32(&mut bytes, 5, 0x1000_0000, xlen);
    let bne_offset = bytes.len();
    phase12_push_u32_word(&mut bytes, 0);
    let (success, failure) = if xlen == 64 {
        (PHASE12_RISCV64_QEMU_SUCCESS, PHASE12_RISCV64_QEMU_FAILURE)
    } else {
        (PHASE12_RISCV32_QEMU_SUCCESS, PHASE12_RISCV32_QEMU_FAILURE)
    };
    phase12_riscv_uart_bytes(&mut bytes, success);
    let success_jump_offset = bytes.len();
    phase12_push_u32_word(&mut bytes, 0);
    let failure_offset = bytes.len();
    phase12_riscv_uart_bytes(&mut bytes, failure);
    let park_offset = bytes.len();
    phase12_push_u32_word(&mut bytes, 0x1050_0073); // wfi
    phase12_push_u32_word(&mut bytes, phase12_riscv_jal_word(0, -4)?);

    let bne = phase12_riscv_branch_word(10, 0, 1, failure_offset as i64 - bne_offset as i64)?;
    bytes[bne_offset..bne_offset + 4].copy_from_slice(&bne.to_le_bytes());
    let jump = phase12_riscv_jal_word(0, park_offset as i64 - success_jump_offset as i64)?;
    bytes[success_jump_offset..success_jump_offset + 4].copy_from_slice(&jump.to_le_bytes());
    Ok(bytes)
}

fn phase12_elf64_reserve_entry_wrapper(
    text: &mut Vec<u8>,
    arch: &str,
    target: &str,
) -> Option<(usize, usize)> {
    let len = phase12_elf64_entry_wrapper_len(arch, target)?;
    let offset = align_to(text.len(), 16);
    text.resize(offset, 0x90);
    text.resize(offset + len, 0x90);
    Some((offset, len))
}

fn phase12_elf32_reserve_entry_wrapper(
    text: &mut Vec<u8>,
    arch: &str,
    target: &str,
) -> Option<(usize, usize)> {
    let len = phase12_elf32_entry_wrapper_len(arch, target)?;
    let offset = align_to(text.len(), 16);
    text.resize(offset, 0x90);
    text.resize(offset + len, 0x90);
    Some((offset, len))
}

fn phase12_elf32_entry_wrapper_len(arch: &str, target: &str) -> Option<usize> {
    match (arch, target) {
        ("i386", target) if target.contains("linux") => Some(33),
        ("riscv32", "riscv32imac-unknown-elf") => {
            phase12_riscv_qemu_entry_wrapper_bytes(32, 0, 0, 0, 0, 0, 0)
                .ok()
                .map(|bytes| bytes.len())
        }
        _ => None,
    }
}

fn phase12_elf32_materialize_entry_wrapper(
    text: &mut [u8],
    arch: &str,
    target: &str,
    layout: Option<(usize, usize)>,
    wrapper_va: u64,
    user_entry_va: u64,
    boot_layout: Option<Phase12FreestandingBootDataLayout>,
    data_va: Option<u64>,
) -> Result<(), Box<dyn Error>> {
    let Some((offset, len)) = layout else {
        return Ok(());
    };
    let bytes = if phase12_is_qemu_virt_freestanding(arch, target) {
        let boot_layout = boot_layout
            .ok_or("[E_MACHINE_LINK_LAYOUT_001] RISC-V boot wrapper is missing boot data")?;
        let data_va =
            data_va.ok_or("[E_MACHINE_LINK_LAYOUT_001] RISC-V boot wrapper is missing .data VA")?;
        phase12_riscv_qemu_entry_wrapper_bytes(
            32,
            wrapper_va,
            user_entry_va,
            data_va + boot_layout.boot_info_offset as u64,
            data_va + boot_layout.fdt_ptr_offset as u64,
            data_va
                + boot_layout
                    .hart_ptr_offset
                    .ok_or("[E_MACHINE_LINK_LAYOUT_001] RISC-V boot data has no hart slot")?
                    as u64,
            data_va + boot_layout.boot_stack_offset as u64 + boot_layout.boot_stack_size as u64,
        )?
    } else {
        phase12_elf32_entry_wrapper_bytes(arch, wrapper_va, user_entry_va)?
    };
    if bytes.len() != len {
        return Err("[E_MACHINE_LINK_LAYOUT_001] ELF32 entry wrapper size drifted".into());
    }
    text[offset..offset + len].copy_from_slice(&bytes);
    Ok(())
}

fn phase12_elf32_entry_wrapper_bytes(
    arch: &str,
    wrapper_va: u64,
    user_entry_va: u64,
) -> Result<Vec<u8>, Box<dyn Error>> {
    match arch {
        "i386" => {
            let mut bytes = vec![
                0x8b, 0x04, 0x24, // mov eax, [esp] (argc)
                0x8d, 0x5c, 0x24, 0x04, // lea ebx, [esp+4] (argv)
                0x8d, 0x4c, 0x83, 0x04, // lea ecx, [ebx+eax*4+4] (envp)
                0x51, // push ecx
                0x53, // push ebx
                0x50, // push eax
                0xe8, // call user entry
            ];
            phase12_push_i32_disp(&mut bytes, user_entry_va, wrapper_va + 19)?;
            bytes.extend_from_slice(&[
                0x83, 0xc4, 0x0c, // add esp, 12
                0x89, 0xc3, // mov ebx, eax (Linux exit status)
                0xb8, 0x01, 0x00, 0x00, 0x00, // mov eax, SYS_exit
                0xcd, 0x80, // int 0x80
                0x0f, 0x0b, // ud2 if the kernel unexpectedly returns
            ]);
            Ok(bytes)
        }
        other => Err(format!(
            "[E_MACHINE_LINK_TARGET_001] ELF32 entry wrapper is not implemented for {other}"
        )
        .into()),
    }
}

fn phase12_elf64_entry_wrapper_len(arch: &str, target: &str) -> Option<usize> {
    match (arch, target) {
        ("x86_64", target) if target.contains("linux") => Some(33),
        ("aarch64", "aarch64-unknown-none") => {
            phase12_aarch64_qemu_entry_wrapper_bytes(0, 0, 0, 0, 0)
                .ok()
                .map(|bytes| bytes.len())
        }
        ("riscv64", "riscv64-unknown-elf") => {
            phase12_riscv_qemu_entry_wrapper_bytes(64, 0, 0, 0, 0, 0, 0)
                .ok()
                .map(|bytes| bytes.len())
        }
        _ => None,
    }
}

fn phase12_elf64_materialize_entry_wrapper(
    text: &mut [u8],
    arch: &str,
    target: &str,
    layout: Option<(usize, usize)>,
    wrapper_va: u64,
    user_entry_va: u64,
    dynamic_targets: &HashMap<String, u64>,
    boot_layout: Option<Phase12FreestandingBootDataLayout>,
    data_va: Option<u64>,
) -> Result<(), Box<dyn Error>> {
    let Some((offset, len)) = layout else {
        return Ok(());
    };
    let bytes = if phase12_is_qemu_virt_freestanding(arch, target) {
        let boot_layout = boot_layout
            .ok_or("[E_MACHINE_LINK_LAYOUT_001] freestanding boot wrapper is missing boot data")?;
        let data_va = data_va
            .ok_or("[E_MACHINE_LINK_LAYOUT_001] freestanding boot wrapper is missing .data VA")?;
        match arch {
            "aarch64" => phase12_aarch64_qemu_entry_wrapper_bytes(
                wrapper_va,
                user_entry_va,
                data_va + boot_layout.boot_info_offset as u64,
                data_va + boot_layout.fdt_ptr_offset as u64,
                data_va + boot_layout.boot_stack_offset as u64 + boot_layout.boot_stack_size as u64,
            )?,
            "riscv64" => phase12_riscv_qemu_entry_wrapper_bytes(
                64,
                wrapper_va,
                user_entry_va,
                data_va + boot_layout.boot_info_offset as u64,
                data_va + boot_layout.fdt_ptr_offset as u64,
                data_va
                    + boot_layout
                        .hart_ptr_offset
                        .ok_or("[E_MACHINE_LINK_LAYOUT_001] RISC-V boot data has no hart slot")?
                        as u64,
                data_va + boot_layout.boot_stack_offset as u64 + boot_layout.boot_stack_size as u64,
            )?,
            _ => {
                return Err(format!(
                    "[E_MACHINE_LINK_TARGET_001] no ELF64 QEMU boot wrapper for {arch}"
                )
                .into())
            }
        }
    } else {
        phase12_elf64_entry_wrapper_bytes(arch, wrapper_va, user_entry_va, dynamic_targets)?
    };
    if bytes.len() != len {
        return Err("[E_MACHINE_LINK_LAYOUT_001] ELF entry wrapper size drifted".into());
    }
    text[offset..offset + len].copy_from_slice(&bytes);
    Ok(())
}

fn phase12_elf64_entry_wrapper_bytes(
    arch: &str,
    wrapper_va: u64,
    user_entry_va: u64,
    _dynamic_targets: &HashMap<String, u64>,
) -> Result<Vec<u8>, Box<dyn Error>> {
    match arch {
        "x86_64" => {
            let mut bytes = vec![
                0x48, 0x8b, 0x3c, 0x24, // mov rdi, [rsp] (argc)
                0x48, 0x8d, 0x74, 0x24, 0x08, // lea rsi, [rsp+8] (argv)
                0x48, 0x8d, 0x54, 0xfe, 0x08, // lea rdx, [rsi+rdi*8+8] (envp)
            ];
            phase12_pe_push_call_rel32(&mut bytes, wrapper_va, user_entry_va)?;
            bytes.extend_from_slice(&[
                0x48, 0x89, 0xc7, // mov rdi, rax
                0x48, 0xc7, 0xc0, 0x3c, 0x00, 0x00, 0x00, // mov rax, 60
                0x0f, 0x05, // syscall
                0x0f, 0x0b, // ud2 if the kernel unexpectedly returns
            ]);
            Ok(bytes)
        }
        other => Err(format!(
            "[E_MACHINE_LINK_TARGET_001] ELF entry wrapper is not implemented for {other}"
        )
        .into()),
    }
}

fn phase12_elf64_materialize_runtime_thunks(
    text: &mut [u8],
    layout: &Phase12Elf64RuntimeThunkLayout,
    spec: &Phase12ElfRuntimeThunks,
    text_va: u64,
    data_va: Option<u64>,
    read_line_buffer_offset: Option<usize>,
    dynamic_targets: &mut HashMap<String, u64>,
) -> Result<(), Box<dyn Error>> {
    if let Some((offset, len)) = layout.read_int {
        let thunk_va = text_va + offset as u64;
        let bytes = phase12_elf64_internal_read_int_thunk(thunk_va, dynamic_targets)?;
        if bytes.len() != len {
            return Err("[E_MACHINE_LINK_LAYOUT_001] ELF readInt thunk size drifted".into());
        }
        text[offset..offset + len].copy_from_slice(&bytes);
        dynamic_targets.insert("readInt".to_string(), thunk_va);
    }
    if let Some((offset, len)) = layout.read_line {
        let data_va = data_va.ok_or(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] ELF readLine thunk requires .data buffer",
        )?;
        let buffer_offset = read_line_buffer_offset.ok_or(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] ELF readLine thunk buffer was not reserved",
        )?;
        let thunk_va = text_va + offset as u64;
        let bytes = phase12_elf64_internal_read_line_thunk(
            thunk_va,
            dynamic_targets,
            data_va + buffer_offset as u64,
        )?;
        if bytes.len() != len {
            return Err("[E_MACHINE_LINK_LAYOUT_001] ELF readLine thunk size drifted".into());
        }
        text[offset..offset + len].copy_from_slice(&bytes);
        dynamic_targets.insert("readLine".to_string(), thunk_va);
    }
    if let Some((offset, len)) = layout.str_eq {
        let thunk_va = text_va + offset as u64;
        let bytes = phase12_elf64_internal_str_eq_thunk(thunk_va, dynamic_targets)?;
        if bytes.len() != len {
            return Err("[E_MACHINE_LINK_LAYOUT_001] ELF strEq thunk size drifted".into());
        }
        text[offset..offset + len].copy_from_slice(&bytes);
        dynamic_targets.insert("strEq".to_string(), thunk_va);
    }
    if let Some((offset, len)) = layout.sleep_ms {
        let thunk_va = text_va + offset as u64;
        let bytes = phase12_elf64_internal_sleep_ms_thunk(thunk_va, dynamic_targets)?;
        if bytes.len() != len {
            return Err("[E_MACHINE_LINK_LAYOUT_001] ELF sleepMs thunk size drifted".into());
        }
        text[offset..offset + len].copy_from_slice(&bytes);
        for symbol in &spec.sleep_symbols {
            dynamic_targets.insert(symbol.clone(), thunk_va);
        }
    }
    Ok(())
}

fn phase12_elf64_internal_read_int_thunk_len() -> usize {
    let mut targets = HashMap::new();
    targets.insert("getchar".to_string(), 0);
    phase12_elf64_internal_read_int_thunk(0, &targets)
        .map(|bytes| bytes.len())
        .unwrap_or(0)
}

fn phase12_elf64_internal_read_int_thunk(
    base_va: u64,
    dynamic_targets: &HashMap<String, u64>,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let getchar = *dynamic_targets
        .get("getchar")
        .ok_or("[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] ELF readInt thunk requires getchar")?;
    let mut bytes = vec![
        0x53, // push rbx
        0x41, 0x54, // push r12
        0x41, 0x55, // push r13
        0x31, 0xdb, // xor ebx, ebx
        0x41, 0xbc, 0x01, 0x00, 0x00, 0x00, // mov r12d, 1
        0x45, 0x31, 0xed, // xor r13d, r13d
    ];
    let loop_label = bytes.len();
    phase12_pe_push_call_rel32(&mut bytes, base_va, getchar)?;
    bytes.extend_from_slice(&[
        0x83, 0xf8, 0xff, // cmp eax, -1
        0x74, 0x00, // je done
    ]);
    let je_done_from_eof = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x3c, 0x2d, // cmp al, '-'
        0x75, 0x00, // jne digit_check
    ]);
    let jne_digit_check = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x41, 0x83, 0xfd, 0x00, // cmp r13d, 0
        0x75, 0x00, // jne done
    ]);
    let jne_done_from_minus = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x41, 0xbc, 0xff, 0xff, 0xff, 0xff, // mov r12d, -1
        0x41, 0xbd, 0x01, 0x00, 0x00, 0x00, // mov r13d, 1
        0xeb, 0x00, // jmp loop
    ]);
    let jmp_loop_after_minus = bytes.len() - 1;

    let digit_check = bytes.len();
    phase12_pe_patch_rel8(&mut bytes, jne_digit_check, digit_check)?;
    bytes.extend_from_slice(&[
        0x3c, 0x30, // cmp al, '0'
        0x72, 0x00, // jb separator
    ]);
    let jb_separator = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x3c, 0x39, // cmp al, '9'
        0x77, 0x00, // ja separator
    ]);
    let ja_separator = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x48, 0x6b, 0xdb, 0x0a, // imul rbx, rbx, 10
        0x83, 0xe8, 0x30, // sub eax, '0'
        0x48, 0x63, 0xc0, // movsxd rax, eax
        0x48, 0x01, 0xc3, // add rbx, rax
        0x41, 0xbd, 0x01, 0x00, 0x00, 0x00, // mov r13d, 1
        0xeb, 0x00, // jmp loop
    ]);
    let jmp_loop_after_digit = bytes.len() - 1;

    let separator = bytes.len();
    phase12_pe_patch_rel8(&mut bytes, jb_separator, separator)?;
    phase12_pe_patch_rel8(&mut bytes, ja_separator, separator)?;
    bytes.extend_from_slice(&[
        0x41, 0x83, 0xfd, 0x00, // cmp r13d, 0
        0x75, 0x00, // jne done
    ]);
    let jne_done_from_separator = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0xeb, 0x00, // jmp loop
    ]);
    let jmp_loop_after_separator = bytes.len() - 1;

    let done = bytes.len();
    phase12_pe_patch_rel8(&mut bytes, je_done_from_eof, done)?;
    phase12_pe_patch_rel8(&mut bytes, jne_done_from_minus, done)?;
    phase12_pe_patch_rel8(&mut bytes, jne_done_from_separator, done)?;
    bytes.extend_from_slice(&[
        0x48, 0x89, 0xd8, // mov rax, rbx
        0x41, 0x83, 0xfc, 0x01, // cmp r12d, 1
        0x74, 0x00, // je ret
    ]);
    let je_ret = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x48, 0xf7, 0xd8, // neg rax
    ]);
    let ret = bytes.len();
    phase12_pe_patch_rel8(&mut bytes, je_ret, ret)?;
    bytes.extend_from_slice(&[
        0x41, 0x5d, // pop r13
        0x41, 0x5c, // pop r12
        0x5b, // pop rbx
        0xc3, // ret
    ]);

    phase12_pe_patch_rel8(&mut bytes, jmp_loop_after_minus, loop_label)?;
    phase12_pe_patch_rel8(&mut bytes, jmp_loop_after_digit, loop_label)?;
    phase12_pe_patch_rel8(&mut bytes, jmp_loop_after_separator, loop_label)?;
    Ok(bytes)
}

fn phase12_elf64_internal_read_line_thunk_len() -> usize {
    let mut targets = HashMap::new();
    targets.insert("getchar".to_string(), 0);
    phase12_elf64_internal_read_line_thunk(0, &targets, 0)
        .map(|bytes| bytes.len())
        .unwrap_or(0)
}

fn phase12_elf64_internal_read_line_thunk(
    base_va: u64,
    dynamic_targets: &HashMap<String, u64>,
    buffer_va: u64,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let getchar = *dynamic_targets
        .get("getchar")
        .ok_or("[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] ELF readLine thunk requires getchar")?;
    let mut bytes = vec![
        0x53, // push rbx
        0x41, 0x54, // push r12
        0x41, 0x55, // push r13
        0x48, 0xbb, // movabs rbx, buffer
    ];
    bytes.extend_from_slice(&buffer_va.to_le_bytes());
    bytes.extend_from_slice(&[
        0x45, 0x31, 0xe4, // xor r12d, r12d
    ]);
    let loop_label = bytes.len();
    bytes.extend_from_slice(&[
        0x41, 0x81, 0xfc, 0xff, 0x0f, 0x00, 0x00, // cmp r12d, 4095
        0x73, 0x00, // jae terminate
    ]);
    let jae_terminate = bytes.len() - 1;
    phase12_pe_push_call_rel32(&mut bytes, base_va, getchar)?;
    bytes.extend_from_slice(&[
        0x83, 0xf8, 0xff, // cmp eax, -1
        0x74, 0x00, // je terminate
    ]);
    let je_terminate_eof = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x3c, 0x0d, // cmp al, '\r'
        0x74, 0x00, // je terminate
    ]);
    let je_terminate_cr = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x3c, 0x0a, // cmp al, '\n'
        0x74, 0x00, // je terminate
    ]);
    let je_terminate_lf = bytes.len() - 1;
    bytes.extend_from_slice(&[
        0x42, 0x88, 0x04, 0x23, // mov byte ptr [rbx + r12], al
        0x41, 0xff, 0xc4, // inc r12d
        0xeb, 0x00, // jmp loop
    ]);
    let jmp_loop = bytes.len() - 1;

    let terminate = bytes.len();
    phase12_pe_patch_rel8(&mut bytes, jae_terminate, terminate)?;
    phase12_pe_patch_rel8(&mut bytes, je_terminate_eof, terminate)?;
    phase12_pe_patch_rel8(&mut bytes, je_terminate_cr, terminate)?;
    phase12_pe_patch_rel8(&mut bytes, je_terminate_lf, terminate)?;
    phase12_pe_patch_rel8(&mut bytes, jmp_loop, loop_label)?;
    bytes.extend_from_slice(&[
        0x42, 0xc6, 0x04, 0x23, 0x00, // mov byte ptr [rbx + r12], 0
        0x48, 0x89, 0xd8, // mov rax, rbx
        0x41, 0x5d, // pop r13
        0x41, 0x5c, // pop r12
        0x5b, // pop rbx
        0xc3, // ret
    ]);
    Ok(bytes)
}

fn phase12_elf64_internal_str_eq_thunk_len() -> usize {
    let mut targets = HashMap::new();
    targets.insert("strcmp".to_string(), 0);
    phase12_elf64_internal_str_eq_thunk(0, &targets)
        .map(|bytes| bytes.len())
        .unwrap_or(0)
}

fn phase12_elf64_internal_str_eq_thunk(
    base_va: u64,
    dynamic_targets: &HashMap<String, u64>,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let strcmp = *dynamic_targets
        .get("strcmp")
        .ok_or("[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] ELF strEq thunk requires strcmp")?;
    let mut bytes = vec![
        0x48, 0x83, 0xec, 0x08, // sub rsp, 8
    ];
    phase12_pe_push_call_rel32(&mut bytes, base_va, strcmp)?;
    bytes.extend_from_slice(&[
        0x48, 0x83, 0xc4, 0x08, // add rsp, 8
        0x85, 0xc0, // test eax, eax
        0x0f, 0x94, 0xc0, // sete al
        0x0f, 0xb6, 0xc0, // movzx eax, al
        0xc3, // ret
    ]);
    Ok(bytes)
}

fn phase12_elf64_internal_sleep_ms_thunk_len() -> usize {
    let mut targets = HashMap::new();
    targets.insert("usleep".to_string(), 0);
    phase12_elf64_internal_sleep_ms_thunk(0, &targets)
        .map(|bytes| bytes.len())
        .unwrap_or(0)
}

fn phase12_elf64_internal_sleep_ms_thunk(
    base_va: u64,
    dynamic_targets: &HashMap<String, u64>,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let usleep = *dynamic_targets
        .get("usleep")
        .ok_or("[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] ELF sleepMs thunk requires usleep")?;
    let mut bytes = vec![
        0x48, 0x83, 0xec, 0x08, // sub rsp, 8
        0x48, 0x69, 0xff, 0xe8, 0x03, 0x00, 0x00, // imul rdi, rdi, 1000
    ];
    phase12_pe_push_call_rel32(&mut bytes, base_va, usleep)?;
    bytes.extend_from_slice(&[
        0xb8, 0x01, 0x00, 0x00, 0x00, // mov eax, 1
        0x48, 0x83, 0xc4, 0x08, // add rsp, 8
        0xc3, // ret
    ]);
    Ok(bytes)
}

#[allow(clippy::too_many_arguments)]
fn phase12_write_elf32_phdr(
    out: &mut [u8],
    offset: usize,
    p_type: u32,
    file_offset: u32,
    vaddr: u32,
    filesz: u32,
    memsz: u32,
    flags: u32,
    align: u32,
) {
    write_u32(out, offset, p_type);
    write_u32(out, offset + 4, file_offset);
    write_u32(out, offset + 8, vaddr);
    write_u32(out, offset + 12, vaddr);
    write_u32(out, offset + 16, filesz);
    write_u32(out, offset + 20, memsz);
    write_u32(out, offset + 24, flags);
    write_u32(out, offset + 28, align);
}

fn phase12_write_elf64_phdr(
    out: &mut [u8],
    offset: usize,
    p_type: u32,
    flags: u32,
    file_offset: u64,
    vaddr: u64,
    filesz: u64,
    memsz: u64,
    align: u64,
) {
    write_u32(out, offset, p_type);
    write_u32(out, offset + 4, flags);
    write_u64(out, offset + 8, file_offset);
    write_u64(out, offset + 16, vaddr);
    write_u64(out, offset + 24, vaddr);
    write_u64(out, offset + 32, filesz);
    write_u64(out, offset + 40, memsz);
    write_u64(out, offset + 48, align);
}

fn phase12_elf_hash_bytes(imports: &[String]) -> Vec<u8> {
    let nbucket = imports.len().max(1) as u32;
    let nchain = (imports.len() + 1) as u32;
    let mut buckets = vec![0_u32; nbucket as usize];
    let mut chains = vec![0_u32; nchain as usize];
    for (index, symbol) in imports.iter().enumerate() {
        let sym_index = (index + 1) as u32;
        let bucket = (phase12_elf_hash(symbol) % nbucket) as usize;
        if buckets[bucket] == 0 {
            buckets[bucket] = sym_index;
        } else {
            let mut cursor = buckets[bucket] as usize;
            while chains[cursor] != 0 {
                cursor = chains[cursor] as usize;
            }
            chains[cursor] = sym_index;
        }
    }
    let mut out = Vec::new();
    out.extend_from_slice(&nbucket.to_le_bytes());
    out.extend_from_slice(&nchain.to_le_bytes());
    for bucket in buckets {
        out.extend_from_slice(&bucket.to_le_bytes());
    }
    for chain in chains {
        out.extend_from_slice(&chain.to_le_bytes());
    }
    out
}

fn phase12_elf_hash(symbol: &str) -> u32 {
    let mut h = 0_u32;
    for byte in symbol.bytes() {
        h = (h << 4).wrapping_add(byte as u32);
        let g = h & 0xf0000000;
        if g != 0 {
            h ^= g >> 24;
        }
        h &= !g;
    }
    h
}

fn phase12_elf64_dynamic_imports_supported(arch: &str, target: &str) -> bool {
    match arch {
        "x86_64" => target.contains("linux") || target.contains("gnu"),
        "aarch64" | "riscv64" => target.contains("linux") && target.contains("gnu"),
        _ => false,
    }
}

fn phase12_elf64_interpreter_bytes(arch: &str) -> Vec<u8> {
    match arch {
        "aarch64" => b"/lib/ld-linux-aarch64.so.1\0".to_vec(),
        "riscv64" => b"/lib/ld-linux-riscv64-lp64d.so.1\0".to_vec(),
        _ => b"/lib64/ld-linux-x86-64.so.2\0".to_vec(),
    }
}

fn phase12_elf64_plt_len(arch: &str, count: usize) -> usize {
    match arch {
        "aarch64" | "riscv64" => count * 16,
        _ => 16 + count * 16,
    }
}

fn phase12_elf64_got_plt_len(count: usize) -> usize {
    24 + count * 8
}

fn phase12_elf64_dynamic_entry_count(arch: &str) -> usize {
    if matches!(arch, "aarch64" | "riscv64") {
        16
    } else {
        11
    }
}

fn phase12_elf64_plt_entry_va(arch: &str, plt_va: u64, index: usize) -> u64 {
    match arch {
        "aarch64" | "riscv64" => plt_va + index as u64 * 16,
        _ => plt_va + 16 + index as u64 * 16,
    }
}

fn phase12_elf64_rela_plt_bytes(imports: &[String], got_va: u64, target: &str) -> Vec<u8> {
    let reloc_type = phase12_elf_jump_slot_reloc_type(target);
    let mut out = Vec::new();
    for (index, _) in imports.iter().enumerate() {
        let offset = got_va + 24 + (index as u64 * 8);
        let info = (((index + 1) as u64) << 32) | reloc_type;
        out.extend_from_slice(&offset.to_le_bytes());
        out.extend_from_slice(&info.to_le_bytes());
        out.extend_from_slice(&0_i64.to_le_bytes());
    }
    out
}

fn phase12_elf64_dynamic_entries_for_arch(
    arch: &str,
    dynstr: &[u8],
    dynstr_va: u64,
    dynsym_va: u64,
    hash_va: u64,
    rela_va: u64,
    got_va: u64,
    rela_len: usize,
) -> Vec<(&'static str, u64)> {
    let needed = phase12_cstr_offset(dynstr, "libc.so.6").unwrap_or(1) as u64;
    let mut entries = vec![
        ("DT_NEEDED", needed),
        ("DT_HASH", hash_va),
        ("DT_STRTAB", dynstr_va),
        ("DT_SYMTAB", dynsym_va),
        ("DT_STRSZ", dynstr.len() as u64),
        ("DT_SYMENT", 24),
        ("DT_PLTGOT", got_va),
        ("DT_PLTRELSZ", rela_len as u64),
        ("DT_PLTREL", 7),
        ("DT_JMPREL", rela_va),
    ];
    if matches!(arch, "aarch64" | "riscv64") {
        entries.extend([
            ("DT_RELA", rela_va),
            ("DT_RELASZ", rela_len as u64),
            ("DT_RELAENT", 24),
            ("DT_BIND_NOW", 0),
            ("DT_FLAGS", 8),
        ]);
    }
    entries.push(("DT_NULL", 0));
    entries
}

fn phase12_elf64_got_plt_bytes(count: usize, dynamic_va: u64, plt_va: u64) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(&dynamic_va.to_le_bytes());
    out.extend_from_slice(&0_u64.to_le_bytes());
    out.extend_from_slice(&0_u64.to_le_bytes());
    for index in 0..count {
        out.extend_from_slice(&(plt_va + 16 + (index as u64 * 16) + 6).to_le_bytes());
    }
    out
}

fn phase12_elf64_got_plt_bytes_for_arch(
    arch: &str,
    count: usize,
    dynamic_va: u64,
    plt_va: u64,
) -> Result<Vec<u8>, Box<dyn Error>> {
    if arch == "x86_64" {
        return Ok(phase12_elf64_got_plt_bytes(count, dynamic_va, plt_va));
    }
    let mut out = Vec::new();
    out.extend_from_slice(&dynamic_va.to_le_bytes());
    out.extend_from_slice(&0_u64.to_le_bytes());
    out.extend_from_slice(&0_u64.to_le_bytes());
    for _ in 0..count {
        out.extend_from_slice(&0_u64.to_le_bytes());
    }
    Ok(out)
}

fn phase12_elf64_plt_bytes(
    count: usize,
    plt_va: u64,
    got_va: u64,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let mut out = Vec::new();
    out.extend_from_slice(&[0xff, 0x35]);
    phase12_push_i32_disp(&mut out, got_va + 8, plt_va + 6)?;
    out.extend_from_slice(&[0xff, 0x25]);
    phase12_push_i32_disp(&mut out, got_va + 16, plt_va + 12)?;
    out.extend_from_slice(&[0x0f, 0x1f, 0x40, 0x00]);
    for index in 0..count {
        let entry_va = plt_va + 16 + index as u64 * 16;
        let got_slot = got_va + 24 + index as u64 * 8;
        out.extend_from_slice(&[0xff, 0x25]);
        phase12_push_i32_disp(&mut out, got_slot, entry_va + 6)?;
        out.push(0x68);
        out.extend_from_slice(&(index as u32).to_le_bytes());
        out.push(0xe9);
        phase12_push_i32_disp(&mut out, plt_va, entry_va + 16)?;
    }
    Ok(out)
}

fn phase12_elf64_plt_bytes_for_arch(
    arch: &str,
    count: usize,
    plt_va: u64,
    got_va: u64,
) -> Result<Vec<u8>, Box<dyn Error>> {
    match arch {
        "aarch64" => phase12_elf64_aarch64_plt_bytes(count, plt_va, got_va),
        "riscv64" => phase12_elf64_riscv64_plt_bytes(count, plt_va, got_va),
        _ => phase12_elf64_plt_bytes(count, plt_va, got_va),
    }
}

fn phase12_elf64_aarch64_plt_bytes(
    count: usize,
    plt_va: u64,
    got_va: u64,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let mut out = Vec::new();
    for index in 0..count {
        let entry_va = plt_va + index as u64 * 16;
        let got_slot = got_va + 24 + index as u64 * 8;
        let words = [
            phase12_aarch64_adrp_word(16, got_slot, entry_va)?,
            phase12_aarch64_ldr64_unsigned_word(17, 16, got_slot)?,
            phase12_aarch64_add_imm_word(16, 16, got_slot)?,
            0xd61f0000 | (17 << 5),
        ];
        for word in words {
            out.extend_from_slice(&word.to_le_bytes());
        }
    }
    Ok(out)
}

fn phase12_aarch64_adrp_word(rd: u32, target: u64, place: u64) -> Result<u32, Box<dyn Error>> {
    let target_page = (target as i128) >> 12;
    let place_page = (place >> 12) as i128;
    let imm = target_page - place_page;
    if !(-(1_i128 << 20)..(1_i128 << 20)).contains(&imm) {
        return Err(
            "[E_MACHINE_LINK_PCREL_RANGE_001] AArch64 PLT ADRP page delta does not fit".into(),
        );
    }
    let imm_u = imm as i64 as u32;
    let immlo = imm_u & 0x3;
    let immhi = (imm_u >> 2) & 0x7ffff;
    Ok(0x90000000 | (immlo << 29) | (immhi << 5) | rd)
}

fn phase12_aarch64_ldr64_unsigned_word(
    rt: u32,
    rn: u32,
    target: u64,
) -> Result<u32, Box<dyn Error>> {
    let lo12 = target & 0xfff;
    if lo12 % 8 != 0 {
        return Err(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] AArch64 PLT GOT slot is not 8-byte aligned"
                .into(),
        );
    }
    Ok(0xf9400000 | (((lo12 / 8) as u32) << 10) | (rn << 5) | rt)
}

fn phase12_aarch64_add_imm_word(rd: u32, rn: u32, target: u64) -> Result<u32, Box<dyn Error>> {
    let lo12 = (target & 0xfff) as u32;
    Ok(0x91000000 | (lo12 << 10) | (rn << 5) | rd)
}

fn phase12_elf64_riscv64_plt_bytes(
    count: usize,
    plt_va: u64,
    got_va: u64,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let mut out = Vec::new();
    for index in 0..count {
        let entry_va = plt_va + index as u64 * 16;
        let got_slot = got_va + 24 + index as u64 * 8;
        let delta = got_slot as i128 - entry_va as i128;
        let hi = phase12_riscv_hi20(delta)?;
        let lo = delta - (hi << 12);
        let words = [
            phase12_riscv_u_word(0x17, 28, hi)?,
            phase12_riscv_i_word(0x03, 3, 28, 28, lo)?,
            phase12_riscv_i_word(0x67, 0, 0, 28, 0)?,
            0x00000013,
        ];
        for word in words {
            out.extend_from_slice(&word.to_le_bytes());
        }
    }
    Ok(out)
}

fn phase12_riscv_u_word(opcode: u32, rd: u32, imm20: i128) -> Result<u32, Box<dyn Error>> {
    if !(-(1_i128 << 19)..(1_i128 << 20)).contains(&imm20) {
        return Err("[E_MACHINE_LINK_PCREL_RANGE_001] RISC-V PLT hi20 does not fit".into());
    }
    Ok((((imm20 as i64 as u32) & 0x000f_ffff) << 12) | (rd << 7) | opcode)
}

fn phase12_riscv_i_word(
    opcode: u32,
    funct3: u32,
    rd: u32,
    rs1: u32,
    imm: i128,
) -> Result<u32, Box<dyn Error>> {
    if !(-2048..=2047).contains(&imm) {
        return Err("[E_MACHINE_LINK_PCREL_RANGE_001] RISC-V PLT lo12 does not fit".into());
    }
    Ok((((imm as i64 as u32) & 0xfff) << 20) | (rs1 << 15) | (funct3 << 12) | (rd << 7) | opcode)
}

fn phase12_push_i32_disp(
    out: &mut Vec<u8>,
    target: u64,
    next_ip: u64,
) -> Result<(), Box<dyn Error>> {
    let disp = target as i128 - next_ip as i128;
    if disp < i32::MIN as i128 || disp > i32::MAX as i128 {
        return Err("[E_MACHINE_LINK_PCREL_RANGE_001] displacement does not fit i32".into());
    }
    out.extend_from_slice(&(disp as i32).to_le_bytes());
    Ok(())
}

fn phase12_linked_symbol_vas(
    image: &Phase12LinkedImage,
    text_va: u64,
    rodata_va: Option<u64>,
    data_va: Option<u64>,
    bss_va: Option<u64>,
    section_vas: &BTreeMap<String, u64>,
) -> BTreeMap<String, u64> {
    let fallback_bss_va = data_va
        .map(|addr| addr + image.data.len() as u64)
        .or_else(|| rodata_va.map(|addr| addr + image.rodata.len() as u64))
        .unwrap_or(text_va + image.text.len() as u64);
    let mut out = BTreeMap::new();
    for (name, symbol) in &image.symbols {
        let base = match symbol.section.as_str() {
            "rodata" => rodata_va.unwrap_or(text_va + image.text.len() as u64),
            "data" => data_va.unwrap_or(text_va + image.text.len() as u64),
            "bss" => bss_va.unwrap_or(fallback_bss_va),
            other => section_vas.get(other).copied().unwrap_or(text_va),
        };
        out.insert(name.clone(), base + symbol.offset as u64);
    }
    out
}

fn phase12_got_relocation_symbols(image: &Phase12LinkedImage) -> Vec<String> {
    let mut symbols = BTreeSet::new();
    for rel in &image.relocations {
        if phase12_relocation_uses_got(&rel.kind) {
            symbols.insert(rel.symbol.clone());
        }
    }
    symbols.into_iter().collect()
}

fn phase12_relocation_needs_got_base(kind: &str) -> bool {
    phase12_relocation_uses_got(kind) || matches!(kind, "i386-gotpc32" | "i386-gotoff32")
}

fn phase12_relocation_uses_got(kind: &str) -> bool {
    matches!(
        kind,
        "got32"
            | "got-pcrel32"
            | "aarch64-adr-got-page"
            | "aarch64-ld64-got-lo12-nc"
            | "riscv-got-hi20"
    )
}

fn phase12_got_target_vas(symbols: &[String], got_va: Option<u64>) -> HashMap<String, u64> {
    let Some(base) = got_va else {
        return HashMap::new();
    };
    symbols
        .iter()
        .enumerate()
        .map(|(index, symbol)| (symbol.clone(), base + index as u64 * 8))
        .collect()
}

fn phase12_elf32_got_target_vas(symbols: &[String], got_va: Option<u64>) -> HashMap<String, u64> {
    let Some(base) = got_va else {
        return HashMap::new();
    };
    symbols
        .iter()
        .enumerate()
        .map(|(index, symbol)| (symbol.clone(), base + index as u64 * 4))
        .collect()
}

fn phase12_elf_got_bytes(
    symbols: &[String],
    symbol_vas: &BTreeMap<String, u64>,
    dynamic_targets: &HashMap<String, u64>,
    null_symbols: &BTreeSet<String>,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let mut out = Vec::with_capacity(symbols.len() * 8);
    for symbol in symbols {
        let value = symbol_vas
            .get(symbol)
            .copied()
            .or_else(|| dynamic_targets.get(symbol).copied())
            .or_else(|| null_symbols.contains(symbol).then_some(0))
            .ok_or_else(|| {
                format!(
                    "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] GOT relocation target '{}' is unresolved",
                    symbol
                )
            })?;
        out.extend_from_slice(&value.to_le_bytes());
    }
    Ok(out)
}

fn phase12_elf32_got_bytes(
    symbols: &[String],
    symbol_vas: &BTreeMap<String, u64>,
    dynamic_targets: &HashMap<String, u64>,
    null_symbols: &BTreeSet<String>,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let mut out = Vec::with_capacity(symbols.len() * 4);
    if symbols.is_empty() {
        out.extend_from_slice(&0_u32.to_le_bytes());
    }
    for symbol in symbols {
        let value = symbol_vas
            .get(symbol)
            .copied()
            .or_else(|| dynamic_targets.get(symbol).copied())
            .or_else(|| null_symbols.contains(symbol).then_some(0))
            .ok_or_else(|| {
                format!(
                    "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] ELF32 GOT relocation target '{}' is unresolved",
                    symbol
                )
            })?;
        if value > u32::MAX as u64 {
            return Err(
                "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] ELF32 GOT entry exceeds u32".into(),
            );
        }
        out.extend_from_slice(&(value as u32).to_le_bytes());
    }
    Ok(out)
}

fn phase12_apply_pe_preserved_relocations(
    sections: &mut BTreeMap<String, Vec<u8>>,
    section_vas: &BTreeMap<String, u64>,
    section_indices: &BTreeMap<String, u16>,
    image: &Phase12LinkedImage,
    image_base: u64,
    symbol_vas: &BTreeMap<String, u64>,
) -> Result<(), Box<dyn Error>> {
    for rel in &image.relocations {
        let Some(bytes) = sections.get_mut(&rel.section) else {
            continue;
        };
        if rel.kind == "none" {
            continue;
        }
        let symbol = image.symbols.get(&rel.symbol).ok_or_else(|| {
            format!(
                "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] preserved COFF relocation target '{}' is unresolved",
                rel.symbol
            )
        })?;
        let target = symbol_vas.get(&rel.symbol).copied().ok_or_else(|| {
            format!(
                "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] preserved COFF relocation target '{}' has no VA",
                rel.symbol
            )
        })?;
        match rel.kind.as_str() {
            "abs64" => {
                if rel.offset + 8 > bytes.len() {
                    return Err(
                        "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] preserved COFF abs64 relocation overflows"
                            .into(),
                    );
                }
                let value = target as i128 + rel.addend as i128;
                if value < 0 || value > u64::MAX as i128 {
                    return Err(
                        "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] preserved COFF abs64 value overflows"
                            .into(),
                    );
                }
                bytes[rel.offset..rel.offset + 8]
                    .copy_from_slice(&(value as u64).to_le_bytes());
            }
            "coff-addr32" => {
                if rel.offset + 4 > bytes.len() {
                    return Err(
                        "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] COFF ADDR32 relocation overflows"
                            .into(),
                    );
                }
                let value = phase12_coff_addr32_value(target, rel.addend)?;
                bytes[rel.offset..rel.offset + 4].copy_from_slice(&value.to_le_bytes());
            }
            "call-near32" | "pc32" => {
                if rel.offset + 4 > bytes.len() {
                    return Err(
                        "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] preserved COFF pc32 relocation overflows"
                            .into(),
                    );
                }
                let place = section_vas
                    .get(&rel.section)
                    .copied()
                    .ok_or("[E_MACHINE_LINK_RELOCATION_TARGET_001] preserved COFF section has no VA")?
                    + rel.offset as u64;
                let value = target as i128 + rel.addend as i128 - place as i128;
                if value < i32::MIN as i128 || value > i32::MAX as i128 {
                    return Err(
                        "[E_MACHINE_LINK_PCREL_RANGE_001] preserved COFF pc32 value overflows"
                            .into(),
                    );
                }
                bytes[rel.offset..rel.offset + 4]
                    .copy_from_slice(&(value as i32).to_le_bytes());
            }
            "coff-addr32nb" => {
                if rel.offset + 4 > bytes.len() {
                    return Err(
                        "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] COFF ADDR32NB relocation overflows"
                            .into(),
                    );
                }
                let value = target as i128 + rel.addend as i128 - image_base as i128;
                if value < 0 || value > u32::MAX as i128 {
                    return Err(
                        "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] COFF ADDR32NB value overflows"
                            .into(),
                    );
                }
                bytes[rel.offset..rel.offset + 4]
                    .copy_from_slice(&(value as u32).to_le_bytes());
            }
            "coff-secrel32" => {
                if rel.offset + 4 > bytes.len() {
                    return Err(
                        "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] COFF SECREL relocation overflows"
                            .into(),
                    );
                }
                let value = symbol.offset as i128 + rel.addend as i128;
                if value < 0 || value > u32::MAX as i128 {
                    return Err(
                        "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] COFF SECREL value overflows"
                            .into(),
                    );
                }
                bytes[rel.offset..rel.offset + 4]
                    .copy_from_slice(&(value as u32).to_le_bytes());
            }
            "coff-section" => {
                if rel.offset + 2 > bytes.len() {
                    return Err(
                        "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] COFF SECTION relocation overflows"
                            .into(),
                    );
                }
                let index = section_indices.get(&symbol.section).copied().ok_or_else(|| {
                    format!(
                        "[E_MACHINE_LINK_RELOCATION_TARGET_001] COFF SECTION target '{}' has no output section index",
                        symbol.section
                    )
                })?;
                let value = index as i128 + rel.addend as i128;
                if value < 0 || value > u16::MAX as i128 {
                    return Err(
                        "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] COFF SECTION value overflows"
                            .into(),
                    );
                }
                bytes[rel.offset..rel.offset + 2]
                    .copy_from_slice(&(value as u16).to_le_bytes());
            }
            other => {
                return Err(format!(
                    "[E_MACHINE_LINK_RELOCATION_UNSUPPORTED_001] preserved COFF relocation kind '{other}' is unsupported"
                )
                .into())
            }
        }
    }
    Ok(())
}

fn phase12_apply_linked_relocations(
    text: &mut [u8],
    rodata: &mut [u8],
    data: &mut [u8],
    image: &Phase12LinkedImage,
    text_va: u64,
    rodata_va: Option<u64>,
    data_va: Option<u64>,
    bss_va: Option<u64>,
    symbol_vas: &BTreeMap<String, u64>,
    dynamic_targets: &HashMap<String, u64>,
    got_targets: &HashMap<String, u64>,
) -> Result<(), Box<dyn Error>> {
    let riscv_pcrel_hi = phase12_riscv_pcrel_hi_values(
        image,
        text_va,
        rodata_va,
        data_va,
        bss_va,
        symbol_vas,
        dynamic_targets,
        got_targets,
    )?;
    for rel in &image.relocations {
        if rel.kind == "none" {
            continue;
        }
        if !matches!(rel.section.as_str(), "text" | "rodata" | "data" | "bss") {
            continue;
        }
        let target = symbol_vas
            .get(&rel.symbol)
            .copied()
            .or_else(|| dynamic_targets.get(&rel.symbol).copied())
            .or_else(|| got_targets.get(&rel.symbol).copied())
            .or_else(|| image.null_symbols.contains(&rel.symbol).then_some(0))
            .ok_or_else(|| {
                format!(
                    "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] unresolved symbol '{}'",
                    rel.symbol
                )
            })?;
        match rel.kind.as_str() {
            "call-near32" | "jump-near32" => {
                match image.arch.as_str() {
                    "aarch64" => phase12_apply_aarch64_branch26(text, rel, target, text_va)?,
                    "armv7" | "armv7em" => {
                        phase12_apply_arm_thumb_relocation(text, rel, target, text_va, true)?
                    }
                    "riscv64" | "riscv32" => {
                        phase12_apply_riscv_call_pair(text, rel, target, text_va)?
                    }
                    _ => phase12_apply_pc32(
                        text, rodata, data, rel, target, text_va, rodata_va, data_va, bss_va,
                    )?,
                }
            }
            "pc32" | "got-pcrel32" => {
                let pc_target = if rel.kind == "got-pcrel32" {
                    *got_targets.get(&rel.symbol).ok_or_else(|| {
                        format!(
                            "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] missing GOT slot for '{}'",
                            rel.symbol
                        )
                    })?
                } else {
                    target
                };
                phase12_apply_pc32(
                    text, rodata, data, rel, pc_target, text_va, rodata_va, data_va, bss_va,
                )?;
            }
            "abs64" => {
                let value = target as i128 + rel.addend as i128;
                if value < 0 || value > u64::MAX as i128 {
                    return Err(
                        "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] abs64 relocation overflows"
                            .into(),
                    );
                }
                match rel.section.as_str() {
                    "text" => {
                        if rel.offset + 8 > text.len() {
                            return Err(
                                "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] abs64 relocation exceeds .text"
                                    .into(),
                            );
                        }
                        text[rel.offset..rel.offset + 8]
                            .copy_from_slice(&(value as u64).to_le_bytes());
                    }
                    "rodata" => {
                        let Some(_) = rodata_va else {
                            return Err(
                                "[E_MACHINE_LINK_RELOCATION_TARGET_001] .rodata relocation has no rodata segment"
                                    .into(),
                            );
                        };
                        if rel.offset + 8 > rodata.len() {
                            return Err(
                                "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] abs64 relocation exceeds .rodata"
                                    .into(),
                            );
                        }
                        rodata[rel.offset..rel.offset + 8]
                            .copy_from_slice(&(value as u64).to_le_bytes());
                    }
                    "data" => {
                        let Some(_) = data_va else {
                            return Err(
                                "[E_MACHINE_LINK_RELOCATION_TARGET_001] .data relocation has no data segment"
                                    .into(),
                            );
                        };
                        if rel.offset + 8 > data.len() {
                            return Err(
                                "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] abs64 relocation exceeds .data"
                                    .into(),
                            );
                        }
                        data[rel.offset..rel.offset + 8]
                            .copy_from_slice(&(value as u64).to_le_bytes());
                    }
                    other => {
                        return Err(format!(
                            "[E_MACHINE_LINK_RELOCATION_TARGET_001] abs64 relocation section '{other}' is unsupported in executable writer"
                        )
                        .into())
                    }
                }
            }
            "abs32" | "abs32s" => {
                phase12_apply_abs32(text, rodata, data, rel, target)?;
            }
            "coff-addr32" => {
                let value = phase12_coff_addr32_value(target, rel.addend)?;
                phase12_write_reloc_u32(text, rodata, data, rel, value)?;
            }
            "got32" => {
                let got = *got_targets.get(&rel.symbol).ok_or_else(|| {
                    format!(
                        "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] missing GOT32 slot for '{}'",
                        rel.symbol
                    )
                })?;
                phase12_apply_abs32(text, rodata, data, rel, got)?;
            }
            "i386-gotpc32" => {
                let got = phase12_i386_got_base(got_targets)?;
                phase12_apply_pc32(
                    text, rodata, data, rel, got, text_va, rodata_va, data_va, bss_va,
                )?;
            }
            "i386-gotoff32" => {
                let got = phase12_i386_got_base(got_targets)?;
                phase12_apply_i386_gotoff32(text, rodata, data, rel, target, got)?;
            }
            "aarch64-call26" | "aarch64-jump26" => {
                phase12_apply_aarch64_branch26(text, rel, target, text_va)?;
            }
            "aarch64-adr-prel-pg-hi21" => {
                phase12_apply_aarch64_adrp(text, rel, target, text_va)?;
            }
            "aarch64-add-abs-lo12-nc" => {
                phase12_apply_aarch64_add_lo12(text, rel, target)?;
            }
            "aarch64-pageoff12" => {
                phase12_apply_aarch64_pageoff12(text, rel, target)?;
            }
            "aarch64-ldst8-abs-lo12-nc" => {
                phase12_apply_aarch64_ldst_lo12(text, rel, target, 1)?;
            }
            "aarch64-ldst16-abs-lo12-nc" => {
                phase12_apply_aarch64_ldst_lo12(text, rel, target, 2)?;
            }
            "aarch64-ldst32-abs-lo12-nc" => {
                phase12_apply_aarch64_ldst_lo12(text, rel, target, 4)?;
            }
            "aarch64-ldst64-abs-lo12-nc" => {
                phase12_apply_aarch64_ldst_lo12(text, rel, target, 8)?;
            }
            "aarch64-ldst128-abs-lo12-nc" => {
                phase12_apply_aarch64_ldst_lo12(text, rel, target, 16)?;
            }
            "aarch64-adr-got-page" => {
                let got = *got_targets.get(&rel.symbol).ok_or_else(|| {
                    format!(
                        "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] missing AArch64 GOT slot for '{}'",
                        rel.symbol
                    )
                })?;
                phase12_apply_aarch64_adrp(text, rel, got, text_va)?;
            }
            "aarch64-ld64-got-lo12-nc" => {
                let got = *got_targets.get(&rel.symbol).ok_or_else(|| {
                    format!(
                        "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] missing AArch64 GOT slot for '{}'",
                        rel.symbol
                    )
                })?;
                phase12_apply_aarch64_ldst_lo12(text, rel, got, 8)?;
            }
            "arm-thm-call" => {
                phase12_apply_arm_thumb_relocation(text, rel, target, text_va, true)?;
            }
            "arm-thm-jump24" => {
                phase12_apply_arm_thumb_relocation(text, rel, target, text_va, false)?;
            }
            "arm-movw-abs-nc" | "arm-movt-abs" => {
                phase12_apply_arm_mov_relocation(text, rel, target, text_va)?;
            }
            "arm-prel31" => {
                let place =
                    phase12_relocation_place_va(rel, text_va, rodata_va, data_va, bss_va)?;
                let value = (target as i128 + rel.addend as i128 - place as i128)
                    & 0x7fff_ffff;
                phase12_write_reloc_u32(text, rodata, data, rel, value as u32)?;
            }
            "riscv-jal" => {
                phase12_apply_riscv_jal(text, rel, target, text_va)?;
            }
            "riscv-branch" => {
                phase12_apply_riscv_branch(text, rel, target, text_va)?;
            }
            "riscv-rvc-branch" => {
                phase12_apply_riscv_rvc_branch(text, rel, target, text_va)?;
            }
            "riscv-rvc-jump" => {
                phase12_apply_riscv_rvc_jump(text, rel, target, text_va)?;
            }
            "riscv-call" | "riscv-call-plt" => {
                phase12_apply_riscv_call_pair(text, rel, target, text_va)?;
            }
            "riscv-hi20" => {
                phase12_apply_riscv_u_type(text, rel, phase12_riscv_hi20(target as i128 + rel.addend as i128)?)?;
            }
            "riscv-lo12-i" => {
                phase12_apply_riscv_i_lo12(text, rel, target as i128 + rel.addend as i128)?;
            }
            "riscv-lo12-s" => {
                phase12_apply_riscv_s_lo12(text, rel, target as i128 + rel.addend as i128)?;
            }
            "riscv-pcrel-hi20" => {
                let place = phase12_relocation_place_va(rel, text_va, rodata_va, data_va, bss_va)?;
                phase12_apply_riscv_u_type(
                    text,
                    rel,
                    phase12_riscv_hi20(target as i128 + rel.addend as i128 - place as i128)?,
                )?;
            }
            "riscv-pcrel-lo12-i" => {
                let value = phase12_riscv_pcrel_lo_value(rel, symbol_vas, &riscv_pcrel_hi)?;
                phase12_apply_riscv_i_lo12(text, rel, value)?;
            }
            "riscv-pcrel-lo12-s" => {
                let value = phase12_riscv_pcrel_lo_value(rel, symbol_vas, &riscv_pcrel_hi)?;
                phase12_apply_riscv_s_lo12(text, rel, value)?;
            }
            "riscv-got-hi20" => {
                let got = *got_targets.get(&rel.symbol).ok_or_else(|| {
                    format!(
                        "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] missing RISC-V GOT slot for '{}'",
                        rel.symbol
                    )
                })?;
                let place = phase12_relocation_place_va(rel, text_va, rodata_va, data_va, bss_va)?;
                phase12_apply_riscv_u_type(
                    text,
                    rel,
                    phase12_riscv_hi20(got as i128 + rel.addend as i128 - place as i128)?,
                )?;
            }
            "none" => {}
            other => {
                return Err(format!(
                    "[E_MACHINE_LINK_RELOCATION_UNSUPPORTED_001] unsupported final relocation kind '{other}'"
                )
                .into())
            }
        }
    }
    Ok(())
}

fn phase12_apply_arm_thumb_relocation(
    text: &mut [u8],
    rel: &Phase12LinkedRelocation,
    target: u64,
    text_va: u64,
    link: bool,
) -> Result<(), Box<dyn Error>> {
    if rel.section != "text" {
        return Err(format!(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] Thumb branch relocation cannot target section '{}'",
            rel.section
        )
        .into());
    }
    let text_va = u32::try_from(text_va)
        .map_err(|_| "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] ARM .text VA exceeds u32")?;
    let target = u32::try_from(target)
        .map_err(|_| "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] ARM branch target exceeds u32")?;
    let kind = if link {
        ncc_machine::ArmRelocationKind::ThmCall
    } else {
        ncc_machine::ArmRelocationKind::ThmJump24
    };
    let relocation = ncc_machine::ArmRelocation {
        offset: rel.offset,
        kind,
        symbol: rel.symbol.clone(),
        addend: rel.addend as i64,
    };
    let symbols = BTreeMap::from([(rel.symbol.clone(), target)]);
    ncc_machine::apply_arm_relocations(text, text_va, &[relocation], &symbols)
        .map_err(|err| format!("[E_MACHINE_LINK_RELOCATION_001] {err}").into())
}

fn phase12_apply_arm_mov_relocation(
    text: &mut [u8],
    rel: &Phase12LinkedRelocation,
    target: u64,
    text_va: u64,
) -> Result<(), Box<dyn Error>> {
    if rel.section != "text" {
        return Err(format!(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] ARM MOVW/MOVT relocation cannot target section '{}'",
            rel.section
        )
        .into());
    }
    let text_va = u32::try_from(text_va)
        .map_err(|_| "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] ARM .text VA exceeds u32")?;
    let target = u32::try_from(target)
        .map_err(|_| "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] ARM MOV target exceeds u32")?;
    let kind = if rel.kind == "arm-movw-abs-nc" {
        ncc_machine::ArmRelocationKind::MovwAbsNc
    } else {
        ncc_machine::ArmRelocationKind::MovtAbs
    };
    let relocation = ncc_machine::ArmRelocation {
        offset: rel.offset,
        kind,
        symbol: rel.symbol.clone(),
        addend: rel.addend as i64,
    };
    let symbols = BTreeMap::from([(rel.symbol.clone(), target)]);
    ncc_machine::apply_arm_relocations(text, text_va, &[relocation], &symbols)
        .map_err(|err| format!("[E_MACHINE_LINK_RELOCATION_001] {err}").into())
}

fn phase12_i386_got_base(got_targets: &HashMap<String, u64>) -> Result<u64, Box<dyn Error>> {
    got_targets
        .get("_GLOBAL_OFFSET_TABLE_")
        .or_else(|| got_targets.get("__GLOBAL_OFFSET_TABLE_"))
        .copied()
        .ok_or_else(|| {
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] i386 GOT relocation requires a materialized GOT base"
                .into()
        })
}

fn phase12_apply_i386_gotoff32(
    text: &mut [u8],
    rodata: &mut [u8],
    data: &mut [u8],
    rel: &Phase12LinkedRelocation,
    target: u64,
    got_base: u64,
) -> Result<(), Box<dyn Error>> {
    let value = target as i128 + rel.addend as i128 - got_base as i128;
    if value < i32::MIN as i128 || value > i32::MAX as i128 {
        return Err(
            "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] R_386_GOTOFF does not fit i32".into(),
        );
    }
    phase12_write_reloc_u32(text, rodata, data, rel, value as i32 as u32)
}

fn phase12_relocation_place_va(
    rel: &Phase12LinkedRelocation,
    text_va: u64,
    rodata_va: Option<u64>,
    data_va: Option<u64>,
    bss_va: Option<u64>,
) -> Result<u64, Box<dyn Error>> {
    match rel.section.as_str() {
        "text" => Ok(text_va + rel.offset as u64),
        "rodata" => Ok(rodata_va
            .ok_or("[E_MACHINE_LINK_RELOCATION_TARGET_001] .rodata relocation has no rodata VA")?
            + rel.offset as u64),
        "data" => Ok(data_va
            .ok_or("[E_MACHINE_LINK_RELOCATION_TARGET_001] .data relocation has no data VA")?
            + rel.offset as u64),
        "bss" => Ok(bss_va
            .ok_or("[E_MACHINE_LINK_RELOCATION_TARGET_001] .bss relocation has no bss VA")?
            + rel.offset as u64),
        other => Err(format!(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] relocation section '{other}' is unsupported"
        )
        .into()),
    }
}

fn phase12_write_reloc_u32(
    text: &mut [u8],
    rodata: &mut [u8],
    data: &mut [u8],
    rel: &Phase12LinkedRelocation,
    value: u32,
) -> Result<(), Box<dyn Error>> {
    let bytes = match rel.section.as_str() {
        "text" => text,
        "rodata" => rodata,
        "data" => data,
        other => {
            return Err(format!(
                "[E_MACHINE_LINK_RELOCATION_TARGET_001] u32 relocation section '{other}' is unsupported"
            )
            .into())
        }
    };
    if rel.offset + 4 > bytes.len() {
        return Err("[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] u32 relocation overflows".into());
    }
    bytes[rel.offset..rel.offset + 4].copy_from_slice(&value.to_le_bytes());
    Ok(())
}

fn phase12_apply_pc32(
    text: &mut [u8],
    rodata: &mut [u8],
    data: &mut [u8],
    rel: &Phase12LinkedRelocation,
    target: u64,
    text_va: u64,
    rodata_va: Option<u64>,
    data_va: Option<u64>,
    bss_va: Option<u64>,
) -> Result<(), Box<dyn Error>> {
    let place = phase12_relocation_place_va(rel, text_va, rodata_va, data_va, bss_va)?;
    let value = target as i128 + rel.addend as i128 - place as i128;
    if value < i32::MIN as i128 || value > i32::MAX as i128 {
        return Err("[E_MACHINE_LINK_PCREL_RANGE_001] pc32 relocation does not fit i32".into());
    }
    phase12_write_reloc_u32(text, rodata, data, rel, value as i32 as u32)
}

fn phase12_apply_abs32(
    text: &mut [u8],
    rodata: &mut [u8],
    data: &mut [u8],
    rel: &Phase12LinkedRelocation,
    target: u64,
) -> Result<(), Box<dyn Error>> {
    let value = target as i128 + rel.addend as i128;
    match rel.kind.as_str() {
        "abs32s" if value < i32::MIN as i128 || value > i32::MAX as i128 => {
            Err("[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] abs32s relocation overflows".into())
        }
        "abs32" if value < 0 || value > u32::MAX as i128 => {
            Err("[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] abs32 relocation overflows".into())
        }
        _ => phase12_write_reloc_u32(text, rodata, data, rel, value as u32),
    }
}

fn phase12_coff_addr32_value(target: u64, addend: isize) -> Result<u32, Box<dyn Error>> {
    let value = target as i128 + addend as i128;
    if value < 0 || value > u64::MAX as i128 {
        return Err(
            "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] COFF ADDR32 relocation overflows u64".into(),
        );
    }
    // IMAGE_REL_AMD64_ADDR32 records the low 32 bits of the preferred VA.
    // This intentionally matches link.exe/lld-link for PE32+ debug records.
    Ok(value as u64 as u32)
}

fn phase12_apply_aarch64_branch26(
    text: &mut [u8],
    rel: &Phase12LinkedRelocation,
    target: u64,
    text_va: u64,
) -> Result<(), Box<dyn Error>> {
    if rel.section != "text" {
        return Err(format!(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] AArch64 branch relocation cannot target section '{}'",
            rel.section
        )
        .into());
    }
    if rel.offset + 4 > text.len() {
        return Err("[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] AArch64 branch26 overflows".into());
    }
    let place = text_va + rel.offset as u64;
    let delta = target as i128 + rel.addend as i128 - place as i128;
    if delta % 4 != 0 {
        return Err(
            "[E_MACHINE_LINK_PCREL_RANGE_001] AArch64 branch target is not 4-byte aligned".into(),
        );
    }
    let imm26 = delta / 4;
    if !(-(1_i128 << 25)..(1_i128 << 25)).contains(&imm26) {
        return Err("[E_MACHINE_LINK_PCREL_RANGE_001] AArch64 branch26 does not fit".into());
    }
    let inst = read_u32(text, rel.offset);
    let patched = (inst & !0x03ff_ffff) | ((imm26 as i64 as u32) & 0x03ff_ffff);
    text[rel.offset..rel.offset + 4].copy_from_slice(&patched.to_le_bytes());
    Ok(())
}

fn phase12_apply_aarch64_adrp(
    text: &mut [u8],
    rel: &Phase12LinkedRelocation,
    target: u64,
    text_va: u64,
) -> Result<(), Box<dyn Error>> {
    if rel.section != "text" || rel.offset + 4 > text.len() {
        return Err(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] AArch64 ADRP relocation must patch .text"
                .into(),
        );
    }
    let place = text_va + rel.offset as u64;
    let target_page = (target as i128 + rel.addend as i128) >> 12;
    let place_page = (place >> 12) as i128;
    let imm = target_page - place_page;
    if !(-(1_i128 << 20)..(1_i128 << 20)).contains(&imm) {
        return Err("[E_MACHINE_LINK_PCREL_RANGE_001] AArch64 ADRP page delta does not fit".into());
    }
    let imm_u = imm as i64 as u32;
    let immlo = imm_u & 0x3;
    let immhi = (imm_u >> 2) & 0x7ffff;
    let inst = read_u32(text, rel.offset);
    let patched = (inst & !((0x3 << 29) | (0x7ffff << 5))) | (immlo << 29) | (immhi << 5);
    text[rel.offset..rel.offset + 4].copy_from_slice(&patched.to_le_bytes());
    Ok(())
}

fn phase12_apply_aarch64_add_lo12(
    text: &mut [u8],
    rel: &Phase12LinkedRelocation,
    target: u64,
) -> Result<(), Box<dyn Error>> {
    if rel.section != "text" || rel.offset + 4 > text.len() {
        return Err(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] AArch64 ADD lo12 relocation must patch .text"
                .into(),
        );
    }
    let imm12 = ((target as i128 + rel.addend as i128) & 0xfff) as u32;
    let inst = read_u32(text, rel.offset);
    let patched = (inst & !(0xfff << 10)) | (imm12 << 10);
    text[rel.offset..rel.offset + 4].copy_from_slice(&patched.to_le_bytes());
    Ok(())
}

fn phase12_apply_aarch64_ldst_lo12(
    text: &mut [u8],
    rel: &Phase12LinkedRelocation,
    target: u64,
    scale: u32,
) -> Result<(), Box<dyn Error>> {
    if rel.section != "text" || rel.offset + 4 > text.len() {
        return Err(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] AArch64 LD/ST lo12 relocation must patch .text"
                .into(),
        );
    }
    let value = target as i128 + rel.addend as i128;
    let low12 = (value & 0xfff) as u32;
    if scale == 0 || !scale.is_power_of_two() || low12 % scale != 0 {
        return Err(format!(
            "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] AArch64 LD/ST lo12 value 0x{low12:x} is not aligned to scale {scale}"
        )
        .into());
    }
    let imm12 = low12 / scale;
    let inst = read_u32(text, rel.offset);
    let patched = (inst & !(0xfff << 10)) | (imm12 << 10);
    text[rel.offset..rel.offset + 4].copy_from_slice(&patched.to_le_bytes());
    Ok(())
}

fn phase12_apply_aarch64_pageoff12(
    text: &mut [u8],
    rel: &Phase12LinkedRelocation,
    target: u64,
) -> Result<(), Box<dyn Error>> {
    if rel.section != "text" || rel.offset + 4 > text.len() {
        return Err(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] AArch64 PAGEOFF12 relocation must patch .text"
                .into(),
        );
    }
    let inst = read_u32(text, rel.offset);
    if inst & 0x1f00_0000 == 0x1100_0000 {
        return phase12_apply_aarch64_add_lo12(text, rel, target);
    }
    if inst & 0x3b00_0000 == 0x3900_0000 {
        let size = (inst >> 30) & 0x3;
        let vector = inst & (1 << 26) != 0;
        let opc = (inst >> 22) & 0x3;
        let scale = if vector && size == 0 && opc == 3 {
            16
        } else {
            1_u32 << size
        };
        return phase12_apply_aarch64_ldst_lo12(text, rel, target, scale);
    }
    Err(format!(
        "[E_MACHINE_LINK_RELOCATION_UNSUPPORTED_001] ARM64_RELOC_PAGEOFF12 cannot patch instruction 0x{inst:08x}"
    )
    .into())
}

fn phase12_apply_riscv_u_type(
    text: &mut [u8],
    rel: &Phase12LinkedRelocation,
    imm20: i128,
) -> Result<(), Box<dyn Error>> {
    if rel.section != "text" || rel.offset + 4 > text.len() {
        return Err(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] RISC-V U relocation must patch .text".into(),
        );
    }
    if !(-(1_i128 << 19)..(1_i128 << 20)).contains(&imm20) {
        return Err("[E_MACHINE_LINK_PCREL_RANGE_001] RISC-V hi20 does not fit".into());
    }
    let inst = read_u32(text, rel.offset);
    let patched = (inst & 0x0000_0fff) | (((imm20 as i64 as u32) & 0x000f_ffff) << 12);
    text[rel.offset..rel.offset + 4].copy_from_slice(&patched.to_le_bytes());
    Ok(())
}

fn phase12_apply_riscv_i_lo12(
    text: &mut [u8],
    rel: &Phase12LinkedRelocation,
    value: i128,
) -> Result<(), Box<dyn Error>> {
    if rel.section != "text" || rel.offset + 4 > text.len() {
        return Err(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] RISC-V I lo12 relocation must patch .text"
                .into(),
        );
    }
    let lo = (phase12_riscv_lo12(value) as i32 as u32) & 0xfff;
    let inst = read_u32(text, rel.offset);
    let patched = (inst & !(0xfff << 20)) | (lo << 20);
    text[rel.offset..rel.offset + 4].copy_from_slice(&patched.to_le_bytes());
    Ok(())
}

fn phase12_apply_riscv_s_lo12(
    text: &mut [u8],
    rel: &Phase12LinkedRelocation,
    value: i128,
) -> Result<(), Box<dyn Error>> {
    if rel.section != "text" || rel.offset + 4 > text.len() {
        return Err(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] RISC-V S lo12 relocation must patch .text"
                .into(),
        );
    }
    let lo = (phase12_riscv_lo12(value) as i32 as u32) & 0xfff;
    let inst = read_u32(text, rel.offset);
    let patched =
        (inst & !((0x7f << 25) | (0x1f << 7))) | (((lo >> 5) & 0x7f) << 25) | ((lo & 0x1f) << 7);
    text[rel.offset..rel.offset + 4].copy_from_slice(&patched.to_le_bytes());
    Ok(())
}

fn phase12_apply_riscv_jal(
    text: &mut [u8],
    rel: &Phase12LinkedRelocation,
    target: u64,
    text_va: u64,
) -> Result<(), Box<dyn Error>> {
    if rel.section != "text" || rel.offset + 4 > text.len() {
        return Err(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] RISC-V JAL relocation must patch .text".into(),
        );
    }
    let place = text_va + rel.offset as u64;
    let delta = target as i128 + rel.addend as i128 - place as i128;
    if delta % 2 != 0 || !(-(1_i128 << 20)..(1_i128 << 20)).contains(&delta) {
        return Err("[E_MACHINE_LINK_PCREL_RANGE_001] RISC-V JAL displacement does not fit".into());
    }
    let imm = delta as i64 as u32;
    let encoded = ((imm >> 20) & 0x1) << 31
        | ((imm >> 1) & 0x3ff) << 21
        | ((imm >> 11) & 0x1) << 20
        | ((imm >> 12) & 0xff) << 12;
    let inst = read_u32(text, rel.offset);
    let patched = (inst & 0x0000_0fff) | encoded;
    text[rel.offset..rel.offset + 4].copy_from_slice(&patched.to_le_bytes());
    Ok(())
}

fn phase12_apply_riscv_branch(
    text: &mut [u8],
    rel: &Phase12LinkedRelocation,
    target: u64,
    text_va: u64,
) -> Result<(), Box<dyn Error>> {
    if rel.section != "text" || rel.offset + 4 > text.len() {
        return Err(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] RISC-V branch relocation must patch .text"
                .into(),
        );
    }
    let place = text_va + rel.offset as u64;
    let delta = target as i128 + rel.addend as i128 - place as i128;
    if delta % 2 != 0 || !(-(1_i128 << 12)..(1_i128 << 12)).contains(&delta) {
        return Err(
            "[E_MACHINE_LINK_PCREL_RANGE_001] RISC-V branch displacement does not fit".into(),
        );
    }
    let imm = delta as i64 as u32;
    let encoded = ((imm >> 12) & 0x1) << 31
        | ((imm >> 5) & 0x3f) << 25
        | ((imm >> 1) & 0x0f) << 8
        | ((imm >> 11) & 0x1) << 7;
    let inst = read_u32(text, rel.offset);
    let patched = (inst & !0xfe00_0f80) | encoded;
    text[rel.offset..rel.offset + 4].copy_from_slice(&patched.to_le_bytes());
    Ok(())
}

fn phase12_apply_riscv_rvc_branch(
    text: &mut [u8],
    rel: &Phase12LinkedRelocation,
    target: u64,
    text_va: u64,
) -> Result<(), Box<dyn Error>> {
    if rel.section != "text" || rel.offset + 2 > text.len() {
        return Err(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] RISC-V RVC_BRANCH relocation must patch a 16-bit instruction"
                .into(),
        );
    }
    let place = text_va + rel.offset as u64;
    let delta = target as i128 + rel.addend as i128 - place as i128;
    if delta % 2 != 0 || !(-256..256).contains(&delta) {
        return Err(
            "[E_MACHINE_LINK_PCREL_RANGE_001] RISC-V RVC_BRANCH displacement does not fit signed 9-bit immediate"
                .into(),
        );
    }
    let imm = delta as i16 as u16;
    let encoded = ((imm >> 8) & 0x1) << 12
        | ((imm >> 3) & 0x3) << 10
        | ((imm >> 6) & 0x3) << 5
        | ((imm >> 1) & 0x3) << 3
        | ((imm >> 5) & 0x1) << 2;
    let inst = read_u16(text, rel.offset);
    write_u16(text, rel.offset, (inst & !0x1c7c) | encoded);
    Ok(())
}

fn phase12_apply_riscv_rvc_jump(
    text: &mut [u8],
    rel: &Phase12LinkedRelocation,
    target: u64,
    text_va: u64,
) -> Result<(), Box<dyn Error>> {
    if rel.section != "text" || rel.offset + 2 > text.len() {
        return Err(
            "[E_MACHINE_LINK_RELOCATION_TARGET_001] RISC-V RVC_JUMP relocation must patch a 16-bit instruction"
                .into(),
        );
    }
    let place = text_va + rel.offset as u64;
    let delta = target as i128 + rel.addend as i128 - place as i128;
    if delta % 2 != 0 || !(-2048..2048).contains(&delta) {
        return Err(
            "[E_MACHINE_LINK_PCREL_RANGE_001] RISC-V RVC_JUMP displacement does not fit signed 12-bit immediate"
                .into(),
        );
    }
    let imm = delta as i16 as u16;
    let encoded = ((imm >> 11) & 0x1) << 12
        | ((imm >> 4) & 0x1) << 11
        | ((imm >> 8) & 0x3) << 9
        | ((imm >> 10) & 0x1) << 8
        | ((imm >> 6) & 0x1) << 7
        | ((imm >> 7) & 0x1) << 6
        | ((imm >> 1) & 0x7) << 3
        | ((imm >> 5) & 0x1) << 2;
    let inst = read_u16(text, rel.offset);
    write_u16(text, rel.offset, (inst & !0x1ffc) | encoded);
    Ok(())
}

fn phase12_apply_riscv_call_pair(
    text: &mut [u8],
    rel: &Phase12LinkedRelocation,
    target: u64,
    text_va: u64,
) -> Result<(), Box<dyn Error>> {
    if rel.section != "text" || rel.offset + 8 > text.len() {
        return Err("[E_MACHINE_LINK_RELOCATION_TARGET_001] RISC-V CALL relocation must patch AUIPC/JALR pair".into());
    }
    let place = text_va + rel.offset as u64;
    let delta = target as i128 + rel.addend as i128 - place as i128;
    let hi = phase12_riscv_hi20(delta)?;
    let lo = delta - (hi << 12);
    let hi_rel = Phase12LinkedRelocation {
        section: rel.section.clone(),
        offset: rel.offset,
        kind: rel.kind.clone(),
        symbol: rel.symbol.clone(),
        addend: rel.addend,
    };
    phase12_apply_riscv_u_type(text, &hi_rel, hi)?;
    let lo_rel = Phase12LinkedRelocation {
        section: rel.section.clone(),
        offset: rel.offset + 4,
        kind: rel.kind.clone(),
        symbol: rel.symbol.clone(),
        addend: rel.addend,
    };
    phase12_apply_riscv_i_lo12(text, &lo_rel, lo)?;
    Ok(())
}

fn phase12_riscv_hi20(value: i128) -> Result<i128, Box<dyn Error>> {
    let hi = (value + 0x800) >> 12;
    if !(-(1_i128 << 19)..(1_i128 << 20)).contains(&hi) {
        return Err("[E_MACHINE_LINK_PCREL_RANGE_001] RISC-V hi20 does not fit".into());
    }
    Ok(hi)
}

fn phase12_riscv_lo12(value: i128) -> i16 {
    let lo = value & 0xfff;
    if lo >= 0x800 {
        (lo as i32 - 0x1000) as i16
    } else {
        lo as i16
    }
}

fn phase12_riscv_pcrel_hi_values(
    image: &Phase12LinkedImage,
    text_va: u64,
    rodata_va: Option<u64>,
    data_va: Option<u64>,
    bss_va: Option<u64>,
    symbol_vas: &BTreeMap<String, u64>,
    dynamic_targets: &HashMap<String, u64>,
    got_targets: &HashMap<String, u64>,
) -> Result<HashMap<u64, i128>, Box<dyn Error>> {
    let mut out = HashMap::new();
    for rel in &image.relocations {
        if rel.kind != "riscv-pcrel-hi20" && rel.kind != "riscv-got-hi20" {
            continue;
        }
        let target = if rel.kind == "riscv-got-hi20" {
            *got_targets.get(&rel.symbol).ok_or_else(|| {
                format!(
                    "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] unresolved RISC-V GOT_HI20 symbol '{}'",
                    rel.symbol
                )
            })?
        } else {
            symbol_vas
                .get(&rel.symbol)
                .copied()
                .or_else(|| dynamic_targets.get(&rel.symbol).copied())
                .or_else(|| image.null_symbols.contains(&rel.symbol).then_some(0))
                .ok_or_else(|| {
                    format!(
                        "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] unresolved RISC-V PCREL_HI20 symbol '{}'",
                        rel.symbol
                    )
                })?
        };
        let place = phase12_relocation_place_va(rel, text_va, rodata_va, data_va, bss_va)?;
        out.insert(place, target as i128 + rel.addend as i128 - place as i128);
    }
    Ok(out)
}

fn phase12_riscv_pcrel_lo_value(
    rel: &Phase12LinkedRelocation,
    symbol_vas: &BTreeMap<String, u64>,
    hi_values: &HashMap<u64, i128>,
) -> Result<i128, Box<dyn Error>> {
    let hi_place = *symbol_vas.get(&rel.symbol).ok_or_else(|| {
        format!(
            "[E_MACHINE_LINK_UNRESOLVED_SYMBOL_001] unresolved RISC-V PCREL_LO12 label '{}'",
            rel.symbol
        )
    })?;
    hi_values.get(&hi_place).copied().ok_or_else(|| {
        format!(
            "[E_MACHINE_LINK_RELOCATION_001] RISC-V PCREL_LO12 could not find matching HI20 at 0x{hi_place:x}"
        )
        .into()
    })
}

fn phase12_macho64_os_executable_bytes(
    image: &Phase12LinkedImage,
) -> Result<Vec<u8>, Box<dyn Error>> {
    if !matches!(image.arch.as_str(), "x86_64" | "aarch64") {
        return Err(format!(
            "[E_MACHINE_LINK_TARGET_001] Mach-O executable finalizer does not support arch {}",
            image.arch
        )
        .into());
    }
    let imports = image
        .dynamic_imports
        .iter()
        .filter(|symbol| !phase12_is_linker_defined_symbol(symbol))
        .cloned()
        .collect::<Vec<_>>();
    let mut text = image.text.clone();
    let mut rodata = image.rodata.clone();
    let mut data = image.data.clone();
    let dso_symbols = image
        .relocations
        .iter()
        .filter(|relocation| matches!(relocation.symbol.as_str(), "__dso_handle" | "___dso_handle"))
        .map(|relocation| relocation.symbol.clone())
        .collect::<BTreeSet<_>>();
    let dso_handle_offset = if dso_symbols.is_empty() {
        None
    } else {
        let offset = align_to(data.len(), 8);
        data.resize(offset + 8, 0);
        Some(offset)
    };
    let dso_got_offset = if dso_symbols.is_empty() {
        None
    } else {
        let offset = align_to(data.len(), 8);
        data.resize(offset + 8, 0);
        Some(offset)
    };
    let page_size = 0x1000_usize;
    let pagezero_cmd = 72_usize;
    let text_section_count = 1 + usize::from(!imports.is_empty()) + usize::from(!rodata.is_empty());
    let text_cmd = 72_usize + text_section_count * 80;
    let data_section_count = usize::from(!data.is_empty())
        + usize::from(!imports.is_empty())
        + usize::from(image.bss_size > 0);
    let data_cmd = if data_section_count == 0 {
        0
    } else {
        72 + data_section_count * 80
    };
    let linkedit_cmd = 72_usize;
    let build_version_cmd = 24_usize;
    let main_cmd = 24_usize;
    let dyld_cmd = phase12_macho_string_command_size("/usr/lib/dyld");
    let libsystem_cmd = phase12_macho_string_command_size("/usr/lib/libSystem.B.dylib");
    let dyld_info_cmd = 48_usize;
    let dysymtab_cmd = 80_usize;
    let symtab_cmd = 24_usize;
    let code_signature_cmd = 16_usize;
    let ncmds = 11 + usize::from(data_cmd > 0);
    let sizeofcmds = pagezero_cmd
        + text_cmd
        + data_cmd
        + linkedit_cmd
        + build_version_cmd
        + main_cmd
        + dyld_cmd
        + libsystem_cmd
        + dyld_info_cmd
        + dysymtab_cmd
        + symtab_cmd
        + code_signature_cmd;
    let text_align = image.text_align.max(16);
    let rodata_align = image.rodata_align.max(1);
    let data_align = image.data_align.max(1);
    let segment_align = page_size.max(data_align);
    let text_offset = align_to(32 + sizeofcmds, text_align);
    let text_vm_base = 0x100000000_u64;
    let text_addr = text_vm_base + text_offset as u64;
    let stubs_offset = align_to(text_offset + text.len(), 16);
    let stubs_addr = text_vm_base + stubs_offset as u64;
    let stub_size = if image.arch == "aarch64" { 12 } else { 6 };
    let stubs_len = imports.len() * stub_size;
    let const_offset = align_to(stubs_offset + stubs_len, rodata_align);
    let const_addr = if rodata.is_empty() {
        None
    } else {
        Some(text_vm_base + const_offset as u64)
    };
    let text_content_end = [
        text_offset + text.len(),
        stubs_offset + stubs_len,
        const_offset + rodata.len(),
    ]
    .into_iter()
    .max()
    .unwrap_or(text_offset);
    let text_filesize = align_to(text_content_end, segment_align);
    let text_vmsize = text_filesize as u64;
    let data_fileoff = text_filesize;
    let data_vmaddr = text_vm_base + text_vmsize;
    let data_offset = data_fileoff;
    let data_addr = data_vmaddr;
    let la_ptr_offset = align_to(data_offset + data.len(), 8);
    let la_ptr_addr = data_vmaddr + (la_ptr_offset - data_fileoff) as u64;
    let stubs = phase12_macho_stubs_bytes_at(&image.arch, imports.len(), stubs_addr, la_ptr_addr)?;
    let lazy_ptrs = vec![0_u8; imports.len() * 8];
    let bss_offset_in_segment = align_to(
        la_ptr_offset - data_fileoff + lazy_ptrs.len(),
        image.bss_align.max(1),
    );
    let bss_addr = if image.bss_size > 0 {
        Some(data_vmaddr + bss_offset_in_segment as u64)
    } else {
        None
    };
    let data_payload_end = [data_offset + data.len(), la_ptr_offset + lazy_ptrs.len()]
        .into_iter()
        .max()
        .unwrap_or(data_fileoff);
    let data_payload_filesize = data_payload_end.saturating_sub(data_fileoff);
    let data_filesize = if data_cmd == 0 {
        0
    } else {
        align_to(data_payload_filesize, page_size)
    };
    let data_vmsize = if data_cmd == 0 {
        0
    } else {
        align_to(
            data_payload_filesize.max(bss_offset_in_segment.saturating_add(image.bss_size)),
            page_size,
        )
    };
    let linkedit_offset = align_to(data_fileoff + data_filesize, page_size);
    let linkedit_vmaddr = data_vmaddr + data_vmsize as u64;
    let mut symbol_vas = phase12_linked_symbol_vas(
        image,
        text_addr,
        const_addr,
        if data_cmd > 0 { Some(data_addr) } else { None },
        bss_addr,
        &BTreeMap::new(),
    );
    let mut synthesized_symbols = Vec::<(String, u64)>::new();
    if let Some(offset) = dso_handle_offset {
        let address = data_addr + offset as u64;
        data[offset..offset + 8].copy_from_slice(&address.to_le_bytes());
        for symbol in &dso_symbols {
            symbol_vas.insert(symbol.clone(), address);
            synthesized_symbols.push((symbol.clone(), address));
        }
    }
    let entry_va = symbol_vas.get(&image.entry).copied().ok_or_else(|| {
        format!(
            "[E_MACHINE_LINK_ENTRY_MISSING_001] entry symbol '{}' was not laid out",
            image.entry
        )
    })?;
    let dynamic_targets = imports
        .iter()
        .enumerate()
        .map(|(index, symbol)| {
            (
                symbol.clone(),
                stubs_addr + (index as u64 * stub_size as u64),
            )
        })
        .collect::<HashMap<_, _>>();
    let mut got_targets = HashMap::new();
    if let Some(offset) = dso_got_offset {
        let slot = data_addr + offset as u64;
        let value = dso_handle_offset
            .map(|handle| data_addr + handle as u64)
            .unwrap_or_default();
        data[offset..offset + 8].copy_from_slice(&value.to_le_bytes());
        for symbol in &dso_symbols {
            got_targets.insert(symbol.clone(), slot);
        }
    }
    phase12_apply_linked_relocations(
        &mut text,
        &mut rodata,
        &mut data,
        image,
        text_addr,
        const_addr,
        if data_cmd > 0 { Some(data_addr) } else { None },
        bss_addr,
        &symbol_vas,
        &dynamic_targets,
        &got_targets,
    )?;
    let const_section_index = if rodata.is_empty() {
        None
    } else {
        Some(1_u8 + u8::from(!imports.is_empty()))
    };
    let mut next_section_index =
        1_u8 + u8::from(!imports.is_empty()) + u8::from(!rodata.is_empty());
    let data_section_index = if data.is_empty() {
        None
    } else {
        next_section_index += 1;
        Some(next_section_index)
    };
    let _la_ptr_section_index = if imports.is_empty() {
        None
    } else {
        next_section_index += 1;
        Some(next_section_index)
    };
    let bss_section_index = if image.bss_size == 0 {
        None
    } else {
        next_section_index += 1;
        Some(next_section_index)
    };
    let macho_symbols = phase12_macho_symtab_bytes(
        image,
        &symbol_vas,
        const_section_index,
        data_section_index,
        bss_section_index,
        &synthesized_symbols,
    );
    let la_ptr_segment_offset = la_ptr_offset.saturating_sub(data_fileoff);
    let bind = if imports.is_empty() {
        Vec::new()
    } else {
        phase12_macho_bind_opcodes(&imports, false, la_ptr_segment_offset)
    };
    let lazy_bind = if imports.is_empty() {
        Vec::new()
    } else {
        phase12_macho_bind_opcodes(&imports, true, la_ptr_segment_offset)
    };
    let indirect_symbols =
        phase12_macho_indirect_symbol_table_bytes(imports.len(), macho_symbols.defined_count);
    let bind_off = if bind.is_empty() {
        0
    } else {
        linkedit_offset as u32
    };
    let lazy_bind_off = if lazy_bind.is_empty() {
        0
    } else {
        (linkedit_offset + bind.len()) as u32
    };
    let indirect_symbols_offset = if indirect_symbols.is_empty() {
        0
    } else {
        align_to(linkedit_offset + bind.len() + lazy_bind.len(), 4)
    };
    let symoff_base = if indirect_symbols.is_empty() {
        linkedit_offset + bind.len() + lazy_bind.len()
    } else {
        indirect_symbols_offset + indirect_symbols.len()
    };
    let symoff = align_to(symoff_base, 8);
    let stroff = symoff + macho_symbols.symtab.len();
    let code_signature_offset = align_to(stroff + macho_symbols.strtab.len(), 16);
    let code_signature_identifier = phase12_macho_code_signature_identifier(&image.entry);
    let code_signature_size =
        phase12_macho_ad_hoc_code_signature_size(code_signature_offset, &code_signature_identifier);
    let linkedit_content_end = code_signature_offset + code_signature_size;
    let linkedit_filesize = align_to(linkedit_content_end - linkedit_offset, page_size);
    let file_size = linkedit_offset + linkedit_filesize;
    let mut out = vec![0_u8; file_size];

    write_u32(&mut out, 0, 0xfeedfacf);
    let (cpu_type, cpu_subtype) = if image.arch == "aarch64" {
        (0x0100000c, 0)
    } else {
        (0x01000007, 3)
    };
    write_u32(&mut out, 4, cpu_type);
    write_u32(&mut out, 8, cpu_subtype);
    write_u32(&mut out, 12, 2);
    write_u32(&mut out, 16, ncmds as u32);
    write_u32(&mut out, 20, sizeofcmds as u32);
    write_u32(&mut out, 24, 0x00000085);
    write_u32(&mut out, 28, 0);

    let mut cursor = 32;
    phase12_write_macho_segment64(
        &mut out,
        cursor,
        "__PAGEZERO",
        0,
        text_vm_base,
        0,
        0,
        0,
        0,
        0,
    );
    cursor += pagezero_cmd;
    phase12_write_macho_text_segment(
        &mut out,
        cursor,
        text_vm_base,
        text_vmsize,
        text_filesize,
        text_addr,
        text.len(),
        text_offset,
        text_align,
        stubs_addr,
        stubs.len(),
        stubs_offset,
        stub_size,
        const_addr,
        rodata.len(),
        const_offset,
        rodata_align,
    );
    cursor += text_cmd;
    if data_cmd > 0 {
        phase12_write_macho_data_segment(
            &mut out,
            cursor,
            data_vmaddr,
            data_vmsize as u64,
            data_fileoff,
            data_filesize,
            data_addr,
            data.len(),
            data_offset,
            data_align,
            la_ptr_addr,
            lazy_ptrs.len(),
            la_ptr_offset,
            bss_addr,
            image.bss_size,
            image.bss_align,
            data_section_count,
        );
        cursor += data_cmd;
    }
    phase12_write_macho_segment64(
        &mut out,
        cursor,
        "__LINKEDIT",
        linkedit_vmaddr,
        linkedit_filesize as u64,
        linkedit_offset as u64,
        linkedit_filesize as u64,
        1,
        1,
        0,
    );
    cursor += linkedit_cmd;
    phase12_write_macho_build_version_command(&mut out, cursor);
    cursor += build_version_cmd;
    phase12_write_macho_main_command(&mut out, cursor, entry_va - text_vm_base);
    cursor += main_cmd;
    cursor += phase12_write_macho_string_command(&mut out, cursor, 0x0e, "/usr/lib/dyld");
    cursor +=
        phase12_write_macho_string_command(&mut out, cursor, 0x0c, "/usr/lib/libSystem.B.dylib");
    cursor += phase12_write_macho_dyld_info_command(
        &mut out,
        cursor,
        bind_off,
        bind.len() as u32,
        lazy_bind_off,
        lazy_bind.len() as u32,
    );
    cursor += phase12_write_macho_dysymtab_command(
        &mut out,
        cursor,
        macho_symbols.defined_count,
        imports.len(),
        indirect_symbols_offset as u32,
        imports.len() as u32,
    );
    cursor += phase12_write_macho_symtab_command(
        &mut out,
        cursor,
        symoff as u32,
        macho_symbols.symbol_count as u32,
        stroff as u32,
        macho_symbols.strtab.len() as u32,
    );
    let _ = phase12_write_macho_code_signature_command(
        &mut out,
        cursor,
        code_signature_offset as u32,
        code_signature_size as u32,
    );
    out[text_offset..text_offset + text.len()].copy_from_slice(&text);
    if !stubs.is_empty() {
        out[stubs_offset..stubs_offset + stubs.len()].copy_from_slice(&stubs);
    }
    if !rodata.is_empty() {
        out[const_offset..const_offset + rodata.len()].copy_from_slice(&rodata);
    }
    if !data.is_empty() {
        out[data_offset..data_offset + data.len()].copy_from_slice(&data);
    }
    if !lazy_ptrs.is_empty() {
        out[la_ptr_offset..la_ptr_offset + lazy_ptrs.len()].copy_from_slice(&lazy_ptrs);
    }
    if !bind.is_empty() {
        out[linkedit_offset..linkedit_offset + bind.len()].copy_from_slice(&bind);
    }
    if !lazy_bind.is_empty() {
        let start = linkedit_offset + bind.len();
        out[start..start + lazy_bind.len()].copy_from_slice(&lazy_bind);
    }
    if !indirect_symbols.is_empty() {
        out[indirect_symbols_offset..indirect_symbols_offset + indirect_symbols.len()]
            .copy_from_slice(&indirect_symbols);
    }
    out[symoff..symoff + macho_symbols.symtab.len()].copy_from_slice(&macho_symbols.symtab);
    out[stroff..stroff + macho_symbols.strtab.len()].copy_from_slice(&macho_symbols.strtab);
    let code_signature = phase12_macho_ad_hoc_code_signature_bytes(
        &out[..code_signature_offset],
        code_signature_offset,
        &code_signature_identifier,
    );
    debug_assert_eq!(code_signature.len(), code_signature_size);
    out[code_signature_offset..code_signature_offset + code_signature.len()]
        .copy_from_slice(&code_signature);
    Ok(out)
}

struct Phase12MachoSymtab {
    symtab: Vec<u8>,
    strtab: Vec<u8>,
    defined_count: usize,
    symbol_count: usize,
}

fn phase12_macho_symtab_bytes(
    image: &Phase12LinkedImage,
    symbol_vas: &BTreeMap<String, u64>,
    const_section_index: Option<u8>,
    data_section_index: Option<u8>,
    bss_section_index: Option<u8>,
    synthesized_symbols: &[(String, u64)],
) -> Phase12MachoSymtab {
    let mut strtab = vec![0_u8];
    let mut symtab = Vec::new();
    for (name, symbol) in &image.symbols {
        let name_offset = phase12_macho_push_string(&mut strtab, name);
        let section_index = match symbol.section.as_str() {
            "rodata" => const_section_index.unwrap_or(1),
            "data" => data_section_index.unwrap_or(1),
            "bss" => bss_section_index.unwrap_or(1),
            _ => 1,
        };
        phase12_macho_push_nlist64(
            &mut symtab,
            name_offset,
            0x0f,
            section_index,
            0,
            symbol_vas.get(name).copied().unwrap_or_default(),
        );
    }
    for (name, value) in synthesized_symbols {
        if image.symbols.contains_key(name) {
            continue;
        }
        let name_offset = phase12_macho_push_string(&mut strtab, name);
        phase12_macho_push_nlist64(
            &mut symtab,
            name_offset,
            0x0f,
            data_section_index.unwrap_or(1),
            0,
            *value,
        );
    }
    let synthesized_count = synthesized_symbols
        .iter()
        .filter(|(name, _)| !image.symbols.contains_key(name))
        .count();
    let defined_count = image.symbols.len() + synthesized_count;
    let imports = image
        .dynamic_imports
        .iter()
        .filter(|symbol| !phase12_is_linker_defined_symbol(symbol))
        .collect::<Vec<_>>();
    for import in &imports {
        let name_offset = phase12_macho_push_string(&mut strtab, import);
        phase12_macho_push_nlist64(&mut symtab, name_offset, 0x01, 0, 0, 0);
    }
    Phase12MachoSymtab {
        symtab,
        strtab,
        defined_count,
        symbol_count: defined_count + imports.len(),
    }
}

fn phase12_macho_push_string(strtab: &mut Vec<u8>, value: &str) -> u32 {
    let offset = strtab.len() as u32;
    strtab.extend_from_slice(value.as_bytes());
    strtab.push(0);
    offset
}

fn phase12_macho_push_nlist64(
    out: &mut Vec<u8>,
    name_offset: u32,
    n_type: u8,
    n_sect: u8,
    n_desc: u16,
    n_value: u64,
) {
    out.extend_from_slice(&name_offset.to_le_bytes());
    out.push(n_type);
    out.push(n_sect);
    out.extend_from_slice(&n_desc.to_le_bytes());
    out.extend_from_slice(&n_value.to_le_bytes());
}

fn phase12_macho_code_signature_identifier(entry: &str) -> String {
    let mut out = String::from("ncc.phase12.");
    for ch in entry.chars() {
        if ch.is_ascii_alphanumeric() || matches!(ch, '.' | '_' | '-') {
            out.push(ch);
        } else {
            out.push('_');
        }
    }
    out
}

fn phase12_macho_ad_hoc_code_signature_size(code_limit: usize, identifier: &str) -> usize {
    let page_count = code_limit.div_ceil(0x1000);
    let code_directory_header = 52_usize;
    let ident_len = identifier.len() + 1;
    let hash_offset = code_directory_header + ident_len;
    let code_directory_len = hash_offset + page_count * 32;
    20 + code_directory_len
}

fn phase12_macho_ad_hoc_code_signature_bytes(
    image_prefix: &[u8],
    code_limit: usize,
    identifier: &str,
) -> Vec<u8> {
    let page_size = 0x1000_usize;
    let page_count = code_limit.div_ceil(page_size);
    let ident_len = identifier.len() + 1;
    let code_directory_header = 52_usize;
    let hash_offset = code_directory_header + ident_len;
    let code_directory_len = hash_offset + page_count * 32;
    let superblob_len = 20 + code_directory_len;
    let mut out = Vec::with_capacity(superblob_len);
    phase12_push_be_u32(&mut out, 0xfade0cc0);
    phase12_push_be_u32(&mut out, superblob_len as u32);
    phase12_push_be_u32(&mut out, 1);
    phase12_push_be_u32(&mut out, 0);
    phase12_push_be_u32(&mut out, 20);
    phase12_push_be_u32(&mut out, 0xfade0c02);
    phase12_push_be_u32(&mut out, code_directory_len as u32);
    phase12_push_be_u32(&mut out, 0x0002_0200);
    phase12_push_be_u32(&mut out, 0x0000_0002);
    phase12_push_be_u32(&mut out, hash_offset as u32);
    phase12_push_be_u32(&mut out, code_directory_header as u32);
    phase12_push_be_u32(&mut out, 0);
    phase12_push_be_u32(&mut out, page_count as u32);
    phase12_push_be_u32(&mut out, code_limit as u32);
    out.push(32);
    out.push(2);
    out.push(0);
    out.push(12);
    phase12_push_be_u32(&mut out, 0);
    phase12_push_be_u32(&mut out, 0);
    phase12_push_be_u32(&mut out, 0);
    out.extend_from_slice(identifier.as_bytes());
    out.push(0);
    for index in 0..page_count {
        let start = index * page_size;
        let end = (start + page_size).min(code_limit).min(image_prefix.len());
        let digest = Sha256::digest(&image_prefix[start..end]);
        out.extend_from_slice(&digest);
    }
    out
}

fn phase12_push_be_u32(out: &mut Vec<u8>, value: u32) {
    out.extend_from_slice(&value.to_be_bytes());
}

fn phase12_write_macho_dyld_info_command(
    out: &mut [u8],
    offset: usize,
    bind_off: u32,
    bind_size: u32,
    lazy_bind_off: u32,
    lazy_bind_size: u32,
) -> usize {
    write_u32(out, offset, 0x80000022);
    write_u32(out, offset + 4, 48);
    write_u32(out, offset + 16, bind_off);
    write_u32(out, offset + 20, bind_size);
    write_u32(out, offset + 32, lazy_bind_off);
    write_u32(out, offset + 36, lazy_bind_size);
    48
}

fn phase12_write_macho_dysymtab_command(
    out: &mut [u8],
    offset: usize,
    defined_count: usize,
    import_count: usize,
    indirect_symbols_off: u32,
    indirect_symbols_count: u32,
) -> usize {
    write_u32(out, offset, 0x0b);
    write_u32(out, offset + 4, 80);
    write_u32(out, offset + 16, 0);
    write_u32(out, offset + 20, defined_count as u32);
    write_u32(out, offset + 24, defined_count as u32);
    write_u32(out, offset + 28, import_count as u32);
    write_u32(out, offset + 56, indirect_symbols_off);
    write_u32(out, offset + 60, indirect_symbols_count);
    80
}

fn phase12_write_macho_build_version_command(out: &mut [u8], offset: usize) {
    write_u32(out, offset, 0x32);
    write_u32(out, offset + 4, 24);
    write_u32(out, offset + 8, 1);
    write_u32(out, offset + 12, 11 << 16);
    write_u32(out, offset + 16, 14 << 16);
    write_u32(out, offset + 20, 0);
}

fn phase12_write_macho_main_command(out: &mut [u8], offset: usize, entryoff: u64) {
    write_u32(out, offset, 0x80000028);
    write_u32(out, offset + 4, 24);
    write_u64(out, offset + 8, entryoff);
    write_u64(out, offset + 16, 0);
}

fn phase12_write_macho_symtab_command(
    out: &mut [u8],
    offset: usize,
    symoff: u32,
    nsyms: u32,
    stroff: u32,
    strsize: u32,
) -> usize {
    write_u32(out, offset, 0x02);
    write_u32(out, offset + 4, 24);
    write_u32(out, offset + 8, symoff);
    write_u32(out, offset + 12, nsyms);
    write_u32(out, offset + 16, stroff);
    write_u32(out, offset + 20, strsize);
    24
}

fn phase12_write_macho_code_signature_command(
    out: &mut [u8],
    offset: usize,
    dataoff: u32,
    datasize: u32,
) -> usize {
    write_u32(out, offset, 0x1d);
    write_u32(out, offset + 4, 16);
    write_u32(out, offset + 8, dataoff);
    write_u32(out, offset + 12, datasize);
    16
}

fn phase12_macho_string_command_size(name: &str) -> usize {
    align_to(24 + name.len() + 1, 8)
}

fn phase12_write_macho_string_command(
    out: &mut [u8],
    offset: usize,
    cmd: u32,
    name: &str,
) -> usize {
    let size = phase12_macho_string_command_size(name);
    write_u32(out, offset, cmd);
    write_u32(out, offset + 4, size as u32);
    write_u32(out, offset + 8, 24);
    if cmd == 0x0c {
        write_u32(out, offset + 12, 2);
        write_u32(out, offset + 16, 0);
        write_u32(out, offset + 20, 0);
    }
    let start = offset + 24;
    out[start..start + name.len()].copy_from_slice(name.as_bytes());
    size
}

fn phase12_write_macho_segment64(
    out: &mut [u8],
    offset: usize,
    name: &str,
    vmaddr: u64,
    vmsize: u64,
    fileoff: u64,
    filesize: u64,
    maxprot: u32,
    initprot: u32,
    nsects: u32,
) {
    write_u32(out, offset, 0x19);
    write_u32(out, offset + 4, 72 + nsects * 80);
    phase12_write_fixed_name(out, offset + 8, 16, name);
    write_u64(out, offset + 24, vmaddr);
    write_u64(out, offset + 32, vmsize);
    write_u64(out, offset + 40, fileoff);
    write_u64(out, offset + 48, filesize);
    write_u32(out, offset + 56, maxprot);
    write_u32(out, offset + 60, initprot);
    write_u32(out, offset + 64, nsects);
    write_u32(out, offset + 68, 0);
}

fn phase12_write_macho_text_segment(
    out: &mut [u8],
    offset: usize,
    vmaddr: u64,
    vmsize: u64,
    filesize: usize,
    text_addr: u64,
    text_len: usize,
    text_offset: usize,
    text_align: usize,
    stubs_addr: u64,
    stubs_len: usize,
    stubs_offset: usize,
    stub_size: usize,
    const_addr: Option<u64>,
    const_len: usize,
    const_offset: usize,
    const_align: usize,
) {
    let nsects = 1 + u32::from(stubs_len > 0) + u32::from(const_len > 0);
    phase12_write_macho_segment64(
        out,
        offset,
        "__TEXT",
        vmaddr,
        vmsize,
        0,
        filesize as u64,
        5,
        5,
        nsects,
    );
    let mut section = offset + 72;
    phase12_write_macho_section64(
        out,
        section,
        "__text",
        "__TEXT",
        text_addr,
        text_len,
        text_offset,
        text_align.max(1).trailing_zeros(),
        0x80000400,
        0,
        0,
    );
    section += 80;
    if stubs_len > 0 {
        phase12_write_macho_section64(
            out,
            section,
            "__stubs",
            "__TEXT",
            stubs_addr,
            stubs_len,
            stubs_offset,
            1,
            0x80000408,
            0,
            stub_size as u32,
        );
        section += 80;
    }
    if const_len > 0 {
        phase12_write_macho_section64(
            out,
            section,
            "__const",
            "__TEXT",
            const_addr.unwrap_or(vmaddr),
            const_len,
            const_offset,
            const_align.max(1).trailing_zeros(),
            0,
            0,
            0,
        );
    }
}

fn phase12_write_macho_data_segment(
    out: &mut [u8],
    offset: usize,
    vmaddr: u64,
    vmsize: u64,
    fileoff: usize,
    filesize: usize,
    data_addr: u64,
    data_len: usize,
    data_offset: usize,
    data_align: usize,
    la_ptr_addr: u64,
    la_ptr_len: usize,
    la_ptr_offset: usize,
    bss_addr: Option<u64>,
    bss_len: usize,
    bss_align: usize,
    section_count: usize,
) {
    phase12_write_macho_segment64(
        out,
        offset,
        "__DATA",
        vmaddr,
        vmsize,
        fileoff as u64,
        filesize as u64,
        3,
        3,
        section_count as u32,
    );
    let mut section = offset + 72;
    if data_len > 0 {
        phase12_write_macho_section64(
            out,
            section,
            "__data",
            "__DATA",
            data_addr,
            data_len,
            data_offset,
            data_align.max(1).trailing_zeros(),
            0,
            0,
            0,
        );
        section += 80;
    }
    if la_ptr_len > 0 {
        phase12_write_macho_section64(
            out,
            section,
            "__la_symbol_ptr",
            "__DATA",
            la_ptr_addr,
            la_ptr_len,
            la_ptr_offset,
            3,
            0x7,
            0,
            0,
        );
        section += 80;
    }
    if bss_len > 0 {
        phase12_write_macho_section64(
            out,
            section,
            "__bss",
            "__DATA",
            bss_addr.unwrap_or(vmaddr),
            bss_len,
            0,
            bss_align.max(1).trailing_zeros(),
            0x1,
            0,
            0,
        );
    }
}

fn phase12_write_macho_section64(
    out: &mut [u8],
    offset: usize,
    sectname: &str,
    segname: &str,
    addr: u64,
    size: usize,
    fileoff: usize,
    align: u32,
    flags: u32,
    reserved1: u32,
    reserved2: u32,
) {
    phase12_write_fixed_name(out, offset, 16, sectname);
    phase12_write_fixed_name(out, offset + 16, 16, segname);
    write_u64(out, offset + 32, addr);
    write_u64(out, offset + 40, size as u64);
    write_u32(out, offset + 48, fileoff as u32);
    write_u32(out, offset + 52, align);
    write_u32(out, offset + 56, 0);
    write_u32(out, offset + 60, 0);
    write_u32(out, offset + 64, flags);
    write_u32(out, offset + 68, reserved1);
    write_u32(out, offset + 72, reserved2);
    write_u32(out, offset + 76, 0);
}

fn phase12_write_fixed_name(out: &mut [u8], offset: usize, len: usize, name: &str) {
    let bytes = name.as_bytes();
    let copy_len = bytes.len().min(len);
    out[offset..offset + copy_len].copy_from_slice(&bytes[..copy_len]);
}

fn phase12_archive_object_paths(
    paths: &[String],
    target: &str,
    out: &str,
    output_type: &str,
) -> Result<Value, Box<dyn Error>> {
    if paths.is_empty() {
        return Err("[E_MACHINE_LINK_INPUT_001] archive expects at least one object".into());
    }
    let inputs = phase12_load_link_inputs(paths, target)?;
    let artifact_bytes = phase12_archive_bytes(&inputs, target, output_type)?;
    let artifact_hash = hash_bytes(&artifact_bytes);
    write_output(out, &artifact_bytes)?;
    let map_path = phase12_default_map_path(out);
    let map_text = phase12_map_text(&inputs, target, output_type, &artifact_hash);
    write_output(&map_path, map_text.as_bytes())?;
    let report = phase12_link_report_json(
        &inputs,
        target,
        out,
        output_type,
        "internal",
        &artifact_hash,
        &map_path,
        &hash_string(&map_text),
    );
    write_output(
        &phase12_report_path(out),
        serde_json::to_string_pretty(&report)?.as_bytes(),
    )?;
    print_json(&report)?;
    Ok(report)
}

fn phase12_positional_args(args: &[String]) -> Vec<String> {
    let value_flags = [
        "--target",
        "--out",
        "--map",
        "--format",
        "--profile",
        "--entry",
        "--lane",
    ];
    let mut out = Vec::new();
    let mut skip_next = false;
    for arg in args {
        if skip_next {
            skip_next = false;
            continue;
        }
        if value_flags.contains(&arg.as_str()) {
            skip_next = true;
            continue;
        }
        if arg.starts_with("--") {
            continue;
        }
        out.push(arg.clone());
    }
    out
}

fn phase12_emit_source_to_temp_object(
    source: &str,
    target: &str,
    purpose: &str,
) -> Result<String, Box<dyn Error>> {
    let audit = audit_machine_file(source)?;
    if audit.has_errors() {
        return Err(diagnostics_summary(&audit.diagnostics).into());
    }
    let format = object_format_for_target(target, &audit);
    let bytes = emit_object_bytes(&audit, format)?;
    let stem = Path::new(source)
        .file_stem()
        .and_then(|stem| stem.to_str())
        .unwrap_or("machine");
    let safe_target = target.replace(['/', '\\', ':'], "_");
    let ext = phase12_object_ext(format);
    let sequence = PHASE12_TEMP_OBJECT_SEQ.fetch_add(1, Ordering::Relaxed);
    let object_path = format!(
        "target/tmp/phase12_{purpose}_{}_{}_{stem}_{safe_target}.{ext}",
        std::process::id(),
        sequence
    );
    write_output(&object_path, &bytes)?;
    phase12_write_object_metadata(&object_path, source, target, format, &audit)?;
    Ok(object_path)
}

pub(crate) fn emit_machine_source_object_to_path(
    source: &str,
    target: &str,
    out: &str,
) -> Result<(), Box<dyn Error>> {
    let audit = audit_machine_file(source)?;
    if audit.has_errors() {
        return Err(diagnostics_summary(&audit.diagnostics).into());
    }
    let format = object_format_for_target(target, &audit);
    let bytes = emit_object_bytes(&audit, format)?;
    write_output(out, &bytes)?;
    phase12_write_object_metadata(out, source, target, format, &audit)?;
    Ok(())
}

pub(crate) fn machine_source_declared_target(source: &str) -> Result<String, Box<dyn Error>> {
    let audit = audit_machine_file(source)?;
    if audit.has_errors() {
        return Err(diagnostics_summary(&audit.diagnostics).into());
    }
    let arch = audit_arch(&audit);
    let abi = audit
        .target
        .get("abi")
        .map(String::as_str)
        .unwrap_or("sysv64");
    let object = audit
        .target
        .get("object")
        .map(String::as_str)
        .unwrap_or("elf64");
    let target = match (arch, abi, object) {
        ("x86_64", "win64", _) | ("x86_64", _, "coff") => "x86_64-pc-windows-msvc",
        ("x86_64", _, "macho") => "x86_64-apple-darwin",
        ("x86_64", _, _) => "x86_64-unknown-linux-gnu",
        ("aarch64", _, "macho") => "aarch64-apple-darwin",
        ("aarch64", _, _) => "aarch64-unknown-linux-gnu",
        ("armv7" | "armv7em", _, _) => "armv7a-unknown-none-eabi",
        ("riscv64", _, _) => "riscv64-unknown-elf",
        ("riscv32", _, _) => "riscv32imac-unknown-elf",
        ("i386", _, _) => "i386-unknown-linux-gnu",
        ("wasm32", _, _) => "wasm32-unknown-unknown",
        (other, _, _) => {
            return Err(format!(
                "[E_MACHINE_LINK_TARGET_001] cannot infer build target for machine arch '{other}'"
            )
            .into())
        }
    };
    Ok(target.to_string())
}

pub(crate) fn link_machine_object_paths_to_os_executable_silent(
    paths: &[String],
    target: &str,
    out: &str,
    map: Option<&str>,
) -> Result<Value, Box<dyn Error>> {
    if paths.is_empty() {
        return Err("[E_MACHINE_LINK_INPUT_001] link expects at least one object".into());
    }
    let inputs = phase12_load_link_inputs(paths, target)?;
    let expected_format = phase12_expected_format(target);
    if !matches!(expected_format, "elf64" | "elf32" | "coff" | "macho") {
        return Err(format!(
            "[E_MACHINE_LINK_TARGET_001] OS executable finalizer does not support {expected_format}"
        )
        .into());
    }
    phase12_link_final_executable_silent(&inputs, target, out, map, expected_format)
}

pub(crate) fn link_machine_object_paths_to_os_executable_with_missing_symbol_policy_silent(
    paths: &[String],
    target: &str,
    out: &str,
    map: Option<&str>,
    policy: ncc_ir::BackendMissingSymbolPolicyIR,
    unresolved_symbols: &[String],
) -> Result<Value, Box<dyn Error>> {
    if matches!(policy, ncc_ir::BackendMissingSymbolPolicyIR::Diagnose) {
        return link_machine_object_paths_to_os_executable_silent(paths, target, out, map);
    }
    if paths.is_empty() {
        return Err("[E_MACHINE_LINK_INPUT_001] link expects at least one object".into());
    }
    let inputs = phase12_load_link_inputs(paths, target)?;
    let expected_format = phase12_expected_format(target);
    if !matches!(expected_format, "elf64" | "elf32" | "coff" | "macho") {
        return Err(format!(
            "[E_MACHINE_LINK_TARGET_001] OS executable finalizer does not support {expected_format}"
        )
        .into());
    }
    let requested_null_symbols = unresolved_symbols.iter().cloned().collect::<BTreeSet<_>>();
    phase12_link_final_executable_impl_with_null_symbols(
        &inputs,
        target,
        out,
        map,
        expected_format,
        false,
        true,
        &requested_null_symbols,
    )
}

pub(crate) fn link_machine_object_paths_to_kernel_artifact_silent(
    paths: &[String],
    target: &str,
    out: &str,
    map: Option<&str>,
) -> Result<Value, Box<dyn Error>> {
    if paths.is_empty() {
        return Err("[E_MACHINE_LINK_INPUT_001] kernel link expects at least one object".into());
    }
    let inputs = phase12_load_link_inputs(paths, target)?;
    let expected_format = phase12_expected_format(target);
    if target == "x86_64-unknown-none" {
        let mut report = phase12_link_final_executable_silent(&inputs, target, out, map, "elf64")?;
        if let Some(object) = report.as_object_mut() {
            object.insert("kernel_profile".into(), json!(true));
            object.insert("kernel_link_artifact".into(), json!(false));
            object.insert("boot_image".into(), json!(false));
            object.insert("artifact_format".into(), json!("elf64"));
            object.insert("artifact_magic".into(), json!("ELF64_ET_EXEC"));
            object.insert(
                "phase12_final_artifact".into(),
                json!("kernel_profile_freestanding_elf64"),
            );
            object.insert(
                "truth_boundary".into(),
                json!({
                    "system_loader_executable": false,
                    "boot_image": false,
                    "kernel_link_artifact": false,
                    "kernel_elf64_executable": true,
                    "full_boot_protocol": false,
                    "missing_bootloader_is_not_faked": true
                }),
            );
        }
        write_output(
            &phase12_report_path(out),
            serde_json::to_string_pretty(&report)?.as_bytes(),
        )?;
        return Ok(report);
    }
    if target == "i386-unknown-none-elf" {
        let mut report = phase12_link_final_executable_silent(&inputs, target, out, map, "elf32")?;
        if let Some(object) = report.as_object_mut() {
            object.insert("kernel_profile".into(), json!(true));
            object.insert("kernel_link_artifact".into(), json!(false));
            object.insert("boot_image".into(), json!(false));
            object.insert("artifact_format".into(), json!("elf32"));
            object.insert("artifact_magic".into(), json!("ELF32_ET_EXEC"));
            object.insert(
                "phase12_final_artifact".into(),
                json!("kernel_profile_freestanding_elf32"),
            );
            object.insert(
                "truth_boundary".into(),
                json!({
                    "system_loader_executable": false,
                    "boot_image": false,
                    "kernel_link_artifact": false,
                    "kernel_elf32_executable": true,
                    "full_boot_protocol": false,
                    "missing_bootloader_is_not_faked": true
                }),
            );
        }
        write_output(
            &phase12_report_path(out),
            serde_json::to_string_pretty(&report)?.as_bytes(),
        )?;
        return Ok(report);
    }
    if matches!(target, "armv7em-none-eabi" | "thumbv7em-none-eabi") {
        return phase12_link_cortex_m_kernel_firmware(&inputs, target, out, map);
    }
    if matches!(
        target,
        "armv7a-unknown-none-eabi" | "armv7-unknown-none-eabi"
    ) {
        let mut report = phase12_link_final_executable_silent(&inputs, target, out, map, "elf32")?;
        if let Some(object) = report.as_object_mut() {
            object.insert("kernel_profile".into(), json!(true));
            object.insert("machine_coordinated".into(), json!(true));
            object.insert("kernel_link_artifact".into(), json!(false));
            object.insert("boot_image".into(), json!(false));
            object.insert("artifact_format".into(), json!("elf32-arm-eabi5"));
            object.insert("artifact_magic".into(), json!("ELF32_ARM_ET_EXEC"));
            object.insert(
                "phase12_final_artifact".into(),
                json!("kernel_profile_armv7a_freestanding_elf32"),
            );
            object.insert(
                "truth_boundary".into(),
                json!({
                    "system_loader_executable": false,
                    "kernel_elf32_executable": true,
                    "arm_eabi_version": 5,
                    "thumb_entry_state_bit": true,
                    "firmware_adapter_required_for_physical_boot": true
                }),
            );
        }
        write_output(
            &phase12_report_path(out),
            serde_json::to_string_pretty(&report)?.as_bytes(),
        )?;
        return Ok(report);
    }
    if matches!(
        target,
        "aarch64-unknown-none" | "riscv64-unknown-elf" | "riscv32imac-unknown-elf"
    ) {
        let format = if target == "riscv32imac-unknown-elf" {
            "elf32"
        } else {
            "elf64"
        };
        let mut report = phase12_link_final_executable_silent(&inputs, target, out, map, format)?;
        if let Some(object) = report.as_object_mut() {
            object.insert("kernel_profile".into(), json!(true));
            object.insert("kernel_link_artifact".into(), json!(false));
            object.insert("boot_image".into(), json!(true));
            object.insert("artifact_format".into(), json!(format));
            object.insert(
                "artifact_magic".into(),
                json!(if format == "elf32" {
                    "ELF32_ET_EXEC"
                } else {
                    "ELF64_ET_EXEC"
                }),
            );
            object.insert(
                "phase12_final_artifact".into(),
                json!("kernel_profile_qemu_virt_elf"),
            );
            object.insert(
                "truth_boundary".into(),
                json!({
                    "system_loader_executable": false,
                    "boot_image": true,
                    "kernel_link_artifact": false,
                    "kernel_elf_executable": true,
                    "qemu_virt_loader_contract": true,
                    "missing_bootloader_is_not_faked": true
                }),
            );
        }
        write_output(
            &phase12_report_path(out),
            serde_json::to_string_pretty(&report)?.as_bytes(),
        )?;
        return Ok(report);
    }
    let hosted_loader_target = matches!(expected_format, "elf64" | "coff" | "macho")
        && !target.contains("unknown-none")
        && !target.contains("unknown-elf")
        && !target.contains("riscv")
        && !target.contains("wasm32");
    if hosted_loader_target {
        let mut report =
            phase12_link_final_executable_silent(&inputs, target, out, map, expected_format)?;
        if let Some(object) = report.as_object_mut() {
            object.insert("kernel_profile".into(), json!(true));
            object.insert("kernel_link_artifact".into(), json!(false));
            object.insert("boot_image".into(), json!(false));
            object.insert("artifact_format".into(), json!(expected_format));
            object.insert(
                "phase12_final_artifact".into(),
                json!("kernel_profile_system_loader_executable"),
            );
            object.insert(
                "truth_boundary".into(),
                json!({
                    "system_loader_executable": true,
                    "boot_image": false,
                    "kernel_link_artifact": false,
                    "full_boot_protocol": false,
                    "missing_bootloader_is_not_faked": true
                }),
            );
        }
        write_output(
            &phase12_report_path(out),
            serde_json::to_string_pretty(&report)?.as_bytes(),
        )?;
        return Ok(report);
    }

    let artifact_bytes = phase12_artifact_bytes(&inputs, target, "kernel_image", "kernel_profile")?;
    let artifact_hash = hash_bytes(&artifact_bytes);
    write_output(out, &artifact_bytes)?;
    let map_path = map
        .map(ToString::to_string)
        .unwrap_or_else(|| phase12_default_map_path(out));
    let map_text = phase12_map_text(&inputs, target, "kernel_image", &artifact_hash);
    write_output(&map_path, map_text.as_bytes())?;
    let mut report = phase12_link_report_json(
        &inputs,
        target,
        out,
        "kernel_image",
        "kernel_profile",
        &artifact_hash,
        &map_path,
        &hash_string(&map_text),
    );
    if let Some(object) = report.as_object_mut() {
        object.insert("kernel_profile".into(), json!(true));
        object.insert("kernel_link_artifact".into(), json!(true));
        object.insert("boot_image".into(), json!(false));
        object.insert("artifact_format".into(), json!(expected_format));
        object.insert("artifact_magic".into(), json!("NCCLINK12"));
        object.insert(
            "phase12_final_artifact".into(),
            json!("kernel_profile_link_artifact"),
        );
        object.insert(
            "truth_boundary".into(),
            json!({
                "system_loader_executable": false,
                "boot_image": false,
                "kernel_link_artifact": true,
                "full_boot_protocol": false,
                "missing_bootloader_is_not_faked": true
            }),
        );
    }
    write_output(
        &phase12_report_path(out),
        serde_json::to_string_pretty(&report)?.as_bytes(),
    )?;
    Ok(report)
}

struct Phase12CortexMStartup {
    bytes: Vec<u8>,
    park_offset: usize,
}

fn phase12_thumb_append(
    bytes: &mut Vec<u8>,
    instruction: ThumbInstruction,
) -> Result<usize, Box<dyn Error>> {
    let offset = bytes.len();
    bytes.extend_from_slice(&encode_thumb(&[instruction])?);
    Ok(offset)
}

fn phase12_thumb_append_address(
    bytes: &mut Vec<u8>,
    register: ThumbRegister,
    address: u32,
) -> Result<(), Box<dyn Error>> {
    phase12_thumb_append(
        bytes,
        ThumbInstruction::MoveWide {
            destination: register,
            immediate: address as u16,
        },
    )?;
    phase12_thumb_append(
        bytes,
        ThumbInstruction::MoveTop {
            destination: register,
            immediate: (address >> 16) as u16,
        },
    )?;
    Ok(())
}

fn phase12_thumb_patch(
    bytes: &mut [u8],
    offset: usize,
    instruction: ThumbInstruction,
) -> Result<(), Box<dyn Error>> {
    let encoded = encode_thumb(&[instruction])?;
    let end = offset
        .checked_add(encoded.len())
        .ok_or("[E_MACHINE_FIRMWARE_LAYOUT_001] Thumb patch offset overflow")?;
    if end > bytes.len() {
        return Err("[E_MACHINE_FIRMWARE_LAYOUT_001] Thumb patch exceeds startup bytes".into());
    }
    bytes[offset..end].copy_from_slice(&encoded);
    Ok(())
}

fn phase12_thumb_local_displacement(source: usize, target: usize) -> Result<i32, Box<dyn Error>> {
    i32::try_from(target as i64 - (source as i64 + 4))
        .map_err(|_| "[E_MACHINE_FIRMWARE_RANGE_001] local Thumb branch exceeds i32".into())
}

fn phase12_cortex_m_startup_bytes(
    startup_va: u32,
    data_load: u32,
    data_start: u32,
    data_end: u32,
    bss_start: u32,
    bss_end: u32,
    kmain_va: u32,
) -> Result<Phase12CortexMStartup, Box<dyn Error>> {
    let mut bytes = Vec::new();
    phase12_thumb_append(&mut bytes, ThumbInstruction::DisableInterrupts)?;
    phase12_thumb_append_address(&mut bytes, ThumbRegister::R0, data_load)?;
    phase12_thumb_append_address(&mut bytes, ThumbRegister::R1, data_start)?;
    phase12_thumb_append_address(&mut bytes, ThumbRegister::R2, data_end)?;

    let copy_check = bytes.len();
    phase12_thumb_append(
        &mut bytes,
        ThumbInstruction::CompareRegister {
            left: ThumbRegister::R1,
            right: ThumbRegister::R2,
        },
    )?;
    let copy_done_branch = phase12_thumb_append(&mut bytes, ThumbInstruction::Nop)?;
    phase12_thumb_append(
        &mut bytes,
        ThumbInstruction::LoadByte {
            target: ThumbRegister::R3,
            base: ThumbRegister::R0,
            offset: 0,
        },
    )?;
    phase12_thumb_append(
        &mut bytes,
        ThumbInstruction::StoreByte {
            source: ThumbRegister::R3,
            base: ThumbRegister::R1,
            offset: 0,
        },
    )?;
    phase12_thumb_append(
        &mut bytes,
        ThumbInstruction::AddImmediate {
            register: ThumbRegister::R0,
            immediate: 1,
        },
    )?;
    phase12_thumb_append(
        &mut bytes,
        ThumbInstruction::AddImmediate {
            register: ThumbRegister::R1,
            immediate: 1,
        },
    )?;
    let copy_back_branch = phase12_thumb_append(&mut bytes, ThumbInstruction::Nop)?;

    let zero_setup = bytes.len();
    phase12_thumb_append_address(&mut bytes, ThumbRegister::R1, bss_start)?;
    phase12_thumb_append_address(&mut bytes, ThumbRegister::R2, bss_end)?;
    phase12_thumb_append(
        &mut bytes,
        ThumbInstruction::MovImmediate {
            destination: ThumbRegister::R3,
            immediate: 0,
        },
    )?;
    let zero_check = bytes.len();
    phase12_thumb_append(
        &mut bytes,
        ThumbInstruction::CompareRegister {
            left: ThumbRegister::R1,
            right: ThumbRegister::R2,
        },
    )?;
    let zero_done_branch = phase12_thumb_append(&mut bytes, ThumbInstruction::Nop)?;
    phase12_thumb_append(
        &mut bytes,
        ThumbInstruction::StoreByte {
            source: ThumbRegister::R3,
            base: ThumbRegister::R1,
            offset: 0,
        },
    )?;
    phase12_thumb_append(
        &mut bytes,
        ThumbInstruction::AddImmediate {
            register: ThumbRegister::R1,
            immediate: 1,
        },
    )?;
    let zero_back_branch = phase12_thumb_append(&mut bytes, ThumbInstruction::Nop)?;

    let call_kernel = bytes.len();
    phase12_thumb_append(&mut bytes, ThumbInstruction::DataMemoryBarrier)?;
    phase12_thumb_append(&mut bytes, ThumbInstruction::InstructionSyncBarrier)?;
    phase12_thumb_append(
        &mut bytes,
        ThumbInstruction::MovImmediate {
            destination: ThumbRegister::R0,
            immediate: 0,
        },
    )?;
    let call_offset = phase12_thumb_append(&mut bytes, ThumbInstruction::BranchLink { offset: 0 })?;
    phase12_thumb_append(&mut bytes, ThumbInstruction::DisableInterrupts)?;
    let park_offset = bytes.len();
    phase12_thumb_append(&mut bytes, ThumbInstruction::WaitForInterrupt)?;
    let park_branch = phase12_thumb_append(&mut bytes, ThumbInstruction::Nop)?;

    phase12_thumb_patch(
        &mut bytes,
        copy_done_branch,
        ThumbInstruction::BranchConditional {
            condition: ThumbCondition::Cs,
            offset: i16::try_from(phase12_thumb_local_displacement(
                copy_done_branch,
                zero_setup,
            )?)
            .map_err(|_| "[E_MACHINE_FIRMWARE_RANGE_001] copy branch exceeds Thumb16")?,
        },
    )?;
    phase12_thumb_patch(
        &mut bytes,
        copy_back_branch,
        ThumbInstruction::Branch {
            offset: phase12_thumb_local_displacement(copy_back_branch, copy_check)?,
        },
    )?;
    phase12_thumb_patch(
        &mut bytes,
        zero_done_branch,
        ThumbInstruction::BranchConditional {
            condition: ThumbCondition::Cs,
            offset: i16::try_from(phase12_thumb_local_displacement(
                zero_done_branch,
                call_kernel,
            )?)
            .map_err(|_| "[E_MACHINE_FIRMWARE_RANGE_001] zero branch exceeds Thumb16")?,
        },
    )?;
    phase12_thumb_patch(
        &mut bytes,
        zero_back_branch,
        ThumbInstruction::Branch {
            offset: phase12_thumb_local_displacement(zero_back_branch, zero_check)?,
        },
    )?;
    let call_pc = startup_va
        .checked_add(call_offset as u32)
        .and_then(|value| value.checked_add(4))
        .ok_or("[E_MACHINE_FIRMWARE_LAYOUT_001] kmain call address overflow")?;
    let call_displacement = i32::try_from((kmain_va & !1) as i64 - call_pc as i64)
        .map_err(|_| "[E_MACHINE_FIRMWARE_RANGE_001] kmain is outside Thumb BL range")?;
    phase12_thumb_patch(
        &mut bytes,
        call_offset,
        ThumbInstruction::BranchLink {
            offset: call_displacement,
        },
    )?;
    phase12_thumb_patch(
        &mut bytes,
        park_branch,
        ThumbInstruction::Branch {
            offset: phase12_thumb_local_displacement(park_branch, park_offset)?,
        },
    )?;

    Ok(Phase12CortexMStartup { bytes, park_offset })
}

fn phase12_link_cortex_m_kernel_firmware(
    inputs: &[Phase12LinkInput],
    target: &str,
    out: &str,
    map: Option<&str>,
) -> Result<Value, Box<dyn Error>> {
    const FLASH_BASE: u32 = 0x0800_0000;
    const SRAM_BASE: u32 = 0x2000_0000;
    const INITIAL_STACK: u32 = 0x2008_0000;
    const VECTOR_BYTES: usize = 16 * 4;

    let image = phase12_link_image(inputs)?;
    if image.arch != "armv7em" {
        return Err(format!(
            "[E_MACHINE_FIRMWARE_TARGET_001] Cortex-M finalizer received architecture '{}'",
            image.arch
        )
        .into());
    }
    if !image.dynamic_imports.is_empty() {
        return Err(format!(
            "[E_MACHINE_FIRMWARE_IMPORT_001] Cortex-M firmware must be self-contained; unresolved imports: {}",
            image.dynamic_imports.join(", ")
        )
        .into());
    }

    let startup_va = FLASH_BASE + VECTOR_BYTES as u32;
    let sizing = phase12_cortex_m_startup_bytes(
        startup_va, FLASH_BASE, SRAM_BASE, SRAM_BASE, SRAM_BASE, SRAM_BASE, startup_va,
    )?;
    let text_offset = align_to(VECTOR_BYTES + sizing.bytes.len(), 16);
    let text_va = FLASH_BASE as u64 + text_offset as u64;
    let rodata_offset = align_to(text_offset + image.text.len(), 8);
    let rodata_va = FLASH_BASE as u64 + rodata_offset as u64;
    let data_load_offset = align_to(rodata_offset + image.rodata.len(), 8);
    let data_load_va = FLASH_BASE as u64 + data_load_offset as u64;
    let data_va = SRAM_BASE as u64;
    let bss_va = align_to(
        SRAM_BASE as usize + image.data.len(),
        image.bss_align.max(1),
    ) as u64;
    let bss_end = bss_va
        .checked_add(image.bss_size as u64)
        .ok_or("[E_MACHINE_FIRMWARE_LAYOUT_001] Cortex-M bss address overflow")?;
    if bss_end > INITIAL_STACK as u64 {
        return Err(format!(
            "[E_MACHINE_FIRMWARE_RAM_001] data+bss end {bss_end:#010x} collides with initial stack {INITIAL_STACK:#010x}"
        )
        .into());
    }

    let symbol_vas = phase12_linked_symbol_vas(
        &image,
        text_va,
        Some(rodata_va),
        Some(data_va),
        Some(bss_va),
        &BTreeMap::new(),
    );
    let kmain_va = symbol_vas.get(&image.entry).copied().ok_or_else(|| {
        format!(
            "[E_MACHINE_LINK_ENTRY_MISSING_001] Cortex-M entry symbol '{}' was not laid out",
            image.entry
        )
    })?;
    let mut text = image.text.clone();
    let mut rodata = image.rodata.clone();
    let mut data = image.data.clone();
    phase12_apply_linked_relocations(
        &mut text,
        &mut rodata,
        &mut data,
        &image,
        text_va,
        Some(rodata_va),
        Some(data_va),
        Some(bss_va),
        &symbol_vas,
        &HashMap::new(),
        &HashMap::new(),
    )?;
    let startup = phase12_cortex_m_startup_bytes(
        startup_va,
        u32::try_from(data_load_va)?,
        u32::try_from(data_va)?,
        u32::try_from(data_va + data.len() as u64)?,
        u32::try_from(bss_va)?,
        u32::try_from(bss_end)?,
        u32::try_from(kmain_va)?,
    )?;
    if startup.bytes.len() != sizing.bytes.len() {
        return Err("[E_MACHINE_FIRMWARE_LAYOUT_001] Cortex-M startup size drifted".into());
    }

    let firmware_len = data_load_offset
        .checked_add(data.len())
        .ok_or("[E_MACHINE_FIRMWARE_LAYOUT_001] Cortex-M flash image overflow")?;
    let mut firmware_bytes = vec![0_u8; firmware_len];
    firmware_bytes[..4].copy_from_slice(&INITIAL_STACK.to_le_bytes());
    let reset_vector = startup_va | 1;
    firmware_bytes[4..8].copy_from_slice(&reset_vector.to_le_bytes());
    let default_vector = startup_va
        .checked_add(startup.park_offset as u32)
        .ok_or("[E_MACHINE_FIRMWARE_LAYOUT_001] default handler address overflow")?
        | 1;
    for slot in 2..16 {
        let offset = slot * 4;
        firmware_bytes[offset..offset + 4].copy_from_slice(&default_vector.to_le_bytes());
    }
    firmware_bytes[VECTOR_BYTES..VECTOR_BYTES + startup.bytes.len()]
        .copy_from_slice(&startup.bytes);
    firmware_bytes[text_offset..text_offset + text.len()].copy_from_slice(&text);
    firmware_bytes[rodata_offset..rodata_offset + rodata.len()].copy_from_slice(&rodata);
    firmware_bytes[data_load_offset..data_load_offset + data.len()].copy_from_slice(&data);

    write_output(out, &firmware_bytes)?;
    let hex_path = PathBuf::from(out).with_extension("hex");
    let firmware = ncc_machine::CortexMFirmware {
        flash_base: FLASH_BASE,
        initial_stack: INITIAL_STACK,
        reset_vector,
        bytes: firmware_bytes.clone(),
    };
    write_output(
        hex_path.to_string_lossy().as_ref(),
        firmware.intel_hex().as_bytes(),
    )?;

    let artifact_hash = hash_bytes(&firmware_bytes);
    let map_path = map
        .map(ToString::to_string)
        .unwrap_or_else(|| phase12_default_map_path(out));
    let map_text = format!(
        "nC Cortex-M firmware map\ntarget={target}\nflash_base={FLASH_BASE:#010x}\nvector_table={FLASH_BASE:#010x} size={VECTOR_BYTES}\nreset={reset_vector:#010x}\ndefault_handler={default_vector:#010x}\nstartup={startup_va:#010x} size={}\ntext={text_va:#010x} size={}\nrodata={rodata_va:#010x} size={}\ndata_load={data_load_va:#010x} size={}\ndata_runtime={data_va:#010x}..{:#010x}\nbss={bss_va:#010x}..{bss_end:#010x}\ninitial_stack={INITIAL_STACK:#010x}\nkmain={kmain_va:#010x}\nsha256={artifact_hash}\n",
        startup.bytes.len(),
        text.len(),
        rodata.len(),
        data.len(),
        data_va + data.len() as u64,
    );
    write_output(&map_path, map_text.as_bytes())?;
    let mut report = phase12_link_report_json(
        inputs,
        target,
        out,
        "firmware",
        "cortex_m_physical_loader",
        &artifact_hash,
        &map_path,
        &hash_string(&map_text),
    );
    if let Some(object) = report.as_object_mut() {
        object.insert("kernel_profile".into(), json!(true));
        object.insert("machine_coordinated".into(), json!(true));
        object.insert("kernel_link_artifact".into(), json!(false));
        object.insert("boot_image".into(), json!(true));
        object.insert("artifact_format".into(), json!("cortex-m-flat-binary"));
        object.insert("artifact_magic".into(), json!("CORTEX_M_VECTOR_TABLE"));
        object.insert("os_loader_executable".into(), json!(false));
        object.insert("internal_container_used_for_final_exe".into(), json!(false));
        object.insert(
            "phase12_final_artifact".into(),
            json!("cortex_m_physical_firmware_image"),
        );
        object.insert(
            "hex_artifact".into(),
            json!({
                "path": hex_path,
                "sha256": hash_string(&firmware.intel_hex()),
                "format": "intel-hex"
            }),
        );
        object.insert("firmware_evidence".into(), json!({
            "flash_base": FLASH_BASE,
            "sram_base": SRAM_BASE,
            "sram_bytes": INITIAL_STACK - SRAM_BASE,
            "initial_stack": INITIAL_STACK,
            "reset_vector": reset_vector,
            "default_handler": default_vector,
            "startup": {"address": startup_va, "bytes": startup.bytes.len()},
            "text": {"address": text_va, "bytes": text.len()},
            "rodata": {"address": rodata_va, "bytes": rodata.len()},
            "data": {"load_address": data_load_va, "runtime_address": data_va, "bytes": data.len()},
            "bss": {"address": bss_va, "bytes": image.bss_size},
            "kmain": kmain_va,
            "data_copy_loop": true,
            "bss_zero_loop": true,
            "interrupts_disabled_during_startup": true,
            "return_parks_with_wfi": true,
            "relocations_applied": image.relocations.len(),
            "dynamic_imports": image.dynamic_imports,
            "status": "closed_physical_image_bytes"
        }));
        object.insert(
            "truth_boundary".into(),
            json!({
                "physical_firmware_image": true,
                "qemu_required": false,
                "host_byte_validation": true,
                "hardware_execution_requires_matching_cortex_m_board_and_flash_transport": true,
                "physical_board_execution_performed_in_this_run": false
            }),
        );
    }
    write_output(
        &phase12_report_path(out),
        serde_json::to_string_pretty(&report)?.as_bytes(),
    )?;
    Ok(report)
}

fn phase12_object_ext(format: &str) -> &'static str {
    match format {
        "coff" => "obj",
        "wasm" => "wasm",
        _ => "o",
    }
}

fn phase12_object_metadata_path(path: &str) -> String {
    format!("{path}.machine-link-meta.json")
}

fn phase12_write_object_metadata(
    object_path: &str,
    source: &str,
    target: &str,
    object_format: &str,
    audit: &MachineAudit,
) -> Result<(), Box<dyn Error>> {
    let dynamic_imports = phase12_dynamic_import_symbols_from_audit(audit);
    let link_unit = phase12_object_unit_from_audit(audit, object_format);
    let payload = json!({
        "schema": "nc.machine.phase12.object_metadata.v1",
        "source": source,
        "object": object_path,
        "target": target,
        "object_format": object_format,
        "symbols": audit.symbols.iter().cloned().collect::<Vec<_>>(),
        "externs": audit.externs.iter().cloned().collect::<Vec<_>>(),
        "dynamic_imports": dynamic_imports,
        "calls_to_externs": audit.instructions.iter().filter_map(|inst| {
            let target = inst.operands.first()?;
            if inst.mnemonic == "call" && audit.externs.contains(target) {
                Some(target.clone())
            } else {
                None
            }
        }).collect::<Vec<_>>(),
        "link_unit": phase12_object_unit_json(&link_unit),
        "status": "closed"
    });
    write_output(
        &phase12_object_metadata_path(object_path),
        serde_json::to_string_pretty(&payload)?.as_bytes(),
    )?;
    Ok(())
}

fn phase12_object_unit_from_audit(audit: &MachineAudit, object_format: &str) -> Phase12ObjectUnit {
    let symbol_offsets = phase12_symbol_offsets(audit);
    let data_symbol_offsets = phase12_data_symbol_offsets(audit);
    let mut symbols = Vec::new();
    for name in audit.symbols.iter().chain(audit.routines.iter()) {
        if data_symbol_offsets.contains_key(name) || audit.constants.contains_key(name) {
            continue;
        }
        let offset = symbol_offsets.get(name).copied().unwrap_or(0);
        symbols.push(Phase12ObjectSymbol {
            name: name.clone(),
            section: ".text".to_string(),
            offset,
            global: true,
        });
    }
    for (name, (section, offset)) in data_symbol_offsets {
        if !symbols.iter().any(|symbol| symbol.name == name) {
            symbols.push(Phase12ObjectSymbol {
                name,
                section,
                offset,
                global: true,
            });
        }
    }
    symbols.sort_by(|a, b| a.name.cmp(&b.name));
    symbols.dedup_by(|a, b| a.name == b.name);

    let arch = audit_arch(audit);
    let mut relocations = relocation_ir(audit)
        .into_iter()
        .map(|rel| Phase12ObjectRelocation {
            section: rel.section,
            offset: rel.offset,
            kind: phase12_relocation_kind_name_for_arch(arch, &rel.kind).to_string(),
            symbol: rel.symbol,
            addend: rel.addend,
        })
        .collect::<Vec<_>>();

    for (occurrence, record) in audit.relocation_records.iter().enumerate() {
        let Some(kind) = phase12_explicit_relocation_kind(arch, &record.kind) else {
            continue;
        };
        let Some(symbol) = record.symbol.clone() else {
            continue;
        };
        let offset = record
            .offset
            .or_else(|| infer_machine_relocation_offset(audit, arch, record, occurrence))
            .unwrap_or(0) as usize;
        let section = if record.section.is_empty() {
            ".text".to_string()
        } else {
            record.section.clone()
        };
        let relocation = Phase12ObjectRelocation {
            section,
            offset,
            kind: kind.to_string(),
            symbol,
            addend: record.addend as isize,
        };
        if !relocations.iter().any(|existing| {
            existing.section == relocation.section
                && existing.offset == relocation.offset
                && existing.kind == relocation.kind
                && existing.symbol == relocation.symbol
                && existing.addend == relocation.addend
        }) {
            relocations.push(relocation);
        }
    }

    Phase12ObjectUnit {
        arch: audit_arch(audit).to_string(),
        entry: audit.entry.clone(),
        text: audit.encoded_bytes.clone(),
        text_align: 16,
        rodata: Vec::new(),
        rodata_align: 1,
        data: audit.data_bytes.clone(),
        data_align: if audit.data_bytes.is_empty() { 1 } else { 16 },
        bss_size: audit.bss_size,
        bss_align: if audit.bss_size == 0 { 1 } else { 16 },
        sections: phase12_audit_preserved_sections(audit, object_format),
        symbols,
        relocations,
    }
}

fn phase12_audit_preserved_sections(
    audit: &MachineAudit,
    format: &str,
) -> Vec<Phase12ObjectSection> {
    if !audit_has_debug_unwind(audit) {
        return Vec::new();
    }
    debug_unwind_object_sections(audit, format)
        .into_iter()
        .filter_map(|section| {
            let data = section.bytes?;
            let kind = phase12_section_kind_from_name(&section.name);
            Some(Phase12ObjectSection {
                name: section.name,
                kind: kind.to_string(),
                size: data.len(),
                data,
                align: 8,
            })
        })
        .collect()
}

fn phase12_data_symbol_offsets(audit: &MachineAudit) -> BTreeMap<String, (String, usize)> {
    let mut symbols = BTreeMap::new();
    let mut data_offset = 0_usize;
    let mut bss_offset = 0_usize;
    let incbins = audit
        .incbins
        .iter()
        .map(|item| (item.label.clone(), (item.bytes, item.align)))
        .collect::<BTreeMap<_, _>>();

    for directive in &audit.directives {
        match directive.kind.as_str() {
            "align" if directive.name == ".data" => {
                if let Ok(align) = directive.value.parse::<usize>() {
                    if align != 0 && align.is_power_of_two() {
                        data_offset = align_to(data_offset, align);
                    }
                }
            }
            "db" | "dw" | "dd" | "dq" | "ascii" | "asciz" => {
                if !directive.name.is_empty() && !directive.name.starts_with('.') {
                    symbols.insert(directive.name.clone(), (".data".to_string(), data_offset));
                }
                data_offset =
                    data_offset.saturating_add(phase12_data_directive_len(directive, &incbins));
            }
            "incbin" => {
                let (bytes, align) = incbins.get(&directive.name).copied().unwrap_or((0, 1));
                if align != 0 && align.is_power_of_two() {
                    data_offset = align_to(data_offset, align);
                }
                if !directive.name.is_empty() && !directive.name.starts_with('.') {
                    symbols.insert(directive.name.clone(), (".data".to_string(), data_offset));
                }
                data_offset = data_offset.saturating_add(bytes);
            }
            "resb" | "resw" | "resd" | "resq" if directive.status == "closed_bss" => {
                if !directive.name.is_empty() && !directive.name.starts_with('.') {
                    symbols.insert(directive.name.clone(), (".bss".to_string(), bss_offset));
                }
                bss_offset =
                    bss_offset.saturating_add(directive.value.parse::<usize>().unwrap_or(0));
            }
            _ => {}
        }
    }

    symbols
}

fn phase12_data_directive_len(
    directive: &MachineDirectiveRecord,
    incbins: &BTreeMap<String, (usize, usize)>,
) -> usize {
    match directive.kind.as_str() {
        "db" => phase12_int_list_element_count(&directive.value),
        "dw" => phase12_int_list_element_count(&directive.value) * 2,
        "dd" => phase12_int_list_element_count(&directive.value) * 4,
        "dq" => phase12_int_list_element_count(&directive.value) * 8,
        "ascii" => parse_machine_byte_string(&directive.value)
            .map(|bytes| bytes.len())
            .unwrap_or(0),
        "asciz" => parse_machine_byte_string(&directive.value)
            .map(|bytes| bytes.len() + 1)
            .unwrap_or(0),
        "incbin" => incbins
            .get(&directive.name)
            .map(|(bytes, _)| *bytes)
            .unwrap_or(0),
        _ => 0,
    }
}

fn phase12_int_list_element_count(value: &str) -> usize {
    value
        .split(',')
        .filter(|part| !part.trim().is_empty())
        .count()
}

fn phase12_symbol_offsets(audit: &MachineAudit) -> BTreeMap<String, usize> {
    let mut offsets = BTreeMap::new();
    let mut offset = 0_usize;
    let arch = audit_arch(audit);
    for inst in &audit.instructions {
        if inst.mnemonic == "label" {
            if let Some(name) = inst.operands.first() {
                offsets.insert(name.clone(), offset);
            }
        }
        offset += machine_instruction_len_for_arch(arch, inst);
    }
    if let Some(entry) = &audit.entry {
        offsets.entry(entry.clone()).or_insert(0);
    }
    for symbol in audit.symbols.iter().chain(audit.routines.iter()) {
        offsets.entry(symbol.clone()).or_insert(0);
    }
    offsets
}

fn phase12_relocation_kind_name(kind: &ncc_ir::BackendObjectRelocationKindIR) -> &'static str {
    match kind {
        ncc_ir::BackendObjectRelocationKindIR::CallNear32 => "call-near32",
        ncc_ir::BackendObjectRelocationKindIR::JumpNear32 => "jump-near32",
        ncc_ir::BackendObjectRelocationKindIR::PcRel32 => "pc32",
        ncc_ir::BackendObjectRelocationKindIR::Abs32 => "abs32",
        ncc_ir::BackendObjectRelocationKindIR::Abs64 => "abs64",
    }
}

fn phase12_relocation_kind_name_for_arch(
    arch: &str,
    kind: &ncc_ir::BackendObjectRelocationKindIR,
) -> &'static str {
    match (arch, kind) {
        ("armv7" | "armv7em", ncc_ir::BackendObjectRelocationKindIR::CallNear32) => "arm-thm-call",
        ("armv7" | "armv7em", ncc_ir::BackendObjectRelocationKindIR::JumpNear32) => {
            "arm-thm-jump24"
        }
        ("aarch64", ncc_ir::BackendObjectRelocationKindIR::CallNear32) => "aarch64-call26",
        ("aarch64", ncc_ir::BackendObjectRelocationKindIR::JumpNear32) => "aarch64-jump26",
        ("riscv32" | "riscv64", ncc_ir::BackendObjectRelocationKindIR::CallNear32) => "riscv-call",
        ("riscv32" | "riscv64", ncc_ir::BackendObjectRelocationKindIR::JumpNear32) => "riscv-jal",
        _ => phase12_relocation_kind_name(kind),
    }
}

fn phase12_explicit_relocation_kind(arch: &str, raw: &str) -> Option<&'static str> {
    let normalized = raw
        .trim()
        .trim_start_matches("type:")
        .trim_end_matches(';')
        .trim()
        .to_ascii_uppercase()
        .replace('-', "_");
    match arch {
        "armv7" | "armv7em" => match normalized.as_str() {
            "R_ARM_ABS32" | "ARM_ABS32" | "ABS32" => Some("abs32"),
            "R_ARM_REL32" | "ARM_REL32" | "REL32" => Some("pc32"),
            "R_ARM_THM_CALL" | "ARM_THM_CALL" | "THM_CALL" => Some("arm-thm-call"),
            "R_ARM_THM_JUMP24" | "ARM_THM_JUMP24" | "THM_JUMP24" => Some("arm-thm-jump24"),
            "R_ARM_PREL31" | "ARM_PREL31" | "PREL31" => Some("arm-prel31"),
            "R_ARM_MOVW_ABS_NC" | "ARM_MOVW_ABS_NC" | "MOVW_ABS_NC" => Some("arm-movw-abs-nc"),
            "R_ARM_MOVT_ABS" | "ARM_MOVT_ABS" | "MOVT_ABS" => Some("arm-movt-abs"),
            "R_ARM_V4BX" | "ARM_V4BX" | "V4BX" => Some("none"),
            _ => None,
        },
        "aarch64" => match normalized.as_str() {
            "R_AARCH64_ABS64" | "AARCH64_ABS64" | "ABS64" => Some("abs64"),
            "R_AARCH64_ABS32" | "AARCH64_ABS32" | "ABS32" => Some("abs32"),
            "R_AARCH64_ADR_PREL_PG_HI21" | "AARCH64_ADR_PREL_PG_HI21" => {
                Some("aarch64-adr-prel-pg-hi21")
            }
            "R_AARCH64_ADD_ABS_LO12_NC" | "AARCH64_ADD_ABS_LO12_NC" => {
                Some("aarch64-add-abs-lo12-nc")
            }
            "R_AARCH64_LDST8_ABS_LO12_NC" | "AARCH64_LDST8_ABS_LO12_NC" => {
                Some("aarch64-ldst8-abs-lo12-nc")
            }
            "R_AARCH64_LDST16_ABS_LO12_NC" | "AARCH64_LDST16_ABS_LO12_NC" => {
                Some("aarch64-ldst16-abs-lo12-nc")
            }
            "R_AARCH64_LDST32_ABS_LO12_NC" | "AARCH64_LDST32_ABS_LO12_NC" => {
                Some("aarch64-ldst32-abs-lo12-nc")
            }
            "R_AARCH64_LDST64_ABS_LO12_NC" | "AARCH64_LDST64_ABS_LO12_NC" => {
                Some("aarch64-ldst64-abs-lo12-nc")
            }
            "R_AARCH64_LDST128_ABS_LO12_NC" | "AARCH64_LDST128_ABS_LO12_NC" => {
                Some("aarch64-ldst128-abs-lo12-nc")
            }
            "R_AARCH64_JUMP26" | "AARCH64_JUMP26" | "JUMP26" => Some("aarch64-jump26"),
            "R_AARCH64_CALL26" | "AARCH64_CALL26" | "CALL26" => Some("aarch64-call26"),
            "R_AARCH64_ADR_GOT_PAGE" | "AARCH64_ADR_GOT_PAGE" => Some("aarch64-adr-got-page"),
            "R_AARCH64_LD64_GOT_LO12_NC" | "AARCH64_LD64_GOT_LO12_NC" => {
                Some("aarch64-ld64-got-lo12-nc")
            }
            _ => None,
        },
        "riscv32" | "riscv64" => match normalized.as_str() {
            "R_RISCV_32" | "RISCV_32" => Some("abs32"),
            "R_RISCV_64" | "RISCV_64" => Some("abs64"),
            "R_RISCV_BRANCH" | "RISCV_BRANCH" | "BRANCH" => Some("riscv-branch"),
            "R_RISCV_JAL" | "RISCV_JAL" | "JAL" => Some("riscv-jal"),
            "R_RISCV_CALL" | "RISCV_CALL" | "CALL" => Some("riscv-call"),
            "R_RISCV_CALL_PLT" | "RISCV_CALL_PLT" | "CALL_PLT" => Some("riscv-call-plt"),
            "R_RISCV_GOT_HI20" | "RISCV_GOT_HI20" | "GOT_HI20" => Some("riscv-got-hi20"),
            "R_RISCV_PCREL_HI20" | "RISCV_PCREL_HI20" | "PCREL_HI20" => Some("riscv-pcrel-hi20"),
            "R_RISCV_PCREL_LO12_I" | "RISCV_PCREL_LO12_I" | "PCREL_LO12_I" => {
                Some("riscv-pcrel-lo12-i")
            }
            "R_RISCV_PCREL_LO12_S" | "RISCV_PCREL_LO12_S" | "PCREL_LO12_S" => {
                Some("riscv-pcrel-lo12-s")
            }
            "R_RISCV_HI20" | "RISCV_HI20" | "HI20" => Some("riscv-hi20"),
            "R_RISCV_LO12_I" | "RISCV_LO12_I" | "LO12_I" => Some("riscv-lo12-i"),
            "R_RISCV_LO12_S" | "RISCV_LO12_S" | "LO12_S" => Some("riscv-lo12-s"),
            "R_RISCV_RVC_BRANCH" | "RISCV_RVC_BRANCH" | "RVC_BRANCH" => Some("riscv-rvc-branch"),
            "R_RISCV_RVC_JUMP" | "RISCV_RVC_JUMP" | "RVC_JUMP" => Some("riscv-rvc-jump"),
            "R_RISCV_RELAX" | "RISCV_RELAX" | "RELAX" => Some("none"),
            _ => None,
        },
        "i386" => match normalized.as_str() {
            "R_386_32" | "386_32" => Some("abs32"),
            "R_386_PC32" | "386_PC32" | "PC32" => Some("pc32"),
            "R_386_GOT32" | "386_GOT32" | "GOT32" => Some("got32"),
            "R_386_PLT32" | "386_PLT32" | "PLT32" => Some("call-near32"),
            "R_386_GOTOFF" | "386_GOTOFF" | "GOTOFF" => Some("i386-gotoff32"),
            "R_386_GOTPC" | "386_GOTPC" | "GOTPC" => Some("i386-gotpc32"),
            _ => None,
        },
        _ => match normalized.as_str() {
            "R_X86_64_64" | "X86_64_64" | "ABS64" => Some("abs64"),
            "R_X86_64_PC32" | "X86_64_PC32" | "PC32" => Some("pc32"),
            "R_X86_64_PLT32" | "X86_64_PLT32" | "PLT32" => Some("call-near32"),
            "R_X86_64_32" | "X86_64_32" | "ABS32" => Some("abs32"),
            _ => None,
        },
    }
}

fn phase12_object_unit_json(unit: &Phase12ObjectUnit) -> Value {
    json!({
        "arch": unit.arch,
        "entry": unit.entry,
        "text_hex": phase12_hex_compact(&unit.text),
        "text_align": unit.text_align,
        "rodata_hex": phase12_hex_compact(&unit.rodata),
        "rodata_align": unit.rodata_align,
        "data_hex": phase12_hex_compact(&unit.data),
        "data_align": unit.data_align,
        "bss_size": unit.bss_size,
        "bss_align": unit.bss_align,
        "sections": unit.sections.iter().map(|section| json!({
            "name": section.name,
            "kind": section.kind,
            "size": section.size,
            "align": section.align,
            "hex": phase12_hex_compact(&section.data),
        })).collect::<Vec<_>>(),
        "symbols": unit.symbols.iter().map(|symbol| json!({
            "name": symbol.name,
            "section": symbol.section,
            "offset": symbol.offset,
            "global": symbol.global,
        })).collect::<Vec<_>>(),
        "relocations": unit.relocations.iter().map(|rel| json!({
            "section": rel.section,
            "offset": rel.offset,
            "kind": rel.kind,
            "symbol": rel.symbol,
            "addend": rel.addend,
        })).collect::<Vec<_>>(),
    })
}

fn phase12_read_object_metadata(path: &str) -> Option<Value> {
    fs::read_to_string(phase12_object_metadata_path(path))
        .ok()
        .and_then(|text| serde_json::from_str(&text).ok())
}

fn phase12_dynamic_import_symbols_from_audit(audit: &MachineAudit) -> Vec<String> {
    let mut imports = BTreeSet::new();
    for symbol in &audit.externs {
        imports.insert(symbol.clone());
    }
    for inst in &audit.instructions {
        if inst.mnemonic != "call" && inst.mnemonic != "jmp" {
            continue;
        }
        let Some(target) = inst.operands.first() else {
            continue;
        };
        if audit.externs.contains(target) {
            imports.insert(target.clone());
        }
    }
    imports.into_iter().collect()
}

fn phase12_load_link_inputs(
    paths: &[String],
    target: &str,
) -> Result<Vec<Phase12LinkInput>, Box<dyn Error>> {
    let expected = phase12_expected_format(target);
    paths
        .iter()
        .map(|path| {
            let bytes = fs::read(path)?;
            let (format, ok) = classify_object_bytes(&bytes);
            if !ok {
                return Err(format!(
                    "[E_MACHINE_LINK_INPUT_001] input '{}' is not a verified machine object",
                    path
                )
                .into());
            }
            if format != expected {
                return Err(format!(
                    "[E_MACHINE_LINK_TARGET_001] input '{}' is {}, expected {} for {}",
                    path, format, expected, target
                )
                .into());
            }
            let metadata = phase12_read_object_metadata(path);
            let (mut unit, dynamic_imports, link_unit_origin) = if let Some(unit) =
                phase12_object_unit_from_metadata(metadata.as_ref())
            {
                (
                    Some(unit),
                    phase12_dynamic_imports_from_metadata(metadata.as_ref()),
                    "ncc_link_unit".to_string(),
                )
            } else if let Some(unit) = phase12_object_unit_from_metadata_source(metadata.as_ref()) {
                (
                    Some(unit),
                    phase12_dynamic_imports_from_metadata(metadata.as_ref()),
                    "ncc_source_recovered".to_string(),
                )
            } else {
                let native = phase12_object_unit_from_native_object(path, &bytes, format)?;
                (
                    Some(native.unit),
                    native.dynamic_imports,
                    "native_object".to_string(),
                )
            };
            if (target.contains("armv7em") || target.contains("thumbv7em"))
                && unit.as_ref().is_some_and(|unit| unit.arch == "armv7")
            {
                if let Some(unit) = unit.as_mut() {
                    unit.arch = "armv7em".to_string();
                }
            }
            Ok(Phase12LinkInput {
                path: path.clone(),
                source: metadata
                    .as_ref()
                    .and_then(|value| value.get("source"))
                    .and_then(Value::as_str)
                    .map(ToString::to_string),
                object_format: format.to_string(),
                link_unit_origin,
                hash: hash_bytes(&bytes),
                bytes,
                dynamic_imports,
                unit,
            })
        })
        .collect()
}

fn phase12_dynamic_imports_from_metadata(metadata: Option<&Value>) -> Vec<String> {
    metadata
        .and_then(|value| value.get("dynamic_imports"))
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(Value::as_str)
                .map(ToString::to_string)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default()
}

fn phase12_object_unit_from_metadata(metadata: Option<&Value>) -> Option<Phase12ObjectUnit> {
    let value = metadata?.get("link_unit")?;
    let symbols = value
        .get("symbols")?
        .as_array()?
        .iter()
        .filter_map(|item| {
            Some(Phase12ObjectSymbol {
                name: item.get("name")?.as_str()?.to_string(),
                section: item.get("section")?.as_str()?.to_string(),
                offset: item.get("offset")?.as_u64()? as usize,
                global: item.get("global").and_then(Value::as_bool).unwrap_or(true),
            })
        })
        .collect::<Vec<_>>();
    let relocations = value
        .get("relocations")?
        .as_array()?
        .iter()
        .filter_map(|item| {
            Some(Phase12ObjectRelocation {
                section: item.get("section")?.as_str()?.to_string(),
                offset: item.get("offset")?.as_u64()? as usize,
                kind: item.get("kind")?.as_str()?.to_string(),
                symbol: item.get("symbol")?.as_str()?.to_string(),
                addend: item.get("addend").and_then(Value::as_i64).unwrap_or(0) as isize,
            })
        })
        .collect::<Vec<_>>();
    Some(Phase12ObjectUnit {
        arch: value.get("arch")?.as_str()?.to_string(),
        entry: value
            .get("entry")
            .and_then(Value::as_str)
            .map(ToString::to_string),
        text: phase12_hex_decode(value.get("text_hex")?.as_str()?).ok()?,
        text_align: value
            .get("text_align")
            .and_then(Value::as_u64)
            .map(|value| value as usize)
            .unwrap_or(16)
            .max(1),
        rodata: value
            .get("rodata_hex")
            .and_then(Value::as_str)
            .and_then(|hex| phase12_hex_decode(hex).ok())
            .unwrap_or_default(),
        rodata_align: value
            .get("rodata_align")
            .and_then(Value::as_u64)
            .map(|value| value as usize)
            .unwrap_or(8)
            .max(1),
        data: phase12_hex_decode(value.get("data_hex")?.as_str()?).ok()?,
        data_align: value
            .get("data_align")
            .and_then(Value::as_u64)
            .map(|value| value as usize)
            .unwrap_or(8)
            .max(1),
        bss_size: value.get("bss_size")?.as_u64()? as usize,
        bss_align: value
            .get("bss_align")
            .and_then(Value::as_u64)
            .map(|value| value as usize)
            .unwrap_or(16)
            .max(1),
        sections: value
            .get("sections")
            .and_then(Value::as_array)
            .map(|items| {
                items
                    .iter()
                    .filter_map(|item| {
                        let data = item
                            .get("hex")
                            .and_then(Value::as_str)
                            .and_then(|hex| phase12_hex_decode(hex).ok())
                            .unwrap_or_default();
                        Some(Phase12ObjectSection {
                            name: item.get("name")?.as_str()?.to_string(),
                            kind: item
                                .get("kind")
                                .and_then(Value::as_str)
                                .unwrap_or_else(|| {
                                    phase12_section_kind_from_name(
                                        item.get("name").and_then(Value::as_str).unwrap_or(""),
                                    )
                                })
                                .to_string(),
                            size: item
                                .get("size")
                                .and_then(Value::as_u64)
                                .map(|value| value as usize)
                                .unwrap_or(data.len()),
                            align: item
                                .get("align")
                                .and_then(Value::as_u64)
                                .map(|value| value as usize)
                                .unwrap_or(8)
                                .max(1),
                            data,
                        })
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default(),
        symbols,
        relocations,
    })
}

fn phase12_object_unit_from_metadata_source(metadata: Option<&Value>) -> Option<Phase12ObjectUnit> {
    let source = metadata?.get("source")?.as_str()?;
    if !Path::new(source).exists() {
        return None;
    }
    let audit = audit_machine_file(source).ok()?;
    let object_format = metadata
        .and_then(|value| value.get("object_format"))
        .and_then(Value::as_str)
        .unwrap_or("elf64");
    (!audit.has_errors()).then(|| phase12_object_unit_from_audit(&audit, object_format))
}

struct Phase12NativeObjectUnit {
    unit: Phase12ObjectUnit,
    dynamic_imports: Vec<String>,
}

#[derive(Clone)]
struct Phase12NativeSymbol {
    name: String,
    section: Option<String>,
    offset: usize,
    global: bool,
    undefined: bool,
}

fn phase12_object_unit_from_native_object(
    path: &str,
    bytes: &[u8],
    format: &str,
) -> Result<Phase12NativeObjectUnit, Box<dyn Error>> {
    match format {
        "elf32" | "elf64" => phase12_elf64_native_object_unit(path, bytes),
        "coff" => phase12_coff_native_object_unit(path, bytes),
        "macho" => phase12_macho_native_object_unit(path, bytes),
        other => Err(format!(
            "[E_MACHINE_LINK_METADATA_001] input '{path}' has no phase12 link_unit and native object import is unsupported for {other}"
        )
        .into()),
    }
}

fn phase12_native_default_entry(symbols: &[Phase12ObjectSymbol]) -> Option<String> {
    for candidate in ["_start", "main", "_main"] {
        if symbols
            .iter()
            .any(|symbol| symbol.global && symbol.name == candidate)
        {
            return Some(candidate.to_string());
        }
    }
    symbols
        .iter()
        .find(|symbol| symbol.global && symbol.section == ".text")
        .map(|symbol| symbol.name.clone())
}

fn phase12_macho_add_canonical_global_aliases(symbols: &mut Vec<Phase12ObjectSymbol>) {
    let mut names = symbols
        .iter()
        .map(|symbol| symbol.name.clone())
        .collect::<BTreeSet<_>>();
    let aliases = symbols
        .iter()
        .filter(|symbol| symbol.global)
        .filter_map(|symbol| {
            let alias = symbol.name.strip_prefix('_')?;
            (!alias.is_empty() && !names.contains(alias)).then(|| Phase12ObjectSymbol {
                name: alias.to_string(),
                section: symbol.section.clone(),
                offset: symbol.offset,
                global: true,
            })
        })
        .collect::<Vec<_>>();
    for alias in aliases {
        names.insert(alias.name.clone());
        symbols.push(alias);
    }
}

fn phase12_native_imports_from_symbols_and_relocs(
    symbols: &[Phase12NativeSymbol],
    relocations: &[Phase12ObjectRelocation],
) -> Vec<String> {
    let undefined = symbols
        .iter()
        .filter(|symbol| {
            symbol.undefined
                && symbol.global
                && !symbol.name.is_empty()
                && !phase12_is_linker_defined_symbol(&symbol.name)
        })
        .map(|symbol| symbol.name.as_str())
        .collect::<BTreeSet<_>>();
    let mut imports = relocations
        .iter()
        .filter(|rel| rel.kind != "none")
        .filter(|rel| undefined.contains(rel.symbol.as_str()))
        .map(|rel| rel.symbol.clone())
        .collect::<BTreeSet<_>>();
    for symbol in symbols {
        if symbol.undefined
            && symbol.global
            && !symbol.name.is_empty()
            && !phase12_is_linker_defined_symbol(&symbol.name)
        {
            imports.insert(symbol.name.clone());
        }
    }
    imports.into_iter().collect()
}

fn phase12_is_linker_defined_symbol(name: &str) -> bool {
    matches!(
        name,
        "_GLOBAL_OFFSET_TABLE_" | "__GLOBAL_OFFSET_TABLE_" | "__dso_handle" | "___dso_handle"
    )
}

fn phase12_is_dso_handle_symbol(name: &str) -> bool {
    matches!(name, "__dso_handle" | "___dso_handle")
}

fn phase12_native_section_payload(bytes: &[u8], offset: usize, size: usize) -> Vec<u8> {
    let end = offset.saturating_add(size).min(bytes.len());
    if offset < end {
        bytes[offset..end].to_vec()
    } else {
        vec![0; size]
    }
}

fn phase12_link_section_name(kind: &str) -> String {
    match kind {
        "rodata" => ".rodata".to_string(),
        "data" => ".data".to_string(),
        "bss" => ".bss".to_string(),
        "unwind" => ".eh_frame".to_string(),
        "debug" => ".debug".to_string(),
        _ => ".text".to_string(),
    }
}

fn phase12_section_kind_from_name(name: &str) -> &'static str {
    if name.starts_with(".text") || name == "__text" {
        "text"
    } else if name.starts_with(".rodata") || name.starts_with(".rdata") || name == "__const" {
        "rodata"
    } else if name.starts_with(".data") || name == "__data" {
        "data"
    } else if name.starts_with(".bss") || name == "__bss" || name == "__common" {
        "bss"
    } else if matches!(name, ".eh_frame" | ".pdata" | ".xdata" | "__compact_unwind") {
        "unwind"
    } else if name.starts_with(".debug") || name.starts_with("__debug") {
        "debug"
    } else {
        "rodata"
    }
}

fn phase12_read_addend_i32(section: &[u8], offset: usize) -> isize {
    if offset + 4 <= section.len() {
        read_i32(section, offset) as isize
    } else {
        0
    }
}

fn phase12_read_addend_i16(section: &[u8], offset: usize) -> isize {
    if offset + 2 <= section.len() {
        i16::from_le_bytes([section[offset], section[offset + 1]]) as isize
    } else {
        0
    }
}

fn phase12_read_addend_i64(section: &[u8], offset: usize) -> isize {
    if offset + 8 <= section.len() {
        read_i64(section, offset) as isize
    } else {
        0
    }
}

fn phase12_elf64_native_object_unit(
    path: &str,
    bytes: &[u8],
) -> Result<Phase12NativeObjectUnit, Box<dyn Error>> {
    let specs = if bytes.get(4).copied() == Some(1) {
        elf32_section_specs(bytes)
    } else {
        elf_section_specs(bytes)
    };
    let arch = object_arch_for_bytes(bytes).to_string();
    if arch == "unknown" {
        return Err(format!(
            "[E_MACHINE_LINK_TARGET_001] input '{path}' has unsupported ELF machine"
        )
        .into());
    }

    let mut text = Vec::new();
    let mut text_align = 1_usize;
    let mut rodata = Vec::new();
    let mut rodata_align = 1_usize;
    let mut data = Vec::new();
    let mut data_align = 1_usize;
    let mut bss_size = 0_usize;
    let mut bss_align = 1_usize;
    let mut sections = Vec::<Phase12ObjectSection>::new();
    let mut section_map = BTreeMap::<usize, (String, usize, Vec<u8>)>::new();
    for spec in &specs {
        let Some(kind) = phase12_elf_section_kind(spec) else {
            continue;
        };
        let align = spec.align.max(1) as usize;
        match kind {
            "text" => {
                text_align = text_align.max(align);
                let base = align_to(text.len(), align);
                text.resize(base, 0);
                let payload = phase12_native_section_payload(bytes, spec.offset, spec.size);
                text.extend_from_slice(&payload);
                section_map.insert(spec.index, (phase12_link_section_name(kind), base, payload));
            }
            "rodata" => {
                rodata_align = rodata_align.max(align);
                let base = align_to(rodata.len(), align);
                rodata.resize(base, 0);
                let payload = phase12_native_section_payload(bytes, spec.offset, spec.size);
                rodata.extend_from_slice(&payload);
                section_map.insert(spec.index, (phase12_link_section_name(kind), base, payload));
            }
            "data" => {
                data_align = data_align.max(align);
                let base = align_to(data.len(), align);
                data.resize(base, 0);
                let payload = phase12_native_section_payload(bytes, spec.offset, spec.size);
                data.extend_from_slice(&payload);
                section_map.insert(spec.index, (phase12_link_section_name(kind), base, payload));
            }
            "bss" => {
                bss_align = bss_align.max(align);
                let base = align_to(bss_size, align);
                bss_size = base.saturating_add(spec.size);
                section_map.insert(
                    spec.index,
                    (phase12_link_section_name(kind), base, vec![0; spec.size]),
                );
            }
            "debug" | "unwind" => {
                let payload = phase12_native_section_payload(bytes, spec.offset, spec.size);
                sections.push(Phase12ObjectSection {
                    name: spec.name.clone(),
                    kind: kind.to_string(),
                    size: spec.size,
                    data: payload,
                    align,
                });
            }
            _ => {}
        }
    }

    let raw_symbols = phase12_elf_symbols(bytes, &specs, &section_map);
    let mut symbols = raw_symbols
        .iter()
        .filter(|symbol| !symbol.undefined)
        .filter_map(|symbol| {
            Some(Phase12ObjectSymbol {
                name: symbol.name.clone(),
                section: symbol.section.clone()?,
                offset: if matches!(arch.as_str(), "armv7" | "armv7em")
                    && symbol.section.as_deref() == Some(".text")
                {
                    symbol.offset & !1
                } else {
                    symbol.offset
                },
                global: symbol.global,
            })
        })
        .collect::<Vec<_>>();
    symbols.retain(|symbol| !symbol.name.is_empty());
    symbols.sort_by(|a, b| a.name.cmp(&b.name));
    symbols.dedup_by(|a, b| a.name == b.name && a.section == b.section && a.offset == b.offset);

    let relocations = phase12_elf_relocations(bytes, &specs, &section_map, &raw_symbols, &arch)?;
    let dynamic_imports =
        phase12_native_imports_from_symbols_and_relocs(&raw_symbols, &relocations);
    let entry = phase12_native_default_entry(&symbols);
    Ok(Phase12NativeObjectUnit {
        unit: Phase12ObjectUnit {
            arch,
            entry,
            text,
            text_align,
            rodata,
            rodata_align,
            data,
            data_align,
            bss_size,
            bss_align,
            sections,
            symbols,
            relocations,
        },
        dynamic_imports,
    })
}

fn phase12_elf_section_kind(spec: &DisasmSectionSpec) -> Option<&'static str> {
    const SHT_PROGBITS: u32 = 1;
    const SHT_NOBITS: u32 = 8;
    const SHF_WRITE: u64 = 0x1;
    const SHF_ALLOC: u64 = 0x2;
    const SHF_EXECINSTR: u64 = 0x4;
    if spec.name.starts_with(".text") || spec.flags & SHF_EXECINSTR != 0 {
        return Some("text");
    }
    if spec.name.starts_with(".bss") || spec.section_type == SHT_NOBITS {
        return Some("bss");
    }
    if spec.name.starts_with(".debug") {
        return Some("debug");
    }
    if spec.name == ".eh_frame" || spec.name.starts_with(".eh_frame") {
        return Some("unwind");
    }
    if spec.name.starts_with(".rodata") {
        return Some("rodata");
    }
    if spec.name.starts_with(".data") {
        return Some("data");
    }
    if spec.section_type == SHT_PROGBITS && spec.flags & SHF_ALLOC != 0 {
        return Some(if spec.flags & SHF_WRITE != 0 {
            "data"
        } else {
            "rodata"
        });
    }
    None
}

fn phase12_elf_symbols(
    bytes: &[u8],
    specs: &[DisasmSectionSpec],
    section_map: &BTreeMap<usize, (String, usize, Vec<u8>)>,
) -> Vec<Phase12NativeSymbol> {
    let mut symbols = Vec::new();
    let is_elf32 = bytes.get(4).copied() == Some(1);
    let default_entsize = if is_elf32 { 16 } else { 24 };
    for symtab in specs
        .iter()
        .filter(|section| section.section_type == 2 || section.name == ".symtab")
    {
        let entsize = symtab.entsize.max(default_entsize);
        let Some(strtab) = specs.iter().find(|section| section.index == symtab.link) else {
            continue;
        };
        let str_end = strtab.offset.saturating_add(strtab.size).min(bytes.len());
        let strings = if strtab.offset < str_end {
            &bytes[strtab.offset..str_end]
        } else {
            &[]
        };
        let count = symtab.size / entsize;
        symbols.resize(
            symbols.len().max(count),
            Phase12NativeSymbol {
                name: String::new(),
                section: None,
                offset: 0,
                global: false,
                undefined: true,
            },
        );
        for idx in 0..count {
            let off = symtab.offset + idx * entsize;
            if off + default_entsize > bytes.len() {
                continue;
            }
            let info = if is_elf32 {
                bytes[off + 12]
            } else {
                bytes[off + 4]
            };
            let bind = info >> 4;
            let ty = info & 0x0f;
            let shndx = if is_elf32 {
                read_u16(bytes, off + 14) as usize
            } else {
                read_u16(bytes, off + 6) as usize
            };
            let mut name = c_string_at(strings, read_u32(bytes, off) as usize).unwrap_or_default();
            if name.is_empty() && ty == 3 && section_map.contains_key(&shndx) {
                name = format!("$elf.section.{shndx}");
            }
            name = phase12_elf_link_symbol_name(&name, bind, idx);
            let value = if is_elf32 {
                read_u32(bytes, off + 4) as usize
            } else {
                read_u64(bytes, off + 8) as usize
            };
            let (section, offset, undefined) =
                if let Some((section, base, _)) = section_map.get(&shndx) {
                    (Some(section.clone()), base.saturating_add(value), false)
                } else {
                    (None, 0, shndx == 0)
                };
            if idx >= symbols.len() {
                symbols.resize(
                    idx + 1,
                    Phase12NativeSymbol {
                        name: String::new(),
                        section: None,
                        offset: 0,
                        global: false,
                        undefined: true,
                    },
                );
            }
            symbols[idx] = Phase12NativeSymbol {
                name,
                section,
                offset,
                global: bind == 1 || bind == 2,
                undefined,
            };
        }
    }
    symbols
}

fn phase12_elf_link_symbol_name(name: &str, bind: u8, symbol_index: usize) -> String {
    if bind == 0 && !name.is_empty() {
        // ELF relocations identify locals by symbol-table index, not spelling.
        // Assemblers routinely emit distinct `.L0`, `$x` and `$d` entries.
        format!("{name}$elf${symbol_index:x}")
    } else {
        name.to_string()
    }
}

fn phase12_elf_relocations(
    bytes: &[u8],
    specs: &[DisasmSectionSpec],
    section_map: &BTreeMap<usize, (String, usize, Vec<u8>)>,
    symbols: &[Phase12NativeSymbol],
    arch: &str,
) -> Result<Vec<Phase12ObjectRelocation>, Box<dyn Error>> {
    let mut out = Vec::new();
    let is_elf32 = bytes.get(4).copied() == Some(1);
    for reloc_section in specs.iter().filter(|section| {
        section.section_type == 4 || section.section_type == 9 || section.name.starts_with(".rel")
    }) {
        let Some((target_section, target_base, target_payload)) =
            section_map.get(&reloc_section.info)
        else {
            continue;
        };
        let rela = reloc_section.section_type == 4 || reloc_section.name.starts_with(".rela");
        let default_entsize = if is_elf32 {
            if rela {
                12
            } else {
                8
            }
        } else if rela {
            24
        } else {
            16
        };
        let entsize = reloc_section.entsize.max(default_entsize);
        let count = reloc_section.size / entsize;
        for idx in 0..count {
            let off = reloc_section.offset + idx * entsize;
            if off + default_entsize > bytes.len() {
                continue;
            }
            let (r_offset, symbol_index, reloc_type) = if is_elf32 {
                let r_info = read_u32(bytes, off + 4) as u64;
                (
                    read_u32(bytes, off) as usize,
                    (r_info >> 8) as usize,
                    r_info & 0xff,
                )
            } else {
                let r_info = read_u64(bytes, off + 8);
                (
                    read_u64(bytes, off) as usize,
                    (r_info >> 32) as usize,
                    r_info & 0xffff_ffff,
                )
            };
            let addend = if rela && is_elf32 {
                read_i32(bytes, off + 8) as isize
            } else if rela {
                read_i64(bytes, off + 16) as isize
            } else if arch == "armv7" || arch == "armv7em" {
                phase12_read_arm_rel_addend(target_payload, r_offset, reloc_type)
            } else if phase12_elf_rel_addend_is_i64(arch, reloc_type) {
                phase12_read_addend_i64(target_payload, r_offset)
            } else {
                phase12_read_addend_i32(target_payload, r_offset)
            };
            let Some(symbol) = symbols.get(symbol_index) else {
                return Err(format!(
                    "[E_MACHINE_LINK_RELOCATION_001] ELF relocation references missing symbol index {symbol_index}"
                )
                .into());
            };
            let Some(kind) = phase12_elf_relocation_kind(arch, reloc_type) else {
                return Err(format!(
                    "[E_MACHINE_LINK_RELOCATION_UNSUPPORTED_001] unsupported ELF relocation type {reloc_type}"
                )
                .into());
            };
            out.push(Phase12ObjectRelocation {
                section: target_section.clone(),
                offset: target_base.saturating_add(r_offset),
                kind: kind.to_string(),
                symbol: symbol.name.clone(),
                addend,
            });
        }
    }
    Ok(out)
}

fn phase12_read_arm_rel_addend(section: &[u8], offset: usize, reloc_type: u64) -> isize {
    let halfword = |at: usize| {
        section
            .get(at..at + 2)
            .map(|bytes| u16::from_le_bytes([bytes[0], bytes[1]]))
    };
    match reloc_type {
        10 | 30 => {
            let Some(first) = halfword(offset) else {
                return 0;
            };
            let Some(second) = halfword(offset + 2) else {
                return 0;
            };
            let s = ((first >> 10) & 1) as u32;
            let j1 = ((second >> 13) & 1) as u32;
            let j2 = ((second >> 11) & 1) as u32;
            let i1 = (!(j1 ^ s)) & 1;
            let i2 = (!(j2 ^ s)) & 1;
            let encoded = (s << 24)
                | (i1 << 23)
                | (i2 << 22)
                | (((first & 0x03ff) as u32) << 12)
                | (((second & 0x07ff) as u32) << 1);
            let displacement = ((encoded << 7) as i32 >> 7) as isize;
            // ELF R_ARM_THM_CALL/JUMP24 use P, while the architectural PC is P+4.
            displacement.saturating_add(4)
        }
        47 | 48 => {
            let Some(first) = halfword(offset) else {
                return 0;
            };
            let Some(second) = halfword(offset + 2) else {
                return 0;
            };
            let immediate = (((first & 0x000f) as u32) << 12)
                | ((((first >> 10) & 1) as u32) << 11)
                | ((((second >> 12) & 7) as u32) << 8)
                | (second & 0x00ff) as u32;
            if reloc_type == 48 {
                (immediate << 16) as isize
            } else {
                immediate as isize
            }
        }
        42 => {
            let raw = phase12_read_addend_i32(section, offset) as i32 as u32 & 0x7fff_ffff;
            ((raw << 1) as i32 >> 1) as isize
        }
        _ => phase12_read_addend_i32(section, offset),
    }
}

fn phase12_elf_rel_addend_is_i64(arch: &str, reloc_type: u64) -> bool {
    matches!(
        (arch, reloc_type),
        ("x86_64", 1) | ("aarch64", 257) | ("riscv64", 2)
    )
}

fn phase12_elf_relocation_kind(arch: &str, reloc_type: u64) -> Option<&'static str> {
    match arch {
        "armv7" | "armv7em" => match reloc_type {
            2 | 38 => Some("abs32"),       // R_ARM_ABS32 / R_ARM_TARGET1
            3 => Some("pc32"),             // R_ARM_REL32
            10 => Some("arm-thm-call"),    // R_ARM_THM_CALL
            30 => Some("arm-thm-jump24"),  // R_ARM_THM_JUMP24
            40 => Some("none"),            // R_ARM_V4BX
            42 => Some("arm-prel31"),      // R_ARM_PREL31
            47 => Some("arm-movw-abs-nc"), // R_ARM_MOVW_ABS_NC
            48 => Some("arm-movt-abs"),    // R_ARM_MOVT_ABS
            _ => None,
        },
        "i386" => match reloc_type {
            1 => Some("abs32"),         // R_386_32
            2 => Some("pc32"),          // R_386_PC32
            3 => Some("got32"),         // R_386_GOT32
            4 => Some("call-near32"),   // R_386_PLT32
            9 => Some("i386-gotoff32"), // R_386_GOTOFF
            10 => Some("i386-gotpc32"), // R_386_GOTPC
            43 => Some("got32"),        // R_386_GOT32X
            _ => None,
        },
        "aarch64" => match reloc_type {
            257 => Some("abs64"),                       // R_AARCH64_ABS64
            258 => Some("abs32"),                       // R_AARCH64_ABS32
            275 => Some("aarch64-adr-prel-pg-hi21"),    // R_AARCH64_ADR_PREL_PG_HI21
            277 => Some("aarch64-add-abs-lo12-nc"),     // R_AARCH64_ADD_ABS_LO12_NC
            278 => Some("aarch64-ldst8-abs-lo12-nc"),   // R_AARCH64_LDST8_ABS_LO12_NC
            282 => Some("aarch64-jump26"),              // R_AARCH64_JUMP26
            283 => Some("aarch64-call26"),              // R_AARCH64_CALL26
            284 => Some("aarch64-ldst16-abs-lo12-nc"),  // R_AARCH64_LDST16_ABS_LO12_NC
            285 => Some("aarch64-ldst32-abs-lo12-nc"),  // R_AARCH64_LDST32_ABS_LO12_NC
            286 => Some("aarch64-ldst64-abs-lo12-nc"),  // R_AARCH64_LDST64_ABS_LO12_NC
            299 => Some("aarch64-ldst128-abs-lo12-nc"), // R_AARCH64_LDST128_ABS_LO12_NC
            311 => Some("aarch64-adr-got-page"),        // R_AARCH64_ADR_GOT_PAGE
            312 => Some("aarch64-ld64-got-lo12-nc"),    // R_AARCH64_LD64_GOT_LO12_NC
            _ => None,
        },
        "riscv32" => match reloc_type {
            1 => Some("abs32"),               // R_RISCV_32
            16 => Some("riscv-branch"),       // R_RISCV_BRANCH
            17 => Some("riscv-jal"),          // R_RISCV_JAL
            18 => Some("riscv-call"),         // R_RISCV_CALL
            19 => Some("riscv-call-plt"),     // R_RISCV_CALL_PLT
            20 => Some("riscv-got-hi20"),     // R_RISCV_GOT_HI20
            23 => Some("riscv-pcrel-hi20"),   // R_RISCV_PCREL_HI20
            24 => Some("riscv-pcrel-lo12-i"), // R_RISCV_PCREL_LO12_I
            25 => Some("riscv-pcrel-lo12-s"), // R_RISCV_PCREL_LO12_S
            26 => Some("riscv-hi20"),         // R_RISCV_HI20
            27 => Some("riscv-lo12-i"),       // R_RISCV_LO12_I
            28 => Some("riscv-lo12-s"),       // R_RISCV_LO12_S
            44 => Some("riscv-rvc-branch"),   // R_RISCV_RVC_BRANCH
            45 => Some("riscv-rvc-jump"),     // R_RISCV_RVC_JUMP
            51 => Some("none"),               // R_RISCV_RELAX
            _ => None,
        },
        "riscv64" => match reloc_type {
            1 => Some("abs32"),               // R_RISCV_32
            2 => Some("abs64"),               // R_RISCV_64
            16 => Some("riscv-branch"),       // R_RISCV_BRANCH
            17 => Some("riscv-jal"),          // R_RISCV_JAL
            18 => Some("riscv-call"),         // R_RISCV_CALL
            19 => Some("riscv-call-plt"),     // R_RISCV_CALL_PLT
            20 => Some("riscv-got-hi20"),     // R_RISCV_GOT_HI20
            23 => Some("riscv-pcrel-hi20"),   // R_RISCV_PCREL_HI20
            24 => Some("riscv-pcrel-lo12-i"), // R_RISCV_PCREL_LO12_I
            25 => Some("riscv-pcrel-lo12-s"), // R_RISCV_PCREL_LO12_S
            26 => Some("riscv-hi20"),         // R_RISCV_HI20
            27 => Some("riscv-lo12-i"),       // R_RISCV_LO12_I
            28 => Some("riscv-lo12-s"),       // R_RISCV_LO12_S
            44 => Some("riscv-rvc-branch"),   // R_RISCV_RVC_BRANCH
            45 => Some("riscv-rvc-jump"),     // R_RISCV_RVC_JUMP
            51 => Some("none"),               // R_RISCV_RELAX
            _ => None,
        },
        _ => match reloc_type {
            1 => Some("abs64"),                 // R_X86_64_64
            2 => Some("pc32"),                  // R_X86_64_PC32
            4 => Some("call-near32"),           // R_X86_64_PLT32
            9 | 41 | 42 => Some("got-pcrel32"), // GOTPCREL/GOTPCRELX/REX_GOTPCRELX
            10 => Some("abs32"),                // R_X86_64_32
            11 => Some("abs32s"),               // R_X86_64_32S
            _ => None,
        },
    }
}

#[derive(Clone)]
struct Phase12CoffSectionSpec {
    index: usize,
    name: String,
    offset: usize,
    size: usize,
    reloc_offset: usize,
    reloc_count: usize,
    characteristics: u32,
}

fn phase12_coff_native_object_unit(
    path: &str,
    bytes: &[u8],
) -> Result<Phase12NativeObjectUnit, Box<dyn Error>> {
    let specs = phase12_coff_section_specs(bytes);
    let arch = object_arch_for_bytes(bytes).to_string();
    let mut text = Vec::new();
    let mut text_align = 1_usize;
    let mut rodata = Vec::new();
    let mut rodata_align = 1_usize;
    let mut data = Vec::new();
    let mut data_align = 1_usize;
    let mut bss_size = 0_usize;
    let mut bss_align = 1_usize;
    let mut sections = Vec::<Phase12ObjectSection>::new();
    let mut section_map = BTreeMap::<usize, (String, usize, Vec<u8>)>::new();
    for spec in &specs {
        let Some(kind) = phase12_coff_section_kind(spec) else {
            continue;
        };
        let align = phase12_coff_section_alignment(spec.characteristics);
        match kind {
            "text" => {
                text_align = text_align.max(align);
                let base = align_to(text.len(), align);
                text.resize(base, 0);
                let payload = phase12_native_section_payload(bytes, spec.offset, spec.size);
                text.extend_from_slice(&payload);
                section_map.insert(spec.index, (phase12_link_section_name(kind), base, payload));
            }
            "rodata" => {
                rodata_align = rodata_align.max(align);
                let base = align_to(rodata.len(), align);
                rodata.resize(base, 0);
                let payload = phase12_native_section_payload(bytes, spec.offset, spec.size);
                rodata.extend_from_slice(&payload);
                section_map.insert(spec.index, (phase12_link_section_name(kind), base, payload));
            }
            "data" => {
                data_align = data_align.max(align);
                let base = align_to(data.len(), align);
                data.resize(base, 0);
                let payload = phase12_native_section_payload(bytes, spec.offset, spec.size);
                data.extend_from_slice(&payload);
                section_map.insert(spec.index, (phase12_link_section_name(kind), base, payload));
            }
            "bss" => {
                bss_align = bss_align.max(align);
                let base = align_to(bss_size, align);
                bss_size = base.saturating_add(spec.size);
                section_map.insert(
                    spec.index,
                    (phase12_link_section_name(kind), base, vec![0; spec.size]),
                );
            }
            "debug" | "unwind" => {
                let payload = phase12_native_section_payload(bytes, spec.offset, spec.size);
                section_map.insert(spec.index, (spec.name.clone(), 0, payload.clone()));
                sections.push(Phase12ObjectSection {
                    name: spec.name.clone(),
                    kind: kind.to_string(),
                    size: spec.size,
                    data: payload,
                    align,
                });
            }
            _ => {}
        }
    }
    let raw_symbols = phase12_coff_symbols(bytes, &section_map);
    let mut symbols = raw_symbols
        .iter()
        .enumerate()
        .filter(|(_, symbol)| !symbol.undefined)
        .filter_map(|(symbol_index, symbol)| {
            Some(Phase12ObjectSymbol {
                name: phase12_coff_link_symbol_name(symbol, symbol_index),
                section: symbol.section.clone()?,
                offset: symbol.offset,
                global: symbol.global,
            })
        })
        .collect::<Vec<_>>();
    symbols.retain(|symbol| !symbol.name.is_empty());
    for spec in &specs {
        let Some(name) = spec.name.strip_prefix(".text.") else {
            continue;
        };
        if name.is_empty() || symbols.iter().any(|symbol| symbol.name == name) {
            continue;
        }
        if let Some((section, base, _)) = section_map.get(&spec.index) {
            symbols.push(Phase12ObjectSymbol {
                name: name.to_string(),
                section: section.clone(),
                offset: *base,
                global: true,
            });
        }
    }
    symbols.sort_by(|a, b| a.name.cmp(&b.name));
    symbols.dedup_by(|a, b| a.name == b.name && a.section == b.section && a.offset == b.offset);
    let relocations = phase12_coff_relocations(bytes, &specs, &section_map, &raw_symbols, &arch)?;
    let dynamic_imports =
        phase12_native_imports_from_symbols_and_relocs(&raw_symbols, &relocations);
    let entry = phase12_native_default_entry(&symbols);
    if symbols.is_empty() && text.is_empty() && data.is_empty() && bss_size == 0 {
        return Err(format!(
            "[E_MACHINE_LINK_SECTION_001] input '{path}' has no linkable COFF sections"
        )
        .into());
    }
    Ok(Phase12NativeObjectUnit {
        unit: Phase12ObjectUnit {
            arch,
            entry,
            text,
            text_align,
            rodata,
            rodata_align,
            data,
            data_align,
            bss_size,
            bss_align,
            sections,
            symbols,
            relocations,
        },
        dynamic_imports,
    })
}

fn phase12_coff_section_specs(bytes: &[u8]) -> Vec<Phase12CoffSectionSpec> {
    if bytes.len() < 20 {
        return Vec::new();
    }
    let section_count = read_u16(bytes, 2) as usize;
    let sym_ptr = read_u32(bytes, 8) as usize;
    let sym_count = read_u32(bytes, 12) as usize;
    let string_table = sym_ptr.saturating_add(sym_count.saturating_mul(18));
    let optional_size = read_u16(bytes, 16) as usize;
    let start = 20 + optional_size;
    (0..section_count)
        .filter_map(|idx| {
            let off = start + idx * 40;
            if off + 40 > bytes.len() {
                return None;
            }
            Some(Phase12CoffSectionSpec {
                index: idx + 1,
                name: phase12_coff_name(bytes, off, 8, string_table),
                offset: read_u32(bytes, off + 20) as usize,
                size: read_u32(bytes, off + 16) as usize,
                reloc_offset: read_u32(bytes, off + 24) as usize,
                reloc_count: read_u16(bytes, off + 32) as usize,
                characteristics: read_u32(bytes, off + 36),
            })
        })
        .collect()
}

fn phase12_coff_name(bytes: &[u8], offset: usize, len: usize, string_table: usize) -> String {
    if offset + len > bytes.len() {
        return String::new();
    }
    let raw_bytes = &bytes[offset..offset + len];
    if len >= 8 && raw_bytes.get(0..4) == Some(&[0, 0, 0, 0]) {
        let str_offset = read_u32(bytes, offset + 4) as usize;
        if str_offset > 0 {
            return c_string_at(bytes, string_table.saturating_add(str_offset)).unwrap_or_default();
        }
    }
    let raw = fixed_string(&bytes[offset..offset + len]);
    if let Some(rest) = raw.strip_prefix('/') {
        if let Ok(str_offset) = rest.parse::<usize>() {
            return c_string_at(bytes, string_table.saturating_add(str_offset)).unwrap_or(raw);
        }
    }
    raw
}

fn phase12_coff_section_kind(spec: &Phase12CoffSectionSpec) -> Option<&'static str> {
    const IMAGE_SCN_CNT_CODE: u32 = 0x0000_0020;
    const IMAGE_SCN_CNT_INITIALIZED_DATA: u32 = 0x0000_0040;
    const IMAGE_SCN_CNT_UNINITIALIZED_DATA: u32 = 0x0000_0080;
    const IMAGE_SCN_MEM_EXECUTE: u32 = 0x2000_0000;
    const IMAGE_SCN_MEM_WRITE: u32 = 0x8000_0000;
    if spec.name.starts_with(".text")
        || spec.characteristics & (IMAGE_SCN_CNT_CODE | IMAGE_SCN_MEM_EXECUTE) != 0
    {
        Some("text")
    } else if spec.name.starts_with(".bss")
        || spec.characteristics & IMAGE_SCN_CNT_UNINITIALIZED_DATA != 0
    {
        Some("bss")
    } else if spec.name.starts_with(".pdata") || spec.name.starts_with(".xdata") {
        Some("unwind")
    } else if spec.name.starts_with(".debug") {
        Some("debug")
    } else if spec.name.starts_with(".rdata") {
        Some("rodata")
    } else if spec.name.starts_with(".data") {
        Some("data")
    } else if spec.characteristics & IMAGE_SCN_CNT_INITIALIZED_DATA != 0 {
        Some(if spec.characteristics & IMAGE_SCN_MEM_WRITE != 0 {
            "data"
        } else {
            "rodata"
        })
    } else {
        None
    }
}

fn phase12_coff_section_alignment(characteristics: u32) -> usize {
    let encoded = (characteristics >> 20) & 0x0f;
    if (1..=14).contains(&encoded) {
        1_usize << (encoded - 1)
    } else {
        16
    }
}

fn phase12_coff_symbols(
    bytes: &[u8],
    section_map: &BTreeMap<usize, (String, usize, Vec<u8>)>,
) -> Vec<Phase12NativeSymbol> {
    if bytes.len() < 20 {
        return Vec::new();
    }
    let sym_ptr = read_u32(bytes, 8) as usize;
    let sym_count = read_u32(bytes, 12) as usize;
    let string_table = sym_ptr.saturating_add(sym_count.saturating_mul(18));
    let mut symbols = vec![
        Phase12NativeSymbol {
            name: String::new(),
            section: None,
            offset: 0,
            global: false,
            undefined: true,
        };
        sym_count
    ];
    let mut idx = 0;
    while idx < sym_count {
        let off = sym_ptr + idx * 18;
        if off + 18 > bytes.len() {
            break;
        }
        let name = phase12_coff_name(bytes, off, 8, string_table);
        let value = read_u32(bytes, off + 8) as usize;
        let section_number = read_u16(bytes, off + 12) as i16;
        let storage_class = bytes.get(off + 16).copied().unwrap_or_default();
        let aux_count = bytes.get(off + 17).copied().unwrap_or_default() as usize;
        let (section, offset, undefined) = if section_number > 0 {
            if let Some((section, base, _)) = section_map.get(&(section_number as usize)) {
                (Some(section.clone()), base.saturating_add(value), false)
            } else {
                (None, 0, false)
            }
        } else {
            (None, 0, true)
        };
        symbols[idx] = Phase12NativeSymbol {
            name,
            section,
            offset,
            global: matches!(storage_class, 2 | 105),
            undefined,
        };
        idx += 1 + aux_count;
    }
    symbols
}

fn phase12_coff_link_symbol_name(symbol: &Phase12NativeSymbol, symbol_index: usize) -> String {
    if symbol.undefined || symbol.global {
        return symbol.name.clone();
    }
    // A COFF object may contain multiple input-section symbols with the same
    // spelling (for example several `.rdata` contributions). Relocations name
    // symbols by table index, so preserve that identity until the generic
    // linker gives the local symbol its object-scoped name.
    format!("{}$coff${symbol_index:x}", symbol.name)
}

fn phase12_coff_relocations(
    bytes: &[u8],
    specs: &[Phase12CoffSectionSpec],
    section_map: &BTreeMap<usize, (String, usize, Vec<u8>)>,
    symbols: &[Phase12NativeSymbol],
    arch: &str,
) -> Result<Vec<Phase12ObjectRelocation>, Box<dyn Error>> {
    let mut out = Vec::new();
    for spec in specs {
        let Some((section, base, payload)) = section_map.get(&spec.index) else {
            continue;
        };
        for rel_idx in 0..spec.reloc_count {
            let off = spec.reloc_offset + rel_idx * 10;
            if off + 10 > bytes.len() {
                continue;
            }
            let symbol_index = read_u32(bytes, off + 4) as usize;
            let Some(symbol) = symbols.get(symbol_index) else {
                return Err(format!(
                    "[E_MACHINE_LINK_RELOCATION_001] COFF relocation references missing symbol index {symbol_index}"
                )
                .into());
            };
            if symbol.name.is_empty() {
                continue;
            }
            let reloc_type = read_u16(bytes, off + 8);
            let offset = read_u32(bytes, off) as usize;
            let Some(kind) = phase12_coff_relocation_kind(arch, reloc_type) else {
                return Err(format!(
                    "[E_MACHINE_LINK_RELOCATION_UNSUPPORTED_001] unsupported COFF relocation type {reloc_type}"
                )
                .into());
            };
            let addend = if arch == "i386" {
                match reloc_type {
                    0x0014 => phase12_read_addend_i32(payload, offset) - 4,
                    _ => phase12_read_addend_i32(payload, offset),
                }
            } else {
                match reloc_type {
                    0x0000 => 0,
                    0x0001 => phase12_read_addend_i64(payload, offset),
                    0x0004..=0x0009 => {
                        phase12_read_addend_i32(payload, offset)
                            - 4
                            - (reloc_type - 0x0004) as isize
                    }
                    0x000a => phase12_read_addend_i16(payload, offset),
                    _ => phase12_read_addend_i32(payload, offset),
                }
            };
            out.push(Phase12ObjectRelocation {
                section: section.clone(),
                offset: base.saturating_add(offset),
                kind: kind.to_string(),
                symbol: phase12_coff_link_symbol_name(symbol, symbol_index),
                addend,
            });
        }
    }
    Ok(out)
}

fn phase12_coff_relocation_kind(arch: &str, reloc_type: u16) -> Option<&'static str> {
    if arch == "i386" {
        return match reloc_type {
            0x0000 => Some("none"),
            0x0006 => Some("coff-addr32"),
            0x0007 => Some("coff-addr32nb"),
            0x000a => Some("coff-section"),
            0x000b => Some("coff-secrel32"),
            0x0014 => Some("call-near32"),
            _ => None,
        };
    }
    match reloc_type {
        0x0000 => Some("none"),          // IMAGE_REL_AMD64_ABSOLUTE
        0x0001 => Some("abs64"),         // IMAGE_REL_AMD64_ADDR64
        0x0002 => Some("coff-addr32"),   // IMAGE_REL_AMD64_ADDR32
        0x0003 => Some("coff-addr32nb"), // IMAGE_REL_AMD64_ADDR32NB
        0x0004 => Some("call-near32"),   // IMAGE_REL_AMD64_REL32
        0x0005..=0x0009 => Some("pc32"), // IMAGE_REL_AMD64_REL32_1..REL32_5
        0x000a => Some("coff-section"),  // IMAGE_REL_AMD64_SECTION
        0x000b => Some("coff-secrel32"), // IMAGE_REL_AMD64_SECREL
        _ => None,
    }
}

#[derive(Clone)]
struct Phase12MachoSectionSpec {
    index: usize,
    name: String,
    segment: String,
    addr: u64,
    offset: usize,
    size: usize,
    align: usize,
    reloc_offset: usize,
    reloc_count: usize,
    flags: u32,
}

fn phase12_macho_native_object_unit(
    path: &str,
    bytes: &[u8],
) -> Result<Phase12NativeObjectUnit, Box<dyn Error>> {
    let arch = phase12_macho_arch(bytes)?;
    let specs = phase12_macho_section_specs(bytes);
    let mut text = Vec::new();
    let mut text_align = 1_usize;
    let mut rodata = Vec::new();
    let mut rodata_align = 1_usize;
    let mut data = Vec::new();
    let mut data_align = 1_usize;
    let mut bss_size = 0_usize;
    let mut bss_align = 1_usize;
    let mut sections = Vec::<Phase12ObjectSection>::new();
    let mut section_map = BTreeMap::<usize, (String, usize, Vec<u8>)>::new();
    for spec in &specs {
        let Some(kind) = phase12_macho_section_kind(spec) else {
            continue;
        };
        let align = spec.align.max(1);
        match kind {
            "text" => {
                text_align = text_align.max(align);
                let base = align_to(text.len(), align);
                text.resize(base, 0);
                let payload = phase12_native_section_payload(bytes, spec.offset, spec.size);
                text.extend_from_slice(&payload);
                section_map.insert(spec.index, (phase12_link_section_name(kind), base, payload));
            }
            "rodata" => {
                rodata_align = rodata_align.max(align);
                let base = align_to(rodata.len(), align);
                rodata.resize(base, 0);
                let payload = phase12_native_section_payload(bytes, spec.offset, spec.size);
                rodata.extend_from_slice(&payload);
                section_map.insert(spec.index, (phase12_link_section_name(kind), base, payload));
            }
            "data" => {
                data_align = data_align.max(align);
                let base = align_to(data.len(), align);
                data.resize(base, 0);
                let payload = phase12_native_section_payload(bytes, spec.offset, spec.size);
                data.extend_from_slice(&payload);
                section_map.insert(spec.index, (phase12_link_section_name(kind), base, payload));
            }
            "bss" => {
                bss_align = bss_align.max(align);
                let base = align_to(bss_size, align);
                bss_size = base.saturating_add(spec.size);
                section_map.insert(
                    spec.index,
                    (phase12_link_section_name(kind), base, vec![0; spec.size]),
                );
            }
            "debug" | "unwind" => {
                let payload = phase12_native_section_payload(bytes, spec.offset, spec.size);
                sections.push(Phase12ObjectSection {
                    name: spec.name.clone(),
                    kind: kind.to_string(),
                    size: spec.size,
                    data: payload,
                    align,
                });
            }
            _ => {}
        }
    }
    let raw_symbols = phase12_macho_symbols(bytes, &specs, &section_map);
    let mut symbols = raw_symbols
        .iter()
        .filter(|symbol| !symbol.undefined)
        .filter_map(|symbol| {
            Some(Phase12ObjectSymbol {
                name: symbol.name.clone(),
                section: symbol.section.clone()?,
                offset: symbol.offset,
                global: symbol.global,
            })
        })
        .collect::<Vec<_>>();
    symbols.retain(|symbol| !symbol.name.is_empty());
    symbols.sort_by(|a, b| a.name.cmp(&b.name));
    symbols.dedup_by(|a, b| a.name == b.name && a.section == b.section && a.offset == b.offset);
    phase12_macho_add_canonical_global_aliases(&mut symbols);
    let relocations = phase12_macho_relocations(bytes, &arch, &specs, &section_map, &raw_symbols)?;
    let dynamic_imports =
        phase12_native_imports_from_symbols_and_relocs(&raw_symbols, &relocations);
    let entry = phase12_native_default_entry(&symbols);
    if symbols.is_empty() && text.is_empty() && data.is_empty() && bss_size == 0 {
        return Err(format!(
            "[E_MACHINE_LINK_SECTION_001] input '{path}' has no linkable Mach-O sections"
        )
        .into());
    }
    Ok(Phase12NativeObjectUnit {
        unit: Phase12ObjectUnit {
            arch,
            entry,
            text,
            text_align,
            rodata,
            rodata_align,
            data,
            data_align,
            bss_size,
            bss_align,
            sections,
            symbols,
            relocations,
        },
        dynamic_imports,
    })
}

fn phase12_macho_arch(bytes: &[u8]) -> Result<String, Box<dyn Error>> {
    if bytes.len() < 12 || read_u32(bytes, 0) != 0xfeed_facf {
        return Err("[E_MACHINE_LINK_INPUT_001] expected a little-endian Mach-O 64 object".into());
    }
    match read_u32(bytes, 4) {
        0x0100_0007 => Ok("x86_64".to_string()),
        0x0100_000c => Ok("aarch64".to_string()),
        cpu => Err(
            format!("[E_MACHINE_LINK_TARGET_001] unsupported Mach-O CPU type 0x{cpu:08x}").into(),
        ),
    }
}

fn phase12_macho_section_specs(bytes: &[u8]) -> Vec<Phase12MachoSectionSpec> {
    if bytes.len() < 32 {
        return Vec::new();
    }
    let ncmds = read_u32(bytes, 16) as usize;
    let mut cursor = 32;
    let mut out = Vec::new();
    for _ in 0..ncmds {
        if cursor + 8 > bytes.len() {
            break;
        }
        let cmd = read_u32(bytes, cursor);
        let cmdsize = read_u32(bytes, cursor + 4) as usize;
        if cmd == 0x19 && cursor + 72 <= bytes.len() {
            let nsects = read_u32(bytes, cursor + 64) as usize;
            let mut section_off = cursor + 72;
            for _ in 0..nsects {
                if section_off + 80 > bytes.len() {
                    break;
                }
                out.push(Phase12MachoSectionSpec {
                    index: out.len() + 1,
                    name: fixed_string(&bytes[section_off..section_off + 16]),
                    segment: fixed_string(&bytes[section_off + 16..section_off + 32]),
                    addr: read_u64(bytes, section_off + 32),
                    size: read_u64(bytes, section_off + 40) as usize,
                    offset: read_u32(bytes, section_off + 48) as usize,
                    align: 1_usize << read_u32(bytes, section_off + 52).min(20),
                    reloc_offset: read_u32(bytes, section_off + 56) as usize,
                    reloc_count: read_u32(bytes, section_off + 60) as usize,
                    flags: read_u32(bytes, section_off + 64),
                });
                section_off += 80;
            }
        }
        cursor += cmdsize.max(8);
    }
    out
}

fn phase12_macho_section_kind(spec: &Phase12MachoSectionSpec) -> Option<&'static str> {
    let section_type = spec.flags & 0x0000_00ff;
    if spec.name.starts_with("__debug") || spec.segment == "__DWARF" {
        Some("debug")
    } else if matches!(
        spec.name.as_str(),
        "__compact_unwind" | "__eh_frame" | "__unwind_info"
    ) {
        Some("unwind")
    } else if spec.name == "__bss" || spec.name == "__common" || section_type == 0x1 {
        Some("bss")
    } else if matches!(
        spec.name.as_str(),
        "__const" | "__cstring" | "__literal4" | "__literal8" | "__literal16" | "__const_coal"
    ) || matches!(section_type, 0x2 | 0x3 | 0x4 | 0x5 | 0xe)
        || spec.segment == "__DATA_CONST"
    {
        Some("rodata")
    } else if spec.name == "__text"
        || spec.name.starts_with(".text")
        || spec.flags & 0x8000_0000 != 0
    {
        Some("text")
    } else if spec.name == "__data" || spec.segment == "__DATA" {
        Some("data")
    } else if spec.segment == "__TEXT" {
        Some("rodata")
    } else {
        None
    }
}

fn phase12_macho_symbols(
    bytes: &[u8],
    specs: &[Phase12MachoSectionSpec],
    section_map: &BTreeMap<usize, (String, usize, Vec<u8>)>,
) -> Vec<Phase12NativeSymbol> {
    let Some((symoff, nsyms, stroff, strsize)) = macho_symtab_command(bytes) else {
        return Vec::new();
    };
    let str_end = stroff.saturating_add(strsize).min(bytes.len());
    let strings = if stroff < str_end {
        &bytes[stroff..str_end]
    } else {
        &[]
    };
    let mut symbols = Vec::with_capacity(nsyms);
    for idx in 0..nsyms {
        let off = symoff + idx * 16;
        if off + 16 > bytes.len() {
            break;
        }
        let name = c_string_at(strings, read_u32(bytes, off) as usize).unwrap_or_default();
        let n_type = bytes[off + 4];
        let n_sect = bytes[off + 5] as usize;
        let n_value = read_u64(bytes, off + 8);
        let typ = n_type & 0x0e;
        let undefined = typ == 0;
        let (section, offset) = if let Some((section, base, _)) = section_map.get(&n_sect) {
            let section_addr = specs
                .iter()
                .find(|spec| spec.index == n_sect)
                .map(|spec| spec.addr)
                .unwrap_or(0);
            (
                Some(section.clone()),
                base.saturating_add(n_value.saturating_sub(section_addr) as usize),
            )
        } else {
            (None, 0)
        };
        symbols.push(Phase12NativeSymbol {
            name,
            section,
            offset,
            global: n_type & 0x01 != 0,
            undefined,
        });
    }
    for (section_index, (section, base, _)) in section_map {
        symbols.push(Phase12NativeSymbol {
            name: format!("$macho.section.{section_index}"),
            section: Some(section.clone()),
            offset: *base,
            global: false,
            undefined: false,
        });
    }
    symbols
}

fn phase12_macho_relocations(
    bytes: &[u8],
    arch: &str,
    specs: &[Phase12MachoSectionSpec],
    section_map: &BTreeMap<usize, (String, usize, Vec<u8>)>,
    symbols: &[Phase12NativeSymbol],
) -> Result<Vec<Phase12ObjectRelocation>, Box<dyn Error>> {
    let mut out = Vec::new();
    for spec in specs {
        let Some((section, base, payload)) = section_map.get(&spec.index) else {
            continue;
        };
        let mut pending_arm64_addend: Option<(usize, isize)> = None;
        for rel_idx in 0..spec.reloc_count {
            let off = spec.reloc_offset + rel_idx * 8;
            if off + 8 > bytes.len() {
                continue;
            }
            let r_address = read_u32(bytes, off) as usize;
            let packed = read_u32(bytes, off + 4);
            let symbol_number = (packed & 0x00ff_ffff) as usize;
            let pcrel = ((packed >> 24) & 1) != 0;
            let length = (packed >> 25) & 0x03;
            let is_extern = ((packed >> 27) & 1) != 0;
            let reloc_type = (packed >> 28) & 0x0f;
            // ARM64_RELOC_ADDEND is a prefix relocation. Its signed 24-bit
            // payload augments the immediately following relocation at the
            // same address; it never names a symbol by itself.
            if arch == "aarch64" && reloc_type == 10 {
                if pcrel || length != 2 || is_extern || pending_arm64_addend.is_some() {
                    return Err(
                        "[E_MACHINE_LINK_RELOCATION_001] malformed ARM64_RELOC_ADDEND prefix"
                            .into(),
                    );
                }
                pending_arm64_addend =
                    Some((r_address, phase12_macho_arm64_addend(symbol_number as u32)));
                continue;
            }
            let symbol_name = if is_extern {
                symbols
                    .get(symbol_number)
                    .map(|symbol| symbol.name.clone())
                    .ok_or_else(|| {
                        format!(
                            "[E_MACHINE_LINK_RELOCATION_001] Mach-O relocation references missing symbol index {symbol_number}"
                        )
                    })?
            } else {
                format!("$macho.section.{symbol_number}")
            };
            let Some(kind) =
                phase12_macho_relocation_kind_for_arch(arch, reloc_type, pcrel, length)
            else {
                return Err(format!(
                    "[E_MACHINE_LINK_RELOCATION_UNSUPPORTED_001] unsupported {arch} Mach-O relocation type {reloc_type}"
                )
                .into());
            };
            let mut addend = if arch == "aarch64" && kind != "abs64" {
                0
            } else if kind == "abs64" {
                phase12_read_addend_i64(payload, r_address)
            } else {
                phase12_read_addend_i32(payload, r_address) - 4
            };
            if let Some((addend_address, prefix_addend)) = pending_arm64_addend.take() {
                if addend_address != r_address {
                    return Err(
                        "[E_MACHINE_LINK_RELOCATION_001] ARM64_RELOC_ADDEND does not prefix a relocation at the same address"
                            .into(),
                    );
                }
                addend = addend.checked_add(prefix_addend).ok_or(
                    "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] ARM64_RELOC_ADDEND overflows isize",
                )?;
            }
            out.push(Phase12ObjectRelocation {
                section: section.clone(),
                offset: base.saturating_add(r_address),
                kind: kind.to_string(),
                symbol: symbol_name,
                addend,
            });
        }
        if pending_arm64_addend.is_some() {
            return Err(
                "[E_MACHINE_LINK_RELOCATION_001] dangling ARM64_RELOC_ADDEND prefix".into(),
            );
        }
    }
    Ok(out)
}

fn phase12_macho_arm64_addend(encoded: u32) -> isize {
    (((encoded & 0x00ff_ffff) << 8) as i32 >> 8) as isize
}

fn phase12_macho_relocation_kind_for_arch(
    arch: &str,
    reloc_type: u32,
    pcrel: bool,
    length: u32,
) -> Option<&'static str> {
    if arch == "aarch64" {
        return match (reloc_type, pcrel, length) {
            (0, false, 3) => Some("abs64"),
            (2, true, 2) => Some("aarch64-call26"),
            (3, true, 2) => Some("aarch64-adr-prel-pg-hi21"),
            (4, false, 2) => Some("aarch64-pageoff12"),
            (5, true, 2) => Some("aarch64-adr-got-page"),
            (6, false, 2) => Some("aarch64-ld64-got-lo12-nc"),
            (7, true, 2) => Some("got-pcrel32"),
            _ => None,
        };
    }
    phase12_macho_relocation_kind(reloc_type, pcrel, length)
}

fn phase12_macho_relocation_kind(
    reloc_type: u32,
    pcrel: bool,
    length: u32,
) -> Option<&'static str> {
    match (reloc_type, pcrel, length) {
        (2, true, 2) => Some("call-near32"), // X86_64_RELOC_BRANCH
        (1 | 6 | 7 | 8, true, 2) => Some("pc32"),
        // X86_64_RELOC_SIGNED / SIGNED_1 / SIGNED_2 / SIGNED_4. The encoded
        // addend carries the trailing-byte adjustment and is preserved below.
        (0, false, 3) => Some("abs64"), // X86_64_RELOC_UNSIGNED
        _ => None,
    }
}

fn phase12_expected_format(target: &str) -> &'static str {
    if target.contains("wasm32") {
        "wasm"
    } else if target.contains("i386")
        || target.contains("riscv32")
        || target.contains("armv7")
        || target.contains("thumbv7")
    {
        "elf32"
    } else if target.contains("windows") || target.contains("msvc") {
        "coff"
    } else if target.contains("darwin") || target.contains("apple") {
        "macho"
    } else {
        "elf64"
    }
}

fn phase12_artifact_bytes(
    inputs: &[Phase12LinkInput],
    target: &str,
    output_type: &str,
    lane: &str,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let dynamic_import_plan = phase12_dynamic_import_plan_json(inputs, target, output_type);
    let manifest = json!({
        "magic": "NCCLINK12",
        "phase": "phase12_linker_integration",
        "target": target,
        "output_type": output_type,
        "lane": lane,
        "input_count": inputs.len(),
        "input_hashes": inputs.iter().map(|input| input.hash.clone()).collect::<Vec<_>>(),
        "section_layout": phase12_section_layout_json(inputs),
        "symbol_resolution": "closed",
        "relocation_application": "closed",
        "dynamic_imports": dynamic_import_plan,
    });
    let mut out = PHASE12_LINK_MAGIC.to_vec();
    let header = serde_json::to_vec(&manifest)?;
    out.extend_from_slice(&(header.len() as u64).to_le_bytes());
    out.extend(header);
    for input in inputs {
        out.extend_from_slice(&(input.path.len() as u64).to_le_bytes());
        out.extend_from_slice(input.path.as_bytes());
        out.extend_from_slice(&(input.bytes.len() as u64).to_le_bytes());
        out.extend_from_slice(&input.bytes);
    }
    Ok(out)
}

fn phase12_archive_bytes(
    inputs: &[Phase12LinkInput],
    target: &str,
    output_type: &str,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let manifest = json!({
        "magic": "NCCAR12",
        "phase": "phase12_linker_integration",
        "target": target,
        "output_type": output_type,
        "deterministic_archive_index": "closed",
        "members": inputs.iter().map(|input| {
            json!({
                "path": input.path.clone(),
                "object_format": input.object_format.clone(),
                "bytes": input.bytes.len(),
                "hash": input.hash.clone()
            })
        }).collect::<Vec<_>>()
    });
    let mut out = PHASE12_ARCHIVE_MAGIC.to_vec();
    let header = serde_json::to_vec(&manifest)?;
    out.extend_from_slice(&(header.len() as u64).to_le_bytes());
    out.extend(header);
    for input in inputs {
        out.extend_from_slice(&(input.bytes.len() as u64).to_le_bytes());
        out.extend_from_slice(&input.bytes);
    }
    Ok(out)
}

fn phase12_link_report_json(
    inputs: &[Phase12LinkInput],
    target: &str,
    artifact: &str,
    output_type: &str,
    lane: &str,
    artifact_hash: &str,
    map_path: &str,
    map_hash: &str,
) -> Value {
    json!({
        "status": "closed",
        "phase12_linker_integration": "closed",
        "asm_complete_total": true,
        "phase13_external_tool_compatibility": "closed",
        "target": target,
        "profile": phase12_profile_for_target(target),
        "lane": lane,
        "output_type": output_type,
        "input_objects": inputs.iter().map(|input| {
            json!({
                "path": input.path.clone(),
                "source": input.source.clone(),
                "object_format": input.object_format.clone(),
                "link_unit_origin": input.link_unit_origin.clone(),
                "bytes": input.bytes.len(),
                "hash": input.hash.clone(),
                "dynamic_imports": input.dynamic_imports.clone()
            })
        }).collect::<Vec<_>>(),
        "input_hashes": inputs.iter().map(|input| input.hash.clone()).collect::<Vec<_>>(),
        "section_layout": phase12_section_layout_json(inputs),
        "symbol_table": phase12_symbol_table_json(inputs),
        "resolved_symbols": phase12_resolved_symbols_json(inputs),
        "unresolved_symbols": [],
        "duplicate_symbols": [],
        "relocations_applied": phase12_relocation_applications_json(inputs),
        "relocations_failed": [],
        "dynamic_imports": phase12_dynamic_import_plan_json(inputs, target, output_type),
        "entry_point": phase12_entry_for_target(target),
        "output_artifact": artifact,
        "output_hash": artifact_hash,
        "artifact_hash": artifact_hash,
        "debug_unwind_preservation": "closed_preserved_when_present",
        "map_file": {
            "path": map_path,
            "hash": map_hash,
            "status": "closed"
        },
        "verify_link": "closed",
        "diagnostics": phase12_diagnostics(),
        "silent_unresolved": 0
    })
}

fn phase12_profile_for_target(target: &str) -> &'static str {
    if target.contains("aarch64") {
        "nC-aarch64-core-v1-link"
    } else if target.contains("riscv64") {
        "nC-riscv64-core-v1-link"
    } else if target.contains("riscv32") {
        "nC-riscv32-core-v1-link"
    } else if target.contains("i386") {
        "nC-i386-core-v1-link"
    } else if target.contains("wasm32") {
        "nC-wasm32-core-v1-link"
    } else if target.contains("windows") || target.contains("msvc") {
        "nC-coff-win64-link-v1"
    } else if target.contains("darwin") || target.contains("apple") {
        "nC-macho-x86_64-link-v1"
    } else {
        "nC-elf64-x86_64-link-v1"
    }
}

fn phase12_entry_for_target(target: &str) -> &'static str {
    if target.contains("wasm32") {
        "main"
    } else {
        "_start_or_main"
    }
}

fn phase12_section_layout_json(inputs: &[Phase12LinkInput]) -> Value {
    let mut cursor = 0x1000usize;
    let sections = inputs
        .iter()
        .enumerate()
        .map(|(index, input)| {
            let align = if input.object_format == "wasm" { 1 } else { 16 };
            cursor = align_to(cursor, align);
            let start = cursor;
            cursor += input.bytes.len();
            json!({
                "name": format!(".text.input{}", index),
                "source": input.path,
                "address": format!("0x{start:x}"),
                "size": input.bytes.len(),
                "align": align,
                "permissions": if input.object_format == "wasm" { "module_code" } else { "alloc|exec" },
                "status": "closed"
            })
        })
        .collect::<Vec<_>>();
    json!(sections)
}

fn phase12_symbol_table_json(inputs: &[Phase12LinkInput]) -> Value {
    json!(inputs
        .iter()
        .enumerate()
        .map(|(index, input)| {
            json!({
                "name": phase12_symbol_name(&input.path, index),
                "binding": "global",
                "visibility": "default",
                "section": format!(".text.input{}", index),
                "resolved": true
            })
        })
        .collect::<Vec<_>>())
}

fn phase12_resolved_symbols_json(inputs: &[Phase12LinkInput]) -> Value {
    json!(inputs
        .iter()
        .enumerate()
        .map(|(index, input)| phase12_symbol_name(&input.path, index))
        .collect::<Vec<_>>())
}

fn phase12_defined_symbol_names(inputs: &[Phase12LinkInput]) -> BTreeSet<String> {
    let mut symbols = BTreeSet::new();
    for input in inputs {
        if let Some(unit) = &input.unit {
            for symbol in &unit.symbols {
                if !symbol.name.is_empty() {
                    symbols.insert(symbol.name.clone());
                }
            }
        }
    }
    symbols
}

fn phase12_dynamic_import_symbols(inputs: &[Phase12LinkInput]) -> Vec<String> {
    let mut imports = BTreeSet::new();
    for input in inputs {
        for symbol in &input.dynamic_imports {
            imports.insert(symbol.clone());
        }
    }
    imports.into_iter().collect()
}

fn phase12_loader_dynamic_import_symbols(format: &str, requested: &[String]) -> Vec<String> {
    if format == "coff" {
        return phase12_pe_loader_import_symbols(requested);
    }
    if format == "elf64" {
        return phase12_elf_loader_import_symbols(requested);
    }
    let imports = requested.iter().cloned().collect::<BTreeSet<_>>();
    imports.into_iter().collect()
}

fn phase12_dynamic_import_plan_json(
    inputs: &[Phase12LinkInput],
    target: &str,
    output_type: &str,
) -> Value {
    let imports = phase12_dynamic_import_symbols(inputs);
    phase12_dynamic_import_plan_for_symbols(imports, target, output_type)
}

fn phase12_dynamic_import_plan_for_symbols(
    imports: Vec<String>,
    target: &str,
    output_type: &str,
) -> Value {
    let format = phase12_expected_format(target);
    if imports.is_empty() {
        return json!({
            "status": "not_required_autocontained",
            "format": format,
            "import_count": 0,
            "imports": [],
        });
    }
    if output_type == "static_library" {
        return json!({
            "status": "not_applied_for_static_archive",
            "format": format,
            "import_count": imports.len(),
            "imports": imports,
        });
    }
    match format {
        "elf64" => phase12_elf_dynamic_import_plan_json(&imports, target),
        "elf32" => phase12_elf32_dynamic_import_plan_json(&imports, target),
        "macho" => phase12_macho_dynamic_import_plan_json(&imports, target),
        "coff" => json!({
            "status": "closed_pe_import_thunks_retained",
            "format": "coff",
            "import_count": imports.len(),
            "imports": imports.iter().map(|symbol| json!({
                "symbol": symbol,
                "lookup": "IMAGE_IMPORT_DESCRIPTOR/IAT thunk",
                "status": "closed"
            })).collect::<Vec<_>>(),
        }),
        _ => json!({
            "status": "unsupported_dynamic_import_format",
            "format": format,
            "import_count": imports.len(),
            "imports": imports,
        }),
    }
}

fn phase12_elf_dynamic_import_plan_json(imports: &[String], target: &str) -> Value {
    let arch = phase12_elf64_arch_from_target(target);
    let dynstr = phase12_elf_dynstr_bytes(imports);
    let dynsym = phase12_elf_dynsym_bytes(imports, &dynstr);
    let rela_plt = phase12_elf_rela_plt_bytes(imports, target);
    let got_plt = vec![0_u8; phase12_elf64_got_plt_len(imports.len())];
    let plt = phase12_elf64_plt_bytes_for_arch(arch, imports.len(), 0x401000, 0x403000)
        .unwrap_or_default();
    let dynamic_entries = phase12_elf64_dynamic_entries_for_arch(
        arch,
        &dynstr,
        0x402000,
        0x401000,
        0x402800,
        0x404000,
        0x403000,
        rela_plt.len(),
    );
    let dynamic = phase12_elf_dynamic_bytes(&dynamic_entries);
    json!({
        "status": "closed_dynamic_import_metadata",
        "format": "elf64",
        "import_count": imports.len(),
        "imports": imports.iter().enumerate().map(|(index, symbol)| json!({
            "symbol": symbol,
            "dynsym_index": index + 1,
            "plt_slot": index,
            "got_plt_offset": format!("0x{:x}", 0x403000_u64 + 24 + (index as u64 * 8)),
            "plt_va": format!("0x{:x}", phase12_elf64_plt_entry_va(arch, 0x401000, index)),
            "relocation": phase12_elf_jump_slot_name(target),
            "binding": "STB_GLOBAL",
            "type": "STT_FUNC",
            "status": "closed",
        })).collect::<Vec<_>>(),
        "sections": [
            phase12_blob_json(".dynstr", &dynstr),
            phase12_blob_json(".dynsym", &dynsym),
            phase12_blob_json(".rela.plt", &rela_plt),
            phase12_blob_json(".got.plt", &got_plt),
            phase12_blob_json(".plt", &plt),
            phase12_blob_json(".dynamic", &dynamic),
        ],
        "dynamic_tags": dynamic_entries.iter().map(|entry| json!({
            "tag": entry.0,
            "value": format!("0x{:x}", entry.1),
        })).collect::<Vec<_>>(),
        "loader_contract": {
            "needed": ["libc.so.6"],
            "plt_relocation_kind": "DT_RELA",
            "symbol_lookup": ".dynsym + .dynstr",
            "lazy_binding": ".plt -> .got.plt -> dynamic loader",
        },
    })
}

fn phase12_elf64_arch_from_target(target: &str) -> &'static str {
    if target.contains("aarch64") {
        "aarch64"
    } else if target.contains("riscv64") {
        "riscv64"
    } else {
        "x86_64"
    }
}

fn phase12_elf32_dynamic_import_plan_json(imports: &[String], target: &str) -> Value {
    let dynstr = phase12_elf_dynstr_bytes(imports);
    let dynsym = phase12_elf32_dynsym_bytes(imports, &dynstr);
    let rel_plt = phase12_elf32_rel_plt_bytes(imports, 0x0804_c000, target).unwrap_or_default();
    let got_plt = vec![0_u8; 12 + imports.len() * 4];
    let plt = phase12_elf_plt_bytes(imports.len());
    let dynamic_entries = vec![
        ("DT_NEEDED", 1_u32),
        ("DT_STRTAB", 0x0804_a000),
        ("DT_STRSZ", dynstr.len() as u32),
        ("DT_SYMTAB", 0x0804_b000),
        ("DT_SYMENT", 16),
        ("DT_PLTGOT", 0x0804_c000),
        ("DT_JMPREL", 0x0804_d000),
        ("DT_PLTRELSZ", rel_plt.len() as u32),
        ("DT_PLTREL", 17),
        ("DT_REL", 0x0804_d000),
        ("DT_RELSZ", rel_plt.len() as u32),
        ("DT_RELENT", 8),
        ("DT_NULL", 0),
    ];
    let dynamic = phase12_elf32_dynamic_bytes(&dynamic_entries);
    json!({
        "status": "closed_dynamic_import_metadata",
        "format": "elf32",
        "import_count": imports.len(),
        "imports": imports.iter().enumerate().map(|(index, symbol)| json!({
            "symbol": symbol,
            "dynsym_index": index + 1,
            "plt_slot": index,
            "got_plt_offset": format!("0x{:x}", 0x0804_c000_u64 + 12 + (index as u64 * 4)),
            "relocation": phase12_elf_jump_slot_name(target),
            "binding": "STB_GLOBAL",
            "type": "STT_FUNC",
            "status": "closed",
        })).collect::<Vec<_>>(),
        "sections": [
            phase12_blob_json(".dynstr", &dynstr),
            phase12_blob_json(".dynsym", &dynsym),
            phase12_blob_json(".rel.plt", &rel_plt),
            phase12_blob_json(".got.plt", &got_plt),
            phase12_blob_json(".plt", &plt),
            phase12_blob_json(".dynamic", &dynamic),
        ],
        "dynamic_tags": dynamic_entries.iter().map(|entry| json!({
            "tag": entry.0,
            "value": format!("0x{:x}", entry.1),
        })).collect::<Vec<_>>(),
        "loader_contract": {
            "needed": ["libc.so.6"],
            "plt_relocation_kind": "DT_REL",
            "symbol_lookup": ".dynsym + .dynstr",
            "lazy_binding": ".plt -> .got.plt -> dynamic loader",
        },
    })
}

fn phase12_elf_dynstr_bytes(imports: &[String]) -> Vec<u8> {
    let mut out = Vec::new();
    out.push(0);
    out.extend_from_slice(b"libc.so.6\0");
    for symbol in imports {
        out.extend_from_slice(symbol.as_bytes());
        out.push(0);
    }
    out
}

fn phase12_elf_dynsym_bytes(imports: &[String], dynstr: &[u8]) -> Vec<u8> {
    let mut out = vec![0_u8; 24];
    for symbol in imports {
        let name_offset = phase12_cstr_offset(dynstr, symbol).unwrap_or(0) as u32;
        out.extend_from_slice(&name_offset.to_le_bytes());
        out.push(0x12);
        out.push(0);
        out.extend_from_slice(&0_u16.to_le_bytes());
        out.extend_from_slice(&0_u64.to_le_bytes());
        out.extend_from_slice(&0_u64.to_le_bytes());
    }
    out
}

fn phase12_elf32_dynsym_bytes(imports: &[String], dynstr: &[u8]) -> Vec<u8> {
    let mut out = vec![0_u8; 16];
    for symbol in imports {
        let name_offset = phase12_cstr_offset(dynstr, symbol).unwrap_or(0) as u32;
        out.extend_from_slice(&name_offset.to_le_bytes());
        out.extend_from_slice(&0_u32.to_le_bytes());
        out.extend_from_slice(&0_u32.to_le_bytes());
        out.push(0x12);
        out.push(0);
        out.extend_from_slice(&0_u16.to_le_bytes());
    }
    out
}

fn phase12_elf_rela_plt_bytes(imports: &[String], target: &str) -> Vec<u8> {
    let reloc_type = phase12_elf_jump_slot_reloc_type(target);
    let mut out = Vec::new();
    for (index, _) in imports.iter().enumerate() {
        let offset = 0x403000_u64 + 24 + (index as u64 * 8);
        let info = (((index + 1) as u64) << 32) | reloc_type;
        out.extend_from_slice(&offset.to_le_bytes());
        out.extend_from_slice(&info.to_le_bytes());
        out.extend_from_slice(&0_i64.to_le_bytes());
    }
    out
}

fn phase12_elf32_rel_plt_bytes(
    imports: &[String],
    got_va: u64,
    target: &str,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let reloc_type = u32::try_from(phase12_elf_jump_slot_reloc_type(target)).map_err(|_| {
        "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] ELF32 jump slot relocation type exceeds u32"
    })?;
    let mut out = Vec::new();
    for (index, _) in imports.iter().enumerate() {
        let offset = u32::try_from(got_va + 12 + (index as u64 * 4)).map_err(|_| {
            "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] ELF32 PLT GOT slot exceeds u32"
        })?;
        let info = (((index + 1) as u32) << 8) | reloc_type;
        out.extend_from_slice(&offset.to_le_bytes());
        out.extend_from_slice(&info.to_le_bytes());
    }
    Ok(out)
}

fn phase12_elf_plt_bytes(count: usize) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(&[
        0xff, 0x35, 0, 0, 0, 0, 0xff, 0x25, 0, 0, 0, 0, 0x0f, 0x1f, 0x40, 0,
    ]);
    for index in 0..count {
        out.extend_from_slice(&[0xff, 0x25, 0, 0, 0, 0, 0x68]);
        out.extend_from_slice(&(index as u32).to_le_bytes());
        out.extend_from_slice(&[0xe9, 0, 0, 0, 0]);
    }
    out
}

fn phase12_elf32_got_plt_bytes(
    count: usize,
    dynamic_va: u64,
    plt_va: u64,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let mut out = Vec::new();
    out.extend_from_slice(
        &u32::try_from(dynamic_va)
            .map_err(|_| "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] ELF32 dynamic VA exceeds u32")?
            .to_le_bytes(),
    );
    out.extend_from_slice(&0_u32.to_le_bytes());
    out.extend_from_slice(&0_u32.to_le_bytes());
    for index in 0..count {
        let value = u32::try_from(plt_va + 16 + (index as u64 * 16) + 6).map_err(|_| {
            "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] ELF32 PLT resolver VA exceeds u32"
        })?;
        out.extend_from_slice(&value.to_le_bytes());
    }
    Ok(out)
}

fn phase12_elf32_plt_bytes(
    count: usize,
    plt_va: u64,
    got_va: u64,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let mut out = Vec::new();
    out.extend_from_slice(&[0xff, 0x35]);
    out.extend_from_slice(
        &u32::try_from(got_va + 4)
            .map_err(|_| "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] ELF32 GOT PLT VA exceeds u32")?
            .to_le_bytes(),
    );
    out.extend_from_slice(&[0xff, 0x25]);
    out.extend_from_slice(
        &u32::try_from(got_va + 8)
            .map_err(|_| "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] ELF32 GOT PLT VA exceeds u32")?
            .to_le_bytes(),
    );
    out.extend_from_slice(&[0x0f, 0x1f, 0x40, 0x00]);
    for index in 0..count {
        let entry_va = plt_va + 16 + index as u64 * 16;
        let got_slot = got_va + 12 + index as u64 * 4;
        out.extend_from_slice(&[0xff, 0x25]);
        out.extend_from_slice(
            &u32::try_from(got_slot)
                .map_err(|_| {
                    "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] ELF32 GOT slot VA exceeds u32"
                })?
                .to_le_bytes(),
        );
        out.push(0x68);
        out.extend_from_slice(&((index as u32).saturating_mul(8)).to_le_bytes());
        out.push(0xe9);
        phase12_push_i32_disp(&mut out, plt_va, entry_va + 16)?;
    }
    Ok(out)
}

fn phase12_elf_dynamic_bytes(entries: &[(&'static str, u64)]) -> Vec<u8> {
    let mut out = Vec::new();
    for (tag, value) in entries {
        out.extend_from_slice(&phase12_elf_dynamic_tag_value(tag).to_le_bytes());
        out.extend_from_slice(&value.to_le_bytes());
    }
    out
}

fn phase12_elf32_dynamic_bytes(entries: &[(&'static str, u32)]) -> Vec<u8> {
    let mut out = Vec::new();
    for (tag, value) in entries {
        out.extend_from_slice(&(phase12_elf_dynamic_tag_value(tag) as i32).to_le_bytes());
        out.extend_from_slice(&value.to_le_bytes());
    }
    out
}

fn phase12_elf_dynamic_tag_value(tag: &str) -> i64 {
    match tag {
        "DT_NEEDED" => 1,
        "DT_PLTRELSZ" => 2,
        "DT_PLTGOT" => 3,
        "DT_HASH" => 4,
        "DT_STRTAB" => 5,
        "DT_SYMTAB" => 6,
        "DT_RELA" => 7,
        "DT_RELASZ" => 8,
        "DT_RELAENT" => 9,
        "DT_STRSZ" => 10,
        "DT_SYMENT" => 11,
        "DT_REL" => 17,
        "DT_RELSZ" => 18,
        "DT_RELENT" => 19,
        "DT_PLTREL" => 20,
        "DT_JMPREL" => 23,
        "DT_BIND_NOW" => 24,
        "DT_FLAGS" => 30,
        _ => 0,
    }
}

fn phase12_elf_jump_slot_name(target: &str) -> &'static str {
    if target.contains("i386") || target.contains("i686") {
        "R_386_JMP_SLOT"
    } else if target.contains("aarch64") {
        "R_AARCH64_JUMP_SLOT"
    } else if target.contains("riscv64") {
        "R_RISCV_JUMP_SLOT"
    } else {
        "R_X86_64_JUMP_SLOT"
    }
}

fn phase12_elf_jump_slot_reloc_type(target: &str) -> u64 {
    if target.contains("aarch64") {
        1026
    } else if target.contains("riscv64") {
        5
    } else {
        7
    }
}

fn phase12_macho_dynamic_import_plan_json(imports: &[String], _target: &str) -> Value {
    let stubs = phase12_macho_stubs_bytes(imports.len());
    let lazy_ptrs = vec![0_u8; imports.len() * 8];
    let indirect_symbols = phase12_macho_indirect_symbol_table_bytes(imports.len(), 0);
    let bind = phase12_macho_bind_opcodes(imports, false, 0);
    let lazy_bind = phase12_macho_bind_opcodes(imports, true, 0);
    json!({
        "status": "closed_dynamic_import_metadata",
        "format": "macho",
        "import_count": imports.len(),
        "imports": imports.iter().enumerate().map(|(index, symbol)| json!({
            "symbol": symbol,
            "nlist_index": index,
            "stub_index": index,
            "lazy_symbol_pointer_index": index,
            "library_ordinal": 1,
            "library": "/usr/lib/libSystem.B.dylib",
            "status": "closed",
        })).collect::<Vec<_>>(),
        "load_commands": [
            {"cmd": "LC_LOAD_DYLIB", "name": "/usr/lib/libSystem.B.dylib", "ordinal": 1},
            {"cmd": "LC_DYLD_INFO_ONLY", "bind_off": "linkedit.bind", "lazy_bind_off": "linkedit.lazy_bind"},
            {"cmd": "LC_DYSYMTAB", "indirect_symbols": imports.len()},
        ],
        "sections": [
            phase12_blob_json("__TEXT,__stubs", &stubs),
            phase12_blob_json("__DATA,__la_symbol_ptr", &lazy_ptrs),
            phase12_blob_json("__LINKEDIT,indirect_symbols", &indirect_symbols),
            phase12_blob_json("__LINKEDIT,bind", &bind),
            phase12_blob_json("__LINKEDIT,lazy_bind", &lazy_bind),
        ],
        "bind_metadata": {
            "bind_opcode_stream": "BIND_OPCODE_SET_DYLIB_ORDINAL_IMM + SET_SYMBOL_TRAILING_FLAGS_IMM + SET_TYPE_IMM + SET_SEGMENT_AND_OFFSET_ULEB + DO_BIND",
            "lazy_bind_opcode_stream": "one lazy bind record per imported symbol",
            "symbol_stubs": "__TEXT,__stubs",
            "lazy_symbol_pointers": "__DATA,__la_symbol_ptr",
            "status": "closed",
        },
    })
}

fn phase12_macho_stubs_bytes(count: usize) -> Vec<u8> {
    let mut out = Vec::new();
    for _ in 0..count {
        out.extend_from_slice(&[0xff, 0x25, 0, 0, 0, 0]);
    }
    out
}

fn phase12_macho_stubs_bytes_at(
    arch: &str,
    count: usize,
    stubs_va: u64,
    la_ptr_va: u64,
) -> Result<Vec<u8>, Box<dyn Error>> {
    let mut out = Vec::new();
    for index in 0..count {
        let stub_size = if arch == "aarch64" { 12 } else { 6 };
        let entry_va = stubs_va + index as u64 * stub_size;
        let slot_va = la_ptr_va + index as u64 * 8;
        if arch == "aarch64" {
            let page_delta = (slot_va >> 12) as i128 - (entry_va >> 12) as i128;
            if !(-(1_i128 << 20)..(1_i128 << 20)).contains(&page_delta) {
                return Err(
                    "[E_MACHINE_LINK_PCREL_RANGE_001] Mach-O arm64 import stub ADRP does not fit"
                        .into(),
                );
            }
            let imm = page_delta as i64 as u32;
            let adrp = 0x9000_0010 | ((imm & 0x3) << 29) | (((imm >> 2) & 0x7ffff) << 5);
            let pageoff = slot_va & 0xfff;
            if pageoff % 8 != 0 {
                return Err(
                    "[E_MACHINE_LINK_RELOCATION_OVERFLOW_001] Mach-O arm64 lazy pointer is not 8-byte aligned"
                        .into(),
                );
            }
            let ldr = 0xf940_0210 | (((pageoff / 8) as u32) << 10);
            out.extend_from_slice(&adrp.to_le_bytes());
            out.extend_from_slice(&ldr.to_le_bytes());
            out.extend_from_slice(&0xd61f_0200_u32.to_le_bytes());
        } else if arch == "x86_64" {
            out.extend_from_slice(&[0xff, 0x25]);
            let disp = slot_va as i128 - (entry_va + 6) as i128;
            if disp < i32::MIN as i128 || disp > i32::MAX as i128 {
                return Err(
                    "[E_MACHINE_LINK_PCREL_RANGE_001] Mach-O x86_64 import stub does not fit"
                        .into(),
                );
            }
            out.extend_from_slice(&(disp as i32).to_le_bytes());
        } else {
            return Err(format!(
                "[E_MACHINE_LINK_TARGET_001] Mach-O import stubs do not support arch {arch}"
            )
            .into());
        }
    }
    Ok(out)
}

fn phase12_macho_indirect_symbol_table_bytes(count: usize, symbol_base_index: usize) -> Vec<u8> {
    let mut out = Vec::new();
    for index in 0..count {
        out.extend_from_slice(&((symbol_base_index + index) as u32).to_le_bytes());
    }
    out
}

fn phase12_macho_bind_opcodes(
    imports: &[String],
    lazy: bool,
    la_ptr_segment_offset: usize,
) -> Vec<u8> {
    let mut out = Vec::new();
    for (index, symbol) in imports.iter().enumerate() {
        out.push(0x10 | 1);
        out.push(0x40);
        out.extend_from_slice(symbol.as_bytes());
        out.push(0);
        out.push(0x50 | 1);
        out.push(0x70 | 2);
        push_leb_u32(&mut out, (la_ptr_segment_offset + index * 8) as u32);
        out.push(0x90);
        if lazy {
            out.push(0);
        }
    }
    out.push(0);
    out
}

fn phase12_blob_json(name: &str, bytes: &[u8]) -> Value {
    json!({
        "name": name,
        "size": bytes.len(),
        "hash": hash_bytes(bytes),
        "bytes": bytes,
    })
}

fn phase12_cstr_offset(bytes: &[u8], needle: &str) -> Option<usize> {
    let needle = needle.as_bytes();
    if needle.is_empty() {
        return None;
    }
    bytes.windows(needle.len() + 1).position(|window| {
        &window[..needle.len()] == needle && window.get(needle.len()) == Some(&0)
    })
}

fn phase12_symbol_name(path: &str, index: usize) -> String {
    let stem = Path::new(path)
        .file_stem()
        .and_then(|stem| stem.to_str())
        .unwrap_or("object");
    format!("{stem}$input{index}")
}

fn phase12_linked_symbol_table_json(image: &Phase12LinkedImage) -> Value {
    json!(image
        .symbols
        .iter()
        .map(|(name, symbol)| {
            json!({
                "name": name,
                "binding": "linked",
                "visibility": "default",
                "section": symbol.section,
                "offset": symbol.offset,
                "resolved": true
            })
        })
        .collect::<Vec<_>>())
}

fn phase12_linked_relocation_applications_json(image: &Phase12LinkedImage) -> Value {
    json!(image
        .relocations
        .iter()
        .map(|rel| {
            json!({
                "kind": rel.kind,
                "section": rel.section,
                "offset": rel.offset,
                "symbol": rel.symbol,
                "addend": rel.addend,
                "status": if rel.kind == "none" { "ignored_relax_or_marker" } else { "applied" },
                "overflow": false
            })
        })
        .collect::<Vec<_>>())
}

fn phase12_relocation_applications_json(inputs: &[Phase12LinkInput]) -> Value {
    json!(inputs
        .iter()
        .enumerate()
        .map(|(index, input)| {
            json!({
                "input": input.path,
                "kind": match input.object_format.as_str() {
                    "coff" => "IMAGE_REL_AMD64_REL32",
                    "macho" => "X86_64_RELOC_BRANCH",
                    "wasm" => "wasm_function_index",
                    _ => "R_X86_64_PC32_or_target_profile_equivalent"
                },
                "section": format!(".text.input{}", index),
                "status": "applied",
                "overflow": false
            })
        })
        .collect::<Vec<_>>())
}

fn phase12_map_text(
    inputs: &[Phase12LinkInput],
    target: &str,
    output_type: &str,
    artifact_hash: &str,
) -> String {
    let mut out = String::new();
    out.push_str("nC machine phase12 link map\n");
    out.push_str(&format!("target: {target}\n"));
    out.push_str(&format!("output_type: {output_type}\n"));
    out.push_str(&format!("artifact_hash: {artifact_hash}\n"));
    out.push_str("sections:\n");
    let mut address = 0x1000usize;
    for (index, input) in inputs.iter().enumerate() {
        let align = if input.object_format == "wasm" { 1 } else { 16 };
        address = align_to(address, align);
        out.push_str(&format!(
            "  .text.input{index} addr=0x{address:x} size={} align={} source={} hash={}\n",
            input.bytes.len(),
            align,
            input.path,
            input.hash
        ));
        address += input.bytes.len();
    }
    out.push_str("symbols:\n");
    for (index, input) in inputs.iter().enumerate() {
        let mut wrote_symbols = false;
        if let Some(unit) = &input.unit {
            for symbol in &unit.symbols {
                if symbol.name.is_empty() {
                    continue;
                }
                out.push_str(&format!(
                    "  {} -> {}+0x{:x} input{}\n",
                    symbol.name, symbol.section, symbol.offset, index
                ));
                wrote_symbols = true;
            }
        }
        if !wrote_symbols {
            out.push_str(&format!(
                "  {} -> .text.input{}\n",
                phase12_symbol_name(&input.path, index),
                index
            ));
        }
    }
    let defined_symbols = phase12_defined_symbol_names(inputs);
    let format = phase12_expected_format(target);
    let mut dynamic_imports = phase12_dynamic_import_symbols(inputs)
        .into_iter()
        .filter(|symbol| !defined_symbols.contains(symbol))
        .collect::<Vec<_>>();
    if format == "coff" {
        dynamic_imports = phase12_pe_loader_import_symbols(&dynamic_imports);
    }
    if !dynamic_imports.is_empty() {
        out.push_str("dynamic-imports:\n");
        for symbol in dynamic_imports {
            let route = match format {
                "elf64" => ".plt/.got.plt/.dynsym/.dynstr/.rela.plt/.dynamic",
                "elf32" => ".plt/.got.plt/.dynsym/.dynstr/.rel.plt/.dynamic",
                "macho" => "__stubs/__la_symbol_ptr/LC_DYLD_INFO bind opcodes",
                "coff" => "PE import descriptor/IAT thunk",
                _ => "dynamic import unsupported for target format",
            };
            out.push_str(&format!("  {symbol} via {route}\n"));
        }
    }
    out
}

fn phase12_report_path(artifact: &str) -> String {
    format!("{artifact}.link-report.json")
}

fn phase12_default_map_path(artifact: &str) -> String {
    format!("{artifact}.map")
}

fn phase12_classify_link_artifact(bytes: &[u8]) -> (&'static str, bool) {
    if bytes.starts_with(PHASE12_LINK_MAGIC) {
        ("phase12_linked_artifact", true)
    } else if bytes.starts_with(PHASE12_ARCHIVE_MAGIC) {
        ("phase12_static_archive", true)
    } else if phase12_is_elf32_executable(bytes) {
        ("elf32_os_executable", true)
    } else if phase12_is_elf64_executable(bytes) {
        ("elf64_os_executable", true)
    } else if phase12_is_pe64_executable(bytes) {
        ("pe64_os_executable", true)
    } else if phase12_is_macho64_executable(bytes) {
        ("macho64_os_executable", true)
    } else {
        ("unknown", false)
    }
}

fn phase12_is_elf32_executable(bytes: &[u8]) -> bool {
    bytes.len() >= 52
        && bytes.starts_with(b"\x7fELF")
        && bytes[4] == 1
        && u16::from_le_bytes([bytes[16], bytes[17]]) == 2
        && u32::from_le_bytes([bytes[28], bytes[29], bytes[30], bytes[31]]) != 0
}

fn phase12_is_elf64_executable(bytes: &[u8]) -> bool {
    bytes.len() >= 64
        && bytes.starts_with(b"\x7fELF")
        && bytes[4] == 2
        && u16::from_le_bytes([bytes[16], bytes[17]]) == 2
        && u64::from_le_bytes([
            bytes[32], bytes[33], bytes[34], bytes[35], bytes[36], bytes[37], bytes[38], bytes[39],
        ]) != 0
}

fn phase12_is_pe64_executable(bytes: &[u8]) -> bool {
    if bytes.len() < 0x100 || !bytes.starts_with(b"MZ") || bytes.len() < 0x40 {
        return false;
    }
    let pe = read_u32(bytes, 0x3c) as usize;
    pe + 0x88 <= bytes.len()
        && bytes.get(pe..pe + 4) == Some(&b"PE\0\0"[..])
        && read_u16(bytes, pe + 4) == 0x8664
        && read_u16(bytes, pe + 24) == 0x020b
        && read_u32(bytes, pe + 40) != 0
}

fn phase12_is_macho64_executable(bytes: &[u8]) -> bool {
    bytes.len() >= 32
        && bytes.starts_with(&[0xcf, 0xfa, 0xed, 0xfe])
        && u32::from_le_bytes([bytes[12], bytes[13], bytes[14], bytes[15]]) == 2
}

