fn run_phase13_external_tools(args: &[String]) -> Result<(), Box<dyn Error>> {
    let payload = phase13_external_tools_json();
    if has_flag(args, "--json") {
        print_json(&payload)?;
    } else {
        println!(
            "machine external-tools: discovered={} blocked_by_environment={}",
            payload["tool_count"].as_u64().unwrap_or(0),
            payload["blocked_by_environment"].as_u64().unwrap_or(0)
        );
    }
    Ok(())
}

fn run_phase13_external_compat(args: &[String]) -> Result<(), Box<dyn Error>> {
    if args.is_empty() || is_help(args.first()) {
        println!(
            "Usage: machine external-compat <doctor|matrix|report|validate|validate-debug|validate-link> [artifact] [--profile <profile>] [--json]"
        );
        return Ok(());
    }
    match args[0].as_str() {
        "doctor" => print_json(&phase13_external_compat_doctor_json())?,
        "matrix" => print_json(&phase13_external_compat_matrix_json())?,
        "report" => print_json(&phase13_external_compat_report_json())?,
        "validate" => {
            let artifact = first_non_flag(&args[1..])
                .ok_or("machine external-compat validate expects an artifact path")?;
            let profile = option_value(&args[1..], "--profile")
                .map(phase13_normalize_profile)
                .unwrap_or_else(|| phase13_profile_for_artifact_path(artifact));
            let payload = phase13_validate_artifact_json(artifact, &profile)?;
            print_json(&payload)?;
        }
        "validate-debug" => {
            let artifact = first_non_flag(&args[1..])
                .ok_or("machine external-compat validate-debug expects an artifact path")?;
            let payload = phase13_validate_artifact_json(artifact, "debug")?;
            print_json(&payload)?;
        }
        "validate-link" => {
            let artifact = first_non_flag(&args[1..])
                .ok_or("machine external-compat validate-link expects an artifact path")?;
            let payload = phase13_validate_artifact_json(artifact, "linker")?;
            print_json(&payload)?;
        }
        other => {
            return Err(format!(
                "[E_MACHINE_EXTERNAL_COMPAT_001] unknown external-compat command '{}'",
                other
            )
            .into());
        }
    }
    Ok(())
}

