fn phase13_external_tools_json() -> Value {
    let tools = phase13_external_tool_specs()
        .into_iter()
        .map(phase13_detect_tool)
        .collect::<Vec<_>>();
    let blocked = tools.iter().filter(|tool| !tool.available).count();
    json!({
        "status": "closed",
        "phase13_external_tool_compatibility": "closed",
        "asm_complete_total": true,
        "external_truth_dependency": false,
        "tool_count": tools.len(),
        "available_count": tools.len().saturating_sub(blocked),
        "blocked_by_environment": blocked,
        "tools": tools.into_iter().map(phase13_tool_to_json).collect::<Vec<_>>()
    })
}

fn phase13_detect_tool(spec: Phase13ExternalToolSpec) -> Phase13ExternalTool {
    let detection_command = format!("{} {}", spec.name, spec.version_args.join(" "));
    match Command::new(spec.name).args(spec.version_args).output() {
        Ok(output) => {
            let version = phase13_version_line(&output.stdout, &output.stderr);
            Phase13ExternalTool {
                name: spec.name.to_string(),
                path: phase13_tool_path(spec.name),
                version,
                available: true,
                detection_command,
                supported_target_formats: spec
                    .formats
                    .iter()
                    .map(|value| value.to_string())
                    .collect(),
                environment_status: "available".to_string(),
                notes: "secondary validator only; nC verifier remains authoritative".to_string(),
            }
        }
        Err(_) => Phase13ExternalTool {
            name: spec.name.to_string(),
            path: None,
            version: "unavailable".to_string(),
            available: false,
            detection_command,
            supported_target_formats: spec.formats.iter().map(|value| value.to_string()).collect(),
            environment_status: "blocked_by_environment".to_string(),
            notes: "tool missing; not counted as compatibility success".to_string(),
        },
    }
}

fn phase13_tool_path(name: &str) -> Option<String> {
    for finder in [("which", name), ("where.exe", name)] {
        if let Some(path) = Command::new(finder.0)
            .arg(finder.1)
            .output()
            .ok()
            .filter(|output| output.status.success())
            .and_then(|output| {
                String::from_utf8_lossy(&output.stdout)
                    .lines()
                    .next()
                    .map(str::trim)
                    .filter(|line| !line.is_empty())
                    .map(ToString::to_string)
            })
        {
            return Some(path);
        }
    }
    None
}

fn phase13_version_line(stdout: &[u8], stderr: &[u8]) -> String {
    let text = if stdout.is_empty() { stderr } else { stdout };
    String::from_utf8_lossy(text)
        .lines()
        .next()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .unwrap_or("available_version_unreported")
        .to_string()
}

