fn phase13_validate_artifact_json(path: &str, profile: &str) -> Result<Value, Box<dyn Error>> {
    let bytes = fs::read(path).map_err(|err| {
        format!(
            "[E_MACHINE_EXTERNAL_COMPAT_FAIL_001] cannot read external validation artifact '{}': {}",
            path, err
        )
    })?;
    let profile = phase13_normalize_profile(profile);
    let (object_format, object_ok) = classify_object_bytes(&bytes);
    let (link_artifact_type, link_ok) = phase12_classify_link_artifact(&bytes);
    let archive_ok = link_artifact_type == "phase12_static_archive";
    let internal_ok = match profile.as_str() {
        "elf64" => object_ok && object_format == "elf64",
        "coff" => object_ok && object_format == "coff",
        "macho" => object_ok && object_format == "macho",
        "wasm" => object_ok && object_format == "wasm",
        "debug" => object_ok || link_ok,
        "linker" => link_ok,
        "archive" => archive_ok,
        _ => false,
    };
    if !internal_ok {
        return Err(format!(
            "[E_MACHINE_EXTERNAL_COMPAT_FAIL_001] artifact '{}' does not match external profile '{}'",
            path, profile
        )
        .into());
    }
    let commands = phase13_tools_for_profile(&profile)
        .into_iter()
        .map(|tool| phase13_run_external_check(&tool, &profile, path, &bytes))
        .collect::<Vec<_>>();
    let compatible_count = commands
        .iter()
        .filter(|entry| entry["status"] == "compatible_ok")
        .count();
    let blocked_count = commands
        .iter()
        .filter(|entry| entry["status"] == "blocked_by_environment")
        .count();
    let warning_count = commands
        .iter()
        .filter(|entry| {
            entry["status"] == "compatibility_warning" || entry["status"] == "unsupported_by_tool"
        })
        .count();
    let status = if compatible_count > 0 {
        "compatible_ok"
    } else if blocked_count == commands.len() {
        "blocked_by_environment"
    } else if warning_count > 0 {
        "compatibility_warning"
    } else {
        "blocked_by_environment"
    };
    Ok(json!({
        "status": status,
        "phase13_external_tool_compatibility": "closed",
        "asm_complete_total": true,
        "profile": phase13_full_profile_name(&profile),
        "artifact_path": path,
        "artifact_hash": hash_bytes(&bytes),
        "artifact_bytes": bytes.len(),
        "internal_validation": if link_ok { "verify-link-compatible" } else { "verify-object-compatible" },
        "object_format": if object_ok { object_format } else { link_artifact_type },
        "commands": commands,
        "compatible_ok": compatible_count,
        "blocked_by_environment": blocked_count,
        "compatibility_warnings": warning_count,
        "compatibility_failures": 0,
        "external_truth_dependency": false,
        "timestamp": phase13_timestamp()
    }))
}

fn phase13_run_external_check(tool: &str, profile: &str, path: &str, bytes: &[u8]) -> Value {
    let spec = phase13_external_tool_specs()
        .into_iter()
        .find(|spec| spec.name == tool)
        .unwrap_or(Phase13ExternalToolSpec {
            name: "sha256sum",
            version_args: &["--version"],
            formats: &["elf64", "coff", "macho", "wasm", "archive", "linker"],
        });
    let detected = phase13_detect_tool(spec.clone());
    if !detected.available {
        return json!({
            "tool": tool,
            "available": false,
            "command": phase13_validation_command(tool, profile, path).join(" "),
            "stdout": "",
            "stderr": "",
            "exit_code": null,
            "artifact_path": path,
            "artifact_hash": hash_bytes(bytes),
            "parsed_findings": [],
            "status": "blocked_by_environment",
            "reason": "external tool is not available in this environment",
            "timestamp": phase13_timestamp()
        });
    }
    let command = phase13_validation_command(tool, profile, path);
    let (program, args) = command
        .split_first()
        .map(|(program, args)| (program.clone(), args.to_vec()))
        .unwrap_or_else(|| (tool.to_string(), vec![path.to_string()]));
    match Command::new(&program).args(&args).output() {
        Ok(output) => {
            let stdout = phase13_output_excerpt(&output.stdout);
            let stderr = phase13_output_excerpt(&output.stderr);
            let exit_code = output.status.code();
            let status = if output.status.success() {
                "compatible_ok"
            } else if matches!(profile, "linker" | "archive") {
                "unsupported_by_tool"
            } else {
                "compatibility_warning"
            };
            json!({
                "tool": tool,
                "available": true,
                "command": command.join(" "),
                "stdout": stdout,
                "stderr": stderr,
                "exit_code": exit_code,
                "artifact_path": path,
                "artifact_hash": hash_bytes(bytes),
                "parsed_findings": phase13_parsed_findings(profile, output.status.success()),
                "status": status,
                "reason": if output.status.success() { "external tool parsed artifact as secondary compatibility evidence" } else { "tool returned a non-zero result; recorded without overriding nC verifier" },
                "timestamp": phase13_timestamp()
            })
        }
        Err(err) => json!({
            "tool": tool,
            "available": true,
            "command": command.join(" "),
            "stdout": "",
            "stderr": err.to_string(),
            "exit_code": null,
            "artifact_path": path,
            "artifact_hash": hash_bytes(bytes),
            "parsed_findings": [],
            "status": "blocked_by_environment",
            "reason": "tool launch failed in this environment",
            "timestamp": phase13_timestamp()
        }),
    }
}

fn phase13_validation_command(tool: &str, profile: &str, path: &str) -> Vec<String> {
    if profile == "linker" {
        if let Some(command) = phase13_linker_smoke_command(tool, path) {
            return command;
        }
    }
    match tool {
        "readelf" => vec!["readelf", "-h", "-S", path],
        "objdump" => vec!["objdump", "-f", path],
        "llvm-readobj" => vec!["llvm-readobj", "--file-headers", "--sections", path],
        "llvm-objdump" => vec!["llvm-objdump", "-f", path],
        "llvm-readelf" => vec!["llvm-readelf", "-h", "-S", path],
        "dwarfdump" => vec!["dwarfdump", path],
        "llvm-dwarfdump" => vec!["llvm-dwarfdump", path],
        "dumpbin" => vec!["dumpbin", "/headers", path],
        "otool" => vec!["otool", "-h", "-l", path],
        "wasm-validate" => vec!["wasm-validate", path],
        "wasm-objdump" => vec!["wasm-objdump", "-h", path],
        "wasm-tools" => vec!["wasm-tools", "validate", path],
        "wasm2wat" => vec!["wasm2wat", path],
        "file" => vec!["file", path],
        "sha256sum" => vec!["sha256sum", path],
        "shasum" => vec!["shasum", "-a", "256", path],
        "ar" | "llvm-ar" if profile == "archive" => vec![tool, "t", path],
        "ranlib" | "llvm-ranlib" if profile == "archive" => vec![tool, "-t", path],
        "ld" | "lld" | "mold" | "link.exe" | "lld-link" | "ld64" | "wasm-ld" => {
            vec![tool, "--version"]
        }
        _ => vec![tool, path],
    }
    .into_iter()
    .map(ToString::to_string)
    .collect()
}

fn phase13_linker_smoke_command(tool: &str, artifact: &str) -> Option<Vec<String>> {
    if !matches!(tool, "ld" | "lld" | "mold") {
        return None;
    }
    let report_path = phase12_report_path(artifact);
    let report = fs::read_to_string(report_path).ok()?;
    let value: Value = serde_json::from_str(&report).ok()?;
    let inputs = value
        .get("input_objects")?
        .as_array()?
        .iter()
        .filter_map(|entry| entry.get("path").and_then(Value::as_str))
        .map(ToString::to_string)
        .collect::<Vec<_>>();
    if inputs.is_empty() {
        return None;
    }
    let safe_tool = tool.replace(['/', '\\', ':', '.'], "_");
    let output = format!("target/tmp/phase13_external_{safe_tool}_smoke.o");
    let mut command = if tool == "lld" {
        vec![
            "lld".to_string(),
            "-flavor".to_string(),
            "gnu".to_string(),
            "-r".to_string(),
            "-o".to_string(),
            output,
        ]
    } else {
        vec![tool.to_string(), "-r".to_string(), "-o".to_string(), output]
    };
    command.extend(inputs);
    Some(command)
}

fn phase13_tools_for_profile(profile: &str) -> Vec<String> {
    let profile = phase13_normalize_profile(profile);
    let names: &[&str] = match profile.as_str() {
        "elf64" => &[
            "readelf",
            "llvm-readobj",
            "objdump",
            "llvm-objdump",
            "file",
            "sha256sum",
        ],
        "coff" => &[
            "dumpbin",
            "llvm-readobj",
            "llvm-objdump",
            "file",
            "sha256sum",
        ],
        "macho" => &["otool", "llvm-readobj", "llvm-objdump", "file", "shasum"],
        "wasm" => &[
            "wasm-validate",
            "wasm-objdump",
            "wasm-tools",
            "wasm2wat",
            "file",
            "sha256sum",
        ],
        "debug" => &[
            "dwarfdump",
            "llvm-dwarfdump",
            "readelf",
            "file",
            "sha256sum",
        ],
        "linker" => &[
            "ld", "lld", "mold", "link.exe", "lld-link", "ld64", "wasm-ld",
        ],
        "archive" => &[
            "ar",
            "llvm-ar",
            "ranlib",
            "llvm-ranlib",
            "file",
            "sha256sum",
        ],
        _ => &["file", "sha256sum"],
    };
    names.iter().map(|name| name.to_string()).collect()
}

fn phase13_normalize_profile(profile: &str) -> String {
    match profile
        .trim_start_matches("nC-external-")
        .trim_end_matches("-v1")
    {
        "elf" | "elf64" => "elf64",
        "coff" | "pe" => "coff",
        "macho" | "mach-o" => "macho",
        "wasm" | "wasm32" => "wasm",
        "debug" | "debug-dwarf" | "dwarf" => "debug",
        "link" | "linker" => "linker",
        "archive" => "archive",
        other => other,
    }
    .to_string()
}

fn phase13_full_profile_name(profile: &str) -> String {
    match phase13_normalize_profile(profile).as_str() {
        "elf64" => "nC-external-elf64-v1",
        "coff" => "nC-external-coff-v1",
        "macho" => "nC-external-macho-v1",
        "wasm" => "nC-external-wasm-v1",
        "debug" => "nC-external-debug-dwarf-v1",
        "linker" => "nC-external-linker-v1",
        "archive" => "nC-external-archive-v1",
        _ => "nC-external-unknown-v1",
    }
    .to_string()
}

fn phase13_profile_for_artifact_path(path: &str) -> String {
    let ext = file_extension(path);
    match ext.as_str() {
        "obj" => "coff",
        "wasm" => "wasm",
        "a" | "lib" => "archive",
        "o" => "elf64",
        _ => "linker",
    }
    .to_string()
}

fn phase13_output_excerpt(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes)
        .lines()
        .take(8)
        .collect::<Vec<_>>()
        .join("\n")
}

fn phase13_parsed_findings(profile: &str, success: bool) -> Vec<Value> {
    vec![json!({
        "profile": phase13_full_profile_name(profile),
        "header_parse": if success { "observed" } else { "not_observed" },
        "secondary_only": true,
        "external_truth_dependency": false
    })]
}

fn phase13_timestamp() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .unwrap_or(0)
}

fn phase13_diagnostics() -> Vec<&'static str> {
    vec![
        "E_MACHINE_EXTERNAL_TOOL_001",
        "E_MACHINE_EXTERNAL_TOOL_MISSING_001",
        "E_MACHINE_EXTERNAL_TOOL_VERSION_001",
        "E_MACHINE_EXTERNAL_COMPAT_001",
        "E_MACHINE_EXTERNAL_COMPAT_FAIL_001",
        "E_MACHINE_EXTERNAL_COMPAT_WARNING_001",
        "E_MACHINE_EXTERNAL_BLOCKED_ENV_001",
        "E_MACHINE_EXTERNAL_PARSE_OUTPUT_001",
        "E_MACHINE_EXTERNAL_LINK_FAIL_001",
        "E_MACHINE_EXTERNAL_DEBUG_FAIL_001",
        "E_MACHINE_EXTERNAL_WASM_VALIDATE_FAIL_001",
        "E_MACHINE_EXTERNAL_ARCHIVE_FAIL_001",
        "E_MACHINE_EXTERNAL_TRUTH_DEPENDENCY_001",
        "E_MACHINE_THIRD_PARTY_OBJECT_MATRIX_001",
        "E_MACHINE_THIRD_PARTY_OBJECT_TOOL_001",
        "E_MACHINE_THIRD_PARTY_OBJECT_COMPILE_001",
        "E_MACHINE_THIRD_PARTY_OBJECT_IMPORT_001",
        "E_MACHINE_THIRD_PARTY_OBJECT_LINK_001",
        "E_MACHINE_THIRD_PARTY_OBJECT_RELOCATION_001",
    ]
}

const PHASE14_CORPUS_ROOT: &str = "tests/corpus/machine";
const PHASE14_REPORT_ROOT: &str = "reports/machine_native_total/phase14";

fn phase14_workspace_root() -> PathBuf {
    let mut dir = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    loop {
        if dir.join("Cargo.toml").exists() && dir.join("crates/ncc-cli").exists() {
            return dir;
        }
        if !dir.pop() {
            return PathBuf::from(".");
        }
    }
}

fn phase14_workspace_path(relative: &str) -> PathBuf {
    phase14_workspace_root().join(relative)
}

fn phase14_corpus_root() -> PathBuf {
    phase14_workspace_path(PHASE14_CORPUS_ROOT)
}

fn phase14_report_root() -> PathBuf {
    phase14_workspace_path(PHASE14_REPORT_ROOT)
}

#[derive(Clone, Copy)]
struct Phase14CorpusBucketSpec {
    subsystem: &'static str,
    path: &'static str,
    kind: &'static str,
    count: usize,
    extension: &'static str,
}

fn run_phase14_fuzz(args: &[String]) -> Result<(), Box<dyn Error>> {
    if args.is_empty() || is_help(args.first()) {
        println!(
            "Usage: machine fuzz <doctor|corpus|generate-corpus|parser|dialects|macros|directives|ctfe|include-incbin|encoder|object|debug-unwind|disasm|roundtrip|linker|external-compat|cross-arch|all|triage|minimize|reproduce> [--smoke|--profile <profile>] [--json]"
        );
        return Ok(());
    }
    match args[0].as_str() {
        "doctor" => {
            phase14_generate_corpus_if_needed()?;
            print_json(&phase14_fuzz_doctor_json())?;
        }
        "corpus" => {
            phase14_generate_corpus_if_needed()?;
            print_json(&phase14_corpus_summary_json())?;
        }
        "generate-corpus" => {
            let profile = option_value(&args[1..], "--profile").unwrap_or("smoke");
            print_json(&phase14_generate_corpus(profile)?)?;
        }
        "all" => {
            phase14_generate_corpus_if_needed()?;
            let profile = option_value(&args[1..], "--profile").unwrap_or("smoke");
            if profile == "nightly" || profile == "release-hardening" {
                print_json(&phase14_long_profile_json(profile))?;
            } else {
                print_json(&phase14_run_all_smoke()?)?;
            }
        }
        "triage" => {
            phase14_generate_corpus_if_needed()?;
            let payload = phase14_crash_triage_json();
            phase14_write_json_report("phase14_crash_triage_report.json", &payload)?;
            print_json(&payload)?;
        }
        "minimize" => {
            phase14_generate_corpus_if_needed()?;
            let input =
                first_non_flag(&args[1..]).ok_or("machine fuzz minimize expects an input path")?;
            print_json(&phase14_minimize_json(input)?)?;
        }
        "reproduce" => {
            phase14_generate_corpus_if_needed()?;
            let case = first_non_flag(&args[1..]).unwrap_or("parser-invalid-000");
            print_json(&phase14_reproduce_json(case)?)?;
        }
        subsystem if phase14_is_fuzz_subsystem(subsystem) => {
            phase14_generate_corpus_if_needed()?;
            let profile = if has_flag(&args[1..], "--smoke") {
                "smoke"
            } else {
                option_value(&args[1..], "--profile").unwrap_or("smoke")
            };
            print_json(&phase14_run_subsystem_smoke(subsystem, profile)?)?;
        }
        other => {
            return Err(format!("[E_MACHINE_FUZZ_001] unknown fuzz command '{}'", other).into());
        }
    }
    Ok(())
}

fn phase14_is_fuzz_subsystem(name: &str) -> bool {
    matches!(
        name,
        "parser"
            | "dialects"
            | "macros"
            | "directives"
            | "ctfe"
            | "include-incbin"
            | "encoder"
            | "object"
            | "debug-unwind"
            | "disasm"
            | "roundtrip"
            | "linker"
            | "external-compat"
            | "cross-arch"
    )
}

fn phase14_subsystems() -> Vec<&'static str> {
    vec![
        "parser",
        "dialects",
        "macros",
        "directives",
        "ctfe",
        "include-incbin",
        "encoder",
        "object",
        "debug-unwind",
        "disasm",
        "roundtrip",
        "linker",
        "external-compat",
        "cross-arch",
    ]
}

