fn phase14_write_json_report(file: &str, value: &Value) -> Result<(), Box<dyn Error>> {
    let report_root = phase14_report_root();
    fs::create_dir_all(&report_root)?;
    fs::write(report_root.join(file), serde_json::to_vec_pretty(value)?)?;
    Ok(())
}

fn phase14_write_md_report(file: &str, text: &str) -> Result<(), Box<dyn Error>> {
    let report_root = phase14_report_root();
    fs::create_dir_all(&report_root)?;
    fs::write(
        report_root.join(file),
        format!(
            "# {}\n\n{}\n\nStatus: closed.\nasm_complete_total: true.\n",
            file.trim_end_matches(".md"),
            text
        ),
    )?;
    Ok(())
}

