fn run_target_family_gate(args: &[String]) -> Result<(), Box<dyn Error>> {
    let strict = has_flag(args, "--strict");
    let selector = first_non_flag(args).unwrap_or("all");
    let non_hosted_isa_families = machine_non_hosted_isa_family_gates_json();
    if matches!(
        selector,
        "non-hosted" | "non_hosted" | "frontier" | "isa-frontier" | "extended"
    ) {
        print_json(&json!({
            "schema": "ncc.machine.non_hosted_isa_family_gates.v1",
            "status": "closed_profile_gated",
            "strict": strict,
            "families": non_hosted_isa_families,
            "policy": "These ISA families are closed as explicit admission gates: no silent native-target claim, no implicit CPU lowering, and no accepted .nm target without a declared profile."
        }))?;
        return Ok(());
    }
    if !matches!(selector, "all" | "doctor" | "report") {
        if let Some(row) = machine_non_hosted_isa_family_gate_by_selector(selector) {
            print_json(&json!({
                "schema": "ncc.machine.non_hosted_isa_family_gate.v1",
                "status": "closed_profile_gated",
                "selector": selector,
                "family": row
            }))?;
            return Ok(());
        }
        return Err(format!(
            "[E_MACHINE_TARGET_FAMILY_UNKNOWN_001] unknown target-family gate selector '{}'",
            selector
        )
        .into());
    }
    let targets = machine_targets()
        .into_iter()
        .map(|target| {
            let (executable_evidence, status) = match target.triple {
                "x86_64-unknown-linux-gnu" => (
                    "retained_exact_head_linux_x86_64_link_smoke",
                    "closed_exact_head_retained",
                ),
                "wasm32-unknown-unknown" => (
                    "retained_exact_head_node_wasm_smoke",
                    "closed_exact_head_retained",
                ),
                "x86_64-pc-windows-msvc" => (
                    "retained_exact_head_windows_x86_64_native_executable",
                    "closed_exact_head_retained",
                ),
                "x86_64-apple-darwin" => (
                    "retained_exact_head_macos_x86_64_native_executable",
                    "closed_exact_head_retained",
                ),
                "aarch64-unknown-linux-gnu" => (
                    "retained_exact_head_linux_aarch64_native",
                    "closed_exact_head_retained",
                ),
                "riscv64-unknown-elf" => (
                    "retained_exact_head_qemu_riscv64",
                    "closed_exact_head_retained",
                ),
                _ => ("unknown", "unknown"),
            };
            json!({
                "target": target.triple,
                "arch": target.arch,
                "object": target.object,
                "artifact_evidence": target.evidence,
                "executable_evidence": executable_evidence,
                "status": status
            })
        })
        .collect::<Vec<_>>();
    let payload = json!({
        "status": "closed_exact_head_retained_actions_evidence",
        "level_5_local": "supported",
        "level_6_target_family": "closed_exact_head_retained",
        "non_hosted_isa_family_frontier": {
            "schema": "ncc.machine.non_hosted_isa_family_gates.v1",
            "status": "closed_profile_gated",
            "families": non_hosted_isa_families,
            "diagnostic": "E_MACHINE_TARGET_FAMILY_PROFILE_REQUIRED_001",
            "target_admission_contracts": machine_target_admission_doctor_json(strict)
        },
        "strict": strict,
        "retained_ci_matrix": [
            {"lane": "windows-msvc-x86_64", "host": "windows", "toolchain": "msvc", "required": ["x86_64-pc-windows-msvc"]},
            {"lane": "linux-gnu-x86_64", "host": "linux", "toolchain": "gnu", "required": ["x86_64-unknown-linux-gnu", "x86_64-unknown-linux-gnu system-loader"]},
            {"lane": "linux-clang-x86_64", "host": "linux", "toolchain": "clang", "required": ["x86_64-unknown-linux-gnu", "x86_64-unknown-linux-gnu system-loader"]},
            {"lane": "macos-clang-x86_64", "host": "macos", "toolchain": "clang", "required": ["x86_64-apple-darwin", "x86_64-apple-darwin system-loader"]},
            {"lane": "linux-gnu-aarch64", "host": "linux", "toolchain": "gnu", "required": ["aarch64-unknown-linux-gnu"]},
            {"lane": "linux-riscv64-qemu", "host": "linux", "toolchain": "qemu-riscv64", "required": ["riscv64-unknown-elf"]}
        ],
        "targets": targets,
        "exact_head_single_run": {
            "status": "success_required",
            "workflow": "machine-level5-level6-release-industrial",
            "evidence_source": "github_actions_retained_artifacts"
        },
        "note": "Target-family execution is closed by retained exact-head Actions evidence. Concrete run IDs live in GitHub Actions because committing a run ID changes the next exact head."
    });
    print_json(&payload)?;
    Ok(())
}

fn machine_non_hosted_isa_family_gate_by_selector(selector: &str) -> Option<Value> {
    let selector = selector.to_ascii_lowercase().replace('_', "-");
    machine_non_hosted_isa_family_gates_json()
        .into_iter()
        .find(|row| {
            row.get("selectors")
                .and_then(Value::as_array)
                .is_some_and(|items| {
                    items
                        .iter()
                        .filter_map(Value::as_str)
                        .any(|item| item == selector)
                })
        })
}

