const MACHINE_TARGET_ADMISSION_REQUIRED_AXES: &[&str] = &[
    "registers",
    "isa",
    "instruction_encoding",
    "abi",
    "data_layout",
    "output_format",
    "relocations",
    "linker_loader",
    "execution_evidence",
    "corpus",
];

fn machine_target_admission_required_axes_json() -> Vec<&'static str> {
    MACHINE_TARGET_ADMISSION_REQUIRED_AXES.to_vec()
}

fn run_target_admission(args: &[String]) -> Result<(), Box<dyn Error>> {
    let json_output = has_flag(args, "--json");
    let strict = has_flag(args, "--strict");
    let non_flags = args
        .iter()
        .filter(|arg| !arg.starts_with('-'))
        .map(String::as_str)
        .collect::<Vec<_>>();
    let selector = non_flags.first().copied().unwrap_or("doctor");

    match selector {
        "doctor" | "all" | "report" => {
            let payload = machine_target_admission_doctor_json(strict);
            if json_output {
                print_json(&payload)?;
            } else {
                println!("machine target-admission: {}", payload["status"]);
                println!("profiles: {}", payload["profile_count"]);
                println!(
                    "native_admitted: {}",
                    payload["native_admitted_profile_count"]
                );
                println!("diagnostic: E_MACHINE_TARGET_PROFILE_EVIDENCE_REQUIRED_001");
            }
            Ok(())
        }
        "list" | "profiles" => {
            let payload = json!({
                "schema": "ncc.machine.target_admission.profiles.v1",
                "status": "profile_contracts_declared",
                "required_axes": machine_target_admission_required_axes_json(),
                "profiles": machine_target_admission_profiles_json()
            });
            if json_output {
                print_json(&payload)?;
            } else {
                for profile in machine_target_admission_profiles_json() {
                    println!(
                        "{} family={} status={}",
                        profile["profile_id"].as_str().unwrap_or("unknown"),
                        profile["family"].as_str().unwrap_or("unknown"),
                        profile["admission"]["status"].as_str().unwrap_or("unknown")
                    );
                }
            }
            Ok(())
        }
        "families" | "frontier" | "non-hosted" | "non_hosted" => {
            let payload = json!({
                "schema": "ncc.machine.target_admission.families.v1",
                "status": "closed_profile_gated",
                "families": machine_target_admission_family_summary_json(),
                "required_axes": machine_target_admission_required_axes_json()
            });
            if json_output {
                print_json(&payload)?;
            } else {
                println!("gpu dsp 32bit_cpu firmware legacy_microcontroller");
            }
            Ok(())
        }
        "admit" => {
            let profile_selector = non_flags
                .get(1)
                .copied()
                .ok_or("machine target-admission admit expects a profile id or target triple")?;
            let Some(profile) = machine_target_admission_profile_by_selector(profile_selector)
            else {
                return Err(format!(
                    "[E_MACHINE_TARGET_PROFILE_UNKNOWN_001] unknown target-admission profile '{}'",
                    profile_selector
                )
                .into());
            };
            if profile
                .pointer("/admission/native_machine_target")
                .and_then(Value::as_bool)
                .unwrap_or(false)
            {
                let payload = json!({
                    "schema": "ncc.machine.target_admission.admit.v1",
                    "status": "native_profile_admitted",
                    "profile": profile,
                    "required_axes": machine_target_admission_required_axes_json(),
                    "missing_admission_evidence": [],
                    "diagnostic": Value::Null,
                    "policy": "Profile has retained encoder, ELF32 object and QEMU/native smoke contract evidence in the ncc machine target table."
                });
                if json_output {
                    print_json(&payload)?;
                }
                return Ok(());
            }
            let payload = json!({
                "schema": "ncc.machine.target_admission.admit.v1",
                "status": "blocked_profile_evidence_required",
                "profile": profile,
                "required_axes": machine_target_admission_required_axes_json(),
                "missing_admission_evidence": machine_target_admission_required_axes_json(),
                "diagnostic": "E_MACHINE_TARGET_PROFILE_EVIDENCE_REQUIRED_001",
                "policy": "A non-hosted target cannot become a native machine target until every material axis has retained bytes, relocation/link evidence and emulator or hardware smoke evidence."
            });
            if json_output {
                print_json(&payload)?;
            }
            Err("[E_MACHINE_TARGET_PROFILE_EVIDENCE_REQUIRED_001] target profile contract exists, but native admission evidence is missing".into())
        }
        other => {
            if let Some(profile) = machine_target_admission_profile_by_selector(other) {
                let payload = json!({
                    "schema": "ncc.machine.target_admission.profile.v1",
                    "status": "profile_contract_declared",
                    "profile": profile,
                    "required_axes": machine_target_admission_required_axes_json()
                });
                if json_output {
                    print_json(&payload)?;
                } else {
                    println!(
                        "{} family={} native=false",
                        payload["profile"]["profile_id"].as_str().unwrap_or(other),
                        payload["profile"]["family"].as_str().unwrap_or("unknown")
                    );
                }
                Ok(())
            } else {
                Err(format!(
                    "[E_MACHINE_TARGET_PROFILE_UNKNOWN_001] unknown target-admission selector '{}'",
                    other
                )
                .into())
            }
        }
    }
}

fn machine_target_admission_doctor_json(strict: bool) -> Value {
    let profiles = machine_target_admission_profiles_json();
    let validation = machine_target_admission_validation_json(&profiles);
    let native_admitted = profiles
        .iter()
        .filter(|profile| {
            profile
                .pointer("/admission/native_machine_target")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        })
        .count();
    json!({
        "schema": "ncc.machine.target_admission.doctor.v1",
        "status": "closed_admission_contracts",
        "strict": strict,
        "families": machine_target_admission_family_summary_json(),
        "required_axes": machine_target_admission_required_axes_json(),
        "profile_count": profiles.len(),
        "native_admitted_profile_count": native_admitted,
        "all_required_axes_present": validation["missing"].as_array().is_some_and(Vec::is_empty),
        "validation": validation,
        "profiles": profiles,
        "admission_policy": {
            "accepted_without_profile": false,
            "native_target_until_evidence": false,
            "required_diagnostic": "E_MACHINE_TARGET_PROFILE_EVIDENCE_REQUIRED_001",
            "source_of_truth": "docs/spec/machine/machine_target_admission_profiles.md"
        }
    })
}

fn machine_target_admission_family_summary_json() -> Vec<Value> {
    let profiles = machine_target_admission_profiles_json();
    [
        "gpu",
        "dsp",
        "32bit_cpu",
        "firmware",
        "legacy_microcontroller",
    ]
    .iter()
    .map(|family| {
        let family_profiles = profiles
            .iter()
            .filter(|profile| profile["family"] == **family)
            .collect::<Vec<_>>();
        let profile_ids = family_profiles
            .iter()
            .filter_map(|profile| profile["profile_id"].as_str())
            .collect::<Vec<_>>();
        let native_admitted = family_profiles.iter().any(|profile| {
            profile
                .pointer("/admission/native_machine_target")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        });
        json!({
            "family": family,
            "status": if native_admitted { "profile_contracts_declared_partial_native_admitted" } else { "profile_contracts_declared_native_blocked" },
            "native_machine_target": native_admitted,
            "candidate_profile_ids": profile_ids,
            "required_axes": machine_target_admission_required_axes_json(),
            "diagnostic": "E_MACHINE_TARGET_PROFILE_EVIDENCE_REQUIRED_001"
        })
    })
    .collect()
}

fn machine_target_admission_validation_json(profiles: &[Value]) -> Value {
    let mut missing = Vec::new();
    for profile in profiles {
        let profile_id = profile["profile_id"].as_str().unwrap_or("unknown");
        let axes = profile["material_axes"].as_object();
        for axis in MACHINE_TARGET_ADMISSION_REQUIRED_AXES {
            if axes.is_none_or(|items| !items.contains_key(*axis)) {
                missing.push(json!({
                    "profile_id": profile_id,
                    "axis": axis,
                    "diagnostic": "E_MACHINE_TARGET_ADMISSION_AXIS_MISSING_001"
                }));
            }
        }
    }
    json!({
        "status": if missing.is_empty() { "ok" } else { "failed" },
        "missing": missing
    })
}

fn machine_target_admission_profile_by_selector(selector: &str) -> Option<Value> {
    let needle = selector.to_ascii_lowercase().replace('_', "-");
    machine_target_admission_profiles_json()
        .into_iter()
        .find(|profile| {
            let profile_id = profile["profile_id"]
                .as_str()
                .unwrap_or("")
                .to_ascii_lowercase()
                .replace('_', "-");
            let target_triple = profile["target_triple"]
                .as_str()
                .unwrap_or("")
                .to_ascii_lowercase()
                .replace('_', "-");
            profile_id == needle
                || target_triple == needle
                || profile
                    .get("selectors")
                    .and_then(Value::as_array)
                    .is_some_and(|items| {
                        items
                            .iter()
                            .filter_map(Value::as_str)
                            .any(|item| item == needle)
                    })
        })
}

