#[derive(Clone)]
enum MachineDisasmFormat {
    Elf32,
    Elf64,
    Coff,
    MachO,
    Wasm,
    Unknown,
}

impl MachineDisasmFormat {
    fn as_str(&self) -> &'static str {
        match self {
            MachineDisasmFormat::Elf32 => "elf32",
            MachineDisasmFormat::Elf64 => "elf64",
            MachineDisasmFormat::Coff => "coff",
            MachineDisasmFormat::MachO => "macho",
            MachineDisasmFormat::Wasm => "wasm",
            MachineDisasmFormat::Unknown => "unknown",
        }
    }
}

