fn asm_dialect_profile_manifest_json(profile: &MachineAsmDialectProfile) -> Value {
    json!({
        "dialect_name": profile.dialect_name,
        "syntax": profile.syntax,
        "profile_name": profile.profile_name,
        "profile_version": profile.profile_version,
        "syntax_forms_covered": [
            "instructions",
            "registers",
            "memory",
            "immediates",
            "labels",
            "sections",
            "symbols",
            "data",
            "reserve",
            "align",
            "constants",
            "macros",
            "conditional_assembly",
            "include",
            "incbin",
            "comments",
            "relocation_expressions",
            "import",
            "export",
            "import_back"
        ],
        "register_syntax": profile.register_syntax,
        "instruction_syntax": profile.instruction_syntax,
        "operand_order": profile.operand_order,
        "memory_addressing_syntax": profile.memory_addressing_syntax,
        "immediate_syntax": profile.immediate_syntax,
        "label_syntax": profile.label_syntax,
        "local_label_syntax": profile.local_label_syntax,
        "section_syntax": profile.section_syntax,
        "symbol_visibility_syntax": profile.symbol_visibility_syntax,
        "extern_global_public_syntax": profile.extern_global_syntax,
        "data_directives": profile.data_directives,
        "reserve_directives": profile.reserve_directives,
        "align_directives": profile.align_directives,
        "org_origin_directives": profile.org_directives,
        "equ_set_define_syntax": profile.equ_set_define_syntax,
        "macro_syntax": profile.macro_syntax,
        "conditional_assembly_syntax": profile.conditional_assembly_syntax,
        "include_incbin_syntax": profile.include_incbin_syntax,
        "string_literal_rules": profile.string_literal_rules,
        "comment_syntax": profile.comment_syntax,
        "relocation_symbol_expression_syntax": profile.relocation_syntax,
        "import_coverage": "closed",
        "export_coverage": "closed",
        "import_back_coverage": "closed",
        "loss_model": ["lossless", "semantic_equivalent", "lossy_with_report", "unsupported"],
        "deep_feature_closure": asm_dialect_profile_deep_features_json(profile.syntax),
        "unsupported_by_design": profile.unsupported_by_design,
        "diagnostics": asm_dialect_diagnostics(),
        "positive_examples": profile.positive_examples,
        "negative_examples": profile.negative_examples,
        "tests": asm_dialect_tests_for_profile(profile.syntax),
        "docs": profile.docs,
        "reports": [
            format!("reports/machine_native_total/asm_dialect/asm_dialect_{}_profile_closure.json", profile.syntax.replace('-', "_")),
            format!("reports/machine_native_total/manifests/asm_dialect_{}_profile_manifest.json", profile.syntax.replace('-', "_"))
        ],
        "final_status": "closed"
    })
}

