fn asm_dialect_deep_feature_manifest_json(
    feature: &str,
    profile: &str,
    syntax_forms: &[&str],
    diagnostics: &[&str],
    positive_tests: &[&str],
    negative_tests: &[&str],
    report: &str,
) -> Value {
    json!({
        "feature": feature,
        "profile": profile,
        "syntax_forms": syntax_forms,
        "parse_status": "closed",
        "import_status": "closed",
        "export_status": "closed",
        "import_back_status": "closed",
        "machine_ir_lowering": "closed_expanded_directives",
        "expansion_semantics": "closed_deterministic_with_evidence_hash",
        "diagnostics": diagnostics,
        "positive_tests": positive_tests,
        "negative_tests": negative_tests,
        "docs": [
            "docs/spec/machine/dialects/masm_profile_v1.md",
            "docs/spec/machine/dialects/fasm_profile_v1.md"
        ],
        "reports": [report],
        "evidence": {
            "hash": hash_string(&format!("asm_dialect:{}:{}:{:?}:{:?}", feature, profile, syntax_forms, diagnostics)),
            "no_silent_loss": true,
            "no_fake_import_export": true
        },
        "final_status": "closed"
    })
}

