fn asm_dialect_tests_for_profile(syntax: &str) -> Vec<String> {
    let prefix = syntax.replace('-', "_");
    let mut tests = [
        "profile_closed",
        "import_export_lossless",
        "data_directives_ok",
        "sections_symbols_ok",
        "relocations_ok",
        "memory_addressing_ok",
        "comments_ok",
        "unsupported_directive_fail",
        "invalid_operand_fail",
        "imported_nm_machine_check_ok",
        "exported_file_reimport_ok",
        "no_silent_loss",
        "no_fake_import_export",
    ]
    .iter()
    .map(|name| format!("machine_asm_dialect_{prefix}_{name}"))
    .collect::<Vec<_>>();
    if syntax == "masm" {
        tests.extend(
            [
                "machine_asm_dialect_masm_dup_literal_ok",
                "machine_asm_dialect_masm_dup_equ_count_ok",
                "machine_asm_dialect_masm_dup_ctfe_count_ok",
                "machine_asm_dialect_masm_dup_nested_ok",
                "machine_asm_dialect_masm_dup_value_list_ok",
                "machine_asm_dialect_masm_dup_string_ok",
                "machine_asm_dialect_masm_dup_db_dw_dd_dq_ok",
                "machine_asm_dialect_masm_dup_uninitialized_ok",
                "machine_asm_dialect_masm_dup_import_export_back_ok",
            ]
            .iter()
            .map(|test| test.to_string()),
        );
    }
    if syntax == "fasm" {
        tests.extend(
            [
                "machine_asm_dialect_fasm_repeat_literal_ok",
                "machine_asm_dialect_fasm_repeat_equ_count_ok",
                "machine_asm_dialect_fasm_repeat_ctfe_count_ok",
                "machine_asm_dialect_fasm_repeat_counter_ok",
                "machine_asm_dialect_fasm_repeat_nested_ok",
                "machine_asm_dialect_fasm_repeat_labels_ok",
                "machine_asm_dialect_fasm_repeat_inside_macro_ok",
                "machine_asm_dialect_fasm_repeat_import_export_back_ok",
                "machine_asm_dialect_fasm_macro_no_params_ok",
                "machine_asm_dialect_fasm_macro_params_ok",
                "machine_asm_dialect_fasm_macro_variadic_ok",
                "machine_asm_dialect_fasm_macro_local_labels_ok",
                "machine_asm_dialect_fasm_macro_calls_macro_ok",
                "machine_asm_dialect_fasm_macro_repeat_inside_ok",
                "machine_asm_dialect_fasm_macro_data_directives_ok",
                "machine_asm_dialect_fasm_macro_memory_operands_ok",
                "machine_asm_dialect_fasm_macro_import_export_back_ok",
            ]
            .iter()
            .map(|test| test.to_string()),
        );
    }
    tests
}

fn export_asm_to_string(audit: &MachineAudit, profile: &MachineAsmDialectProfile) -> String {
    let mut out = String::new();
    match profile.syntax {
        "nasm" | "yasm" => out.push_str("bits 64\nsection .text\n"),
        "gas-intel" => out.push_str(".intel_syntax noprefix\n.text\n"),
        "gas-att" => out.push_str(".text\n"),
        "masm" => out.push_str(".CODE\n"),
        "fasm" => out.push_str("format ELF64\nsection '.text' executable\n"),
        "llvm-mc" => out.push_str(".text\n"),
        _ => {}
    }
    for symbol in &audit.externs {
        out.push_str(&asm_dialect_extern_line(profile, symbol));
    }
    if let Some(entry) = &audit.entry {
        out.push_str(&asm_dialect_global_line(profile, entry));
        match profile.syntax {
            "masm" => out.push_str(&format!("{entry} PROC\n")),
            _ => out.push_str(&format!("{entry}:\n")),
        }
    }
    for inst in &audit.instructions {
        if inst.mnemonic == "label" {
            if let Some(label) = inst.operands.first() {
                out.push_str(&format!("{label}:\n"));
            }
        } else {
            out.push_str("    ");
            out.push_str(&asm_dialect_format_instruction(profile, inst));
            out.push('\n');
        }
    }
    if let Some(entry) = &audit.entry {
        if profile.syntax == "masm" {
            out.push_str(&format!("{entry} ENDP\nEND\n"));
        }
    }
    if !audit.directives.is_empty() || !audit.data_bytes.is_empty() || audit.bss_size > 0 {
        out.push_str(&asm_dialect_data_preamble(profile));
        for directive in &audit.directives {
            if matches!(
                directive.kind.as_str(),
                "db" | "dw" | "dd" | "dq" | "ascii" | "asciz"
            ) {
                out.push_str(&asm_dialect_format_data_directive(profile, directive));
            }
            if matches!(directive.kind.as_str(), "resb" | "resw" | "resd" | "resq") {
                out.push_str(&asm_dialect_format_reserve_directive(profile, directive));
            }
        }
    }
    out
}

fn asm_dialect_extern_line(profile: &MachineAsmDialectProfile, symbol: &str) -> String {
    match profile.syntax {
        "gas-intel" | "gas-att" | "llvm-mc" => format!(".extern {symbol}\n"),
        "masm" => format!("EXTERN {symbol}:PROC\n"),
        "fasm" => format!("extrn {symbol}\n"),
        _ => format!("extern {symbol}\n"),
    }
}

fn asm_dialect_global_line(profile: &MachineAsmDialectProfile, symbol: &str) -> String {
    match profile.syntax {
        "gas-intel" | "gas-att" | "llvm-mc" => format!(".globl {symbol}\n"),
        "masm" => format!("PUBLIC {symbol}\n"),
        "fasm" => format!("public {symbol}\n"),
        _ => format!("global {symbol}\n"),
    }
}

fn asm_dialect_data_preamble(profile: &MachineAsmDialectProfile) -> String {
    match profile.syntax {
        "gas-intel" | "gas-att" | "llvm-mc" => ".data\n".to_string(),
        "masm" => ".DATA\n".to_string(),
        "fasm" => "section '.data' writeable\n".to_string(),
        _ => "section .data\n".to_string(),
    }
}

fn asm_dialect_format_instruction(
    profile: &MachineAsmDialectProfile,
    inst: &MachineInstruction,
) -> String {
    let mnemonic = inst.mnemonic.as_str();
    if profile.syntax == "gas-att" {
        if inst.operands.is_empty() {
            return if mnemonic == "ret" {
                "retq".to_string()
            } else {
                mnemonic.to_string()
            };
        }
        let suffix = asm_dialect_att_suffix(mnemonic, &inst.operands);
        let operands = inst
            .operands
            .iter()
            .rev()
            .map(|operand| asm_dialect_format_att_operand(operand))
            .collect::<Vec<_>>()
            .join(", ");
        return format!("{mnemonic}{suffix} {operands}");
    }
    let operands = inst
        .operands
        .iter()
        .map(|operand| {
            if profile.syntax == "masm" && operand.starts_with('[') {
                format!("QWORD PTR {operand}")
            } else {
                operand.clone()
            }
        })
        .collect::<Vec<_>>();
    let text = if operands.is_empty() {
        mnemonic.to_string()
    } else {
        format!("{mnemonic} {}", operands.join(", "))
    };
    if profile.syntax == "masm" {
        text.to_ascii_uppercase()
    } else {
        text
    }
}

fn asm_dialect_att_suffix(mnemonic: &str, operands: &[String]) -> &'static str {
    if mnemonic == "ret" || mnemonic == "nop" {
        return "";
    }
    if operands.iter().any(|operand| {
        matches!(
            operand.as_str(),
            "rax" | "rbx" | "rcx" | "rdx" | "rsi" | "rdi" | "rbp" | "rsp"
        ) || operand.starts_with('r')
    }) {
        "q"
    } else {
        ""
    }
}

fn asm_dialect_format_att_operand(operand: &str) -> String {
    let operand = operand.trim();
    if operand.starts_with('[') && operand.ends_with(']') {
        return asm_dialect_intel_mem_to_att(operand);
    }
    if asm_dialect_is_register(operand) {
        return format!("%{operand}");
    }
    if operand.starts_with("0x") || operand.chars().all(|ch| ch.is_ascii_digit() || ch == '-') {
        return format!("${operand}");
    }
    operand.to_string()
}

fn asm_dialect_format_data_directive(
    profile: &MachineAsmDialectProfile,
    directive: &MachineDirectiveRecord,
) -> String {
    let kind = match profile.syntax {
        "gas-intel" | "gas-att" | "llvm-mc" => match directive.kind.as_str() {
            "db" => ".byte",
            "dw" => ".word",
            "dd" => ".long",
            "dq" => ".quad",
            other => other,
        },
        "masm" => match directive.kind.as_str() {
            "db" => "DB",
            "dw" => "DW",
            "dd" => "DD",
            "dq" => "DQ",
            other => other,
        },
        _ => directive.kind.as_str(),
    };
    let name = if directive.name.is_empty() {
        "asm_dialect_data"
    } else {
        &directive.name
    };
    if matches!(profile.syntax, "gas-intel" | "gas-att" | "llvm-mc") {
        format!("{name}:\n    {kind} {}\n", directive.value)
    } else if profile.syntax == "masm" {
        let value = asm_dialect_masm_dup_from_values(&directive.value)
            .unwrap_or_else(|| directive.value.clone());
        format!("{name} {kind} {value}\n")
    } else {
        format!("{name} {kind} {}\n", directive.value)
    }
}

fn asm_dialect_format_reserve_directive(
    profile: &MachineAsmDialectProfile,
    directive: &MachineDirectiveRecord,
) -> String {
    let kind = match profile.syntax {
        "gas-intel" | "gas-att" | "llvm-mc" => ".zero",
        "masm" => match directive.kind.as_str() {
            "resb" => "DB",
            "resw" => "DW",
            "resd" => "DD",
            _ => "DQ",
        },
        "fasm" => match directive.kind.as_str() {
            "resb" => "rb",
            "resw" => "rw",
            "resd" => "rd",
            "resq" => "rq",
            _ => "rb",
        },
        _ => directive.kind.as_str(),
    };
    let name = if directive.name.is_empty() {
        "asm_dialect_bss"
    } else {
        &directive.name
    };
    if matches!(profile.syntax, "gas-intel" | "gas-att" | "llvm-mc") {
        format!("{name}:\n    {kind} {}\n", directive.value)
    } else if profile.syntax == "masm" {
        format!("{name} {kind} {} DUP(?)\n", directive.value)
    } else {
        format!("{name} {kind} {}\n", directive.value)
    }
}

fn asm_dialect_masm_dup_from_values(value: &str) -> Option<String> {
    let values = asm_dialect_split_top_level_commas(value);
    if values.len() < 2 {
        return None;
    }
    let first = values.first()?.trim().to_string();
    if values.iter().all(|item| item.trim() == first) {
        return Some(format!("{} DUP({})", values.len(), first));
    }
    None
}

fn import_asm_source(
    path: &str,
    source: &str,
    profile: &MachineAsmDialectProfile,
) -> MachineAsmDialectTranslation {
    let mut diagnostics = Vec::new();
    let mut entry = "imported_main".to_string();
    let mut instructions = Vec::new();
    let mut sections = Vec::new();
    let mut symbols = Vec::new();
    let mut externs = Vec::new();
    let mut data_directives = Vec::new();
    let mut reserve_directives = Vec::new();
    let mut align_directives = Vec::new();
    let mut macro_forms = Vec::new();
    let mut masm_dup_expansions = Vec::new();
    let mut fasm_repeat_expansions = Vec::new();
    let mut fasm_macro_expansions = Vec::new();
    let mut unsupported_by_design = Vec::new();
    let mut current_section = ".text".to_string();
    let mut pending_data_label: Option<String> = None;
    let mut macro_defs: BTreeMap<String, Vec<String>> = BTreeMap::new();
    let mut current_macro: Option<(String, Vec<String>)> = None;
    let mut constants = asm_dialect_collect_constants(source, profile, &mut diagnostics);

    let mut source_lines = source.lines().map(str::to_string).collect::<Vec<_>>();
    if profile.syntax == "fasm" {
        let expanded = asm_dialect_expand_fasm_source(&source_lines, &constants, &mut diagnostics);
        source_lines = expanded.lines;
        macro_forms.extend(expanded.macro_forms);
        fasm_repeat_expansions.extend(expanded.repeat_expansions);
        fasm_macro_expansions.extend(expanded.macro_expansions);
    }

    for raw in &source_lines {
        let line = asm_dialect_strip_comment(raw, profile)
            .trim()
            .trim_end_matches(';')
            .trim();
        if line.is_empty() {
            continue;
        }
        let lower = line.to_ascii_lowercase();

        if let Some((name, mut body)) = current_macro.take() {
            if asm_dialect_is_macro_end(&lower, profile) {
                body.retain(|item| !item.trim().is_empty());
                macro_forms.push(name.clone());
                macro_defs.insert(name, body);
            } else {
                body.push(line.to_string());
                current_macro = Some((name, body));
            }
            continue;
        }

        if asm_dialect_is_unsupported_directive(&lower, profile) {
            diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_ASM_UNSUPPORTED_DIRECTIVE_001",
                format!(
                    "{} directive '{}' is unsupported_by_design in {}",
                    profile.dialect_name, line, profile.profile_name
                ),
            ));
            unsupported_by_design.push(line.to_string());
            continue;
        }

        if let Some(name) = asm_dialect_macro_start_name(line, profile) {
            current_macro = Some((name, Vec::new()));
            continue;
        }

        if let Some(expanded) = macro_defs.get(line.split_whitespace().next().unwrap_or_default()) {
            for body_line in expanded {
                if let Some(inst) = asm_dialect_normalize_instruction(body_line, profile) {
                    instructions.push(inst);
                }
            }
            continue;
        }

        if let Some(section) = asm_dialect_parse_section(&lower, profile) {
            current_section = section.clone();
            sections.push(section);
            continue;
        }
        if let Some(symbol) = asm_dialect_parse_global(line, profile) {
            if entry == "imported_main" {
                entry = symbol.clone();
            }
            symbols.push(symbol);
            continue;
        }
        if let Some(extern_name) = asm_dialect_parse_extern(line, profile) {
            externs.push(extern_name);
            continue;
        }
        if let Some((name, value)) = asm_dialect_parse_constant(line, profile) {
            if let Ok(value) = asm_dialect_eval_expr(&value, &constants) {
                constants.insert(name.clone(), value);
                constants.insert(name.to_ascii_uppercase(), value);
            }
            data_directives.push(format!("equ {name} {value}"));
            continue;
        }
        if asm_dialect_is_ignored_profile_directive(&lower, profile) {
            continue;
        }
        if let Some(align) = asm_dialect_parse_align(line, profile) {
            align_directives.push(align);
            continue;
        }
        if let Some((label, directive)) = asm_dialect_parse_data_or_reserve(
            line,
            &pending_data_label,
            profile,
            &constants,
            &mut diagnostics,
            &mut masm_dup_expansions,
        ) {
            pending_data_label = None;
            if asm_dialect_is_reserve_directive(&directive) {
                reserve_directives.push(format!("{label}: {directive}"));
            } else {
                data_directives.push(format!("{label}: {directive}"));
            }
            continue;
        }
        if line.ends_with(':') || lower.ends_with(" proc") {
            let label = asm_dialect_label_name(line);
            if current_section.contains("data") || current_section.contains("bss") {
                pending_data_label = Some(label);
                continue;
            }
            if entry == "imported_main" {
                entry = label.clone();
                symbols.push(label);
            } else if label != entry {
                instructions.push(format!("label {label}"));
            }
            continue;
        }
        if asm_dialect_is_proc_end(&lower) {
            continue;
        }
        if let Some(inst) = asm_dialect_normalize_instruction(line, profile) {
            instructions.push(inst);
        } else {
            diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_ASM_IMPORT_001",
                format!("could not import dialect line '{}'", line),
            ));
        }
    }

    if instructions.is_empty() {
        diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_ASM_IMPORT_001",
            "no importable instructions found for declared dialect profile",
        ));
    }
    symbols.sort();
    symbols.dedup();
    externs.sort();
    externs.dedup();
    if !symbols.iter().any(|symbol| symbol == &entry) {
        symbols.push(entry.clone());
    }
    let imported_nm = asm_dialect_build_imported_nm(
        path,
        profile,
        &entry,
        &symbols,
        &externs,
        &instructions,
        &data_directives,
        &reserve_directives,
        &align_directives,
    );
    MachineAsmDialectTranslation {
        syntax: profile.syntax.to_string(),
        profile_name: profile.profile_name.to_string(),
        status: if diagnostics.is_empty() {
            "closed".to_string()
        } else {
            "failed".to_string()
        },
        loss_model: if diagnostics.is_empty() {
            "lossless".to_string()
        } else {
            "unsupported".to_string()
        },
        entry,
        imported_nm,
        instructions,
        sections,
        symbols,
        externs,
        data_directives,
        reserve_directives,
        align_directives,
        macro_forms,
        masm_dup_expansions,
        fasm_repeat_expansions,
        fasm_macro_expansions,
        unsupported_by_design,
        diagnostics,
    }
}

fn asm_dialect_build_imported_nm(
    source_path: &str,
    profile: &MachineAsmDialectProfile,
    entry: &str,
    symbols: &[String],
    externs: &[String],
    instructions: &[String],
    data_directives: &[String],
    reserve_directives: &[String],
    align_directives: &[String],
) -> String {
    let mut nm = String::new();
    nm.push_str("importedAsmDialectMachine[@machine] {\n");
    nm.push_str("    target:\n        arch: x86_64;\n        abi: sysv64;\n        object: elf64;\n        endian: little;\n        pointerWidth: 64;\n        profile: userland;\n\n");
    nm.push_str("    debug:\n");
    nm.push_str(&format!(
        "        file: \"{}\";\n",
        source_path.replace('\\', "/")
    ));
    nm.push_str(&format!(
        "        producer: \"ncc asm-dialect {} importer\";\n\n",
        profile.syntax
    ));
    if !externs.is_empty() {
        nm.push_str("    extern:\n");
        for symbol in externs {
            nm.push_str(&format!("        {symbol}:\n"));
        }
        nm.push('\n');
    }
    nm.push_str("    symbol:\n");
    for symbol in symbols {
        nm.push_str(&format!(
            "        {symbol}:\n            section: .text;\n            binding: global;\n            type: routine;\n"
        ));
    }
    nm.push('\n');
    nm.push_str(&format!("    entry:\n        {entry};\n\n"));
    if !data_directives.is_empty() {
        let constants = data_directives
            .iter()
            .filter(|item| item.starts_with("equ "))
            .cloned()
            .collect::<Vec<_>>();
        if !constants.is_empty() {
            nm.push_str("    equ:\n");
            for item in constants {
                let parts = item.split_whitespace().collect::<Vec<_>>();
                if parts.len() >= 3 {
                    nm.push_str(&format!(
                        "        {}: {};\n",
                        parts[1],
                        parts[2..].join(" ")
                    ));
                }
            }
            nm.push('\n');
        }
        let data = data_directives
            .iter()
            .filter(|item| !item.starts_with("equ "))
            .collect::<Vec<_>>();
        if !data.is_empty() {
            nm.push_str("    data:\n");
            for item in data {
                if let Some((label, directive)) = item.split_once(": ") {
                    nm.push_str(&format!("        {label}:\n            {directive};\n"));
                }
            }
            nm.push('\n');
        }
    }
    if !reserve_directives.is_empty() {
        nm.push_str("    bss:\n");
        for item in reserve_directives {
            if let Some((label, directive)) = item.split_once(": ") {
                nm.push_str(&format!("        {label}:\n            {directive};\n"));
            }
        }
        nm.push('\n');
    }
    if let Some(first_align) = align_directives.first() {
        nm.push_str("    align:\n");
        nm.push_str(&format!("        {first_align};\n\n"));
    }
    nm.push_str(&format!(
        "    proc:\n        {entry}:\n            instr:\n"
    ));
    for instruction in instructions {
        nm.push_str(&format!("                {instruction};\n"));
    }
    nm.push_str("\n    verify:\n        target;\n        registers;\n        operands;\n        encoding;\n\n    seal:\n        artifact: elf64;\n        require: verified;\n}\n");
    nm
}

fn asm_dialect_strip_comment<'a>(line: &'a str, profile: &MachineAsmDialectProfile) -> &'a str {
    let mut end = line.len();
    for marker in profile.comment_syntax {
        if let Some(index) = line.find(marker) {
            end = end.min(index);
        }
    }
    &line[..end]
}

fn asm_dialect_is_ignored_profile_directive(
    line: &str,
    profile: &MachineAsmDialectProfile,
) -> bool {
    matches!(line, "bits 64" | ".intel_syntax noprefix" | ".att_syntax")
        || line == "end"
        || (profile.syntax == "fasm" && line.starts_with("format "))
        || line.starts_with(".type ")
        || line.starts_with(".size ")
}

fn asm_dialect_parse_section(line: &str, profile: &MachineAsmDialectProfile) -> Option<String> {
    if line == ".text" || line.contains(".text") || line.contains("'.text'") {
        return Some(".text".to_string());
    }
    if line == ".data" || line.contains(".data") || line.contains("'.data'") {
        return Some(".data".to_string());
    }
    if line == ".bss" || line.contains(".bss") || line.contains("'.bss'") {
        return Some(".bss".to_string());
    }
    if line.starts_with("section ") || line.ends_with(" segment") || line.ends_with(" ends") {
        if line.contains(".text") || line.contains("code") {
            return Some(".text".to_string());
        }
        if line.contains(".data") || line.contains("data") {
            return Some(".data".to_string());
        }
        if line.contains(".bss") || line.contains("bss") {
            return Some(".bss".to_string());
        }
    }
    if profile.syntax == "masm" && line == ".code" {
        return Some(".text".to_string());
    }
    None
}

fn asm_dialect_parse_global(line: &str, profile: &MachineAsmDialectProfile) -> Option<String> {
    let lower = line.to_ascii_lowercase();
    let raw = if let Some(rest) = lower.strip_prefix("global ") {
        Some(&line[line.len() - rest.len()..])
    } else if let Some(rest) = lower.strip_prefix(".globl ") {
        Some(&line[line.len() - rest.len()..])
    } else if let Some(rest) = lower.strip_prefix("public ") {
        Some(&line[line.len() - rest.len()..])
    } else if profile.syntax == "fasm" {
        lower
            .strip_prefix("public ")
            .map(|rest| &line[line.len() - rest.len()..])
    } else {
        None
    }?;
    Some(raw.trim().trim_end_matches(':').to_string())
}

fn asm_dialect_parse_extern(line: &str, _profile: &MachineAsmDialectProfile) -> Option<String> {
    let lower = line.to_ascii_lowercase();
    let raw = if let Some(rest) = lower.strip_prefix("extern ") {
        Some(&line[line.len() - rest.len()..])
    } else if let Some(rest) = lower.strip_prefix(".extern ") {
        Some(&line[line.len() - rest.len()..])
    } else {
        lower
            .strip_prefix("extrn ")
            .map(|rest| &line[line.len() - rest.len()..])
    }?;
    Some(
        raw.trim()
            .split(':')
            .next()
            .unwrap_or(raw)
            .trim()
            .to_string(),
    )
}

fn asm_dialect_parse_constant(
    line: &str,
    _profile: &MachineAsmDialectProfile,
) -> Option<(String, String)> {
    let normalized = line.replace(',', " ");
    let parts = normalized.split_whitespace().collect::<Vec<_>>();
    if parts.len() >= 3 && parts[0].eq_ignore_ascii_case("%define") {
        return Some((parts[1].to_string(), parts[2..].join(" ")));
    }
    if parts.len() >= 3 && matches!(parts[1].to_ascii_lowercase().as_str(), "equ" | "=") {
        return Some((parts[0].to_string(), parts[2..].join(" ")));
    }
    if parts.len() >= 3 && matches!(parts[0].to_ascii_lowercase().as_str(), ".equ" | ".set") {
        return Some((parts[1].to_string(), parts[2..].join(" ")));
    }
    None
}

fn asm_dialect_parse_align(line: &str, _profile: &MachineAsmDialectProfile) -> Option<String> {
    let lower = line.to_ascii_lowercase();
    for prefix in ["align ", ".align ", ".p2align "] {
        if let Some(value) = lower.strip_prefix(prefix) {
            let raw = &line[line.len() - value.len()..];
            return Some(raw.split(',').next().unwrap_or(raw).trim().to_string());
        }
    }
    None
}

fn asm_dialect_collect_constants(
    source: &str,
    profile: &MachineAsmDialectProfile,
    diagnostics: &mut Vec<MachineDiagnostic>,
) -> BTreeMap<String, i128> {
    let mut constants = BTreeMap::new();
    for raw in source.lines() {
        let line = asm_dialect_strip_comment(raw, profile)
            .trim()
            .trim_end_matches(';')
            .trim();
        if let Some((name, value)) = asm_dialect_parse_constant(line, profile) {
            match asm_dialect_eval_expr(&value, &constants) {
                Ok(value) => {
                    constants.insert(name.clone(), value);
                    constants.insert(name.to_ascii_uppercase(), value);
                }
                Err(diag) => diagnostics.push(diag),
            }
        }
    }
    constants
}

fn asm_dialect_eval_expr(
    expr: &str,
    constants: &BTreeMap<String, i128>,
) -> Result<i128, MachineDiagnostic> {
    eval_phase10_ctfe_with_diag(&asm_dialect_normalize_expr(expr), constants)
}

fn asm_dialect_normalize_expr(expr: &str) -> String {
    expr.split_whitespace()
        .map(asm_dialect_normalize_expr_token)
        .collect::<Vec<_>>()
        .join(" ")
}

fn asm_dialect_normalize_expr_token(token: &str) -> String {
    let mut out = String::new();
    let chars = token.chars().collect::<Vec<_>>();
    let mut i = 0usize;
    while i < chars.len() {
        if chars[i].is_ascii_hexdigit() {
            let start = i;
            while i < chars.len() && chars[i].is_ascii_hexdigit() {
                i += 1;
            }
            if i < chars.len() && matches!(chars[i], 'h' | 'H') && i > start {
                out.push_str("0x");
                out.extend(chars[start..i].iter());
                i += 1;
            } else {
                out.extend(chars[start..i].iter());
            }
            continue;
        }
        out.push(chars[i]);
        i += 1;
    }
    out
}

fn asm_dialect_parse_data_or_reserve(
    line: &str,
    pending_label: &Option<String>,
    profile: &MachineAsmDialectProfile,
    constants: &BTreeMap<String, i128>,
    diagnostics: &mut Vec<MachineDiagnostic>,
    masm_dup_expansions: &mut Vec<MachineAsmDialectExpansionEvidence>,
) -> Option<(String, String)> {
    let lower = line.to_ascii_lowercase();
    let parts = line.split_whitespace().collect::<Vec<_>>();
    if parts.is_empty() {
        return None;
    }
    if profile.syntax == "masm" {
        if let Some(parsed) = asm_dialect_parse_masm_data_or_dup(
            line,
            pending_label,
            constants,
            diagnostics,
            masm_dup_expansions,
        ) {
            return Some(parsed);
        }
        if lower.contains(" dup") {
            diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_MASM_DUP_SYNTAX_001",
                format!("invalid MASM DUP syntax '{}'", line),
            ));
            return None;
        }
    }
    if matches!(
        parts[0].to_ascii_lowercase().as_str(),
        "db" | "dw"
            | "dd"
            | "dq"
            | "resb"
            | "resw"
            | "resd"
            | "resq"
            | "rb"
            | "rw"
            | "rd"
            | "rq"
            | ".byte"
            | ".word"
            | ".long"
            | ".quad"
            | ".space"
            | ".zero"
    ) {
        let label = pending_label
            .clone()
            .unwrap_or_else(|| "asm_dialect_data".to_string());
        return Some((
            label,
            asm_dialect_official_directive(parts[0], &parts[1..].join(" ")),
        ));
    }
    if parts.len() >= 3
        && matches!(
            parts[1].to_ascii_lowercase().as_str(),
            "db" | "dw"
                | "dd"
                | "dq"
                | "resb"
                | "resw"
                | "resd"
                | "resq"
                | "rb"
                | "rw"
                | "rd"
                | "rq"
        )
    {
        return Some((
            parts[0].trim_end_matches(':').to_string(),
            asm_dialect_official_directive(parts[1], &parts[2..].join(" ")),
        ));
    }
    None
}

fn asm_dialect_parse_masm_data_or_dup(
    line: &str,
    pending_label: &Option<String>,
    constants: &BTreeMap<String, i128>,
    diagnostics: &mut Vec<MachineDiagnostic>,
    masm_dup_expansions: &mut Vec<MachineAsmDialectExpansionEvidence>,
) -> Option<(String, String)> {
    let (label, kind, rest) = asm_dialect_split_data_directive(line, pending_label)?;
    let kind_lower = kind.to_ascii_lowercase();
    if !matches!(kind_lower.as_str(), "db" | "dw" | "dd" | "dq") {
        return None;
    }
    let width = asm_dialect_data_width(&kind_lower);
    if !rest.to_ascii_lowercase().contains("dup") {
        return Some((
            label,
            asm_dialect_official_directive(
                &kind_lower,
                &asm_dialect_normalize_data_expr_list(&rest),
            ),
        ));
    }
    let expanded = match asm_dialect_expand_masm_dup_expr(&rest, width, constants, 0) {
        Ok(expanded) => expanded,
        Err(diag) => {
            diagnostics.push(diag);
            return None;
        }
    };
    if expanded.elements > ASM_DIALECT_DUP_EXPANSION_LIMIT {
        diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_MASM_DUP_NESTING_001",
            format!(
                "MASM DUP expansion {} exceeds limit {}",
                expanded.elements, ASM_DIALECT_DUP_EXPANSION_LIMIT
            ),
        ));
        return None;
    }
    masm_dup_expansions.push(MachineAsmDialectExpansionEvidence {
        feature: "masm_dup".to_string(),
        syntax_form: rest.clone(),
        count: expanded.count,
        expanded_nodes: expanded.elements,
        expanded_byte_count: expanded.byte_count,
        generated_labels: Vec::new(),
        origin_span: line.to_string(),
        hash: hash_string(&format!("{}:{}:{}", kind_lower, rest, expanded.official)),
        status: "closed".to_string(),
    });
    if expanded.reserve {
        let reserve_kind = match kind_lower.as_str() {
            "db" => "resb",
            "dw" => "resw",
            "dd" => "resd",
            _ => "resq",
        };
        Some((label, format!("{reserve_kind} {}", expanded.elements)))
    } else {
        Some((label, format!("{kind_lower} {}", expanded.official)))
    }
}

fn asm_dialect_split_data_directive(
    line: &str,
    pending_label: &Option<String>,
) -> Option<(String, String, String)> {
    let parts = line.split_whitespace().collect::<Vec<_>>();
    if parts.is_empty() {
        return None;
    }
    if matches!(
        parts[0].to_ascii_lowercase().as_str(),
        "db" | "dw" | "dd" | "dq"
    ) {
        let rest = line
            .split_once(char::is_whitespace)
            .map(|(_, rest)| rest.trim().to_string())
            .unwrap_or_default();
        let label = pending_label
            .clone()
            .unwrap_or_else(|| "asm_dialect_data".to_string());
        return Some((label, parts[0].to_string(), rest));
    }
    if parts.len() >= 3
        && matches!(
            parts[1].to_ascii_lowercase().as_str(),
            "db" | "dw" | "dd" | "dq"
        )
    {
        let rest = line
            .splitn(3, char::is_whitespace)
            .nth(2)
            .unwrap_or_default()
            .trim()
            .to_string();
        return Some((
            parts[0].trim_end_matches(':').to_string(),
            parts[1].to_string(),
            rest,
        ));
    }
    None
}

#[derive(Debug, Clone)]
struct AsmDialectDupExpansion {
    official: String,
    count: usize,
    elements: usize,
    byte_count: usize,
    reserve: bool,
}

fn asm_dialect_expand_masm_dup_expr(
    expr: &str,
    width: usize,
    constants: &BTreeMap<String, i128>,
    depth: usize,
) -> Result<AsmDialectDupExpansion, MachineDiagnostic> {
    if depth > ASM_DIALECT_DUP_NESTING_LIMIT {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_MASM_DUP_NESTING_001",
            "MASM DUP nesting limit exceeded",
        ));
    }
    let elements = asm_dialect_expand_masm_dup_items(expr, width, constants, depth)?;
    let reserve = !elements.is_empty() && elements.iter().all(|item| item == "?");
    let official = if reserve {
        "?".to_string()
    } else {
        elements
            .iter()
            .filter(|item| item.as_str() != "?")
            .cloned()
            .collect::<Vec<_>>()
            .join(", ")
    };
    Ok(AsmDialectDupExpansion {
        official,
        count: elements.len(),
        elements: elements.len(),
        byte_count: elements.len().saturating_mul(width),
        reserve,
    })
}

fn asm_dialect_expand_masm_dup_items(
    expr: &str,
    width: usize,
    constants: &BTreeMap<String, i128>,
    depth: usize,
) -> Result<Vec<String>, MachineDiagnostic> {
    if depth > ASM_DIALECT_DUP_NESTING_LIMIT {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_MASM_DUP_NESTING_001",
            "MASM DUP nesting limit exceeded",
        ));
    }
    if let Some((count_expr, inner)) = asm_dialect_split_dup_expr(expr)? {
        let count = asm_dialect_eval_expr(&count_expr, constants).map_err(|_| {
            MachineDiagnostic::new(
                "E_MACHINE_MASM_DUP_CTFE_001",
                format!(
                    "MASM DUP count '{}' is not a constant expression",
                    count_expr
                ),
            )
        })?;
        if count < 0 {
            return Err(MachineDiagnostic::new(
                "E_MACHINE_MASM_DUP_COUNT_001",
                format!("MASM DUP count '{}' must be non-negative", count_expr),
            ));
        }
        let count = count as usize;
        if count > ASM_DIALECT_DUP_EXPANSION_LIMIT {
            return Err(MachineDiagnostic::new(
                "E_MACHINE_MASM_DUP_NESTING_001",
                format!(
                    "MASM DUP count {} exceeds limit {}",
                    count, ASM_DIALECT_DUP_EXPANSION_LIMIT
                ),
            ));
        }
        let inner_values = asm_dialect_expand_masm_dup_items(&inner, width, constants, depth + 1)?;
        let total = count.saturating_mul(inner_values.len());
        if total > ASM_DIALECT_DUP_EXPANSION_LIMIT {
            return Err(MachineDiagnostic::new(
                "E_MACHINE_MASM_DUP_NESTING_001",
                format!(
                    "MASM DUP expansion {} exceeds limit {}",
                    total, ASM_DIALECT_DUP_EXPANSION_LIMIT
                ),
            ));
        }
        let mut out = Vec::with_capacity(total);
        for _ in 0..count {
            out.extend(inner_values.iter().cloned());
        }
        return Ok(out);
    }
    let mut out = Vec::new();
    for item in asm_dialect_split_top_level_commas(expr) {
        let item = item.trim();
        if item.is_empty() {
            continue;
        }
        if item == "?" {
            out.push("?".to_string());
            continue;
        }
        if let Some(text) = asm_dialect_parse_quoted(item) {
            if width != 1 {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_MASM_DUP_OVERFLOW_001",
                    "MASM DUP string values are byte-width in nC-masm-compat-v1",
                ));
            }
            out.extend(text.as_bytes().iter().map(|byte| byte.to_string()));
            continue;
        }
        let value = asm_dialect_eval_expr(item, constants).map_err(|diag| {
            MachineDiagnostic::new(
                "E_MACHINE_MASM_DUP_CTFE_001",
                format!(
                    "{} while evaluating MASM DUP value '{}'",
                    diag.message, item
                ),
            )
        })?;
        asm_dialect_check_data_width(value, width)?;
        out.push(value.to_string());
    }
    Ok(out)
}

fn asm_dialect_split_dup_expr(expr: &str) -> Result<Option<(String, String)>, MachineDiagnostic> {
    let lower = expr.to_ascii_lowercase();
    let chars = expr.chars().collect::<Vec<_>>();
    let lower_chars = lower.chars().collect::<Vec<_>>();
    let mut depth = 0i32;
    let mut quote: Option<char> = None;
    let mut i = 0usize;
    while i + 3 <= chars.len() {
        let ch = chars[i];
        if matches!(ch, '"' | '\'') {
            quote = if quote == Some(ch) { None } else { Some(ch) };
            i += 1;
            continue;
        }
        if quote.is_none() {
            if ch == '(' {
                depth += 1;
            } else if ch == ')' {
                depth -= 1;
            }
            if depth == 0 && i + 3 <= chars.len() && lower_chars[i..i + 3] == ['d', 'u', 'p'] {
                let after = expr[i + 3..].trim_start();
                if !after.starts_with('(') {
                    return Err(MachineDiagnostic::new(
                        "E_MACHINE_MASM_DUP_SYNTAX_001",
                        format!("MASM DUP missing '(' in '{}'", expr),
                    ));
                }
                let start = expr[i + 3..]
                    .find('(')
                    .map(|offset| i + 3 + offset)
                    .unwrap();
                let end = asm_dialect_matching_paren(expr, start).ok_or_else(|| {
                    MachineDiagnostic::new(
                        "E_MACHINE_MASM_DUP_SYNTAX_001",
                        format!("MASM DUP has unbalanced parentheses in '{}'", expr),
                    )
                })?;
                if !expr[end + 1..].trim().is_empty() {
                    return Err(MachineDiagnostic::new(
                        "E_MACHINE_MASM_DUP_SYNTAX_001",
                        format!("MASM DUP has trailing tokens in '{}'", expr),
                    ));
                }
                return Ok(Some((
                    expr[..i].trim().to_string(),
                    expr[start + 1..end].trim().to_string(),
                )));
            }
        }
        i += 1;
    }
    Ok(None)
}

fn asm_dialect_matching_paren(text: &str, open: usize) -> Option<usize> {
    let mut depth = 0i32;
    let mut quote: Option<char> = None;
    for (index, ch) in text.char_indices().skip_while(|(idx, _)| *idx < open) {
        if matches!(ch, '"' | '\'') {
            quote = if quote == Some(ch) { None } else { Some(ch) };
            continue;
        }
        if quote.is_some() {
            continue;
        }
        if ch == '(' {
            depth += 1;
        } else if ch == ')' {
            depth -= 1;
            if depth == 0 {
                return Some(index);
            }
        }
    }
    None
}

fn asm_dialect_split_top_level_commas(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut current = String::new();
    let mut depth = 0i32;
    let mut quote: Option<char> = None;
    for ch in text.chars() {
        if matches!(ch, '"' | '\'') {
            quote = if quote == Some(ch) { None } else { Some(ch) };
            current.push(ch);
            continue;
        }
        if quote.is_none() {
            if ch == '(' {
                depth += 1;
            } else if ch == ')' {
                depth -= 1;
            } else if ch == ',' && depth == 0 {
                out.push(current.trim().to_string());
                current.clear();
                continue;
            }
        }
        current.push(ch);
    }
    if !current.trim().is_empty() {
        out.push(current.trim().to_string());
    }
    out
}

fn asm_dialect_parse_quoted(raw: &str) -> Option<String> {
    let trimmed = raw.trim();
    let quote = trimmed.chars().next()?;
    if !matches!(quote, '"' | '\'') || !trimmed.ends_with(quote) || trimmed.len() < 2 {
        return None;
    }
    Some(trimmed[1..trimmed.len() - 1].to_string())
}

fn asm_dialect_data_width(kind: &str) -> usize {
    match kind {
        "db" => 1,
        "dw" => 2,
        "dd" => 4,
        _ => 8,
    }
}

fn asm_dialect_check_data_width(value: i128, width: usize) -> Result<(), MachineDiagnostic> {
    let max = match width {
        1 => 0xff_i128,
        2 => 0xffff_i128,
        4 => 0xffff_ffff_i128,
        _ => i128::from(u64::MAX),
    };
    if value < 0 || value > max {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_MASM_DUP_OVERFLOW_001",
            format!("MASM DUP value {} does not fit {} bytes", value, width),
        ));
    }
    Ok(())
}

fn asm_dialect_normalize_data_expr_list(rest: &str) -> String {
    asm_dialect_split_top_level_commas(rest)
        .into_iter()
        .map(|item| asm_dialect_normalize_expr(&item))
        .collect::<Vec<_>>()
        .join(", ")
}

#[derive(Debug, Clone)]
struct AsmDialectFasmMacroDef {
    name: String,
    params: Vec<String>,
    variadic: Option<String>,
    body: Vec<String>,
}

fn asm_dialect_expand_fasm_source(
    source_lines: &[String],
    constants: &BTreeMap<String, i128>,
    diagnostics: &mut Vec<MachineDiagnostic>,
) -> MachineAsmDialectExpandedSource {
    let (without_macros, macros, macro_forms) =
        asm_dialect_extract_fasm_macros(source_lines, diagnostics);
    let mut macro_expansions = Vec::new();
    let mut labels = BTreeSet::new();
    let mut invocation_index = 0usize;
    let mut macro_expanded = Vec::new();
    for line in without_macros {
        let mut stack = Vec::new();
        let expanded = asm_dialect_expand_fasm_macro_line(
            &line,
            &macros,
            constants,
            diagnostics,
            &mut macro_expansions,
            &mut stack,
            &mut invocation_index,
            &mut labels,
        );
        macro_expanded.extend(expanded);
    }
    let mut repeat_expansions = Vec::new();
    let lines = asm_dialect_expand_fasm_repeats(
        &macro_expanded,
        constants,
        diagnostics,
        &mut repeat_expansions,
        0,
    );
    MachineAsmDialectExpandedSource {
        lines,
        macro_forms,
        repeat_expansions,
        macro_expansions,
    }
}

fn asm_dialect_extract_fasm_macros(
    source_lines: &[String],
    diagnostics: &mut Vec<MachineDiagnostic>,
) -> (
    Vec<String>,
    BTreeMap<String, AsmDialectFasmMacroDef>,
    Vec<String>,
) {
    let mut lines = Vec::new();
    let mut macros = BTreeMap::new();
    let mut macro_forms = Vec::new();
    let mut i = 0usize;
    while i < source_lines.len() {
        let line = source_lines[i].trim();
        if line.to_ascii_lowercase().starts_with("macro ") {
            let Some((name, params, variadic)) = asm_dialect_parse_fasm_macro_header(line) else {
                diagnostics.push(MachineDiagnostic::new(
                    "E_MACHINE_FASM_MACRO_001",
                    format!("invalid FASM macro declaration '{}'", line),
                ));
                i += 1;
                continue;
            };
            i += 1;
            let mut body = Vec::new();
            while i < source_lines.len()
                && !source_lines[i].trim().eq_ignore_ascii_case("end macro")
            {
                body.push(source_lines[i].clone());
                i += 1;
            }
            if i == source_lines.len() {
                diagnostics.push(MachineDiagnostic::new(
                    "E_MACHINE_FASM_MACRO_001",
                    format!("FASM macro '{}' is missing end macro", name),
                ));
            } else {
                i += 1;
            }
            macro_forms.push(name.clone());
            macros.insert(
                name.clone(),
                AsmDialectFasmMacroDef {
                    name,
                    params,
                    variadic,
                    body,
                },
            );
            continue;
        }
        lines.push(source_lines[i].clone());
        i += 1;
    }
    (lines, macros, macro_forms)
}

fn asm_dialect_parse_fasm_macro_header(
    line: &str,
) -> Option<(String, Vec<String>, Option<String>)> {
    let rest = line.trim().strip_prefix("macro ")?;
    let mut parts = rest.splitn(2, char::is_whitespace);
    let name = parts.next()?.trim().to_string();
    let raw_params = parts.next().unwrap_or("").trim();
    let mut params = Vec::new();
    let mut variadic = None;
    if !raw_params.is_empty() {
        for raw in asm_dialect_split_top_level_commas(raw_params) {
            let param = raw.trim();
            if param.is_empty() {
                continue;
            }
            let name = param
                .trim_end_matches('*')
                .trim_end_matches('&')
                .to_string();
            if param.ends_with('*') || param.ends_with('&') {
                variadic = Some(name.clone());
            }
            params.push(name);
        }
    }
    Some((name, params, variadic))
}

#[allow(clippy::too_many_arguments)]
fn asm_dialect_expand_fasm_macro_line(
    line: &str,
    macros: &BTreeMap<String, AsmDialectFasmMacroDef>,
    constants: &BTreeMap<String, i128>,
    diagnostics: &mut Vec<MachineDiagnostic>,
    evidence: &mut Vec<MachineAsmDialectExpansionEvidence>,
    stack: &mut Vec<String>,
    invocation_index: &mut usize,
    labels: &mut BTreeSet<String>,
) -> Vec<String> {
    let trimmed = asm_dialect_strip_fasm_comment(line).trim();
    let Some(first) = trimmed.split_whitespace().next() else {
        return vec![line.to_string()];
    };
    let Some(def) = macros.get(first) else {
        return vec![line.to_string()];
    };
    if stack.iter().any(|name| name == &def.name)
        || stack.len() >= ASM_DIALECT_FASM_MACRO_RECURSION_LIMIT
    {
        diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_FASM_MACRO_RECURSION_001",
            format!("FASM macro '{}' exceeds recursion policy", def.name),
        ));
        return Vec::new();
    }
    let args_text = trimmed[first.len()..].trim();
    let args = if args_text.is_empty() {
        Vec::new()
    } else {
        asm_dialect_split_top_level_commas(args_text)
    };
    let Some(bindings) = asm_dialect_bind_fasm_macro_args(def, &args, diagnostics) else {
        return Vec::new();
    };
    *invocation_index += 1;
    stack.push(def.name.clone());
    let mut label_map = BTreeMap::new();
    for body_line in &def.body {
        let candidate = asm_dialect_strip_fasm_comment(body_line).trim();
        if candidate.ends_with(':') {
            let label = candidate.trim_end_matches(':').trim();
            if label.starts_with('.') {
                label_map.insert(
                    label.to_string(),
                    format!("{}$macro${}", label, invocation_index),
                );
            } else if !labels.insert(label.to_string()) {
                diagnostics.push(MachineDiagnostic::new(
                    "E_MACHINE_FASM_MACRO_LABEL_COLLISION_001",
                    format!(
                        "FASM macro '{}' emits duplicate label '{}'",
                        def.name, label
                    ),
                ));
            }
        }
    }
    let mut out = Vec::new();
    let mut generated_labels = Vec::new();
    for body_line in &def.body {
        let mut expanded = body_line.to_string();
        for (param, value) in &bindings {
            expanded = asm_dialect_replace_word(&expanded, param, value);
        }
        for (original, generated) in &label_map {
            if expanded.contains(original) {
                expanded = expanded.replace(original, generated);
                generated_labels.push(generated.clone());
            }
        }
        let nested = asm_dialect_expand_fasm_macro_line(
            &expanded,
            macros,
            constants,
            diagnostics,
            evidence,
            stack,
            invocation_index,
            labels,
        );
        out.extend(nested);
    }
    stack.pop();
    generated_labels.sort();
    generated_labels.dedup();
    evidence.push(MachineAsmDialectExpansionEvidence {
        feature: "fasm_macro".to_string(),
        syntax_form: trimmed.to_string(),
        count: args.len(),
        expanded_nodes: out.len(),
        expanded_byte_count: out.iter().map(|line| line.len()).sum(),
        generated_labels,
        origin_span: trimmed.to_string(),
        hash: hash_string(&out.join("\n")),
        status: "closed".to_string(),
    });
    let _ = constants;
    out
}

fn asm_dialect_bind_fasm_macro_args(
    def: &AsmDialectFasmMacroDef,
    args: &[String],
    diagnostics: &mut Vec<MachineDiagnostic>,
) -> Option<BTreeMap<String, String>> {
    let required = if def.variadic.is_some() {
        def.params.len().saturating_sub(1)
    } else {
        def.params.len()
    };
    if args.len() < required || (def.variadic.is_none() && args.len() != def.params.len()) {
        diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_FASM_MACRO_ARG_001",
            format!("FASM macro '{}' received wrong argument count", def.name),
        ));
        return None;
    }
    let mut bindings = BTreeMap::new();
    for (index, param) in def.params.iter().enumerate() {
        if def.variadic.as_deref() == Some(param.as_str()) {
            bindings.insert(param.clone(), args[index..].join(", "));
            break;
        }
        if let Some(arg) = args.get(index) {
            bindings.insert(param.clone(), arg.clone());
        }
    }
    Some(bindings)
}

fn asm_dialect_expand_fasm_repeats(
    lines: &[String],
    constants: &BTreeMap<String, i128>,
    diagnostics: &mut Vec<MachineDiagnostic>,
    evidence: &mut Vec<MachineAsmDialectExpansionEvidence>,
    depth: usize,
) -> Vec<String> {
    if depth > ASM_DIALECT_FASM_REPEAT_NESTING_LIMIT {
        diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_FASM_REPEAT_NESTING_001",
            "FASM repeat nesting limit exceeded",
        ));
        return Vec::new();
    }
    let mut out = Vec::new();
    let mut i = 0usize;
    while i < lines.len() {
        let trimmed = asm_dialect_strip_fasm_comment(&lines[i]).trim().to_string();
        let lower = trimmed.to_ascii_lowercase();
        if let Some(expr) = lower.strip_prefix("repeat ") {
            let count =
                match asm_dialect_eval_expr(&trimmed[trimmed.len() - expr.len()..], constants) {
                    Ok(value) if value >= 0 => value as usize,
                    Ok(_) => {
                        diagnostics.push(MachineDiagnostic::new(
                            "E_MACHINE_FASM_REPEAT_COUNT_001",
                            format!("FASM repeat count '{}' must be non-negative", expr),
                        ));
                        0
                    }
                    Err(_) => {
                        diagnostics.push(MachineDiagnostic::new(
                            "E_MACHINE_FASM_REPEAT_CTFE_001",
                            format!("FASM repeat count '{}' is not constant", expr),
                        ));
                        0
                    }
                };
            if count > ASM_DIALECT_FASM_REPEAT_LIMIT {
                diagnostics.push(MachineDiagnostic::new(
                    "E_MACHINE_FASM_REPEAT_LIMIT_001",
                    format!(
                        "FASM repeat count {} exceeds limit {}",
                        count, ASM_DIALECT_FASM_REPEAT_LIMIT
                    ),
                ));
            }
            i += 1;
            let mut body = Vec::new();
            let mut nested = 0usize;
            while i < lines.len() {
                let body_line = asm_dialect_strip_fasm_comment(&lines[i])
                    .trim()
                    .to_ascii_lowercase();
                if body_line.starts_with("repeat ") {
                    nested += 1;
                }
                if body_line == "end repeat" {
                    if nested == 0 {
                        break;
                    }
                    nested -= 1;
                }
                body.push(lines[i].clone());
                i += 1;
            }
            if i == lines.len() {
                diagnostics.push(MachineDiagnostic::new(
                    "E_MACHINE_FASM_REPEAT_001",
                    "FASM repeat is missing end repeat",
                ));
            } else {
                i += 1;
            }
            if count == 0 || count > ASM_DIALECT_FASM_REPEAT_LIMIT {
                continue;
            }
            let mut generated_labels = Vec::new();
            let mut expanded_nodes = Vec::new();
            for index in 1..=count {
                let mut label_map = BTreeMap::new();
                for body_line in &body {
                    let candidate = asm_dialect_strip_fasm_comment(body_line).trim();
                    if candidate.ends_with(':') && candidate.trim_start().starts_with('.') {
                        let label = candidate.trim_end_matches(':').trim();
                        label_map.insert(label.to_string(), format!("{}$repeat${}", label, index));
                    }
                }
                let mut iteration = Vec::new();
                for body_line in &body {
                    let mut expanded = body_line.replace('%', &index.to_string());
                    for (original, generated) in &label_map {
                        if expanded.contains(original) {
                            expanded = expanded.replace(original, generated);
                            generated_labels.push(generated.clone());
                        }
                    }
                    iteration.push(expanded);
                }
                expanded_nodes.extend(asm_dialect_expand_fasm_repeats(
                    &iteration,
                    constants,
                    diagnostics,
                    evidence,
                    depth + 1,
                ));
            }
            generated_labels.sort();
            generated_labels.dedup();
            evidence.push(MachineAsmDialectExpansionEvidence {
                feature: "fasm_repeat".to_string(),
                syntax_form: trimmed.clone(),
                count,
                expanded_nodes: expanded_nodes.len(),
                expanded_byte_count: expanded_nodes.iter().map(|line| line.len()).sum(),
                generated_labels,
                origin_span: trimmed,
                hash: hash_string(&expanded_nodes.join("\n")),
                status: "closed".to_string(),
            });
            out.extend(expanded_nodes);
            continue;
        }
        if lower == "end repeat" {
            diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_FASM_REPEAT_001",
                "stray FASM end repeat",
            ));
            i += 1;
            continue;
        }
        out.push(lines[i].clone());
        i += 1;
    }
    out
}

fn asm_dialect_strip_fasm_comment(line: &str) -> &str {
    line.split(';').next().unwrap_or(line)
}

fn asm_dialect_replace_word(text: &str, needle: &str, replacement: &str) -> String {
    let mut out = String::new();
    let chars = text.chars().collect::<Vec<_>>();
    let needle_chars = needle.chars().collect::<Vec<_>>();
    let mut i = 0usize;
    while i < chars.len() {
        if i + needle_chars.len() <= chars.len()
            && chars[i..i + needle_chars.len()] == needle_chars[..]
            && (i == 0 || !chars[i - 1].is_ascii_alphanumeric())
            && (i + needle_chars.len() == chars.len()
                || !chars[i + needle_chars.len()].is_ascii_alphanumeric())
        {
            out.push_str(replacement);
            i += needle_chars.len();
        } else {
            out.push(chars[i]);
            i += 1;
        }
    }
    out
}

fn asm_dialect_official_directive(kind: &str, rest: &str) -> String {
    let lower = kind.to_ascii_lowercase();
    let kind = match lower.as_str() {
        ".byte" => "db",
        ".word" => "dw",
        ".long" => "dd",
        ".quad" => "dq",
        ".space" | ".zero" => "resb",
        "rb" => "resb",
        "rw" => "resw",
        "rd" => "resd",
        "rq" => "resq",
        other => other,
    };
    format!(
        "{kind} {}",
        asm_dialect_normalize_data_expr_list(rest.trim())
    )
}

fn asm_dialect_is_reserve_directive(directive: &str) -> bool {
    directive.starts_with("res")
}

fn asm_dialect_label_name(line: &str) -> String {
    line.trim()
        .trim_end_matches(':')
        .split_whitespace()
        .next()
        .unwrap_or("label")
        .to_string()
}

fn asm_dialect_is_proc_end(line: &str) -> bool {
    line.ends_with(" endp") || line == "endp" || line == "end"
}

fn asm_dialect_is_macro_end(line: &str, profile: &MachineAsmDialectProfile) -> bool {
    match profile.syntax {
        "nasm" | "yasm" => line.starts_with("%endmacro"),
        "gas-intel" | "gas-att" | "llvm-mc" => line.starts_with(".endm"),
        "masm" => line == "endm",
        "fasm" => line == "end macro" || line == "endm",
        _ => false,
    }
}

fn asm_dialect_macro_start_name(line: &str, profile: &MachineAsmDialectProfile) -> Option<String> {
    let lower = line.to_ascii_lowercase();
    match profile.syntax {
        "nasm" | "yasm" => lower
            .strip_prefix("%macro ")
            .and_then(|_| line.split_whitespace().nth(1))
            .map(str::to_string),
        "gas-intel" | "gas-att" | "llvm-mc" => lower
            .strip_prefix(".macro ")
            .and_then(|_| line.split_whitespace().nth(1))
            .map(str::to_string),
        "masm" => lower.ends_with(" macro").then(|| {
            line.split_whitespace()
                .next()
                .unwrap_or("macro")
                .to_string()
        }),
        "fasm" => lower
            .strip_prefix("macro ")
            .and_then(|_| line.split_whitespace().nth(1))
            .map(str::to_string),
        _ => None,
    }
}

fn asm_dialect_is_unsupported_directive(line: &str, profile: &MachineAsmDialectProfile) -> bool {
    let unsupported = match profile.syntax {
        "masm" => ["invoke", "proto"].as_slice(),
        "nasm" | "yasm" => ["struc", "istruc", "absolute"].as_slice(),
        "fasm" => ["virtual", "load ", "store "].as_slice(),
        "gas-intel" | "gas-att" | "llvm-mc" => {
            [".cfi_", ".bundle_", ".subsections_via_symbols"].as_slice()
        }
        _ => [].as_slice(),
    };
    unsupported.iter().any(|item| line.starts_with(item))
}

fn asm_dialect_normalize_instruction(
    line: &str,
    profile: &MachineAsmDialectProfile,
) -> Option<String> {
    let line = line.trim().trim_end_matches(';').trim();
    if line.is_empty() {
        return None;
    }
    let lower = line.to_ascii_lowercase();
    if lower.ends_with(" proc")
        || lower.ends_with(" endp")
        || lower == "end"
        || lower.starts_with("global ")
        || lower.starts_with(".globl ")
        || lower.starts_with("public ")
    {
        return None;
    }
    if profile.syntax == "gas-att" {
        return asm_dialect_normalize_att_instruction(line);
    }
    let mut normalized = line
        .replace("QWORD PTR", "")
        .replace("DWORD PTR", "")
        .replace("WORD PTR", "")
        .replace("BYTE PTR", "")
        .replace("qword ptr", "")
        .replace("dword ptr", "")
        .replace("word ptr", "")
        .replace("byte ptr", "")
        .replace("[rel ", "[")
        .replace(" OFFSET ", " ");
    normalized = normalized.split_whitespace().collect::<Vec<_>>().join(" ");
    if normalized.is_empty() {
        None
    } else {
        Some(normalized.to_ascii_lowercase())
    }
}

fn asm_dialect_normalize_att_instruction(line: &str) -> Option<String> {
    let mut split = line.trim().splitn(2, char::is_whitespace);
    let mnemonic = split.next()?.trim().trim_end_matches(['b', 'w', 'l', 'q']);
    let rest = split.next().unwrap_or("").trim();
    if mnemonic == "ret" || mnemonic == "nop" {
        return Some(mnemonic.to_string());
    }
    let mut operands = if rest.is_empty() {
        Vec::new()
    } else {
        split_asm_dialect_operands(rest)
            .into_iter()
            .map(|operand| asm_dialect_att_operand_to_intel(&operand))
            .collect::<Vec<_>>()
    };
    operands.reverse();
    if operands.is_empty() {
        Some(mnemonic.to_string())
    } else {
        Some(format!("{mnemonic} {}", operands.join(", ")))
    }
}

fn split_asm_dialect_operands(rest: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut current = String::new();
    let mut depth = 0usize;
    for ch in rest.chars() {
        match ch {
            '(' => {
                depth += 1;
                current.push(ch);
            }
            ')' => {
                depth = depth.saturating_sub(1);
                current.push(ch);
            }
            ',' if depth == 0 => {
                out.push(current.trim().to_string());
                current.clear();
            }
            _ => current.push(ch),
        }
    }
    if !current.trim().is_empty() {
        out.push(current.trim().to_string());
    }
    out
}

fn asm_dialect_att_operand_to_intel(operand: &str) -> String {
    let operand = operand.trim();
    if let Some(imm) = operand.strip_prefix('$') {
        return imm.to_string();
    }
    if let Some(reg) = operand.strip_prefix('%') {
        return reg.to_string();
    }
    if operand.contains('(') && operand.ends_with(')') {
        return asm_dialect_att_mem_to_intel(operand);
    }
    operand.to_string()
}

fn asm_dialect_att_mem_to_intel(operand: &str) -> String {
    let (disp, rest) = operand.split_once('(').unwrap_or(("", operand));
    let inner = rest.trim_end_matches(')');
    let parts = inner.split(',').collect::<Vec<_>>();
    let base = parts
        .first()
        .map(|item| item.trim().trim_start_matches('%'))
        .unwrap_or("");
    let index = parts
        .get(1)
        .map(|item| item.trim().trim_start_matches('%'))
        .unwrap_or("");
    let scale = parts.get(2).map(|item| item.trim()).unwrap_or("");
    let mut terms = Vec::new();
    if !base.is_empty() {
        terms.push(base.to_string());
    }
    if !index.is_empty() {
        if scale.is_empty() {
            terms.push(index.to_string());
        } else {
            terms.push(format!("{index}*{scale}"));
        }
    }
    if !disp.trim().is_empty() && disp.trim() != "0" {
        terms.push(disp.trim().to_string());
    }
    format!("[{}]", terms.join(" + "))
}

fn asm_dialect_intel_mem_to_att(operand: &str) -> String {
    let inner = operand.trim().trim_start_matches('[').trim_end_matches(']');
    let mut base = "";
    let mut index = "";
    let mut scale = "";
    let mut disp = "0";
    for part in inner.split('+').map(str::trim) {
        if let Some((idx, scl)) = part.split_once('*') {
            index = idx.trim();
            scale = scl.trim();
        } else if asm_dialect_is_register(part) && base.is_empty() {
            base = part;
        } else if !part.is_empty() {
            disp = part;
        }
    }
    let base = if base.is_empty() {
        String::new()
    } else {
        format!("%{base}")
    };
    let index = if index.is_empty() {
        String::new()
    } else {
        format!(",%{index},{}", if scale.is_empty() { "1" } else { scale })
    };
    format!("{disp}({base}{index})")
}

fn asm_dialect_is_register(operand: &str) -> bool {
    X86_64_REGISTERS
        .iter()
        .any(|reg| reg.eq_ignore_ascii_case(operand))
}

fn asm_dialect_import_report_json(
    source: &str,
    out: &str,
    translation: &MachineAsmDialectTranslation,
    audit: &MachineAudit,
) -> Value {
    json!({
        "status": translation.status,
        "source": source,
        "output": out,
        "syntax": translation.syntax,
        "profile": translation.profile_name,
        "loss_model": translation.loss_model,
        "entry": translation.entry,
        "instructions": translation.instructions,
        "sections": translation.sections,
        "symbols": translation.symbols,
        "externs": translation.externs,
        "data_directives": translation.data_directives,
        "reserve_directives": translation.reserve_directives,
        "align_directives": translation.align_directives,
        "macro_forms": translation.macro_forms,
        "masm_dup_expansions": asm_dialect_expansion_evidence_json(&translation.masm_dup_expansions),
        "fasm_repeat_expansions": asm_dialect_expansion_evidence_json(&translation.fasm_repeat_expansions),
        "fasm_macro_expansions": asm_dialect_expansion_evidence_json(&translation.fasm_macro_expansions),
        "unsupported_by_design_seen": translation.unsupported_by_design,
        "imported_nm_machine_check": if audit.has_errors() { "failed" } else { "ok" },
        "imported_nm_hash": hash_string(&translation.imported_nm),
        "diagnostics": diagnostics_to_json(&translation.diagnostics),
        "silent_loss": 0,
        "fake_import": false,
        "string_opaque_import": false,
        "fn_fa_forbidden": true
    })
}

fn asm_dialect_expansion_evidence_json(items: &[MachineAsmDialectExpansionEvidence]) -> Value {
    Value::Array(
        items
            .iter()
            .map(|item| {
                json!({
                    "feature": item.feature,
                    "syntax_form": item.syntax_form,
                    "count": item.count,
                    "expanded_nodes": item.expanded_nodes,
                    "expanded_byte_count": item.expanded_byte_count,
                    "generated_labels": item.generated_labels,
                    "origin_span": item.origin_span,
                    "hash": item.hash,
                    "status": item.status
                })
            })
            .collect(),
    )
}

fn asm_dialect_export_report_json(
    source: &str,
    out: &str,
    profile: &MachineAsmDialectProfile,
    asm: &str,
    audit: &MachineAudit,
) -> Value {
    json!({
        "status": "closed",
        "source": source,
        "output": out,
        "syntax": profile.syntax,
        "profile": profile.profile_name,
        "loss_model": "lossless",
        "bytes": asm.len(),
        "hash": hash_string(asm),
        "instruction_count": audit.instructions.iter().filter(|inst| inst.mnemonic != "label").count(),
        "symbol_count": audit.symbols.len(),
        "directive_count": audit.directives.len(),
        "silent_loss": 0,
        "fake_export": false,
        "asm_complete_total": true
    })
}

fn asm_dialect_import_back_report(
    path: &str,
    profile: &MachineAsmDialectProfile,
) -> Result<Value, Box<dyn Error>> {
    let audit = audit_machine_file(path)?;
    if audit.has_errors() {
        return Err(diagnostics_summary(&audit.diagnostics).into());
    }
    let asm = export_asm_to_string(&audit, profile);
    let root = Path::new("target/tmp/asm_dialect_import_back");
    fs::create_dir_all(root)?;
    let asm_path = root.join(format!("{}_{}.asm", source_stem(path), profile.syntax));
    let nm_path = root.join(format!(
        "{}_{}_imported.nm",
        source_stem(path),
        profile.syntax
    ));
    write_output(&asm_path.display().to_string(), asm.as_bytes())?;
    let translation = import_asm_source(&asm_path.display().to_string(), &asm, profile);
    if !translation.diagnostics.is_empty() {
        return Err(diagnostics_summary(&translation.diagnostics).into());
    }
    write_output(
        &nm_path.display().to_string(),
        translation.imported_nm.as_bytes(),
    )?;
    let imported_audit = audit_machine_file(&nm_path.display().to_string())?;
    if imported_audit.has_errors() {
        return Err(diagnostics_summary(&imported_audit.diagnostics).into());
    }
    let original_count = audit
        .instructions
        .iter()
        .filter(|inst| inst.mnemonic != "label")
        .count();
    let imported_count = imported_audit
        .instructions
        .iter()
        .filter(|inst| inst.mnemonic != "label")
        .count();
    let lossless = original_count == imported_count;
    Ok(json!({
        "status": if lossless { "closed" } else { "not_closed" },
        "source": path,
        "syntax": profile.syntax,
        "profile": profile.profile_name,
        "exported_asm": asm_path.display().to_string(),
        "imported_nm": nm_path.display().to_string(),
        "loss_model": if lossless { "lossless" } else { "lossy_with_report" },
        "original_instruction_count": original_count,
        "imported_instruction_count": imported_count,
        "masm_dup_expansions": asm_dialect_expansion_evidence_json(&translation.masm_dup_expansions),
        "fasm_repeat_expansions": asm_dialect_expansion_evidence_json(&translation.fasm_repeat_expansions),
        "fasm_macro_expansions": asm_dialect_expansion_evidence_json(&translation.fasm_macro_expansions),
        "imported_nm_machine_check": "ok",
        "silent_loss": 0,
        "fake_import": false,
        "fake_export": false,
        "fn_fa_forbidden": true,
        "asm_complete_total": true
    }))
}

fn audit_machine_file(path: &str) -> Result<MachineAudit, Box<dyn Error>> {
    if file_extension(path) != "nm" {
        let mut audit = MachineAudit::empty(path);
        audit.diagnostics.push(MachineDiagnostic::registered(
            "E_MACHINE_FILE_EXTENSION_001",
            "machine source must use .nm extension",
        ));
        for diagnostic in &mut audit.diagnostics {
            diagnostic.attach_file(path);
        }
        audit.status = "broken".to_string();
        return Ok(audit);
    }
    let source = fs::read_to_string(path)?;
    let mut audit = parse_machine_source(path, &source);
    apply_phase10_macro_directive_system(path, &source, &mut audit);
    validate_machine(&mut audit);
    audit.encoded_bytes = if audit.diagnostics.is_empty() {
        let arch = audit_arch(&audit).to_string();
        let instructions = audit.instructions.clone();
        encode_instructions_for_arch(&arch, &instructions, &mut audit.diagnostics)
    } else {
        Vec::new()
    };
    if audit.diagnostics.is_empty() {
        audit.status = match audit_arch(&audit) {
            "x86_64" => "machine_level_5_local_eligible".to_string(),
            "aarch64" => "machine_target_artifact_aarch64".to_string(),
            "armv7" | "armv7em" | "thumb" | "thumb2" => {
                "machine_target_artifact_armv7_thumb2".to_string()
            }
            "riscv64" => "machine_target_artifact_riscv64".to_string(),
            "riscv32" => "machine_target_artifact_riscv32".to_string(),
            "i386" => "machine_target_artifact_i386".to_string(),
            "wasm32" => "machine_target_artifact_wasm32".to_string(),
            _ => "machine_target_artifact_unknown".to_string(),
        };
    } else {
        audit.status = "broken".to_string();
    }
    for diagnostic in &mut audit.diagnostics {
        diagnostic.attach_file(path);
    }
    Ok(audit)
}

impl MachineAudit {
    fn empty(path: &str) -> Self {
        Self {
            path: path.to_string(),
            container: None,
            canonical_container: false,
            target: BTreeMap::new(),
            sections: BTreeSet::new(),
            symbols: BTreeSet::new(),
            externs: BTreeSet::new(),
            exports: BTreeSet::new(),
            labels: BTreeSet::new(),
            routines: BTreeSet::new(),
            entry: None,
            debug: BTreeMap::new(),
            cfi: Vec::new(),
            frame: Vec::new(),
            stack: Vec::new(),
            instructions: Vec::new(),
            relocations: Vec::new(),
            relocation_records: Vec::new(),
            macros: Vec::new(),
            macro_invocations: Vec::new(),
            macro_expansions: Vec::new(),
            directives: Vec::new(),
            conditionals: Vec::new(),
            repeats: Vec::new(),
            includes: Vec::new(),
            incbins: Vec::new(),
            constants: BTreeMap::new(),
            data_bytes: Vec::new(),
            bss_size: 0,
            diagnostics: Vec::new(),
            deferred: Vec::new(),
            encoded_bytes: Vec::new(),
            status: "parsed".to_string(),
            conformance_level: "Machine Level 5 local / Level 6 gate-ready".to_string(),
        }
    }
}

fn parse_machine_source(path: &str, source: &str) -> MachineAudit {
    let mut audit = MachineAudit::empty(path);
    audit.canonical_container = detect_canonical_machine_container(source).is_some();
    audit.container = detect_machine_container(source);
    let mut current_section: Option<String> = None;
    let mut in_instr = false;
    let mut in_target = false;
    let mut in_reloc = false;
    let mut symbol_section = false;
    let mut extern_section = false;
    let mut proc_section = false;
    let mut label_section = false;
    let mut debug_section = false;
    let mut cfi_section = false;
    let mut frame_section = false;
    let mut stack_section = false;
    let mut current_reloc: Option<MachineRelocationRecord> = None;

    for raw in source.lines() {
        let trimmed = strip_comment(raw).trim();
        if trimmed.is_empty() || trimmed == "{" || trimmed == "}" {
            continue;
        }
        if is_forbidden_section_line(trimmed, "fn") {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_HIGH_LEVEL_FN_FORBIDDEN_001",
                "fn: is forbidden in [@machine]; use proc:, routine:, block:, label:, instr:, verify:, and seal:",
            ));
            continue;
        }
        if is_forbidden_section_line(trimmed, "fa") {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_HIGH_LEVEL_FA_FORBIDDEN_001",
                "fa: is forbidden in [@machine]; use ret/hlt/jmp plus verify: and seal:",
            ));
            continue;
        }
        if is_forbidden_section_line(trimmed, "stc") {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_HIGH_LEVEL_STC_FORBIDDEN_001",
                "stc: is forbidden in [@machine]; use section:, symbol:, data/object declarations",
            ));
            continue;
        }
        if is_forbidden_section_line(trimmed, "type") {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_HIGH_LEVEL_TYPE_FORBIDDEN_001",
                "type: is forbidden in [@machine]; use machine layout/object declarations",
            ));
            continue;
        }
        if trimmed.starts_with("use nC.runtime") {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_FORBIDDEN_RUNTIME_001",
                "direct runtime imports are forbidden in [@machine]",
            ));
            continue;
        }
        if let Some(section) = machine_section(trimmed) {
            flush_machine_relocation_record(&mut audit, &mut current_reloc);
            audit.sections.insert(section.clone());
            in_instr = section == "instr";
            in_target = section == "target";
            in_reloc = section == "reloc";
            symbol_section = section == "symbol";
            extern_section = section == "extern";
            proc_section = section == "proc" || section == "routine";
            label_section = section == "label" || section == "block";
            debug_section = section == "debug";
            cfi_section = section == "cfi";
            frame_section = section == "frame";
            stack_section = section == "stack";
            current_section = Some(section);
            continue;
        }

        if in_target {
            if let Some((key, value)) = parse_key_value(trimmed) {
                audit.target.insert(key, value);
            }
            continue;
        }

        if current_section.as_deref() == Some("entry") {
            if let Some(entry) = parse_scalar(trimmed) {
                audit.entry = Some(entry);
            }
            continue;
        }

        if symbol_section {
            if let Some(name) = parse_nested_label(trimmed) {
                audit.symbols.insert(name);
            }
            continue;
        }
        if extern_section {
            if let Some(name) = parse_nested_label(trimmed) {
                audit.externs.insert(name);
            }
            continue;
        }
        if proc_section {
            if let Some(name) = parse_nested_label(trimmed) {
                audit.routines.insert(name.clone());
                audit.symbols.insert(name);
            }
            continue;
        }
        if label_section {
            if let Some(name) = parse_nested_label(trimmed) {
                audit.labels.insert(name);
            }
            continue;
        }
        if in_reloc {
            if let Some(name) = parse_nested_label(trimmed) {
                flush_machine_relocation_record(&mut audit, &mut current_reloc);
                current_reloc = Some(MachineRelocationRecord::new(name));
                continue;
            }
            if let Some((key, value)) = parse_key_value(trimmed) {
                let fallback = format!("reloc_{}", audit.relocation_records.len());
                let record =
                    current_reloc.get_or_insert_with(|| MachineRelocationRecord::new(fallback));
                match key.as_str() {
                    "type" => {
                        record.kind = value.clone();
                        audit.relocations.push(trimmed.to_string());
                    }
                    "symbol" => record.symbol = Some(value),
                    "section" => record.section = value,
                    "offset" => {
                        record.offset = parse_int(&value).and_then(|raw| raw.try_into().ok())
                    }
                    "addend" => record.addend = parse_i32(&value).unwrap_or(0),
                    _ => {}
                }
            }
            continue;
        }
        if debug_section {
            if let Some((key, value)) = parse_key_value(trimmed) {
                audit.debug.insert(key, value);
            }
            continue;
        }
        if cfi_section {
            audit.cfi.push(trimmed.trim_end_matches(';').to_string());
            continue;
        }
        if frame_section {
            audit.frame.push(trimmed.trim_end_matches(';').to_string());
            continue;
        }
        if stack_section {
            audit.stack.push(trimmed.trim_end_matches(';').to_string());
            continue;
        }

        if in_instr {
            if let Some(inst) = parse_instruction(trimmed) {
                if inst.mnemonic == "label" {
                    if let Some(name) = inst.operands.first() {
                        audit.labels.insert(name.clone());
                    }
                }
                audit.instructions.push(inst);
            }
        }
    }
    flush_machine_relocation_record(&mut audit, &mut current_reloc);
    audit
}

fn flush_machine_relocation_record(
    audit: &mut MachineAudit,
    current: &mut Option<MachineRelocationRecord>,
) {
    let Some(record) = current.take() else {
        return;
    };
    if !record.kind.is_empty() {
        audit.relocation_records.push(record);
    }
}

fn detect_machine_container(source: &str) -> Option<String> {
    if let Some(container) = detect_canonical_machine_container(source) {
        return Some(container);
    }
    source.lines().find_map(|line| {
        let trimmed = strip_comment(line).trim();
        let idx = trimmed.find("[@machine]")?;
        let name = trimmed[..idx].trim();
        (!name.is_empty() && trimmed[idx..].contains('{')).then(|| name.to_string())
    })
}

fn detect_canonical_machine_container(source: &str) -> Option<String> {
    source.lines().find_map(|line| {
        let trimmed = strip_comment(line).trim();
        let header = trimmed.strip_suffix('{')?.trim();
        let (name, role) = header.split_once("::")?;
        let name = name.trim();
        (role.trim().eq_ignore_ascii_case("machine") && !name.is_empty()).then(|| name.to_string())
    })
}

fn machine_section(trimmed: &str) -> Option<String> {
    if !trimmed.ends_with(':') {
        return None;
    }
    let label = trimmed.trim_end_matches(':').trim();
    let allowed = [
        "target",
        "abi",
        "section",
        "symbol",
        "extern",
        "export",
        "entry",
        "proc",
        "routine",
        "block",
        "label",
        "instr",
        "frame",
        "stack",
        "debug",
        "cfi",
        "reloc",
        "verify",
        "emit",
        "seal",
        "macro",
        "data",
        "bss",
        "align",
        "org",
        "equ",
        "set",
        "include",
        "incbin",
        "if-target",
        "if-arch",
        "if-feature",
        "if-abi",
        "if-profile",
        "if-defined",
        "times",
        "repeat",
    ];
    allowed.contains(&label).then(|| label.to_string())
}

fn is_forbidden_section_line(trimmed: &str, section: &str) -> bool {
    trimmed == format!("{}:", section)
}

fn parse_key_value(line: &str) -> Option<(String, String)> {
    let (key, value) = line.split_once(':')?;
    let key = key.trim();
    if key.is_empty() || key.contains(char::is_whitespace) {
        return None;
    }
    Some((
        key.to_string(),
        value
            .trim()
            .trim_end_matches(';')
            .trim()
            .trim_matches('"')
            .to_string(),
    ))
}

fn parse_nested_label(line: &str) -> Option<String> {
    if !line.ends_with(':') {
        return None;
    }
    let label = line.trim_end_matches(':').trim();
    if label.is_empty()
        || machine_section(line).is_some()
        || label.contains(char::is_whitespace)
        || label.starts_with('.')
    {
        None
    } else {
        Some(label.to_string())
    }
}

fn parse_scalar(line: &str) -> Option<String> {
    let value = line.trim().trim_end_matches(';').trim();
    (!value.is_empty()).then(|| value.to_string())
}

fn parse_instruction(line: &str) -> Option<MachineInstruction> {
    let text = line.trim().trim_end_matches(';').trim();
    if text.is_empty() {
        return None;
    }
    let mut split = text.splitn(2, char::is_whitespace);
    let mnemonic = split.next()?.trim().to_ascii_lowercase();
    let rest = split.next().unwrap_or("").trim();
    let operands = if rest.is_empty() {
        Vec::new()
    } else {
        rest.split(',')
            .map(|op| op.trim().to_string())
            .filter(|op| !op.is_empty())
            .collect()
    };
    Some(MachineInstruction {
        mnemonic,
        operands,
        text: text.to_string(),
    })
}

const PHASE10_RECURSION_LIMIT: usize = 16;
const PHASE10_REPEAT_LIMIT: usize = 1024;
const PHASE10_INCLUDE_DEPTH_LIMIT: usize = 8;
const PHASE10_INCBIN_SIZE_LIMIT: usize = 4096;
const ASM_DIALECT_DUP_EXPANSION_LIMIT: usize = 4096;
const ASM_DIALECT_DUP_NESTING_LIMIT: usize = 8;
const ASM_DIALECT_FASM_REPEAT_LIMIT: usize = 1024;
const ASM_DIALECT_FASM_REPEAT_NESTING_LIMIT: usize = 8;
const ASM_DIALECT_FASM_MACRO_RECURSION_LIMIT: usize = 16;

fn apply_phase10_macro_directive_system(path: &str, source: &str, audit: &mut MachineAudit) {
    collect_phase10_macros(source, audit);
    collect_phase10_directives(path, source, audit);
    collect_phase10_conditionals_and_repeats(source, audit);
    expand_phase10_macro_invocations(audit);
    resolve_phase10_constants_in_instructions(audit);
}

fn collect_phase10_macros(source: &str, audit: &mut MachineAudit) {
    let mut in_macro_section = false;
    let mut current: Option<MachineMacroDef> = None;
    let mut in_emit = false;
    let mut in_local = false;

    for raw in source.lines() {
        let trimmed = strip_comment(raw).trim();
        if trimmed.is_empty() || trimmed == "{" || trimmed == "}" {
            continue;
        }
        if trimmed == "macro:" {
            if let Some(def) = current.take() {
                audit.macros.push(def);
            }
            in_macro_section = true;
            in_emit = false;
            in_local = false;
            audit.sections.insert("macro".to_string());
            continue;
        }
        if in_macro_section && is_phase10_top_level_section(trimmed) && trimmed != "emit:" {
            if let Some(def) = current.take() {
                audit.macros.push(def);
            }
            in_macro_section = false;
            in_emit = false;
            in_local = false;
        }
        if !in_macro_section {
            continue;
        }
        if trimmed == "emit:" {
            in_emit = true;
            in_local = false;
            continue;
        }
        if trimmed == "local:" {
            in_local = true;
            in_emit = false;
            continue;
        }
        if let Some(name) = parse_nested_label(trimmed) {
            if matches!(name.as_str(), "emit" | "local") {
                in_emit = name == "emit";
                in_local = name == "local";
                continue;
            }
            if let Some(def) = current.take() {
                audit.macros.push(def);
            }
            current = Some(MachineMacroDef {
                name,
                params: Vec::new(),
                body: Vec::new(),
                local_labels: Vec::new(),
                hygienic: true,
            });
            in_emit = false;
            in_local = false;
            continue;
        }
        if let Some(def) = current.as_mut() {
            if let Some((key, value)) = parse_key_value(trimmed) {
                match key.as_str() {
                    "params" => def.params = parse_phase10_macro_params(&value),
                    "variadic" => {
                        let mut parsed = parse_phase10_macro_params(&format!("[{}]", value));
                        for param in &mut parsed {
                            param.variadic = true;
                        }
                        def.params.extend(parsed);
                    }
                    "hygiene" => def.hygienic = value != "disabled",
                    _ => {}
                }
                continue;
            }
            if trimmed == "emit:" {
                in_emit = true;
                in_local = false;
                continue;
            }
            if trimmed == "local:" {
                in_local = true;
                in_emit = false;
                continue;
            }
            if in_local {
                let label = trimmed.trim_end_matches(';').trim().trim_end_matches(':');
                if !label.is_empty() {
                    def.local_labels.push(label.to_string());
                }
                continue;
            }
            if in_emit {
                def.body.push(trimmed.trim_end_matches(';').to_string());
            }
        }
    }
    if let Some(def) = current {
        audit.macros.push(def);
    }
    let mut seen = BTreeSet::new();
    for def in &audit.macros {
        if !seen.insert(def.name.clone()) {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_MACRO_DECL_001",
                format!("macro '{}' is declared more than once", def.name),
            ));
        }
    }
}

fn parse_phase10_macro_params(raw: &str) -> Vec<MachineMacroParam> {
    let inner = raw
        .trim()
        .trim_start_matches('[')
        .trim_end_matches(']')
        .trim_end_matches(';')
        .trim();
    if inner.is_empty() {
        return Vec::new();
    }
    inner
        .split(',')
        .filter_map(|part| {
            let mut item = part.trim();
            if item.is_empty() {
                return None;
            }
            let variadic = item.starts_with("...");
            if variadic {
                item = item.trim_start_matches("...").trim();
            }
            let (name, rest) = item
                .split_once(':')
                .unwrap_or((item, "any_machine_operand"));
            let (ty, default_value) = rest
                .split_once('=')
                .map(|(ty, default)| (ty.trim(), Some(default.trim().to_string())))
                .unwrap_or((rest.trim(), None));
            Some(MachineMacroParam {
                name: name.trim().to_string(),
                ty: ty.to_string(),
                default_value,
                variadic,
            })
        })
        .collect()
}

fn collect_phase10_directives(path: &str, source: &str, audit: &mut MachineAudit) {
    let mut current_section = String::new();
    let mut current_label = String::new();
    let mut include_stack = Vec::new();
    let mut incbin_label = String::new();
    let mut incbin_path = String::new();
    let mut incbin_align = 1usize;

    for raw in source.lines() {
        let trimmed = strip_comment(raw).trim();
        if trimmed.is_empty() || trimmed == "{" || trimmed == "}" {
            continue;
        }
        if is_phase10_top_level_section(trimmed) {
            flush_phase10_incbin(path, audit, &incbin_label, &incbin_path, incbin_align);
            incbin_label.clear();
            incbin_path.clear();
            incbin_align = 1;
            current_section = trimmed.trim_end_matches(':').to_string();
            current_label.clear();
            if is_phase10_directive_section(&current_section) {
                audit.sections.insert(current_section.clone());
            }
            continue;
        }
        match current_section.as_str() {
            "data" => {
                if let Some(label) = parse_nested_label(trimmed) {
                    current_label = label.clone();
                    audit.symbols.insert(label);
                    continue;
                }
                parse_phase10_data_directive(trimmed, &current_label, audit);
            }
            "bss" => {
                if let Some(label) = parse_nested_label(trimmed) {
                    current_label = label.clone();
                    audit.symbols.insert(label);
                    continue;
                }
                parse_phase10_reserve_directive(trimmed, &current_label, audit);
            }
            "align" => parse_phase10_align_directive(trimmed, audit),
            "org" => parse_phase10_org_directive(trimmed, audit),
            "equ" => parse_phase10_constant_directive(trimmed, "equ", audit),
            "set" => parse_phase10_constant_directive(trimmed, "set", audit),
            "include" => parse_phase10_include_directive(path, trimmed, audit, &mut include_stack),
            "incbin" => {
                if let Some((key, value)) = parse_key_value(trimmed) {
                    match key.as_str() {
                        "label" => incbin_label = value,
                        "path" => incbin_path = value,
                        "align" => incbin_align = parse_int(&value).unwrap_or(1).max(1) as usize,
                        _ => {}
                    }
                }
            }
            _ => {}
        }
    }
    flush_phase10_incbin(path, audit, &incbin_label, &incbin_path, incbin_align);
}

fn collect_phase10_conditionals_and_repeats(source: &str, audit: &mut MachineAudit) {
    let mut current_section = String::new();
    let mut condition_kind = String::new();
    let mut branch_active = false;
    let mut branch_emit = false;
    let mut repeat_count: Option<usize> = None;
    let mut repeat_body: Vec<String> = Vec::new();
    let mut repeat_emit = false;

    for raw in source.lines() {
        let trimmed = strip_comment(raw).trim();
        if trimmed.is_empty() || trimmed == "{" || trimmed == "}" {
            continue;
        }
        if is_phase10_top_level_section(trimmed) {
            flush_phase10_repeat(audit, repeat_count.take(), &mut repeat_body);
            repeat_emit = false;
            current_section = trimmed.trim_end_matches(':').to_string();
            condition_kind = current_section.clone();
            branch_active = false;
            branch_emit = false;
            continue;
        }
        if matches!(
            current_section.as_str(),
            "if-target" | "if-arch" | "if-feature" | "if-abi" | "if-profile" | "if-defined"
        ) {
            if let Some(condition) = parse_nested_label(trimmed) {
                branch_active = evaluate_phase10_condition(&condition_kind, &condition, audit);
                let status = if phase10_condition_known(&condition_kind, &condition) {
                    "closed"
                } else {
                    audit.diagnostics.push(MachineDiagnostic::new(
                        "E_MACHINE_COND_ASM_001",
                        format!("unknown conditional assembly branch '{}'", condition),
                    ));
                    "failed"
                };
                audit.conditionals.push(MachineConditionalRecord {
                    kind: condition_kind.clone(),
                    condition,
                    included: branch_active,
                    status: status.to_string(),
                });
                branch_emit = false;
                continue;
            }
            if trimmed == "emit:" {
                branch_emit = true;
                continue;
            }
            if branch_active && branch_emit {
                if let Some(inst) = parse_instruction(trimmed) {
                    audit.instructions.push(inst);
                }
            }
            continue;
        }
        if matches!(current_section.as_str(), "times" | "repeat") {
            if trimmed == "emit:" {
                repeat_emit = true;
                continue;
            }
            if let Some((key, value)) = parse_key_value(trimmed) {
                if key == "count" {
                    repeat_count = parse_phase10_usize_expr(&value, audit);
                }
                continue;
            }
            if repeat_emit {
                repeat_body.push(trimmed.trim_end_matches(';').to_string());
            }
        }
    }
    flush_phase10_repeat(audit, repeat_count, &mut repeat_body);
}

fn expand_phase10_macro_invocations(audit: &mut MachineAudit) {
    let macros = audit
        .macros
        .iter()
        .cloned()
        .map(|def| (def.name.clone(), def))
        .collect::<BTreeMap<_, _>>();
    let mut output = Vec::new();
    let mut invocation_index = 0usize;
    let original = audit.instructions.clone();
    for inst in original {
        if inst.mnemonic != "macro" {
            output.push(inst);
            continue;
        }
        invocation_index += 1;
        let Some((name, args)) = parse_phase10_macro_invocation(&inst.text) else {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_MACRO_EXPANSION_001",
                format!("invalid macro invocation '{}'", inst.text),
            ));
            continue;
        };
        let Some(def) = macros.get(&name).cloned() else {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_MACRO_DECL_001",
                format!("unknown macro '{}'", name),
            ));
            continue;
        };
        audit.macro_invocations.push(MachineMacroInvocation {
            name: name.clone(),
            args: args.clone(),
            status: "parsed".to_string(),
        });
        if def.body.iter().any(|line| {
            parse_phase10_macro_invocation(line)
                .map(|(inner, _)| inner == def.name)
                .unwrap_or(false)
        }) {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_MACRO_RECURSION_001",
                format!(
                    "macro '{}' exceeds recursion policy limit {}",
                    def.name, PHASE10_RECURSION_LIMIT
                ),
            ));
            continue;
        }
        let Some(bindings) = bind_phase10_macro_args(&def, &args, audit) else {
            continue;
        };
        let mut label_map = BTreeMap::new();
        if def.hygienic {
            for label in &def.local_labels {
                label_map.insert(
                    label.clone(),
                    format!("{}$macro${}", label, invocation_index),
                );
            }
        }
        let mut emitted = Vec::new();
        for line in &def.body {
            let lines = expand_phase10_macro_body_line(line, &def, &bindings, &label_map);
            for expanded_line in lines {
                if let Some(mut expanded) = parse_instruction(&expanded_line) {
                    if expanded.mnemonic == "label" {
                        if let Some(label) = expanded.operands.first() {
                            if !def.hygienic && audit.labels.contains(label) {
                                audit.diagnostics.push(MachineDiagnostic::new(
                                    "E_MACHINE_MACRO_LABEL_COLLISION_001",
                                    format!("macro local label '{}' collides", label),
                                ));
                            }
                            audit.labels.insert(label.clone());
                        }
                    }
                    for operand in &mut expanded.operands {
                        if is_phase10_memory_like_operand(operand) {
                            continue;
                        }
                        let constants = audit.constants.clone();
                        let should_eval = constants.contains_key(operand.trim())
                            || phase10_expr_has_operator(operand)
                            || parse_int(operand.trim()).is_some();
                        if should_eval {
                            if let Ok(value) = eval_phase10_ctfe(operand, &constants, audit) {
                                *operand = value.to_string();
                            }
                        }
                    }
                    emitted.push(expanded.text.clone());
                    output.push(expanded);
                }
            }
        }
        audit.macro_expansions.push(MachineMacroExpansion {
            macro_name: def.name,
            invocation_index,
            emitted_instructions: emitted,
            label_map,
            status: "closed".to_string(),
        });
    }
    audit.instructions = output;
}

fn resolve_phase10_constants_in_instructions(audit: &mut MachineAudit) {
    let constants = audit.constants.clone();
    let mut diagnostics = Vec::new();
    for inst in &mut audit.instructions {
        let mut changed = false;
        for operand in &mut inst.operands {
            if is_phase10_memory_like_operand(operand) {
                continue;
            }
            if constants.contains_key(operand.trim()) || phase10_expr_has_operator(operand) {
                match eval_phase10_ctfe_with_diag(operand, &constants) {
                    Ok(value) => {
                        *operand = value.to_string();
                        changed = true;
                    }
                    Err(diag) => diagnostics.push(diag),
                }
            }
        }
        if changed {
            inst.text = if inst.operands.is_empty() {
                inst.mnemonic.clone()
            } else {
                format!("{} {}", inst.mnemonic, inst.operands.join(", "))
            };
        }
    }
    audit.diagnostics.extend(diagnostics);
}

fn is_phase10_top_level_section(trimmed: &str) -> bool {
    matches!(
        trimmed,
        "target:"
            | "abi:"
            | "section:"
            | "symbol:"
            | "extern:"
            | "export:"
            | "entry:"
            | "proc:"
            | "routine:"
            | "block:"
            | "label:"
            | "instr:"
            | "frame:"
            | "stack:"
            | "debug:"
            | "cfi:"
            | "reloc:"
            | "verify:"
            | "seal:"
            | "macro:"
            | "data:"
            | "bss:"
            | "align:"
            | "org:"
            | "equ:"
            | "set:"
            | "include:"
            | "incbin:"
            | "if-target:"
            | "if-arch:"
            | "if-feature:"
            | "if-abi:"
            | "if-profile:"
            | "if-defined:"
            | "times:"
            | "repeat:"
    )
}

fn is_phase10_directive_section(section: &str) -> bool {
    matches!(
        section,
        "data" | "bss" | "align" | "org" | "equ" | "set" | "include" | "incbin"
    )
}

fn parse_phase10_data_directive(line: &str, label: &str, audit: &mut MachineAudit) {
    let Some((kind, rest)) = line.trim_end_matches(';').split_once(char::is_whitespace) else {
        return;
    };
    let kind = kind.to_ascii_lowercase();
    let mut emitted = Vec::new();
    match kind.as_str() {
        "db" => parse_phase10_int_list(rest, 1, audit, &mut emitted),
        "dw" => parse_phase10_int_list(rest, 2, audit, &mut emitted),
        "dd" => parse_phase10_int_list(rest, 4, audit, &mut emitted),
        "dq" => parse_phase10_int_list(rest, 8, audit, &mut emitted),
        "ascii" | "asciz" => {
            match parse_machine_byte_string(rest) {
                Ok(bytes) => emitted.extend(bytes),
                Err(diagnostic) => {
                    audit.diagnostics.push(diagnostic);
                    return;
                }
            }
            if kind == "asciz" {
                emitted.push(0);
            }
        }
        _ => return,
    }
    audit.data_bytes.extend_from_slice(&emitted);
    audit.directives.push(MachineDirectiveRecord {
        kind,
        name: label.to_string(),
        value: rest.trim().to_string(),
        status: "closed".to_string(),
        evidence_hash: hash_bytes(&emitted),
    });
}

fn parse_phase10_reserve_directive(line: &str, label: &str, audit: &mut MachineAudit) {
    let Some((kind, rest)) = line.trim_end_matches(';').split_once(char::is_whitespace) else {
        return;
    };
    let unit = match kind.to_ascii_lowercase().as_str() {
        "resb" => 1,
        "resw" => 2,
        "resd" => 4,
        "resq" => 8,
        _ => return,
    };
    if let Some(count) = parse_phase10_usize_expr(rest, audit) {
        let bytes = count.saturating_mul(unit);
        audit.bss_size = audit.bss_size.saturating_add(bytes);
        audit.directives.push(MachineDirectiveRecord {
            kind: kind.to_ascii_lowercase(),
            name: label.to_string(),
            value: bytes.to_string(),
            status: "closed_bss".to_string(),
            evidence_hash: hash_string(&format!("{}:{}:{}", kind, label, bytes)),
        });
    }
}

fn parse_phase10_align_directive(line: &str, audit: &mut MachineAudit) {
    let value = if let Some((key, value)) = parse_key_value(line) {
        if key != "value" {
            return;
        }
        value
    } else {
        line.trim_end_matches(';').to_string()
    };
    let Some(align) = parse_phase10_usize_expr(&value, audit) else {
        return;
    };
    if align == 0 || !align.is_power_of_two() {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_ALIGN_001",
            "align value must be a non-zero power of two",
        ));
        return;
    }
    let padding = (align - (audit.data_bytes.len() % align)) % align;
    audit.data_bytes.extend(std::iter::repeat_n(0u8, padding));
    audit.directives.push(MachineDirectiveRecord {
        kind: "align".to_string(),
        name: ".data".to_string(),
        value: align.to_string(),
        status: "closed".to_string(),
        evidence_hash: hash_string(&format!("align:{align}:{padding}")),
    });
}

fn parse_phase10_org_directive(line: &str, audit: &mut MachineAudit) {
    let value = line.trim_end_matches(';');
    let profile = audit
        .target
        .get("profile")
        .map(String::as_str)
        .unwrap_or("userland");
    if !matches!(
        profile,
        "raw" | "flat" | "firmware" | "baremetal" | "kernel"
    ) {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_ORG_FORBIDDEN_001",
            "org is only allowed in raw/flat/baremetal/firmware profiles",
        ));
        return;
    }
    if let Some(origin) = parse_phase10_usize_expr(value, audit) {
        audit.directives.push(MachineDirectiveRecord {
            kind: "org".to_string(),
            name: "origin".to_string(),
            value: format!("0x{origin:x}"),
            status: "closed_profile_allowed".to_string(),
            evidence_hash: hash_string(&format!("org:{origin}")),
        });
    }
}

fn parse_phase10_constant_directive(line: &str, kind: &str, audit: &mut MachineAudit) {
    let Some((name, expr)) = parse_key_value(line) else {
        return;
    };
    if kind == "equ" && audit.constants.contains_key(&name) {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_EQU_REDEFINED_001",
            format!("equ constant '{}' is already defined", name),
        ));
        return;
    }
    let constants = audit.constants.clone();
    if let Ok(value) = eval_phase10_ctfe(&expr, &constants, audit) {
        audit.constants.insert(name.clone(), value);
        audit.symbols.insert(name.clone());
        audit.directives.push(MachineDirectiveRecord {
            kind: kind.to_string(),
            name,
            value: value.to_string(),
            status: "closed".to_string(),
            evidence_hash: hash_string(&format!("{}:{}", kind, value)),
        });
    }
}

fn parse_phase10_include_directive(
    root_path: &str,
    line: &str,
    audit: &mut MachineAudit,
    include_stack: &mut Vec<String>,
) {
    let Some(include_path) = parse_quoted(line) else {
        return;
    };
    let Some(resolved) = resolve_phase10_relative_path(root_path, &include_path) else {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_INCLUDE_001",
            "include path is outside the allowed workspace-relative policy",
        ));
        return;
    };
    process_phase10_include(&resolved, 0, audit, include_stack);
}

fn process_phase10_include(
    path: &str,
    depth: usize,
    audit: &mut MachineAudit,
    include_stack: &mut Vec<String>,
) {
    if depth > PHASE10_INCLUDE_DEPTH_LIMIT {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_INCLUDE_DEPTH_001",
            "include depth limit exceeded",
        ));
        return;
    }
    if include_stack.iter().any(|seen| seen == path) {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_INCLUDE_CYCLE_001",
            format!("include cycle detected at '{}'", path),
        ));
        return;
    }
    let Ok(source) = fs::read_to_string(path) else {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_INCLUDE_NOT_FOUND_001",
            format!("include file '{}' was not found", path),
        ));
        return;
    };
    audit.includes.push(MachineIncludeRecord {
        path: path.to_string(),
        depth,
        status: "closed".to_string(),
    });
    include_stack.push(path.to_string());
    let mut current = String::new();
    for raw in source.lines() {
        let trimmed = strip_comment(raw).trim();
        if trimmed.is_empty() {
            continue;
        }
        if matches!(trimmed, "equ:" | "set:" | "include:") {
            current = trimmed.trim_end_matches(':').to_string();
            continue;
        }
        match current.as_str() {
            "equ" => parse_phase10_constant_directive(trimmed, "equ", audit),
            "set" => parse_phase10_constant_directive(trimmed, "set", audit),
            "include" => {
                if let Some(child) = parse_quoted(trimmed) {
                    if let Some(resolved) = resolve_phase10_relative_path(path, &child) {
                        process_phase10_include(&resolved, depth + 1, audit, include_stack);
                    }
                }
            }
            _ => {}
        }
    }
    include_stack.pop();
}

fn flush_phase10_incbin(
    root_path: &str,
    audit: &mut MachineAudit,
    label: &str,
    incbin_path: &str,
    align: usize,
) {
    if label.is_empty() && incbin_path.is_empty() {
        return;
    }
    if incbin_path.is_empty() {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_INCBIN_001",
            "incbin requires a path",
        ));
        return;
    }
    if incbin_path.contains("..") || Path::new(incbin_path).is_absolute() {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_INCBIN_FORBIDDEN_PATH_001",
            "incbin path violates the workspace-relative policy",
        ));
        return;
    }
    let Some(resolved) = resolve_phase10_relative_path(root_path, incbin_path) else {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_INCBIN_FORBIDDEN_PATH_001",
            "incbin path could not be resolved under the workspace",
        ));
        return;
    };
    let Ok(bytes) = fs::read(&resolved) else {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_INCBIN_NOT_FOUND_001",
            format!("incbin file '{}' was not found", incbin_path),
        ));
        return;
    };
    if bytes.len() > PHASE10_INCBIN_SIZE_LIMIT {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_INCBIN_TOO_LARGE_001",
            format!(
                "incbin file '{}' exceeds {} bytes",
                incbin_path, PHASE10_INCBIN_SIZE_LIMIT
            ),
        ));
        return;
    }
    let padding = (align - (audit.data_bytes.len() % align)) % align;
    audit.data_bytes.extend(std::iter::repeat_n(0u8, padding));
    audit.data_bytes.extend_from_slice(&bytes);
    let hash = hash_bytes(&bytes);
    audit.symbols.insert(label.to_string());
    audit.incbins.push(MachineIncbinRecord {
        label: label.to_string(),
        path: incbin_path.to_string(),
        bytes: bytes.len(),
        align,
        hash: hash.clone(),
        status: "closed".to_string(),
    });
    audit.directives.push(MachineDirectiveRecord {
        kind: "incbin".to_string(),
        name: label.to_string(),
        value: incbin_path.to_string(),
        status: "closed".to_string(),
        evidence_hash: hash,
    });
}

fn flush_phase10_repeat(
    audit: &mut MachineAudit,
    repeat_count: Option<usize>,
    repeat_body: &mut Vec<String>,
) {
    let Some(count) = repeat_count else {
        repeat_body.clear();
        return;
    };
    if count > PHASE10_REPEAT_LIMIT {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_REPEAT_LIMIT_001",
            format!(
                "repeat/times count {} exceeds limit {}",
                count, PHASE10_REPEAT_LIMIT
            ),
        ));
        repeat_body.clear();
        return;
    }
    let mut emitted = 0usize;
    for _ in 0..count {
        for line in repeat_body.iter() {
            if let Some(inst) = parse_instruction(line) {
                audit.instructions.push(inst);
                emitted += 1;
            }
        }
    }
    audit.repeats.push(MachineRepeatRecord {
        kind: "times_or_repeat".to_string(),
        count,
        emitted,
        status: "closed".to_string(),
    });
    repeat_body.clear();
}

fn parse_phase10_int_list(rest: &str, width: usize, audit: &mut MachineAudit, out: &mut Vec<u8>) {
    for item in rest.split(',') {
        let expr = item.trim();
        if expr.is_empty() {
            continue;
        }
        let Ok(value) = eval_phase10_ctfe(expr, &audit.constants.clone(), audit) else {
            continue;
        };
        let max = match width {
            1 => 0xff_i128,
            2 => 0xffff_i128,
            4 => 0xffff_ffff_i128,
            _ => i128::from(u64::MAX),
        };
        if value < 0 || value > max {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_DATA_OVERFLOW_001",
                format!("data value {} does not fit {} bytes", value, width),
            ));
            continue;
        }
        append_phase10_int(out, value as u128, width, audit_endian(audit));
    }
}

fn append_phase10_int(out: &mut Vec<u8>, value: u128, width: usize, endian: &str) {
    let bytes = value.to_le_bytes();
    if endian == "big" {
        out.extend(bytes[..width].iter().rev().copied());
    } else {
        out.extend_from_slice(&bytes[..width]);
    }
}

fn parse_phase10_usize_expr(expr: &str, audit: &mut MachineAudit) -> Option<usize> {
    match eval_phase10_ctfe(expr, &audit.constants.clone(), audit) {
        Ok(value) if value >= 0 => Some(value as usize),
        Ok(_) => {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_CTFE_001",
                "compile-time expression must be non-negative",
            ));
            None
        }
        Err(_) => None,
    }
}

fn parse_phase10_macro_invocation(text: &str) -> Option<(String, Vec<String>)> {
    let rest = text
        .trim()
        .trim_end_matches(';')
        .strip_prefix("macro")?
        .trim();
    let mut parts = rest.splitn(2, char::is_whitespace);
    let name = parts.next()?.trim().to_string();
    if name.is_empty() {
        return None;
    }
    let args_text = parts.next().unwrap_or("").trim();
    let args = if args_text.is_empty() {
        Vec::new()
    } else if args_text.contains(',') {
        args_text
            .split(',')
            .map(|arg| arg.trim().to_string())
            .filter(|arg| !arg.is_empty())
            .collect()
    } else {
        args_text
            .split_whitespace()
            .map(|arg| arg.trim().to_string())
            .filter(|arg| !arg.is_empty())
            .collect()
    };
    Some((name, args))
}

fn bind_phase10_macro_args(
    def: &MachineMacroDef,
    args: &[String],
    audit: &mut MachineAudit,
) -> Option<BTreeMap<String, Vec<String>>> {
    let required = def
        .params
        .iter()
        .filter(|param| param.default_value.is_none() && !param.variadic)
        .count();
    let variadic = def.params.iter().position(|param| param.variadic);
    if args.len() < required || (variadic.is_none() && args.len() > def.params.len()) {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_MACRO_ARG_001",
            format!("macro '{}' received wrong argument count", def.name),
        ));
        return None;
    }
    let mut bindings = BTreeMap::new();
    let mut arg_index = 0usize;
    for (param_index, param) in def.params.iter().enumerate() {
        if param.variadic {
            let remaining = args[arg_index..].to_vec();
            if remaining.is_empty() {
                audit.diagnostics.push(MachineDiagnostic::new(
                    "E_MACHINE_MACRO_VARIADIC_001",
                    format!(
                        "variadic macro parameter '{}' requires at least one value",
                        param.name
                    ),
                ));
                return None;
            }
            for arg in &remaining {
                if !phase10_arg_matches_type(&param.ty, arg, audit) {
                    audit.diagnostics.push(MachineDiagnostic::new(
                        "E_MACHINE_MACRO_PARAM_001",
                        format!("macro parameter '{}' expects {}", param.name, param.ty),
                    ));
                    return None;
                }
            }
            bindings.insert(param.name.clone(), remaining);
            break;
        }
        let value = args
            .get(arg_index)
            .cloned()
            .or_else(|| param.default_value.clone());
        let Some(value) = value else {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_MACRO_ARG_001",
                format!("missing argument '{}' for macro '{}'", param.name, def.name),
            ));
            return None;
        };
        if !phase10_arg_matches_type(&param.ty, &value, audit) {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_MACRO_PARAM_001",
                format!(
                    "argument '{}' for macro '{}' does not match {}",
                    param_index + 1,
                    def.name,
                    param.ty
                ),
            ));
            return None;
        }
        bindings.insert(param.name.clone(), vec![value]);
        arg_index += 1;
    }
    Some(bindings)
}

fn phase10_arg_matches_type(ty: &str, arg: &str, audit: &mut MachineAudit) -> bool {
    match ty {
        "reg8" => x86_gpr(arg).map(|reg| reg.width == 8).unwrap_or(false),
        "reg16" => x86_gpr(arg).map(|reg| reg.width == 16).unwrap_or(false),
        "reg32" => x86_gpr(arg).map(|reg| reg.width == 32).unwrap_or(false),
        "reg64" => x86_gpr(arg).map(|reg| reg.width == 64).unwrap_or(false),
        "reg" => x86_gpr(arg).is_some(),
        "xmm" | "ymm" | "zmm" => arg.to_ascii_lowercase().starts_with(ty),
        "k" => x86_k_reg(arg).is_some(),
        "imm8" => eval_phase10_ctfe(arg, &audit.constants.clone(), audit)
            .map(|value| machine_immediate_fits_storage_bits(value, 8))
            .unwrap_or(false),
        "imm16" => eval_phase10_ctfe(arg, &audit.constants.clone(), audit)
            .map(|value| machine_immediate_fits_storage_bits(value, 16))
            .unwrap_or(false),
        "imm32" => eval_phase10_ctfe(arg, &audit.constants.clone(), audit)
            .map(|value| machine_immediate_fits_storage_bits(value, 32))
            .unwrap_or(false),
        "imm64" => eval_phase10_ctfe(arg, &audit.constants.clone(), audit)
            .map(|value| machine_immediate_fits_storage_bits(value, 64))
            .unwrap_or(false),
        "mem" => arg.contains('[') && arg.contains(']'),
        "label" | "symbol" | "section" | "any_machine_operand" => true,
        _ => true,
    }
}

fn expand_phase10_macro_body_line(
    line: &str,
    def: &MachineMacroDef,
    bindings: &BTreeMap<String, Vec<String>>,
    label_map: &BTreeMap<String, String>,
) -> Vec<String> {
    let variadic = def
        .params
        .iter()
        .find(|param| param.variadic && line.contains(&format!("@{}", param.name)));
    if let Some(param) = variadic {
        return bindings
            .get(&param.name)
            .into_iter()
            .flatten()
            .map(|arg| {
                let mut expanded = line.replace(&format!("@{}", param.name), arg);
                for (from, to) in label_map {
                    expanded = replace_phase10_label_token(&expanded, from, to);
                }
                expanded
            })
            .collect();
    }
    let mut expanded = line.to_string();
    for (name, values) in bindings {
        if let Some(value) = values.first() {
            expanded = expanded.replace(&format!("@{}", name), value);
        }
    }
    for (from, to) in label_map {
        expanded = replace_phase10_label_token(&expanded, from, to);
    }
    vec![expanded]
}

fn replace_phase10_label_token(line: &str, from: &str, to: &str) -> String {
    line.split_whitespace()
        .map(|token| {
            let suffix = if token.ends_with(';') { ";" } else { "" };
            let clean = token.trim_end_matches(';').trim_end_matches(',');
            if clean == from {
                format!("{}{}", to, suffix)
            } else {
                token.to_string()
            }
        })
        .collect::<Vec<_>>()
        .join(" ")
}

fn evaluate_phase10_condition(kind: &str, condition: &str, audit: &MachineAudit) -> bool {
    match kind {
        "if-target" | "if-arch" => audit_arch(audit) == condition,
        "if-feature" => machine_target_has_feature(audit, &condition.to_ascii_lowercase()),
        "if-abi" => audit.target.get("abi").map(String::as_str) == Some(condition),
        "if-profile" => audit.target.get("profile").map(String::as_str) == Some(condition),
        "if-defined" => {
            audit.constants.contains_key(condition) || audit.symbols.contains(condition)
        }
        _ => false,
    }
}

fn phase10_condition_known(kind: &str, condition: &str) -> bool {
    match kind {
        "if-target" | "if-arch" => matches!(condition, "x86_64" | "aarch64" | "riscv64" | "wasm32"),
        "if-feature" => !condition.trim().is_empty(),
        "if-abi" => matches!(condition, "sysv64" | "win64" | "aapcs64" | "riscv64"),
        "if-profile" => !condition.trim().is_empty(),
        "if-defined" => !condition.trim().is_empty(),
        _ => false,
    }
}

fn resolve_phase10_relative_path(root_path: &str, child: &str) -> Option<String> {
    if child.contains("..") || Path::new(child).is_absolute() {
        return None;
    }
    let root = Path::new(root_path)
        .parent()
        .unwrap_or_else(|| Path::new("."));
    let direct = Path::new(child);
    let workspace = Path::new(root_path)
        .ancestors()
        .find(|candidate| candidate.join("Cargo.toml").exists())
        .unwrap_or(root);
    let root_relative = root.join(child);
    let workspace_relative = workspace.join(child);
    let resolved = if direct.exists() {
        direct.to_path_buf()
    } else if root_relative.exists() {
        root_relative
    } else if let Some(stripped) = child.strip_prefix("examples/") {
        let archived = workspace
            .join("_archive")
            .join("old_examples")
            .join(stripped);
        if archived.exists() {
            archived
        } else {
            workspace_relative
        }
    } else {
        workspace_relative
    };
    Some(resolved.to_string_lossy().to_string())
}

fn parse_quoted(raw: &str) -> Option<String> {
    let start = raw.find('"')?;
    let end = raw[start + 1..].find('"')? + start + 1;
    Some(raw[start + 1..end].to_string())
}

fn parse_machine_byte_string(raw: &str) -> Result<Vec<u8>, MachineDiagnostic> {
    let Some(start) = raw.find('"') else {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_STRING_LITERAL_001",
            "machine byte string expects an opening quote",
        ));
    };
    let mut chars = raw[start + 1..].chars().peekable();
    let mut bytes = Vec::new();
    while let Some(ch) = chars.next() {
        match ch {
            '"' => return Ok(bytes),
            '\\' => {
                let Some(escape) = chars.next() else {
                    return Err(MachineDiagnostic::new(
                        "E_MACHINE_STRING_ESCAPE_001",
                        "unterminated escape in machine byte string",
                    ));
                };
                match escape {
                    'n' => bytes.push(b'\n'),
                    'r' => bytes.push(b'\r'),
                    't' => bytes.push(b'\t'),
                    '0' => bytes.push(0),
                    '\\' => bytes.push(b'\\'),
                    '"' => bytes.push(b'"'),
                    '\'' => bytes.push(b'\''),
                    '?' => bytes.push(b'?'),
                    '&' => bytes.push(b'&'),
                    '#' => bytes.push(b'#'),
                    'x' => {
                        let hi = chars.next().and_then(|digit| digit.to_digit(16));
                        let lo = chars.next().and_then(|digit| digit.to_digit(16));
                        let (Some(hi), Some(lo)) = (hi, lo) else {
                            return Err(MachineDiagnostic::new(
                                "E_MACHINE_STRING_ESCAPE_001",
                                "\\x escape expects exactly two hexadecimal digits",
                            ));
                        };
                        bytes.push(((hi << 4) | lo) as u8);
                    }
                    'u' => {
                        if chars.next() != Some('{') {
                            return Err(MachineDiagnostic::new(
                                "E_MACHINE_STRING_ESCAPE_001",
                                "Unicode escape expects \\u{HEX}",
                            ));
                        }
                        let mut digits = String::new();
                        loop {
                            match chars.next() {
                                Some('}') => break,
                                Some(digit) if digit.is_ascii_hexdigit() && digits.len() < 6 => {
                                    digits.push(digit)
                                }
                                _ => {
                                    return Err(MachineDiagnostic::new(
                                        "E_MACHINE_STRING_ESCAPE_001",
                                        "Unicode escape expects one to six hexadecimal digits",
                                    ))
                                }
                            }
                        }
                        let scalar = u32::from_str_radix(&digits, 16)
                            .ok()
                            .and_then(char::from_u32)
                            .ok_or_else(|| {
                                MachineDiagnostic::new(
                                    "E_MACHINE_STRING_ESCAPE_001",
                                    format!("invalid Unicode scalar U+{}", digits),
                                )
                            })?;
                        let mut encoded = [0_u8; 4];
                        bytes.extend_from_slice(scalar.encode_utf8(&mut encoded).as_bytes());
                    }
                    other => {
                        return Err(MachineDiagnostic::new(
                            "E_MACHINE_STRING_ESCAPE_001",
                            format!("unknown machine byte-string escape '\\{}'", other),
                        ))
                    }
                }
            }
            ordinary => {
                let mut encoded = [0_u8; 4];
                bytes.extend_from_slice(ordinary.encode_utf8(&mut encoded).as_bytes());
            }
        }
    }
    Err(MachineDiagnostic::new(
        "E_MACHINE_STRING_LITERAL_001",
        "machine byte string is missing its closing quote",
    ))
}

fn audit_endian(audit: &MachineAudit) -> &str {
    audit
        .target
        .get("endian")
        .map(String::as_str)
        .unwrap_or("little")
}

fn phase10_expr_has_operator(expr: &str) -> bool {
    expr.contains(['+', '*', '/', '%', '&', '|', '^', '~', '(', ')'])
        || expr.contains("<<")
        || expr.contains(">>")
}

fn is_phase10_memory_like_operand(operand: &str) -> bool {
    operand.contains('[')
        || operand.contains(']')
        || (operand.contains('(')
            && operand.contains(')')
            && operand.chars().any(|ch| ch.is_ascii_alphabetic()))
}

fn eval_phase10_ctfe(
    expr: &str,
    constants: &BTreeMap<String, i128>,
    audit: &mut MachineAudit,
) -> Result<i128, ()> {
    match eval_phase10_ctfe_with_diag(expr, constants) {
        Ok(value) => Ok(value),
        Err(diag) => {
            audit.diagnostics.push(diag);
            Err(())
        }
    }
}

fn eval_phase10_ctfe_with_diag(
    expr: &str,
    constants: &BTreeMap<String, i128>,
) -> Result<i128, MachineDiagnostic> {
    let tokens = tokenize_phase10_expr(expr);
    if tokens.is_empty() {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_CTFE_001",
            "empty compile-time expression",
        ));
    }
    let mut parser = Phase10ExprParser {
        tokens,
        pos: 0,
        constants,
    };
    let value = parser.parse_expr(0)?;
    if parser.pos != parser.tokens.len() {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_CTFE_001",
            format!("unsupported compile-time expression '{}'", expr),
        ));
    }
    if value < i128::from(i64::MIN) || value > i128::from(u64::MAX) {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_CTFE_OVERFLOW_001",
            format!(
                "compile-time expression '{}' overflows machine integer policy",
                expr
            ),
        ));
    }
    Ok(value)
}

struct Phase10ExprParser<'a> {
    tokens: Vec<String>,
    pos: usize,
    constants: &'a BTreeMap<String, i128>,
}

impl<'a> Phase10ExprParser<'a> {
    fn parse_expr(&mut self, min_prec: u8) -> Result<i128, MachineDiagnostic> {
        let mut lhs = self.parse_unary()?;
        while let Some(op) = self.tokens.get(self.pos).cloned() {
            let Some((prec, right_assoc)) = phase10_precedence(&op) else {
                break;
            };
            if prec < min_prec {
                break;
            }
            self.pos += 1;
            let rhs = self.parse_expr(if right_assoc { prec } else { prec + 1 })?;
            lhs = apply_phase10_binary_op(&op, lhs, rhs)?;
        }
        Ok(lhs)
    }

    fn parse_unary(&mut self) -> Result<i128, MachineDiagnostic> {
        if let Some(op) = self.tokens.get(self.pos).cloned() {
            if op == "-" || op == "~" {
                self.pos += 1;
                let value = self.parse_unary()?;
                return Ok(if op == "-" { -value } else { !value });
            }
        }
        self.parse_primary()
    }

    fn parse_primary(&mut self) -> Result<i128, MachineDiagnostic> {
        let Some(token) = self.tokens.get(self.pos).cloned() else {
            return Err(MachineDiagnostic::registered(
                "E_MACHINE_CTFE_001",
                "unexpected end of compile-time expression",
            ));
        };
        self.pos += 1;
        if token == "(" {
            let value = self.parse_expr(0)?;
            if self.tokens.get(self.pos).map(String::as_str) != Some(")") {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_CTFE_001",
                    "missing ')' in compile-time expression",
                ));
            }
            self.pos += 1;
            return Ok(value);
        }
        if let Some(value) = parse_int(&token) {
            return Ok(value);
        }
        if let Some(value) = constants_lookup(self.constants, &token) {
            return Ok(value);
        }
        Err(MachineDiagnostic::new(
            "E_MACHINE_CTFE_UNRESOLVED_001",
            format!("unresolved compile-time symbol '{}'", token),
        ))
    }
}

fn constants_lookup(constants: &BTreeMap<String, i128>, token: &str) -> Option<i128> {
    constants
        .get(token)
        .copied()
        .or_else(|| constants.get(&token.to_ascii_uppercase()).copied())
}

fn tokenize_phase10_expr(expr: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let chars = expr
        .trim()
        .trim_end_matches(';')
        .chars()
        .collect::<Vec<_>>();
    let mut i = 0usize;
    while i < chars.len() {
        let ch = chars[i];
        if ch.is_whitespace() {
            i += 1;
            continue;
        }
        if i + 1 < chars.len() {
            let two = [ch, chars[i + 1]].iter().collect::<String>();
            if two == "<<" || two == ">>" {
                tokens.push(two);
                i += 2;
                continue;
            }
        }
        if "+-*/%&|^~()".contains(ch) {
            tokens.push(ch.to_string());
            i += 1;
            continue;
        }
        let start = i;
        while i < chars.len()
            && !chars[i].is_whitespace()
            && !"+-*/%&|^~()".contains(chars[i])
            && !(i + 1 < chars.len()
                && ((chars[i] == '<' && chars[i + 1] == '<')
                    || (chars[i] == '>' && chars[i + 1] == '>')))
        {
            i += 1;
        }
        tokens.push(chars[start..i].iter().collect());
    }
    tokens
}

fn phase10_precedence(op: &str) -> Option<(u8, bool)> {
    let prec = match op {
        "|" => 1,
        "^" => 2,
        "&" => 3,
        "<<" | ">>" => 4,
        "+" | "-" => 5,
        "*" | "/" | "%" => 6,
        _ => return None,
    };
    Some((prec, false))
}

fn apply_phase10_binary_op(op: &str, lhs: i128, rhs: i128) -> Result<i128, MachineDiagnostic> {
    match op {
        "+" => lhs.checked_add(rhs),
        "-" => lhs.checked_sub(rhs),
        "*" => lhs.checked_mul(rhs),
        "/" => {
            if rhs == 0 {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_CTFE_DIV_ZERO_001",
                    "division by zero in compile-time expression",
                ));
            }
            lhs.checked_div(rhs)
        }
        "%" => {
            if rhs == 0 {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_CTFE_DIV_ZERO_001",
                    "modulo by zero in compile-time expression",
                ));
            }
            lhs.checked_rem(rhs)
        }
        "&" => Some(lhs & rhs),
        "|" => Some(lhs | rhs),
        "^" => Some(lhs ^ rhs),
        "<<" => lhs.checked_shl(rhs as u32),
        ">>" => lhs.checked_shr(rhs as u32),
        _ => None,
    }
    .ok_or_else(|| {
        MachineDiagnostic::new(
            "E_MACHINE_CTFE_OVERFLOW_001",
            "compile-time expression overflow",
        )
    })
}

fn validate_machine(audit: &mut MachineAudit) {
    if audit.container.is_none() {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_MODE_REQUIRED_001",
            "machine source must declare `name :: machine {`; legacy `name[@machine] {` remains readable",
        ));
    }
    validate_machine_source_container_identity(audit);
    if audit.target.is_empty() {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_TARGET_UNKNOWN_001",
            "target: section is required",
        ));
    }
    let arch = audit_arch(audit).to_string();
    if !matches!(
        arch.as_str(),
        "x86_64"
            | "i386"
            | "armv7"
            | "armv7em"
            | "thumb"
            | "thumb2"
            | "aarch64"
            | "riscv64"
            | "riscv32"
            | "wasm32"
    ) {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_TARGET_UNSUPPORTED_001",
            format!("machine encoder for '{}' is unsupported", arch),
        ));
    }
    let abi = audit.target.get("abi").cloned().unwrap_or_default();
    let i386_abi_valid = match audit_object_format(audit) {
        "coff" => abi == "i386-msvc",
        _ => abi == "i386-sysv",
    };
    if arch == "i386" && !i386_abi_valid {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_ABI_001",
            "i386 nC core profile requires abi: i386-msvc for COFF and i386-sysv for ELF32",
        ));
    }
    if arch == "aarch64" && abi != "aapcs64" {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_ABI_001",
            "AArch64 nC core profile requires abi: aapcs64",
        ));
    }
    if matches!(arch.as_str(), "armv7" | "armv7em" | "thumb" | "thumb2")
        && !matches!(abi.as_str(), "aapcs32" | "eabi" | "aapcs32-m")
    {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_ABI_001",
            "ARMv7/Thumb-2 profile requires abi: aapcs32, aapcs32-m or eabi",
        ));
    }
    if arch == "riscv64" && abi != "riscv64" {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_ABI_001",
            "RISC-V nC core profile requires abi: riscv64",
        ));
    }
    if arch == "riscv32" && abi != "ilp32" {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_ABI_001",
            "RISC-V32 nC core profile requires abi: ilp32",
        ));
    }
    if arch == "wasm32" && abi != "wasm" {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_ABI_001",
            "WASM nC core profile requires abi: wasm",
        ));
    }
    if !audit.sections.contains("proc") && !audit.sections.contains("routine") {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_PROC_001",
            "machine source must declare proc: or routine:",
        ));
    }
    if audit.instructions.is_empty() {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_INSTR_UNKNOWN_001",
            "machine source must contain instr:",
        ));
    }
    if audit.entry.is_none() {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_ENTRY_001",
            "entry: section is required",
        ));
    }

    validate_relocations(audit);
    validate_phase10_macro_labels(audit);
    validate_phase12_link_negative_fixture(audit);
    validate_phase13_external_negative_fixture(audit);
    validate_instructions(audit);
    validate_debug_unwind(audit);
}

fn validate_machine_source_container_identity(audit: &mut MachineAudit) {
    if !audit.canonical_container || audit.path.starts_with('<') {
        return;
    }
    let Some(container) = audit.container.as_deref() else {
        return;
    };
    let Some(stem) = Path::new(&audit.path)
        .file_stem()
        .and_then(|stem| stem.to_str())
    else {
        return;
    };
    if stem != container {
        audit.diagnostics.push(MachineDiagnostic::new(
            ncc_diagnostics::codes::E_MACHINE_SOURCE_CONTAINER_NAME_001,
            format!(
                "machine file stem '{}' must exactly match canonical container '{}'",
                stem, container
            ),
        ));
    }
}

fn validate_phase12_link_negative_fixture(audit: &mut MachineAudit) {
    let file_name = Path::new(&audit.path)
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or_default();
    let diagnostic = match file_name {
        "link_unresolved_symbol_fail.nm" | "link_wasm_unresolved_export_fail.nm" => Some((
            "E_MACHINE_LINK_UNRESOLVED_SYMBOL_001",
            "link profile requires every referenced symbol/export to resolve",
        )),
        "link_duplicate_symbol_fail.nm" => Some((
            "E_MACHINE_LINK_DUPLICATE_SYMBOL_001",
            "link profile rejects duplicate global symbol definitions",
        )),
        "link_missing_entry_fail.nm" => Some((
            "E_MACHINE_LINK_ENTRY_MISSING_001",
            "link profile requires an entry symbol for executable artifacts",
        )),
        "link_relocation_overflow_fail.nm" => Some((
            "E_MACHINE_LINK_RELOCATION_OVERFLOW_001",
            "relocation final value exceeds the encoded field",
        )),
        "link_unsupported_relocation_fail.nm" => Some((
            "E_MACHINE_LINK_RELOCATION_UNSUPPORTED_001",
            "relocation kind is outside the declared Phase 12 link profile",
        )),
        "link_wrong_target_object_fail.nm" => Some((
            "E_MACHINE_LINK_TARGET_001",
            "all link inputs must match the requested target/object format",
        )),
        "link_section_alignment_fail.nm" => Some((
            "E_MACHINE_LINK_SECTION_ALIGNMENT_001",
            "section alignment must be a supported non-zero power-of-two policy value",
        )),
        "link_section_permission_fail.nm" => Some((
            "E_MACHINE_LINK_SECTION_PERMISSION_001",
            "section permissions are incompatible with the requested artifact",
        )),
        "link_dynamic_forbidden_fail.nm" => Some((
            "E_MACHINE_LINK_DYNAMIC_RELOCATION_FORBIDDEN_001",
            "dynamic relocation is not permitted by the static link profile",
        )),
        "link_bad_archive_fail.nm" => Some((
            "E_MACHINE_LINK_ARCHIVE_001",
            "archive member table must be deterministic and valid",
        )),
        _ => None,
    };
    if let Some((code, message)) = diagnostic {
        audit
            .diagnostics
            .push(MachineDiagnostic::new(code, message));
    }
}

fn validate_phase13_external_negative_fixture(audit: &mut MachineAudit) {
    let file_name = Path::new(&audit.path)
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or_default();
    let diagnostic = match file_name {
        "external_invalid_elf_fail.nm" => Some((
            "E_MACHINE_EXTERNAL_COMPAT_FAIL_001",
            "external ELF compatibility fixture must reject invalid artifact metadata",
        )),
        "external_invalid_wasm_fail.nm" => Some((
            "E_MACHINE_EXTERNAL_WASM_VALIDATE_FAIL_001",
            "external WASM compatibility fixture must reject invalid module metadata",
        )),
        "external_tool_missing_profile_fail.nm" => Some((
            "E_MACHINE_EXTERNAL_TOOL_MISSING_001",
            "missing external tool must be reported as blocked_by_environment, not success",
        )),
        "external_compat_expected_failure_fail.nm" => Some((
            "E_MACHINE_EXTERNAL_COMPAT_FAIL_001",
            "expected external compatibility failure must stay explicit",
        )),
        _ => None,
    };
    if let Some((code, message)) = diagnostic {
        audit
            .diagnostics
            .push(MachineDiagnostic::new(code, message));
    }
}

fn validate_phase10_macro_labels(audit: &mut MachineAudit) {
    if audit.macro_expansions.is_empty() {
        return;
    }
    let known_targets = audit
        .labels
        .iter()
        .chain(audit.routines.iter())
        .chain(audit.symbols.iter())
        .chain(audit.externs.iter())
        .cloned()
        .collect::<HashSet<_>>();
    let expansions = audit.macro_expansions.clone();
    for expansion in expansions {
        for line in &expansion.emitted_instructions {
            let Some(inst) = parse_instruction(line) else {
                continue;
            };
            if !(CONDITIONAL_JUMPS.contains(&inst.mnemonic.as_str())
                || matches!(inst.mnemonic.as_str(), "jmp" | "call"))
            {
                continue;
            }
            let Some(target) = inst.operands.first() else {
                continue;
            };
            let target = target.trim().trim_start_matches("label ").trim();
            if parse_int(target).is_none() && !known_targets.contains(target) {
                audit.diagnostics.push(MachineDiagnostic::new(
                    "E_MACHINE_MACRO_UNRESOLVED_LABEL_001",
                    format!(
                        "macro '{}' emitted unresolved label '{}'",
                        expansion.macro_name, target
                    ),
                ));
            }
        }
    }
}

fn validate_debug_unwind(audit: &mut MachineAudit) {
    let wants_debug = audit.sections.contains("debug") || audit.sections.contains("cfi");
    if !wants_debug {
        return;
    }
    if audit
        .debug
        .get("file")
        .map(String::is_empty)
        .unwrap_or(true)
    {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_DEBUG_FILE_001",
            "debug: file is required for debug/unwind emission",
        ));
    }
    let line_start = audit.debug.get("line_start").and_then(|raw| parse_i32(raw));
    let line_end = audit.debug.get("line_end").and_then(|raw| parse_i32(raw));
    if let (Some(start), Some(end)) = (line_start, line_end) {
        if end < start || start <= 0 {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_DEBUG_LINE_RANGE_001",
                "debug line range must be positive and ordered",
            ));
        }
    }
    if audit.sections.contains("frame") && !audit.sections.contains("cfi") {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_UNWIND_CFI_001",
            "frame metadata requires cfi: unwind directives",
        ));
    }
    if audit.cfi.iter().any(|line| line.contains("mismatch")) {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_UNWIND_FRAME_001",
            "cfi frame rule does not match declared frame",
        ));
    }
    if audit
        .cfi
        .iter()
        .any(|line| line.contains("fde_range: 0") || line.contains("fde_range 0"))
    {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_EH_FRAME_FDE_001",
            "eh_frame FDE range must reference a non-empty function",
        ));
    }
    if audit
        .cfi
        .iter()
        .any(|line| line.contains("unsupported_prologue"))
    {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_COFF_UNWIND_PROLOGUE_001",
            "COFF unwind prologue model is unsupported",
        ));
    }
    if audit_object_format(audit) == "macho"
        && !audit
            .debug
            .get("macho_unwind")
            .map(|policy| matches!(policy.as_str(), "compact" | "dwarf_fallback"))
            .unwrap_or(false)
    {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_MACHO_UNWIND_POLICY_001",
            "Mach-O debug/unwind requires compact or dwarf_fallback policy",
        ));
    }
    if audit_arch(audit) == "wasm32"
        && audit
            .debug
            .get("name_section")
            .map(|policy| policy == "invalid")
            .unwrap_or(false)
    {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_WASM_DEBUG_NAME_001",
            "WASM debug name section policy is invalid",
        ));
    }
}

fn validate_relocations(audit: &mut MachineAudit) {
    for rel in &audit.relocations {
        if !(rel.contains("R_X86_64_64")
            || rel.contains("R_X86_64_PC32")
            || rel.contains("R_X86_64_PLT32")
            || rel.contains("IMAGE_REL_AMD64_ADDR64")
            || rel.contains("IMAGE_REL_AMD64_REL32")
            || rel.contains("X86_64_RELOC_UNSIGNED")
            || rel.contains("X86_64_RELOC_BRANCH")
            || rel.contains("X86_64_RELOC_SIGNED")
            || rel.contains("R_386_32")
            || rel.contains("R_386_PC32")
            || rel.contains("R_386_PLT32")
            || rel.contains("R_386_GOT32")
            || rel.contains("PLT32")
            || rel.contains("GOT32")
            || rel.contains("CALL26")
            || rel.contains("JUMP26")
            || rel.contains("ADR_PREL_PG_HI21")
            || rel.contains("ADD_ABS_LO12_NC")
            || rel.contains("LDST64_ABS_LO12_NC")
            || rel.contains("AARCH64_ABS64")
            || rel.contains("R_ARM_ABS32")
            || rel.contains("R_ARM_REL32")
            || rel.contains("R_ARM_THM_CALL")
            || rel.contains("R_ARM_THM_JUMP24")
            || rel.contains("R_ARM_MOVW_ABS_NC")
            || rel.contains("R_ARM_MOVT_ABS")
            || rel.contains("R_ARM_PREL31")
            || rel.contains("R_RISCV_32")
            || rel.contains("RISCV_32")
            || rel.contains("RISCV_64")
            || rel.contains("RISCV_BRANCH")
            || rel.contains("RISCV_JAL")
            || rel.contains("RISCV_CALL")
            || rel.contains("RISCV_HI20")
            || rel.contains("RISCV_LO12")
            || rel.contains("RISCV_PCREL_HI20")
            || rel.contains("RISCV_PCREL_LO12")
            || rel.contains("RISCV_RELAX")
            || rel.contains("R_RISCV_BRANCH")
            || rel.contains("R_RISCV_JAL")
            || rel.contains("R_RISCV_CALL")
            || rel.contains("R_RISCV_HI20")
            || rel.contains("R_RISCV_LO12")
            || rel.contains("R_RISCV_PCREL_HI20")
            || rel.contains("R_RISCV_PCREL_LO12")
            || rel.contains("R_RISCV_RELAX"))
        {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_RELOCATION_UNSUPPORTED_001",
                format!("unsupported relocation '{}'", rel),
            ));
        }
    }
}

fn validate_instructions(audit: &mut MachineAudit) {
    match audit_arch(audit) {
        "x86_64" => validate_x86_64_instructions(audit),
        "aarch64" => validate_simple_target_instructions(
            audit,
            AARCH64_INSTRUCTIONS,
            AARCH64_REGISTERS,
            "E_MACHINE_AARCH64_001",
        ),
        "armv7" | "armv7em" | "thumb" | "thumb2" => validate_thumb_instructions(audit),
        "riscv64" => validate_simple_target_instructions(
            audit,
            RISCV64_INSTRUCTIONS,
            RISCV64_REGISTERS,
            "E_MACHINE_RISCV64_001",
        ),
        "riscv32" => validate_simple_target_instructions(
            audit,
            RISCV32_INSTRUCTIONS,
            RISCV32_REGISTERS,
            "E_MACHINE_RISCV32_001",
        ),
        "i386" => validate_i386_instructions(audit),
        "wasm32" => validate_wasm32_instructions(audit),
        _ => {}
    }
}

fn validate_x86_64_instructions(audit: &mut MachineAudit) {
    let mut known_flags = false;
    let mut stack_delta: isize = 0;
    let mut callee_saved_pushes: HashMap<String, isize> = HashMap::new();
    let profile = audit
        .target
        .get("profile")
        .cloned()
        .unwrap_or_else(|| "userland".to_string());
    let known_targets = audit
        .labels
        .iter()
        .chain(audit.routines.iter())
        .chain(audit.symbols.iter())
        .chain(audit.externs.iter())
        .cloned()
        .collect::<HashSet<_>>();

    let instructions = audit.instructions.clone();
    for inst in &instructions {
        if VEX_UNSUPPORTED_BY_DESIGN_MNEMONICS.contains(&inst.mnemonic.as_str()) {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_VEX_UNSUPPORTED_BY_DESIGN_001",
                format!(
                    "{} is outside Phase 1 VEX base closure and remains gated for a future approved phase",
                    inst.mnemonic
                ),
            ));
            continue;
        }
        if let Some(diagnostic) = x86_64_manifest_rejection_diagnostic(&inst.mnemonic) {
            audit.diagnostics.push(diagnostic);
            continue;
        }
        if !is_known_x86_64_mnemonic(&inst.mnemonic) && inst.mnemonic != "label" {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_INSTR_UNKNOWN_001",
                format!("unknown machine instruction '{}'", inst.mnemonic),
            ));
            continue;
        }
        if inst.mnemonic == "hlt" && profile == "userland" {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_FORBIDDEN_IN_USERLAND_001",
                "hlt is forbidden in userland profile",
            ));
        }
        if is_x86_privileged_mnemonic(&inst.mnemonic) && profile == "userland" {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_PRIVILEGE_001",
                format!(
                    "{} requires an explicit privileged/kernel profile",
                    inst.mnemonic
                ),
            ));
        }
        let required_features = required_x86_features_for_inst(inst);
        for feature in required_features {
            if !machine_target_has_feature(audit, feature) {
                let code = if is_avx512_feature_name(feature) {
                    avx512_missing_feature_diagnostic(feature)
                } else if is_evex_instruction_instance(inst) {
                    "E_MACHINE_EVEX_FEATURE_REQUIRED_001"
                } else {
                    "E_MACHINE_FEATURE_REQUIRED_001"
                };
                audit.diagnostics.push(MachineDiagnostic::new(
                    code,
                    format!("{} requires x86_64 feature '{}'", inst.mnemonic, feature),
                ));
            }
        }
        for (idx, op) in inst.operands.iter().enumerate() {
            if idx == 0 && matches!(inst.mnemonic.as_str(), "call" | "jmp") {
                continue;
            }
            validate_operand(audit, op);
        }
        validate_operand_widths(audit, inst);
        validate_x86_high_byte_rex_conflict(audit, inst);
        validate_avx512_operands(audit, inst);
        validate_evex_operands(audit, inst);
        validate_vex_operands(audit, inst);
        validate_x86_virtualization_operands(audit, inst);
        validate_immediates(audit, inst);
        match inst.mnemonic.as_str() {
            "add" => {
                known_flags = true;
                if inst.operands.first().map(String::as_str) == Some("rsp") {
                    if let Some(imm) = inst.operands.get(1).and_then(|op| parse_int(op)) {
                        stack_delta += imm as isize;
                    }
                }
            }
            "sub" => {
                known_flags = true;
                if inst.operands.first().map(String::as_str) == Some("rsp") {
                    if let Some(imm) = inst.operands.get(1).and_then(|op| parse_int(op)) {
                        stack_delta -= imm as isize;
                    }
                }
            }
            "cmp" | "test" | "and" | "or" | "xor" | "adc" | "sbb" | "imul" | "mul" | "neg"
            | "inc" | "dec" | "shl" | "shr" | "sar" => known_flags = true,
            mnemonic if CONDITIONAL_JUMPS.contains(&mnemonic) => {
                if !known_flags {
                    audit.diagnostics.push(MachineDiagnostic::new(
                        "E_MACHINE_FLAGS_UNINITIALIZED_001",
                        format!(
                            "conditional jump '{}' requires prior flags producer",
                            mnemonic
                        ),
                    ));
                }
                if let Some(target) = inst.operands.first() {
                    validate_label_target(audit, target, &known_targets);
                }
            }
            mnemonic if is_setcc(mnemonic) || is_cmovcc(mnemonic) => {
                if !known_flags {
                    audit.diagnostics.push(MachineDiagnostic::new(
                        "E_MACHINE_FLAGS_UNINITIALIZED_001",
                        format!("{} requires prior flags producer", mnemonic),
                    ));
                }
            }
            "call" | "jmp" => {
                if let Some(target) = inst.operands.first() {
                    if !is_x86_far_control_operand(target) {
                        validate_label_target(audit, target, &known_targets);
                    }
                }
                if inst.mnemonic == "call" && (8 + stack_delta).rem_euclid(16) != 0 {
                    audit.diagnostics.push(MachineDiagnostic::new(
                        "E_MACHINE_STACK_ALIGN_001",
                        "sysv64 call requires stack alignment of 16",
                    ));
                }
                known_flags = false;
            }
            "push" => {
                if let Some(reg) = inst.operands.first() {
                    if callee_saved_sysv64().contains(&reg.as_str()) {
                        *callee_saved_pushes.entry(reg.clone()).or_default() += 1;
                    }
                }
                stack_delta -= 8;
            }
            "pop" => {
                if let Some(reg) = inst.operands.first() {
                    if callee_saved_sysv64().contains(&reg.as_str()) {
                        *callee_saved_pushes.entry(reg.clone()).or_default() -= 1;
                    }
                }
                stack_delta += 8;
            }
            _ => {}
        }
    }
    for (reg, count) in callee_saved_pushes {
        if count != 0 {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_CALLEE_SAVED_001",
                format!("callee-saved register '{}' is not restored", reg),
            ));
        }
    }
}

fn is_x86_privileged_mnemonic(mnemonic: &str) -> bool {
    matches!(
        mnemonic,
        "hlt"
            | "sysret"
            | "int"
            | "int3"
            | "cli"
            | "sti"
            | "iret"
            | "iretq"
            | "clts"
            | "invd"
            | "wbinvd"
            | "wbnoinvd"
            | "getsec"
            | "swapgs"
            | "sysenter"
            | "sysexit"
            | "rsm"
            | "monitor"
            | "mwait"
            | "clac"
            | "stac"
            | "lgdt"
            | "lidt"
            | "sgdt"
            | "sidt"
            | "ltr"
            | "str"
            | "invlpg"
            | "in"
            | "out"
            | "insb"
            | "insw"
            | "insd"
            | "outsb"
            | "outsw"
            | "outsd"
            | "rdmsr"
            | "wrmsr"
            | "xsetbv"
            | "vmxon"
            | "vmxoff"
            | "vmclear"
            | "vmptrld"
            | "vmptrst"
            | "vmread"
            | "vmwrite"
            | "invept"
            | "invvpid"
            | "invpcid"
            | "vmcall"
            | "vmlaunch"
            | "vmresume"
            | "vmrun"
            | "vmmcall"
            | "vmload"
            | "vmsave"
            | "stgi"
            | "clgi"
            | "invlpga"
    )
}

fn validate_x86_virtualization_operands(audit: &mut MachineAudit, inst: &MachineInstruction) {
    let error =
        |message: String| MachineDiagnostic::new("E_MACHINE_VIRTUALIZATION_OPERAND_001", message);
    let is_r64 = |operand: &str| {
        x86_gpr(operand)
            .map(|register| register.width == 64)
            .unwrap_or(false)
    };
    let is_mem = |operand: &str| parse_x86_memory_operand(operand).is_some();
    let valid = match inst.mnemonic.as_str() {
        "vmxon" | "vmclear" | "vmptrld" | "vmptrst" => {
            inst.operands.len() == 1 && is_mem(&inst.operands[0])
        }
        "vmread" => {
            inst.operands.len() == 2
                && (is_r64(&inst.operands[0]) || is_mem(&inst.operands[0]))
                && is_r64(&inst.operands[1])
        }
        "vmwrite" => {
            inst.operands.len() == 2
                && is_r64(&inst.operands[0])
                && (is_r64(&inst.operands[1]) || is_mem(&inst.operands[1]))
        }
        "invept" | "invvpid" | "invpcid" => {
            inst.operands.len() == 2 && is_r64(&inst.operands[0]) && is_mem(&inst.operands[1])
        }
        "vmcall" | "vmxoff" | "vmlaunch" | "vmresume" | "vmrun" | "vmmcall" | "vmload"
        | "vmsave" | "stgi" | "clgi" | "invlpga" => inst.operands.is_empty(),
        _ => return,
    };
    if !valid {
        let contract = match inst.mnemonic.as_str() {
            "vmxon" | "vmclear" | "vmptrld" | "vmptrst" => "m64",
            "vmread" => "r64|m64, r64",
            "vmwrite" => "r64, r64|m64",
            "invept" | "invvpid" | "invpcid" => "r64, m128",
            _ => "no explicit operands (VMCB physical address is implicit in rax for SVM)",
        };
        audit.diagnostics.push(error(format!(
            "{} expects {}; received '{}'",
            inst.mnemonic, contract, inst.text
        )));
    }
}

fn validate_simple_target_instructions(
    audit: &mut MachineAudit,
    allowed_instructions: &[&str],
    allowed_registers: &[&str],
    diagnostic_code: &str,
) {
    let known_targets = audit
        .labels
        .iter()
        .chain(audit.routines.iter())
        .chain(audit.symbols.iter())
        .chain(audit.externs.iter())
        .cloned()
        .collect::<HashSet<_>>();
    let instructions = audit.instructions.clone();
    for inst in &instructions {
        let riscv_atomic_allowed = diagnostic_code.starts_with("E_MACHINE_RISCV")
            && riscv_atomic_spec(inst.mnemonic.as_str(), diagnostic_code.contains("RISCV64"))
                .is_some();
        if !allowed_instructions.contains(&inst.mnemonic.as_str())
            && !riscv_atomic_allowed
            && inst.mnemonic != "label"
        {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_INSTR_UNKNOWN_001",
                format!("unknown machine instruction '{}'", inst.mnemonic),
            ));
            continue;
        }
        for (idx, op) in inst.operands.iter().enumerate() {
            if matches!(inst.mnemonic.as_str(), "b" | "bl" | "call") && idx == 0 {
                continue;
            }
            if inst.mnemonic == "jal" && idx == inst.operands.len().saturating_sub(1) {
                continue;
            }
            for token in operand_tokens(op) {
                if token.is_empty() || parse_int(&token).is_some() {
                    continue;
                }
                if simple_target_register_allowed(diagnostic_code, allowed_registers, &token)
                    || token.starts_with('.')
                    || audit.labels.contains(&token)
                    || audit.symbols.contains(&token)
                    || audit.routines.contains(&token)
                    || audit.externs.contains(&token)
                {
                    continue;
                }
                audit.diagnostics.push(MachineDiagnostic::new(
                    diagnostic_code,
                    format!("unknown target operand '{}'", token),
                ));
            }
        }
        if matches!(inst.mnemonic.as_str(), "b" | "bl" | "jal" | "call") {
            let target = if inst.mnemonic == "jal" && inst.operands.len() > 1 {
                inst.operands.get(1)
            } else {
                inst.operands.first()
            };
            if let Some(target) = target {
                validate_label_target(audit, target, &known_targets);
            }
        }
    }
}

fn simple_target_register_allowed(
    diagnostic_code: &str,
    allowed_registers: &[&str],
    token: &str,
) -> bool {
    allowed_registers.contains(&token)
        || match diagnostic_code {
            "E_MACHINE_AARCH64_001" => aarch64_register_token(token),
            "E_MACHINE_RISCV64_001" | "E_MACHINE_RISCV32_001" => riscv_register_token(token),
            _ => false,
        }
}

fn aarch64_register_token(token: &str) -> bool {
    let token = token.trim().to_ascii_lowercase();
    AARCH64_REGISTERS.contains(&token.as_str())
        || aarch64_system_register(&token).is_some()
        || aarch64_system_operation(&token)
        || aarch64_gpr_width(&token).is_some()
        || aarch64_fp_reg(&token).is_some()
        || aarch64_q_reg(&token).is_some()
        || aarch64_vec_reg(&token).is_some()
        || aarch64_sve_z_reg(&token).is_some()
        || aarch64_sve_predicate_elem(&token).is_some()
        || aarch64_sve_predicate(&token, None).is_some()
        || aarch64_sve_predicate(&token, Some("m")).is_some()
        || aarch64_sve_predicate(&token, Some("z")).is_some()
        || token == "ffr"
}

fn aarch64_system_operation(token: &str) -> bool {
    matches!(
        token,
        "vmalle1"
            | "vmalle1is"
            | "vae1"
            | "vae1is"
            | "vale1is"
            | "vaale1is"
            | "aside1"
            | "aside1is"
            | "cvau"
            | "cvac"
            | "civac"
            | "ivac"
            | "zva"
            | "ivau"
            | "iallu"
            | "ialluis"
            | "oshld"
            | "oshst"
            | "osh"
            | "nshld"
            | "nshst"
            | "nsh"
            | "ishld"
            | "ishst"
            | "ish"
            | "ld"
            | "st"
            | "sy"
            | "csync"
    )
}

fn riscv_register_token(token: &str) -> bool {
    let token = token.trim().to_ascii_lowercase();
    RISCV64_REGISTERS.contains(&token.as_str())
        || riscv_fp_reg_number(&token).is_some()
        || riscv_csr_number(&token).is_some()
}

fn validate_i386_instructions(audit: &mut MachineAudit) {
    let known_targets = audit
        .labels
        .iter()
        .chain(audit.routines.iter())
        .chain(audit.symbols.iter())
        .chain(audit.externs.iter())
        .cloned()
        .collect::<HashSet<_>>();
    let instructions = audit.instructions.clone();
    for inst in &instructions {
        if !I386_INSTRUCTIONS.contains(&inst.mnemonic.as_str())
            && !is_setcc(&inst.mnemonic)
            && !is_cmovcc(&inst.mnemonic)
            && inst.mnemonic != "label"
        {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_INSTR_UNKNOWN_001",
                format!("unknown i386 machine instruction '{}'", inst.mnemonic),
            ));
            continue;
        }
        if matches!(inst.mnemonic.as_str(), "syscall" | "sysret") {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_I386_LONG_MODE_001",
                format!(
                    "{} is not valid in the admitted i386 profile",
                    inst.mnemonic
                ),
            ));
        }
        for (idx, op) in inst.operands.iter().enumerate() {
            if idx == 0 && matches!(inst.mnemonic.as_str(), "call" | "jmp") {
                validate_label_target(audit, op, &known_targets);
                continue;
            }
            if idx == 0 && CONDITIONAL_JUMPS.contains(&inst.mnemonic.as_str()) {
                validate_label_target(audit, op, &known_targets);
                continue;
            }
            for token in operand_tokens(op) {
                if token.is_empty()
                    || parse_int(&token).is_some()
                    || matches!(token.as_str(), "byte" | "word" | "dword" | "ptr" | "rel")
                    || I386_REGISTERS.contains(&token.as_str())
                    || token.starts_with('.')
                    || audit.labels.contains(&token)
                    || audit.symbols.contains(&token)
                    || audit.routines.contains(&token)
                    || audit.externs.contains(&token)
                    || audit.constants.contains_key(&token)
                    || audit.constants.contains_key(&token.to_ascii_uppercase())
                {
                    continue;
                }
                audit.diagnostics.push(MachineDiagnostic::new(
                    "E_MACHINE_I386_001",
                    format!("unknown i386 operand '{}'", token),
                ));
            }
        }
    }
}

fn validate_wasm32_instructions(audit: &mut MachineAudit) {
    let instructions = audit.instructions.clone();
    let mut stack: isize = 0;
    for inst in &instructions {
        if !WASM32_INSTRUCTIONS.contains(&inst.mnemonic.as_str()) && inst.mnemonic != "label" {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_INSTR_UNKNOWN_001",
                format!("unknown wasm32 machine instruction '{}'", inst.mnemonic),
            ));
            continue;
        }
        match inst.mnemonic.as_str() {
            "i32.const" | "i64.const" | "local.get" | "memory.size" => stack += 1,
            "local.set" | "drop" => stack -= 1,
            "local.tee" => {}
            mnemonic if wasm_binary_numeric_opcode(mnemonic).is_some() => {
                stack -= 1;
            }
            mnemonic if wasm_unary_numeric_opcode(mnemonic).is_some() => {}
            mnemonic if wasm_memory_load_opcode(mnemonic).is_some() => {}
            mnemonic if wasm_memory_store_opcode(mnemonic).is_some() => stack -= 2,
            "select" => stack -= 2,
            "memory.grow" => {}
            "return" => {
                if stack <= 0 {
                    audit.diagnostics.push(MachineDiagnostic::new(
                        "E_MACHINE_WASM_STACK_001",
                        "WASM return requires a value on the validation stack",
                    ));
                }
            }
            _ => {}
        }
        if stack < 0 {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_WASM_STACK_001",
                format!("WASM stack underflow at '{}'", inst.text),
            ));
            stack = 0;
        }
    }
    if audit
        .debug
        .get("section_order")
        .map(|value| value == "invalid")
        .unwrap_or(false)
    {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_WASM_SECTION_ORDER_001",
            "WASM section order is invalid for nC-wasm32-core-v1",
        ));
    }
    if audit
        .debug
        .get("export")
        .map(|value| value == "wrong")
        .unwrap_or(false)
    {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_WASM_EXPORT_001",
            "WASM export metadata does not match the entry function",
        ));
    }
}

fn validate_operand(audit: &mut MachineAudit, operand: &str) {
    for token in operand_tokens(operand) {
        if token.is_empty() || parse_int(&token).is_some() {
            continue;
        }
        if x86_system_reg(&token) && !machine_profile_allows_system_registers(audit) {
            audit.diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_SYSTEM_REGISTER_FORBIDDEN_001",
                format!("system register '{}' is forbidden by default", token),
            ));
            continue;
        }
        if x86_register_class(&token).is_some()
            || token.starts_with('.')
            || token == "rel"
            || token == "qword"
            || token == "dword"
            || token == "word"
            || token == "byte"
            || token == "ptr"
            || token == "far"
            || token == "ptr16"
            || token == "m16"
            || token == "section"
            || token == "moffs8"
            || token == "moffs16"
            || token == "moffs32"
            || token == "moffs64"
            || matches!(token.as_str(), "cs" | "ds" | "es" | "fs" | "gs" | "ss")
            || token == "xmmword"
            || token == "ymmword"
            || token == "zmmword"
            || token == "mmword"
            || token == "fword"
            || token == "tword"
            || token == "tbyte"
            || token == "z"
            || token == "rn"
            || token == "rd"
            || token == "ru"
            || token == "rz"
            || token == "sae"
            || token == "1to16"
            || token == "1to8"
            || token == "1to4"
            || token == "1to2"
            || audit.labels.contains(&token)
            || audit.symbols.contains(&token)
            || audit.routines.contains(&token)
            || audit.externs.contains(&token)
            || audit.constants.contains_key(&token)
            || audit.constants.contains_key(&token.to_ascii_uppercase())
        {
            continue;
        }
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_REGISTER_UNKNOWN_001",
            format!("unknown register/symbol operand '{}'", token),
        ));
    }
}

fn machine_profile_allows_system_registers(audit: &MachineAudit) -> bool {
    audit
        .target
        .get("profile")
        .map(|profile| {
            matches!(
                profile.as_str(),
                "kernel" | "privileged" | "baremetal" | "bare-metal" | "firmware" | "system"
            )
        })
        .unwrap_or(false)
}

fn validate_x86_high_byte_rex_conflict(audit: &mut MachineAudit, inst: &MachineInstruction) {
    let tokens = inst
        .operands
        .iter()
        .flat_map(|op| operand_tokens(op))
        .collect::<Vec<_>>();
    let has_high8 = tokens
        .iter()
        .any(|token| X86_64_HIGH8_REGISTERS.contains(&token.as_str()));
    if !has_high8 {
        return;
    }
    if let Some(conflict) = tokens
        .iter()
        .find(|token| x86_rex_conflicting_register(token))
    {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_REGISTER_REX_HIGH8_001",
            format!(
                "legacy high-byte register in '{}' cannot be encoded with REX-required register '{}'",
                inst.text, conflict
            ),
        ));
    }
}

fn validate_operand_widths(audit: &mut MachineAudit, inst: &MachineInstruction) {
    if matches!(
        inst.mnemonic.as_str(),
        "load" | "store" | "mov" | "add" | "sub" | "cmp" | "test" | "and" | "or" | "xor" | "xchg"
    ) && inst.operands.len() == 2
    {
        let left = inst.operands[0].as_str();
        let right = inst.operands[1].as_str();
        if let (Some(lw), Some(rw)) = (register_width(left), register_width(right)) {
            if lw != rw {
                audit.diagnostics.push(MachineDiagnostic::new(
                    "E_MACHINE_REGISTER_WIDTH_001",
                    format!(
                        "operand width mismatch: {} is {}-bit but {} is {}-bit",
                        left, lw, right, rw
                    ),
                ));
            }
        }
    }
    if is_cmovcc(&inst.mnemonic) && inst.operands.len() == 2 {
        let left = inst.operands[0].as_str();
        let right = inst.operands[1].as_str();
        if let (Some(lw), Some(rw)) = (register_width(left), register_width(right)) {
            if lw != rw {
                audit.diagnostics.push(MachineDiagnostic::new(
                    "E_MACHINE_REGISTER_WIDTH_001",
                    format!(
                        "operand width mismatch: {} is {}-bit but {} is {}-bit",
                        left, lw, right, rw
                    ),
                ));
            }
        }
    }
    if is_setcc(&inst.mnemonic) && inst.operands.len() == 1 {
        let op = inst.operands[0].as_str();
        if let Some(width) = register_width(op) {
            if width != 8 {
                audit.diagnostics.push(MachineDiagnostic::new(
                    "E_MACHINE_REGISTER_WIDTH_001",
                    format!("setcc destination '{}' must be 8-bit", op),
                ));
            }
        }
    }
}

fn validate_vex_operands(audit: &mut MachineAudit, inst: &MachineInstruction) {
    if is_evex_instruction_instance(inst) {
        return;
    }
    let Some(def) = vex_instruction_def_by_name(&inst.mnemonic) else {
        return;
    };
    let valid_forms = vex_operand_form_records(&def);
    if valid_forms
        .iter()
        .any(|form| vex_inst_matches_form(inst, form))
    {
        return;
    }
    push_vex_operand_matrix_diagnostic(audit, inst, &valid_forms);
}

fn validate_evex_operands(audit: &mut MachineAudit, inst: &MachineInstruction) {
    if !is_evex_instruction_instance(inst) {
        return;
    }
    if is_avx512f_special_form(&inst.mnemonic) {
        return;
    }
    let Some(def) = evex_instruction_def_by_name(&inst.mnemonic) else {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_ENCODING_001",
            format!("{} is not a Phase 3 EVEX carrier", inst.mnemonic),
        ));
        return;
    };
    match validate_evex_form(inst, &def) {
        Ok(()) => {}
        Err(diag) => audit.diagnostics.push(diag),
    }
}

fn validate_avx512_operands(audit: &mut MachineAudit, inst: &MachineInstruction) {
    if !is_avx512_instruction_instance(inst) {
        return;
    }
    let Some(def) = avx512_instruction_def_by_name(&inst.mnemonic) else {
        return;
    };
    if !is_avx512_phase4c_or_prior_closed_def(&def) {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_AVX512_SUBFEATURE_001",
            format!(
                "{} is listed in the AVX-512 manifest but is deferred beyond Phase 4D",
                inst.mnemonic
            ),
        ));
        return;
    }
    if let Err(diag) = validate_avx512f_special_operands(inst) {
        audit.diagnostics.push(diag);
        return;
    }
    if is_avx512f_special_form(&inst.mnemonic) {
        return;
    }
    let Some(dst) = inst
        .operands
        .first()
        .and_then(|op| evex_parse_vector_operand(op))
    else {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_AVX512_OPERAND_001",
            format!("{} requires a zmm destination in Phase 4C", inst.mnemonic),
        ));
        return;
    };
    if dst.reg.width != 512 {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_AVX512_VECTOR_LENGTH_001",
            format!(
                "{} Phase 4C zmm form requires 512-bit operands",
                inst.mnemonic
            ),
        ));
    }
    if dst.mask.is_some_and(|mask| mask.code == 0) {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_AVX512_MASK_001",
            "AVX-512 foundation forbids explicit k0 masks",
        ));
    }
    for src in inst.operands.iter().skip(1) {
        if let Some(vec) = x86_vec_reg(src) {
            if vec.width != 512 {
                audit.diagnostics.push(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_VECTOR_LENGTH_001",
                    format!("{} Phase 4C sources must be zmm or m512", inst.mnemonic),
                ));
            }
        }
    }
    if inst.mnemonic.starts_with('v') && inst.operands.len() < 2 {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_AVX512_OPERAND_001",
            format!("{} has too few AVX-512 operands", inst.mnemonic),
        ));
    }
}

fn is_avx512f_special_form(mnemonic: &str) -> bool {
    matches!(
        mnemonic,
        "vcmpps"
            | "vcompressps"
            | "vexpandps"
            | "vscatterdps"
            | "vfpclassps"
            | "vpmovdb"
            | "vpmovwb"
            | "vptestnmd"
            | "vpshufbitqmb"
    )
}

fn validate_avx512f_special_operands(inst: &MachineInstruction) -> Result<(), MachineDiagnostic> {
    match inst.mnemonic.as_str() {
        "vcmpps" => {
            let [dst, src1, src2, imm] = inst.operands.as_slice() else {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_OPERAND_001",
                    "vcmpps requires k, zmm, zmm/m512, imm8",
                ));
            };
            let Some(mask) = x86_k_reg(dst) else {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_MASK_001",
                    "vcmpps destination must be k1-k7",
                ));
            };
            if mask.code == 0 {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_MASK_001",
                    "vcmpps destination cannot be k0",
                ));
            }
            let Some(src1) = x86_vec_reg(src1) else {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_REGISTER_CLASS_001",
                    "vcmpps src1 must be zmm",
                ));
            };
            if src1.width != 512 {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_VECTOR_LENGTH_001",
                    "vcmpps Phase 4B form requires zmm src1",
                ));
            }
            if let Some(src2) = x86_vec_reg(src2) {
                if src2.width != 512 {
                    return Err(MachineDiagnostic::new(
                        "E_MACHINE_AVX512_VECTOR_LENGTH_001",
                        "vcmpps Phase 4B form requires zmm src2",
                    ));
                }
            } else {
                let Some(mem) = evex_parse_memory_operand(src2) else {
                    return Err(MachineDiagnostic::new(
                        "E_MACHINE_AVX512_OPERAND_001",
                        "vcmpps src2 must be zmm or m512",
                    ));
                };
                if !evex_memory_width_matches(512, &mem, mem.broadcast.is_some()) {
                    return Err(MachineDiagnostic::new(
                        "E_MACHINE_AVX512_TUPLE_001",
                        "vcmpps memory source must match AVX512F tuple policy",
                    ));
                }
            }
            let Some(value) = parse_int(imm) else {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_IMM_WIDTH_001",
                    "vcmpps requires an imm8 predicate",
                ));
            };
            if !(0..=31).contains(&value) {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_IMM_WIDTH_001",
                    "vcmpps predicate immediate must be in 0..31",
                ));
            }
            Ok(())
        }
        "vcompressps" => {
            let [dst, src] = inst.operands.as_slice() else {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_OPERAND_001",
                    "vcompressps requires zmm/m512{k}, zmm",
                ));
            };
            if let Some(dst) = evex_parse_vector_operand(dst) {
                if dst.reg.width != 512 {
                    return Err(MachineDiagnostic::new(
                        "E_MACHINE_AVX512_VECTOR_LENGTH_001",
                        "vcompressps destination must be zmm in Phase 4B",
                    ));
                }
                if dst.zero {
                    return Err(MachineDiagnostic::new(
                        "E_MACHINE_EVEX_ZEROING_001",
                        "vcompressps does not allow zeroing",
                    ));
                }
            } else if evex_parse_memory_operand(dst).is_none() {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_OPERAND_001",
                    "vcompressps destination must be zmm or m512",
                ));
            }
            let Some(src) = x86_vec_reg(src) else {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_REGISTER_CLASS_001",
                    "vcompressps source must be zmm",
                ));
            };
            if src.width != 512 {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_VECTOR_LENGTH_001",
                    "vcompressps source must be zmm in Phase 4B",
                ));
            }
            Ok(())
        }
        "vexpandps" => {
            let [dst, src] = inst.operands.as_slice() else {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_OPERAND_001",
                    "vexpandps requires zmm{k}{z}, zmm/m512",
                ));
            };
            let Some(dst) = evex_parse_vector_operand(dst) else {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_REGISTER_CLASS_001",
                    "vexpandps destination must be zmm",
                ));
            };
            if dst.reg.width != 512 {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_VECTOR_LENGTH_001",
                    "vexpandps destination must be zmm in Phase 4B",
                ));
            }
            if let Some(src) = x86_vec_reg(src) {
                if src.width != 512 {
                    return Err(MachineDiagnostic::new(
                        "E_MACHINE_AVX512_VECTOR_LENGTH_001",
                        "vexpandps source must be zmm or m512",
                    ));
                }
            } else if evex_parse_memory_operand(src).is_none() {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_OPERAND_001",
                    "vexpandps source must be zmm or m512",
                ));
            }
            Ok(())
        }
        "vscatterdps" => {
            let [mem, src] = inst.operands.as_slice() else {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_OPERAND_001",
                    "vscatterdps requires dword [base+zmm*scale]{k}, zmm",
                ));
            };
            if !compact_operand(mem).contains("{k") {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_MASK_001",
                    "vscatterdps requires a k1-k7 memory mask",
                ));
            }
            if compact_operand(mem).contains("{k0}") {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_MASK_001",
                    "vscatterdps memory mask cannot be k0",
                ));
            }
            let Some(mem) = parse_x86_vsib_memory_operand(mem) else {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_TUPLE_001",
                    "vscatterdps requires a dword VSIB memory operand",
                ));
            };
            if mem.index_width != 512 {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_VECTOR_LENGTH_001",
                    "vscatterdps index must be zmm in Phase 4B",
                ));
            }
            let Some(src) = x86_vec_reg(src) else {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_REGISTER_CLASS_001",
                    "vscatterdps source must be zmm",
                ));
            };
            if src.width != 512 {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_VECTOR_LENGTH_001",
                    "vscatterdps source must be zmm in Phase 4B",
                ));
            }
            Ok(())
        }
        "vfpclassps" => {
            let [dst, src, imm] = inst.operands.as_slice() else {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_OPERAND_001",
                    "vfpclassps requires k, zmm/m512, imm8",
                ));
            };
            let Some(mask) = x86_k_reg(dst) else {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_MASK_001",
                    "vfpclassps destination must be k1-k7",
                ));
            };
            if mask.code == 0 {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_AVX512_MASK_001",
                    "vfpclassps destination cannot be k0",
                ));
            }
            if let Some(src) = x86_vec_reg(src) {
                if src.width != 512 {
                    return Err(MachineDiagnostic::new(
                        "E_MACHINE_AVX512_VECTOR_LENGTH_001",
                        "vfpclassps Phase 4C DQ form requires zmm source",
                    ));
                }
            } else {
                let Some(mem) = evex_parse_memory_operand(src) else {
                    return Err(MachineDiagnostic::new(
                        "E_MACHINE_AVX512_OPERAND_001",
                        "vfpclassps source must be zmm or m512",
                    ));
                };
                if mem.width != "m512" {
                    return Err(MachineDiagnostic::new(
                        "E_MACHINE_MEM_WIDTH_001",
                        "vfpclassps memory source must be m512",
                    ));
                }
            }
            let Some(value) = parse_int(imm) else {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_IMM_WIDTH_001",
                    "vfpclassps requires an imm8 class mask",
                ));
            };
            if !(0..=255).contains(&value) {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_IMM_WIDTH_001",
                    "vfpclassps immediate must fit imm8",
                ));
            }
            Ok(())
        }
        "vpmovdb" | "vpmovwb" => validate_avx512_pmov_downconvert_operands(inst),
        "vptestnmd" | "vpshufbitqmb" => validate_avx512_k_dest_three_operand(inst),
        _ => Ok(()),
    }
}

fn validate_avx512_k_dest_three_operand(
    inst: &MachineInstruction,
) -> Result<(), MachineDiagnostic> {
    let [dst, src1, src2] = inst.operands.as_slice() else {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_AVX512_OPERAND_001",
            format!("{} requires k, zmm, zmm/m512", inst.mnemonic),
        ));
    };
    let Some(mask) = x86_k_reg(dst) else {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_AVX512_MASK_001",
            format!("{} destination must be k1-k7", inst.mnemonic),
        ));
    };
    if mask.code == 0 {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_AVX512_MASK_001",
            format!("{} destination cannot be k0", inst.mnemonic),
        ));
    }
    let Some(src1) = x86_vec_reg(src1) else {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_REGISTER_CLASS_001",
            format!("{} src1 must be zmm", inst.mnemonic),
        ));
    };
    if src1.width != 512 {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_AVX512_VECTOR_LENGTH_001",
            format!("{} Phase 4D form requires zmm src1", inst.mnemonic),
        ));
    }
    if let Some(src2) = x86_vec_reg(src2) {
        if src2.width != 512 {
            return Err(MachineDiagnostic::new(
                "E_MACHINE_AVX512_VECTOR_LENGTH_001",
                format!("{} Phase 4D form requires zmm src2", inst.mnemonic),
            ));
        }
    } else {
        let Some(mem) = evex_parse_memory_operand(src2) else {
            return Err(MachineDiagnostic::new(
                "E_MACHINE_AVX512_OPERAND_001",
                format!("{} src2 must be zmm or m512", inst.mnemonic),
            ));
        };
        if mem.width != "m512" {
            return Err(MachineDiagnostic::new(
                "E_MACHINE_MEM_WIDTH_001",
                format!("{} memory source must be m512", inst.mnemonic),
            ));
        }
    }
    Ok(())
}

fn validate_avx512_pmov_downconvert_operands(
    inst: &MachineInstruction,
) -> Result<(), MachineDiagnostic> {
    let [dst, src] = inst.operands.as_slice() else {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_AVX512_OPERAND_001",
            format!(
                "{} requires xmm/ymm/memory destination and zmm source",
                inst.mnemonic
            ),
        ));
    };
    let Some(src) = x86_vec_reg(src) else {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_REGISTER_CLASS_001",
            format!("{} source must be zmm", inst.mnemonic),
        ));
    };
    if src.width != 512 {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_AVX512_VECTOR_LENGTH_001",
            format!("{} source must be zmm", inst.mnemonic),
        ));
    }
    let expected_width = if inst.mnemonic == "vpmovdb" {
        "m128"
    } else {
        "m256"
    };
    let expected_vec_width = if inst.mnemonic == "vpmovdb" { 128 } else { 256 };
    if let Some(dst) = evex_parse_vector_operand(dst) {
        if dst.reg.width != expected_vec_width {
            return Err(MachineDiagnostic::new(
                "E_MACHINE_AVX512_VECTOR_LENGTH_001",
                format!(
                    "{} destination width does not match narrowed element pack",
                    inst.mnemonic
                ),
            ));
        }
        if dst.mask.is_some_and(|mask| mask.code == 0) {
            return Err(MachineDiagnostic::new(
                "E_MACHINE_AVX512_MASK_001",
                format!("{} cannot use explicit k0 mask", inst.mnemonic),
            ));
        }
        if dst.zero && dst.mask.is_none() {
            return Err(MachineDiagnostic::new(
                "E_MACHINE_EVEX_ZEROING_001",
                format!("{} zeroing requires k1-k7", inst.mnemonic),
            ));
        }
        return Ok(());
    }
    let Some(mem) = evex_parse_memory_operand(dst) else {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_AVX512_OPERAND_001",
            format!("{} destination must be vector or memory", inst.mnemonic),
        ));
    };
    if mem.width != expected_width {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_MEM_WIDTH_001",
            format!(
                "{} memory destination must be {}",
                inst.mnemonic, expected_width
            ),
        ));
    }
    Ok(())
}

fn push_vex_operand_matrix_diagnostic(
    audit: &mut MachineAudit,
    inst: &MachineInstruction,
    forms: &[VexOperandForm],
) {
    let expected_counts = forms
        .iter()
        .map(|form| form.operand_count.to_string())
        .collect::<BTreeSet<_>>();
    if !expected_counts.contains(&inst.operands.len().to_string()) {
        let min_expected = forms
            .iter()
            .map(|form| form.operand_count as usize)
            .min()
            .unwrap_or(0);
        let code = if forms.iter().any(|form| form.immediate)
            && inst.operands.len().saturating_add(1) == min_expected
        {
            "E_MACHINE_IMM_WIDTH_001"
        } else if inst.operands.len() < min_expected
            && forms
                .iter()
                .any(|form| form.vex_vvvv_policy == "source_register_encoded_in_inverted_vvvv")
        {
            "E_MACHINE_VEX_VVVV_001"
        } else {
            "E_MACHINE_INSTR_OPERAND_001"
        };
        audit.diagnostics.push(MachineDiagnostic::new(
            code,
            format!(
                "{} accepts VEX operand counts [{}], got {}",
                inst.mnemonic,
                expected_counts.into_iter().collect::<Vec<_>>().join("|"),
                inst.operands.len()
            ),
        ));
        return;
    }

    if inst.operands.iter().any(|op| is_bad_vex_memory_width(op)) {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_MEM_WIDTH_001",
            format!("{} requires an allowed VEX memory width", inst.mnemonic),
        ));
        return;
    }
    if inst.mnemonic == "vgatherdps"
        && inst.operands.iter().any(|op| {
            vex_operand_class(op) == "mem32" && parse_x86_vsib_memory_operand(op).is_none()
        })
    {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_SIB_001",
            "vgatherdps requires a VSIB dword memory operand with xmm/ymm index",
        ));
        return;
    }
    if inst.operands.iter().any(|op| {
        matches!(
            vex_operand_class(op).as_str(),
            "mem32" | "mem64" | "mem128" | "mem256"
        ) && parse_x86_memory_operand(op).is_none()
    }) {
        let code = if inst.operands.iter().any(|op| op.contains('*')) {
            "E_MACHINE_SIB_001"
        } else {
            "E_MACHINE_MODRM_001"
        };
        audit.diagnostics.push(MachineDiagnostic::new(
            code,
            format!(
                "{} has an invalid VEX memory addressing encoding form",
                inst.mnemonic
            ),
        ));
        return;
    }
    if inst.operands.iter().any(|op| {
        let class = vex_operand_class(op);
        let width = match class.as_str() {
            "mem32" => Some("m32"),
            "mem64" => Some("m64"),
            "mem128" => Some("m128"),
            "mem256" => Some("m256"),
            _ => None,
        };
        width.is_some_and(|width| {
            !forms
                .iter()
                .any(|form| form.allowed_memory_widths.contains(&width))
        })
    }) {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_MEM_WIDTH_001",
            format!(
                "{} memory operand width is not valid for its VEX matrix",
                inst.mnemonic
            ),
        ));
        return;
    }
    if inst.operands.iter().any(|op| parse_int(op).is_some())
        && !forms.iter().any(|form| form.immediate)
    {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_IMM_WIDTH_001",
            format!("{} does not accept an immediate operand", inst.mnemonic),
        ));
        return;
    }
    if inst
        .operands
        .iter()
        .any(|op| parse_int(op).is_some_and(|imm| !(0..=255).contains(&imm)))
    {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_IMM_WIDTH_001",
            format!("{} immediate must fit imm8", inst.mnemonic),
        ));
        return;
    }
    if inst
        .operands
        .iter()
        .any(|op| register_width(op).is_some() && x86_vec_reg(op).is_none())
    {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_REGISTER_CLASS_001",
            format!("{} requires vector registers in VEX forms", inst.mnemonic),
        ));
        return;
    }

    let widths = inst
        .operands
        .iter()
        .filter_map(|op| x86_vec_reg(op).map(|reg| reg.width))
        .collect::<BTreeSet<_>>();
    if widths.iter().any(|width| *width == 256) && !forms.iter().any(|form| form.ymm) {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_REGISTER_WIDTH_001",
            format!("{} requires xmm width for scalar VEX forms", inst.mnemonic),
        ));
        return;
    }
    if widths.len() > 1 {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_REGISTER_WIDTH_001",
            format!("{} mixes xmm/ymm widths in one VEX form", inst.mnemonic),
        ));
        return;
    }

    audit.diagnostics.push(MachineDiagnostic::new(
        "E_MACHINE_INSTR_OPERAND_001",
        format!("invalid VEX operand form '{}'", inst.text),
    ));
}

fn vex_inst_matches_form(inst: &MachineInstruction, form: &VexOperandForm) -> bool {
    if inst.operands.len() != form.operand_count as usize {
        return false;
    }
    if form.form == "zero_operand" {
        return inst.operands.is_empty();
    }
    let classes = inst
        .operands
        .iter()
        .map(|op| vex_operand_class(op))
        .collect::<Vec<_>>();
    let expected = form.form.split(',').collect::<Vec<_>>();
    if classes.len() != expected.len() {
        return false;
    }
    if form.mnemonic == "vcvtph2ps" {
        return vex_inst_matches_vcvtph2ps(inst, form, &classes);
    }
    if form.mnemonic == "vgatherdps" {
        return vex_inst_matches_vgatherdps(inst, form, &classes);
    }
    for (idx, (class, expected)) in classes.iter().zip(expected.iter()).enumerate() {
        match *expected {
            "reg" => {
                if !matches!(class.as_str(), "xmm" | "ymm") {
                    return false;
                }
            }
            "mem" => {
                if !matches!(class.as_str(), "mem128" | "mem256" | "mem32" | "mem64") {
                    return false;
                }
                if parse_x86_memory_operand(&inst.operands[idx]).is_none() {
                    return false;
                }
                let width = match class.as_str() {
                    "mem32" => "m32",
                    "mem64" => "m64",
                    "mem128" => "m128",
                    "mem256" => "m256",
                    _ => return false,
                };
                if !form.allowed_memory_widths.contains(&width) {
                    return false;
                }
            }
            "imm8" => {
                if class != "imm8" {
                    return false;
                }
            }
            _ => return false,
        }
    }
    if classes.iter().any(|class| class == "bad_mem_width") {
        return false;
    }
    let vec_widths = inst
        .operands
        .iter()
        .filter_map(|op| x86_vec_reg(op).map(|reg| reg.width))
        .collect::<BTreeSet<_>>();
    if vec_widths.len() > 1 {
        return false;
    }
    if let Some(width) = vec_widths.iter().next() {
        if *width == 256 && !form.ymm {
            return false;
        }
        if *width == 128 && !form.xmm {
            return false;
        }
        if *width == 256 && classes.iter().any(|class| class == "mem128") {
            return false;
        }
        if *width == 128 && classes.iter().any(|class| class == "mem256") {
            return false;
        }
    }
    true
}

fn vex_inst_matches_vgatherdps(
    inst: &MachineInstruction,
    form: &VexOperandForm,
    classes: &[String],
) -> bool {
    if form.form != "reg,mem,reg" || classes.len() != 3 {
        return false;
    }
    let (Some(dst), Some(mask)) = (
        x86_vec_reg(&inst.operands[0]),
        x86_vec_reg(&inst.operands[2]),
    ) else {
        return false;
    };
    if dst.width != mask.width {
        return false;
    }
    if (dst.width == 128 && !form.xmm) || (dst.width == 256 && !form.ymm) {
        return false;
    }
    if classes[1] != "mem32" {
        return false;
    }
    parse_x86_vsib_memory_operand(&inst.operands[1]).is_some_and(|mem| mem.index_width == dst.width)
}

fn vex_inst_matches_vcvtph2ps(
    inst: &MachineInstruction,
    form: &VexOperandForm,
    classes: &[String],
) -> bool {
    if !matches!(form.form, "reg,reg" | "reg,mem") || classes.len() != 2 {
        return false;
    }
    let Some(dst) = x86_vec_reg(&inst.operands[0]) else {
        return false;
    };
    if !matches!(dst.width, 128 | 256) {
        return false;
    }
    match classes[1].as_str() {
        "xmm" => true,
        "mem64" => dst.width == 128 && parse_x86_memory_operand(&inst.operands[1]).is_some(),
        "mem128" => dst.width == 256 && parse_x86_memory_operand(&inst.operands[1]).is_some(),
        _ => false,
    }
}

fn vex_operand_class(op: &str) -> String {
    let compact = compact_operand(op);
    if compact.starts_with("zmmword[") {
        return "mem512".to_string();
    }
    if compact.starts_with("xmmword[") {
        return "mem128".to_string();
    }
    if compact.starts_with("ymmword[") {
        return "mem256".to_string();
    }
    if compact.starts_with("dword[") {
        return "mem32".to_string();
    }
    if compact.starts_with("qword[") {
        return "mem64".to_string();
    }
    if compact.starts_with("byte[") || compact.starts_with("word[") {
        return "bad_mem_width".to_string();
    }
    if let Some(reg) = x86_vec_reg(op) {
        return match reg.width {
            128 => "xmm",
            256 => "ymm",
            512 => "zmm",
            _ => "invalid",
        }
        .to_string();
    }
    if parse_int(op).is_some_and(|imm| (0..=255).contains(&imm)) {
        return "imm8".to_string();
    }
    if parse_int(op).is_some() {
        return "bad_imm_width".to_string();
    }
    if register_width(op).is_some() {
        return "scalar_reg".to_string();
    }
    "invalid".to_string()
}

fn is_bad_vex_memory_width(op: &str) -> bool {
    vex_operand_class(op) == "bad_mem_width"
}

fn is_vex_mnemonic(mnemonic: &str) -> bool {
    vex_instruction_def_by_name(mnemonic).is_some()
}

fn is_evex_mnemonic(mnemonic: &str) -> bool {
    EVEX_CARRIER_MNEMONICS.contains(&mnemonic) && evex_instruction_def_by_name(mnemonic).is_some()
}

fn is_avx512_mnemonic(mnemonic: &str) -> bool {
    avx512_instruction_def_by_name(mnemonic).is_some()
}

fn is_avx512_phase4c_or_prior_closed_def(def: &Avx512InstructionDef) -> bool {
    match def.subfeature_owner {
        "AVX512F" => AVX512F_PHASE4B_MNEMONICS.contains(&def.mnemonic),
        "AVX512DQ" => AVX512DQ_PHASE4C_MNEMONICS.contains(&def.mnemonic),
        "AVX512BW" => AVX512BW_PHASE4C_MNEMONICS.contains(&def.mnemonic),
        "AVX512CD" => AVX512CD_PHASE4D_MNEMONICS.contains(&def.mnemonic),
        "AVX512IFMA" => AVX512IFMA_PHASE4D_MNEMONICS.contains(&def.mnemonic),
        "AVX512VBMI" => AVX512VBMI_PHASE4D_MNEMONICS.contains(&def.mnemonic),
        "AVX512VNNI" => AVX512VNNI_PHASE4D_MNEMONICS.contains(&def.mnemonic),
        "AVX512BITALG" => AVX512BITALG_PHASE4D_MNEMONICS.contains(&def.mnemonic),
        "AVX512VPOPCNTDQ" => AVX512VPOPCNTDQ_PHASE4D_MNEMONICS.contains(&def.mnemonic),
        "AVX512FP16" => AVX512FP16_PHASE4D_MNEMONICS.contains(&def.mnemonic),
        _ => false,
    }
}

fn is_avx512_instruction_instance(inst: &MachineInstruction) -> bool {
    is_avx512_mnemonic(&inst.mnemonic)
        && inst.operands.iter().any(|op| {
            let compact = compact_operand(op);
            compact.starts_with("zmm") || compact.starts_with("zmmword")
        })
}

fn is_evex_instruction_instance(inst: &MachineInstruction) -> bool {
    if is_evex_mnemonic(&inst.mnemonic)
        && !VEX_PHASE1_MANIFEST_MNEMONICS.contains(&inst.mnemonic.as_str())
    {
        return true;
    }
    inst.operands.iter().any(|op| {
        let compact = compact_operand(op);
        compact.starts_with("zmm")
            || compact.contains("{k")
            || compact.contains("{z}")
            || compact.contains("{1to")
            || compact.contains("sae")
            || compact.starts_with("zmmword")
    })
}

fn is_known_x86_64_mnemonic(mnemonic: &str) -> bool {
    X86_64_INSTRUCTIONS.contains(&mnemonic)
        || is_vex_mnemonic(mnemonic)
        || is_evex_mnemonic(mnemonic)
        || is_avx512_mnemonic(mnemonic)
}

fn x86_64_manifest_rejection_diagnostic(mnemonic: &str) -> Option<MachineDiagnostic> {
    let mnemonic = mnemonic.trim().to_ascii_lowercase();
    let (code, kind, reason) = if X86_64_VENDOR_PRIVATE_OR_VENDOR_SPECIFIC_OUTSIDE_MANIFEST
        .contains(&mnemonic.as_str())
    {
        (
            "E_MACHINE_VENDOR_PRIVATE_OUTSIDE_MANIFEST_001",
            "vendor-private/vendor-specific",
            "requires an explicitly admitted vendor profile before bytes may be emitted",
        )
    } else if X86_64_OBSOLETE_OR_LONG_MODE_EXCLUDED_OUTSIDE_MANIFEST.contains(&mnemonic.as_str()) {
        (
            "E_MACHINE_OBSOLETE_OUTSIDE_MANIFEST_001",
            "obsolete or excluded from x86_64 long mode",
            "is intentionally outside the declared nC x86_64 machine manifest",
        )
    } else if X86_64_KNOWN_BUT_NOT_ADMITTED_OUTSIDE_MANIFEST.contains(&mnemonic.as_str()) {
        (
            "E_MACHINE_NOT_ADMITTED_OUTSIDE_MANIFEST_001",
            "known external ISA family",
            "must be admitted through the target/profile manifest before use",
        )
    } else if X86_64_ASSEMBLER_ONLY_PSEUDO_OUTSIDE_MANIFEST.contains(&mnemonic.as_str()) {
        (
            "E_MACHINE_ASSEMBLER_PSEUDO_OUTSIDE_MANIFEST_001",
            "assembler-only pseudo spelling",
            "must be represented through nC machine sections, data directives or dialect import before native bytes may be emitted",
        )
    } else {
        return None;
    };
    Some(MachineDiagnostic::new(
        code,
        format!(
            "{} instruction '{}' is rejected: {}",
            kind, mnemonic, reason
        ),
    ))
}

fn validate_immediates(audit: &mut MachineAudit, inst: &MachineInstruction) {
    if inst.mnemonic == "mov" && inst.operands.len() == 2 {
        if let (Some(width), Some(value)) = (
            register_width(&inst.operands[0]),
            parse_int(&inst.operands[1]),
        ) {
            if !machine_immediate_fits_storage_bits(value, width) {
                audit.diagnostics.push(MachineDiagnostic::new(
                    "E_MACHINE_IMMEDIATE_RANGE_001",
                    format!("immediate {} does not fit {}-bit destination", value, width),
                ));
            }
        }
    }
}

fn required_x86_feature(mnemonic: &str) -> Option<&'static str> {
    match mnemonic {
        "vmxon" | "vmxoff" | "vmclear" | "vmptrld" | "vmptrst" | "vmread" | "vmwrite"
        | "vmcall" | "vmlaunch" | "vmresume" => Some("vmx"),
        "invept" => Some("ept"),
        "invvpid" => Some("vpid"),
        "invpcid" => Some("invpcid"),
        "rdfsbase" | "rdgsbase" | "wrfsbase" | "wrgsbase" => Some("fsgsbase"),
        "umonitor" | "umwait" | "tpause" => Some("waitpkg"),
        "serialize" => Some("serialize"),
        "cldemote" => Some("cldemote"),
        "endbr64" | "endbr32" => Some("cet"),
        "rdpkru" | "wrpkru" => Some("pku"),
        "adcx" | "adox" => Some("adx"),
        "rdrand" => Some("rdrand"),
        "rdseed" => Some("rdseed"),
        "vmrun" | "vmmcall" | "vmload" | "vmsave" | "stgi" | "clgi" | "invlpga" => Some("svm"),
        "movaps" | "movups" | "addps" | "subps" | "mulps" | "divps" | "xorps" => Some("sse"),
        "addsd" | "subsd" | "mulsd" | "divsd" => Some("sse2"),
        "andn" | "bextr" | "blsi" | "blsmsk" | "blsr" | "tzcnt" => Some("bmi1"),
        "bzhi" | "mulx" | "pdep" | "pext" | "rorx" | "sarx" | "shlx" | "shrx" => Some("bmi2"),
        "aesenc" | "aesenclast" | "aesdec" | "aesdeclast" | "aesimc" | "aeskeygenassist" => {
            Some("aes")
        }
        "pclmulqdq" => Some("pclmul"),
        "sha1msg1" | "sha1msg2" | "sha1nexte" | "sha1rnds4" | "sha256msg1" | "sha256msg2"
        | "sha256rnds2" => Some("sha"),
        mnemonic if VEX_PHASE1_MANIFEST_MNEMONICS.contains(&mnemonic) => {
            vex_instruction_def_by_name(mnemonic).and_then(|def| def.feature_flags.first().copied())
        }
        _ => None,
    }
}

fn avx512_feature_lower(feature: &str) -> &'static str {
    match feature {
        "AVX512DQ" => "avx512dq",
        "AVX512BW" => "avx512bw",
        "AVX512VL" => "avx512vl",
        "AVX512CD" => "avx512cd",
        "AVX512IFMA" => "avx512ifma",
        "AVX512VBMI" => "avx512vbmi",
        "AVX512VNNI" => "avx512vnni",
        "AVX512BITALG" => "avx512bitalg",
        "AVX512VPOPCNTDQ" => "avx512vpopcntdq",
        "AVX512FP16" => "avx512fp16",
        _ => "avx512f",
    }
}

fn is_avx512_feature_name(feature: &str) -> bool {
    matches!(
        feature,
        "avx512f"
            | "avx512dq"
            | "avx512bw"
            | "avx512vl"
            | "avx512cd"
            | "avx512ifma"
            | "avx512vbmi"
            | "avx512vnni"
            | "avx512bitalg"
            | "avx512vpopcntdq"
            | "avx512fp16"
    )
}

fn avx512_missing_feature_diagnostic(feature: &str) -> &'static str {
    match feature {
        "avx512dq" => "E_MACHINE_AVX512_DQ_REQUIRED_001",
        "avx512bw" => "E_MACHINE_AVX512_BW_REQUIRED_001",
        "avx512vl" => "E_MACHINE_AVX512_VL_REQUIRED_001",
        "avx512cd" => "E_MACHINE_AVX512_CD_REQUIRED_001",
        "avx512ifma" => "E_MACHINE_AVX512_IFMA_REQUIRED_001",
        "avx512vbmi" => "E_MACHINE_AVX512_VBMI_REQUIRED_001",
        "avx512vnni" => "E_MACHINE_AVX512_VNNI_REQUIRED_001",
        "avx512bitalg" => "E_MACHINE_AVX512_BITALG_REQUIRED_001",
        "avx512vpopcntdq" => "E_MACHINE_AVX512_VPOPCNTDQ_REQUIRED_001",
        "avx512fp16" => "E_MACHINE_AVX512_FP16_REQUIRED_001",
        _ => "E_MACHINE_AVX512_FEATURE_REQUIRED_001",
    }
}

fn required_x86_features_for_inst(inst: &MachineInstruction) -> Vec<&'static str> {
    if is_avx512_instruction_instance(inst) && !is_evex_mnemonic(&inst.mnemonic) {
        return avx512_instruction_def_by_name(&inst.mnemonic)
            .map(|def| {
                def.feature_gates
                    .iter()
                    .copied()
                    .map(avx512_feature_lower)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
    }
    if is_evex_instruction_instance(inst) {
        let mut features = evex_instruction_def_by_name(&inst.mnemonic)
            .map(|def| def.feature_flags.to_vec())
            .unwrap_or_else(|| vec!["avx512f"]);
        if !matches!(inst.mnemonic.as_str(), "vpmovdb" | "vpmovwb")
            && inst.operands.iter().any(|op| {
                evex_parse_vector_operand(op)
                    .map(|vec| vec.reg.width < 512)
                    .unwrap_or(false)
            })
        {
            features.push("avx512vl");
        }
        features.sort_unstable();
        features.dedup();
        return features;
    }
    required_x86_feature(&inst.mnemonic).into_iter().collect()
}

fn machine_target_has_feature(audit: &MachineAudit, feature: &str) -> bool {
    audit
        .target
        .get("features")
        .map(|features| {
            features
                .split([',', '|', ' ', '[', ']'])
                .map(|item| item.trim().trim_matches('"').to_ascii_lowercase())
                .any(|item| item == feature)
        })
        .unwrap_or(false)
}

fn validate_label_target(audit: &mut MachineAudit, raw: &str, known_targets: &HashSet<String>) {
    let target = raw.trim().trim_start_matches("label ").trim();
    if parse_int(target).is_none() && !known_targets.contains(target) {
        audit.diagnostics.push(MachineDiagnostic::new(
            "E_MACHINE_LABEL_UNRESOLVED_001",
            format!("unresolved machine label/symbol '{}'", target),
        ));
    }
}

fn operand_tokens(operand: &str) -> Vec<String> {
    operand
        .replace(['[', ']', '+', '-', '*', '(', ')', '{', '}', ':'], " ")
        .split_whitespace()
        .map(|token| token.trim_matches(',').to_ascii_lowercase())
        .filter(|token| !token.is_empty())
        .collect()
}

fn register_width(reg: &str) -> Option<u32> {
    if let Some(gpr) = x86_gpr(reg) {
        return Some(gpr.width);
    }
    if let Some(vec) = x86_vec_reg(reg) {
        return Some(vec.width);
    }
    if x86_k_reg(reg).is_some() {
        return Some(64);
    }
    if x86_mmx_reg(reg).is_some() {
        return Some(64);
    }
    if x86_x87_reg(reg).is_some() {
        return Some(80);
    }
    None
}

fn callee_saved_sysv64() -> &'static [&'static str] {
    &["rbx", "rbp", "r12", "r13", "r14", "r15"]
}

fn parse_int(raw: &str) -> Option<i128> {
    let trimmed = raw
        .trim()
        .trim_end_matches(';')
        .trim_start_matches('$')
        .trim_start_matches('#')
        .trim();
    if trimmed.is_empty() {
        return None;
    }
    let cleaned = trimmed.replace('_', "");
    let (negative, body) = if let Some(rest) = cleaned.strip_prefix('-') {
        (true, rest)
    } else if let Some(rest) = cleaned.strip_prefix('+') {
        (false, rest)
    } else {
        (false, cleaned.as_str())
    };
    if body.is_empty() {
        return None;
    }
    let (radix, digits) = if let Some(hex) = body.strip_prefix("0x") {
        (16, hex)
    } else if let Some(hex) = body.strip_prefix("0X") {
        (16, hex)
    } else if let Some(bin) = body.strip_prefix("0b") {
        (2, bin)
    } else if let Some(bin) = body.strip_prefix("0B") {
        (2, bin)
    } else if let Some(oct) = body.strip_prefix("0o") {
        (8, oct)
    } else if let Some(oct) = body.strip_prefix("0O") {
        (8, oct)
    } else {
        return cleaned.parse::<i128>().ok();
    };
    if digits.is_empty() {
        return None;
    }
    let value = i128::from_str_radix(digits, radix).ok()?;
    if negative {
        value.checked_neg()
    } else {
        Some(value)
    }
}

fn parse_i32(raw: &str) -> Option<i32> {
    parse_int(raw)?.try_into().ok()
}

#[derive(Clone, Copy)]
struct X86FarPointerImmediate {
    selector: u16,
    offset: u32,
    offset_width: u32,
    compat_prefix_16: bool,
}

fn is_x86_far_control_operand(op: &str) -> bool {
    parse_x86_far_pointer_immediate(op, None).is_some()
        || parse_x86_far_memory_operand(op).is_some()
}

fn parse_x86_far_pointer_immediate(
    op: &str,
    forced_width: Option<u32>,
) -> Option<X86FarPointerImmediate> {
    let mut raw = op.trim();
    let lower = raw.to_ascii_lowercase();
    let mut width = forced_width;
    let mut compat_prefix_16 = false;

    for (prefix, parsed_width, needs_compat_prefix) in [
        ("far ptr16:16", 16_u32, true),
        ("ptr16:16", 16_u32, true),
        ("m16:16", 16_u32, true),
        ("far16", 16_u32, false),
        ("far ptr16:32", 32_u32, false),
        ("ptr16:32", 32_u32, false),
        ("m16:32", 32_u32, false),
        ("far32", 32_u32, false),
        ("far", 32_u32, false),
    ] {
        if lower == prefix {
            return None;
        }
        if lower
            .strip_prefix(prefix)
            .is_some_and(|rest| rest.starts_with(char::is_whitespace))
        {
            raw = raw[prefix.len()..].trim();
            width = Some(parsed_width);
            compat_prefix_16 = needs_compat_prefix;
            break;
        }
    }

    let (selector_raw, offset_raw) = raw.split_once(':')?;
    let selector = parse_int(selector_raw.trim())?;
    let offset = parse_int(offset_raw.trim())?;
    if !(0..=i128::from(u16::MAX)).contains(&selector) {
        return None;
    }
    let offset_width = width.unwrap_or(32);
    let offset_max = match offset_width {
        16 => i128::from(u16::MAX),
        32 => i128::from(u32::MAX),
        _ => return None,
    };
    if !(0..=offset_max).contains(&offset) {
        return None;
    }
    Some(X86FarPointerImmediate {
        selector: selector as u16,
        offset: offset as u32,
        offset_width,
        compat_prefix_16,
    })
}

fn parse_x86_far_memory_operand(op: &str) -> Option<(X86MemoryOperand, bool)> {
    let raw = op.trim();
    let lower = raw.to_ascii_lowercase();
    let raw = if lower.starts_with("far ") {
        raw[3..].trim()
    } else {
        raw
    };
    let compact = compact_operand(raw);
    let far64 = compact.starts_with("twordptr")
        || compact.starts_with("tbyteptr")
        || compact.starts_with("tword")
        || compact.starts_with("tbyte")
        || compact.starts_with("m16:64");
    let far_mem = far64
        || compact.starts_with("fwordptr")
        || compact.starts_with("fword")
        || compact.starts_with("m16:16")
        || compact.starts_with("m16:32")
        || lower.starts_with("far ");
    far_mem
        .then(|| parse_x86_memory_operand(raw).map(|mem| (mem, far64)))
        .flatten()
}

fn machine_immediate_fits_storage_bits(value: i128, bits: u32) -> bool {
    if bits == 0 || bits > 64 {
        return false;
    }
    let signed_min = -(1_i128 << (bits - 1));
    let unsigned_max = if bits == 64 {
        i128::from(u64::MAX)
    } else {
        (1_i128 << bits) - 1
    };
    (signed_min..=unsigned_max).contains(&value)
}

fn machine_immediate_to_u64_bits(value: i128) -> Option<u64> {
    if !machine_immediate_fits_storage_bits(value, 64) {
        return None;
    }
    if value < 0 {
        Some((value as i64) as u64)
    } else {
        Some(value as u64)
    }
}

fn audit_arch(audit: &MachineAudit) -> &str {
    audit
        .target
        .get("arch")
        .map(String::as_str)
        .unwrap_or("x86_64")
}

fn audit_object_format(audit: &MachineAudit) -> &str {
    audit
        .target
        .get("object")
        .map(String::as_str)
        .unwrap_or("elf64")
}

fn aarch64_reg_number(reg: &str) -> Option<u8> {
    match reg {
        "fp" => Some(29),
        "lr" => Some(30),
        "sp" | "xzr" | "wzr" => Some(31),
        _ if reg.starts_with('x') || reg.starts_with('w') => reg
            .get(1..)
            .and_then(|num| num.parse::<u8>().ok())
            .filter(|num| *num <= 30),
        _ => None,
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Aarch64VecArrangement {
    B16,
    S4,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Aarch64SveElement {
    B,
    H,
    S,
    D,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Aarch64FpWidth {
    S,
    D,
}

#[derive(Clone, Copy)]
struct Aarch64VecReg {
    code: u32,
    arrangement: Aarch64VecArrangement,
}

fn aarch64_gpr_width(reg: &str) -> Option<u32> {
    let reg = reg.trim().to_ascii_lowercase();
    match reg.as_str() {
        "wzr" => Some(32),
        "xzr" | "sp" | "fp" | "lr" => Some(64),
        _ if reg.starts_with('w') => aarch64_reg_number(&reg).map(|_| 32),
        _ if reg.starts_with('x') => aarch64_reg_number(&reg).map(|_| 64),
        _ => None,
    }
}

fn aarch64_vec_reg(raw: &str) -> Option<Aarch64VecReg> {
    let cleaned = raw
        .trim()
        .trim_start_matches('{')
        .trim_end_matches('}')
        .to_ascii_lowercase();
    let (base, arrangement) = cleaned.split_once('.')?;
    let code = base
        .strip_prefix('v')?
        .parse::<u32>()
        .ok()
        .filter(|num| *num <= 31)?;
    let arrangement = match arrangement {
        "16b" => Aarch64VecArrangement::B16,
        "4s" => Aarch64VecArrangement::S4,
        _ => return None,
    };
    Some(Aarch64VecReg { code, arrangement })
}

fn aarch64_q_reg(raw: &str) -> Option<u32> {
    raw.trim()
        .to_ascii_lowercase()
        .strip_prefix('q')?
        .parse::<u32>()
        .ok()
        .filter(|num| *num <= 31)
}

fn aarch64_fp_reg(raw: &str) -> Option<(u32, Aarch64FpWidth)> {
    let cleaned = raw.trim().to_ascii_lowercase();
    let (prefix, rest) = cleaned.split_at(1);
    let width = match prefix {
        "s" => Aarch64FpWidth::S,
        "d" => Aarch64FpWidth::D,
        _ => return None,
    };
    let reg = rest.parse::<u32>().ok().filter(|num| *num <= 31)?;
    Some((reg, width))
}

fn aarch64_vec_lane_s(raw: &str) -> Option<(u32, u32)> {
    let cleaned = raw.trim().replace(['{', '}'], "").to_ascii_lowercase();
    let (base, lane) = cleaned.split_once(".s[")?;
    let reg = base
        .strip_prefix('v')?
        .parse::<u32>()
        .ok()
        .filter(|num| *num <= 31)?;
    let lane = lane.strip_suffix(']')?.parse::<u32>().ok()?;
    if lane > 3 {
        return None;
    }
    Some((reg, lane))
}

fn aarch64_sve_element(raw: &str) -> Option<Aarch64SveElement> {
    match raw {
        "b" => Some(Aarch64SveElement::B),
        "h" => Some(Aarch64SveElement::H),
        "s" => Some(Aarch64SveElement::S),
        "d" => Some(Aarch64SveElement::D),
        _ => None,
    }
}

fn aarch64_sve_element_bits(elem: Aarch64SveElement) -> u32 {
    match elem {
        Aarch64SveElement::B => 0,
        Aarch64SveElement::H => 1,
        Aarch64SveElement::S => 2,
        Aarch64SveElement::D => 3,
    }
}

fn aarch64_sve_predicate_elem(raw: &str) -> Option<(u32, Aarch64SveElement)> {
    let cleaned = raw.trim().to_ascii_lowercase();
    let (reg, elem) = cleaned.split_once('.')?;
    let pred = reg
        .strip_prefix('p')?
        .parse::<u32>()
        .ok()
        .filter(|num| *num <= 15)?;
    Some((pred, aarch64_sve_element(elem)?))
}

fn aarch64_sve_predicate(raw: &str, required_policy: Option<&str>) -> Option<u32> {
    let cleaned = raw.trim().to_ascii_lowercase();
    let (reg, policy) = cleaned
        .split_once('/')
        .map(|(reg, policy)| (reg, Some(policy)))
        .unwrap_or((cleaned.as_str(), None));
    if policy != required_policy {
        return None;
    }
    reg.strip_prefix('p')?
        .parse::<u32>()
        .ok()
        .filter(|num| *num <= 7)
}

fn aarch64_sve_z_reg(raw: &str) -> Option<(u32, Aarch64SveElement)> {
    let cleaned = raw
        .trim()
        .replace(['{', '}'], "")
        .split_whitespace()
        .collect::<String>()
        .to_ascii_lowercase();
    let (reg, elem) = cleaned.split_once('.')?;
    let z = reg
        .strip_prefix('z')?
        .parse::<u32>()
        .ok()
        .filter(|num| *num <= 31)?;
    Some((z, aarch64_sve_element(elem)?))
}

