fn riscv_fp_reg_number(reg: &str) -> Option<u8> {
    let reg = reg.trim().to_ascii_lowercase();
    let num = reg.strip_prefix('f')?.parse::<u8>().ok()?;
    (num <= 31).then_some(num)
}

fn thumb_register(raw: &str) -> Option<ThumbRegister> {
    let cleaned = raw
        .trim()
        .trim_matches(|ch| matches!(ch, '[' | ']' | '{' | '}' | '!'))
        .to_ascii_lowercase();
    match cleaned.as_str() {
        "sp" => Some(ThumbRegister::Sp),
        "lr" => Some(ThumbRegister::Lr),
        "pc" => Some(ThumbRegister::Pc),
        value => value
            .strip_prefix('r')?
            .parse::<u8>()
            .ok()
            .and_then(|value| ThumbRegister::from_u8(value).ok()),
    }
}

fn thumb_immediate(raw: &str) -> Option<i64> {
    parse_int(raw).and_then(|value| i64::try_from(value).ok())
}

fn thumb_cps_effects(raw: &str) -> Option<(bool, bool, bool)> {
    let mask = raw.trim().to_ascii_lowercase();
    if mask.is_empty() || mask.chars().any(|ch| !matches!(ch, 'a' | 'i' | 'f')) {
        return None;
    }
    let async_abort = mask.contains('a');
    let irq = mask.contains('i');
    let fiq = mask.contains('f');
    (async_abort || irq || fiq).then_some((async_abort, irq, fiq))
}

fn thumb_special_register(raw: &str) -> Option<ThumbSpecialRegister> {
    match raw.trim().to_ascii_lowercase().as_str() {
        "apsr" => Some(ThumbSpecialRegister::Apsr),
        "iapsr" => Some(ThumbSpecialRegister::Iapsr),
        "eapsr" => Some(ThumbSpecialRegister::Eapsr),
        "xpsr" => Some(ThumbSpecialRegister::Xpsr),
        "ipsr" => Some(ThumbSpecialRegister::Ipsr),
        "epsr" => Some(ThumbSpecialRegister::Epsr),
        "iepsr" => Some(ThumbSpecialRegister::Iepsr),
        "msp" => Some(ThumbSpecialRegister::Msp),
        "psp" => Some(ThumbSpecialRegister::Psp),
        "primask" => Some(ThumbSpecialRegister::Primask),
        "basepri" => Some(ThumbSpecialRegister::Basepri),
        "basepri_max" | "baseprimax" => Some(ThumbSpecialRegister::BasepriMax),
        "faultmask" => Some(ThumbSpecialRegister::Faultmask),
        "control" => Some(ThumbSpecialRegister::Control),
        _ => None,
    }
}

fn thumb_condition(mnemonic: &str) -> Option<ncc_machine::ThumbCondition> {
    use ncc_machine::ThumbCondition::*;
    match mnemonic {
        "beq" => Some(Eq),
        "bne" => Some(Ne),
        "bcs" | "bhs" => Some(Cs),
        "bcc" | "blo" => Some(Cc),
        "bmi" => Some(Mi),
        "bpl" => Some(Pl),
        "bvs" => Some(Vs),
        "bvc" => Some(Vc),
        "bhi" => Some(Hi),
        "bls" => Some(Ls),
        "bge" => Some(Ge),
        "blt" => Some(Lt),
        "bgt" => Some(Gt),
        "ble" => Some(Le),
        _ => None,
    }
}

fn thumb_register_list(operands: &[String], pop: bool) -> Option<(u8, bool)> {
    let mut mask = 0u8;
    let mut special = false;
    for operand in operands {
        let cleaned = operand
            .trim()
            .trim_matches(|ch| matches!(ch, '{' | '}' | ' '));
        let register = thumb_register(cleaned)?;
        match register {
            ThumbRegister::R0
            | ThumbRegister::R1
            | ThumbRegister::R2
            | ThumbRegister::R3
            | ThumbRegister::R4
            | ThumbRegister::R5
            | ThumbRegister::R6
            | ThumbRegister::R7 => mask |= 1 << (register as u8),
            ThumbRegister::Lr if !pop => special = true,
            ThumbRegister::Pc if pop => special = true,
            _ => return None,
        }
    }
    (mask != 0 || special).then_some((mask, special))
}

fn machine_thumb_instruction(
    inst: &MachineInstruction,
) -> Result<Option<ThumbInstruction>, String> {
    let ops = &inst.operands;
    let imm8 = |index: usize| -> Result<u8, String> {
        let value = ops
            .get(index)
            .and_then(|raw| thumb_immediate(raw))
            .ok_or_else(|| "expected an 8-bit immediate".to_string())?;
        u8::try_from(value).map_err(|_| "8-bit immediate is out of range".to_string())
    };
    let register = |index: usize| -> Result<ThumbRegister, String> {
        ops.get(index)
            .and_then(|raw| thumb_register(raw))
            .ok_or_else(|| format!("operand {} must be a Thumb register", index + 1))
    };
    let result = match inst.mnemonic.as_str() {
        "label" => return Ok(None),
        "nop" if ops.is_empty() => ThumbInstruction::Nop,
        "mov" | "movs" if ops.len() == 2 => {
            if let Some(immediate) = ops.get(1).and_then(|raw| thumb_immediate(raw)) {
                ThumbInstruction::MovImmediate {
                    destination: register(0)?,
                    immediate: u8::try_from(immediate)
                        .map_err(|_| "mov immediate is out of range")?,
                }
            } else {
                ThumbInstruction::MoveRegister {
                    destination: register(0)?,
                    source: register(1)?,
                }
            }
        }
        "movw" | "movt" if ops.len() == 2 => {
            let immediate = ops
                .get(1)
                .and_then(|raw| thumb_immediate(raw))
                .and_then(|value| u16::try_from(value).ok())
                .ok_or_else(|| "movw/movt expects a 16-bit immediate".to_string())?;
            if inst.mnemonic == "movw" {
                ThumbInstruction::MoveWide {
                    destination: register(0)?,
                    immediate,
                }
            } else {
                ThumbInstruction::MoveTop {
                    destination: register(0)?,
                    immediate,
                }
            }
        }
        "cmp" if ops.len() == 2 => {
            if let Some(immediate) = ops.get(1).and_then(|raw| thumb_immediate(raw)) {
                ThumbInstruction::CompareImmediate {
                    register: register(0)?,
                    immediate: u8::try_from(immediate)
                        .map_err(|_| "cmp immediate is out of range")?,
                }
            } else {
                ThumbInstruction::CompareRegister {
                    left: register(0)?,
                    right: register(1)?,
                }
            }
        }
        "add" | "adds" if ops.len() == 2 => ThumbInstruction::AddImmediate {
            register: register(0)?,
            immediate: imm8(1)?,
        },
        "sub" | "subs" if ops.len() == 2 => ThumbInstruction::SubImmediate {
            register: register(0)?,
            immediate: imm8(1)?,
        },
        "and" | "ands" if ops.len() == 2 => ThumbInstruction::AndRegister {
            destination: register(0)?,
            source: register(1)?,
        },
        "orr" | "orrs" if ops.len() == 2 => ThumbInstruction::OrRegister {
            destination: register(0)?,
            source: register(1)?,
        },
        "eor" | "eors" if ops.len() == 2 => ThumbInstruction::XorRegister {
            destination: register(0)?,
            source: register(1)?,
        },
        "tst" if ops.len() == 2 => ThumbInstruction::TestRegister {
            left: register(0)?,
            right: register(1)?,
        },
        "mul" | "muls" if ops.len() == 2 || ops.len() == 3 => ThumbInstruction::MultiplyRegister {
            destination: register(0)?,
            source: register(if ops.len() == 3 { 1 } else { 1 })?,
        },
        "lsl" | "lsls" | "lsr" | "lsrs" | "asr" | "asrs" if ops.len() == 2 || ops.len() == 3 => {
            let source_index = usize::from(ops.len() == 3);
            let immediate_index = ops.len() - 1;
            let destination = register(0)?;
            let source = if ops.len() == 3 {
                register(source_index)?
            } else {
                destination
            };
            let immediate = imm8(immediate_index)?;
            match inst.mnemonic.as_str() {
                "lsl" | "lsls" => ThumbInstruction::ShiftLeftImmediate {
                    destination,
                    source,
                    immediate,
                },
                "lsr" | "lsrs" => ThumbInstruction::ShiftRightImmediate {
                    destination,
                    source,
                    immediate,
                },
                _ => ThumbInstruction::ShiftArithmeticRightImmediate {
                    destination,
                    source,
                    immediate,
                },
            }
        }
        "qadd" if ops.len() == 3 => ThumbInstruction::SaturatingAdd {
            destination: register(0)?,
            left: register(1)?,
            right: register(2)?,
        },
        "qsub" if ops.len() == 3 => ThumbInstruction::SaturatingSub {
            destination: register(0)?,
            left: register(1)?,
            right: register(2)?,
        },
        "ssat" if ops.len() == 3 => ThumbInstruction::SignedSaturate {
            destination: register(0)?,
            bits: imm8(1)?,
            source: register(2)?,
        },
        "usat" if ops.len() == 3 => ThumbInstruction::UnsignedSaturate {
            destination: register(0)?,
            bits: imm8(1)?,
            source: register(2)?,
        },
        "ldr" | "str" | "ldrb" | "strb" | "ldrh" | "strh" if ops.len() >= 2 => {
            let target = register(0)?;
            let base = register(1)?;
            let byte_offset = ops.get(2).and_then(|raw| thumb_immediate(raw)).unwrap_or(0);
            if byte_offset < 0 {
                return Err("Thumb compact load/store offset cannot be negative".into());
            }
            match inst.mnemonic.as_str() {
                "ldr" => ThumbInstruction::LoadWord {
                    target,
                    base,
                    word_offset: u8::try_from(byte_offset / 4)
                        .map_err(|_| "word offset is out of range")?,
                },
                "str" => ThumbInstruction::StoreWord {
                    source: target,
                    base,
                    word_offset: u8::try_from(byte_offset / 4)
                        .map_err(|_| "word offset is out of range")?,
                },
                "ldrb" => ThumbInstruction::LoadByte {
                    target,
                    base,
                    offset: u8::try_from(byte_offset).map_err(|_| "byte offset is out of range")?,
                },
                "strb" => ThumbInstruction::StoreByte {
                    source: target,
                    base,
                    offset: u8::try_from(byte_offset).map_err(|_| "byte offset is out of range")?,
                },
                "ldrh" => ThumbInstruction::LoadHalf {
                    target,
                    base,
                    half_offset: u8::try_from(byte_offset / 2)
                        .map_err(|_| "halfword offset is out of range")?,
                },
                _ => ThumbInstruction::StoreHalf {
                    source: target,
                    base,
                    half_offset: u8::try_from(byte_offset / 2)
                        .map_err(|_| "halfword offset is out of range")?,
                },
            }
        }
        "push" | "pop" => {
            let pop = inst.mnemonic == "pop";
            let (mask, special) = thumb_register_list(ops, pop)
                .ok_or_else(|| "push/pop requires r0..r7 and optional lr/pc".to_string())?;
            if pop {
                ThumbInstruction::Pop {
                    low_register_mask: mask,
                    pc: special,
                }
            } else {
                ThumbInstruction::Push {
                    low_register_mask: mask,
                    link: special,
                }
            }
        }
        "b" if ops.len() == 1 => ThumbInstruction::Branch {
            offset: thumb_immediate(&ops[0])
                .and_then(|value| i32::try_from(value).ok())
                .unwrap_or(0),
        },
        "bl" if ops.len() == 1 => ThumbInstruction::BranchLink {
            offset: thumb_immediate(&ops[0])
                .and_then(|value| i32::try_from(value).ok())
                .unwrap_or(0),
        },
        mnemonic if thumb_condition(mnemonic).is_some() && ops.len() == 1 => {
            ThumbInstruction::BranchConditional {
                condition: thumb_condition(mnemonic).unwrap(),
                offset: thumb_immediate(&ops[0])
                    .and_then(|value| i16::try_from(value).ok())
                    .unwrap_or(0),
            }
        }
        "bx" if ops.len() == 1 => ThumbInstruction::BranchExchange(register(0)?),
        "blx" if ops.len() == 1 => ThumbInstruction::BranchLinkExchange(register(0)?),
        "mrs" if ops.len() == 2 => ThumbInstruction::ReadSpecial {
            destination: register(0)?,
            special: thumb_special_register(&ops[1])
                .ok_or_else(|| format!("unknown Thumb special register '{}'", ops[1]))?,
        },
        "msr" if ops.len() == 2 => ThumbInstruction::WriteSpecial {
            special: thumb_special_register(&ops[0])
                .ok_or_else(|| format!("unknown Thumb special register '{}'", ops[0]))?,
            source: register(1)?,
        },
        "rbit" if ops.len() == 2 => ThumbInstruction::ReverseBits {
            destination: register(0)?,
            source: register(1)?,
        },
        "clz" if ops.len() == 2 => ThumbInstruction::CountLeadingZeros {
            destination: register(0)?,
            source: register(1)?,
        },
        "rev" if ops.len() == 2 => ThumbInstruction::ReverseBytes {
            destination: register(0)?,
            source: register(1)?,
        },
        "rev16" if ops.len() == 2 => ThumbInstruction::ReverseBytesInHalfwords {
            destination: register(0)?,
            source: register(1)?,
        },
        "revsh" if ops.len() == 2 => ThumbInstruction::ReverseSignedHalfword {
            destination: register(0)?,
            source: register(1)?,
        },
        "ldrex" if ops.len() >= 2 => ThumbInstruction::LoadExclusive {
            target: register(0)?,
            base: register(1)?,
            word_offset: ops
                .get(2)
                .and_then(|raw| thumb_immediate(raw))
                .map(|value| u8::try_from(value / 4))
                .transpose()
                .map_err(|_| "ldrex offset is out of range")?
                .unwrap_or(0),
        },
        "strex" if ops.len() >= 3 => ThumbInstruction::StoreExclusive {
            status: register(0)?,
            source: register(1)?,
            base: register(2)?,
            word_offset: ops
                .get(3)
                .and_then(|raw| thumb_immediate(raw))
                .map(|value| u8::try_from(value / 4))
                .transpose()
                .map_err(|_| "strex offset is out of range")?
                .unwrap_or(0),
        },
        "clrex" if ops.is_empty() => ThumbInstruction::ClearExclusive,
        "setend" if ops.first().is_some_and(|operand| operand == "be") => {
            ThumbInstruction::SetEndianBig
        }
        "setend" if ops.first().is_some_and(|operand| operand == "le") => {
            ThumbInstruction::SetEndianLittle
        }
        "svc" if ops.len() == 1 => ThumbInstruction::SupervisorCall(imm8(0)?),
        "hvc" if ops.len() == 1 => {
            let immediate = ops
                .first()
                .and_then(|raw| thumb_immediate(raw))
                .and_then(|value| u16::try_from(value).ok())
                .ok_or_else(|| "hvc expects a 16-bit immediate".to_string())?;
            ThumbInstruction::HypervisorCall(immediate)
        }
        "smc" if ops.len() == 1 => ThumbInstruction::SecureMonitorCall(imm8(0)?),
        "bkpt" if ops.len() == 1 => ThumbInstruction::Breakpoint(imm8(0)?),
        "udf" if ops.len() == 1 => ThumbInstruction::Undefined(imm8(0)?),
        "dbg" if ops.len() == 1 => ThumbInstruction::DebugHint(imm8(0)?),
        "dmb" => ThumbInstruction::DataMemoryBarrier,
        "dsb" => ThumbInstruction::DataSyncBarrier,
        "isb" => ThumbInstruction::InstructionSyncBarrier,
        "yield" if ops.is_empty() => ThumbInstruction::Yield,
        "wfi" => ThumbInstruction::WaitForInterrupt,
        "wfe" => ThumbInstruction::WaitForEvent,
        "sev" => ThumbInstruction::SendEvent,
        "cpsid" | "cpsie" if ops.len() == 1 => {
            let (affect_async_abort, affect_irq, affect_fiq) = thumb_cps_effects(&ops[0])
                .ok_or_else(|| {
                    "cpsid/cpsie expects a non-empty combination of a, i and f".to_string()
                })?;
            ThumbInstruction::ChangeProcessorState {
                enable: inst.mnemonic == "cpsie",
                affect_async_abort,
                affect_irq,
                affect_fiq,
            }
        }
        _ => return Err(format!("unsupported Thumb-2 form '{}'", inst.text)),
    };
    Ok(Some(result))
}

fn validate_thumb_instructions(audit: &mut MachineAudit) {
    for instruction in audit.instructions.clone() {
        if let Err(message) = machine_thumb_instruction(&instruction).and_then(|instruction| {
            instruction
                .map(|instruction| encode_thumb(&[instruction]).map(|_| ()))
                .transpose()
                .map_err(|error| error.to_string())
                .map(|_| ())
        }) {
            audit
                .diagnostics
                .push(MachineDiagnostic::new("E_MACHINE_ARMV7_001", message));
        }
    }
}

fn encode_thumb_instructions(
    instructions: &[MachineInstruction],
    diagnostics: &mut Vec<MachineDiagnostic>,
) -> Vec<u8> {
    let mut output = Vec::new();
    for instruction in instructions {
        match machine_thumb_instruction(instruction) {
            Ok(Some(instruction)) => match encode_thumb(&[instruction]) {
                Ok(bytes) => output.extend(bytes),
                Err(error) => diagnostics.push(MachineDiagnostic::new(
                    "E_MACHINE_ARMV7_ENCODE_001",
                    error.to_string(),
                )),
            },
            Ok(None) => {}
            Err(message) => diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_ARMV7_ENCODE_001",
                message,
            )),
        }
    }
    output
}

fn encode_instructions_for_arch(
    arch: &str,
    instructions: &[MachineInstruction],
    diagnostics: &mut Vec<MachineDiagnostic>,
) -> Vec<u8> {
    match arch {
        "x86_64" => encode_x86_64_instructions(instructions, diagnostics),
        "aarch64" => encode_aarch64_instructions(instructions, diagnostics),
        "armv7" | "armv7em" | "thumb" | "thumb2" => {
            encode_thumb_instructions(instructions, diagnostics)
        }
        "riscv64" => encode_riscv64_instructions(instructions, diagnostics),
        "riscv32" => encode_riscv32_instructions(instructions, diagnostics),
        "i386" => encode_i386_instructions(instructions, diagnostics),
        "wasm32" => encode_wasm32_module(instructions),
        _ => Vec::new(),
    }
}

