fn x86_segment_prefix(segment: &str) -> Option<u8> {
    match segment.to_ascii_lowercase().as_str() {
        "es" => Some(0x26),
        "cs" => Some(0x2e),
        "ss" => Some(0x36),
        "ds" => Some(0x3e),
        "fs" => Some(0x64),
        "gs" => Some(0x65),
        _ => None,
    }
}

const X86_MEMORY_WIDTH_PREFIXES: &[&str] = &[
    "zmmwordptr",
    "m16:64",
    "m16:32",
    "m16:16",
    "zwordptr",
    "xmmwordptr",
    "ymmwordptr",
    "mmwordptr",
    "fwordptr",
    "twordptr",
    "tbyteptr",
    "owordptr",
    "qwordptr",
    "dwordptr",
    "wordptr",
    "byteptr",
    "ptr",
    "zmmword",
    "zword",
    "xmmword",
    "ymmword",
    "mmword",
    "fword",
    "tword",
    "tbyte",
    "oword",
    "qword",
    "dword",
    "word",
    "byte",
];

fn x86_memory_surface(op: &str) -> Option<(Option<u8>, String, bool)> {
    let compact = evex_strip_memory_decorators(&compact_operand(op));
    x86_memory_surface_from_compact(compact, false)
}

fn x86_memory_surface_from_compact(
    compact: String,
    address_size_32: bool,
) -> Option<(Option<u8>, String, bool)> {
    let (mem, address_size_32) = strip_x86_memory_prefixes_compact(compact, address_size_32);
    if let Some((segment, rest)) = mem.split_once(':') {
        let prefix = x86_segment_prefix(segment)?;
        let (rest, address_size_32) =
            strip_x86_memory_prefixes_compact(rest.to_string(), address_size_32);
        return rest
            .starts_with('[')
            .then_some((Some(prefix), rest, address_size_32));
    }
    Some((None, mem, address_size_32))
}

fn strip_x86_memory_prefixes_compact(mut mem: String, mut address_size_32: bool) -> (String, bool) {
    loop {
        if let Some(rest) = strip_x86_address_size_prefix(&mem) {
            address_size_32 = true;
            mem = rest.to_string();
            continue;
        }
        if let Some(rest) = X86_MEMORY_WIDTH_PREFIXES
            .iter()
            .find_map(|prefix| mem.strip_prefix(prefix))
        {
            mem = rest.to_string();
            continue;
        }
        return (mem, address_size_32);
    }
}

fn strip_x86_address_size_prefix(mem: &str) -> Option<&str> {
    ["addr32", "a32"].into_iter().find_map(|prefix| {
        let rest = mem.strip_prefix(prefix)?;
        (rest.starts_with('[')
            || rest.starts_with("moffs")
            || X86_MEMORY_WIDTH_PREFIXES
                .iter()
                .any(|width| rest.starts_with(width))
            || ["es:", "cs:", "ss:", "ds:", "fs:", "gs:"]
                .iter()
                .any(|segment| rest.starts_with(segment)))
        .then_some(rest)
    })
}

