#[allow(clippy::too_many_arguments)]
fn evex_def(
    mnemonic: &'static str,
    family: &'static str,
    extension_owner: &'static str,
    opcode_map: &'static str,
    opcode: u8,
    pp: &'static str,
    w: u8,
    tuple_type: &'static str,
    operand_forms: &'static [&'static str],
    allow_broadcast: bool,
    allow_rounding: bool,
) -> EvexInstructionDef {
    let _ = (allow_broadcast, allow_rounding);
    EvexInstructionDef {
        mnemonic,
        aliases: &[],
        family,
        extension_owner,
        opcode_map,
        opcode,
        pp: evex_pp_bits(pp),
        w,
        ll_policy: "128|256|512",
        b_policy: if matches!(tuple_type, "full_or_m32bcst" | "full_or_m64bcst") {
            "broadcast_or_rounding_contextual"
        } else {
            "forbidden"
        },
        aaa_policy: "k0_no_mask_or_k1_k7_explicit_mask",
        z_policy: "zeroing_requires_explicit_k1_k7_mask",
        tuple_type,
        operand_forms,
        feature_flags: evex_feature_flags(extension_owner),
        closed_as_evex_carrier: true,
    }
}

fn evex_feature_flags(extension_owner: &str) -> &'static [&'static str] {
    match extension_owner {
        "AVX512DQ" => &["avx512dq"],
        "AVX512BW" => &["avx512bw"],
        "AVX512VL" => &["avx512vl"],
        "AVX512CD" => &["avx512cd"],
        "AVX512IFMA" => &["avx512ifma"],
        "AVX512VBMI" => &["avx512vbmi"],
        "AVX512VNNI" => &["avx512vnni"],
        "AVX512BITALG" => &["avx512bitalg"],
        "AVX512VPOPCNTDQ" => &["avx512vpopcntdq"],
        "AVX512FP16" => &["avx512fp16"],
        _ => &["avx512f"],
    }
}

fn evex_instruction_def_by_name(mnemonic: &str) -> Option<EvexInstructionDef> {
    evex_instruction_defs()
        .into_iter()
        .find(|def| def.mnemonic == mnemonic)
}

fn evex_encoding_spec(def: &EvexInstructionDef) -> EvexEncodingSpec {
    EvexEncodingSpec {
        opcode: def.opcode,
        map: evex_map_bits(def.opcode_map),
        pp: def.pp,
        w: def.w,
        tuple_scale: 64,
        allow_broadcast: matches!(def.tuple_type, "full_or_m32bcst" | "full_or_m64bcst"),
        allow_rounding: def.b_policy == "broadcast_or_rounding_contextual",
    }
}

fn evex_pp_bits(pp: &str) -> u8 {
    match pp {
        "66" => 1,
        "F3" => 2,
        "F2" => 3,
        _ => 0,
    }
}

fn evex_map_bits(map: &str) -> u8 {
    match map {
        "0F" => 1,
        "0F38" => 2,
        "0F3A" => 3,
        "MAP5" => 5,
        _ => 0,
    }
}

fn evex_parse_vector_operand(op: &str) -> Option<EvexVectorOperand> {
    let compact = compact_operand(op);
    let base = compact.split('{').next().unwrap_or("");
    let reg = x86_vec_reg(base)?;
    let mut mask = None;
    let mut zero = false;
    let mut rounding = None;
    let mut sae = false;
    for part in compact.split('{').skip(1) {
        let field = part.split('}').next().unwrap_or("");
        if let Some(k) = x86_k_reg(field) {
            mask = Some(k);
        } else if field == "z" {
            zero = true;
        } else if matches!(field, "rn-sae" | "rd-sae" | "ru-sae" | "rz-sae") {
            rounding = Some(match field {
                "rn-sae" => "rn-sae",
                "rd-sae" => "rd-sae",
                "ru-sae" => "ru-sae",
                _ => "rz-sae",
            });
            sae = true;
        } else if field == "sae" {
            sae = true;
        }
    }
    Some(EvexVectorOperand {
        reg,
        mask,
        zero,
        rounding,
        sae,
    })
}

fn evex_parse_memory_operand(op: &str) -> Option<EvexMemoryOperand> {
    let compact = compact_operand(op);
    let broadcast = if compact.contains("{1to16}") {
        Some("1to16")
    } else if compact.contains("{1to8}") {
        Some("1to8")
    } else if compact.contains("{1to4}") {
        Some("1to4")
    } else if compact.contains("{1to2}") {
        Some("1to2")
    } else {
        None
    };
    let stripped = evex_strip_memory_decorators(&compact);
    let width = if stripped.starts_with("zmmword") || stripped.starts_with("zword") {
        "m512"
    } else if stripped.starts_with("ymmword") {
        "m256"
    } else if stripped.starts_with("xmmword") || stripped.starts_with("oword") {
        "m128"
    } else if stripped.starts_with("qword") {
        "m64"
    } else if stripped.starts_with("dword") {
        "m32"
    } else {
        return None;
    };
    Some(EvexMemoryOperand {
        mem: parse_x86_memory_operand(op)?,
        width,
        broadcast,
    })
}

fn evex_memory_mask(op: &str) -> Option<X86KReg> {
    let compact = compact_operand(op);
    compact
        .split('{')
        .skip(1)
        .filter_map(|part| part.split('}').next())
        .find_map(x86_k_reg)
}

fn evex_ll_bits(width: u32) -> Option<u8> {
    match width {
        128 => Some(0),
        256 => Some(1),
        512 => Some(2),
        _ => None,
    }
}

fn evex_memory_width_matches(width: u32, mem: &EvexMemoryOperand, broadcast: bool) -> bool {
    if broadcast {
        return matches!(
            (width, mem.width, mem.broadcast),
            (512, "m32", Some("1to16")) | (512, "m64", Some("1to8"))
        );
    }
    matches!(
        (width, mem.width),
        (128, "m128") | (256, "m256") | (512, "m512")
    )
}

fn evex_tuple_scale(width: u32, broadcast: bool) -> Option<i32> {
    if broadcast {
        return Some(4);
    }
    match width {
        128 => Some(16),
        256 => Some(32),
        512 => Some(64),
        _ => None,
    }
}

fn validate_evex_form(
    inst: &MachineInstruction,
    def: &EvexInstructionDef,
) -> Result<(), MachineDiagnostic> {
    let spec = evex_encoding_spec(def);
    let Some(dst) = inst
        .operands
        .first()
        .and_then(|op| evex_parse_vector_operand(op))
    else {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_REGISTER_CLASS_001",
            format!("{} requires an EVEX vector destination", inst.mnemonic),
        ));
    };
    if dst.mask.is_some_and(|mask| mask.code == 0) {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_EVEX_MASK_001",
            "explicit EVEX k0 mask is forbidden; omit the mask for no-mask semantics",
        ));
    }
    if dst.zero && dst.mask.is_none() {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_EVEX_ZEROING_001",
            "EVEX zeroing requires an explicit k1-k7 mask",
        ));
    }
    if (dst.rounding.is_some() || dst.sae) && !spec.allow_rounding {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_EVEX_ROUNDING_001",
            format!("{} does not allow EVEX rounding/SAE", inst.mnemonic),
        ));
    }
    match inst.operands.as_slice() {
        [_, src]
            if matches!(
                def.mnemonic,
                "vmovdqa32" | "vmovdqu32" | "vpconflictd" | "vpopcntb" | "vpopcntd" | "vpopcntq"
            ) =>
        {
            validate_evex_source_width(def, &dst, src, false)
        }
        [_, src1, src2] => {
            let Some(src1) = x86_vec_reg(src1) else {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_REGISTER_CLASS_001",
                    format!("{} requires a vector src1", inst.mnemonic),
                ));
            };
            if src1.width != dst.reg.width {
                return Err(MachineDiagnostic::new(
                    "E_MACHINE_EVEX_VECTOR_LENGTH_001",
                    format!(
                        "{} src1 vector length must match destination",
                        inst.mnemonic
                    ),
                ));
            }
            validate_evex_source_width(def, &dst, src2, spec.allow_broadcast)
        }
        _ => Err(MachineDiagnostic::new(
            "E_MACHINE_INSTR_OPERAND_001",
            format!("{} has an invalid EVEX operand count", inst.mnemonic),
        )),
    }
}

fn validate_evex_source_width(
    def: &EvexInstructionDef,
    dst: &EvexVectorOperand,
    src: &str,
    allow_broadcast: bool,
) -> Result<(), MachineDiagnostic> {
    if let Some(src) = x86_vec_reg(src) {
        if src.width != dst.reg.width {
            return Err(MachineDiagnostic::new(
                "E_MACHINE_EVEX_VECTOR_LENGTH_001",
                format!("{} vector lengths must match", def.mnemonic),
            ));
        }
        return Ok(());
    }
    let Some(mem) = evex_parse_memory_operand(src) else {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_INSTR_OPERAND_001",
            format!(
                "{} requires an EVEX register or memory source",
                def.mnemonic
            ),
        ));
    };
    let broadcast = mem.broadcast.is_some();
    if broadcast && !allow_broadcast {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_EVEX_BROADCAST_001",
            format!("{} does not allow EVEX broadcast", def.mnemonic),
        ));
    }
    if !evex_memory_width_matches(dst.reg.width, &mem, broadcast) {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_EVEX_TUPLE_001",
            format!(
                "{} memory width does not match EVEX tuple policy",
                def.mnemonic
            ),
        ));
    }
    let scale = evex_tuple_scale(dst.reg.width, broadcast).unwrap_or(1);
    if scale > 1 && mem.mem.disp != 0 && mem.mem.disp % scale != 0 {
        return Err(MachineDiagnostic::new(
            "E_MACHINE_EVEX_COMPRESSED_DISP_001",
            format!(
                "{} displacement is not encodable as EVEX disp8*N",
                def.mnemonic
            ),
        ));
    }
    Ok(())
}

fn x86_gpr(reg: &str) -> Option<X86Gpr> {
    let reg = reg.to_ascii_lowercase();
    let (code, width, rex8) = match reg.as_str() {
        "rax" => (0, 64, false),
        "rcx" => (1, 64, false),
        "rdx" => (2, 64, false),
        "rbx" => (3, 64, false),
        "rsp" => (4, 64, false),
        "rbp" => (5, 64, false),
        "rsi" => (6, 64, false),
        "rdi" => (7, 64, false),
        "r8" => (8, 64, false),
        "r9" => (9, 64, false),
        "r10" => (10, 64, false),
        "r11" => (11, 64, false),
        "r12" => (12, 64, false),
        "r13" => (13, 64, false),
        "r14" => (14, 64, false),
        "r15" => (15, 64, false),
        "eax" => (0, 32, false),
        "ecx" => (1, 32, false),
        "edx" => (2, 32, false),
        "ebx" => (3, 32, false),
        "esp" => (4, 32, false),
        "ebp" => (5, 32, false),
        "esi" => (6, 32, false),
        "edi" => (7, 32, false),
        "r8d" => (8, 32, false),
        "r9d" => (9, 32, false),
        "r10d" => (10, 32, false),
        "r11d" => (11, 32, false),
        "r12d" => (12, 32, false),
        "r13d" => (13, 32, false),
        "r14d" => (14, 32, false),
        "r15d" => (15, 32, false),
        "ax" => (0, 16, false),
        "cx" => (1, 16, false),
        "dx" => (2, 16, false),
        "bx" => (3, 16, false),
        "sp" => (4, 16, false),
        "bp" => (5, 16, false),
        "si" => (6, 16, false),
        "di" => (7, 16, false),
        "r8w" => (8, 16, false),
        "r9w" => (9, 16, false),
        "r10w" => (10, 16, false),
        "r11w" => (11, 16, false),
        "r12w" => (12, 16, false),
        "r13w" => (13, 16, false),
        "r14w" => (14, 16, false),
        "r15w" => (15, 16, false),
        "al" => (0, 8, false),
        "cl" => (1, 8, false),
        "dl" => (2, 8, false),
        "bl" => (3, 8, false),
        "ah" => (4, 8, false),
        "ch" => (5, 8, false),
        "dh" => (6, 8, false),
        "bh" => (7, 8, false),
        "spl" => (4, 8, true),
        "bpl" => (5, 8, true),
        "sil" => (6, 8, true),
        "dil" => (7, 8, true),
        "r8b" => (8, 8, false),
        "r9b" => (9, 8, false),
        "r10b" => (10, 8, false),
        "r11b" => (11, 8, false),
        "r12b" => (12, 8, false),
        "r13b" => (13, 8, false),
        "r14b" => (14, 8, false),
        "r15b" => (15, 8, false),
        _ => return None,
    };
    Some(X86Gpr {
        code,
        width,
        rex8,
        high8: matches!(reg.as_str(), "ah" | "ch" | "dh" | "bh"),
    })
}

fn x86_vec_reg(reg: &str) -> Option<X86VecReg> {
    let reg = evex_base_operand(reg).to_ascii_lowercase();
    if let Some(num) = reg.strip_prefix("xmm").and_then(|n| n.parse::<u8>().ok()) {
        if num <= 31 {
            return Some(X86VecReg {
                code: num,
                width: 128,
            });
        }
    }
    if let Some(num) = reg.strip_prefix("ymm").and_then(|n| n.parse::<u8>().ok()) {
        if num <= 31 {
            return Some(X86VecReg {
                code: num,
                width: 256,
            });
        }
    }
    if let Some(num) = reg.strip_prefix("zmm").and_then(|n| n.parse::<u8>().ok()) {
        if num <= 31 {
            return Some(X86VecReg {
                code: num,
                width: 512,
            });
        }
    }
    None
}

fn x86_k_reg(reg: &str) -> Option<X86KReg> {
    let reg = evex_base_operand(reg).to_ascii_lowercase();
    let num = reg.strip_prefix('k').and_then(|n| n.parse::<u8>().ok())?;
    (num <= 7).then_some(X86KReg { code: num })
}

fn x86_tile_reg(reg: &str) -> Option<u8> {
    let reg = reg.trim().to_ascii_lowercase();
    let num = reg.strip_prefix("tmm").and_then(|n| n.parse::<u8>().ok())?;
    (num <= 7).then_some(num)
}

fn x86_mmx_reg(reg: &str) -> Option<u8> {
    let reg = reg.trim().to_ascii_lowercase();
    let num = reg.strip_prefix("mm").and_then(|n| n.parse::<u8>().ok())?;
    (num <= 7).then_some(num)
}

fn x86_x87_reg(reg: &str) -> Option<u8> {
    let reg = reg.trim().to_ascii_lowercase();
    if reg == "st" {
        return Some(0);
    }
    let num = reg.strip_prefix("st").and_then(|n| n.parse::<u8>().ok())?;
    (num <= 7).then_some(num)
}

fn x86_segment_reg(reg: &str) -> bool {
    X86_64_SEGMENT_REGISTERS.contains(&reg.to_ascii_lowercase().as_str())
}

fn x86_segment_reg_code(reg: &str) -> Option<u8> {
    match reg.trim().to_ascii_lowercase().as_str() {
        "es" => Some(0),
        "cs" => Some(1),
        "ss" => Some(2),
        "ds" => Some(3),
        "fs" => Some(4),
        "gs" => Some(5),
        _ => None,
    }
}

fn x86_control_reg(reg: &str) -> Option<u8> {
    let reg = reg.trim().to_ascii_lowercase();
    let num = reg.strip_prefix("cr")?.parse::<u8>().ok()?;
    (num <= 15).then_some(num)
}

fn x86_debug_reg(reg: &str) -> Option<u8> {
    let reg = reg.trim().to_ascii_lowercase();
    let num = reg.strip_prefix("dr")?.parse::<u8>().ok()?;
    (num <= 15).then_some(num)
}

fn x86_system_reg(reg: &str) -> bool {
    SYSTEM_REGISTERS.contains(&reg.to_ascii_lowercase().as_str())
}

fn x86_register_class(reg: &str) -> Option<&'static str> {
    let reg = reg.trim().to_ascii_lowercase();
    if x86_gpr(&reg).is_some() {
        return Some("gpr");
    }
    if reg == "rip" {
        return Some("instruction_pointer");
    }
    if let Some(vec) = x86_vec_reg(&reg) {
        return match vec.width {
            128 => Some("xmm"),
            256 => Some("ymm"),
            512 => Some("zmm"),
            _ => Some("vector"),
        };
    }
    if x86_k_reg(&reg).is_some() {
        return Some("opmask");
    }
    if x86_tile_reg(&reg).is_some() {
        return Some("tile");
    }
    if x86_mmx_reg(&reg).is_some() {
        return Some("mmx");
    }
    if x86_x87_reg(&reg).is_some() {
        return Some("x87");
    }
    if x86_segment_reg(&reg) {
        return Some("segment");
    }
    if x86_system_reg(&reg) {
        return Some("system");
    }
    None
}

fn x86_rex_conflicting_register(reg: &str) -> bool {
    let reg = reg.trim().to_ascii_lowercase();
    x86_gpr(&reg)
        .map(|gpr| gpr.code >= 8 || gpr.rex8)
        .unwrap_or(false)
        || x86_vec_reg(&reg).map(|vec| vec.code >= 8).unwrap_or(false)
        || x86_k_reg(&reg).map(|mask| mask.code >= 8).unwrap_or(false)
}

fn push_rex(bytes: &mut Vec<u8>, w: bool, reg: u8, index: u8, base: u8, force: bool) {
    let rex = 0x40
        | if w { 0x08 } else { 0 }
        | (((reg >> 3) & 1) << 2)
        | (((index >> 3) & 1) << 1)
        | ((base >> 3) & 1);
    if force || rex != 0x40 {
        bytes.push(rex);
    }
}

fn vex3_prefix(reg_field: u8, vvvv: u8, rm_field: u8, l_bit: u8, pp: u8, map: u8) -> Vec<u8> {
    vex3_prefix_w(reg_field, vvvv, rm_field, l_bit, pp, map, 0)
}

fn vex3_prefix_w(
    reg_field: u8,
    vvvv: u8,
    rm_field: u8,
    l_bit: u8,
    pp: u8,
    map: u8,
    w: u8,
) -> Vec<u8> {
    vex3_prefix_w_full(reg_field, vvvv, 0, rm_field, l_bit, pp, map, w)
}

fn vex3_prefix_w_full(
    reg_field: u8,
    vvvv: u8,
    index_field: u8,
    rm_field: u8,
    l_bit: u8,
    pp: u8,
    map: u8,
    w: u8,
) -> Vec<u8> {
    let r = ((reg_field >> 3) & 1) ^ 1;
    let x = ((index_field >> 3) & 1) ^ 1;
    let b = ((rm_field >> 3) & 1) ^ 1;
    vec![
        0xc4,
        (r << 7) | (x << 6) | (b << 5) | (map & 0x1f),
        ((w & 1) << 7) | ((!vvvv & 0x0f) << 3) | ((l_bit & 1) << 2) | (pp & 0x03),
    ]
}

fn evex_prefix(
    reg_field: u8,
    vvvv: u8,
    index_field: u8,
    rm_field: u8,
    ll: u8,
    pp: u8,
    map: u8,
    w: u8,
    aaa: u8,
    z: bool,
    b: bool,
) -> Vec<u8> {
    let r = ((reg_field >> 3) & 1) ^ 1;
    let x = ((index_field >> 3) & 1) ^ 1;
    let b_bit = ((rm_field >> 3) & 1) ^ 1;
    let r_prime = ((reg_field >> 4) & 1) ^ 1;
    let v_prime = ((vvvv >> 4) & 1) ^ 1;
    vec![
        0x62,
        (r << 7) | (x << 6) | (b_bit << 5) | (r_prime << 4) | (map & 0x0f),
        ((w & 1) << 7) | ((!vvvv & 0x0f) << 3) | 0x04 | (pp & 0x03),
        (u8::from(z) << 7)
            | ((ll & 0x03) << 5)
            | (u8::from(b) << 4)
            | ((v_prime & 1) << 3)
            | (aaa & 0x07),
    ]
}

fn evex_rm_register_index_field(reg_code: u8) -> u8 {
    reg_code >> 1
}

fn encode_x86_evex_instruction(inst: &MachineInstruction) -> Option<Vec<u8>> {
    let def = evex_instruction_def_by_name(&inst.mnemonic)?;
    let spec = evex_encoding_spec(&def);
    match inst.mnemonic.as_str() {
        "vcmpps" => return encode_x86_evex_compare_imm(&spec, inst.operands.as_slice()),
        "vcompressps" => return encode_x86_evex_compressps(&spec, inst.operands.as_slice()),
        "vexpandps" => return encode_x86_evex_expandps(&spec, inst.operands.as_slice()),
        "vscatterdps" => return encode_x86_evex_scatterdps(&spec, inst.operands.as_slice()),
        "vfpclassps" => return encode_x86_evex_fpclassps(&spec, inst.operands.as_slice()),
        "vptestnmd" | "vpshufbitqmb" => {
            return encode_x86_evex_k_dest_three_operand(&spec, inst.operands.as_slice())
        }
        "vpmovdb" | "vpmovwb" => {
            return encode_x86_evex_pmov_downconvert(
                &spec,
                inst.mnemonic.as_str(),
                inst.operands.as_slice(),
            )
        }
        _ => {}
    }
    match inst.operands.as_slice() {
        [dst, src]
            if matches!(
                def.mnemonic,
                "vmovdqa32" | "vmovdqu32" | "vpconflictd" | "vpopcntb" | "vpopcntd" | "vpopcntq"
            ) =>
        {
            encode_x86_evex_two_operand(&spec, dst, src)
        }
        [dst, src1, src2] => encode_x86_evex_three_operand(&spec, dst, src1, src2),
        _ => None,
    }
}

fn encode_x86_evex_compare_imm(spec: &EvexEncodingSpec, ops: &[String]) -> Option<Vec<u8>> {
    let [dst, src1, src2, imm] = ops else {
        return None;
    };
    let dst = x86_k_reg(dst)?;
    if dst.code == 0 {
        return None;
    }
    let src1 = x86_vec_reg(src1)?;
    if src1.width != 512 {
        return None;
    }
    let imm = parse_int(imm)?;
    if !(0..=255).contains(&imm) {
        return None;
    }
    if let Some(src2) = x86_vec_reg(src2) {
        if src2.width != 512 {
            return None;
        }
        let mut bytes = evex_prefix(
            dst.code,
            src1.code,
            evex_rm_register_index_field(src2.code),
            src2.code,
            2,
            spec.pp,
            spec.map,
            spec.w,
            0,
            false,
            false,
        );
        bytes.extend([spec.opcode, modrm(0b11, dst.code, src2.code), imm as u8]);
        return Some(bytes);
    }
    if let Some(mem) = evex_parse_memory_operand(src2) {
        let broadcast = mem.broadcast.is_some();
        if broadcast && !spec.allow_broadcast {
            return None;
        }
        if !evex_memory_width_matches(512, &mem, broadcast) {
            return None;
        }
        let scale = evex_tuple_scale(512, broadcast)?;
        let mut bytes = evex_prefix(
            dst.code,
            src1.code,
            mem.mem.index.map(|(idx, _)| idx).unwrap_or(0),
            mem.mem.base,
            2,
            spec.pp,
            spec.map,
            spec.w,
            0,
            false,
            broadcast,
        );
        bytes.push(spec.opcode);
        emit_x86_evex_memory_tail(&mut bytes, dst.code, mem.mem, scale)?;
        bytes.push(imm as u8);
        return Some(bytes);
    }
    None
}

fn encode_x86_evex_k_dest_three_operand(
    spec: &EvexEncodingSpec,
    ops: &[String],
) -> Option<Vec<u8>> {
    let [dst, src1, src2] = ops else {
        return None;
    };
    let dst = x86_k_reg(dst)?;
    if dst.code == 0 {
        return None;
    }
    let src1 = x86_vec_reg(src1)?;
    if src1.width != 512 {
        return None;
    }
    if let Some(src2) = x86_vec_reg(src2) {
        if src2.width != 512 {
            return None;
        }
        let mut bytes = evex_prefix(
            dst.code,
            src1.code,
            evex_rm_register_index_field(src2.code),
            src2.code,
            2,
            spec.pp,
            spec.map,
            spec.w,
            0,
            false,
            false,
        );
        bytes.extend([spec.opcode, modrm(0b11, dst.code, src2.code)]);
        return Some(bytes);
    }
    if let Some(mem) = evex_parse_memory_operand(src2) {
        if mem.width != "m512" {
            return None;
        }
        let mut bytes = evex_prefix(
            dst.code,
            src1.code,
            mem.mem.index.map(|(idx, _)| idx).unwrap_or(0),
            mem.mem.base,
            2,
            spec.pp,
            spec.map,
            spec.w,
            0,
            false,
            false,
        );
        bytes.push(spec.opcode);
        emit_x86_evex_memory_tail(&mut bytes, dst.code, mem.mem, 64)?;
        return Some(bytes);
    }
    None
}

fn encode_x86_evex_fpclassps(spec: &EvexEncodingSpec, ops: &[String]) -> Option<Vec<u8>> {
    let [dst, src, imm] = ops else {
        return None;
    };
    let dst = x86_k_reg(dst)?;
    if dst.code == 0 {
        return None;
    }
    let imm = parse_int(imm)?;
    if !(0..=255).contains(&imm) {
        return None;
    }
    if let Some(src) = x86_vec_reg(src) {
        if src.width != 512 {
            return None;
        }
        let mut bytes = evex_prefix(
            dst.code,
            0,
            evex_rm_register_index_field(src.code),
            src.code,
            2,
            spec.pp,
            spec.map,
            spec.w,
            0,
            false,
            false,
        );
        bytes.extend([spec.opcode, modrm(0b11, dst.code, src.code), imm as u8]);
        return Some(bytes);
    }
    if let Some(mem) = evex_parse_memory_operand(src) {
        if mem.width != "m512" {
            return None;
        }
        let mut bytes = evex_prefix(
            dst.code,
            0,
            mem.mem.index.map(|(idx, _)| idx).unwrap_or(0),
            mem.mem.base,
            2,
            spec.pp,
            spec.map,
            spec.w,
            0,
            false,
            false,
        );
        bytes.push(spec.opcode);
        emit_x86_evex_memory_tail(&mut bytes, dst.code, mem.mem, 64)?;
        bytes.push(imm as u8);
        return Some(bytes);
    }
    None
}

fn encode_x86_evex_pmov_downconvert(
    spec: &EvexEncodingSpec,
    mnemonic: &str,
    ops: &[String],
) -> Option<Vec<u8>> {
    let [dst, src] = ops else {
        return None;
    };
    let src = x86_vec_reg(src)?;
    if src.width != 512 {
        return None;
    }
    let (dst_width, mem_width, tuple_scale) = if mnemonic == "vpmovdb" {
        (128, "m128", 16)
    } else {
        (256, "m256", 32)
    };
    if let Some(dst) = evex_parse_vector_operand(dst) {
        if dst.reg.width != dst_width || dst.rounding.is_some() || dst.sae {
            return None;
        }
        if dst.zero && dst.mask.is_none() {
            return None;
        }
        let mut bytes = evex_prefix(
            src.code,
            0,
            evex_rm_register_index_field(dst.reg.code),
            dst.reg.code,
            2,
            spec.pp,
            spec.map,
            spec.w,
            dst.mask.map(|mask| mask.code).unwrap_or(0),
            dst.zero,
            false,
        );
        bytes.extend([spec.opcode, modrm(0b11, src.code, dst.reg.code)]);
        return Some(bytes);
    }
    if let Some(mem) = evex_parse_memory_operand(dst) {
        if mem.width != mem_width {
            return None;
        }
        let mask = evex_memory_mask(dst).map(|mask| mask.code).unwrap_or(0);
        let mut bytes = evex_prefix(
            src.code,
            0,
            mem.mem.index.map(|(idx, _)| idx).unwrap_or(0),
            mem.mem.base,
            2,
            spec.pp,
            spec.map,
            spec.w,
            mask,
            false,
            false,
        );
        bytes.push(spec.opcode);
        emit_x86_evex_memory_tail(&mut bytes, src.code, mem.mem, tuple_scale)?;
        return Some(bytes);
    }
    None
}

fn encode_x86_evex_compressps(spec: &EvexEncodingSpec, ops: &[String]) -> Option<Vec<u8>> {
    let [dst, src] = ops else {
        return None;
    };
    let src = x86_vec_reg(src)?;
    if src.width != 512 {
        return None;
    }
    if let Some(dst) = evex_parse_vector_operand(dst) {
        if dst.reg.width != 512 || dst.zero {
            return None;
        }
        let mut bytes = evex_prefix(
            src.code,
            0,
            evex_rm_register_index_field(dst.reg.code),
            dst.reg.code,
            2,
            spec.pp,
            spec.map,
            spec.w,
            dst.mask.map(|mask| mask.code).unwrap_or(0),
            false,
            false,
        );
        bytes.extend([spec.opcode, modrm(0b11, src.code, dst.reg.code)]);
        return Some(bytes);
    }
    if let Some(mem) = evex_parse_memory_operand(dst) {
        let mask = evex_memory_mask(dst)?;
        if mask.code == 0 || mem.width != "m512" {
            return None;
        }
        let mut bytes = evex_prefix(
            src.code,
            0,
            mem.mem.index.map(|(idx, _)| idx).unwrap_or(0),
            mem.mem.base,
            2,
            spec.pp,
            spec.map,
            spec.w,
            mask.code,
            false,
            false,
        );
        bytes.push(spec.opcode);
        emit_x86_evex_memory_tail(&mut bytes, src.code, mem.mem, 64)?;
        return Some(bytes);
    }
    None
}

fn encode_x86_evex_expandps(spec: &EvexEncodingSpec, ops: &[String]) -> Option<Vec<u8>> {
    let [dst, src] = ops else {
        return None;
    };
    encode_x86_evex_two_operand(spec, dst, src)
}

fn encode_x86_evex_scatterdps(spec: &EvexEncodingSpec, ops: &[String]) -> Option<Vec<u8>> {
    let [mem, src] = ops else {
        return None;
    };
    let mask = evex_memory_mask(mem)?;
    if mask.code == 0 {
        return None;
    }
    let mem = parse_x86_vsib_memory_operand(mem)?;
    let src = x86_vec_reg(src)?;
    if mem.index_width != 512 || src.width != 512 {
        return None;
    }
    let mut bytes = evex_prefix(
        src.code, 0, mem.index, mem.base, 2, spec.pp, spec.map, spec.w, mask.code, false, false,
    );
    bytes.push(spec.opcode);
    emit_x86_vsib_memory_tail(&mut bytes, src.code, mem);
    Some(bytes)
}

fn encode_x86_evex_two_operand(spec: &EvexEncodingSpec, dst: &str, src: &str) -> Option<Vec<u8>> {
    let dst = evex_parse_vector_operand(dst)?;
    if dst.rounding.is_some() || dst.sae || dst.zero && dst.mask.is_none() {
        return None;
    }
    if let Some(src) = x86_vec_reg(src) {
        if dst.reg.width != src.width {
            return None;
        }
        let ll = evex_ll_bits(dst.reg.width)?;
        let mut bytes = evex_prefix(
            dst.reg.code,
            0,
            evex_rm_register_index_field(src.code),
            src.code,
            ll,
            spec.pp,
            spec.map,
            spec.w,
            dst.mask.map(|mask| mask.code).unwrap_or(0),
            dst.zero,
            false,
        );
        bytes.extend([spec.opcode, modrm(0b11, dst.reg.code, src.code)]);
        return Some(bytes);
    }
    if let Some(mem) = evex_parse_memory_operand(src) {
        let ll = evex_ll_bits(dst.reg.width)?;
        if !evex_memory_width_matches(dst.reg.width, &mem, false) {
            return None;
        }
        let mut bytes = evex_prefix(
            dst.reg.code,
            0,
            mem.mem.index.map(|(idx, _)| idx).unwrap_or(0),
            mem.mem.base,
            ll,
            spec.pp,
            spec.map,
            spec.w,
            dst.mask.map(|mask| mask.code).unwrap_or(0),
            dst.zero,
            false,
        );
        bytes.push(spec.opcode);
        emit_x86_evex_memory_tail(&mut bytes, dst.reg.code, mem.mem, spec.tuple_scale)?;
        return Some(bytes);
    }
    None
}

fn encode_x86_evex_three_operand(
    spec: &EvexEncodingSpec,
    dst: &str,
    src1: &str,
    src2: &str,
) -> Option<Vec<u8>> {
    let dst = evex_parse_vector_operand(dst)?;
    let src1 = x86_vec_reg(src1)?;
    if dst.reg.width != src1.width {
        return None;
    }
    let ll = evex_ll_bits(dst.reg.width)?;
    if let Some(src2) = x86_vec_reg(src2) {
        if dst.reg.width != src2.width {
            return None;
        }
        let b = dst.rounding.is_some() || dst.sae;
        if b && !spec.allow_rounding {
            return None;
        }
        let mut bytes = evex_prefix(
            dst.reg.code,
            src1.code,
            evex_rm_register_index_field(src2.code),
            src2.code,
            ll,
            spec.pp,
            spec.map,
            spec.w,
            dst.mask.map(|mask| mask.code).unwrap_or(0),
            dst.zero,
            b,
        );
        bytes.extend([spec.opcode, modrm(0b11, dst.reg.code, src2.code)]);
        return Some(bytes);
    }
    if let Some(mem) = evex_parse_memory_operand(src2) {
        let broadcast = mem.broadcast.is_some();
        if broadcast && !spec.allow_broadcast {
            return None;
        }
        if !evex_memory_width_matches(dst.reg.width, &mem, broadcast) {
            return None;
        }
        let scale = evex_tuple_scale(dst.reg.width, broadcast)?;
        let mut bytes = evex_prefix(
            dst.reg.code,
            src1.code,
            mem.mem.index.map(|(idx, _)| idx).unwrap_or(0),
            mem.mem.base,
            ll,
            spec.pp,
            spec.map,
            spec.w,
            dst.mask.map(|mask| mask.code).unwrap_or(0),
            dst.zero,
            broadcast,
        );
        bytes.push(spec.opcode);
        emit_x86_evex_memory_tail(&mut bytes, dst.reg.code, mem.mem, scale)?;
        return Some(bytes);
    }
    None
}

fn emit_x86_evex_memory_tail(
    bytes: &mut Vec<u8>,
    reg_field: u8,
    mem: X86MemoryOperand,
    tuple_scale: i32,
) -> Option<()> {
    if tuple_scale > 1 && mem.disp != 0 && mem.disp % tuple_scale != 0 {
        return None;
    }
    let encoded_disp = if tuple_scale > 1 && mem.disp != 0 {
        mem.disp / tuple_scale
    } else {
        mem.disp
    };
    emit_x86_modrm_memory_tail_with_disp(bytes, reg_field, mem, encoded_disp, mem.disp);
    Some(())
}

fn modrm(mod_bits: u8, reg: u8, rm: u8) -> u8 {
    ((mod_bits & 0b11) << 6) | ((reg & 7) << 3) | (rm & 7)
}

fn is_setcc(mnemonic: &str) -> bool {
    mnemonic.starts_with("set") && condition_code(mnemonic).is_some()
}

fn is_cmovcc(mnemonic: &str) -> bool {
    mnemonic.starts_with("cmov") && condition_code(mnemonic).is_some()
}

fn condition_code(mnemonic: &str) -> Option<u8> {
    let cond = mnemonic
        .strip_prefix("cmov")
        .or_else(|| mnemonic.strip_prefix("set"))
        .or_else(|| mnemonic.strip_prefix('j'))?;
    match cond {
        "o" => Some(0x0),
        "no" => Some(0x1),
        "b" | "nae" | "c" => Some(0x2),
        "ae" | "nb" | "nc" => Some(0x3),
        "e" | "z" => Some(0x4),
        "ne" | "nz" => Some(0x5),
        "be" | "na" => Some(0x6),
        "a" | "nbe" => Some(0x7),
        "s" => Some(0x8),
        "ns" => Some(0x9),
        "p" | "pe" => Some(0xa),
        "np" | "po" => Some(0xb),
        "l" | "nge" => Some(0xc),
        "ge" | "nl" => Some(0xd),
        "le" | "ng" => Some(0xe),
        "g" | "nle" => Some(0xf),
        _ => None,
    }
}

fn encode_aarch64_instructions(
    instructions: &[MachineInstruction],
    diagnostics: &mut Vec<MachineDiagnostic>,
) -> Vec<u8> {
    let mut bytes = Vec::new();
    for inst in instructions {
        let word = match inst.mnemonic.as_str() {
            "label" => continue,
            "nop" => Some(0xd503201f),
            "yield" => Some(0xd503203f),
            "wfi" => Some(0xd503207f),
            "wfe" => Some(0xd503205f),
            "sev" => Some(0xd503209f),
            "sevl" => Some(0xd50320bf),
            "sb" if inst.operands.is_empty() => Some(0xd50330ff),
            "ssbb" if inst.operands.is_empty() => Some(0xd503309f),
            "pssbb" if inst.operands.is_empty() => Some(0xd503349f),
            "csdb" if inst.operands.is_empty() => Some(0xd503229f),
            "esb" if inst.operands.is_empty() => Some(0xd503221f),
            "dgh" if inst.operands.is_empty() => Some(0xd50320df),
            "wfet" | "wfit" if inst.operands.len() == 1 => inst
                .operands
                .first()
                .and_then(|operand| aarch64_reg_number(operand))
                .map(|register| {
                    (if inst.mnemonic == "wfet" {
                        0xd5031000
                    } else {
                        0xd5031020
                    }) | register as u32
                }),
            "tsb"
                if inst.operands.len() == 1
                    && inst.operands[0].trim().eq_ignore_ascii_case("csync") =>
            {
                Some(0xd503225f)
            }
            "xaflag" if inst.operands.is_empty() => Some(0xd500403f),
            "axflag" if inst.operands.is_empty() => Some(0xd500405f),
            "ret" => {
                let rn = inst
                    .operands
                    .first()
                    .and_then(|op| aarch64_reg_number(op))
                    .unwrap_or(30);
                Some(0xd65f0000 | ((rn as u32) << 5))
            }
            "br" => inst
                .operands
                .first()
                .and_then(|op| aarch64_reg_number(op))
                .map(|rn| 0xd61f0000 | ((rn as u32) << 5)),
            "b" => encode_aarch64_branch_imm(inst, 0x14000000),
            "bl" => encode_aarch64_branch_imm(inst, 0x94000000),
            mnemonic if mnemonic.starts_with("b.") => encode_aarch64_cond_branch(inst),
            "cbz" | "cbnz" => encode_aarch64_cbz(inst),
            "tbz" | "tbnz" => encode_aarch64_tbz(inst),
            "adr" => inst
                .operands
                .first()
                .and_then(|op| aarch64_reg_number(op))
                .map(|rd| 0x10000000 | rd as u32),
            "adrp" => inst
                .operands
                .first()
                .and_then(|op| aarch64_reg_number(op))
                .map(|rd| 0x90000000 | rd as u32),
            "mov" => encode_aarch64_mov(inst),
            "rbit" | "rev" | "rev16" | "rev32" | "clz" | "cls" => encode_aarch64_bit_unary(inst),
            "extr" => encode_aarch64_extract(inst),
            "ubfm" | "sbfm" | "bfm" => encode_aarch64_bitfield(inst),
            "paciasp" if inst.operands.is_empty() => Some(0xd503233f),
            "autiasp" if inst.operands.is_empty() => Some(0xd50323bf),
            "xpaclri" if inst.operands.is_empty() => Some(0xd50320ff),
            "xpaci" | "xpacd" | "paciza" | "autiza" | "pacia" | "autda" => {
                encode_aarch64_pointer_auth(inst)
            }
            "ptrue" => encode_aarch64_sve_ptrue(inst),
            "pfalse" => encode_aarch64_sve_pfalse(inst),
            "whilelo" => encode_aarch64_sve_whilelo(inst),
            "ld1b" | "ld1h" | "ld1w" | "ld1d" | "st1b" | "st1h" | "st1w" | "st1d" => {
                encode_aarch64_sve_load_store(inst)
            }
            "cntb" | "cnth" | "cntw" | "cntd" | "incb" | "inch" | "incw" | "incd" => {
                encode_aarch64_sve_count(inst)
            }
            "fmov" => encode_aarch64_fp_move(inst),
            "fadd" => encode_aarch64_sve_fp_predicated(inst)
                .or_else(|| encode_aarch64_neon_three_operand(inst))
                .or_else(|| encode_aarch64_fp_three_operand(inst)),
            "fsub" | "fmul" | "fdiv" => encode_aarch64_sve_fp_predicated(inst)
                .or_else(|| encode_aarch64_neon_three_operand(inst))
                .or_else(|| encode_aarch64_fp_three_operand(inst)),
            "fmla" => encode_aarch64_sve_fmla(inst),
            "faddv" => encode_aarch64_sve_faddv(inst),
            "fsqrt" => encode_aarch64_fp_unary(inst),
            "fcmp" => encode_aarch64_fp_compare(inst),
            "scvtf" => encode_aarch64_fp_convert_from_int(inst),
            "fcvtzs" => encode_aarch64_fp_convert_to_int(inst),
            "fabs" | "fneg" => encode_aarch64_fp_unary(inst),
            "fcvt" => encode_aarch64_fp_convert_width(inst),
            "fmax" | "fmin" => encode_aarch64_fp_three_operand(inst),
            "fcsel" => encode_aarch64_fp_select(inst),
            "cmpeq" | "cmpne" | "cmplt" | "cmpgt" | "cmpge" | "cmple" => {
                encode_aarch64_sve_compare(inst)
            }
            "sel" => encode_aarch64_sve_select(inst),
            "not" => encode_aarch64_sve_predicate_logic(inst),
            "add" | "and" | "orr" | "eor" | "mul" => encode_aarch64_sve_integer_three_operand(inst)
                .or_else(|| encode_aarch64_sve_predicate_logic(inst))
                .or_else(|| encode_aarch64_neon_three_operand(inst))
                .or_else(|| {
                    if inst.mnemonic == "mul" {
                        encode_aarch64_mul_alias(inst)
                    } else {
                        encode_aarch64_three_operand(inst)
                    }
                }),
            "sub" => encode_aarch64_sve_integer_three_operand(inst)
                .or_else(|| encode_aarch64_three_operand(inst)),
            "adds" | "subs" | "ands" | "bic" | "orn" | "eon" => encode_aarch64_three_operand(inst),
            "adc" | "sbc" => encode_aarch64_adc_sbc(inst),
            "madd" | "msub" => encode_aarch64_madd_msub(inst),
            "sdiv" | "udiv" => encode_aarch64_div(inst),
            "cmp" | "tst" => encode_aarch64_compare_alias(inst),
            "ldr" | "str" | "ldrb" | "ldrh" | "ldrsb" | "ldrsh" | "ldrsw" | "strb" | "strh" => {
                encode_aarch64_neon_q_load_store(inst).or_else(|| encode_aarch64_load_store(inst))
            }
            "ldur" | "stur" => encode_aarch64_unscaled_load_store(inst),
            "ldxr" | "ldaxr" => encode_aarch64_exclusive_load(inst, inst.mnemonic == "ldaxr"),
            "stxr" | "stlxr" => encode_aarch64_exclusive_store(inst, inst.mnemonic == "stlxr"),
            "ldar" | "stlr" => encode_aarch64_ordered_load_store(inst),
            "cas" | "casa" | "casl" | "casal" => encode_aarch64_lse_cas(inst),
            "swp" | "swpa" | "swpl" | "swpal" => encode_aarch64_lse_swp(inst),
            "ldadd" | "ldadda" | "ldaddl" | "ldaddal" | "ldclr" | "ldclra" | "ldclrl"
            | "ldclral" | "ldeor" | "ldeora" | "ldeorl" | "ldeoral" | "ldset" | "ldseta"
            | "ldsetl" | "ldsetal" => encode_aarch64_lse_ldop(inst),
            "rev64" => encode_aarch64_neon_rev64(inst),
            "tbl" => encode_aarch64_neon_tbl(inst),
            "bsl" => encode_aarch64_neon_three_operand(inst),
            "ld1" | "st1" => encode_aarch64_neon_lane_load_store(inst),
            "ldp" | "stp" => encode_aarch64_pair_load_store(inst),
            "lsl" | "lsr" | "asr" => encode_aarch64_shift_alias(inst),
            "dmb" | "dsb" | "isb" => encode_aarch64_barrier(inst),
            "mrs" => encode_aarch64_mrs(inst),
            "msr" => encode_aarch64_msr(inst),
            "tlbi" => encode_aarch64_tlbi(inst),
            "dc" => encode_aarch64_dc(inst),
            "ic" => encode_aarch64_ic(inst),
            "svc" => encode_aarch64_exception(inst, 0xd4000001),
            "hvc" => encode_aarch64_exception(inst, 0xd4000002),
            "smc" => encode_aarch64_exception(inst, 0xd4000003),
            "brk" => encode_aarch64_exception(inst, 0xd4200000),
            "hlt" => encode_aarch64_exception(inst, 0xd4400000),
            "eret" => Some(0xd69f03e0),
            _ => None,
        };
        if let Some(word) = word {
            bytes.extend(word.to_le_bytes());
        } else {
            diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_ENCODING_001",
                format!("aarch64 encoding for '{}' is not available", inst.text),
            ));
        }
    }
    bytes
}

fn encode_aarch64_bit_unary(inst: &MachineInstruction) -> Option<u32> {
    let destination = inst.operands.first()?.trim().to_ascii_lowercase();
    let source = inst.operands.get(1)?.trim().to_ascii_lowercase();
    if inst.operands.len() != 2 {
        return None;
    }
    let width = aarch64_gpr_width(&destination)?;
    if width != aarch64_gpr_width(&source)? || !matches!(width, 32 | 64) {
        return None;
    }
    let rd = aarch64_reg_number(&destination)? as u32;
    let rn = aarch64_reg_number(&source)? as u32;
    let base = match (inst.mnemonic.as_str(), width) {
        ("rbit", 32) => 0x5ac00000,
        ("rbit", 64) => 0xdac00000,
        ("rev16", 32) => 0x5ac00400,
        ("rev16", 64) => 0xdac00400,
        ("rev32", 64) => 0xdac00800,
        ("rev", 32) => 0x5ac00800,
        ("rev", 64) => 0xdac00c00,
        ("clz", 32) => 0x5ac01000,
        ("clz", 64) => 0xdac01000,
        ("cls", 32) => 0x5ac01400,
        ("cls", 64) => 0xdac01400,
        _ => return None,
    };
    Some(base | (rn << 5) | rd)
}

fn encode_aarch64_extract(inst: &MachineInstruction) -> Option<u32> {
    if inst.operands.len() != 4 {
        return None;
    }
    let rd_raw = inst.operands.first()?.trim().to_ascii_lowercase();
    let rn_raw = inst.operands.get(1)?.trim().to_ascii_lowercase();
    let rm_raw = inst.operands.get(2)?.trim().to_ascii_lowercase();
    let width = aarch64_gpr_width(&rd_raw)?;
    if width != aarch64_gpr_width(&rn_raw)? || width != aarch64_gpr_width(&rm_raw)? {
        return None;
    }
    let lsb = parse_int(inst.operands.get(3)?.trim_start_matches('#'))?;
    if lsb < 0 || lsb >= width as i128 {
        return None;
    }
    let base = match width {
        32 => 0x13800000,
        64 => 0x93c00000,
        _ => return None,
    };
    Some(
        base | ((aarch64_reg_number(&rm_raw)? as u32) << 16)
            | ((lsb as u32) << 10)
            | ((aarch64_reg_number(&rn_raw)? as u32) << 5)
            | aarch64_reg_number(&rd_raw)? as u32,
    )
}

fn encode_aarch64_bitfield(inst: &MachineInstruction) -> Option<u32> {
    if inst.operands.len() != 4 {
        return None;
    }
    let rd_raw = inst.operands.first()?.trim().to_ascii_lowercase();
    let rn_raw = inst.operands.get(1)?.trim().to_ascii_lowercase();
    let width = aarch64_gpr_width(&rd_raw)?;
    if width != aarch64_gpr_width(&rn_raw)? {
        return None;
    }
    let immr = parse_int(inst.operands.get(2)?.trim_start_matches('#'))?;
    let imms = parse_int(inst.operands.get(3)?.trim_start_matches('#'))?;
    if immr < 0 || imms < 0 || immr >= width as i128 || imms >= width as i128 {
        return None;
    }
    let base = match (inst.mnemonic.as_str(), width) {
        ("ubfm", 32) => 0x53000000,
        ("ubfm", 64) => 0xd3400000,
        ("sbfm", 32) => 0x13000000,
        ("sbfm", 64) => 0x93400000,
        ("bfm", 32) => 0x33000000,
        ("bfm", 64) => 0xb3400000,
        _ => return None,
    };
    Some(
        base | ((immr as u32) << 16)
            | ((imms as u32) << 10)
            | ((aarch64_reg_number(&rn_raw)? as u32) << 5)
            | aarch64_reg_number(&rd_raw)? as u32,
    )
}

fn encode_aarch64_mov(inst: &MachineInstruction) -> Option<u32> {
    let rd = aarch64_reg_number(inst.operands.first()?)? as u32;
    let src = inst.operands.get(1)?;
    if let Some(imm) = parse_int(src) {
        if !(0..=0xffff).contains(&imm) {
            return None;
        }
        return Some(0xd2800000 | ((imm as u32) << 5) | rd);
    }
    let rm = aarch64_reg_number(src)? as u32;
    Some(0xaa0003e0 | (rm << 16) | rd)
}

fn encode_aarch64_branch_imm(inst: &MachineInstruction, base: u32) -> Option<u32> {
    let imm = inst
        .operands
        .first()
        .and_then(|op| parse_int(op.trim_start_matches('#')))
        .unwrap_or(0);
    if imm % 4 != 0 || !(-134_217_728..=134_217_724).contains(&imm) {
        return None;
    }
    Some(base | (((imm / 4) as i32 as u32) & 0x03ff_ffff))
}

fn encode_aarch64_cond_branch(inst: &MachineInstruction) -> Option<u32> {
    let cond = aarch64_cond_code(inst.mnemonic.strip_prefix("b.")?)? as u32;
    let imm = inst
        .operands
        .first()
        .and_then(|op| parse_int(op.trim_start_matches('#')))
        .unwrap_or(0);
    if imm % 4 != 0 || !(-1_048_576..=1_048_572).contains(&imm) {
        return None;
    }
    Some(0x54000000 | ((((imm / 4) as i32 as u32) & 0x7ffff) << 5) | cond)
}

fn encode_aarch64_cbz(inst: &MachineInstruction) -> Option<u32> {
    let rt = aarch64_reg_number(inst.operands.first()?)? as u32;
    let imm = inst
        .operands
        .get(1)
        .and_then(|op| parse_int(op.trim_start_matches('#')))
        .unwrap_or(0);
    if imm % 4 != 0 || !(-1_048_576..=1_048_572).contains(&imm) {
        return None;
    }
    let base = if inst.mnemonic == "cbz" {
        0xb4000000
    } else {
        0xb5000000
    };
    Some(base | ((((imm / 4) as i32 as u32) & 0x7ffff) << 5) | rt)
}

fn encode_aarch64_tbz(inst: &MachineInstruction) -> Option<u32> {
    let rt = aarch64_reg_number(inst.operands.first()?)? as u32;
    let bit = parse_int(inst.operands.get(1)?.trim_start_matches('#'))?;
    let imm = inst
        .operands
        .get(2)
        .and_then(|op| parse_int(op.trim_start_matches('#')))
        .unwrap_or(0);
    if !(0..=63).contains(&bit) || imm % 4 != 0 || !(-32768..=32764).contains(&imm) {
        return None;
    }
    let base = if inst.mnemonic == "tbz" {
        0x36000000
    } else {
        0x37000000
    };
    Some(
        base | (((bit as u32) & 0x20) << 26)
            | (((bit as u32) & 0x1f) << 19)
            | ((((imm / 4) as i32 as u32) & 0x3fff) << 5)
            | rt,
    )
}

fn encode_aarch64_three_operand(inst: &MachineInstruction) -> Option<u32> {
    let rd = aarch64_reg_number(inst.operands.first()?)? as u32;
    let rn = aarch64_reg_number(inst.operands.get(1)?)? as u32;
    let third = inst.operands.get(2)?;
    if let Some(imm) = parse_int(third) {
        if !(0..=4095).contains(&imm) || !matches!(inst.mnemonic.as_str(), "add" | "sub") {
            return None;
        }
        let base = if inst.mnemonic == "add" {
            0x91000000
        } else {
            0xd1000000
        };
        return Some(base | ((imm as u32) << 10) | (rn << 5) | rd);
    }
    let rm = aarch64_reg_number(third)? as u32;
    let base = match inst.mnemonic.as_str() {
        "add" => 0x8b000000,
        "sub" => 0xcb000000,
        "adds" => 0xab000000,
        "subs" => 0xeb000000,
        "and" => 0x8a000000,
        "orr" => 0xaa000000,
        "eor" => 0xca000000,
        "ands" => 0xea000000,
        "bic" => 0x8a200000,
        "orn" => 0xaa200000,
        "eon" => 0xca200000,
        _ => return None,
    };
    Some(base | (rm << 16) | (rn << 5) | rd)
}

fn encode_aarch64_adc_sbc(inst: &MachineInstruction) -> Option<u32> {
    let rd = aarch64_reg_number(inst.operands.first()?)? as u32;
    let rn = aarch64_reg_number(inst.operands.get(1)?)? as u32;
    let rm = aarch64_reg_number(inst.operands.get(2)?)? as u32;
    let base = if inst.mnemonic == "adc" {
        0x9a000000
    } else {
        0xda000000
    };
    Some(base | (rm << 16) | (rn << 5) | rd)
}

fn encode_aarch64_mul_alias(inst: &MachineInstruction) -> Option<u32> {
    let rd = aarch64_reg_number(inst.operands.first()?)? as u32;
    let rn = aarch64_reg_number(inst.operands.get(1)?)? as u32;
    let rm = aarch64_reg_number(inst.operands.get(2)?)? as u32;
    Some(0x9b007c00 | (rm << 16) | (rn << 5) | rd)
}

fn encode_aarch64_madd_msub(inst: &MachineInstruction) -> Option<u32> {
    let rd = aarch64_reg_number(inst.operands.first()?)? as u32;
    let rn = aarch64_reg_number(inst.operands.get(1)?)? as u32;
    let rm = aarch64_reg_number(inst.operands.get(2)?)? as u32;
    let ra = aarch64_reg_number(inst.operands.get(3)?)? as u32;
    let base = if inst.mnemonic == "madd" {
        0x9b000000
    } else {
        0x9b008000
    };
    Some(base | (rm << 16) | (ra << 10) | (rn << 5) | rd)
}

fn encode_aarch64_div(inst: &MachineInstruction) -> Option<u32> {
    let rd = aarch64_reg_number(inst.operands.first()?)? as u32;
    let rn = aarch64_reg_number(inst.operands.get(1)?)? as u32;
    let rm = aarch64_reg_number(inst.operands.get(2)?)? as u32;
    let base = if inst.mnemonic == "sdiv" {
        0x9ac00c00
    } else {
        0x9ac00800
    };
    Some(base | (rm << 16) | (rn << 5) | rd)
}

fn encode_aarch64_compare_alias(inst: &MachineInstruction) -> Option<u32> {
    let rn = aarch64_reg_number(inst.operands.first()?)? as u32;
    let rm = aarch64_reg_number(inst.operands.get(1)?)? as u32;
    let base = if inst.mnemonic == "cmp" {
        0xeb00001f
    } else {
        0xea00001f
    };
    Some(base | (rm << 16) | (rn << 5))
}

fn encode_aarch64_pointer_auth(inst: &MachineInstruction) -> Option<u32> {
    let rd = aarch64_reg_number(inst.operands.first()?)? as u32;
    let base = match inst.mnemonic.as_str() {
        "xpaci" if inst.operands.len() == 1 => 0xdac1_43e0,
        "xpacd" if inst.operands.len() == 1 => 0xdac1_47e0,
        "paciza" if inst.operands.len() == 1 => 0xdac1_23e0,
        "autiza" if inst.operands.len() == 1 => 0xdac1_33e0,
        "pacia" if inst.operands.len() == 2 => 0xdac1_0000,
        "autda" if inst.operands.len() == 2 => 0xdac1_1800,
        _ => return None,
    };
    if inst.operands.len() == 1 {
        return Some(base | rd);
    }
    let rn = aarch64_reg_number(inst.operands.get(1)?)? as u32;
    Some(base | (rn << 5) | rd)
}

fn encode_aarch64_sve_ptrue(inst: &MachineInstruction) -> Option<u32> {
    let (pd, elem) = aarch64_sve_predicate_elem(inst.operands.first()?)?;
    Some(0x2518e3e0 | (aarch64_sve_element_bits(elem) << 22) | pd)
}

fn encode_aarch64_sve_pfalse(inst: &MachineInstruction) -> Option<u32> {
    let (pd, elem) = aarch64_sve_predicate_elem(inst.operands.first()?)?;
    if elem != Aarch64SveElement::B {
        return None;
    }
    Some(0x2518e400 | pd)
}

fn encode_aarch64_sve_whilelo(inst: &MachineInstruction) -> Option<u32> {
    let (pd, elem) = aarch64_sve_predicate_elem(inst.operands.first()?)?;
    let rn_raw = inst.operands.get(1)?.trim().to_ascii_lowercase();
    let rm_raw = inst.operands.get(2)?.trim().to_ascii_lowercase();
    let rn_width = aarch64_gpr_width(&rn_raw)?;
    if rn_width != aarch64_gpr_width(&rm_raw)? {
        return None;
    }
    let rn = aarch64_reg_number(&rn_raw)? as u32;
    let rm = aarch64_reg_number(&rm_raw)? as u32;
    let base = if rn_width == 32 {
        0x25200c00
    } else {
        0x25201c00
    };
    Some(base | (aarch64_sve_element_bits(elem) << 22) | (rm << 16) | (rn << 5) | pd)
}

fn aarch64_sve_expected_element_for_memory(mnemonic: &str) -> Option<Aarch64SveElement> {
    match mnemonic {
        "ld1b" | "st1b" => Some(Aarch64SveElement::B),
        "ld1h" | "st1h" => Some(Aarch64SveElement::H),
        "ld1w" | "st1w" => Some(Aarch64SveElement::S),
        "ld1d" | "st1d" => Some(Aarch64SveElement::D),
        _ => None,
    }
}

fn aarch64_sve_load_store_base(mnemonic: &str) -> Option<u32> {
    match mnemonic {
        "ld1b" => Some(0xa400a000),
        "ld1h" => Some(0xa4a0a000),
        "ld1w" => Some(0xa540a000),
        "ld1d" => Some(0xa5e0a000),
        "st1b" => Some(0xe400e000),
        "st1h" => Some(0xe4a0e000),
        "st1w" => Some(0xe540e000),
        "st1d" => Some(0xe5e0e000),
        _ => None,
    }
}

fn encode_aarch64_sve_load_store(inst: &MachineInstruction) -> Option<u32> {
    let (zt, elem) = aarch64_sve_z_reg(inst.operands.first()?)?;
    if elem != aarch64_sve_expected_element_for_memory(inst.mnemonic.as_str())? {
        return None;
    }
    let pred = match inst.mnemonic.as_str() {
        "ld1b" | "ld1h" | "ld1w" | "ld1d" => {
            aarch64_sve_predicate(inst.operands.get(1)?, Some("z"))?
        }
        "st1b" | "st1h" | "st1w" | "st1d" => aarch64_sve_predicate(inst.operands.get(1)?, None)?,
        _ => return None,
    };
    let (rn, imm) = aarch64_mem_base(inst.operands.get(2)?)?;
    if imm != 0 {
        return None;
    }
    let base = aarch64_sve_load_store_base(inst.mnemonic.as_str())?;
    Some(base | (pred << 10) | (rn << 5) | zt)
}

fn encode_aarch64_sve_fp_predicated(inst: &MachineInstruction) -> Option<u32> {
    let (zd, zd_elem) = aarch64_sve_z_reg(inst.operands.first()?)?;
    let pred = aarch64_sve_predicate(inst.operands.get(1)?, Some("m"))?;
    let (zn, zn_elem) = aarch64_sve_z_reg(inst.operands.get(2)?)?;
    let (zm, zm_elem) = aarch64_sve_z_reg(inst.operands.get(3)?)?;
    if !matches!(zd_elem, Aarch64SveElement::S | Aarch64SveElement::D)
        || zn_elem != zd_elem
        || zm_elem != zd_elem
        || zn != zd
    {
        return None;
    }
    let base = match inst.mnemonic.as_str() {
        "fadd" => 0x65008000,
        "fsub" => 0x65018000,
        "fmul" => 0x65028000,
        "fdiv" => 0x650d8000,
        _ => return None,
    };
    Some(base | (aarch64_sve_element_bits(zd_elem) << 22) | (pred << 10) | (zm << 5) | zd)
}

fn encode_aarch64_sve_fmla(inst: &MachineInstruction) -> Option<u32> {
    let (zd, zd_elem) = aarch64_sve_z_reg(inst.operands.first()?)?;
    let pred = aarch64_sve_predicate(inst.operands.get(1)?, Some("m"))?;
    let (zn, zn_elem) = aarch64_sve_z_reg(inst.operands.get(2)?)?;
    let (zm, zm_elem) = aarch64_sve_z_reg(inst.operands.get(3)?)?;
    if !matches!(zd_elem, Aarch64SveElement::S | Aarch64SveElement::D)
        || zn_elem != zd_elem
        || zm_elem != zd_elem
    {
        return None;
    }
    Some(
        0x65200000
            | (aarch64_sve_element_bits(zd_elem) << 22)
            | (zm << 16)
            | (pred << 10)
            | (zn << 5)
            | zd,
    )
}

fn encode_aarch64_sve_count(inst: &MachineInstruction) -> Option<u32> {
    let rd_raw = inst.operands.first()?.trim().to_ascii_lowercase();
    if aarch64_gpr_width(&rd_raw)? != 64 {
        return None;
    }
    let rd = aarch64_reg_number(&rd_raw)? as u32;
    let base = match inst.mnemonic.as_str() {
        "cntb" => 0x0420e3e0,
        "cnth" => 0x0460e3e0,
        "cntw" => 0x04a0e3e0,
        "cntd" => 0x04e0e3e0,
        "incb" => 0x0430e3e0,
        "inch" => 0x0470e3e0,
        "incw" => 0x04b0e3e0,
        "incd" => 0x04f0e3e0,
        _ => return None,
    };
    Some(base | rd)
}

fn encode_aarch64_sve_integer_three_operand(inst: &MachineInstruction) -> Option<u32> {
    let (zd, zd_elem) = aarch64_sve_z_reg(inst.operands.first()?)?;
    let (zn, zn_elem) = aarch64_sve_z_reg(inst.operands.get(1)?)?;
    let (zm, zm_elem) = aarch64_sve_z_reg(inst.operands.get(2)?)?;
    if zn_elem != zd_elem || zm_elem != zd_elem {
        return None;
    }
    let (base, encode_element) = match inst.mnemonic.as_str() {
        "add" => (0x04200000, true),
        "sub" => (0x04200400, true),
        "mul" => (0x04206000, true),
        "and" if zd_elem == Aarch64SveElement::D => (0x04203000, false),
        "orr" if zd_elem == Aarch64SveElement::D => (0x04603000, false),
        "eor" if zd_elem == Aarch64SveElement::D => (0x04a03000, false),
        _ => return None,
    };
    Some(
        base | if encode_element {
            aarch64_sve_element_bits(zd_elem) << 22
        } else {
            0
        } | (zm << 16)
            | (zn << 5)
            | zd,
    )
}

fn encode_aarch64_sve_predicate_logic(inst: &MachineInstruction) -> Option<u32> {
    let (pd, pd_elem) = aarch64_sve_predicate_elem(inst.operands.first()?)?;
    if pd_elem != Aarch64SveElement::B {
        return None;
    }
    if inst.mnemonic == "not" {
        let pred = aarch64_sve_predicate(inst.operands.get(1)?, Some("z"))?;
        let (pn, pn_elem) = aarch64_sve_predicate_elem(inst.operands.get(2)?)?;
        if pn_elem != Aarch64SveElement::B {
            return None;
        }
        return Some(0x25004200 | (pred << 16) | (pred << 10) | (pn << 5) | pd);
    }
    let pred = aarch64_sve_predicate(inst.operands.get(1)?, Some("z"))?;
    let (pn, pn_elem) = aarch64_sve_predicate_elem(inst.operands.get(2)?)?;
    let (pm, pm_elem) = aarch64_sve_predicate_elem(inst.operands.get(3)?)?;
    if pn_elem != Aarch64SveElement::B || pm_elem != Aarch64SveElement::B {
        return None;
    }
    let base = match inst.mnemonic.as_str() {
        "and" => 0x25004000,
        "orr" => 0x25804000,
        "eor" => 0x25004200,
        _ => return None,
    };
    Some(base | (pm << 16) | (pred << 10) | (pn << 5) | pd)
}

fn encode_aarch64_sve_compare(inst: &MachineInstruction) -> Option<u32> {
    let (pd, elem) = aarch64_sve_predicate_elem(inst.operands.first()?)?;
    let pred = aarch64_sve_predicate(inst.operands.get(1)?, Some("z"))?;
    let (zn, zn_elem) = aarch64_sve_z_reg(inst.operands.get(2)?)?;
    let (zm, zm_elem) = aarch64_sve_z_reg(inst.operands.get(3)?)?;
    if zn_elem != elem || zm_elem != elem {
        return None;
    }
    let (base, zn, zm) = match inst.mnemonic.as_str() {
        "cmpeq" => (0x2400a000, zn, zm),
        "cmpne" => (0x2400a010, zn, zm),
        "cmpge" => (0x24008000, zn, zm),
        "cmpgt" => (0x24008010, zn, zm),
        "cmple" => (0x24008000, zm, zn),
        "cmplt" => (0x24008010, zm, zn),
        _ => return None,
    };
    Some(base | (aarch64_sve_element_bits(elem) << 22) | (zm << 16) | (pred << 10) | (zn << 5) | pd)
}

fn encode_aarch64_sve_select(inst: &MachineInstruction) -> Option<u32> {
    let (zd, zd_elem) = aarch64_sve_z_reg(inst.operands.first()?)?;
    let pred = aarch64_sve_predicate(inst.operands.get(1)?, None)?;
    let (zn, zn_elem) = aarch64_sve_z_reg(inst.operands.get(2)?)?;
    let (zm, zm_elem) = aarch64_sve_z_reg(inst.operands.get(3)?)?;
    if zn_elem != zd_elem || zm_elem != zd_elem {
        return None;
    }
    Some(
        0x0520c000
            | (aarch64_sve_element_bits(zd_elem) << 22)
            | (zm << 16)
            | (pred << 10)
            | (zn << 5)
            | zd,
    )
}

fn encode_aarch64_sve_faddv(inst: &MachineInstruction) -> Option<u32> {
    let (vd, width) = aarch64_fp_reg(inst.operands.first()?)?;
    let pred = aarch64_sve_predicate(inst.operands.get(1)?, None)?;
    let (zn, elem) = aarch64_sve_z_reg(inst.operands.get(2)?)?;
    let required = match width {
        Aarch64FpWidth::S => Aarch64SveElement::S,
        Aarch64FpWidth::D => Aarch64SveElement::D,
    };
    if elem != required {
        return None;
    }
    Some(0x65002000 | (aarch64_sve_element_bits(elem) << 22) | (pred << 10) | (zn << 5) | vd)
}

fn aarch64_fp_width_bit(width: Aarch64FpWidth) -> u32 {
    match width {
        Aarch64FpWidth::S => 0,
        Aarch64FpWidth::D => 1,
    }
}

fn encode_aarch64_fp_move(inst: &MachineInstruction) -> Option<u32> {
    let (rd, width) = aarch64_fp_reg(inst.operands.first()?)?;
    let (rn, rn_width) = aarch64_fp_reg(inst.operands.get(1)?)?;
    if width != rn_width {
        return None;
    }
    Some(0x1e204000 | (aarch64_fp_width_bit(width) << 22) | (rn << 5) | rd)
}

fn encode_aarch64_fp_three_operand(inst: &MachineInstruction) -> Option<u32> {
    let (rd, width) = aarch64_fp_reg(inst.operands.first()?)?;
    let (rn, rn_width) = aarch64_fp_reg(inst.operands.get(1)?)?;
    let (rm, rm_width) = aarch64_fp_reg(inst.operands.get(2)?)?;
    if width != rn_width || width != rm_width {
        return None;
    }
    let base = match inst.mnemonic.as_str() {
        "fadd" => 0x1e202800,
        "fsub" => 0x1e203800,
        "fmul" => 0x1e200800,
        "fdiv" => 0x1e201800,
        "fmax" => 0x1e204800,
        "fmin" => 0x1e205800,
        _ => return None,
    };
    Some(base | (aarch64_fp_width_bit(width) << 22) | (rm << 16) | (rn << 5) | rd)
}

fn encode_aarch64_fp_unary(inst: &MachineInstruction) -> Option<u32> {
    let (rd, width) = aarch64_fp_reg(inst.operands.first()?)?;
    let (rn, rn_width) = aarch64_fp_reg(inst.operands.get(1)?)?;
    if width != rn_width {
        return None;
    }
    let base = match inst.mnemonic.as_str() {
        "fabs" => 0x1e20c000,
        "fneg" => 0x1e214000,
        "fsqrt" => 0x1e21c000,
        _ => return None,
    };
    Some(base | (aarch64_fp_width_bit(width) << 22) | (rn << 5) | rd)
}

fn encode_aarch64_fp_compare(inst: &MachineInstruction) -> Option<u32> {
    let (rn, width) = aarch64_fp_reg(inst.operands.first()?)?;
    let rhs = inst.operands.get(1)?;
    if matches!(rhs.trim(), "#0.0" | "0.0" | "#0" | "0") {
        return Some(0x1e202008 | (aarch64_fp_width_bit(width) << 22) | (rn << 5));
    }
    let (rm, rm_width) = aarch64_fp_reg(rhs)?;
    if width != rm_width {
        return None;
    }
    Some(0x1e202000 | (aarch64_fp_width_bit(width) << 22) | (rm << 16) | (rn << 5))
}

fn encode_aarch64_fp_convert_from_int(inst: &MachineInstruction) -> Option<u32> {
    let (rd, fp_width) = aarch64_fp_reg(inst.operands.first()?)?;
    let rn_raw = inst.operands.get(1)?.trim().to_ascii_lowercase();
    let rn_width = aarch64_gpr_width(&rn_raw)?;
    let rn = aarch64_reg_number(&rn_raw)? as u32;
    if !matches!(rn_width, 32 | 64) {
        return None;
    }
    let base = 0x1e220000
        | if rn_width == 64 { 0x80000000 } else { 0 }
        | (aarch64_fp_width_bit(fp_width) << 22);
    Some(base | (rn << 5) | rd)
}

fn encode_aarch64_fp_convert_to_int(inst: &MachineInstruction) -> Option<u32> {
    let rd_raw = inst.operands.first()?.trim().to_ascii_lowercase();
    let rd_width = aarch64_gpr_width(&rd_raw)?;
    let rd = aarch64_reg_number(&rd_raw)? as u32;
    let (rn, fp_width) = aarch64_fp_reg(inst.operands.get(1)?)?;
    if !matches!(rd_width, 32 | 64) {
        return None;
    }
    let base = 0x1e380000
        | if rd_width == 64 { 0x80000000 } else { 0 }
        | (aarch64_fp_width_bit(fp_width) << 22);
    Some(base | (rn << 5) | rd)
}

fn encode_aarch64_fp_convert_width(inst: &MachineInstruction) -> Option<u32> {
    let (rd, rd_width) = aarch64_fp_reg(inst.operands.first()?)?;
    let (rn, rn_width) = aarch64_fp_reg(inst.operands.get(1)?)?;
    let base = match (rd_width, rn_width) {
        (Aarch64FpWidth::D, Aarch64FpWidth::S) => 0x1e22c000,
        (Aarch64FpWidth::S, Aarch64FpWidth::D) => 0x1e624000,
        _ => return None,
    };
    Some(base | (rn << 5) | rd)
}

fn encode_aarch64_fp_select(inst: &MachineInstruction) -> Option<u32> {
    let (rd, width) = aarch64_fp_reg(inst.operands.first()?)?;
    let (rn, rn_width) = aarch64_fp_reg(inst.operands.get(1)?)?;
    let (rm, rm_width) = aarch64_fp_reg(inst.operands.get(2)?)?;
    if width != rn_width || width != rm_width {
        return None;
    }
    let cond = aarch64_cond_code(inst.operands.get(3)?.trim())? as u32;
    Some(
        0x1e200c00
            | (aarch64_fp_width_bit(width) << 22)
            | (rm << 16)
            | (cond << 12)
            | (rn << 5)
            | rd,
    )
}

fn encode_aarch64_neon_three_operand(inst: &MachineInstruction) -> Option<u32> {
    let rd = aarch64_vec_reg(inst.operands.first()?)?;
    let rn = aarch64_vec_reg(inst.operands.get(1)?)?;
    let rm = aarch64_vec_reg(inst.operands.get(2)?)?;
    if rd.arrangement != rn.arrangement || rd.arrangement != rm.arrangement {
        return None;
    }
    let base = match (inst.mnemonic.as_str(), rd.arrangement) {
        ("fadd", Aarch64VecArrangement::S4) => 0x4e20d400,
        ("fmul", Aarch64VecArrangement::S4) => 0x6e20dc00,
        ("add", Aarch64VecArrangement::S4) => 0x4ea08400,
        ("mul", Aarch64VecArrangement::S4) => 0x4ea09c00,
        ("and", Aarch64VecArrangement::B16) => 0x4e201c00,
        ("orr", Aarch64VecArrangement::B16) => 0x4ea01c00,
        ("eor", Aarch64VecArrangement::B16) => 0x6e201c00,
        ("bsl", Aarch64VecArrangement::B16) => 0x6e601c00,
        _ => return None,
    };
    Some(base | (rm.code << 16) | (rn.code << 5) | rd.code)
}

fn encode_aarch64_neon_q_load_store(inst: &MachineInstruction) -> Option<u32> {
    let rt = aarch64_q_reg(inst.operands.first()?)?;
    let (rn, imm) = aarch64_mem_base(inst.operands.get(1)?)?;
    if imm % 16 != 0 || imm / 16 > 4095 {
        return None;
    }
    let base = match inst.mnemonic.as_str() {
        "ldr" => 0x3dc00000,
        "str" => 0x3d800000,
        _ => return None,
    };
    Some(base | ((imm / 16) << 10) | (rn << 5) | rt)
}

fn encode_aarch64_neon_rev64(inst: &MachineInstruction) -> Option<u32> {
    let rd = aarch64_vec_reg(inst.operands.first()?)?;
    let rn = aarch64_vec_reg(inst.operands.get(1)?)?;
    if rd.arrangement != Aarch64VecArrangement::S4 || rn.arrangement != Aarch64VecArrangement::S4 {
        return None;
    }
    Some(0x4ea00800 | (rn.code << 5) | rd.code)
}

fn encode_aarch64_neon_tbl(inst: &MachineInstruction) -> Option<u32> {
    let rd = aarch64_vec_reg(inst.operands.first()?)?;
    let rn = aarch64_vec_reg(inst.operands.get(1)?)?;
    let rm = aarch64_vec_reg(inst.operands.get(2)?)?;
    if rd.arrangement != Aarch64VecArrangement::B16
        || rn.arrangement != Aarch64VecArrangement::B16
        || rm.arrangement != Aarch64VecArrangement::B16
    {
        return None;
    }
    Some(0x4e000000 | (rm.code << 16) | (rn.code << 5) | rd.code)
}

fn encode_aarch64_neon_lane_load_store(inst: &MachineInstruction) -> Option<u32> {
    let (rt, lane) = aarch64_vec_lane_s(inst.operands.first()?)?;
    if lane != 0 {
        return None;
    }
    let (rn, imm) = aarch64_mem_base(inst.operands.get(1)?)?;
    if imm != 0 {
        return None;
    }
    let base = match inst.mnemonic.as_str() {
        "ld1" => 0x0d408000,
        "st1" => 0x0d008000,
        _ => return None,
    };
    Some(base | (rn << 5) | rt)
}

fn encode_aarch64_exclusive_load(inst: &MachineInstruction, acquire: bool) -> Option<u32> {
    let rt_raw = inst.operands.first()?.trim().to_ascii_lowercase();
    let rt = aarch64_reg_number(&rt_raw)? as u32;
    let width = aarch64_gpr_width(&rt_raw)?;
    let (rn, imm) = aarch64_mem_base(inst.operands.get(1)?)?;
    if imm != 0 {
        return None;
    }
    let base = match (width, acquire) {
        (32, false) => 0x885f7c00,
        (64, false) => 0xc85f7c00,
        (32, true) => 0x885ffc00,
        (64, true) => 0xc85ffc00,
        _ => return None,
    };
    Some(base | (rn << 5) | rt)
}

fn encode_aarch64_exclusive_store(inst: &MachineInstruction, release: bool) -> Option<u32> {
    let rs_raw = inst.operands.first()?.trim().to_ascii_lowercase();
    let rt_raw = inst.operands.get(1)?.trim().to_ascii_lowercase();
    if aarch64_gpr_width(&rs_raw)? != 32 {
        return None;
    }
    let rs = aarch64_reg_number(&rs_raw)? as u32;
    let rt = aarch64_reg_number(&rt_raw)? as u32;
    let width = aarch64_gpr_width(&rt_raw)?;
    let (rn, imm) = aarch64_mem_base(inst.operands.get(2)?)?;
    if imm != 0 {
        return None;
    }
    let base = match (width, release) {
        (32, false) => 0x88007c00,
        (64, false) => 0xc8007c00,
        (32, true) => 0x8800fc00,
        (64, true) => 0xc800fc00,
        _ => return None,
    };
    Some(base | (rs << 16) | (rn << 5) | rt)
}

fn encode_aarch64_ordered_load_store(inst: &MachineInstruction) -> Option<u32> {
    let rt_raw = inst.operands.first()?.trim().to_ascii_lowercase();
    let rt = aarch64_reg_number(&rt_raw)? as u32;
    let width = aarch64_gpr_width(&rt_raw)?;
    let (rn, imm) = aarch64_mem_base(inst.operands.get(1)?)?;
    if imm != 0 {
        return None;
    }
    let base = match (inst.mnemonic.as_str(), width) {
        ("ldar", 32) => 0x88dffc00,
        ("ldar", 64) => 0xc8dffc00,
        ("stlr", 32) => 0x889ffc00,
        ("stlr", 64) => 0xc89ffc00,
        _ => return None,
    };
    Some(base | (rn << 5) | rt)
}

fn encode_aarch64_lse_cas(inst: &MachineInstruction) -> Option<u32> {
    let rs_raw = inst.operands.first()?.trim().to_ascii_lowercase();
    let rt_raw = inst.operands.get(1)?.trim().to_ascii_lowercase();
    let width = aarch64_gpr_width(&rs_raw)?;
    if width != aarch64_gpr_width(&rt_raw)? {
        return None;
    }
    let rs = aarch64_reg_number(&rs_raw)? as u32;
    let rt = aarch64_reg_number(&rt_raw)? as u32;
    let (rn, imm) = aarch64_mem_base(inst.operands.get(2)?)?;
    if imm != 0 {
        return None;
    }
    let base = match (inst.mnemonic.as_str(), width) {
        ("cas", 32) => 0x88a07c00,
        ("cas", 64) => 0xc8a07c00,
        ("casa", 32) => 0x88e07c00,
        ("casa", 64) => 0xc8e07c00,
        ("casl", 32) => 0x88a0fc00,
        ("casl", 64) => 0xc8a0fc00,
        ("casal", 32) => 0x88e0fc00,
        ("casal", 64) => 0xc8e0fc00,
        _ => return None,
    };
    Some(base | (rs << 16) | (rn << 5) | rt)
}

fn encode_aarch64_lse_swp(inst: &MachineInstruction) -> Option<u32> {
    let rs_raw = inst.operands.first()?.trim().to_ascii_lowercase();
    let rt_raw = inst.operands.get(1)?.trim().to_ascii_lowercase();
    let width = aarch64_gpr_width(&rs_raw)?;
    if width != aarch64_gpr_width(&rt_raw)? {
        return None;
    }
    let rs = aarch64_reg_number(&rs_raw)? as u32;
    let rt = aarch64_reg_number(&rt_raw)? as u32;
    let (rn, imm) = aarch64_mem_base(inst.operands.get(2)?)?;
    if imm != 0 {
        return None;
    }
    let base = match (inst.mnemonic.as_str(), width) {
        ("swp", 32) => 0xb8208000,
        ("swp", 64) => 0xf8208000,
        ("swpa", 32) => 0xb8a08000,
        ("swpa", 64) => 0xf8a08000,
        ("swpl", 32) => 0xb8608000,
        ("swpl", 64) => 0xf8608000,
        ("swpal", 32) => 0xb8e08000,
        ("swpal", 64) => 0xf8e08000,
        _ => return None,
    };
    Some(base | (rs << 16) | (rn << 5) | rt)
}

fn encode_aarch64_lse_ldop(inst: &MachineInstruction) -> Option<u32> {
    let rs_raw = inst.operands.first()?.trim().to_ascii_lowercase();
    let rt_raw = inst.operands.get(1)?.trim().to_ascii_lowercase();
    let width = aarch64_gpr_width(&rs_raw)?;
    if width != aarch64_gpr_width(&rt_raw)? {
        return None;
    }
    let rs = aarch64_reg_number(&rs_raw)? as u32;
    let rt = aarch64_reg_number(&rt_raw)? as u32;
    let (rn, imm) = aarch64_mem_base(inst.operands.get(2)?)?;
    if imm != 0 {
        return None;
    }
    let (order_base32, order_base64) = match inst.mnemonic.as_str() {
        "ldadd" | "ldclr" | "ldeor" | "ldset" => (0xb8200000, 0xf8200000),
        "ldadda" | "ldclra" | "ldeora" | "ldseta" => (0xb8a00000, 0xf8a00000),
        "ldaddl" | "ldclrl" | "ldeorl" | "ldsetl" => (0xb8600000, 0xf8600000),
        "ldaddal" | "ldclral" | "ldeoral" | "ldsetal" => (0xb8e00000, 0xf8e00000),
        _ => return None,
    };
    let op_bits = if inst.mnemonic.starts_with("ldadd") {
        0x0000
    } else if inst.mnemonic.starts_with("ldclr") {
        0x1000
    } else if inst.mnemonic.starts_with("ldeor") {
        0x2000
    } else if inst.mnemonic.starts_with("ldset") {
        0x3000
    } else {
        return None;
    };
    let base = match width {
        32 => order_base32,
        64 => order_base64,
        _ => return None,
    };
    Some(base | op_bits | (rs << 16) | (rn << 5) | rt)
}

fn aarch64_mem_base(raw: &str) -> Option<(u32, u32)> {
    let (rn, imm) = aarch64_mem_base_signed(raw)?;
    Some((rn, u32::try_from(imm).ok()?))
}

fn aarch64_mem_base_signed(raw: &str) -> Option<(u32, i32)> {
    let raw = raw.trim();
    let inner = raw.strip_prefix('[')?.strip_suffix(']')?;
    let compact = inner
        .chars()
        .filter(|ch| !ch.is_ascii_whitespace())
        .collect::<String>();
    let (base, offset) = if let Some((base, offset)) = compact.split_once(',') {
        (base, Some(offset))
    } else if let Some(index) = compact
        .char_indices()
        .skip(1)
        .find_map(|(index, ch)| matches!(ch, '+' | '-').then_some(index))
    {
        (&compact[..index], Some(&compact[index..]))
    } else {
        (compact.as_str(), None)
    };
    let rn = aarch64_reg_number(base)? as u32;
    let imm = match offset {
        Some(value) => parse_i32(value.trim_start_matches('#'))?,
        None => 0,
    };
    Some((rn, imm))
}

fn encode_aarch64_load_store(inst: &MachineInstruction) -> Option<u32> {
    let rt_raw = inst.operands.first()?.trim().to_ascii_lowercase();
    let rt = aarch64_reg_number(&rt_raw)? as u32;
    let width = aarch64_gpr_width(&rt_raw)?;
    let (rn, imm) = aarch64_mem_base(inst.operands.get(1)?)?;
    let (base, scale) = match (inst.mnemonic.as_str(), width) {
        ("ldr", 32) => (0xb9400000, 4),
        ("ldr", 64) => (0xf9400000, 8),
        ("str", 32) => (0xb9000000, 4),
        ("str", 64) => (0xf9000000, 8),
        ("ldrb", 32) => (0x39400000, 1),
        ("strb", 32) => (0x39000000, 1),
        ("ldrh", 32) => (0x79400000, 2),
        ("strh", 32) => (0x79000000, 2),
        ("ldrsb", 32) => (0x39c00000, 1),
        ("ldrsb", 64) => (0x39800000, 1),
        ("ldrsh", 32) => (0x79c00000, 2),
        ("ldrsh", 64) => (0x79800000, 2),
        ("ldrsw", 64) => (0xb9800000, 4),
        _ => return None,
    };
    if imm % scale != 0 || imm / scale > 4095 {
        return None;
    }
    Some(base | ((imm / scale) << 10) | (rn << 5) | rt)
}

fn encode_aarch64_unscaled_load_store(inst: &MachineInstruction) -> Option<u32> {
    let rt_raw = inst.operands.first()?.trim().to_ascii_lowercase();
    let rt = aarch64_reg_number(&rt_raw)? as u32;
    let width = aarch64_gpr_width(&rt_raw)?;
    let (rn, imm) = aarch64_mem_base_signed(inst.operands.get(1)?)?;
    if !(-256..=255).contains(&imm) {
        return None;
    }
    let base = match (inst.mnemonic.as_str(), width) {
        ("ldur", 32) => 0xb8400000,
        ("ldur", 64) => 0xf8400000,
        ("stur", 32) => 0xb8000000,
        ("stur", 64) => 0xf8000000,
        _ => return None,
    };
    Some(base | (((imm as u32) & 0x1ff) << 12) | (rn << 5) | rt)
}

fn encode_aarch64_pair_load_store(inst: &MachineInstruction) -> Option<u32> {
    let rt = aarch64_reg_number(inst.operands.first()?)? as u32;
    let rt2 = aarch64_reg_number(inst.operands.get(1)?)? as u32;
    let (rn, imm) = aarch64_mem_base(inst.operands.get(2)?)?;
    if imm % 8 != 0 || imm > 504 {
        return None;
    }
    let base = if inst.mnemonic == "ldp" {
        0xa9400000
    } else {
        0xa9000000
    };
    Some(base | ((imm / 8) << 15) | (rt2 << 10) | (rn << 5) | rt)
}

fn encode_aarch64_shift_alias(inst: &MachineInstruction) -> Option<u32> {
    let rd = aarch64_reg_number(inst.operands.first()?)? as u32;
    let rn = aarch64_reg_number(inst.operands.get(1)?)? as u32;
    let shift = parse_int(inst.operands.get(2)?.trim_start_matches('#'))? as u32;
    if shift > 63 {
        return None;
    }
    let base = match inst.mnemonic.as_str() {
        "lsl" => 0xd37ff800,
        "lsr" => 0xd340fc00,
        "asr" => 0x9340fc00,
        _ => return None,
    };
    Some(base | (shift << 10) | (rn << 5) | rd)
}

fn encode_aarch64_exception(inst: &MachineInstruction, base: u32) -> Option<u32> {
    let imm = inst
        .operands
        .first()
        .and_then(|op| parse_int(op.trim_start_matches('#')))
        .unwrap_or(0);
    if !(0..=0xffff).contains(&imm) {
        return None;
    }
    Some(base | ((imm as u32) << 5))
}

fn encode_aarch64_mrs(inst: &MachineInstruction) -> Option<u32> {
    if inst.operands.len() != 2 {
        return None;
    }
    let destination = aarch64_reg_number(inst.operands.first()?)?;
    let register = inst.operands.get(1)?.trim().to_ascii_lowercase();
    Some(aarch64_system_register(&register)?.encode_mrs(destination))
}

fn encode_aarch64_msr(inst: &MachineInstruction) -> Option<u32> {
    if inst.operands.len() != 2 {
        return None;
    }
    let register = inst.operands.first()?.trim().to_ascii_lowercase();
    let source = aarch64_reg_number(inst.operands.get(1)?)?;
    Some(aarch64_system_register(&register)?.encode_msr(source))
}

fn encode_aarch64_barrier(inst: &MachineInstruction) -> Option<u32> {
    if inst.operands.len() > 1 {
        return None;
    }
    let option = inst
        .operands
        .first()
        .map(|value| value.trim().to_ascii_lowercase())
        .unwrap_or_else(|| "sy".to_string());
    let crm = match option.as_str() {
        "oshld" => 1,
        "oshst" => 2,
        "osh" => 3,
        "nshld" => 5,
        "nshst" => 6,
        "nsh" => 7,
        "ishld" => 9,
        "ishst" => 10,
        "ish" => 11,
        "ld" => 13,
        "st" => 14,
        "sy" => 15,
        _ => return None,
    };
    let base = match inst.mnemonic.as_str() {
        "dmb" => 0xd50330bf,
        "dsb" => 0xd503309f,
        "isb" if crm == 15 => 0xd50330df,
        _ => return None,
    };
    Some(base | (crm << 8))
}

fn encode_aarch64_tlbi(inst: &MachineInstruction) -> Option<u32> {
    let operation = inst.operands.first()?.trim().to_ascii_lowercase();
    let (base, register_required) = match operation.as_str() {
        "vmalle1" => (0xd508871f, false),
        "vmalle1is" => (0xd508831f, false),
        "vae1" => (0xd5088720, true),
        "vae1is" => (0xd5088320, true),
        "vale1is" => (0xd50883a0, true),
        "vaale1is" => (0xd50883e0, true),
        "aside1" => (0xd5088740, true),
        "aside1is" => (0xd5088340, true),
        _ => return None,
    };
    if register_required {
        if inst.operands.len() != 2 {
            return None;
        }
        Some(base | aarch64_reg_number(inst.operands.get(1)?)? as u32)
    } else if inst.operands.len() == 1 {
        Some(base)
    } else {
        None
    }
}

fn encode_aarch64_dc(inst: &MachineInstruction) -> Option<u32> {
    if inst.operands.len() != 2 {
        return None;
    }
    let base = match inst.operands.first()?.trim().to_ascii_lowercase().as_str() {
        "cvau" => 0xd50b7b20,
        "cvac" => 0xd50b7a20,
        "civac" => 0xd50b7e20,
        "ivac" => 0xd5087620,
        "zva" => 0xd50b7420,
        _ => return None,
    };
    Some(base | aarch64_reg_number(inst.operands.get(1)?)? as u32)
}

fn encode_aarch64_ic(inst: &MachineInstruction) -> Option<u32> {
    let operation = inst.operands.first()?.trim().to_ascii_lowercase();
    match operation.as_str() {
        "ivau" if inst.operands.len() == 2 => {
            Some(0xd50b7520 | aarch64_reg_number(inst.operands.get(1)?)? as u32)
        }
        "iallu" if inst.operands.len() == 1 => Some(0xd508751f),
        "ialluis" if inst.operands.len() == 1 => Some(0xd508711f),
        _ => None,
    }
}

fn aarch64_cond_code(cond: &str) -> Option<u8> {
    match cond {
        "eq" => Some(0),
        "ne" => Some(1),
        "hs" | "cs" => Some(2),
        "lo" | "cc" => Some(3),
        "mi" => Some(4),
        "pl" => Some(5),
        "vs" => Some(6),
        "vc" => Some(7),
        "hi" => Some(8),
        "ls" => Some(9),
        "ge" => Some(10),
        "lt" => Some(11),
        "gt" => Some(12),
        "le" => Some(13),
        "al" => Some(14),
        _ => None,
    }
}

fn resolve_riscv_control_targets(
    instructions: &[MachineInstruction],
    compressed: bool,
) -> Vec<MachineInstruction> {
    let mut labels = HashMap::<String, i128>::new();
    let mut pc = 0_i128;
    for inst in instructions {
        if inst.mnemonic == "label" {
            if let Some(name) = inst.operands.first() {
                labels.insert(name.clone(), pc);
            }
        } else {
            pc += riscv_nominal_instruction_len(inst, compressed) as i128;
        }
    }

    let mut resolved = Vec::with_capacity(instructions.len());
    pc = 0;
    for inst in instructions {
        let mut inst = inst.clone();
        let target_index = match inst.mnemonic.as_str() {
            "beq" | "bne" | "blt" | "bge" | "bltu" | "bgeu" => Some(2),
            "c.beqz" | "c.bnez" => Some(1),
            "jal" => inst.operands.len().checked_sub(1),
            "c.j" | "c.jal" | "call" => Some(0),
            _ => None,
        };
        if let Some(index) = target_index {
            if let Some(target) = inst.operands.get(index).cloned() {
                if parse_int(&target).is_none() {
                    if let Some(target_pc) = labels.get(&target) {
                        inst.operands[index] = (target_pc - pc).to_string();
                    }
                }
            }
        }
        if inst.mnemonic != "label" {
            pc += riscv_nominal_instruction_len(&inst, compressed) as i128;
        }
        resolved.push(inst);
    }
    resolved
}

fn riscv_nominal_instruction_len(inst: &MachineInstruction, compressed: bool) -> usize {
    if inst.mnemonic == "label" {
        0
    } else if compressed && inst.mnemonic.starts_with("c.") {
        2
    } else if inst.mnemonic == "call" {
        8
    } else {
        4
    }
}

fn encode_riscv64_instructions(
    instructions: &[MachineInstruction],
    diagnostics: &mut Vec<MachineDiagnostic>,
) -> Vec<u8> {
    let mut bytes = Vec::new();
    let instructions = resolve_riscv_control_targets(instructions, false);
    for inst in &instructions {
        let word = match inst.mnemonic.as_str() {
            "label" => continue,
            "nop" => Some(0x00000013),
            "ret" => Some(0x00008067),
            "ecall" => Some(0x00000073),
            "ebreak" => Some(0x00100073),
            "fence" => Some(0x0ff0000f),
            "fence.tso" => Some(0x8330000f),
            "fence.i" => Some(0x0000100f),
            "cbo.clean" | "cbo.flush" | "cbo.inval" | "cbo.zero" => encode_riscv_cache_block(inst),
            "pause" => Some(0x0100000f),
            "wrs.nto" => Some(0x00d00073),
            "wrs.sto" => Some(0x01d00073),
            "wfi" => Some(0x10500073),
            "sret" => Some(0x10200073),
            "mret" => Some(0x30200073),
            "sfence.vma" => encode_riscv_sfence_vma(inst),
            "sfence.w.inval" if inst.operands.is_empty() => Some(0x1800_0073),
            "sfence.inval.ir" if inst.operands.is_empty() => Some(0x1810_0073),
            "sinval.vma" => encode_riscv_sinval_vma(inst),
            "hfence.vvma" | "hfence.gvma" | "hinval.vvma" | "hinval.gvma" => {
                encode_riscv_hypervisor_fence(inst)
            }
            "hlv.b" | "hlv.bu" | "hlv.h" | "hlv.hu" | "hlv.w" | "hlv.wu" | "hlv.d" | "hlvx.hu"
            | "hlvx.wu" | "hsv.b" | "hsv.h" | "hsv.w" | "hsv.d" => {
                encode_riscv_hypervisor_memory(inst, true)
            }
            "lui" => encode_riscv_u_type(inst, 0x37),
            "auipc" => encode_riscv_u_type(inst, 0x17),
            "addi" => encode_riscv_i_type(inst, 0x13, 0),
            "slti" => encode_riscv_i_type(inst, 0x13, 2),
            "sltiu" => encode_riscv_i_type(inst, 0x13, 3),
            "xori" => encode_riscv_i_type(inst, 0x13, 4),
            "ori" => encode_riscv_i_type(inst, 0x13, 6),
            "andi" => encode_riscv_i_type(inst, 0x13, 7),
            "slli" => encode_riscv_shift_imm(inst, 1, 0),
            "srli" => encode_riscv_shift_imm(inst, 5, 0),
            "srai" => encode_riscv_shift_imm(inst, 5, 0x20),
            "jalr" => encode_riscv_i_type(inst, 0x67, 0),
            "lb" => encode_riscv_load(inst, 0x03, 0),
            "lh" => encode_riscv_load(inst, 0x03, 1),
            "ld" => encode_riscv_load(inst, 0x03, 3),
            "lw" => encode_riscv_load(inst, 0x03, 2),
            "lbu" => encode_riscv_load(inst, 0x03, 4),
            "lhu" => encode_riscv_load(inst, 0x03, 5),
            "lwu" => encode_riscv_load(inst, 0x03, 6),
            "sb" => encode_riscv_store(inst, 0x23, 0),
            "sh" => encode_riscv_store(inst, 0x23, 1),
            "sd" => encode_riscv_store(inst, 0x23, 3),
            "sw" => encode_riscv_store(inst, 0x23, 2),
            "add" => encode_riscv_r_type(inst, 0x33, 0, 0),
            "sub" => encode_riscv_r_type(inst, 0x33, 0, 0x20),
            "sll" => encode_riscv_r_type(inst, 0x33, 1, 0),
            "slt" => encode_riscv_r_type(inst, 0x33, 2, 0),
            "sltu" => encode_riscv_r_type(inst, 0x33, 3, 0),
            "xor" => encode_riscv_r_type(inst, 0x33, 4, 0),
            "srl" => encode_riscv_r_type(inst, 0x33, 5, 0),
            "sra" => encode_riscv_r_type(inst, 0x33, 5, 0x20),
            "or" => encode_riscv_r_type(inst, 0x33, 6, 0),
            "and" => encode_riscv_r_type(inst, 0x33, 7, 0),
            "andn" => encode_riscv_r_type(inst, 0x33, 7, 0x20),
            "orn" => encode_riscv_r_type(inst, 0x33, 6, 0x20),
            "xnor" => encode_riscv_r_type(inst, 0x33, 4, 0x20),
            "min" => encode_riscv_r_type(inst, 0x33, 4, 0x05),
            "minu" => encode_riscv_r_type(inst, 0x33, 5, 0x05),
            "max" => encode_riscv_r_type(inst, 0x33, 6, 0x05),
            "maxu" => encode_riscv_r_type(inst, 0x33, 7, 0x05),
            "rol" => encode_riscv_r_type(inst, 0x33, 1, 0x30),
            "ror" => encode_riscv_r_type(inst, 0x33, 5, 0x30),
            "bset" => encode_riscv_r_type(inst, 0x33, 1, 0x14),
            "bclr" => encode_riscv_r_type(inst, 0x33, 1, 0x24),
            "binv" => encode_riscv_r_type(inst, 0x33, 1, 0x34),
            "bext" => encode_riscv_r_type(inst, 0x33, 5, 0x24),
            "bseti" | "bclri" | "binvi" | "bexti" => encode_riscv_zbs_immediate(inst, 64),
            "czero.eqz" => encode_riscv_r_type(inst, 0x33, 5, 0x07),
            "czero.nez" => encode_riscv_r_type(inst, 0x33, 7, 0x07),
            "clz" | "ctz" | "cpop" => encode_riscv_zbb_unary(inst, 0x13),
            "sext.b" | "sext.h" | "orc.b" | "rev8" | "zext.h" => {
                encode_riscv_zbb_extended_unary(inst, 64)
            }
            "mul" => encode_riscv_r_type(inst, 0x33, 0, 1),
            "mulh" => encode_riscv_r_type(inst, 0x33, 1, 1),
            "mulhsu" => encode_riscv_r_type(inst, 0x33, 2, 1),
            "mulhu" => encode_riscv_r_type(inst, 0x33, 3, 1),
            "div" => encode_riscv_r_type(inst, 0x33, 4, 1),
            "divu" => encode_riscv_r_type(inst, 0x33, 5, 1),
            "rem" => encode_riscv_r_type(inst, 0x33, 6, 1),
            "remu" => encode_riscv_r_type(inst, 0x33, 7, 1),
            "addw" => encode_riscv_r_type(inst, 0x3b, 0, 0),
            "subw" => encode_riscv_r_type(inst, 0x3b, 0, 0x20),
            "sllw" => encode_riscv_r_type(inst, 0x3b, 1, 0),
            "srlw" => encode_riscv_r_type(inst, 0x3b, 5, 0),
            "sraw" => encode_riscv_r_type(inst, 0x3b, 5, 0x20),
            "rolw" => encode_riscv_r_type(inst, 0x3b, 1, 0x30),
            "rorw" => encode_riscv_r_type(inst, 0x3b, 5, 0x30),
            "clzw" | "ctzw" | "cpopw" => encode_riscv_zbb_unary(inst, 0x1b),
            mnemonic if riscv_atomic_spec(mnemonic, true).is_some() => {
                encode_riscv_atomic(inst, true)
            }
            "csrr" => encode_riscv_csr_pseudo(inst, true),
            "csrw" => encode_riscv_csr_pseudo(inst, false),
            "csrrw" => encode_riscv_csr(inst, 1, false),
            "csrrs" => encode_riscv_csr(inst, 2, false),
            "csrrc" => encode_riscv_csr(inst, 3, false),
            "csrrwi" => encode_riscv_csr(inst, 5, true),
            "csrrsi" => encode_riscv_csr(inst, 6, true),
            "csrrci" => encode_riscv_csr(inst, 7, true),
            "call" => {
                let Some((auipc, jalr)) = encode_riscv_call_pair(inst) else {
                    diagnostics.push(MachineDiagnostic::new(
                        "E_MACHINE_ENCODING_001",
                        format!("riscv64 encoding for '{}' is not available", inst.text),
                    ));
                    continue;
                };
                bytes.extend(auipc.to_le_bytes());
                bytes.extend(jalr.to_le_bytes());
                continue;
            }
            "jal" => encode_riscv_jal(inst),
            "beq" | "bne" | "blt" | "bge" | "bltu" | "bgeu" => encode_riscv_branch(inst),
            _ => None,
        };
        if let Some(word) = word {
            bytes.extend(word.to_le_bytes());
        } else {
            diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_ENCODING_001",
                format!("riscv64 encoding for '{}' is not available", inst.text),
            ));
        }
    }
    bytes
}

fn encode_riscv32_instructions(
    instructions: &[MachineInstruction],
    diagnostics: &mut Vec<MachineDiagnostic>,
) -> Vec<u8> {
    let mut bytes = Vec::new();
    let instructions = resolve_riscv_control_targets(instructions, true);
    for inst in &instructions {
        if inst.mnemonic == "label" {
            continue;
        }
        if let Some(half) = match inst.mnemonic.as_str() {
            "c.nop" => Some(0x0001),
            "c.ret" => Some(0x8082),
            "c.addi" => encode_riscv_c_addi(inst),
            "c.li" => encode_riscv_c_li(inst),
            "c.lui" => encode_riscv_c_lui(inst),
            "c.lw" => encode_riscv_c_lw(inst),
            "c.sw" => encode_riscv_c_sw(inst),
            "c.j" => encode_riscv_c_jump(inst, 0b101),
            "c.jal" => encode_riscv_c_jump(inst, 0b001),
            "c.jalr" => encode_riscv_c_jalr(inst),
            _ => None,
        } {
            bytes.extend((half as u16).to_le_bytes());
            continue;
        }
        let word = match inst.mnemonic.as_str() {
            "nop" => Some(0x00000013),
            "ret" => Some(0x00008067),
            "ecall" => Some(0x00000073),
            "ebreak" => Some(0x00100073),
            "fence" => Some(0x0ff0000f),
            "fence.tso" => Some(0x8330000f),
            "fence.i" => Some(0x0000100f),
            "cbo.clean" | "cbo.flush" | "cbo.inval" | "cbo.zero" => encode_riscv_cache_block(inst),
            "pause" => Some(0x0100000f),
            "wrs.nto" => Some(0x00d00073),
            "wrs.sto" => Some(0x01d00073),
            "wfi" => Some(0x10500073),
            "sret" => Some(0x10200073),
            "mret" => Some(0x30200073),
            "sfence.vma" => encode_riscv_sfence_vma(inst),
            "sfence.w.inval" if inst.operands.is_empty() => Some(0x1800_0073),
            "sfence.inval.ir" if inst.operands.is_empty() => Some(0x1810_0073),
            "sinval.vma" => encode_riscv_sinval_vma(inst),
            "hfence.vvma" | "hfence.gvma" | "hinval.vvma" | "hinval.gvma" => {
                encode_riscv_hypervisor_fence(inst)
            }
            "hlv.b" | "hlv.bu" | "hlv.h" | "hlv.hu" | "hlv.w" | "hlvx.hu" | "hsv.b" | "hsv.h"
            | "hsv.w" => encode_riscv_hypervisor_memory(inst, false),
            "lui" => encode_riscv_u_type(inst, 0x37),
            "auipc" => encode_riscv_u_type(inst, 0x17),
            "addi" => encode_riscv_i_type(inst, 0x13, 0),
            "slti" => encode_riscv_i_type(inst, 0x13, 2),
            "sltiu" => encode_riscv_i_type(inst, 0x13, 3),
            "xori" => encode_riscv_i_type(inst, 0x13, 4),
            "ori" => encode_riscv_i_type(inst, 0x13, 6),
            "andi" => encode_riscv_i_type(inst, 0x13, 7),
            "slli" => encode_riscv_shift_imm(inst, 1, 0),
            "srli" => encode_riscv_shift_imm(inst, 5, 0),
            "srai" => encode_riscv_shift_imm(inst, 5, 0x20),
            "jalr" => encode_riscv_i_type(inst, 0x67, 0),
            "lb" => encode_riscv_load(inst, 0x03, 0),
            "lh" => encode_riscv_load(inst, 0x03, 1),
            "lw" => encode_riscv_load(inst, 0x03, 2),
            "lbu" => encode_riscv_load(inst, 0x03, 4),
            "lhu" => encode_riscv_load(inst, 0x03, 5),
            "sb" => encode_riscv_store(inst, 0x23, 0),
            "sh" => encode_riscv_store(inst, 0x23, 1),
            "sw" => encode_riscv_store(inst, 0x23, 2),
            "add" => encode_riscv_r_type(inst, 0x33, 0, 0),
            "sub" => encode_riscv_r_type(inst, 0x33, 0, 0x20),
            "sll" => encode_riscv_r_type(inst, 0x33, 1, 0),
            "slt" => encode_riscv_r_type(inst, 0x33, 2, 0),
            "sltu" => encode_riscv_r_type(inst, 0x33, 3, 0),
            "xor" => encode_riscv_r_type(inst, 0x33, 4, 0),
            "srl" => encode_riscv_r_type(inst, 0x33, 5, 0),
            "sra" => encode_riscv_r_type(inst, 0x33, 5, 0x20),
            "or" => encode_riscv_r_type(inst, 0x33, 6, 0),
            "and" => encode_riscv_r_type(inst, 0x33, 7, 0),
            "andn" => encode_riscv_r_type(inst, 0x33, 7, 0x20),
            "orn" => encode_riscv_r_type(inst, 0x33, 6, 0x20),
            "xnor" => encode_riscv_r_type(inst, 0x33, 4, 0x20),
            "min" => encode_riscv_r_type(inst, 0x33, 4, 0x05),
            "minu" => encode_riscv_r_type(inst, 0x33, 5, 0x05),
            "max" => encode_riscv_r_type(inst, 0x33, 6, 0x05),
            "maxu" => encode_riscv_r_type(inst, 0x33, 7, 0x05),
            "rol" => encode_riscv_r_type(inst, 0x33, 1, 0x30),
            "ror" => encode_riscv_r_type(inst, 0x33, 5, 0x30),
            "bset" => encode_riscv_r_type(inst, 0x33, 1, 0x14),
            "bclr" => encode_riscv_r_type(inst, 0x33, 1, 0x24),
            "binv" => encode_riscv_r_type(inst, 0x33, 1, 0x34),
            "bext" => encode_riscv_r_type(inst, 0x33, 5, 0x24),
            "bseti" | "bclri" | "binvi" | "bexti" => encode_riscv_zbs_immediate(inst, 32),
            "czero.eqz" => encode_riscv_r_type(inst, 0x33, 5, 0x07),
            "czero.nez" => encode_riscv_r_type(inst, 0x33, 7, 0x07),
            "clz" | "ctz" | "cpop" => encode_riscv_zbb_unary(inst, 0x13),
            "sext.b" | "sext.h" | "orc.b" | "rev8" | "zext.h" => {
                encode_riscv_zbb_extended_unary(inst, 32)
            }
            "mul" => encode_riscv_r_type(inst, 0x33, 0, 1),
            "mulh" => encode_riscv_r_type(inst, 0x33, 1, 1),
            "mulhsu" => encode_riscv_r_type(inst, 0x33, 2, 1),
            "mulhu" => encode_riscv_r_type(inst, 0x33, 3, 1),
            "div" => encode_riscv_r_type(inst, 0x33, 4, 1),
            "divu" => encode_riscv_r_type(inst, 0x33, 5, 1),
            "rem" => encode_riscv_r_type(inst, 0x33, 6, 1),
            "remu" => encode_riscv_r_type(inst, 0x33, 7, 1),
            mnemonic if riscv_atomic_spec(mnemonic, false).is_some() => {
                encode_riscv_atomic(inst, false)
            }
            "csrr" => encode_riscv_csr_pseudo(inst, true),
            "csrw" => encode_riscv_csr_pseudo(inst, false),
            "csrrw" => encode_riscv_csr(inst, 1, false),
            "csrrs" => encode_riscv_csr(inst, 2, false),
            "csrrc" => encode_riscv_csr(inst, 3, false),
            "csrrwi" => encode_riscv_csr(inst, 5, true),
            "csrrsi" => encode_riscv_csr(inst, 6, true),
            "csrrci" => encode_riscv_csr(inst, 7, true),
            "call" => {
                let Some((auipc, jalr)) = encode_riscv_call_pair(inst) else {
                    diagnostics.push(MachineDiagnostic::new(
                        "E_MACHINE_ENCODING_001",
                        format!("riscv32 encoding for '{}' is not available", inst.text),
                    ));
                    continue;
                };
                bytes.extend(auipc.to_le_bytes());
                bytes.extend(jalr.to_le_bytes());
                continue;
            }
            "jal" => encode_riscv_jal(inst),
            "beq" | "bne" | "blt" | "bge" | "bltu" | "bgeu" => encode_riscv_branch(inst),
            _ => None,
        };
        if let Some(word) = word {
            bytes.extend(word.to_le_bytes());
        } else {
            diagnostics.push(MachineDiagnostic::new(
                "E_MACHINE_ENCODING_001",
                format!("riscv32 encoding for '{}' is not available", inst.text),
            ));
        }
    }
    bytes
}

fn encode_riscv_sfence_vma(inst: &MachineInstruction) -> Option<u32> {
    if inst.operands.len() > 2 {
        return None;
    }
    let address = match inst.operands.first() {
        Some(operand) => riscv_reg_number(operand)? as u32,
        None => 0,
    };
    let address_space = match inst.operands.get(1) {
        Some(operand) => riscv_reg_number(operand)? as u32,
        None => 0,
    };
    Some(0x12000073 | (address_space << 20) | (address << 15))
}

fn encode_riscv_sinval_vma(inst: &MachineInstruction) -> Option<u32> {
    if inst.operands.len() > 2 {
        return None;
    }
    let address = match inst.operands.first() {
        Some(operand) => riscv_reg_number(operand)? as u32,
        None => 0,
    };
    let address_space = match inst.operands.get(1) {
        Some(operand) => riscv_reg_number(operand)? as u32,
        None => 0,
    };
    Some(0x1600_0073 | (address_space << 20) | (address << 15))
}

fn encode_riscv_hypervisor_fence(inst: &MachineInstruction) -> Option<u32> {
    if inst.operands.len() > 2 {
        return None;
    }
    let rs1 = match inst.operands.first() {
        Some(operand) => riscv_reg_number(operand)? as u32,
        None => 0,
    };
    let rs2 = match inst.operands.get(1) {
        Some(operand) => riscv_reg_number(operand)? as u32,
        None => 0,
    };
    let base = match inst.mnemonic.as_str() {
        "hfence.vvma" => 0x2200_0073,
        "hfence.gvma" => 0x6200_0073,
        "hinval.vvma" => 0x2600_0073,
        "hinval.gvma" => 0x6600_0073,
        _ => return None,
    };
    Some(base | (rs2 << 20) | (rs1 << 15))
}

fn encode_riscv_hypervisor_memory(inst: &MachineInstruction, rv64: bool) -> Option<u32> {
    if inst.operands.len() != 2 {
        return None;
    }
    let register = riscv_reg_number(inst.operands.first()?)? as u32;
    let (displacement, address) = riscv_mem_operand(inst.operands.get(1)?)?;
    if displacement != 0 {
        return None;
    }
    let address = address as u32;
    let load_base = match inst.mnemonic.as_str() {
        "hlv.b" => Some(0x6000_4073),
        "hlv.bu" => Some(0x6010_4073),
        "hlv.h" => Some(0x6400_4073),
        "hlv.hu" => Some(0x6410_4073),
        "hlv.w" => Some(0x6800_4073),
        "hlv.wu" if rv64 => Some(0x6810_4073),
        "hlv.d" if rv64 => Some(0x6c00_4073),
        "hlvx.hu" => Some(0x6430_4073),
        "hlvx.wu" if rv64 => Some(0x6830_4073),
        _ => None,
    };
    if let Some(base) = load_base {
        return Some(base | (address << 15) | (register << 7));
    }
    let store_base = match inst.mnemonic.as_str() {
        "hsv.b" => 0x6200_4073,
        "hsv.h" => 0x6600_4073,
        "hsv.w" => 0x6a00_4073,
        "hsv.d" if rv64 => 0x6e00_4073,
        _ => return None,
    };
    Some(store_base | (register << 20) | (address << 15))
}

fn encode_riscv_cache_block(inst: &MachineInstruction) -> Option<u32> {
    if inst.operands.len() != 1 {
        return None;
    }
    let (displacement, base_register) = riscv_mem_operand(inst.operands.first()?)?;
    if displacement != 0 {
        return None;
    }
    let operation = match inst.mnemonic.as_str() {
        "cbo.inval" => 0x0000_200f,
        "cbo.clean" => 0x0010_200f,
        "cbo.flush" => 0x0020_200f,
        "cbo.zero" => 0x0040_200f,
        _ => return None,
    };
    Some(operation | ((base_register as u32) << 15))
}

fn encode_riscv_u_type(inst: &MachineInstruction, opcode: u32) -> Option<u32> {
    let rd = riscv_reg_number(inst.operands.first()?)? as u32;
    let imm = parse_int(inst.operands.get(1)?)?;
    if !(0..=0xfffff).contains(&imm) {
        return None;
    }
    Some(((imm as u32) << 12) | (rd << 7) | opcode)
}

fn encode_riscv_i_type(inst: &MachineInstruction, opcode: u32, funct3: u32) -> Option<u32> {
    let rd = riscv_reg_number(inst.operands.first()?)? as u32;
    let rs1 = riscv_reg_number(inst.operands.get(1)?)? as u32;
    let imm = parse_int(inst.operands.get(2)?)?;
    if !(-2048..=2047).contains(&imm) {
        return None;
    }
    Some((((imm as i32 as u32) & 0x0fff) << 20) | (rs1 << 15) | (funct3 << 12) | (rd << 7) | opcode)
}

fn encode_riscv_shift_imm(inst: &MachineInstruction, funct3: u32, funct7: u32) -> Option<u32> {
    let rd = riscv_reg_number(inst.operands.first()?)? as u32;
    let rs1 = riscv_reg_number(inst.operands.get(1)?)? as u32;
    let shamt = parse_int(inst.operands.get(2)?)?;
    if !(0..=31).contains(&shamt) {
        return None;
    }
    Some((funct7 << 25) | ((shamt as u32) << 20) | (rs1 << 15) | (funct3 << 12) | (rd << 7) | 0x13)
}

fn encode_riscv_r_type(
    inst: &MachineInstruction,
    opcode: u32,
    funct3: u32,
    funct7: u32,
) -> Option<u32> {
    let rd = riscv_reg_number(inst.operands.first()?)? as u32;
    let rs1 = riscv_reg_number(inst.operands.get(1)?)? as u32;
    let rs2 = riscv_reg_number(inst.operands.get(2)?)? as u32;
    Some((funct7 << 25) | (rs2 << 20) | (rs1 << 15) | (funct3 << 12) | (rd << 7) | opcode)
}

fn encode_riscv_zbb_unary(inst: &MachineInstruction, opcode: u32) -> Option<u32> {
    if inst.operands.len() != 2 {
        return None;
    }
    let rd = riscv_reg_number(inst.operands.first()?)? as u32;
    let rs1 = riscv_reg_number(inst.operands.get(1)?)? as u32;
    let immediate = match inst.mnemonic.as_str() {
        "clz" | "clzw" => 0x600,
        "ctz" | "ctzw" => 0x601,
        "cpop" | "cpopw" => 0x602,
        _ => return None,
    };
    Some((immediate << 20) | (rs1 << 15) | (1 << 12) | (rd << 7) | opcode)
}

fn encode_riscv_zbb_extended_unary(inst: &MachineInstruction, xlen: u32) -> Option<u32> {
    if inst.operands.len() != 2 {
        return None;
    }
    let rd = riscv_reg_number(inst.operands.first()?)? as u32;
    let rs1 = riscv_reg_number(inst.operands.get(1)?)? as u32;
    let (immediate, funct3, opcode) = match inst.mnemonic.as_str() {
        "sext.b" => (0x604, 1, 0x13),
        "sext.h" => (0x605, 1, 0x13),
        "orc.b" => (0x287, 5, 0x13),
        "rev8" if xlen == 32 => (0x698, 5, 0x13),
        "rev8" if xlen == 64 => (0x6b8, 5, 0x13),
        "zext.h" if xlen == 32 => (0x080, 4, 0x33),
        "zext.h" if xlen == 64 => (0x080, 4, 0x3b),
        _ => return None,
    };
    Some((immediate << 20) | (rs1 << 15) | (funct3 << 12) | (rd << 7) | opcode)
}

fn encode_riscv_zbs_immediate(inst: &MachineInstruction, xlen: u32) -> Option<u32> {
    if inst.operands.len() != 3 {
        return None;
    }
    let rd = riscv_reg_number(inst.operands.first()?)? as u32;
    let rs1 = riscv_reg_number(inst.operands.get(1)?)? as u32;
    let shamt = parse_int(inst.operands.get(2)?.trim_start_matches('#'))?;
    if shamt < 0 || shamt >= xlen as i128 {
        return None;
    }
    let (funct6, funct3) = match inst.mnemonic.as_str() {
        "bseti" => (0x0a, 1),
        "bclri" => (0x12, 1),
        "binvi" => (0x1a, 1),
        "bexti" => (0x12, 5),
        _ => return None,
    };
    Some((funct6 << 26) | ((shamt as u32) << 20) | (rs1 << 15) | (funct3 << 12) | (rd << 7) | 0x13)
}

fn riscv_mem_operand(raw: &str) -> Option<(i128, u8)> {
    let trimmed = raw.trim();
    let open = trimmed.find('(')?;
    let close = trimmed.find(')')?;
    let imm = parse_int(trimmed.get(..open)?.trim()).unwrap_or(0);
    let reg = riscv_reg_number(trimmed.get(open + 1..close)?.trim())?;
    Some((imm, reg))
}

fn encode_riscv_load(inst: &MachineInstruction, opcode: u32, funct3: u32) -> Option<u32> {
    let rd = riscv_reg_number(inst.operands.first()?)? as u32;
    let (imm, rs1) = riscv_mem_operand(inst.operands.get(1)?)?;
    if !(-2048..=2047).contains(&imm) {
        return None;
    }
    Some(
        (((imm as i32 as u32) & 0x0fff) << 20)
            | ((rs1 as u32) << 15)
            | (funct3 << 12)
            | (rd << 7)
            | opcode,
    )
}

fn encode_riscv_store(inst: &MachineInstruction, opcode: u32, funct3: u32) -> Option<u32> {
    let rs2 = riscv_reg_number(inst.operands.first()?)? as u32;
    let (imm, rs1) = riscv_mem_operand(inst.operands.get(1)?)?;
    if !(-2048..=2047).contains(&imm) {
        return None;
    }
    let imm = (imm as i32 as u32) & 0x0fff;
    Some(
        ((imm >> 5) << 25)
            | (rs2 << 20)
            | ((rs1 as u32) << 15)
            | (funct3 << 12)
            | ((imm & 0x1f) << 7)
            | opcode,
    )
}

fn encode_riscv_branch(inst: &MachineInstruction) -> Option<u32> {
    let rs1 = riscv_reg_number(inst.operands.first()?)? as u32;
    let rs2 = riscv_reg_number(inst.operands.get(1)?)? as u32;
    let funct3 = match inst.mnemonic.as_str() {
        "beq" => 0,
        "bne" => 1,
        "blt" => 4,
        "bge" => 5,
        "bltu" => 6,
        "bgeu" => 7,
        _ => return None,
    };
    let imm = inst
        .operands
        .get(2)
        .and_then(|op| parse_int(op))
        .unwrap_or(0);
    if imm % 2 != 0 || !(-4096..=4094).contains(&imm) {
        return None;
    }
    let imm = (imm as i32 as u32) & 0x1fff;
    Some(
        ((imm >> 12) << 31)
            | (((imm >> 5) & 0x3f) << 25)
            | (rs2 << 20)
            | (rs1 << 15)
            | (funct3 << 12)
            | (((imm >> 1) & 0x0f) << 8)
            | (((imm >> 11) & 0x01) << 7)
            | 0x63,
    )
}

fn encode_riscv_jal(inst: &MachineInstruction) -> Option<u32> {
    let (rd, imm) = match inst.operands.as_slice() {
        [imm] => (1_u32, parse_int(imm).unwrap_or(0)),
        [rd, imm] => (riscv_reg_number(rd)? as u32, parse_int(imm).unwrap_or(0)),
        _ => return None,
    };
    if imm % 2 != 0 || !(-1_048_576..=1_048_574).contains(&imm) {
        return None;
    }
    let imm = (imm as i32 as u32) & 0x1f_ffff;
    Some(
        ((imm >> 20) << 31)
            | (((imm >> 1) & 0x03ff) << 21)
            | (((imm >> 11) & 0x01) << 20)
            | (((imm >> 12) & 0xff) << 12)
            | (rd << 7)
            | 0x6f,
    )
}

fn encode_riscv_call_pair(inst: &MachineInstruction) -> Option<(u32, u32)> {
    let displacement = parse_int(inst.operands.first()?).unwrap_or(0);
    if !(i32::MIN as i128..=i32::MAX as i128).contains(&displacement) {
        return None;
    }
    let hi20 = (displacement + 0x800) >> 12;
    let lo12 = displacement - (hi20 << 12);
    if !(-2048..=2047).contains(&lo12) {
        return None;
    }
    let auipc = (((hi20 as i64 as u32) & 0x000f_ffff) << 12) | (1 << 7) | 0x17;
    let jalr = (((lo12 as i64 as u32) & 0x0fff) << 20) | (1 << 15) | (1 << 7) | 0x67;
    Some((auipc, jalr))
}

fn encode_riscv_csr_pseudo(inst: &MachineInstruction, read: bool) -> Option<u32> {
    let mut expanded = inst.clone();
    expanded.operands = if read {
        vec![
            inst.operands.first()?.clone(),
            inst.operands.get(1)?.clone(),
            "x0".into(),
        ]
    } else {
        vec![
            "x0".into(),
            inst.operands.first()?.clone(),
            inst.operands.get(1)?.clone(),
        ]
    };
    encode_riscv_csr(&expanded, if read { 2 } else { 1 }, false)
}

fn encode_riscv_csr(inst: &MachineInstruction, funct3: u32, immediate: bool) -> Option<u32> {
    let rd = riscv_reg_number(inst.operands.first()?)? as u32;
    let csr = riscv_csr_number(inst.operands.get(1)?)?;
    if !(0..=0x0fff).contains(&csr) {
        return None;
    }
    let rs1_or_imm = if immediate {
        let zimm = parse_int(inst.operands.get(2)?)?;
        if !(0..=31).contains(&zimm) {
            return None;
        }
        zimm as u32
    } else {
        riscv_reg_number(inst.operands.get(2)?)? as u32
    };
    Some(((csr as u32) << 20) | (rs1_or_imm << 15) | (funct3 << 12) | (rd << 7) | 0x73)
}

fn riscv_csr_number(raw: &str) -> Option<i128> {
    parse_int(raw).or_else(|| {
        Some(match raw.trim().to_ascii_lowercase().as_str() {
            "sstatus" => 0x100,
            "sie" => 0x104,
            "stvec" => 0x105,
            "scounteren" => 0x106,
            "sscratch" => 0x140,
            "sepc" => 0x141,
            "scause" => 0x142,
            "stval" => 0x143,
            "sip" => 0x144,
            "satp" => 0x180,
            "vsstatus" => 0x200,
            "vsie" => 0x204,
            "vstvec" => 0x205,
            "vsscratch" => 0x240,
            "vsepc" => 0x241,
            "vscause" => 0x242,
            "vstval" => 0x243,
            "vsip" => 0x244,
            "vsatp" => 0x280,
            "mstatus" => 0x300,
            "misa" => 0x301,
            "medeleg" => 0x302,
            "mideleg" => 0x303,
            "mie" => 0x304,
            "mtvec" => 0x305,
            "mcounteren" => 0x306,
            "mscratch" => 0x340,
            "mepc" => 0x341,
            "mcause" => 0x342,
            "mtval" => 0x343,
            "mip" => 0x344,
            "hstatus" => 0x600,
            "hedeleg" => 0x602,
            "hideleg" => 0x603,
            "hie" => 0x604,
            "hcounteren" => 0x606,
            "hgeie" => 0x607,
            "htval" => 0x643,
            "hip" => 0x644,
            "hvip" => 0x645,
            "htinst" => 0x64a,
            "hgatp" => 0x680,
            _ => return None,
        })
    })
}

#[derive(Clone, Copy)]
enum RiscvAtomicForm {
    LoadReserved,
    ReadModifyWrite,
}

fn encode_riscv_atomic(inst: &MachineInstruction, allow_doubleword: bool) -> Option<u32> {
    let (form, funct5, funct3, aq, rl) = riscv_atomic_spec(&inst.mnemonic, allow_doubleword)?;
    let rd = riscv_reg_number(inst.operands.first()?)? as u32;
    let order = ((aq as u32) << 26) | ((rl as u32) << 25);
    match form {
        RiscvAtomicForm::LoadReserved => {
            let rs1 = riscv_atomic_base(inst.operands.get(1)?)? as u32;
            Some((funct5 << 27) | order | (rs1 << 15) | (funct3 << 12) | (rd << 7) | 0x2f)
        }
        RiscvAtomicForm::ReadModifyWrite => {
            let rs2 = riscv_reg_number(inst.operands.get(1)?)? as u32;
            let rs1 = riscv_atomic_base(inst.operands.get(2)?)? as u32;
            Some(
                (funct5 << 27)
                    | order
                    | (rs2 << 20)
                    | (rs1 << 15)
                    | (funct3 << 12)
                    | (rd << 7)
                    | 0x2f,
            )
        }
    }
}

fn riscv_atomic_spec(
    mnemonic: &str,
    allow_doubleword: bool,
) -> Option<(RiscvAtomicForm, u32, u32, bool, bool)> {
    let (base, aq, rl) = if let Some(base) = mnemonic.strip_suffix(".aqrl") {
        (base, true, true)
    } else if let Some(base) = mnemonic.strip_suffix(".aq") {
        (base, true, false)
    } else if let Some(base) = mnemonic.strip_suffix(".rl") {
        (base, false, true)
    } else {
        (mnemonic, false, false)
    };
    let (root, width) = base.rsplit_once('.')?;
    let funct3 = match width {
        "w" => 2,
        "d" if allow_doubleword => 3,
        _ => return None,
    };
    let (form, funct5) = match root {
        "lr" => (RiscvAtomicForm::LoadReserved, 0b00010),
        "sc" => (RiscvAtomicForm::ReadModifyWrite, 0b00011),
        "amoswap" => (RiscvAtomicForm::ReadModifyWrite, 0b00001),
        "amoadd" => (RiscvAtomicForm::ReadModifyWrite, 0b00000),
        "amoxor" => (RiscvAtomicForm::ReadModifyWrite, 0b00100),
        "amoand" => (RiscvAtomicForm::ReadModifyWrite, 0b01100),
        "amoor" => (RiscvAtomicForm::ReadModifyWrite, 0b01000),
        "amomin" => (RiscvAtomicForm::ReadModifyWrite, 0b10000),
        "amomax" => (RiscvAtomicForm::ReadModifyWrite, 0b10100),
        "amominu" => (RiscvAtomicForm::ReadModifyWrite, 0b11000),
        "amomaxu" => (RiscvAtomicForm::ReadModifyWrite, 0b11100),
        _ => return None,
    };
    Some((form, funct5, funct3, aq, rl))
}

fn riscv_atomic_base(raw: &str) -> Option<u8> {
    if let Some((_, reg)) = riscv_mem_operand(raw) {
        return Some(reg);
    }
    let inner = raw.trim().strip_prefix('(')?.strip_suffix(')')?;
    riscv_reg_number(inner.trim())
}

fn encode_riscv_c_addi(inst: &MachineInstruction) -> Option<u16> {
    let rd = riscv_reg_number(inst.operands.first()?)? as u16;
    if rd == 0 {
        return None;
    }
    let imm = parse_int(inst.operands.get(1)?)?;
    if !(-32..=31).contains(&imm) {
        return None;
    }
    let imm = (imm as i16 as u16) & 0x3f;
    Some(((imm & 0x20) << 7) | (rd << 7) | ((imm & 0x1f) << 2) | 0b01)
}

fn encode_riscv_c_li(inst: &MachineInstruction) -> Option<u16> {
    let rd = riscv_reg_number(inst.operands.first()?)? as u16;
    if rd == 0 {
        return None;
    }
    let imm = parse_int(inst.operands.get(1)?)?;
    if !(-32..=31).contains(&imm) {
        return None;
    }
    let imm = (imm as i16 as u16) & 0x3f;
    Some((0b010 << 13) | ((imm & 0x20) << 7) | (rd << 7) | ((imm & 0x1f) << 2) | 0b01)
}

fn encode_riscv_c_lui(inst: &MachineInstruction) -> Option<u16> {
    let rd = riscv_reg_number(inst.operands.first()?)? as u16;
    if rd == 0 || rd == 2 {
        return None;
    }
    let imm = parse_int(inst.operands.get(1)?)?;
    if !(-32..=31).contains(&imm) || imm == 0 {
        return None;
    }
    let imm = (imm as i16 as u16) & 0x3f;
    Some((0b011 << 13) | ((imm & 0x20) << 7) | (rd << 7) | ((imm & 0x1f) << 2) | 0b01)
}

fn encode_riscv_c_lw(inst: &MachineInstruction) -> Option<u16> {
    let rd = riscv_compressed_reg(inst.operands.first()?)? as u16;
    let (imm, rs1) = riscv_mem_operand(inst.operands.get(1)?)?;
    let rs1 = riscv_compressed_reg_number(rs1)? as u16;
    if !(0..=124).contains(&imm) || imm % 4 != 0 {
        return None;
    }
    let imm = imm as u16;
    Some(
        (0b010 << 13)
            | (((imm >> 3) & 0x7) << 10)
            | (rs1 << 7)
            | (((imm >> 2) & 0x1) << 6)
            | (((imm >> 6) & 0x1) << 5)
            | (rd << 2),
    )
}

fn encode_riscv_c_sw(inst: &MachineInstruction) -> Option<u16> {
    let rs2 = riscv_compressed_reg(inst.operands.first()?)? as u16;
    let (imm, rs1) = riscv_mem_operand(inst.operands.get(1)?)?;
    let rs1 = riscv_compressed_reg_number(rs1)? as u16;
    if !(0..=124).contains(&imm) || imm % 4 != 0 {
        return None;
    }
    let imm = imm as u16;
    Some(
        (0b110 << 13)
            | (((imm >> 3) & 0x7) << 10)
            | (rs1 << 7)
            | (((imm >> 2) & 0x1) << 6)
            | (((imm >> 6) & 0x1) << 5)
            | (rs2 << 2),
    )
}

fn encode_riscv_c_jump(inst: &MachineInstruction, funct3: u16) -> Option<u16> {
    let imm = parse_int(inst.operands.first()?)?;
    if imm % 2 != 0 || !(-2048..=2046).contains(&imm) {
        return None;
    }
    let imm = (imm as i16 as u16) & 0x0fff;
    Some(
        (funct3 << 13)
            | (((imm >> 11) & 0x1) << 12)
            | (((imm >> 4) & 0x1) << 11)
            | (((imm >> 8) & 0x3) << 9)
            | (((imm >> 10) & 0x1) << 8)
            | (((imm >> 6) & 0x1) << 7)
            | (((imm >> 7) & 0x1) << 6)
            | (((imm >> 1) & 0x7) << 3)
            | (((imm >> 5) & 0x1) << 2)
            | 0b01,
    )
}

fn encode_riscv_c_jalr(inst: &MachineInstruction) -> Option<u16> {
    let rs1 = riscv_reg_number(inst.operands.first()?)? as u16;
    if rs1 == 0 {
        return None;
    }
    Some((0b100 << 13) | (1 << 12) | (rs1 << 7) | 0b10)
}

fn riscv_compressed_reg(raw: &str) -> Option<u8> {
    riscv_compressed_reg_number(riscv_reg_number(raw)?)
}

fn riscv_compressed_reg_number(reg: u8) -> Option<u8> {
    (8..=15).contains(&reg).then_some(reg - 8)
}

fn encode_wasm32_module(instructions: &[MachineInstruction]) -> Vec<u8> {
    let mut body = Vec::new();
    body.push(0x00); // local decl count
    for inst in instructions {
        match inst.mnemonic.as_str() {
            "i32.const" => {
                body.push(0x41);
                push_leb_i32(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_i32(op))
                        .unwrap_or(0),
                );
            }
            "i64.const" => {
                body.push(0x42);
                push_leb_i64(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_int(op))
                        .and_then(|value| i64::try_from(value).ok())
                        .unwrap_or(0),
                );
            }
            "local.get" => {
                body.push(0x20);
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
            }
            "local.set" => {
                body.push(0x21);
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
            }
            "local.tee" => {
                body.push(0x22);
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
            }
            "table.get" | "table.set" => {
                body.push(if inst.mnemonic == "table.get" {
                    0x25
                } else {
                    0x26
                });
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
            }
            "ref.null" => {
                body.push(0xd0);
                body.push(match inst.operands.first().map(String::as_str) {
                    Some("extern") | Some("externref") => 0x6f,
                    _ => 0x70,
                });
            }
            "ref.is_null" => body.push(0xd1),
            "ref.func" => {
                body.push(0xd2);
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
            }
            mnemonic if wasm_unary_numeric_opcode(mnemonic).is_some() => {
                body.push(wasm_unary_numeric_opcode(mnemonic).unwrap());
            }
            mnemonic if wasm_binary_numeric_opcode(mnemonic).is_some() => {
                body.push(wasm_binary_numeric_opcode(mnemonic).unwrap());
            }
            "block" => body.extend([0x02, 0x40]),
            "loop" => body.extend([0x03, 0x40]),
            "br" => {
                body.push(0x0c);
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
            }
            "br_if" => {
                body.push(0x0d);
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
            }
            "call" => {
                body.push(0x10);
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
            }
            mnemonic if wasm_memory_load_opcode(mnemonic).is_some() => {
                let (opcode, align) = wasm_memory_load_opcode(mnemonic).unwrap();
                body.extend([opcode, align, 0x00]);
            }
            mnemonic if wasm_memory_store_opcode(mnemonic).is_some() => {
                let (opcode, align) = wasm_memory_store_opcode(mnemonic).unwrap();
                body.extend([opcode, align, 0x00]);
            }
            "drop" => body.push(0x1a),
            "select" => body.push(0x1b),
            "memory.size" => body.extend([0x3f, 0x00]),
            "memory.grow" => body.extend([0x40, 0x00]),
            "memory.copy" => body.extend([0xfc, 0x0a, 0x00, 0x00]),
            "memory.fill" => body.extend([0xfc, 0x0b, 0x00]),
            "memory.init" => {
                body.extend([0xfc, 0x08]);
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .get(1)
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
            }
            "data.drop" => {
                body.extend([0xfc, 0x09]);
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
            }
            "table.grow" | "table.size" | "table.fill" => {
                body.extend([
                    0xfc,
                    match inst.mnemonic.as_str() {
                        "table.grow" => 0x0f,
                        "table.size" => 0x10,
                        _ => 0x11,
                    },
                ]);
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
            }
            "table.copy" => {
                body.extend([0xfc, 0x0e]);
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .get(1)
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
            }
            "table.init" => {
                body.extend([0xfc, 0x0c]);
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .get(1)
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
            }
            "elem.drop" => {
                body.extend([0xfc, 0x0d]);
                push_leb_u32(
                    &mut body,
                    inst.operands
                        .first()
                        .and_then(|op| parse_int(op))
                        .unwrap_or(0) as u32,
                );
            }
            "return" => body.push(0x0f),
            "end" | "label" => {}
            _ => {}
        }
    }
    if !body.contains(&0x0f) {
        body.push(0x0f);
    }
    body.push(0x0b);

    let mut out = b"\0asm".to_vec();
    out.extend([0x01, 0x00, 0x00, 0x00]);
    push_wasm_section(&mut out, 1, &[0x01, 0x60, 0x00, 0x01, 0x7f]);
    push_wasm_section(&mut out, 3, &[0x01, 0x00]);
    if instructions.iter().any(|instruction| {
        matches!(
            instruction.mnemonic.as_str(),
            "table.get"
                | "table.set"
                | "table.grow"
                | "table.size"
                | "table.fill"
                | "table.copy"
                | "table.init"
                | "elem.drop"
                | "ref.null"
                | "ref.is_null"
                | "ref.func"
        )
    }) {
        push_wasm_section(&mut out, 4, &[0x01, 0x70, 0x00, 0x01]);
    }
    if instructions.iter().any(|instruction| {
        wasm_memory_load_opcode(&instruction.mnemonic).is_some()
            || wasm_memory_store_opcode(&instruction.mnemonic).is_some()
            || matches!(
                instruction.mnemonic.as_str(),
                "memory.size"
                    | "memory.grow"
                    | "memory.copy"
                    | "memory.fill"
                    | "memory.init"
                    | "data.drop"
            )
    }) {
        push_wasm_section(&mut out, 5, &[0x01, 0x00, 0x01]);
    }
    push_wasm_section(
        &mut out,
        7,
        &[0x01, 0x04, b'm', b'a', b'i', b'n', 0x00, 0x00],
    );
    let uses_passive_elements = instructions
        .iter()
        .any(|instruction| matches!(instruction.mnemonic.as_str(), "table.init" | "elem.drop"));
    let uses_passive_data = instructions
        .iter()
        .any(|instruction| matches!(instruction.mnemonic.as_str(), "memory.init" | "data.drop"));
    if uses_passive_elements {
        push_wasm_section(&mut out, 9, &[0x01, 0x01, 0x00, 0x00]);
    }
    if uses_passive_data {
        push_wasm_section(&mut out, 12, &[0x01]);
    }
    let mut code = Vec::new();
    push_leb_u32(&mut code, 1);
    push_leb_u32(&mut code, body.len() as u32);
    code.extend(body);
    push_wasm_section(&mut out, 10, &code);
    if uses_passive_data {
        push_wasm_section(&mut out, 11, &[0x01, 0x01, 0x00]);
    }
    out
}

fn wasm_unary_numeric_opcode(mnemonic: &str) -> Option<u8> {
    Some(match mnemonic {
        "i32.extend8_s" => 0xc0,
        "i32.extend16_s" => 0xc1,
        "i64.extend8_s" => 0xc2,
        "i64.extend16_s" => 0xc3,
        "i64.extend32_s" => 0xc4,
        "i32.eqz" => 0x45,
        "i64.eqz" => 0x50,
        "i32.clz" => 0x67,
        "i32.ctz" => 0x68,
        "i32.popcnt" => 0x69,
        "i64.clz" => 0x79,
        "i64.ctz" => 0x7a,
        "i64.popcnt" => 0x7b,
        _ => return None,
    })
}

fn wasm_binary_numeric_opcode(mnemonic: &str) -> Option<u8> {
    Some(match mnemonic {
        "i32.eq" => 0x46,
        "i32.ne" => 0x47,
        "i32.lt_s" => 0x48,
        "i32.lt_u" => 0x49,
        "i32.gt_s" => 0x4a,
        "i32.gt_u" => 0x4b,
        "i32.le_s" => 0x4c,
        "i32.le_u" => 0x4d,
        "i32.ge_s" => 0x4e,
        "i32.ge_u" => 0x4f,
        "i64.eq" => 0x51,
        "i64.ne" => 0x52,
        "i64.lt_s" => 0x53,
        "i64.lt_u" => 0x54,
        "i64.gt_s" => 0x55,
        "i64.gt_u" => 0x56,
        "i64.le_s" => 0x57,
        "i64.le_u" => 0x58,
        "i64.ge_s" => 0x59,
        "i64.ge_u" => 0x5a,
        "i32.add" => 0x6a,
        "i32.sub" => 0x6b,
        "i32.mul" => 0x6c,
        "i32.div_s" => 0x6d,
        "i32.div_u" => 0x6e,
        "i32.rem_s" => 0x6f,
        "i32.rem_u" => 0x70,
        "i32.and" => 0x71,
        "i32.or" => 0x72,
        "i32.xor" => 0x73,
        "i32.shl" => 0x74,
        "i32.shr_s" => 0x75,
        "i32.shr_u" => 0x76,
        "i32.rotl" => 0x77,
        "i32.rotr" => 0x78,
        "i64.add" => 0x7c,
        "i64.sub" => 0x7d,
        "i64.mul" => 0x7e,
        "i64.div_s" => 0x7f,
        "i64.div_u" => 0x80,
        "i64.rem_s" => 0x81,
        "i64.rem_u" => 0x82,
        "i64.and" => 0x83,
        "i64.or" => 0x84,
        "i64.xor" => 0x85,
        "i64.shl" => 0x86,
        "i64.shr_s" => 0x87,
        "i64.shr_u" => 0x88,
        "i64.rotl" => 0x89,
        "i64.rotr" => 0x8a,
        _ => return None,
    })
}

fn wasm_memory_load_opcode(mnemonic: &str) -> Option<(u8, u8)> {
    Some(match mnemonic {
        "i32.load" => (0x28, 2),
        "i64.load" => (0x29, 3),
        "i32.load8_s" => (0x2c, 0),
        "i32.load8_u" => (0x2d, 0),
        "i32.load16_s" => (0x2e, 1),
        "i32.load16_u" => (0x2f, 1),
        "i64.load8_s" => (0x30, 0),
        "i64.load8_u" => (0x31, 0),
        "i64.load16_s" => (0x32, 1),
        "i64.load16_u" => (0x33, 1),
        "i64.load32_s" => (0x34, 2),
        "i64.load32_u" => (0x35, 2),
        _ => return None,
    })
}

fn wasm_memory_store_opcode(mnemonic: &str) -> Option<(u8, u8)> {
    Some(match mnemonic {
        "i32.store" => (0x36, 2),
        "i64.store" => (0x37, 3),
        "i32.store8" => (0x3a, 0),
        "i32.store16" => (0x3b, 1),
        "i64.store8" => (0x3c, 0),
        "i64.store16" => (0x3d, 1),
        "i64.store32" => (0x3e, 2),
        _ => return None,
    })
}

fn emit_object_bytes(audit: &MachineAudit, format: &str) -> Result<Vec<u8>, Box<dyn Error>> {
    let arch = audit_arch(audit);
    if arch == "wasm32" || format == "wasm" {
        let mut bytes = audit.encoded_bytes.clone();
        if audit_has_debug_unwind(audit) {
            append_wasm_debug_sections(&mut bytes, audit);
        }
        if !audit.data_bytes.is_empty() {
            let mut payload = Vec::new();
            push_wasm_name(&mut payload, "nC.data");
            payload.extend_from_slice(&audit.data_bytes);
            push_wasm_section(&mut bytes, 0, &payload);
        }
        return Ok(bytes);
    }
    if arch == "riscv64" {
        let entry = audit.entry.as_deref().unwrap_or("main");
        return Ok(emit_minimal_elf64_relocatable_with_relocs(
            audit, entry, 243, 4, 0x04,
        ));
    }
    if arch == "riscv32" {
        let entry = audit.entry.as_deref().unwrap_or("main");
        return Ok(emit_minimal_elf32_relocatable(audit, entry, 243, 4, 0x01));
    }
    if arch == "i386" && format == "coff" {
        return emit_minimal_coff_i386_relocatable(audit);
    }
    if arch == "i386" {
        let entry = audit.entry.as_deref().unwrap_or("main");
        return Ok(emit_minimal_elf32_relocatable(audit, entry, 3, 16, 0));
    }
    if matches!(arch, "armv7" | "armv7em" | "thumb" | "thumb2") {
        let entry = audit.entry.as_deref().unwrap_or("reset");
        let relocations = audit
            .relocation_records
            .iter()
            .filter_map(|record| {
                let normalized = record.kind.trim().to_ascii_uppercase().replace('-', "_");
                let kind = match normalized.as_str() {
                    "R_ARM_ABS32" | "ARM_ABS32" | "ABS32" => ArmRelocationKind::Abs32,
                    "R_ARM_REL32" | "ARM_REL32" | "REL32" => ArmRelocationKind::Rel32,
                    "R_ARM_THM_CALL" | "ARM_THM_CALL" | "THM_CALL" => ArmRelocationKind::ThmCall,
                    "R_ARM_THM_JUMP24" | "ARM_THM_JUMP24" | "THM_JUMP24" => {
                        ArmRelocationKind::ThmJump24
                    }
                    "R_ARM_MOVW_ABS_NC" | "ARM_MOVW_ABS_NC" | "MOVW_ABS_NC" => {
                        ArmRelocationKind::MovwAbsNc
                    }
                    "R_ARM_MOVT_ABS" | "ARM_MOVT_ABS" | "MOVT_ABS" => ArmRelocationKind::MovtAbs,
                    "R_ARM_PREL31" | "ARM_PREL31" | "PREL31" => ArmRelocationKind::Prel31,
                    _ => return None,
                };
                Some(ArmRelocation {
                    offset: record.offset.unwrap_or(0) as usize,
                    kind,
                    symbol: record.symbol.clone().unwrap_or_default(),
                    addend: record.addend as i64,
                })
            })
            .collect::<Vec<_>>();
        return Ok(ncc_machine::emit_arm_elf32_object(
            entry,
            &audit.encoded_bytes,
            &relocations,
        )?);
    }
    let mut profile = match format {
        _ if arch == "aarch64" => ncc_ir::BackendLoweringProfileIR::nc_aapcs64(),
        "coff" => ncc_ir::BackendLoweringProfileIR::nc_win64(),
        "macho" => ncc_ir::BackendLoweringProfileIR::nc_sysv64(),
        _ => ncc_ir::BackendLoweringProfileIR::nc_sysv64(),
    };
    profile.target_spec.object_format = match format {
        "coff" => ncc_ir::BackendObjectFormatIR::Coff,
        "macho" => ncc_ir::BackendObjectFormatIR::MachO,
        _ => ncc_ir::BackendObjectFormatIR::Elf64,
    };
    let section = ncc_ir::BackendObjectSectionIR {
        name: ".text".to_string(),
        kind: ncc_ir::BackendObjectSectionKindIR::Text,
        unit: audit.entry.clone().unwrap_or_else(|| {
            audit
                .container
                .clone()
                .unwrap_or_else(|| "machine".to_string())
        }),
        lines: audit
            .instructions
            .iter()
            .map(|inst| inst.text.clone())
            .collect(),
        bytes: Some(audit.encoded_bytes.clone()),
        size_bytes: audit.encoded_bytes.len(),
        align_bytes: 16,
        comdat: None,
    };
    let mut sections = vec![section];
    if audit_has_debug_unwind(audit) {
        sections.extend(debug_unwind_object_sections(audit, format));
    }
    if !audit.data_bytes.is_empty() {
        sections.push(object_data_section(".data", audit.data_bytes.clone()));
    }
    if audit.bss_size > 0 {
        sections.push(object_data_section(".bss", vec![0; audit.bss_size]));
    }
    let entry = audit.entry.clone().unwrap_or_else(|| {
        audit
            .container
            .clone()
            .unwrap_or_else(|| "main".to_string())
    });
    let mut symbols = vec![ncc_ir::BackendObjectSymbolIR {
        name: entry.clone(),
        section: ".text".to_string(),
        offset: 0,
        visibility: ncc_ir::BackendSymbolVisibilityIR::Global,
    }];
    for (name, (section_name, offset)) in phase12_data_symbol_offsets(audit) {
        if !symbols.iter().any(|symbol| symbol.name == name) {
            symbols.push(ncc_ir::BackendObjectSymbolIR {
                name,
                section: section_name,
                offset,
                visibility: ncc_ir::BackendSymbolVisibilityIR::Global,
            });
        }
    }
    let object = ncc_ir::BackendObjectIR {
        target: profile.target,
        target_spec: profile.target_spec,
        sections,
        symbols,
        relocations: relocation_ir(audit),
    };
    let bytes = match format {
        "coff" => ncc_ir::emit_object_coff(&object)?,
        "macho" => ncc_ir::emit_object_macho64(&object)?,
        _ => ncc_ir::emit_object_elf64(&object)?,
    };
    Ok(bytes)
}

fn emit_minimal_coff_i386_relocatable(audit: &MachineAudit) -> Result<Vec<u8>, Box<dyn Error>> {
    #[derive(Clone)]
    struct Section {
        name: &'static str,
        bytes: Vec<u8>,
        virtual_size: usize,
        characteristics: u32,
        relocations: Vec<(u32, String, u16)>,
    }

    let mut sections = vec![Section {
        name: ".text",
        bytes: audit.encoded_bytes.clone(),
        virtual_size: audit.encoded_bytes.len(),
        characteristics: 0x6050_0020,
        relocations: Vec::new(),
    }];
    if !audit.data_bytes.is_empty() {
        sections.push(Section {
            name: ".data",
            bytes: audit.data_bytes.clone(),
            virtual_size: audit.data_bytes.len(),
            characteristics: 0xc050_0040,
            relocations: Vec::new(),
        });
    }
    if audit.bss_size > 0 {
        sections.push(Section {
            name: ".bss",
            bytes: Vec::new(),
            virtual_size: audit.bss_size,
            characteristics: 0xc050_0080,
            relocations: Vec::new(),
        });
    }

    for relocation in relocation_ir(audit) {
        let relocation_type = match relocation.kind {
            ncc_ir::BackendObjectRelocationKindIR::CallNear32
            | ncc_ir::BackendObjectRelocationKindIR::JumpNear32
            | ncc_ir::BackendObjectRelocationKindIR::PcRel32 => 0x0014,
            ncc_ir::BackendObjectRelocationKindIR::Abs32 => 0x0006,
            ncc_ir::BackendObjectRelocationKindIR::Abs64 => return Err(
                "[E_MACHINE_COFF_I386_RELOCATION_001] i386 COFF cannot encode an abs64 relocation"
                    .into(),
            ),
        };
        let section = sections
            .iter_mut()
            .find(|section| section.name == relocation.section)
            .ok_or_else(|| {
                format!(
                    "[E_MACHINE_COFF_I386_SECTION_001] relocation references missing section '{}'",
                    relocation.section
                )
            })?;
        section.relocations.push((
            u32::try_from(relocation.offset)
                .map_err(|_| "[E_MACHINE_COFF_I386_RANGE_001] relocation offset exceeds u32")?,
            relocation.symbol,
            relocation_type,
        ));
    }

    #[derive(Clone)]
    struct Symbol {
        name: String,
        value: u32,
        section: i16,
        symbol_type: u16,
    }
    let mut symbols = vec![Symbol {
        name: audit.entry.clone().unwrap_or_else(|| "main".to_string()),
        value: 0,
        section: 1,
        symbol_type: 0x20,
    }];
    for (name, (section_name, offset)) in phase12_data_symbol_offsets(audit) {
        let Some(index) = sections
            .iter()
            .position(|section| section.name == section_name)
        else {
            continue;
        };
        if !symbols.iter().any(|symbol| symbol.name == name) {
            symbols.push(Symbol {
                name,
                value: u32::try_from(offset)
                    .map_err(|_| "[E_MACHINE_COFF_I386_RANGE_001] symbol offset exceeds u32")?,
                section: (index + 1) as i16,
                symbol_type: 0,
            });
        }
    }
    let mut unresolved = BTreeSet::new();
    for section in &sections {
        for (_, name, _) in &section.relocations {
            if !symbols.iter().any(|symbol| symbol.name == *name) {
                unresolved.insert(name.clone());
            }
        }
    }
    symbols.extend(unresolved.into_iter().map(|name| Symbol {
        name,
        value: 0,
        section: 0,
        symbol_type: 0,
    }));
    let symbol_indices = symbols
        .iter()
        .enumerate()
        .map(|(index, symbol)| (symbol.name.clone(), index as u32))
        .collect::<BTreeMap<_, _>>();

    let header_size = 20 + sections.len() * 40;
    let mut cursor = header_size;
    let mut raw_offsets = Vec::with_capacity(sections.len());
    for section in &sections {
        if section.bytes.is_empty() {
            raw_offsets.push(0_u32);
        } else {
            raw_offsets.push(cursor as u32);
            cursor += section.bytes.len();
        }
    }
    let mut relocation_offsets = Vec::with_capacity(sections.len());
    for section in &sections {
        if section.relocations.is_empty() {
            relocation_offsets.push(0_u32);
        } else {
            relocation_offsets.push(cursor as u32);
            cursor += section.relocations.len() * 10;
        }
    }
    let symbol_table_offset = cursor as u32;

    let mut string_tail = Vec::new();
    let mut string_offsets = BTreeMap::<String, u32>::new();
    let mut symbol_name_fields = Vec::with_capacity(symbols.len());
    for symbol in &symbols {
        let mut field = [0_u8; 8];
        if symbol.name.len() <= 8 {
            field[..symbol.name.len()].copy_from_slice(symbol.name.as_bytes());
        } else {
            let offset = *string_offsets
                .entry(symbol.name.clone())
                .or_insert_with(|| {
                    let offset = (4 + string_tail.len()) as u32;
                    string_tail.extend_from_slice(symbol.name.as_bytes());
                    string_tail.push(0);
                    offset
                });
            field[4..8].copy_from_slice(&offset.to_le_bytes());
        }
        symbol_name_fields.push(field);
    }

    let mut out = Vec::new();
    out.extend_from_slice(&0x014c_u16.to_le_bytes());
    out.extend_from_slice(&(sections.len() as u16).to_le_bytes());
    out.extend_from_slice(&0_u32.to_le_bytes());
    out.extend_from_slice(&symbol_table_offset.to_le_bytes());
    out.extend_from_slice(&(symbols.len() as u32).to_le_bytes());
    out.extend_from_slice(&0_u16.to_le_bytes());
    out.extend_from_slice(&0_u16.to_le_bytes());
    for (index, section) in sections.iter().enumerate() {
        let mut name = [0_u8; 8];
        name[..section.name.len()].copy_from_slice(section.name.as_bytes());
        out.extend_from_slice(&name);
        out.extend_from_slice(&(section.virtual_size as u32).to_le_bytes());
        out.extend_from_slice(&0_u32.to_le_bytes());
        out.extend_from_slice(&(section.bytes.len() as u32).to_le_bytes());
        out.extend_from_slice(&raw_offsets[index].to_le_bytes());
        out.extend_from_slice(&relocation_offsets[index].to_le_bytes());
        out.extend_from_slice(&0_u32.to_le_bytes());
        out.extend_from_slice(&(section.relocations.len() as u16).to_le_bytes());
        out.extend_from_slice(&0_u16.to_le_bytes());
        out.extend_from_slice(&section.characteristics.to_le_bytes());
    }
    for section in &sections {
        out.extend_from_slice(&section.bytes);
    }
    for section in &sections {
        for (offset, symbol, relocation_type) in &section.relocations {
            out.extend_from_slice(&offset.to_le_bytes());
            let symbol_index = symbol_indices.get(symbol).copied().ok_or_else(|| {
                format!(
                    "[E_MACHINE_COFF_I386_SYMBOL_001] relocation symbol '{}' was not cataloged",
                    symbol
                )
            })?;
            out.extend_from_slice(&symbol_index.to_le_bytes());
            out.extend_from_slice(&relocation_type.to_le_bytes());
        }
    }
    for (symbol, name) in symbols.iter().zip(symbol_name_fields.iter()) {
        out.extend_from_slice(name);
        out.extend_from_slice(&symbol.value.to_le_bytes());
        out.extend_from_slice(&symbol.section.to_le_bytes());
        out.extend_from_slice(&symbol.symbol_type.to_le_bytes());
        out.push(2);
        out.push(0);
    }
    out.extend_from_slice(&(4_u32 + string_tail.len() as u32).to_le_bytes());
    out.extend_from_slice(&string_tail);
    Ok(out)
}

fn audit_has_debug_unwind(audit: &MachineAudit) -> bool {
    audit.sections.contains("debug") || audit.sections.contains("cfi") || !audit.debug.is_empty()
}

fn debug_unwind_object_sections(
    audit: &MachineAudit,
    format: &str,
) -> Vec<ncc_ir::BackendObjectSectionIR> {
    let text_len = audit.encoded_bytes.len().max(1);
    match format {
        "coff" => vec![
            object_data_section(".pdata", coff_pdata_bytes(text_len)),
            object_data_section(".xdata", coff_xdata_bytes(audit)),
        ],
        "macho" => vec![
            object_data_section("__compact_unwind", macho_compact_unwind_bytes(text_len)),
            object_data_section("__debug_line", dwarf_debug_line_bytes(audit, text_len)),
            object_data_section("__debug_info", dwarf_debug_info_bytes(audit, text_len)),
            object_data_section("__debug_abbrev", dwarf_debug_abbrev_bytes()),
            object_data_section("__debug_str", dwarf_debug_str_bytes(audit)),
        ],
        _ => vec![
            object_data_section(".debug_line", dwarf_debug_line_bytes(audit, text_len)),
            object_data_section(".debug_info", dwarf_debug_info_bytes(audit, text_len)),
            object_data_section(".debug_abbrev", dwarf_debug_abbrev_bytes()),
            object_data_section(".debug_str", dwarf_debug_str_bytes(audit)),
            object_data_section(".eh_frame", eh_frame_bytes(audit, text_len)),
        ],
    }
}

fn object_data_section(name: &str, bytes: Vec<u8>) -> ncc_ir::BackendObjectSectionIR {
    ncc_ir::BackendObjectSectionIR {
        name: name.to_string(),
        kind: ncc_ir::BackendObjectSectionKindIR::TypeMeta,
        unit: "machine_debug_unwind".to_string(),
        lines: Vec::new(),
        size_bytes: bytes.len(),
        bytes: Some(bytes),
        align_bytes: 1,
        comdat: None,
    }
}

fn dwarf_debug_str_bytes(audit: &MachineAudit) -> Vec<u8> {
    let entry = audit.entry.as_deref().unwrap_or("main");
    let source = audit
        .debug
        .get("file")
        .map(String::as_str)
        .unwrap_or(audit.path.as_str());
    let mut out = Vec::new();
    for value in ["ncc", "nC.machine", source, entry] {
        out.extend_from_slice(value.as_bytes());
        out.push(0);
    }
    out
}

fn dwarf_debug_abbrev_bytes() -> Vec<u8> {
    let mut out = Vec::new();
    push_leb_u32(&mut out, 1);
    push_leb_u32(&mut out, 0x11);
    out.push(1);
    for (name, form) in [
        (0x25, 0x0e),
        (0x13, 0x05),
        (0x03, 0x0e),
        (0x10, 0x17),
        (0x11, 0x01),
        (0x12, 0x07),
    ] {
        push_leb_u32(&mut out, name);
        push_leb_u32(&mut out, form);
    }
    out.extend([0, 0]);
    push_leb_u32(&mut out, 2);
    push_leb_u32(&mut out, 0x2e);
    out.push(0);
    for (name, form) in [(0x03, 0x0e), (0x11, 0x01), (0x12, 0x07), (0x3f, 0x19)] {
        push_leb_u32(&mut out, name);
        push_leb_u32(&mut out, form);
    }
    out.extend([0, 0, 0]);
    out
}

fn dwarf_debug_info_bytes(audit: &MachineAudit, text_len: usize) -> Vec<u8> {
    let mut body = Vec::new();
    body.extend_from_slice(&4_u16.to_le_bytes());
    body.extend_from_slice(&0_u32.to_le_bytes());
    body.push(8);
    push_leb_u32(&mut body, 1);
    body.extend_from_slice(&0_u32.to_le_bytes());
    body.extend_from_slice(&0x001d_u16.to_le_bytes());
    body.extend_from_slice(&4_u32.to_le_bytes());
    body.extend_from_slice(&0_u32.to_le_bytes());
    body.extend_from_slice(&0_u64.to_le_bytes());
    body.extend_from_slice(&(text_len as u64).to_le_bytes());
    push_leb_u32(&mut body, 2);
    body.extend_from_slice(&("ncc\0nC.machine\0".len() as u32).to_le_bytes());
    body.extend_from_slice(&0_u64.to_le_bytes());
    body.extend_from_slice(&(text_len as u64).to_le_bytes());
    body.push(1);
    body.push(0);
    let mut out = Vec::new();
    out.extend_from_slice(&(body.len() as u32).to_le_bytes());
    out.extend(body);
    let _ = audit;
    out
}

fn dwarf_debug_line_bytes(audit: &MachineAudit, text_len: usize) -> Vec<u8> {
    let source = audit
        .debug
        .get("file")
        .map(String::as_str)
        .unwrap_or(audit.path.as_str());
    let file_name = Path::new(source)
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or(source);
    let mut header = vec![1, 1, (-5_i8) as u8, 14, 13];
    header.extend([0, 1, 1, 1, 1, 0, 0, 0, 1, 0, 0, 1]);
    header.push(0);
    header.extend_from_slice(file_name.as_bytes());
    header.push(0);
    header.extend([0, 0, 0, 0]);

    let mut program = Vec::new();
    program.push(0);
    push_leb_u32(&mut program, 9);
    program.push(2);
    program.extend_from_slice(&0_u64.to_le_bytes());
    if text_len > 1 {
        program.push(2);
        push_leb_u32(&mut program, (text_len - 1) as u32);
    }
    program.push(1);
    program.push(0);
    push_leb_u32(&mut program, 1);
    program.push(1);

    let header_len = header.len() as u32;
    let mut body = Vec::new();
    body.extend_from_slice(&4_u16.to_le_bytes());
    body.extend_from_slice(&header_len.to_le_bytes());
    body.extend(header);
    body.extend(program);
    let mut out = Vec::new();
    out.extend_from_slice(&(body.len() as u32).to_le_bytes());
    out.extend(body);
    out
}

fn eh_frame_bytes(audit: &MachineAudit, text_len: usize) -> Vec<u8> {
    let cie = MachineCie {
        version: 1,
        code_alignment_factor: 1,
        data_alignment_factor: -8,
        return_address_register: 16,
    };
    let fde = MachineFde {
        symbol: audit.entry.clone().unwrap_or_else(|| "main".to_string()),
        pc_begin: 0,
        pc_range: text_len as u64,
    };
    let cfa = MachineCfaRule {
        register: "rsp",
        offset: 8,
    };
    let mut out = Vec::new();
    let mut cie_body = Vec::new();
    cie_body.extend_from_slice(&0_u32.to_le_bytes());
    cie_body.push(cie.version);
    cie_body.extend_from_slice(b"zR\0");
    push_leb_u32(&mut cie_body, cie.code_alignment_factor as u32);
    push_sleb_i32(&mut cie_body, cie.data_alignment_factor as i32);
    push_leb_u32(&mut cie_body, cie.return_address_register as u32);
    push_leb_u32(&mut cie_body, 1);
    cie_body.push(0x1b);
    cie_body.push(0x0c);
    push_leb_u32(&mut cie_body, 7);
    push_leb_u32(&mut cie_body, cfa.offset as u32);
    cie_body.push(0x90);
    push_leb_u32(&mut cie_body, 1);
    out.extend_from_slice(&(cie_body.len() as u32).to_le_bytes());
    out.extend(cie_body);
    while out.len() % 4 != 0 {
        out.push(0);
    }
    let fde_start = out.len();
    let mut fde_body = Vec::new();
    fde_body.extend_from_slice(&((fde_start + 4) as u32).to_le_bytes());
    fde_body.extend_from_slice(&(fde.pc_begin as u32).to_le_bytes());
    fde_body.extend_from_slice(&(fde.pc_range as u32).to_le_bytes());
    fde_body.push(0);
    let symbol_len = fde.symbol.len().min(255) as u8;
    fde_body.extend([0x04, symbol_len]);
    out.extend_from_slice(&(fde_body.len() as u32).to_le_bytes());
    out.extend(fde_body);
    while out.len() % 4 != 0 {
        out.push(0);
    }
    let _ = cfa.register;
    out
}

fn coff_pdata_bytes(text_len: usize) -> Vec<u8> {
    let pdata = MachineCoffPdataEntry {
        begin_rva: 0,
        end_rva: text_len as u32,
        unwind_info_rva: 0,
    };
    let mut out = Vec::new();
    out.extend_from_slice(&pdata.begin_rva.to_le_bytes());
    out.extend_from_slice(&pdata.end_rva.to_le_bytes());
    out.extend_from_slice(&pdata.unwind_info_rva.to_le_bytes());
    out
}

fn coff_xdata_bytes(audit: &MachineAudit) -> Vec<u8> {
    let prologue_size = if audit.instructions.iter().any(|inst| {
        inst.mnemonic == "push" && inst.operands.first().map(String::as_str) == Some("rbp")
    }) {
        1
    } else {
        0
    };
    let xdata = MachineCoffXdataEntry {
        version: 1,
        flags: 0,
        prologue_size,
        unwind_code_count: 1,
    };
    vec![
        xdata.version | (xdata.flags << 3),
        xdata.prologue_size,
        xdata.unwind_code_count,
        0x50,
        0x00,
        0x03,
        0x00,
        0x00,
    ]
}

fn macho_compact_unwind_bytes(text_len: usize) -> Vec<u8> {
    let entry = MachineMachOCompactUnwindEntry {
        function_offset: 0,
        function_length: text_len as u32,
        encoding: 0x0200_0000,
    };
    let mut out = Vec::new();
    out.extend_from_slice(&entry.function_offset.to_le_bytes());
    out.extend_from_slice(&entry.function_length.to_le_bytes());
    out.extend_from_slice(&entry.encoding.to_le_bytes());
    out.extend_from_slice(&0_u32.to_le_bytes());
    out.extend_from_slice(&0_u32.to_le_bytes());
    out.extend_from_slice(&0_u32.to_le_bytes());
    out.extend_from_slice(&0_u32.to_le_bytes());
    out.extend_from_slice(&0_u32.to_le_bytes());
    out
}

fn relocation_ir(audit: &MachineAudit) -> Vec<ncc_ir::BackendObjectRelocationIR> {
    let mut relocs = Vec::new();
    let mut offset = 0_usize;
    let arch = audit_arch(audit);
    for inst in &audit.instructions {
        if inst.mnemonic == "call" {
            let (slot_offset, addend) = match arch {
                "aarch64" | "riscv64" | "riscv32" => (offset, 0),
                _ => (offset + 1, -4),
            };
            relocs.push(ncc_ir::BackendObjectRelocationIR {
                section: ".text".to_string(),
                offset: slot_offset,
                kind: ncc_ir::BackendObjectRelocationKindIR::CallNear32,
                symbol: inst
                    .operands
                    .first()
                    .cloned()
                    .unwrap_or_else(|| "external".to_string()),
                addend,
            });
        }
        if inst.mnemonic == "lea" && inst.operands.len() == 2 {
            if let Some(rel) = parse_x86_rel_memory_symbol(&inst.operands[1]) {
                relocs.push(ncc_ir::BackendObjectRelocationIR {
                    section: ".text".to_string(),
                    offset: offset + x86_rel32_displacement_offset(inst).unwrap_or(3),
                    kind: ncc_ir::BackendObjectRelocationKindIR::PcRel32,
                    symbol: rel.symbol,
                    addend: rel.addend as isize - 4,
                });
            } else if let Some(direct) = parse_x86_direct_memory_symbol(&inst.operands[1]) {
                relocs.push(ncc_ir::BackendObjectRelocationIR {
                    section: ".text".to_string(),
                    offset: offset + x86_rel32_displacement_offset(inst).unwrap_or(4),
                    kind: ncc_ir::BackendObjectRelocationKindIR::Abs32,
                    symbol: direct.symbol,
                    addend: direct.addend as isize,
                });
            }
        }
        if inst.mnemonic == "mov" && inst.operands.len() == 2 {
            if let Some(rel) = inst
                .operands
                .iter()
                .find_map(|operand| parse_x86_rel_memory_symbol(operand))
            {
                relocs.push(ncc_ir::BackendObjectRelocationIR {
                    section: ".text".to_string(),
                    offset: offset + x86_rel32_displacement_offset(inst).unwrap_or(3),
                    kind: ncc_ir::BackendObjectRelocationKindIR::PcRel32,
                    symbol: rel.symbol,
                    addend: rel.addend as isize - 4,
                });
            } else if let Some(direct) = inst
                .operands
                .iter()
                .find_map(|operand| parse_x86_direct_memory_symbol(operand))
            {
                relocs.push(ncc_ir::BackendObjectRelocationIR {
                    section: ".text".to_string(),
                    offset: offset + x86_rel32_displacement_offset(inst).unwrap_or(4),
                    kind: ncc_ir::BackendObjectRelocationKindIR::Abs32,
                    symbol: direct.symbol,
                    addend: direct.addend as isize,
                });
            }
        }
        offset += machine_instruction_len_for_arch(arch, inst);
    }
    for (occurrence, record) in audit.relocation_records.iter().enumerate() {
        let Some(canonical) = phase12_explicit_relocation_kind(arch, &record.kind) else {
            continue;
        };
        let kind = match canonical {
            "call-near32" | "aarch64-call26" | "riscv-call" | "riscv-call-plt" => {
                ncc_ir::BackendObjectRelocationKindIR::CallNear32
            }
            "jump-near32" | "aarch64-jump26" | "riscv-jal" => {
                ncc_ir::BackendObjectRelocationKindIR::JumpNear32
            }
            "pc32" => ncc_ir::BackendObjectRelocationKindIR::PcRel32,
            "abs32" => ncc_ir::BackendObjectRelocationKindIR::Abs32,
            "abs64" => ncc_ir::BackendObjectRelocationKindIR::Abs64,
            _ => continue,
        };
        let Some(symbol) = record.symbol.clone() else {
            continue;
        };
        let relocation = ncc_ir::BackendObjectRelocationIR {
            section: if record.section.is_empty() {
                ".text".to_string()
            } else {
                record.section.clone()
            },
            offset: record
                .offset
                .or_else(|| infer_machine_relocation_offset(audit, arch, record, occurrence))
                .unwrap_or(0) as usize,
            kind,
            symbol,
            addend: record.addend as isize,
        };
        if !relocs.iter().any(|existing| {
            existing.section == relocation.section
                && existing.offset == relocation.offset
                && existing.kind == relocation.kind
                && existing.symbol == relocation.symbol
                && existing.addend == relocation.addend
        }) {
            relocs.push(relocation);
        }
    }
    relocs
}

fn machine_instruction_len_for_arch(arch: &str, inst: &MachineInstruction) -> usize {
    match arch {
        "i386" => try_encode_i386_instruction(inst)
            .ok()
            .flatten()
            .map(|bytes| bytes.len())
            .unwrap_or(0),
        "aarch64" => {
            let mut diagnostics = Vec::new();
            let len =
                encode_aarch64_instructions(std::slice::from_ref(inst), &mut diagnostics).len();
            if len == 0 && inst.mnemonic != "label" {
                4
            } else {
                len
            }
        }
        "armv7" | "armv7em" | "thumb" | "thumb2" => {
            let mut diagnostics = Vec::new();
            encode_thumb_instructions(std::slice::from_ref(inst), &mut diagnostics).len()
        }
        "riscv64" => {
            let mut diagnostics = Vec::new();
            let len =
                encode_riscv64_instructions(std::slice::from_ref(inst), &mut diagnostics).len();
            if len == 0 && inst.mnemonic != "label" {
                4
            } else {
                len
            }
        }
        "riscv32" => {
            let mut diagnostics = Vec::new();
            let len =
                encode_riscv32_instructions(std::slice::from_ref(inst), &mut diagnostics).len();
            if len == 0 && inst.mnemonic != "label" {
                4
            } else {
                len
            }
        }
        _ => x86_64_instruction_len(inst),
    }
}

fn x86_rel32_displacement_offset(inst: &MachineInstruction) -> Option<usize> {
    let encoded = try_encode_x86_64_instruction(inst).ok().flatten()?;
    encoded.len().checked_sub(4)
}

fn x86_64_instruction_len(inst: &MachineInstruction) -> usize {
    if let Ok(Some(encoded)) = try_encode_x86_64_instruction(inst) {
        return encoded.len();
    }
    match inst.mnemonic.as_str() {
        "mov" if inst.operands.as_slice() == ["rax", "rdi"] => 3,
        "mov" if inst.operands.as_slice() == ["rbp", "rsp"] => 3,
        "mov" if inst.operands.first().map(String::as_str) == Some("rax") => 10,
        "add" if inst.operands.as_slice() == ["rax", "rbx"] => 3,
        "add" if inst.operands.as_slice() == ["rax", "rsi"] => 3,
        "add" if inst.operands.first().map(String::as_str) == Some("rsp") => 4,
        "sub" if inst.operands.first().map(String::as_str) == Some("rsp") => 4,
        "cmp" if inst.operands.first().map(String::as_str) == Some("rcx") => 4,
        "dec" if inst.operands.first().map(String::as_str) == Some("rcx") => 3,
        "push" | "pop" if inst.operands.first().map(String::as_str) == Some("rbp") => 1,
        "push" | "pop" if inst.operands.first().map(String::as_str) == Some("rbx") => 1,
        "ret" | "nop" | "hlt" | "leave" => 1,
        "jmp" | "call" => 5,
        mnemonic if CONDITIONAL_JUMPS.contains(&mnemonic) => 6,
        "label" => 0,
        _ => 0,
    }
}

fn emit_minimal_elf64_relocatable(
    text: &[u8],
    symbol: &str,
    machine: u16,
    text_align: u64,
    elf_flags: u32,
) -> Vec<u8> {
    const ELF_HEADER_SIZE: usize = 64;
    const SECTION_HEADER_SIZE: usize = 64;
    const SYMTAB_ENTRY_SIZE: usize = 24;

    let text_offset = align_to(ELF_HEADER_SIZE, text_align as usize);
    let symtab_offset = align_to(text_offset + text.len(), 8);
    let strtab = {
        let mut out = Vec::new();
        out.push(0);
        out.extend_from_slice(symbol.as_bytes());
        out.push(0);
        out
    };
    let symtab_size = SYMTAB_ENTRY_SIZE * 2;
    let strtab_offset = symtab_offset + symtab_size;
    let shstrtab = b"\0.text\0.symtab\0.strtab\0.shstrtab\0".to_vec();
    let shstrtab_offset = strtab_offset + strtab.len();
    let shoff = align_to(shstrtab_offset + shstrtab.len(), 8);
    let total = shoff + SECTION_HEADER_SIZE * 5;
    let mut bytes = vec![0_u8; total];

    bytes[0..4].copy_from_slice(b"\x7fELF");
    bytes[4] = 2;
    bytes[5] = 1;
    bytes[6] = 1;
    write_u16(&mut bytes, 16, 1);
    write_u16(&mut bytes, 18, machine);
    write_u32(&mut bytes, 20, 1);
    write_u32(&mut bytes, 48, elf_flags);
    write_u64(&mut bytes, 40, shoff as u64);
    write_u16(&mut bytes, 52, ELF_HEADER_SIZE as u16);
    write_u16(&mut bytes, 58, SECTION_HEADER_SIZE as u16);
    write_u16(&mut bytes, 60, 5);
    write_u16(&mut bytes, 62, 4);

    bytes[text_offset..text_offset + text.len()].copy_from_slice(text);

    let mut symtab = vec![0_u8; symtab_size];
    symtab[SYMTAB_ENTRY_SIZE] = 1;
    symtab[SYMTAB_ENTRY_SIZE + 4] = 0x12;
    write_u16(&mut symtab, SYMTAB_ENTRY_SIZE + 6, 1);
    write_u64(&mut symtab, SYMTAB_ENTRY_SIZE + 8, 0);
    write_u64(&mut symtab, SYMTAB_ENTRY_SIZE + 16, text.len() as u64);
    bytes[symtab_offset..symtab_offset + symtab_size].copy_from_slice(&symtab);
    bytes[strtab_offset..strtab_offset + strtab.len()].copy_from_slice(&strtab);
    bytes[shstrtab_offset..shstrtab_offset + shstrtab.len()].copy_from_slice(&shstrtab);

    write_section_header(
        &mut bytes,
        shoff + SECTION_HEADER_SIZE,
        1,
        1,
        6,
        text_offset,
        text.len(),
        0,
        0,
        text_align,
        0,
    );
    write_section_header(
        &mut bytes,
        shoff + SECTION_HEADER_SIZE * 2,
        7,
        2,
        0,
        symtab_offset,
        symtab_size,
        3,
        1,
        8,
        SYMTAB_ENTRY_SIZE,
    );
    write_section_header(
        &mut bytes,
        shoff + SECTION_HEADER_SIZE * 3,
        15,
        3,
        0,
        strtab_offset,
        strtab.len(),
        0,
        0,
        1,
        0,
    );
    write_section_header(
        &mut bytes,
        shoff + SECTION_HEADER_SIZE * 4,
        23,
        3,
        0,
        shstrtab_offset,
        shstrtab.len(),
        0,
        0,
        1,
        0,
    );
    bytes
}

fn emit_minimal_elf64_relocatable_with_relocs(
    audit: &MachineAudit,
    symbol: &str,
    machine: u16,
    text_align: u64,
    elf_flags: u32,
) -> Vec<u8> {
    if audit.relocation_records.is_empty() {
        return emit_minimal_elf64_relocatable(
            &audit.encoded_bytes,
            symbol,
            machine,
            text_align,
            elf_flags,
        );
    }

    const ELF_HEADER_SIZE: usize = 64;
    const SECTION_HEADER_SIZE: usize = 64;
    const SYMTAB_ENTRY_SIZE: usize = 24;
    const RELA_ENTRY_SIZE: usize = 24;

    let text = &audit.encoded_bytes;
    let arch = audit_arch(audit);
    let relocs = audit
        .relocation_records
        .iter()
        .filter_map(|record| {
            let reloc_type = elf64_relocation_type(arch, &record.kind)?;
            Some((
                record.offset.unwrap_or(0) as u64,
                record.symbol.clone().unwrap_or_else(|| symbol.to_string()),
                reloc_type,
                record.addend as i64,
            ))
        })
        .collect::<Vec<_>>();
    if relocs.is_empty() {
        return emit_minimal_elf64_relocatable(text, symbol, machine, text_align, elf_flags);
    }

    let mut symbol_names = vec![symbol.to_string()];
    for name in audit.symbols.iter().chain(audit.externs.iter()) {
        if !symbol_names.iter().any(|item| item == name) {
            symbol_names.push(name.clone());
        }
    }
    for (_, name, _, _) in &relocs {
        if !symbol_names.iter().any(|item| item == name) {
            symbol_names.push(name.clone());
        }
    }
    let (strtab_offsets, strtab) = elf32_string_table(&symbol_names);
    let mut symbol_index = BTreeMap::<String, u64>::new();
    for (idx, name) in symbol_names.iter().enumerate() {
        symbol_index.insert(name.clone(), (idx + 1) as u64);
    }

    let mut rela_text = Vec::with_capacity(relocs.len() * RELA_ENTRY_SIZE);
    for (offset, name, reloc_type, addend) in &relocs {
        let sym_idx = symbol_index.get(name).copied().unwrap_or(0);
        rela_text.extend(offset.to_le_bytes());
        rela_text.extend(((sym_idx << 32) | (*reloc_type as u64)).to_le_bytes());
        rela_text.extend(addend.to_le_bytes());
    }

    let text_offset = align_to(ELF_HEADER_SIZE, text_align as usize);
    let rela_offset = align_to(text_offset + text.len(), 8);
    let symtab_offset = align_to(rela_offset + rela_text.len(), 8);
    let symtab_size = SYMTAB_ENTRY_SIZE * (symbol_names.len() + 1);
    let strtab_offset = symtab_offset + symtab_size;
    let shstrtab = b"\0.text\0.rela.text\0.symtab\0.strtab\0.shstrtab\0".to_vec();
    let shstrtab_offset = strtab_offset + strtab.len();
    let shoff = align_to(shstrtab_offset + shstrtab.len(), 8);
    let section_count = 6usize;
    let total = shoff + SECTION_HEADER_SIZE * section_count;
    let mut bytes = vec![0_u8; total];

    bytes[0..4].copy_from_slice(b"\x7fELF");
    bytes[4] = 2;
    bytes[5] = 1;
    bytes[6] = 1;
    write_u16(&mut bytes, 16, 1);
    write_u16(&mut bytes, 18, machine);
    write_u32(&mut bytes, 20, 1);
    write_u32(&mut bytes, 48, elf_flags);
    write_u64(&mut bytes, 40, shoff as u64);
    write_u16(&mut bytes, 52, ELF_HEADER_SIZE as u16);
    write_u16(&mut bytes, 58, SECTION_HEADER_SIZE as u16);
    write_u16(&mut bytes, 60, section_count as u16);
    write_u16(&mut bytes, 62, 5);

    bytes[text_offset..text_offset + text.len()].copy_from_slice(text);
    bytes[rela_offset..rela_offset + rela_text.len()].copy_from_slice(&rela_text);

    let mut symtab = vec![0_u8; symtab_size];
    for (idx, name) in symbol_names.iter().enumerate() {
        let entry_off = SYMTAB_ENTRY_SIZE * (idx + 1);
        write_u32(&mut symtab, entry_off, strtab_offsets[idx]);
        if name == symbol {
            symtab[entry_off + 4] = 0x12;
            write_u16(&mut symtab, entry_off + 6, 1);
            write_u64(&mut symtab, entry_off + 8, 0);
            write_u64(&mut symtab, entry_off + 16, text.len() as u64);
        } else {
            symtab[entry_off + 4] = 0x10;
            write_u16(&mut symtab, entry_off + 6, 0);
        }
    }
    bytes[symtab_offset..symtab_offset + symtab_size].copy_from_slice(&symtab);
    bytes[strtab_offset..strtab_offset + strtab.len()].copy_from_slice(&strtab);
    bytes[shstrtab_offset..shstrtab_offset + shstrtab.len()].copy_from_slice(&shstrtab);

    write_section_header(
        &mut bytes,
        shoff + SECTION_HEADER_SIZE,
        1,
        1,
        6,
        text_offset,
        text.len(),
        0,
        0,
        text_align,
        0,
    );
    write_section_header(
        &mut bytes,
        shoff + SECTION_HEADER_SIZE * 2,
        7,
        4,
        0,
        rela_offset,
        rela_text.len(),
        3,
        1,
        8,
        RELA_ENTRY_SIZE,
    );
    write_section_header(
        &mut bytes,
        shoff + SECTION_HEADER_SIZE * 3,
        18,
        2,
        0,
        symtab_offset,
        symtab_size,
        4,
        1,
        8,
        SYMTAB_ENTRY_SIZE,
    );
    write_section_header(
        &mut bytes,
        shoff + SECTION_HEADER_SIZE * 4,
        26,
        3,
        0,
        strtab_offset,
        strtab.len(),
        0,
        0,
        1,
        0,
    );
    write_section_header(
        &mut bytes,
        shoff + SECTION_HEADER_SIZE * 5,
        34,
        3,
        0,
        shstrtab_offset,
        shstrtab.len(),
        0,
        0,
        1,
        0,
    );
    bytes
}

fn elf64_relocation_type(arch: &str, kind: &str) -> Option<u32> {
    let normalized = kind
        .trim()
        .trim_start_matches("type:")
        .trim_end_matches(';')
        .trim()
        .to_ascii_uppercase()
        .replace('-', "_");
    match arch {
        "riscv64" => match normalized.as_str() {
            "R_RISCV_CALL" | "RISCV_CALL" | "CALL" => Some(18),
            "R_RISCV_CALL_PLT" | "RISCV_CALL_PLT" | "CALL_PLT" => Some(19),
            "R_RISCV_32" | "RISCV_32" => Some(1),
            "R_RISCV_64" | "RISCV_64" => Some(2),
            "R_RISCV_BRANCH" | "RISCV_BRANCH" | "BRANCH" => Some(16),
            "R_RISCV_JAL" | "RISCV_JAL" | "JAL" => Some(17),
            "R_RISCV_PCREL_HI20" | "RISCV_PCREL_HI20" | "PCREL_HI20" => Some(23),
            "R_RISCV_PCREL_LO12_I" | "RISCV_PCREL_LO12_I" | "PCREL_LO12_I" => Some(24),
            "R_RISCV_PCREL_LO12_S" | "RISCV_PCREL_LO12_S" | "PCREL_LO12_S" => Some(25),
            "R_RISCV_HI20" | "RISCV_HI20" | "HI20" => Some(26),
            "R_RISCV_LO12_I" | "RISCV_LO12_I" | "LO12_I" => Some(27),
            "R_RISCV_LO12_S" | "RISCV_LO12_S" | "LO12_S" => Some(28),
            "R_RISCV_RELAX" | "RISCV_RELAX" | "RELAX" => Some(51),
            _ => None,
        },
        _ => None,
    }
}

#[derive(Clone)]
struct Elf32SectionImage {
    name: String,
    sh_type: u32,
    flags: u32,
    data: Vec<u8>,
    size: usize,
    align: u32,
    entsize: usize,
    link: u32,
    info: u32,
    offset: usize,
}

#[derive(Clone)]
struct Elf32RelocationImage {
    section: String,
    offset: u32,
    symbol: Option<String>,
    reloc_type: u32,
    addend: i32,
    rela: bool,
}

fn emit_minimal_elf32_relocatable(
    audit: &MachineAudit,
    symbol: &str,
    machine: u16,
    text_align: u32,
    elf_flags: u32,
) -> Vec<u8> {
    const ELF_HEADER_SIZE: usize = 52;
    const SECTION_HEADER_SIZE: usize = 40;
    const SYMTAB_ENTRY_SIZE: usize = 16;
    const SHT_PROGBITS: u32 = 1;
    const SHT_SYMTAB: u32 = 2;
    const SHT_STRTAB: u32 = 3;
    const SHT_RELA: u32 = 4;
    const SHT_NOBITS: u32 = 8;
    const SHT_REL: u32 = 9;
    const SHF_WRITE: u32 = 0x1;
    const SHF_ALLOC: u32 = 0x2;
    const SHF_EXECINSTR: u32 = 0x4;

    let text = &audit.encoded_bytes;
    let arch = audit_arch(audit);
    let relocations = elf32_relocation_images(audit, arch);

    let mut sections = vec![Elf32SectionImage {
        name: ".text".to_string(),
        sh_type: SHT_PROGBITS,
        flags: SHF_ALLOC | SHF_EXECINSTR,
        data: text.clone(),
        size: text.len(),
        align: text_align,
        entsize: 0,
        link: 0,
        info: 0,
        offset: 0,
    }];
    if !audit.data_bytes.is_empty() {
        sections.push(Elf32SectionImage {
            name: ".data".to_string(),
            sh_type: SHT_PROGBITS,
            flags: SHF_ALLOC | SHF_WRITE,
            data: audit.data_bytes.clone(),
            size: audit.data_bytes.len(),
            align: 4,
            entsize: 0,
            link: 0,
            info: 0,
            offset: 0,
        });
    }
    if audit.bss_size > 0 {
        sections.push(Elf32SectionImage {
            name: ".bss".to_string(),
            sh_type: SHT_NOBITS,
            flags: SHF_ALLOC | SHF_WRITE,
            data: Vec::new(),
            size: audit.bss_size,
            align: 4,
            entsize: 0,
            link: 0,
            info: 0,
            offset: 0,
        });
    }

    let mut section_index = BTreeMap::<String, usize>::new();
    for (idx, section) in sections.iter().enumerate() {
        section_index.insert(section.name.clone(), idx + 1);
    }

    let mut reloc_groups = BTreeMap::<(String, bool), Vec<Elf32RelocationImage>>::new();
    for reloc in relocations {
        reloc_groups
            .entry((reloc.section.clone(), reloc.rela))
            .or_default()
            .push(reloc);
    }

    let symtab_index = 1 + sections.len() + reloc_groups.len();
    let strtab_index = symtab_index + 1;
    let shstrtab_index = symtab_index + 2;

    let symbol_names = elf32_symbol_names(audit, symbol, &reloc_groups);
    let (strtab_offsets, strtab) = elf32_string_table(&symbol_names);
    let mut symbol_index = BTreeMap::<String, u32>::new();
    for (idx, name) in symbol_names.iter().enumerate() {
        symbol_index.insert(name.clone(), (idx + 1) as u32);
    }

    for ((target_section, rela), group) in reloc_groups {
        let mut data = Vec::new();
        for reloc in group {
            let sym_idx = reloc
                .symbol
                .as_ref()
                .and_then(|name| symbol_index.get(name))
                .copied()
                .unwrap_or(0);
            write_u32_to_vec(&mut data, reloc.offset);
            write_u32_to_vec(&mut data, (sym_idx << 8) | (reloc.reloc_type & 0xff));
            if rela {
                data.extend(reloc.addend.to_le_bytes());
            }
        }
        sections.push(Elf32SectionImage {
            name: format!(
                "{}.{}",
                if rela { ".rela" } else { ".rel" },
                target_section.trim_start_matches('.')
            ),
            sh_type: if rela { SHT_RELA } else { SHT_REL },
            flags: 0,
            size: data.len(),
            data,
            align: 4,
            entsize: if rela { 12 } else { 8 },
            link: symtab_index as u32,
            info: section_index.get(&target_section).copied().unwrap_or(1) as u32,
            offset: 0,
        });
    }

    let mut symtab = vec![0_u8; SYMTAB_ENTRY_SIZE];
    for (idx, name) in symbol_names.iter().enumerate() {
        let name_offset = strtab_offsets[idx];
        let (value, size, info, shndx) =
            elf32_symbol_entry_fields(audit, name, symbol, text.len(), &section_index);
        let mut entry = vec![0_u8; SYMTAB_ENTRY_SIZE];
        write_u32(&mut entry, 0, name_offset);
        write_u32(&mut entry, 4, value);
        write_u32(&mut entry, 8, size);
        entry[12] = info;
        entry[13] = 0;
        write_u16(&mut entry, 14, shndx as u16);
        symtab.extend(entry);
    }
    sections.push(Elf32SectionImage {
        name: ".symtab".to_string(),
        sh_type: SHT_SYMTAB,
        flags: 0,
        size: symtab.len(),
        data: symtab,
        align: 4,
        entsize: SYMTAB_ENTRY_SIZE,
        link: strtab_index as u32,
        info: 1,
        offset: 0,
    });
    sections.push(Elf32SectionImage {
        name: ".strtab".to_string(),
        sh_type: SHT_STRTAB,
        flags: 0,
        size: strtab.len(),
        data: strtab,
        align: 1,
        entsize: 0,
        link: 0,
        info: 0,
        offset: 0,
    });

    let section_names = sections
        .iter()
        .map(|section| section.name.clone())
        .chain(std::iter::once(".shstrtab".to_string()))
        .collect::<Vec<_>>();
    let (shstr_offsets, shstrtab) = elf32_string_table(&section_names);
    sections.push(Elf32SectionImage {
        name: ".shstrtab".to_string(),
        sh_type: SHT_STRTAB,
        flags: 0,
        size: shstrtab.len(),
        data: shstrtab,
        align: 1,
        entsize: 0,
        link: 0,
        info: 0,
        offset: 0,
    });

    let mut cursor = ELF_HEADER_SIZE;
    for section in &mut sections {
        cursor = align_to(cursor, section.align.max(1) as usize);
        section.offset = cursor;
        if section.sh_type != SHT_NOBITS {
            cursor = cursor.saturating_add(section.data.len());
        }
    }
    let shoff = align_to(cursor, 4);
    let section_count = sections.len() + 1;
    let total = shoff + SECTION_HEADER_SIZE * section_count;
    let mut bytes = vec![0_u8; total];

    bytes[0..4].copy_from_slice(b"\x7fELF");
    bytes[4] = 1;
    bytes[5] = 1;
    bytes[6] = 1;
    write_u16(&mut bytes, 16, 1);
    write_u16(&mut bytes, 18, machine);
    write_u32(&mut bytes, 20, 1);
    write_u32(&mut bytes, 32, shoff as u32);
    write_u32(&mut bytes, 36, elf_flags);
    write_u16(&mut bytes, 40, ELF_HEADER_SIZE as u16);
    write_u16(&mut bytes, 46, SECTION_HEADER_SIZE as u16);
    write_u16(&mut bytes, 48, section_count as u16);
    write_u16(&mut bytes, 50, shstrtab_index as u16);

    for section in &sections {
        if section.sh_type != SHT_NOBITS && !section.data.is_empty() {
            let start = section.offset;
            let end = start + section.data.len();
            bytes[start..end].copy_from_slice(&section.data);
        }
    }

    for (idx, section) in sections.iter().enumerate() {
        write_elf32_section_header(
            &mut bytes,
            shoff + SECTION_HEADER_SIZE * (idx + 1),
            shstr_offsets[idx],
            section.sh_type,
            section.flags,
            section.offset,
            section.size,
            section.link,
            section.info,
            section.align,
            section.entsize,
        );
    }
    bytes
}

fn elf32_string_table(names: &[String]) -> (Vec<u32>, Vec<u8>) {
    let mut table = vec![0_u8];
    let mut offsets = Vec::new();
    for name in names {
        offsets.push(table.len() as u32);
        table.extend_from_slice(name.as_bytes());
        table.push(0);
    }
    (offsets, table)
}

fn write_u32_to_vec(out: &mut Vec<u8>, value: u32) {
    out.extend(value.to_le_bytes());
}

fn elf32_symbol_names(
    audit: &MachineAudit,
    entry: &str,
    reloc_groups: &BTreeMap<(String, bool), Vec<Elf32RelocationImage>>,
) -> Vec<String> {
    let mut names = vec![entry.to_string()];
    for name in audit.symbols.iter().chain(audit.externs.iter()) {
        if !names.iter().any(|item| item == name) {
            names.push(name.clone());
        }
    }
    for directive in &audit.directives {
        if !directive.name.is_empty()
            && !directive.name.starts_with('.')
            && !names.iter().any(|item| item == &directive.name)
        {
            names.push(directive.name.clone());
        }
    }
    for group in reloc_groups.values() {
        for reloc in group {
            if let Some(symbol) = &reloc.symbol {
                if !names.iter().any(|item| item == symbol) {
                    names.push(symbol.clone());
                }
            }
        }
    }
    names
}

fn elf32_symbol_entry_fields(
    audit: &MachineAudit,
    name: &str,
    entry: &str,
    text_len: usize,
    section_index: &BTreeMap<String, usize>,
) -> (u32, u32, u8, usize) {
    if name == entry || (audit.symbols.contains(name) && !audit.externs.contains(name)) {
        return (
            0,
            if name == entry { text_len as u32 } else { 0 },
            0x12,
            section_index.get(".text").copied().unwrap_or(1),
        );
    }
    if audit
        .directives
        .iter()
        .any(|directive| directive.name == name)
    {
        let section = if audit
            .directives
            .iter()
            .any(|directive| directive.name == name && directive.status == "closed_bss")
        {
            ".bss"
        } else {
            ".data"
        };
        return (0, 0, 0x11, section_index.get(section).copied().unwrap_or(0));
    }
    (0, 0, 0x10, 0)
}

fn elf32_relocation_images(audit: &MachineAudit, arch: &str) -> Vec<Elf32RelocationImage> {
    audit
        .relocation_records
        .iter()
        .enumerate()
        .filter_map(|(idx, record)| {
            let (reloc_type, rela) = elf32_relocation_type(arch, &record.kind)?;
            let offset = record
                .offset
                .or_else(|| infer_machine_relocation_offset(audit, arch, record, idx))
                .unwrap_or(0);
            Some(Elf32RelocationImage {
                section: if record.section.is_empty() {
                    ".text".to_string()
                } else {
                    record.section.clone()
                },
                offset,
                symbol: record.symbol.clone(),
                reloc_type,
                addend: record.addend,
                rela,
            })
        })
        .collect()
}

fn elf32_relocation_type(arch: &str, kind: &str) -> Option<(u32, bool)> {
    let normalized = kind
        .trim()
        .trim_start_matches("type:")
        .trim_end_matches(';')
        .trim()
        .to_ascii_uppercase()
        .replace('-', "_");
    match arch {
        "i386" => match normalized.as_str() {
            "R_386_32" | "386_32" => Some((1, false)),
            "R_386_PC32" | "PC32" => Some((2, false)),
            "R_386_GOT32" | "GOT32" => Some((3, false)),
            "R_386_PLT32" | "PLT32" => Some((4, false)),
            _ => None,
        },
        "riscv32" => match normalized.as_str() {
            "R_RISCV_32" | "RISCV_32" => Some((1, true)),
            "R_RISCV_BRANCH" | "RISCV_BRANCH" | "BRANCH" => Some((16, true)),
            "R_RISCV_JAL" | "RISCV_JAL" | "JAL" => Some((17, true)),
            "R_RISCV_CALL" | "RISCV_CALL" | "CALL" => Some((18, true)),
            "R_RISCV_CALL_PLT" | "RISCV_CALL_PLT" | "CALL_PLT" => Some((19, true)),
            "R_RISCV_GOT_HI20" | "RISCV_GOT_HI20" | "GOT_HI20" => Some((20, true)),
            "R_RISCV_PCREL_HI20" | "RISCV_PCREL_HI20" | "PCREL_HI20" => Some((23, true)),
            "R_RISCV_PCREL_LO12"
            | "RISCV_PCREL_LO12"
            | "PCREL_LO12"
            | "R_RISCV_PCREL_LO12_I"
            | "RISCV_PCREL_LO12_I"
            | "PCREL_LO12_I" => Some((24, true)),
            "R_RISCV_PCREL_LO12_S" | "RISCV_PCREL_LO12_S" | "PCREL_LO12_S" => Some((25, true)),
            "R_RISCV_HI20" | "RISCV_HI20" | "HI20" => Some((26, true)),
            "R_RISCV_LO12" | "RISCV_LO12" | "LO12" | "R_RISCV_LO12_I" | "RISCV_LO12_I"
            | "LO12_I" => Some((27, true)),
            "R_RISCV_LO12_S" | "RISCV_LO12_S" | "LO12_S" => Some((28, true)),
            "R_RISCV_RELAX" | "RISCV_RELAX" | "RELAX" => Some((51, true)),
            _ => None,
        },
        _ => None,
    }
}

fn infer_machine_relocation_offset(
    audit: &MachineAudit,
    arch: &str,
    record: &MachineRelocationRecord,
    occurrence: usize,
) -> Option<u32> {
    let symbol = record.symbol.as_deref()?;
    let mut offset = 0_u32;
    let mut seen = 0_usize;
    for inst in &audit.instructions {
        let len = machine_instruction_encoded_len(arch, inst)? as u32;
        if inst.operands.iter().any(|operand| operand == symbol) {
            if seen == occurrence {
                return Some(offset + machine_relocation_patch_delta(arch, inst, &record.kind));
            }
            seen += 1;
        }
        offset = offset.saturating_add(len);
    }
    None
}

fn machine_instruction_encoded_len(arch: &str, inst: &MachineInstruction) -> Option<usize> {
    match arch {
        "i386" => try_encode_i386_instruction(inst)
            .ok()
            .flatten()
            .map(|bytes| bytes.len()),
        "armv7" | "armv7em" | "thumb" | "thumb2" => {
            let mut diagnostics = Vec::new();
            let length =
                encode_thumb_instructions(std::slice::from_ref(inst), &mut diagnostics).len();
            diagnostics.is_empty().then_some(length)
        }
        "riscv32" => {
            if matches!(inst.mnemonic.as_str(), "label") {
                Some(0)
            } else if inst.mnemonic == "call" {
                Some(8)
            } else if matches!(inst.mnemonic.as_str(), "c.nop" | "c.ret" | "c.addi") {
                Some(2)
            } else {
                Some(4)
            }
        }
        _ => None,
    }
}

fn machine_relocation_patch_delta(arch: &str, inst: &MachineInstruction, kind: &str) -> u32 {
    if arch == "i386" {
        return match inst.mnemonic.as_str() {
            "call" | "jmp" => 1,
            mnemonic if CONDITIONAL_JUMPS.contains(&mnemonic) => 2,
            _ => 0,
        };
    }
    let kind = kind.to_ascii_uppercase();
    if arch == "riscv32" && kind.contains("LO12") && inst.mnemonic == "auipc" {
        return 4;
    }
    0
}

#[allow(clippy::too_many_arguments)]
fn write_section_header(
    bytes: &mut [u8],
    offset: usize,
    name: u32,
    sh_type: u32,
    flags: u64,
    data_offset: usize,
    size: usize,
    link: u32,
    info: u32,
    align: u64,
    entsize: usize,
) {
    write_u32(bytes, offset, name);
    write_u32(bytes, offset + 4, sh_type);
    write_u64(bytes, offset + 8, flags);
    write_u64(bytes, offset + 24, data_offset as u64);
    write_u64(bytes, offset + 32, size as u64);
    write_u32(bytes, offset + 40, link);
    write_u32(bytes, offset + 44, info);
    write_u64(bytes, offset + 48, align);
    write_u64(bytes, offset + 56, entsize as u64);
}

#[allow(clippy::too_many_arguments)]
fn write_elf32_section_header(
    bytes: &mut [u8],
    offset: usize,
    name: u32,
    sh_type: u32,
    flags: u32,
    data_offset: usize,
    size: usize,
    link: u32,
    info: u32,
    align: u32,
    entsize: usize,
) {
    write_u32(bytes, offset, name);
    write_u32(bytes, offset + 4, sh_type);
    write_u32(bytes, offset + 8, flags);
    write_u32(bytes, offset + 16, data_offset as u32);
    write_u32(bytes, offset + 20, size as u32);
    write_u32(bytes, offset + 24, link);
    write_u32(bytes, offset + 28, info);
    write_u32(bytes, offset + 32, align);
    write_u32(bytes, offset + 36, entsize as u32);
}

fn classify_object_bytes(bytes: &[u8]) -> (&'static str, bool) {
    if bytes.starts_with(b"\x7fELF") {
        match bytes.get(4).copied() {
            Some(1) => ("elf32", true),
            Some(2) => ("elf64", true),
            _ => ("unknown", false),
        }
    } else if bytes.len() >= 4
        && ((bytes[0] == 0x64 && bytes[1] == 0x86) || (bytes[0] == 0x4c && bytes[1] == 0x01))
    {
        ("coff", true)
    } else if bytes.starts_with(&[0xcf, 0xfa, 0xed, 0xfe])
        || bytes.starts_with(&[0xfe, 0xed, 0xfa, 0xcf])
    {
        ("macho", true)
    } else if bytes.starts_with(b"\0asm") {
        ("wasm", true)
    } else {
        ("unknown", false)
    }
}

fn run_system_loader_smoke(
    audit: &MachineAudit,
    target: &str,
    expected_exit: Option<i32>,
) -> Result<Value, Box<dyn Error>> {
    let arch = audit_arch(audit);
    if (target.contains("windows")
        || target.contains("msvc")
        || audit_object_format(audit) == "coff")
        && arch == "x86_64"
    {
        return run_windows_pe_system_loader_smoke(audit, target, expected_exit);
    }
    if target.contains("linux") && target.contains("x86_64") && arch == "x86_64" {
        return run_linux_elf_system_loader_smoke(audit, target, expected_exit);
    }
    if (target.contains("darwin")
        || target.contains("apple")
        || audit_object_format(audit) == "macho")
        && arch == "x86_64"
    {
        return run_macos_macho_system_loader_smoke(audit, target, expected_exit);
    }
    Ok(json!({
        "status": "blocked_system_loader_target_required",
        "target": target,
        "source": audit.path,
        "arch": arch,
        "diagnostic": "E_MACHINE_SYSTEM_LOADER_SMOKE_TARGET_001",
        "reason": "system-loader smoke currently covers final PE64 x86_64 on Windows, final ELF64 x86_64 on Linux and final Mach-O x86_64 on macOS"
    }))
}

fn phase12_link_image_from_audit(
    audit: &MachineAudit,
    target: &str,
) -> Result<Phase12LinkedImage, Box<dyn Error>> {
    let object_format = object_format_for_target(target, audit);
    let object_format = if object_format == "elf" {
        "elf64"
    } else {
        object_format
    };
    let object_bytes = emit_object_bytes(audit, object_format)?;
    let input = Phase12LinkInput {
        path: audit.path.clone(),
        source: Some(audit.path.clone()),
        object_format: object_format.to_string(),
        link_unit_origin: "ncc_audit".to_string(),
        bytes: object_bytes.clone(),
        hash: hash_bytes(&object_bytes),
        dynamic_imports: phase12_dynamic_import_symbols_from_audit(audit),
        unit: Some(phase12_object_unit_from_audit(audit, object_format)),
    };
    phase12_link_image(&[input])
}

fn phase12_mark_executable(path: &Path) -> Result<(), Box<dyn Error>> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mut perms = fs::metadata(path)?.permissions();
        perms.set_mode(perms.mode() | 0o111);
        fs::set_permissions(path, perms)?;
    }
    let _ = path;
    Ok(())
}

fn system_loader_status(run: &std::process::Output, expected_exit: Option<i32>) -> &'static str {
    let exit_code = run.status.code();
    if expected_exit
        .map(|expected| exit_code == Some(expected))
        .unwrap_or_else(|| run.status.success())
    {
        "passed"
    } else {
        "failed_execute"
    }
}

fn run_linux_elf_system_loader_smoke(
    audit: &MachineAudit,
    target: &str,
    expected_exit: Option<i32>,
) -> Result<Value, Box<dyn Error>> {
    let host_os = std::env::consts::OS;
    let host_arch = std::env::consts::ARCH;
    if host_os != "linux" || host_arch != "x86_64" {
        return Ok(json!({
            "status": "blocked_native_linux_x86_64_runner_required",
            "target": target,
            "source": audit.path,
            "host_os": host_os,
            "host_arch": host_arch,
            "diagnostic": "E_MACHINE_SYSTEM_LOADER_SMOKE_HOST_001",
            "reason": "ELF system-loader smoke must execute on a native Linux x86_64 runner"
        }));
    }
    let root = Path::new("target/tmp/machine_system_loader_smoke");
    fs::create_dir_all(root)?;
    let stem = Path::new(&audit.path)
        .file_stem()
        .and_then(|name| name.to_str())
        .unwrap_or("machine");
    let exe_path = root.join(format!("{stem}_linux_x86_64_loader"));
    let image = phase12_link_image_from_audit(audit, target)?;
    let executable = phase12_elf64_os_executable_bytes(&image, target)?;
    fs::write(&exe_path, &executable)?;
    phase12_mark_executable(&exe_path)?;
    let run = Command::new(&exe_path).output()?;
    Ok(json!({
        "status": system_loader_status(&run, expected_exit),
        "target": target,
        "source": audit.path,
        "entry": image.entry,
        "environment": "native-linux-x86_64",
        "evidence_level": "executed_os_loader_executable",
        "artifact_format": "elf64",
        "loader": "linux-kernel-elf-loader",
        "executable": exe_path.display().to_string(),
        "executable_sha256": hash_bytes(&executable),
        "stdout": String::from_utf8_lossy(&run.stdout).trim().to_string(),
        "stderr": String::from_utf8_lossy(&run.stderr).trim().to_string(),
        "exit_code": run.status.code(),
        "expected_exit": expected_exit
    }))
}

