fn run_native_link_smoke(audit: &MachineAudit, target: &str) -> Result<Value, Box<dyn Error>> {
    if audit_arch(audit) == "aarch64" || target.contains("aarch64") {
        return run_aarch64_native_link_smoke(audit, target);
    }
    if audit_arch(audit) == "riscv64" || target.contains("riscv64") {
        return run_riscv64_qemu_link_smoke(audit, target);
    }
    if audit_arch(audit) == "riscv32" || target.contains("riscv32") {
        return run_riscv32_qemu_link_smoke(audit, target);
    }
    if audit_arch(audit) == "i386" || target.contains("i386") {
        return run_i386_qemu_link_smoke(audit, target);
    }
    if target.contains("windows") || target.contains("msvc") || audit_object_format(audit) == "coff"
    {
        return run_windows_coff_native_link_smoke(audit, target);
    }
    if target.contains("darwin")
        || target.contains("apple")
        || audit_object_format(audit) == "macho"
    {
        return run_macos_macho_native_link_smoke(audit, target);
    }

    let host_os = std::env::consts::OS;
    let host_arch = std::env::consts::ARCH;
    if host_os != "linux"
        || host_arch != "x86_64"
        || audit_arch(audit) != "x86_64"
        || !target.contains("x86_64")
        || !target.contains("linux")
    {
        return Ok(json!({
            "status": "blocked_cross_host_required",
            "target": target,
            "source": audit.path,
            "host_os": host_os,
            "host_arch": host_arch,
            "reason": "native link-smoke in this workspace is limited to Linux x86_64; other targets require CI runner or emulator evidence"
        }));
    }
    let c_compiler = machine_c_compiler("cc");
    if Command::new(&c_compiler).arg("--version").output().is_err() {
        return Ok(json!({
            "status": "blocked_no_c_compiler",
            "target": target,
            "diagnostic": "E_MACHINE_LINK_SMOKE_ENV_001",
            "compiler": c_compiler
        }));
    }
    let entry = audit.entry.as_deref().unwrap_or("main");
    let root = Path::new("target/tmp/machine_link_smoke");
    fs::create_dir_all(root)?;
    let stem = Path::new(&audit.path)
        .file_stem()
        .and_then(|name| name.to_str())
        .unwrap_or("machine");
    let object_path = root.join(format!("{}.o", stem));
    let harness_path = root.join(format!("{}_harness.c", stem));
    let exe_path = root.join(format!("{}_smoke", stem));
    let object = emit_object_bytes(audit, "elf")?;
    fs::write(&object_path, &object)?;
    let harness = if audit.externs.contains("machine_marker") {
        format!(
            "#include <stdio.h>\nstatic int called = 0;\nvoid machine_marker(void) {{ called = 1; }}\nextern void {entry}(void);\nint main(void) {{ {entry}(); printf(\"external-called=%d\\n\", called); return called ? 0 : 1; }}\n"
        )
    } else {
        format!(
            "#include <stdio.h>\nextern long {entry}(long a, long b);\nint main(void) {{ long r = {entry}(40, 2); printf(\"%ld\\n\", r); return r == 42 ? 0 : 1; }}\n"
        )
    };
    fs::write(&harness_path, harness)?;
    let link = Command::new(&c_compiler)
        .arg(&harness_path)
        .arg(&object_path)
        .arg("-o")
        .arg(&exe_path)
        .output()?;
    if !link.status.success() {
        return Ok(json!({
            "status": "failed_link",
            "target": target,
            "object": object_path.display().to_string(),
            "stderr": String::from_utf8_lossy(&link.stderr).to_string(),
            "diagnostic": "E_MACHINE_LINK_SMOKE_001"
        }));
    }
    let run = Command::new(&exe_path).output()?;
    Ok(json!({
        "status": if run.status.success() { "passed" } else { "failed_execute" },
        "target": target,
        "source": audit.path,
        "entry": entry,
        "object": object_path.display().to_string(),
        "executable": exe_path.display().to_string(),
        "object_sha256": hash_bytes(&object),
        "compiler": c_compiler,
        "stdout": String::from_utf8_lossy(&run.stdout).trim().to_string(),
        "stderr": String::from_utf8_lossy(&run.stderr).trim().to_string(),
        "exit_code": run.status.code()
    }))
}

fn run_windows_coff_native_link_smoke(
    audit: &MachineAudit,
    target: &str,
) -> Result<Value, Box<dyn Error>> {
    let host_os = std::env::consts::OS;
    let host_arch = std::env::consts::ARCH;
    if host_os != "windows"
        || host_arch != "x86_64"
        || audit_arch(audit) != "x86_64"
        || !(target.contains("windows") || target.contains("msvc"))
    {
        return Ok(json!({
            "status": "blocked_native_windows_x86_64_runner_required",
            "target": target,
            "source": audit.path,
            "host_os": host_os,
            "host_arch": host_arch,
            "diagnostic": "E_MACHINE_NATIVE_EXECUTION_HOST_002",
            "reason": "COFF executable smoke requires a retained native Windows x86_64 runner artifact"
        }));
    }
    if Command::new("rustc").arg("--version").output().is_err() {
        return Ok(json!({
            "status": "blocked_no_rustc",
            "target": target,
            "diagnostic": "E_MACHINE_LINK_SMOKE_ENV_001"
        }));
    }

    let entry = audit.entry.as_deref().unwrap_or("main");
    let root = Path::new("target/tmp/machine_native_executable_smoke");
    fs::create_dir_all(root)?;
    let stem = Path::new(&audit.path)
        .file_stem()
        .and_then(|name| name.to_str())
        .unwrap_or("machine");
    let object_path = root.join(format!("{}_windows_x86_64.obj", stem));
    let harness_path = root.join(format!("{}_windows_x86_64_harness.rs", stem));
    let exe_path = root.join(format!("{}_windows_x86_64_smoke.exe", stem));
    let object = emit_object_bytes(audit, "coff")?;
    fs::write(&object_path, &object)?;
    let harness = format!(
        "unsafe extern \"C\" {{ fn {entry}() -> i64; }}\nfn main() {{ let value = unsafe {{ {entry}() }}; println!(\"{{}}\", value); if value != 42 {{ std::process::exit(1); }} }}\n"
    );
    fs::write(&harness_path, harness)?;
    let link = Command::new("rustc")
        .arg(&harness_path)
        .arg("-C")
        .arg(format!("link-arg={}", object_path.display()))
        .arg("-o")
        .arg(&exe_path)
        .output()?;
    if !link.status.success() {
        return Ok(json!({
            "status": "failed_link",
            "target": target,
            "object": object_path.display().to_string(),
            "stdout": String::from_utf8_lossy(&link.stdout).to_string(),
            "stderr": String::from_utf8_lossy(&link.stderr).to_string(),
            "diagnostic": "E_MACHINE_COFF_EXECUTABLE_SMOKE_001"
        }));
    }
    let run = Command::new(&exe_path).output()?;
    Ok(json!({
        "status": if run.status.success() { "passed" } else { "failed_execute" },
        "target": target,
        "source": audit.path,
        "entry": entry,
        "environment": "native-windows-x86_64",
        "evidence_level": "executed_native_executable",
        "object_format": "coff",
        "linker": "rustc-msvc-link",
        "object": object_path.display().to_string(),
        "executable": exe_path.display().to_string(),
        "object_sha256": hash_bytes(&object),
        "stdout": String::from_utf8_lossy(&run.stdout).trim().to_string(),
        "stderr": String::from_utf8_lossy(&run.stderr).trim().to_string(),
        "exit_code": run.status.code()
    }))
}

