fn run_riscv64_qemu_link_smoke(
    audit: &MachineAudit,
    target: &str,
) -> Result<Value, Box<dyn Error>> {
    let host_os = std::env::consts::OS;
    let host_arch = std::env::consts::ARCH;
    if host_os != "linux" {
        return Ok(json!({
            "status": "blocked_linux_qemu_required",
            "target": target,
            "source": audit.path,
            "host_os": host_os,
            "host_arch": host_arch,
            "diagnostic": "E_MACHINE_RISCV64_EMULATOR_ENV_001",
            "reason": "riscv64 execution evidence requires Linux qemu-riscv64 with a riscv64 cross linker"
        }));
    }
    let riscv64_compiler = machine_env_tool("RISCV64_CC", "riscv64-linux-gnu-gcc");
    if Command::new(&riscv64_compiler)
        .arg("--version")
        .output()
        .is_err()
    {
        return Ok(json!({
            "status": "blocked_no_riscv64_cross_compiler",
            "target": target,
            "source": audit.path,
            "host_os": host_os,
            "host_arch": host_arch,
            "diagnostic": "E_MACHINE_RISCV64_TOOLCHAIN_001",
            "compiler": riscv64_compiler
        }));
    }
    if Command::new("qemu-riscv64")
        .arg("--version")
        .output()
        .is_err()
    {
        return Ok(json!({
            "status": "blocked_no_qemu_riscv64",
            "target": target,
            "source": audit.path,
            "host_os": host_os,
            "host_arch": host_arch,
            "diagnostic": "E_MACHINE_RISCV64_EMULATOR_ENV_001"
        }));
    }

    let entry = audit.entry.as_deref().unwrap_or("main");
    let root = Path::new("target/tmp/machine_non_x86_execution");
    fs::create_dir_all(root)?;
    let stem = Path::new(&audit.path)
        .file_stem()
        .and_then(|name| name.to_str())
        .unwrap_or("machine");
    let object_path = root.join(format!("{}_riscv64.o", stem));
    let harness_path = root.join(format!("{}_riscv64_harness.c", stem));
    let exe_path = root.join(format!("{}_riscv64_qemu_smoke", stem));
    let object = emit_object_bytes(audit, "elf")?;
    fs::write(&object_path, &object)?;
    let harness = format!(
        "#include <stdio.h>\nextern long {entry}(long a, long b);\nint main(void) {{ long r = {entry}(40, 2); printf(\"%ld\\n\", r); return r == 42 ? 0 : 1; }}\n"
    );
    fs::write(&harness_path, harness)?;
    let link = Command::new(&riscv64_compiler)
        .arg("-static")
        .arg(&harness_path)
        .arg(&object_path)
        .arg("-o")
        .arg(&exe_path)
        .output()?;
    if !link.status.success() {
        return Ok(json!({
            "status": "failed_link",
            "target": target,
            "object": object_path.display().to_string(),
            "stderr": String::from_utf8_lossy(&link.stderr).to_string(),
            "diagnostic": "E_MACHINE_RISCV64_LINK_SMOKE_001"
        }));
    }
    let run = Command::new("qemu-riscv64").arg(&exe_path).output()?;
    Ok(json!({
        "status": if run.status.success() { "passed" } else { "failed_execute" },
        "target": target,
        "source": audit.path,
        "entry": entry,
        "environment": "qemu-riscv64-user",
        "evidence_level": "executed_emulated",
        "emulator": "qemu-riscv64",
        "cross_compiler": riscv64_compiler,
        "object": object_path.display().to_string(),
        "executable": exe_path.display().to_string(),
        "object_sha256": hash_bytes(&object),
        "stdout": String::from_utf8_lossy(&run.stdout).trim().to_string(),
        "stderr": String::from_utf8_lossy(&run.stderr).trim().to_string(),
        "exit_code": run.status.code()
    }))
}

