fn resolve_node_command_for_smoke() -> Option<PathBuf> {
    for env_name in ["NODE", "NODE_BINARY"] {
        if let Ok(value) = env::var(env_name) {
            let candidate = PathBuf::from(value);
            if candidate.exists() && candidate.is_file() {
                return Some(candidate);
            }
        }
    }

    if Command::new("node").arg("--version").output().is_ok() {
        return Some(PathBuf::from("node"));
    }

    let users_dir = Path::new("/mnt/c/Users");
    if let Ok(entries) = fs::read_dir(users_dir) {
        for entry in entries.flatten() {
            let candidate = entry
                .path()
                .join(".cache/codex-runtimes/codex-primary-runtime/dependencies/node/bin/node.exe");
            if candidate.exists() && candidate.is_file() {
                return Some(candidate);
            }
        }
    }

    None
}

fn run_wasm_node_smoke(audit: &MachineAudit) -> Result<Value, Box<dyn Error>> {
    let Some(node) = resolve_node_command_for_smoke() else {
        return Ok(json!({
            "status": "blocked_no_node",
            "target": "wasm32-unknown-unknown",
            "diagnostic": "E_MACHINE_WASM_SMOKE_ENV_001"
        }));
    };
    let root = Path::new("target/tmp/machine_wasm_smoke");
    fs::create_dir_all(root)?;
    let wasm_path = root.join("machine_smoke.wasm");
    let runner_path = root.join("machine_smoke_runner.mjs");
    fs::write(&wasm_path, &audit.encoded_bytes)?;
    let runner = format!(
        "import fs from 'node:fs';\nconst bytes = fs.readFileSync({:?});\nconst mod = await WebAssembly.instantiate(bytes, {{}});\nconst value = mod.instance.exports.main();\nconsole.log(String(value));\nprocess.exit(value === 42 ? 0 : 1);\n",
        wasm_path.display().to_string()
    );
    fs::write(&runner_path, runner)?;
    let run = Command::new(&node).arg(&runner_path).output()?;
    Ok(json!({
        "status": if run.status.success() { "passed" } else { "failed_execute" },
        "target": "wasm32-unknown-unknown",
        "source": audit.path,
        "node": node.display().to_string(),
        "artifact": wasm_path.display().to_string(),
        "artifact_sha256": hash_bytes(&audit.encoded_bytes),
        "stdout": String::from_utf8_lossy(&run.stdout).trim().to_string(),
        "stderr": String::from_utf8_lossy(&run.stderr).trim().to_string(),
        "exit_code": run.status.code()
    }))
}

fn decode_known_x86_64_bytes(bytes: &[u8]) -> (Vec<Value>, Vec<Value>) {
    let (decoded, unknown) = decode_native_x86_64(bytes);
    (
        decoded
            .iter()
            .map(|inst| {
                let operands = inst.operands.join(", ");
                json!({
                    "offset": inst.offset,
                    "length": inst.length,
                    "mnemonic": inst.mnemonic,
                    "operands": inst.operands,
                    "feature_family": inst.feature_family,
                    "text": if operands.is_empty() {
                        inst.mnemonic.clone()
                    } else {
                        format!("{} {}", inst.mnemonic, operands)
                    }
                })
            })
            .collect(),
        unknown
            .iter()
            .map(|byte| {
                json!({
                    "code": byte.diagnostic,
                    "offset": byte.offset,
                    "byte": format!("{:02x}", byte.byte),
                    "message": "unknown byte in native x86_64 decoder"
                })
            })
            .collect(),
    )
}

fn render_asm(audit: &MachineAudit) -> String {
    let mut out = String::new();
    out.push_str("; ncc machine asm\n");
    if let Some(entry) = &audit.entry {
        out.push_str(&format!(".global {}\n{}:\n", entry, entry));
    }
    for inst in &audit.instructions {
        if inst.mnemonic == "label" {
            if let Some(label) = inst.operands.first() {
                out.push_str(&format!("{}:\n", label));
            }
        } else {
            out.push_str("    ");
            out.push_str(&inst.text);
            out.push('\n');
        }
    }
    out
}

