#[derive(Clone)]
struct MachineTargetRow {
    triple: &'static str,
    arch: &'static str,
    abi: &'static str,
    object: &'static str,
    status: &'static str,
    evidence: &'static str,
}

impl MachineTargetRow {
    fn new(
        triple: &'static str,
        arch: &'static str,
        abi: &'static str,
        object: &'static str,
        status: &'static str,
        evidence: &'static str,
    ) -> Self {
        Self {
            triple,
            arch,
            abi,
            object,
            status,
            evidence,
        }
    }
}

