fn authority_tool_status(label: &str, names: &[&str]) -> Value {
    if let Some(path) = find_tool(names) {
        let version = tool_version(&path);
        json!({
            "tool": label,
            "status": "available",
            "path": path,
            "version": version
        })
    } else {
        json!({
            "tool": label,
            "status": "missing",
            "diagnostic": "E_MACHINE_AUTHORITY_TOOL_MISSING_001"
        })
    }
}

fn assemble_with_authority(
    audit: &MachineAudit,
    target: &str,
    tool: &str,
    out: &str,
) -> Result<Value, Box<dyn Error>> {
    if audit_arch(audit) == "wasm32" {
        return Ok(json!({
            "status": "blocked",
            "tool": tool,
            "target": target,
            "diagnostic": "E_MACHINE_AUTHORITY_WASM_ASM_001",
            "reason": "WASM authority assembly requires a WAT/WASM pipeline, not native ASM text"
        }));
    }
    let executable = authority_executable_for_tool(tool, target);
    let Some(executable) = executable else {
        return Ok(json!({
            "status": "blocked",
            "tool": tool,
            "target": target,
            "diagnostic": "E_MACHINE_AUTHORITY_TOOL_MISSING_001"
        }));
    };
    if tool == "nasm" && audit_arch(audit) != "x86_64" {
        return Ok(json!({
            "status": "blocked",
            "tool": tool,
            "target": target,
            "diagnostic": "E_MACHINE_AUTHORITY_TARGET_UNSUPPORTED_001",
            "reason": "NASM authority is only applicable to x86_64 machine sources"
        }));
    }
    let root = Path::new("target/tmp/machine_authority");
    fs::create_dir_all(root)?;
    let stem = source_stem(&audit.path);
    let asm_path = root.join(format!(
        "{}_{}_{}.{}",
        stem,
        target_family_key(target),
        sanitize_tool_name(tool),
        if tool == "nasm" { "asm" } else { "s" }
    ));
    let asm = render_authority_asm(audit, target, tool);
    fs::write(&asm_path, asm.as_bytes())?;
    let mut cmd = Command::new(&executable);
    match tool {
        "llvm-mc" => {
            cmd.arg(format!("-triple={}", llvm_triple_for_target(target)))
                .arg("-filetype=obj")
                .arg("-o")
                .arg(out)
                .arg(&asm_path);
        }
        "clang" => {
            cmd.arg("-target")
                .arg(clang_triple_for_target(target))
                .arg("-x")
                .arg("assembler")
                .arg("-c")
                .arg(&asm_path)
                .arg("-o")
                .arg(out);
        }
        "nasm" => {
            cmd.arg("-f")
                .arg(nasm_format_for_target(target))
                .arg(&asm_path)
                .arg("-o")
                .arg(out);
        }
        "gas" => {
            cmd.arg("-o").arg(out).arg(&asm_path);
        }
        other => {
            return Ok(json!({
                "status": "blocked",
                "tool": other,
                "target": target,
                "diagnostic": "E_MACHINE_AUTHORITY_TOOL_UNKNOWN_001"
            }));
        }
    }
    let rendered_command = format!("{:?}", cmd);
    let output = cmd.output()?;
    let success = output.status.success();
    let bytes = if success {
        fs::read(out).unwrap_or_default()
    } else {
        Vec::new()
    };
    Ok(json!({
        "status": if success { "passed" } else { "failed" },
        "tool": tool,
        "tool_path": executable,
        "target": target,
        "source": audit.path,
        "asm_path": asm_path.display().to_string(),
        "object": out,
        "object_bytes": bytes.len(),
        "object_sha256": if bytes.is_empty() { Value::Null } else { json!(hash_bytes(&bytes)) },
        "command": rendered_command,
        "stdout": String::from_utf8_lossy(&output.stdout).trim().to_string(),
        "stderr": String::from_utf8_lossy(&output.stderr).trim().to_string(),
        "exit_code": output.status.code(),
        "diagnostic": if success { Value::Null } else { json!("E_MACHINE_AUTHORITY_ASSEMBLE_001") }
    }))
}

fn disasm_object_with_authority(path: &str, tool: &str) -> Result<Value, Box<dyn Error>> {
    let executable = match tool {
        "llvm-objdump" => find_tool(&["llvm-objdump"]),
        "objdump" => find_tool(&["objdump"]),
        other => {
            return Ok(json!({
                "status": "blocked",
                "tool": other,
                "diagnostic": "E_MACHINE_AUTHORITY_TOOL_UNKNOWN_001"
            }));
        }
    };
    let Some(executable) = executable else {
        return Ok(json!({
            "status": "blocked",
            "tool": tool,
            "diagnostic": "E_MACHINE_AUTHORITY_TOOL_MISSING_001"
        }));
    };
    let mut cmd = Command::new(&executable);
    cmd.arg("-d").arg(path);
    let rendered_command = format!("{:?}", cmd);
    let output = cmd.output()?;
    let success = output.status.success();
    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    Ok(json!({
        "status": if success { "passed" } else { "failed" },
        "tool": tool,
        "tool_path": executable,
        "object": path,
        "command": rendered_command,
        "stdout_sha256": hash_bytes(stdout.as_bytes()),
        "stdout": stdout,
        "stderr": String::from_utf8_lossy(&output.stderr).trim().to_string(),
        "exit_code": output.status.code(),
        "diagnostic": if success { Value::Null } else { json!("E_MACHINE_AUTHORITY_DISASM_001") }
    }))
}

fn render_authority_asm(audit: &MachineAudit, target: &str, tool: &str) -> String {
    let entry = audit.entry.as_deref().unwrap_or("main");
    let mut out = String::new();
    if tool == "nasm" {
        for ext in &audit.externs {
            out.push_str(&format!("extern {}\n", ext));
        }
        out.push_str(&format!("global {}\nsection .text\n{}:\n", entry, entry));
    } else {
        if audit_arch(audit) == "x86_64" {
            out.push_str(".intel_syntax noprefix\n");
        }
        out.push_str(".text\n");
        for ext in &audit.externs {
            out.push_str(&format!(".extern {}\n", ext));
        }
        out.push_str(&format!(".globl {}\n", entry));
        if target.contains("linux")
            || target.contains("elf")
            || audit_object_format(audit) == "elf64"
        {
            out.push_str(&format!(".type {}, @function\n", entry));
        }
        out.push_str(&format!("{}:\n", entry));
    }
    for inst in &audit.instructions {
        if inst.mnemonic == "label" {
            if let Some(label) = inst.operands.first() {
                out.push_str(&format!("{}:\n", label));
            }
        } else {
            out.push_str("    ");
            out.push_str(&inst.text);
            out.push('\n');
        }
    }
    out
}

fn authority_executable_for_tool(tool: &str, target: &str) -> Option<String> {
    match tool {
        "llvm-mc" => find_tool(&["llvm-mc"]),
        "clang" => find_tool(&["clang"]),
        "nasm" => find_tool(&["nasm"]),
        "gas" if target.contains("aarch64") => find_tool(&["aarch64-linux-gnu-as"]),
        "gas" if target.contains("riscv64") => find_tool(&["riscv64-linux-gnu-as"]),
        "gas" => find_tool(&["as"]),
        _ => None,
    }
}

fn find_tool(names: &[&str]) -> Option<String> {
    for name in names {
        if let Ok(output) = Command::new("which").arg(name).output() {
            if output.status.success() {
                let path = String::from_utf8_lossy(&output.stdout).trim().to_string();
                if !path.is_empty() {
                    return Some(path);
                }
            }
        }
        for version in (10..=25).rev() {
            let path = format!("/usr/lib/llvm-{}/bin/{}", version, name);
            if Path::new(&path).exists() {
                return Some(path);
            }
        }
    }
    None
}

fn tool_version(path: &str) -> String {
    Command::new(path)
        .arg("--version")
        .output()
        .ok()
        .map(|output| {
            String::from_utf8_lossy(&output.stdout)
                .lines()
                .next()
                .unwrap_or("")
                .to_string()
        })
        .filter(|line| !line.is_empty())
        .unwrap_or_else(|| "version_unavailable".to_string())
}

fn llvm_triple_for_target(target: &str) -> &str {
    if target.contains("windows") || target.contains("msvc") {
        "x86_64-pc-windows-msvc"
    } else if target.contains("darwin") || target.contains("apple") {
        "x86_64-apple-darwin"
    } else if target.contains("aarch64") {
        "aarch64-unknown-linux-gnu"
    } else if target.contains("riscv64") {
        "riscv64-unknown-elf"
    } else {
        "x86_64-unknown-linux-gnu"
    }
}

fn clang_triple_for_target(target: &str) -> &str {
    llvm_triple_for_target(target)
}

fn nasm_format_for_target(target: &str) -> &str {
    if target.contains("windows") || target.contains("msvc") {
        "win64"
    } else if target.contains("darwin") || target.contains("apple") {
        "macho64"
    } else {
        "elf64"
    }
}

fn authority_tools_for_target(target: &str) -> Vec<&'static str> {
    if target.contains("riscv64") || target.contains("aarch64") {
        vec!["llvm-mc", "clang", "gas"]
    } else if target.contains("wasm32") {
        vec!["clang"]
    } else {
        vec!["llvm-mc", "clang", "nasm", "gas"]
    }
}

fn source_stem(path: &str) -> String {
    Path::new(path)
        .file_stem()
        .and_then(|name| name.to_str())
        .unwrap_or("machine")
        .to_string()
}

fn sanitize_tool_name(tool: &str) -> String {
    tool.chars()
        .map(|ch| if ch.is_ascii_alphanumeric() { ch } else { '_' })
        .collect()
}

fn target_family_key(target: &str) -> String {
    target
        .chars()
        .map(|ch| if ch.is_ascii_alphanumeric() { ch } else { '_' })
        .collect()
}

