fn vex_family_coverage_json() -> Value {
    let mut families: BTreeMap<String, (usize, usize, usize, usize)> = BTreeMap::new();
    for def in vex_instruction_defs() {
        for form in vex_operand_form_records(&def) {
            let status = vex_phase1c_form_status_json(&def, &form);
            let entry = families.entry(def.family.to_string()).or_default();
            entry.0 += 1;
            if status["encoding_status"] == "closed" {
                entry.1 += 1;
            } else if status["encoding_status"] == "deferred" {
                entry.2 += 1;
            }
            if status["verifier_status"]
                .as_str()
                .is_some_and(|value| value.starts_with("closed"))
            {
                entry.3 += 1;
            }
        }
    }
    let rows = families
        .into_iter()
        .map(|(family, (total, encoding_closed, encoding_deferred, verifier_closed))| {
            json!({
                "family": family,
                "total_forms": total,
                "encoding_closed": encoding_closed,
                "encoding_deferred": encoding_deferred,
                "verifier_closed": verifier_closed,
                "tests": if encoding_closed > 0 { "positive_and_negative_coverage" } else { "negative_or_deferred_coverage" },
                "status": if encoding_deferred == 0 { "closed" } else if encoding_closed > 0 { "partial_family_closed" } else { "deferred" }
            })
        })
        .collect::<Vec<_>>();
    json!({
        "status": "phase2_avx2_vex_family_coverage_reported",
        "phase1_vex_base_complete": "closed",
        "phase1_vex_complete": "closed",
        "phase2_avx2_complete": "closed",
        "phase2b_vex_fma_f16c": "closed",
        "counts": vex_phase1c_counts_json(),
        "families": rows
    })
}

