fn vex_phase1f_extension_owner(mnemonic: &str) -> &'static str {
    match mnemonic {
        "vpermps" | "vgatherdps" | "vpmulld" => "AVX2",
        "vfmadd132ps" => "FMA",
        "vcvtph2ps" => "F16C",
        _ => "AVX",
    }
}

fn vex_phase1f_belongs_to_phase(mnemonic: &str) -> &'static str {
    match vex_phase1f_extension_owner(mnemonic) {
        "AVX2" => "phase2",
        "FMA" | "F16C" => "phase2b",
        _ => "phase1",
    }
}

fn vex_phase1f_final_classification(mnemonic: &str) -> &'static str {
    match vex_phase1f_extension_owner(mnemonic) {
        "AVX2" => "delegated_to_phase2_avx2",
        "FMA" => "delegated_to_phase2b_fma",
        "F16C" => "delegated_to_phase2b_f16c",
        _ => "phase1_vex_base_closed",
    }
}

fn vex_phase1f_required_encoding_work(mnemonic: &str) -> &'static str {
    match vex_phase1f_extension_owner(mnemonic) {
        "AVX2" => "open Phase 2 and implement the AVX2 VEX opcode, feature gate, operand and memory semantics",
        "FMA" => "open Phase 2B and implement FMA VEX opcode, destructive-source semantics and feature gate",
        "F16C" => "open Phase 2B and implement F16C conversion opcode, memory width rules and feature gate",
        _ => "none",
    }
}

fn vex_phase1f_delegated_form_count(phase: &str) -> usize {
    vex_phase1c_status_entries()
        .iter()
        .filter(|entry| entry["encoding_status"] == "unsupported_by_design")
        .filter(|entry| {
            entry["instruction_mnemonic"]
                .as_str()
                .is_some_and(|mnemonic| vex_phase1f_belongs_to_phase(mnemonic) == phase)
        })
        .count()
}

fn vex_phase1f_resolution_entries() -> Vec<Value> {
    vex_phase1c_status_entries()
        .into_iter()
        .filter(|entry| entry["encoding_status"] == "unsupported_by_design")
        .map(|entry| {
            let mnemonic = entry["instruction_mnemonic"].as_str().unwrap_or("unknown");
            let phase = vex_phase1f_belongs_to_phase(mnemonic);
            json!({
                "form_id": entry["form_id"],
                "mnemonic": mnemonic,
                "operand_form": entry["operands"],
                "extension_owner": vex_phase1f_extension_owner(mnemonic),
                "belongs_to_phase": phase,
                "reason": "instruction belongs to a VEX extension domain outside the Phase 1 base closure",
                "can_be_closed_now": false,
                "required_encoding_work": vex_phase1f_required_encoding_work(mnemonic),
                "required_verifier_work": "enable the future phase gate and keep the current explicit rejection until that phase starts",
                "required_tests": "positive encoding tests in the future phase plus current negative diagnostic coverage",
                "final_classification": vex_phase1f_final_classification(mnemonic),
                "diagnostic_if_used_before_phase_enabled": "E_MACHINE_VEX_UNSUPPORTED_BY_DESIGN_001"
            })
        })
        .collect()
}

