fn evex_field_entries() -> Vec<Value> {
    vec![
        json!({"field": "prefix", "byte": 0, "bits": "7..0", "meaning": "EVEX marker 0x62", "allowed_values": ["0x62"], "invalid_values": ["any_other"], "diagnostic": "E_MACHINE_EVEX_FIELD_001", "tests": ["machine_evex_prefix_0x62_ok"]}),
        json!({"field": "P0.R", "byte": 1, "bits": "7", "meaning": "inverted ModRM.reg bit 3", "allowed_values": ["0", "1"], "diagnostic": "E_MACHINE_EVEX_FIELD_001", "tests": ["machine_evex_p0_fields_ok"]}),
        json!({"field": "P0.X", "byte": 1, "bits": "6", "meaning": "inverted SIB.index bit 3", "allowed_values": ["0", "1"], "diagnostic": "E_MACHINE_EVEX_FIELD_001", "tests": ["machine_evex_p0_fields_ok"]}),
        json!({"field": "P0.B", "byte": 1, "bits": "5", "meaning": "inverted ModRM.rm/base bit 3", "allowed_values": ["0", "1"], "diagnostic": "E_MACHINE_EVEX_FIELD_001", "tests": ["machine_evex_p0_fields_ok"]}),
        json!({"field": "P0.R'", "byte": 1, "bits": "4", "meaning": "inverted ModRM.reg bit 4 for xmm/ymm/zmm16..31", "allowed_values": ["0", "1"], "diagnostic": "E_MACHINE_EVEX_FIELD_001", "tests": ["machine_evex_zmm_registers_ok"]}),
        json!({"field": "P0.mm", "byte": 1, "bits": "3..0", "meaning": "opcode map", "allowed_values": ["0F", "0F38", "0F3A"], "diagnostic": "E_MACHINE_EVEX_FIELD_001", "tests": ["machine_evex_p0_fields_ok"]}),
        json!({"field": "P1.W", "byte": 2, "bits": "7", "meaning": "EVEX W field", "allowed_values": ["0", "1", "WIG"], "diagnostic": "E_MACHINE_EVEX_FIELD_001", "tests": ["machine_evex_p1_fields_ok"]}),
        json!({"field": "P1.vvvv", "byte": 2, "bits": "6..3", "meaning": "inverted first source register", "allowed_values": ["0..31 through vvvv plus V'"], "diagnostic": "E_MACHINE_EVEX_FIELD_001", "tests": ["machine_evex_p1_fields_ok"]}),
        json!({"field": "P1.pp", "byte": 2, "bits": "1..0", "meaning": "mandatory prefix selector", "allowed_values": ["none", "66", "F3", "F2"], "diagnostic": "E_MACHINE_EVEX_FIELD_001", "tests": ["machine_evex_p1_fields_ok"]}),
        json!({"field": "P2.z", "byte": 3, "bits": "7", "meaning": "zeroing mask", "allowed_values": ["0", "1 when k1-k7 present"], "diagnostic": "E_MACHINE_EVEX_ZEROING_001", "tests": ["machine_evex_zeroing_ok"]}),
        json!({"field": "P2.L'L", "byte": 3, "bits": "6..5", "meaning": "vector length 128/256/512", "allowed_values": ["00", "01", "10"], "diagnostic": "E_MACHINE_EVEX_VECTOR_LENGTH_001", "tests": ["machine_evex_vl_xmm_ok", "machine_evex_vl_ymm_ok", "machine_evex_zmm_ok"]}),
        json!({"field": "P2.b", "byte": 3, "bits": "4", "meaning": "broadcast/rounding/SAE context", "allowed_values": ["0", "1 when carrier form allows it"], "diagnostic": "E_MACHINE_EVEX_BROADCAST_001", "tests": ["machine_evex_broadcast_ok", "machine_evex_rounding_ok"]}),
        json!({"field": "P2.V'", "byte": 3, "bits": "3", "meaning": "inverted high bit for vvvv source register", "allowed_values": ["0", "1"], "diagnostic": "E_MACHINE_EVEX_FIELD_001", "tests": ["machine_evex_p2_fields_ok"]}),
        json!({"field": "P2.aaa", "byte": 3, "bits": "2..0", "meaning": "opmask k0..k7", "allowed_values": ["k0 implicit no-mask", "k1..k7 explicit"], "diagnostic": "E_MACHINE_EVEX_MASK_001", "tests": ["machine_evex_k_mask_registers_ok"]}),
    ]
}

