fn evex_byte_pattern_entries() -> Vec<Value> {
    evex_carrier_examples()
        .into_iter()
        .filter_map(|example| {
            parse_instruction(example).and_then(|inst| {
                try_encode_x86_64_instruction(&inst)
                    .ok()
                    .flatten()
                    .map(|bytes| {
                        json!({
                            "instruction": example,
                            "bytes": hex_bytes(&bytes),
                            "hash": hash_bytes(&bytes)
                        })
                    })
            })
        })
        .collect()
}

