fn avx512_instruction_defs() -> Vec<Avx512InstructionDef> {
    let avx512f = AVX512F_PHASE4B_MNEMONICS
        .iter()
        .copied()
        .map(avx512_foundation_def);
    let avx512dq = AVX512DQ_PHASE4C_MNEMONICS
        .iter()
        .copied()
        .map(avx512_foundation_def);
    let avx512bw = AVX512BW_PHASE4C_MNEMONICS
        .iter()
        .copied()
        .map(avx512_foundation_def);
    let avx512cd = AVX512CD_PHASE4D_MNEMONICS
        .iter()
        .copied()
        .map(avx512_foundation_def);
    let avx512ifma = AVX512IFMA_PHASE4D_MNEMONICS
        .iter()
        .copied()
        .map(avx512_foundation_def);
    let avx512vbmi = AVX512VBMI_PHASE4D_MNEMONICS
        .iter()
        .copied()
        .map(avx512_foundation_def);
    let avx512vnni = AVX512VNNI_PHASE4D_MNEMONICS
        .iter()
        .copied()
        .map(avx512_foundation_def);
    let avx512bitalg = AVX512BITALG_PHASE4D_MNEMONICS
        .iter()
        .copied()
        .map(avx512_foundation_def);
    let avx512vpopcntdq = AVX512VPOPCNTDQ_PHASE4D_MNEMONICS
        .iter()
        .copied()
        .map(avx512_foundation_def);
    let avx512fp16 = AVX512FP16_PHASE4D_MNEMONICS
        .iter()
        .copied()
        .map(avx512_foundation_def);
    avx512f
        .chain(avx512dq)
        .chain(avx512bw)
        .chain(avx512cd)
        .chain(avx512ifma)
        .chain(avx512vbmi)
        .chain(avx512vnni)
        .chain(avx512bitalg)
        .chain(avx512vpopcntdq)
        .chain(avx512fp16)
        .collect()
}

fn avx512_instruction_def_by_name(mnemonic: &str) -> Option<Avx512InstructionDef> {
    avx512_instruction_defs()
        .into_iter()
        .find(|def| def.mnemonic == mnemonic)
}

fn avx512_foundation_def(mnemonic: &'static str) -> Avx512InstructionDef {
    let Some(evex) = evex_instruction_def_by_name(mnemonic) else {
        return avx512_deferred_def(mnemonic, "AVX512F");
    };
    let foundation = AVX512F_FOUNDATION_CARRIERS.contains(&mnemonic);
    let owner = evex.extension_owner;
    let closure_status = avx512_closed_status_for(owner, foundation);
    Avx512InstructionDef {
        mnemonic,
        aliases: &[],
        subfeature_owner: owner,
        evex_map: evex.opcode_map,
        opcode: Some(evex.opcode),
        pp: match evex.pp {
            1 => "66",
            2 => "F3",
            3 => "F2",
            _ => "none",
        },
        w: if evex.w == 0 { "W0" } else { "W1" },
        ll_policy: if owner == "AVX512VL" {
            "xmm_128_ymm_256"
        } else {
            "zmm_512_with_vl_forms_when_avx512vl_enabled"
        },
        b_policy: evex.b_policy,
        aaa_mask_policy: evex.aaa_policy,
        z_policy: evex.z_policy,
        tuple_type: evex.tuple_type,
        operands: if matches!(
            mnemonic,
            "vmovdqa32"
                | "vmovdqu32"
                | "vexpandps"
                | "vpconflictd"
                | "vpopcntb"
                | "vpopcntd"
                | "vpopcntq"
        ) {
            &["zmm{k}{z}", "zmm/m512"]
        } else if mnemonic == "vcmpps" {
            &["k1..k7", "zmm", "zmm/m512", "imm8"]
        } else if mnemonic == "vcompressps" {
            &["zmm/m512{k}", "zmm"]
        } else if mnemonic == "vscatterdps" {
            &["dword_vsib{k}", "zmm"]
        } else if mnemonic == "vfpclassps" {
            &["k1..k7", "zmm/m512", "imm8"]
        } else if mnemonic == "vpmovdb" {
            &["xmm/m128{k}{z}", "zmm"]
        } else if mnemonic == "vpmovwb" {
            &["ymm/m256{k}{z}", "zmm"]
        } else if matches!(mnemonic, "vptestnmd" | "vpshufbitqmb") {
            &["k1..k7", "zmm", "zmm/m512"]
        } else {
            &["zmm{k}{z}", "zmm", "zmm/m512"]
        },
        operand_forms: evex.operand_forms,
        register_classes: if owner == "AVX512VL" {
            &["xmm0..xmm31", "ymm0..ymm31", "k1..k7"]
        } else {
            &[
                "zmm0..zmm31",
                "xmm0..xmm31 when AVX512VL",
                "ymm0..ymm31 when AVX512VL",
                "k1..k7",
            ]
        },
        memory_width: if mnemonic == "vscatterdps" {
            "dword_vsib"
        } else if mnemonic == "vpmovdb" {
            "m128_narrow_destination_or_zmm_source"
        } else if mnemonic == "vpmovwb" {
            "m256_narrow_destination_or_zmm_source"
        } else if evex.tuple_type == "full_or_m64bcst" {
            "m512_or_m64bcst_when_valid"
        } else {
            "m512_or_m32bcst_when_valid"
        },
        immediate_width: if matches!(mnemonic, "vcmpps" | "vfpclassps") {
            "imm8"
        } else {
            "none"
        },
        feature_gates: avx512_feature_gate_slice(owner),
        encoding_status: closure_status,
        verifier_status: closure_status,
        tests_status: "positive_and_negative",
        docs_status: "present",
        final_status: avx512_final_status_for(owner, foundation),
        foundation_carrier: foundation,
    }
}

fn avx512_closed_status_for(owner: &str, foundation: bool) -> &'static str {
    match owner {
        "AVX512F" if foundation => "closed_phase4a_foundation",
        "AVX512F" => "closed_phase4b_avx512f",
        "AVX512DQ" => "closed_phase4c_avx512dq",
        "AVX512BW" => "closed_phase4c_avx512bw",
        "AVX512VL" => "closed_phase4c_avx512vl",
        "AVX512CD" => "closed_phase4d_avx512cd",
        "AVX512IFMA" => "closed_phase4d_avx512ifma",
        "AVX512VBMI" => "closed_phase4d_avx512vbmi",
        "AVX512VNNI" => "closed_phase4d_avx512vnni",
        "AVX512BITALG" => "closed_phase4d_avx512bitalg",
        "AVX512VPOPCNTDQ" => "closed_phase4d_avx512vpopcntdq",
        "AVX512FP16" => "closed_phase4d_avx512fp16",
        _ => "closed_phase4d",
    }
}

fn avx512_final_status_for(owner: &str, foundation: bool) -> &'static str {
    match owner {
        "AVX512F" if foundation => "closed_as_avx512f_foundation",
        "AVX512F" => "closed_as_avx512f_phase4b",
        "AVX512DQ" => "closed_as_avx512dq_phase4c",
        "AVX512BW" => "closed_as_avx512bw_phase4c",
        "AVX512VL" => "closed_as_avx512vl_phase4c",
        "AVX512CD" => "closed_as_avx512cd_phase4d",
        "AVX512IFMA" => "closed_as_avx512ifma_phase4d",
        "AVX512VBMI" => "closed_as_avx512vbmi_phase4d",
        "AVX512VNNI" => "closed_as_avx512vnni_phase4d",
        "AVX512BITALG" => "closed_as_avx512bitalg_phase4d",
        "AVX512VPOPCNTDQ" => "closed_as_avx512vpopcntdq_phase4d",
        "AVX512FP16" => "closed_as_avx512fp16_phase4d",
        _ => "closed_as_phase4d",
    }
}

fn avx512_deferred_def(
    mnemonic: &'static str,
    subfeature_owner: &'static str,
) -> Avx512InstructionDef {
    Avx512InstructionDef {
        mnemonic,
        aliases: &[],
        subfeature_owner,
        evex_map: "deferred",
        opcode: None,
        pp: "deferred",
        w: "deferred",
        ll_policy: "deferred_to_later_phase",
        b_policy: "deferred_to_later_phase",
        aaa_mask_policy: "deferred_to_later_phase",
        z_policy: "deferred_to_later_phase",
        tuple_type: "deferred_to_later_phase",
        operands: &["deferred_to_later_phase"],
        operand_forms: &["deferred_to_later_phase"],
        register_classes: &["xmm", "ymm", "zmm", "k"],
        memory_width: "deferred_to_later_phase",
        immediate_width: "deferred_to_later_phase",
        feature_gates: avx512_feature_gate_slice(subfeature_owner),
        encoding_status: "deferred_to_phase4b_or_later",
        verifier_status: "deferred_to_phase4b_or_later",
        tests_status: "manifest_gate_only",
        docs_status: "listed",
        final_status: "deferred",
        foundation_carrier: false,
    }
}

fn avx512_feature_gate_slice(subfeature_owner: &str) -> &'static [&'static str] {
    match subfeature_owner {
        "AVX512DQ" => &["AVX512DQ"],
        "AVX512BW" => &["AVX512BW"],
        "AVX512VL" => &["AVX512VL"],
        "AVX512CD" => &["AVX512CD"],
        "AVX512IFMA" => &["AVX512IFMA"],
        "AVX512VBMI" => &["AVX512VBMI"],
        "AVX512VNNI" => &["AVX512VNNI"],
        "AVX512BITALG" => &["AVX512BITALG"],
        "AVX512VPOPCNTDQ" => &["AVX512VPOPCNTDQ"],
        "AVX512FP16" => &["AVX512FP16"],
        _ => &["AVX512F"],
    }
}

fn avx512_instruction_entry(def: Avx512InstructionDef) -> Value {
    json!({
        "mnemonic": def.mnemonic,
        "aliases": def.aliases,
        "subfeature_owner": def.subfeature_owner,
        "EVEX_map": def.evex_map,
        "opcode": def.opcode.map(|opcode| format!("{:02x}", opcode)).unwrap_or_else(|| "deferred".to_string()),
        "pp": def.pp,
        "W": def.w,
        "L'L": def.ll_policy,
        "b_policy": def.b_policy,
        "aaa_mask_policy": def.aaa_mask_policy,
        "z_policy": def.z_policy,
        "tuple_type": def.tuple_type,
        "operands": def.operands,
        "operand_forms": def.operand_forms,
        "register_classes": def.register_classes,
        "memory_width": def.memory_width,
        "immediate_width": def.immediate_width,
        "feature_gates": def.feature_gates,
        "encoding_status": def.encoding_status,
        "verifier_status": def.verifier_status,
        "tests_status": def.tests_status,
        "docs_status": def.docs_status,
        "final_status": def.final_status,
        "foundation_carrier": def.foundation_carrier
    })
}

fn avx512_instruction_entries() -> Vec<Value> {
    avx512_instruction_defs()
        .into_iter()
        .map(avx512_instruction_entry)
        .collect()
}

fn avx512_feature_gates() -> Vec<Avx512FeatureGate> {
    AVX512_SUBFEATURES
        .iter()
        .copied()
        .map(|subfeature| Avx512FeatureGate {
            subfeature,
            status: match subfeature {
                "AVX512F" => "phase4b_closed",
                "AVX512DQ" | "AVX512BW" | "AVX512VL" => "phase4c_closed",
                "AVX512CD" | "AVX512IFMA" | "AVX512VBMI" | "AVX512VNNI" | "AVX512BITALG"
                | "AVX512VPOPCNTDQ" | "AVX512FP16" => "phase4d_closed",
                _ => "deferred_to_later_phase",
            },
            diagnostic_if_missing: avx512_subfeature_required_diagnostic(subfeature),
            phase_owner: match subfeature {
                "AVX512F" => "phase4b",
                "AVX512DQ" | "AVX512BW" | "AVX512VL" => "phase4c",
                "AVX512CD" | "AVX512IFMA" | "AVX512VBMI" | "AVX512VNNI" | "AVX512BITALG"
                | "AVX512VPOPCNTDQ" => "phase4d",
                "AVX512FP16" => "phase4d",
                _ => "phase4_later",
            },
        })
        .collect()
}

fn avx512_subfeature_required_diagnostic(subfeature: &str) -> &'static str {
    match subfeature {
        "AVX512DQ" => "E_MACHINE_AVX512_DQ_REQUIRED_001",
        "AVX512BW" => "E_MACHINE_AVX512_BW_REQUIRED_001",
        "AVX512VL" => "E_MACHINE_AVX512_VL_REQUIRED_001",
        "AVX512CD" => "E_MACHINE_AVX512_CD_REQUIRED_001",
        "AVX512IFMA" => "E_MACHINE_AVX512_IFMA_REQUIRED_001",
        "AVX512VBMI" => "E_MACHINE_AVX512_VBMI_REQUIRED_001",
        "AVX512VNNI" => "E_MACHINE_AVX512_VNNI_REQUIRED_001",
        "AVX512BITALG" => "E_MACHINE_AVX512_BITALG_REQUIRED_001",
        "AVX512VPOPCNTDQ" => "E_MACHINE_AVX512_VPOPCNTDQ_REQUIRED_001",
        "AVX512FP16" => "E_MACHINE_AVX512_FP16_REQUIRED_001",
        _ => "E_MACHINE_AVX512_FEATURE_REQUIRED_001",
    }
}

