fn avx512_byte_pattern_entries() -> Vec<Value> {
    avx512_phase4b_examples()
        .into_iter()
        .chain(avx512_phase4c_examples())
        .chain(avx512_phase4d_examples())
        .filter_map(|example| {
            let mnemonic = example.split_whitespace().next()?;
            parse_instruction(example).and_then(|inst| {
                try_encode_x86_64_instruction(&inst)
                    .ok()
                    .flatten()
                    .map(|bytes| {
                        json!({
                            "instruction": example,
                            "bytes": hex_bytes(&bytes),
                            "hash": hash_bytes(&bytes),
                            "status": avx512_byte_pattern_status(example, mnemonic)
                        })
                    })
            })
        })
        .collect()
}

fn avx512_byte_pattern_status(example: &str, mnemonic: &str) -> &'static str {
    if !matches!(mnemonic, "vpmovdb" | "vpmovwb")
        && (example.contains("xmm") || example.contains("ymm"))
    {
        return "closed_phase4c_avx512vl";
    }
    if AVX512F_FOUNDATION_CARRIERS.contains(&mnemonic) {
        "closed_phase4a_foundation"
    } else if AVX512F_PHASE4B_MNEMONICS.contains(&mnemonic) {
        "closed_phase4b_avx512f"
    } else if AVX512DQ_PHASE4C_MNEMONICS.contains(&mnemonic) {
        "closed_phase4c_avx512dq"
    } else if AVX512BW_PHASE4C_MNEMONICS.contains(&mnemonic) {
        "closed_phase4c_avx512bw"
    } else if AVX512CD_PHASE4D_MNEMONICS.contains(&mnemonic) {
        "closed_phase4d_avx512cd"
    } else if AVX512IFMA_PHASE4D_MNEMONICS.contains(&mnemonic) {
        "closed_phase4d_avx512ifma"
    } else if AVX512VBMI_PHASE4D_MNEMONICS.contains(&mnemonic) {
        "closed_phase4d_avx512vbmi"
    } else if AVX512VNNI_PHASE4D_MNEMONICS.contains(&mnemonic) {
        "closed_phase4d_avx512vnni"
    } else if AVX512BITALG_PHASE4D_MNEMONICS.contains(&mnemonic) {
        "closed_phase4d_avx512bitalg"
    } else if AVX512VPOPCNTDQ_PHASE4D_MNEMONICS.contains(&mnemonic) {
        "closed_phase4d_avx512vpopcntdq"
    } else if AVX512FP16_PHASE4D_MNEMONICS.contains(&mnemonic) {
        "closed_phase4d_avx512fp16"
    } else {
        "closed_phase4d"
    }
}

fn avx512_encoding_patterns() -> Vec<Avx512EncodingPattern> {
    avx512_byte_pattern_entries()
        .into_iter()
        .filter_map(|entry| {
            let instruction = entry.get("instruction")?.as_str()?;
            let mnemonic = instruction.split_whitespace().next()?;
            let def = avx512_instruction_def_by_name(mnemonic)?;
            Some(Avx512EncodingPattern {
                mnemonic: def.mnemonic,
                evex_map: def.evex_map,
                opcode: "see_byte_pattern",
                pp: def.pp,
                w: def.w,
                ll: "512",
                tuple_type: def.tuple_type,
                expected_bytes: &["recorded_in_byte_pattern_manifest"],
                evidence_hash: "recorded_per_form",
                status: avx512_byte_pattern_status(instruction, def.mnemonic),
            })
        })
        .collect()
}

fn avx512_encoding_pattern_entries() -> Vec<Value> {
    avx512_encoding_patterns()
        .into_iter()
        .map(|pattern| {
            json!({
                "mnemonic": pattern.mnemonic,
                "EVEX_map": pattern.evex_map,
                "opcode": pattern.opcode,
                "pp": pattern.pp,
                "W": pattern.w,
                "LL": pattern.ll,
                "tuple_type": pattern.tuple_type,
                "expected_bytes": pattern.expected_bytes,
                "evidence_hash": pattern.evidence_hash,
                "status": pattern.status
            })
        })
        .collect()
}

