fn avx512_final_manifest_entries() -> Vec<Value> {
    let patterns = avx512_byte_pattern_entries();
    avx512_instruction_defs()
        .into_iter()
        .map(|def| {
            let mnemonic = def.mnemonic;
            let mut entry = avx512_instruction_entry(def);
            let pattern = patterns.iter().find(|pattern| {
                pattern
                    .get("instruction")
                    .and_then(Value::as_str)
                    .and_then(|instruction| instruction.split_whitespace().next())
                    .map(|pattern_mnemonic| pattern_mnemonic == mnemonic)
                    .unwrap_or(false)
            });
            if let Some(object) = entry.as_object_mut() {
                object.insert("dependency".to_string(), json!("EVEX"));
                object.insert(
                    "byte_pattern_hash".to_string(),
                    pattern
                        .and_then(|pattern| pattern.get("hash"))
                        .cloned()
                        .unwrap_or_else(|| json!("missing")),
                );
                object.insert(
                    "byte_pattern_instruction".to_string(),
                    pattern
                        .and_then(|pattern| pattern.get("instruction"))
                        .cloned()
                        .unwrap_or_else(|| json!("missing")),
                );
                object.insert(
                    "positive_tests".to_string(),
                    json!(AVX512_POSITIVE_EXAMPLES),
                );
                object.insert(
                    "negative_tests".to_string(),
                    json!(AVX512_NEGATIVE_EXAMPLES),
                );
                object.insert(
                    "docs".to_string(),
                    json!("docs/spec/machine/machine_avx512_final_closure.md"),
                );
            }
            entry
        })
        .collect()
}

