fn avx512_subfeature_counts(subfeature: &str) -> (usize, usize) {
    let defs = avx512_instruction_defs();
    let total = defs
        .iter()
        .filter(|def| def.subfeature_owner == subfeature)
        .count();
    let closed = defs
        .iter()
        .filter(|def| def.subfeature_owner == subfeature && def.final_status.starts_with("closed"))
        .count();
    (total, closed)
}

fn avx512_closed_defs() -> Vec<Avx512InstructionDef> {
    avx512_instruction_defs()
        .into_iter()
        .filter(|def| def.final_status.starts_with("closed"))
        .collect()
}

