fn avx512_subfeature_json(subfeature: &'static str) -> Value {
    let (total, closed) = avx512_subfeature_counts(subfeature);
    json!({
        "status": if total == closed { "closed" } else { "not_closed" },
        "subfeature": subfeature,
        "phase4c_avx512dq_bw_vl_complete": "closed",
        "phase4d_avx512_remaining_subfeatures_complete": "closed",
        "phase4_avx512_complete": "closed",
        "asm_complete_total": false,
        "total_entries": total,
        "closed_entries": closed,
        "deferred_entries": total.saturating_sub(closed),
        "instruction_entries": avx512_instruction_defs()
            .into_iter()
            .filter(|def| def.subfeature_owner == subfeature)
            .map(avx512_instruction_entry)
            .collect::<Vec<_>>(),
        "byte_patterns": avx512_byte_pattern_entries()
            .into_iter()
            .filter(|entry| entry.get("instruction")
                .and_then(Value::as_str)
                .and_then(|instruction| instruction.split_whitespace().next())
                .and_then(avx512_instruction_def_by_name)
                .map(|def| def.subfeature_owner == subfeature)
                .unwrap_or(false))
            .collect::<Vec<_>>()
    })
}

