fn avx512_family_coverage_json() -> Value {
    let mut by_feature: BTreeMap<&'static str, (usize, usize)> = BTreeMap::new();
    for def in avx512_instruction_defs() {
        let entry = by_feature.entry(def.subfeature_owner).or_insert((0, 0));
        entry.0 += 1;
        if def.final_status.starts_with("closed") {
            entry.1 += 1;
        }
    }
    json!({
        "status": "phase4d_family_coverage_reported",
        "families": by_feature.into_iter().map(|(feature, (total, closed))| json!({
            "subfeature": feature,
            "total_entries": total,
            "closed_entries": closed,
            "deferred_entries": total.saturating_sub(closed),
            "status": if total == closed { "closed" } else { "deferred_to_later_phase" }
        })).collect::<Vec<_>>()
    })
}

