fn audit_to_json(audit: &MachineAudit) -> Value {
    json!({
        "path": audit.path,
        "file_classification": ".nm machine source",
        "container": audit.container,
        "target": audit.target,
        "sections": audit.sections.iter().cloned().collect::<Vec<_>>(),
        "symbols": audit.symbols.iter().cloned().collect::<Vec<_>>(),
        "externs": audit.externs.iter().cloned().collect::<Vec<_>>(),
        "exports": audit.exports.iter().cloned().collect::<Vec<_>>(),
        "labels": audit.labels.iter().cloned().collect::<Vec<_>>(),
        "routines": audit.routines.iter().cloned().collect::<Vec<_>>(),
        "entry": audit.entry,
        "instructions": audit.instructions.iter().map(instruction_to_json).collect::<Vec<_>>(),
        "relocations": audit.relocations,
        "phase10_macro_directive_system": {
            "macros": phase10_macros_json(audit),
            "macro_invocations": phase10_macro_invocations_json(audit),
            "macro_expansions": phase10_macro_expansions_json(audit),
            "directives": phase10_directives_json(audit),
            "conditionals": phase10_conditionals_json(audit),
            "repeats": phase10_repeats_json(audit),
            "includes": phase10_includes_json(audit),
            "incbins": phase10_incbins_json(audit),
            "constants": audit.constants.clone(),
            "data_bytes": audit.data_bytes.len(),
            "data_hash": hash_bytes(&audit.data_bytes),
            "bss_size": audit.bss_size
        },
        "diagnostics": diagnostics_to_json(&audit.diagnostics),
        "deferred": audit.deferred,
        "encoded_bytes": audit.encoded_bytes.len(),
        "encoded_hash": hash_bytes(&audit.encoded_bytes),
        "status": audit.status,
        "conformance_level": audit.conformance_level,
        "fn_fa_forbidden": true
    })
}

fn audit_to_markdown(audit: &MachineAudit) -> String {
    let mut out = String::new();
    out.push_str("# Machine Report\n\n");
    out.push_str(&format!("- Source: `{}`\n", audit.path));
    out.push_str(&format!("- Status: `{}`\n", audit.status));
    out.push_str(&format!("- Conformance: `{}`\n", audit.conformance_level));
    out.push_str(&format!(
        "- Container: `{}`\n",
        audit.container.as_deref().unwrap_or("<missing>")
    ));
    out.push_str(&format!(
        "- Encoded bytes: `{}`\n",
        audit.encoded_bytes.len()
    ));
    out.push_str(&format!(
        "- Encoded hash: `{}`\n\n",
        hash_bytes(&audit.encoded_bytes)
    ));
    out.push_str("## Instructions\n\n");
    for inst in &audit.instructions {
        out.push_str(&format!("- `{}`\n", inst.text));
    }
    out.push_str("\n## Diagnostics\n\n");
    if audit.diagnostics.is_empty() {
        out.push_str("- none\n");
    } else {
        for diag in &audit.diagnostics {
            out.push_str(&format!("- `{}`: {}\n", diag.code, diag.message));
        }
    }
    out
}

fn diagnostics_to_json(diagnostics: &[MachineDiagnostic]) -> Value {
    Value::Array(
        diagnostics
            .iter()
            .map(|diag| crate::canonical_diagnostic_to_json(diag.canonical()))
            .collect(),
    )
}

