fn has_flag(args: &[String], flag: &str) -> bool {
    args.iter().any(|arg| arg == flag)
}

fn first_non_flag(args: &[String]) -> Option<&str> {
    args.iter()
        .find(|arg| !arg.starts_with("--"))
        .map(String::as_str)
}

fn option_value<'a>(args: &'a [String], flag: &str) -> Option<&'a str> {
    args.windows(2)
        .find_map(|pair| (pair[0] == flag).then(|| pair[1].as_str()))
}

fn file_extension(path: &str) -> String {
    Path::new(path)
        .extension()
        .and_then(|ext| ext.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase()
}

fn strip_comment(line: &str) -> &str {
    line.split_once("//")
        .map(|(prefix, _)| prefix)
        .unwrap_or(line)
}

fn write_output(path: &str, bytes: &[u8]) -> Result<(), Box<dyn Error>> {
    if let Some(parent) = Path::new(path).parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent)?;
        }
    }
    fs::write(path, bytes)?;
    Ok(())
}

fn append_wasm_debug_sections(out: &mut Vec<u8>, audit: &MachineAudit) {
    let wasm_name = MachineWasmNameSection {
        function_name: audit.entry.clone().unwrap_or_else(|| "main".to_string()),
    };
    let mut name_payload = Vec::new();
    push_wasm_name(&mut name_payload, "name");
    let mut func_names = Vec::new();
    func_names.push(0x01);
    func_names.push(0x00);
    push_wasm_name(&mut func_names, &wasm_name.function_name);
    name_payload.push(0x01);
    push_leb_u32(&mut name_payload, func_names.len() as u32);
    name_payload.extend(func_names);
    push_wasm_section(out, 0, &name_payload);

    let mut nc_debug = Vec::new();
    push_wasm_name(&mut nc_debug, "nC.debug");
    nc_debug.extend_from_slice(b"producer=ncc;language=nC.machine;file=");
    nc_debug.extend_from_slice(
        audit
            .debug
            .get("file")
            .map(String::as_bytes)
            .unwrap_or_else(|| audit.path.as_bytes()),
    );
    push_wasm_section(out, 0, &nc_debug);
}

fn push_wasm_name(out: &mut Vec<u8>, name: &str) {
    push_leb_u32(out, name.len() as u32);
    out.extend_from_slice(name.as_bytes());
}

fn push_wasm_section(out: &mut Vec<u8>, id: u8, payload: &[u8]) {
    out.push(id);
    push_leb_u32(out, payload.len() as u32);
    out.extend_from_slice(payload);
}

fn push_leb_u32(out: &mut Vec<u8>, mut value: u32) {
    loop {
        let mut byte = (value & 0x7f) as u8;
        value >>= 7;
        if value != 0 {
            byte |= 0x80;
        }
        out.push(byte);
        if value == 0 {
            break;
        }
    }
}

fn push_leb_i32(out: &mut Vec<u8>, value: i32) {
    push_sleb_i32(out, value);
}

fn push_leb_i64(out: &mut Vec<u8>, mut value: i64) {
    loop {
        let byte = (value as u8) & 0x7f;
        value >>= 7;
        let done = (value == 0 && (byte & 0x40) == 0) || (value == -1 && (byte & 0x40) != 0);
        out.push(if done { byte } else { byte | 0x80 });
        if done {
            break;
        }
    }
}

fn push_sleb_i32(out: &mut Vec<u8>, mut value: i32) {
    loop {
        let byte = (value as u8) & 0x7f;
        value >>= 7;
        let done = (value == 0 && (byte & 0x40) == 0) || (value == -1 && (byte & 0x40) != 0);
        out.push(if done { byte } else { byte | 0x80 });
        if done {
            break;
        }
    }
}

fn align_to(value: usize, align: usize) -> usize {
    if align == 0 {
        value
    } else {
        value.div_ceil(align) * align
    }
}

fn write_u16(bytes: &mut [u8], offset: usize, value: u16) {
    bytes[offset..offset + 2].copy_from_slice(&value.to_le_bytes());
}

fn write_u32(bytes: &mut [u8], offset: usize, value: u32) {
    bytes[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
}

fn write_u64(bytes: &mut [u8], offset: usize, value: u64) {
    bytes[offset..offset + 8].copy_from_slice(&value.to_le_bytes());
}

fn hash_bytes(bytes: &[u8]) -> String {
    let digest = Sha256::digest(bytes);
    digest.iter().map(|b| format!("{:02x}", b)).collect()
}

fn hex_bytes(bytes: &[u8]) -> String {
    bytes
        .iter()
        .map(|byte| format!("{:02x}", byte))
        .collect::<Vec<_>>()
        .join(" ")
}

fn phase12_hex_compact(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{:02x}", byte)).collect()
}

fn phase12_hex_decode(text: &str) -> Result<Vec<u8>, Box<dyn Error>> {
    let text = text.trim();
    if !text.len().is_multiple_of(2) {
        return Err("[E_MACHINE_LINK_METADATA_001] hex byte string has odd length".into());
    }
    let mut out = Vec::with_capacity(text.len() / 2);
    for index in (0..text.len()).step_by(2) {
        out.push(u8::from_str_radix(&text[index..index + 2], 16)?);
    }
    Ok(out)
}

fn print_json(value: &Value) -> Result<(), Box<dyn Error>> {
    println!("{}", serde_json::to_string_pretty(value)?);
    Ok(())
}

