    #[test]
    fn coff_amd64_addr32_and_rel32_variants_are_classified() {
        assert_eq!(phase12_coff_relocation_kind("x86_64", 0x0000), Some("none"));
        assert_eq!(
            phase12_coff_relocation_kind("x86_64", 0x0002),
            Some("coff-addr32")
        );
        assert_eq!(
            phase12_coff_relocation_kind("x86_64", 0x0003),
            Some("coff-addr32nb")
        );
        for relocation_type in 0x0005..=0x0009 {
            assert_eq!(
                phase12_coff_relocation_kind("x86_64", relocation_type),
                Some("pc32")
            );
        }
    }

    #[test]
    fn pe_addr32_uses_low_va_and_emits_highlow_base_relocation() {
        assert_eq!(
            phase12_coff_addr32_value(0x0000_0001_4001_3000, 0)
                .expect("PE32+ ADDR32 must retain the low VA bits"),
            0x4001_3000
        );
        assert!(phase12_coff_addr32_value(0, -1).is_err());

        let bytes = phase12_pe_base_relocation_bytes(
            &[
                (0x1234, PE_BASE_RELOCATION_HIGHLOW),
                (0x1abc, PE_BASE_RELOCATION_DIR64),
            ],
            0x1000,
        );
        assert_eq!(read_u32(&bytes, 0), 0x1000);
        assert_eq!(read_u32(&bytes, 4), 12);
        assert_eq!(read_u16(&bytes, 8), 0x3234);
        assert_eq!(read_u16(&bytes, 10), 0xaabc);
    }

    #[test]
    fn coff_duplicate_rdata_contributions_keep_symbol_and_relocation_identity() {
        const HEADER_SIZE: usize = 20;
        const SECTION_COUNT: usize = 3;
        const SECTION_HEADERS_SIZE: usize = SECTION_COUNT * 40;
        const TEXT_RAW: usize = HEADER_SIZE + SECTION_HEADERS_SIZE;
        const RDATA_A_RAW: usize = TEXT_RAW + 4;
        const RDATA_B_RAW: usize = RDATA_A_RAW + 8;
        const TEXT_RELOC: usize = RDATA_B_RAW + 16;
        const RDATA_B_RELOC: usize = TEXT_RELOC + 10;
        const SYMBOL_TABLE: usize = RDATA_B_RELOC + 10;
        const SYMBOL_COUNT: usize = 3;

        let mut object = vec![0_u8; SYMBOL_TABLE + SYMBOL_COUNT * 18 + 4];
        write_u16(&mut object, 0, 0x8664); // IMAGE_FILE_MACHINE_AMD64
        write_u16(&mut object, 2, SECTION_COUNT as u16);
        write_u32(&mut object, 8, SYMBOL_TABLE as u32);
        write_u32(&mut object, 12, SYMBOL_COUNT as u32);

        let write_section = |object: &mut [u8],
                             index: usize,
                             name: &[u8],
                             size: usize,
                             raw: usize,
                             reloc: usize,
                             reloc_count: u16,
                             characteristics: u32| {
            let offset = HEADER_SIZE + index * 40;
            object[offset..offset + name.len()].copy_from_slice(name);
            write_u32(object, offset + 16, size as u32);
            write_u32(object, offset + 20, raw as u32);
            write_u32(object, offset + 24, reloc as u32);
            write_u16(object, offset + 32, reloc_count);
            write_u32(object, offset + 36, characteristics);
        };
        write_section(
            &mut object,
            0,
            b".text",
            4,
            TEXT_RAW,
            TEXT_RELOC,
            1,
            0x6030_0020,
        );
        write_section(&mut object, 1, b".rdata", 8, RDATA_A_RAW, 0, 0, 0x4040_0040);
        write_section(
            &mut object,
            2,
            b".rdata",
            16,
            RDATA_B_RAW,
            RDATA_B_RELOC,
            1,
            0x4040_0040,
        );
        object[RDATA_A_RAW..RDATA_A_RAW + 8].fill(0xa5);
        object[RDATA_B_RAW..RDATA_B_RAW + 8].copy_from_slice(&5_u64.to_le_bytes());

        // REL32 in .text -> the second `.rdata` section symbol.
        write_u32(&mut object, TEXT_RELOC + 4, 2);
        write_u16(&mut object, TEXT_RELOC + 8, 0x0004);
        // ADDR64 in the second `.rdata` contribution -> that same symbol.
        write_u32(&mut object, RDATA_B_RELOC + 4, 2);
        write_u16(&mut object, RDATA_B_RELOC + 8, 0x0001);

        let write_symbol = |object: &mut [u8],
                            index: usize,
                            name: &[u8],
                            value: u32,
                            section: u16,
                            storage_class: u8| {
            let offset = SYMBOL_TABLE + index * 18;
            object[offset..offset + name.len()].copy_from_slice(name);
            write_u32(object, offset + 8, value);
            write_u16(object, offset + 12, section);
            object[offset + 16] = storage_class;
        };
        write_symbol(&mut object, 0, b"main", 0, 1, 2);
        write_symbol(&mut object, 1, b".rdata", 0, 2, 3);
        write_symbol(&mut object, 2, b".rdata", 3, 3, 3);
        write_u32(&mut object, SYMBOL_TABLE + SYMBOL_COUNT * 18, 4);

        let native = phase12_coff_native_object_unit("duplicate-rdata.obj", &object)
            .expect("synthetic COFF must import");
        let mut rdata_symbols = native
            .unit
            .symbols
            .iter()
            .filter(|symbol| symbol.section == ".rodata")
            .collect::<Vec<_>>();
        rdata_symbols.sort_by_key(|symbol| symbol.offset);
        assert_eq!(
            rdata_symbols
                .iter()
                .map(|symbol| symbol.offset)
                .collect::<Vec<_>>(),
            vec![0, 11],
            "the second section contribution base (8) must precede symbol.value (3)"
        );
        assert_ne!(rdata_symbols[0].name, rdata_symbols[1].name);
        assert_eq!(native.unit.relocations[0].symbol, rdata_symbols[1].name);
        assert_eq!(native.unit.relocations[1].symbol, rdata_symbols[1].name);
        assert_eq!(native.unit.relocations[1].offset, 8);

        let image = phase12_link_image(&[Phase12LinkInput {
            path: "duplicate-rdata.obj".into(),
            source: None,
            object_format: "coff".into(),
            link_unit_origin: "native_object".into(),
            bytes: object,
            hash: "synthetic".into(),
            dynamic_imports: native.dynamic_imports,
            unit: Some(native.unit),
        }])
        .expect("synthetic COFF must link");
        let text_va = 0x0000_0001_4000_1000_u64;
        let rodata_va = 0x0000_0001_4000_2000_u64;
        let symbol_vas = image
            .symbols
            .iter()
            .map(|(name, symbol)| {
                let base = match symbol.section.as_str() {
                    "text" => text_va,
                    "rodata" => rodata_va,
                    other => panic!("unexpected synthetic section {other}"),
                };
                (name.clone(), base + symbol.offset as u64)
            })
            .collect::<BTreeMap<_, _>>();
        let target = symbol_vas[&image.relocations[0].symbol];
        assert_eq!(target, rodata_va + 11);

        let mut text = image.text.clone();
        let mut rodata = image.rodata.clone();
        let mut data = image.data.clone();
        phase12_apply_linked_relocations(
            &mut text,
            &mut rodata,
            &mut data,
            &image,
            text_va,
            Some(rodata_va),
            None,
            None,
            &symbol_vas,
            &HashMap::new(),
            &HashMap::new(),
        )
        .expect("REL32 and ADDR64 must apply");
        assert_eq!(
            read_u32(&text, 0) as i32 as i64,
            (target as i128 - 4 - text_va as i128) as i64
        );
        assert_eq!(&rodata[..8], &[0xa5; 8]);
        assert_eq!(read_u64(&rodata, 8), target + 5);
    }

    #[test]
    fn i386_plt_pushes_elf32_rel_byte_offsets() {
        let plt = phase12_elf32_plt_bytes(3, 0x0804_9000, 0x0804_a000).expect("i386 PLT bytes");
        assert_eq!(read_u32(&plt, 16 + 7), 0);
        assert_eq!(read_u32(&plt, 32 + 7), 8);
        assert_eq!(read_u32(&plt, 48 + 7), 16);

        let rel = phase12_elf32_rel_plt_bytes(
            &["malloc".into(), "exit".into()],
            0x0804_a000,
            "i386-unknown-linux-gnu",
        )
        .expect("i386 REL PLT bytes");
        assert_eq!(read_u32(&rel, 4) & 0xff, 7);
        assert_eq!(read_u32(&rel, 12) & 0xff, 7);
    }

    #[test]
    fn i386_linux_entry_wrapper_calls_main_and_exits_without_ret() {
        assert_eq!(
            phase12_elf32_entry_wrapper_len("i386", "i386-unknown-linux-gnu"),
            Some(33)
        );
        assert_eq!(
            phase12_elf32_entry_wrapper_len("riscv32", "riscv32imac-unknown-elf"),
            phase12_riscv_qemu_entry_wrapper_bytes(32, 0, 0, 0, 0, 0, 0)
                .ok()
                .map(|bytes| bytes.len())
        );
        let wrapper = phase12_elf32_entry_wrapper_bytes("i386", 0x0804_9000, 0x0804_8800)
            .expect("i386 entry wrapper");
        assert_eq!(wrapper.len(), 33);
        assert_eq!(
            &wrapper[..14],
            &[0x8b, 0x04, 0x24, 0x8d, 0x5c, 0x24, 0x04, 0x8d, 0x4c, 0x83, 0x04, 0x51, 0x53, 0x50]
        );
        assert_eq!(wrapper[14], 0xe8);
        assert_eq!(&wrapper[19..25], &[0x83, 0xc4, 0x0c, 0x89, 0xc3, 0xb8]);
        assert_eq!(&wrapper[31..], &[0x0f, 0x0b]);
    }

    #[test]
    fn qemu_virt_entry_conditionals_use_c_main_zero_success_contract() {
        let cbnz = phase12_aarch64_compare_branch_word(0xb500_0000, 0, 0x1000, 0x1040)
            .expect("AArch64 CBNZ");
        assert_eq!(cbnz, 0xb500_0200);
        assert_eq!(
            (cbnz >> 24) & 1,
            1,
            "CBNZ must branch only on non-zero status"
        );

        let bne = phase12_riscv_branch_word(10, 0, 1, 8).expect("RISC-V BNE");
        assert_eq!(
            (bne >> 12) & 0x7,
            1,
            "BNE must reject non-zero C main status"
        );
        assert_eq!(bne & 0x7f, 0x63);

        assert!(phase12_elf64_entry_wrapper_len("aarch64", "aarch64-unknown-none").is_some());
        assert!(phase12_elf64_entry_wrapper_len("riscv64", "riscv64-unknown-elf").is_some());
        assert!(phase12_elf32_entry_wrapper_len("riscv32", "riscv32imac-unknown-elf").is_some());
    }

    #[test]
    fn pe_runtime_os_media_imports_lower_to_real_winapi_symbols() {
        let imports = phase12_pe_loader_import_symbols(&[
            "openUri".to_string(),
            "mediaNext".to_string(),
            "mediaPlay".to_string(),
            "mediaPause".to_string(),
            "mediaPrevious".to_string(),
            "sleep".to_string(),
            "printf".to_string(),
            "fflush".to_string(),
            "GetCommandLineW".to_string(),
            "CommandLineToArgvW".to_string(),
            "WideCharToMultiByte".to_string(),
            "LocalFree".to_string(),
        ]);

        assert!(imports.contains(&"ShellExecuteA".to_string()));
        assert!(imports.contains(&"keybd_event".to_string()));
        assert!(imports.contains(&"Sleep".to_string()));
        assert!(imports.contains(&"GetStdHandle".to_string()));
        assert!(imports.contains(&"WriteFile".to_string()));
        assert!(imports.contains(&"GetCommandLineW".to_string()));
        assert!(imports.contains(&"CommandLineToArgvW".to_string()));
        assert!(imports.contains(&"WideCharToMultiByte".to_string()));
        assert!(imports.contains(&"LocalFree".to_string()));
        for leaked in [
            "openUri",
            "mediaNext",
            "mediaPlay",
            "mediaPause",
            "mediaPrevious",
            "sleep",
            "printf",
            "fflush",
        ] {
            assert!(
                !imports.contains(&leaked.to_string()),
                "{leaked} must be an internal PE thunk, not a loader import"
            );
        }
        assert_eq!(phase12_pe_import_dll("ShellExecuteA"), "SHELL32.dll");
        assert_eq!(phase12_pe_import_dll("keybd_event"), "USER32.dll");
        assert_eq!(phase12_pe_import_dll("Sleep"), "KERNEL32.dll");
        assert_eq!(phase12_pe_import_dll("GetCommandLineW"), "KERNEL32.dll");
        assert_eq!(phase12_pe_import_dll("WideCharToMultiByte"), "KERNEL32.dll");
        assert_eq!(phase12_pe_import_dll("LocalFree"), "KERNEL32.dll");
        assert_eq!(phase12_pe_import_dll("CommandLineToArgvW"), "SHELL32.dll");
        assert_eq!(phase12_pe_import_dll("WinHttpOpen"), "WINHTTP.dll");
        assert_eq!(
            phase12_pe_import_dll("WinHttpQueryDataAvailable"),
            "WINHTTP.dll"
        );
        assert_eq!(phase12_pe_import_dll("WSAPoll"), "WS2_32.dll");
        assert_eq!(phase12_pe_import_dll("ioctlsocket"), "WS2_32.dll");
        assert_eq!(
            phase12_pe_import_dll("GetAdaptersAddresses"),
            "IPHLPAPI.dll"
        );
    }

    #[test]
    fn pe_posix_spellings_keep_write_outside_the_crt() {
        assert_eq!(
            phase12_pe_runtime_provider_symbol("strtoll"),
            Some("strtoll")
        );
        let imports = phase12_pe_loader_import_symbols(&[
            "snprintf".to_string(),
            "write".to_string(),
            "strtoll".to_string(),
        ]);

        assert!(imports.contains(&"_snprintf".to_string()));
        assert!(imports.contains(&"GetStdHandle".to_string()));
        assert!(imports.contains(&"WriteFile".to_string()));
        assert!(!imports.contains(&"_write".to_string()));
        assert!(imports.contains(&"_strtoi64".to_string()));
        assert!(!imports.contains(&"snprintf".to_string()));
        assert!(!imports.contains(&"write".to_string()));
        assert!(!imports.contains(&"strtoll".to_string()));
        assert_eq!(phase12_pe_import_dll("_snprintf"), "msvcrt.dll");
        assert_eq!(phase12_pe_import_dll("_strtoi64"), "msvcrt.dll");
        assert_eq!(phase12_pe_import_dll("getenv"), "msvcrt.dll");
        assert_eq!(phase12_pe_import_dll("strtod"), "msvcrt.dll");
        for symbol in [
            "_access",
            "_aligned_malloc",
            "_aligned_realloc",
            "_aligned_free",
        ] {
            assert_eq!(phase12_pe_import_dll(symbol), "msvcrt.dll");
        }
    }

    #[test]
    fn pe_internal_write_thunk_is_length_aware_and_crt_free() {
        let base = 0x0000_0001_4000_1000_u64;
        let targets = HashMap::from([
            ("GetStdHandle".to_string(), base + 0x400),
            ("WriteFile".to_string(), base + 0x500),
        ]);
        let bytes = phase12_pe_internal_write_thunk(base, &targets)
            .expect("Win32 output thunk must encode");

        assert_eq!(bytes.len(), phase12_pe_internal_write_thunk_len());
        assert!(bytes.starts_with(&[0x48, 0x83, 0xec, 0x48]));
        assert!(bytes
            .windows(5)
            .any(|window| window == [0x4c, 0x89, 0x44, 0x24, 0x30]));
        assert_eq!(bytes.last(), Some(&0xc3));
    }

    #[test]
    fn pe_internal_memory_thunks_are_materialized_without_crt_imports() {
        let memcpy = phase12_pe_internal_memcpy_thunk();
        let memmove = phase12_pe_internal_memmove_thunk();
        let memset = phase12_pe_internal_memset_thunk();
        let strlen = phase12_pe_internal_strlen_thunk();

        for bytes in [&memcpy, &memmove, &memset] {
            assert!(bytes.starts_with(&[0x48, 0x89, 0xc8]));
            assert_eq!(bytes.last(), Some(&0xc3));
        }
        assert_eq!(
            strlen,
            [0x31, 0xc0, 0x80, 0x3c, 0x01, 0x00, 0x74, 0x05, 0x48, 0xff, 0xc0, 0xeb, 0xf5, 0xc3]
        );
        assert!(!phase12_pe_loader_import_symbols(&["strlen".to_string()])
            .iter()
            .any(|symbol| symbol == "strlen"));

        let imports = phase12_pe_loader_import_symbols(&[
            "memcpy".to_string(),
            "memmove".to_string(),
            "memset".to_string(),
        ]);
        assert!(
            imports.is_empty(),
            "memory helpers leaked into PE imports: {imports:?}"
        );
    }

