    #[test]
    fn pe_floating_point_support_marker_is_linker_defined_data() {
        let image = phase12_link_image(&[Phase12LinkInput {
            path: "floating.obj".into(),
            source: None,
            object_format: "coff".into(),
            link_unit_origin: "native_object".into(),
            bytes: Vec::new(),
            hash: "synthetic".into(),
            dynamic_imports: vec!["_fltused".into()],
            unit: Some(Phase12ObjectUnit {
                arch: "x86_64".into(),
                entry: Some("main".into()),
                text: vec![0xc3],
                text_align: 16,
                rodata: Vec::new(),
                rodata_align: 1,
                data: vec![0; 8],
                data_align: 8,
                bss_size: 0,
                bss_align: 1,
                sections: Vec::new(),
                symbols: vec![Phase12ObjectSymbol {
                    name: "main".into(),
                    section: ".text".into(),
                    offset: 0,
                    global: true,
                }],
                relocations: vec![Phase12ObjectRelocation {
                    section: ".data".into(),
                    offset: 0,
                    kind: "abs64".into(),
                    symbol: "_fltused".into(),
                    addend: 0,
                }],
            }),
        }])
        .expect("COFF floating-point support symbol must link internally");

        assert_eq!(image.symbols["_fltused"].section, "data");
        assert_eq!(image.symbols["_fltused"].offset, 8);
        assert_eq!(image.data.len(), 12);
        assert!(!image.dynamic_imports.contains(&"_fltused".to_string()));
        assert!(phase12_pe_loader_import_symbols(&["_fltused".into()]).is_empty());
        let executable = phase12_pe64_os_executable_bytes(&image)
            .expect("linker-defined _fltused must materialize in PE64");
        assert_eq!(&executable[..2], b"MZ");
    }

    #[test]
    fn pe_runtime_os_media_thunks_emit_real_bytes() {
        let base = 0x0000_0001_4000_1000_u64;
        let mut targets = HashMap::new();
        targets.insert("ShellExecuteA".to_string(), base + 0x200);
        targets.insert("keybd_event".to_string(), base + 0x240);
        targets.insert("Sleep".to_string(), base + 0x280);

        let open_uri = phase12_pe_internal_open_uri_thunk(base, &targets).unwrap();
        let media_play = phase12_pe_internal_media_key_thunk(base, &targets, 0xB3).unwrap();
        let sleep = phase12_pe_internal_sleep_thunk(base, &targets).unwrap();

        assert!(open_uri.starts_with(&[0x48, 0x83, 0xec, 0x38]));
        assert!(open_uri.ends_with(&[0x48, 0x83, 0xc4, 0x38, 0xc3]));
        assert_eq!(media_play[5], 0xB3);
        assert!(media_play.ends_with(&[0x48, 0x83, 0xc4, 0x28, 0xc3]));
        assert!(sleep.starts_with(&[0x48, 0x83, 0xec, 0x28]));
        assert!(sleep.ends_with(&[0x48, 0x83, 0xc4, 0x28, 0xc3]));
    }

    #[test]
    fn pe_runtime_win32_graphics_imports_lower_to_multi_dll_iat() {
        let requested = [
            "windowOpen",
            "windowPoll",
            "windowWaitEvent",
            "windowIsFocused",
            "windowSetTitle",
            "canvasRect",
            "canvasText",
            "canvasBeginFrame",
            "canvasRoundRect",
            "canvasTextStyled",
            "canvasBackdropBlur",
            "canvasPresent",
            "monotonicMs",
            "canvasLine",
            "mouseX",
            "keyDown",
            "windowReadKey",
            "windowReadChar",
        ]
        .into_iter()
        .map(str::to_string)
        .collect::<Vec<_>>();
        let imports = phase12_pe_loader_import_symbols(&requested);

        for symbol in [
            "CreateWindowExW",
            "PeekMessageA",
            "PeekMessageW",
            "MsgWaitForMultipleObjectsEx",
            "GetForegroundWindow",
            "SetWindowTextW",
            "CreateSolidBrush",
            "FillRect",
            "TextOutW",
            "CreatePen",
            "LineTo",
            "GetCursorPos",
            "GetAsyncKeyState",
            "GetModuleHandleA",
            "GetPropA",
            "SetPropA",
            "RemovePropA",
            "CreateCompatibleDC",
            "CreateCompatibleBitmap",
            "RoundRect",
            "CreateFontW",
            "StretchBlt",
            "BitBlt",
            "GetTickCount64",
        ] {
            assert!(imports.contains(&symbol.to_string()), "missing {symbol}");
        }
        for legacy_ansi in [
            "CreateWindowExA",
            "SetWindowTextA",
            "TextOutA",
            "CreateFontA",
        ] {
            assert!(!imports.contains(&legacy_ansi.to_string()));
        }
        for runtime_symbol in requested {
            assert!(!imports.contains(&runtime_symbol));
        }

        assert_eq!(phase12_pe_import_dll("CreateWindowExW"), "USER32.dll");
        assert_eq!(
            phase12_pe_import_dll("MsgWaitForMultipleObjectsEx"),
            "USER32.dll"
        );
        assert_eq!(phase12_pe_import_dll("PeekMessageW"), "USER32.dll");
        assert_eq!(phase12_pe_import_dll("GetForegroundWindow"), "USER32.dll");
        assert_eq!(phase12_pe_import_dll("FillRect"), "USER32.dll");
        assert_eq!(phase12_pe_import_dll("CreateSolidBrush"), "GDI32.dll");
        assert_eq!(phase12_pe_import_dll("TextOutW"), "GDI32.dll");
        assert_eq!(phase12_pe_import_dll("GetModuleHandleA"), "KERNEL32.dll");
        assert_eq!(phase12_pe_import_dll("GetPropA"), "USER32.dll");
        assert_eq!(phase12_pe_import_dll("RoundRect"), "GDI32.dll");
        assert_eq!(phase12_pe_import_dll("GetTickCount64"), "KERNEL32.dll");

        let data = phase12_pe_import_data(&imports, 0x3000);
        let payload = String::from_utf8_lossy(&data.bytes);
        for dll in ["USER32.dll", "GDI32.dll", "KERNEL32.dll"] {
            assert!(payload.contains(dll), "missing descriptor for {dll}");
        }
        assert_eq!(data.iat_rvas.len(), imports.len());
        assert_eq!(
            phase12_pe_subsystem(&["windowOpen".to_string()]),
            (PE_SUBSYSTEM_WINDOWS_GUI, "windows_gui"),
            "a native-window program must not open an auxiliary console"
        );
        assert_eq!(
            phase12_pe_subsystem(&["printf".to_string()]),
            (PE_SUBSYSTEM_WINDOWS_CUI, "windows_console")
        );
        assert_eq!(
            phase12_pe_subsystem(&["windowOpen".to_string(), "readInt".to_string()]),
            (PE_SUBSYSTEM_WINDOWS_CUI, "windows_console"),
            "mixed native-window/console-input programs must retain their console"
        );
    }

