    #[test]
    fn pe_runtime_canonical_names_reduce_only_at_the_provider_boundary() {
        let requested = [
            "nC.runtime.terminal.windowOpen",
            "nC.runtime.terminal.windowPoll",
            "nC.runtime.render.canvasPresent",
            "nC.runtime.input.windowReadChar",
            "nC.runtime.string.strEq",
            "nC.runtime.time.sleep",
            "nC.runtime.list.removeAt",
        ]
        .into_iter()
        .map(str::to_string)
        .collect::<Vec<_>>();
        let spec = Phase12PeWin32RuntimeSpec::from_requested(&requested);
        let imports = phase12_pe_loader_import_symbols(&requested);

        for leaf in [
            "windowOpen",
            "windowPoll",
            "canvasPresent",
            "windowReadChar",
            "strEq",
        ] {
            assert!(
                spec.has(leaf),
                "missing provider thunk selection for {leaf}"
            );
        }
        for concrete in [
            "CreateWindowExW",
            "PeekMessageA",
            "BitBlt",
            "PeekMessageW",
            "strcmp",
            "Sleep",
        ] {
            assert!(
                imports.contains(&concrete.to_string()),
                "missing concrete PE import {concrete}"
            );
        }
        for canonical in requested.iter().take(6) {
            assert!(
                !imports.contains(canonical),
                "supported canonical runtime symbol leaked to the OS loader: {canonical}"
            );
        }
        assert!(
            imports.contains(&"nC.runtime.list.removeAt".to_string()),
            "an unsupported provider must remain canonical instead of being silently rewritten"
        );
        assert_eq!(
            phase12_pe_subsystem(&requested),
            (PE_SUBSYSTEM_WINDOWS_GUI, "windows_gui")
        );
    }

    #[test]
    fn pe_runtime_win32_graphics_thunks_emit_real_machine_bytes() {
        let requested = [
            "windowOpen",
            "windowShow",
            "windowHide",
            "windowPoll",
            "windowWaitEvent",
            "windowClose",
            "windowIsOpen",
            "windowIsFocused",
            "windowSetTitle",
            "windowSetSize",
            "windowWidth",
            "windowHeight",
            "windowFocus",
            "canvasClear",
            "canvasBeginFrame",
            "canvasRect",
            "canvasRoundRect",
            "canvasText",
            "canvasTextStyled",
            "canvasLine",
            "canvasEllipse",
            "canvasBackdropBlur",
            "canvasPresent",
            "monotonicMs",
            "mouseX",
            "mouseY",
            "mouseDown",
            "keyDown",
            "windowReadKey",
            "windowReadChar",
        ]
        .into_iter()
        .map(str::to_string)
        .collect::<Vec<_>>();
        let spec = Phase12PeWin32RuntimeSpec::from_requested(&requested);
        let base = 0x0000_0001_4000_1000_u64;
        let mut targets = phase12_pe_win32_dummy_targets(base);
        let mut bytes = Vec::new();
        phase12_pe_append_win32_runtime_thunks(&spec, base, &mut targets, &mut bytes)
            .expect("Win32 runtime thunks");

        assert_eq!(bytes.len(), phase12_pe_win32_runtime_thunk_len(&spec));
        assert!(
            bytes.len() > 500,
            "full graphical runtime must emit substantial code"
        );
        let wide_static = "STATIC\0"
            .encode_utf16()
            .flat_map(u16::to_le_bytes)
            .collect::<Vec<_>>();
        let wide_static_offset = bytes
            .windows(wide_static.len())
            .position(|window| window == wide_static)
            .expect("embedded STATIC wide string");
        assert_eq!(
            (base + wide_static_offset as u64) % 8,
            0,
            "CreateWindowExW class literal must remain naturally aligned across thunk compositions"
        );
        assert!(bytes.contains(&0xe8), "thunks must contain real near calls");
        for symbol in requested {
            assert!(targets.contains_key(&symbol), "missing target for {symbol}");
        }
        assert_ne!(targets["windowClose"], targets["DestroyWindow"]);
        assert_ne!(targets["windowSetTitle"], targets["SetWindowTextW"]);
        assert_eq!(targets["mouseDown"], targets["keyDown"]);
        assert_ne!(targets["windowReadKey"], targets["PeekMessageA"]);
        assert_ne!(targets["windowReadChar"], targets["PeekMessageW"]);
        assert_ne!(targets["windowIsFocused"], targets["GetForegroundWindow"]);
        assert_ne!(
            targets["windowWaitEvent"],
            targets["MsgWaitForMultipleObjectsEx"]
        );
        assert_eq!(targets["monotonicMs"], targets["GetTickCount64"]);
        assert!(bytes
            .windows(b"nC.canvas.dc\0".len())
            .any(|window| window == b"nC.canvas.dc\0"));
        assert!(bytes
            .windows(b"nC.canvas.bmp\0".len())
            .any(|window| window == b"nC.canvas.bmp\0"));
    }

    #[test]
    fn pe_canvas_text_styled_uses_positive_disp32_for_large_frame_slots() {
        let base = 0x0000_0001_4000_1000_u64;
        let targets = phase12_pe_win32_dummy_targets(base);
        let bytes = phase12_pe_internal_canvas_text_styled_thunk(base, &targets)
            .expect("canvasTextStyled thunk");

        for expected in [
            &[0x48, 0x89, 0x84, 0x24, 0x80, 0, 0, 0][..],
            &[0x48, 0x89, 0x84, 0x24, 0x88, 0, 0, 0][..],
            &[0x48, 0x8b, 0x94, 0x24, 0x88, 0, 0, 0][..],
            &[0x48, 0x8b, 0x8c, 0x24, 0x80, 0, 0, 0][..],
        ] {
            assert!(
                bytes
                    .windows(expected.len())
                    .any(|window| window == expected),
                "missing positive disp32 frame access: {expected:02x?}"
            );
        }

        for negative_alias in [
            &[0x48, 0x89, 0x44, 0x24, 0x80][..],
            &[0x48, 0x89, 0x44, 0x24, 0x88][..],
            &[0x48, 0x8b, 0x54, 0x24, 0x88][..],
            &[0x48, 0x8b, 0x4c, 0x24, 0x80][..],
        ] {
            assert!(
                !bytes
                    .windows(negative_alias.len())
                    .any(|window| window == negative_alias),
                "signed disp8 aliases a positive frame slot as a negative address: {negative_alias:02x?}"
            );
        }
    }

