    #[test]
    fn pe_window_poll_preserves_key_and_char_messages_for_typed_input() {
        let base = 0x0000_0001_4000_1000_u64;
        let mut targets = phase12_pe_win32_dummy_targets(base);
        targets.insert("windowClose".to_string(), base + 0x800);
        let poll = phase12_pe_internal_window_poll_thunk(base, &targets).expect("windowPoll thunk");
        let read_key =
            phase12_pe_internal_window_read_key_thunk(base, &targets).expect("windowReadKey thunk");
        let read_char = phase12_pe_internal_window_read_char_thunk(base, &targets)
            .expect("windowReadChar thunk");
        let wait = phase12_pe_internal_window_wait_event_thunk(base, &targets)
            .expect("windowWaitEvent thunk");

        assert!(
            poll.windows(28).any(|window| {
                window
                    == [
                        0x48, 0x8d, 0x4c, 0x24, 0x30, 0x31, 0xd2, 0x41, 0xb8, 0x12, 0, 0, 0, 0x41,
                        0xb9, 0x12, 0, 0, 0, 0x48, 0xc7, 0x44, 0x24, 0x20, 0x01, 0, 0, 0,
                    ]
            }),
            "windowPoll must probe thread-level WM_QUIT with hwnd=NULL"
        );
        assert!(poll.windows(12).any(|window| {
            window
                == [
                    0x48, 0x89, 0xda, 0x45, 0x31, 0xc0, 0x41, 0xb9, 0xff, 0, 0, 0,
                ]
        }));
        assert!(poll.windows(15).any(|window| {
            window
                == [
                    0x48, 0x89, 0xda, 0x41, 0xb8, 0x01, 0x01, 0, 0, 0x41, 0xb9, 0x01, 0x01, 0, 0,
                ]
        }));
        let mut budget_cmp = vec![0x81, 0x7c, 0x24, 0x2c];
        budget_cmp.extend_from_slice(&PHASE12_PE_WINDOW_POLL_MESSAGE_BUDGET.to_le_bytes());
        assert!(
            poll.windows(budget_cmp.len())
                .any(|window| window == budget_cmp),
            "windowPoll must yield after its finite message budget"
        );
        assert!(
            poll.windows(9)
                .any(|window| { window == [0xff, 0x44, 0x24, 0x2c, 0x83, 0x7c, 0x24, 0x38, 0x10] }),
            "windowPoll must inspect and dispatch each removed message instead of discarding it"
        );
        assert!(
            poll.windows(7)
                .any(|window| window == [0x83, 0x7c, 0x24, 0x38, 0x02, 0x0f, 0x84]),
            "windowPoll must mark an observed WM_DESTROY as closed"
        );
        assert!(poll.windows(15).any(|window| {
            window
                == [
                    0x48, 0x89, 0xda, 0x41, 0xb8, 0x03, 0x01, 0, 0, 0x41, 0xb9, 0xff, 0xff, 0xff,
                    0xff,
                ]
        }));
        assert!(read_key
            .windows(12)
            .any(|window| { window == [0x41, 0xb8, 0, 0x01, 0, 0, 0x41, 0xb9, 0, 0x01, 0, 0,] }));
        assert!(read_char.windows(12).any(|window| {
            window == [0x41, 0xb8, 0x02, 0x01, 0, 0, 0x41, 0xb9, 0x02, 0x01, 0, 0]
        }));
        assert_eq!(
            read_key.len(),
            read_char.len() + 10,
            "windowReadKey must TranslateMessage before returning the virtual key"
        );
        assert!(wait
            .windows(6)
            .any(|window| { window == [0x41, 0xb9, 0xff, 0x04, 0, 0] }));
        assert!(wait
            .windows(9)
            .any(|window| { window == [0x48, 0xc7, 0x44, 0x24, 0x20, 0x04, 0, 0, 0] }));
        assert!(wait
            .windows(5)
            .any(|window| { window == [0xb8, 0xfe, 0xff, 0xff, 0xff] }));
    }

