    #[test]
    fn pe_canvas_text_centered_decodes_every_win64_stack_argument_after_its_frame() {
        let base = 0x0000_0001_4000_1000_u64;
        let targets = phase12_pe_win32_dummy_targets(base);
        let bytes = phase12_pe_internal_canvas_text_centered_thunk(base, &targets)
            .expect("canvasTextCentered thunk");

        // Five non-volatile pushes plus the 0xc0-byte frame move entry rsp by 0xe8.
        // The first Win64 stack argument is at entry rsp+0x28, hence current+0x110.
        assert_eq!(
            &bytes[..14],
            &[0x53, 0x56, 0x57, 0x41, 0x54, 0x41, 0x55, 0x48, 0x81, 0xec, 0xc0, 0, 0, 0]
        );

        let decode_disp32 = |offset: usize, opcode: &[u8]| {
            assert_eq!(&bytes[offset..offset + opcode.len()], opcode);
            u32::from_le_bytes(
                bytes[offset + opcode.len()..offset + opcode.len() + 4]
                    .try_into()
                    .expect("disp32"),
            )
        };

        let mut cursor = 25;
        assert_eq!(decode_disp32(cursor, &[0x8b, 0x84, 0x24]), 0x110); // h
        cursor += 7;
        assert_eq!(&bytes[cursor..cursor + 4], &[0x89, 0x44, 0x24, 0x7c]);
        cursor += 4;
        assert_eq!(decode_disp32(cursor, &[0x4c, 0x8b, 0xac, 0x24]), 0x118); // text
        cursor += 8;
        assert_eq!(decode_disp32(cursor, &[0x8b, 0x84, 0x24]), 0x120); // color
        cursor += 11;
        assert_eq!(decode_disp32(cursor, &[0x8b, 0x84, 0x24]), 0x128); // size
        cursor += 11;
        assert_eq!(decode_disp32(cursor, &[0x8b, 0x84, 0x24]), 0x130); // weight

        assert!(
            bytes
                .windows(4)
                .any(|window| window == [0x03, 0x44, 0x24, 0x7c]),
            "centered text RECT must use the separately preserved height"
        );
    }

    #[test]
    fn pe_canvas_round_rect_alpha_preserves_win64_nonvolatiles_and_decodes_stack_args() {
        let base = 0x0000_0001_4000_1000_u64;
        let targets = phase12_pe_win32_dummy_targets(base);
        let bytes = phase12_pe_internal_canvas_round_rect_alpha_thunk(base, &targets)
            .expect("canvasRoundRectAlpha thunk");

        // RBX, RSI, RDI and R12-R15 are all non-volatile under Win64. Together
        // with the 0xd0-byte frame, their seven pushes produce a 0x108 delta.
        assert_eq!(
            &bytes[..18],
            &[
                0x53, 0x56, 0x57, 0x41, 0x54, 0x41, 0x55, 0x41, 0x56, 0x41, 0x57, 0x48, 0x81, 0xec,
                0xd0, 0, 0, 0,
            ]
        );

        let decode_disp32 = |offset: usize, opcode: &[u8]| {
            assert_eq!(&bytes[offset..offset + opcode.len()], opcode);
            u32::from_le_bytes(
                bytes[offset + opcode.len()..offset + opcode.len() + 4]
                    .try_into()
                    .expect("disp32"),
            )
        };
        let mut cursor = 29;
        assert_eq!(decode_disp32(cursor, &[0x44, 0x8b, 0xac, 0x24]), 0x130); // height
        cursor += 8;
        assert_eq!(decode_disp32(cursor, &[0x44, 0x8b, 0xb4, 0x24]), 0x138); // radius
        cursor += 8;
        assert_eq!(decode_disp32(cursor, &[0x44, 0x8b, 0xbc, 0x24]), 0x140); // color
        cursor += 8;
        assert_eq!(decode_disp32(cursor, &[0x8b, 0x84, 0x24]), 0x148); // alpha

        let dc_key = b"nC.canvas.dc\0";
        let key_offset = bytes
            .windows(dc_key.len())
            .position(|window| window == dc_key)
            .expect("canvas DC property key");
        let epilogue = [
            0x48, 0x81, 0xc4, 0xd0, 0, 0, 0, 0x41, 0x5f, 0x41, 0x5e, 0x41, 0x5d, 0x41, 0x5c, 0x5f,
            0x5e, 0x5b, 0xc3,
        ];
        assert_eq!(&bytes[key_offset - epilogue.len()..key_offset], epilogue);
    }

    #[test]
    fn pe_canvas_physical_paths_reset_fit_origin_before_pixel_operations() {
        let base = 0x0000_0001_4000_1000_u64;
        let targets = phase12_pe_win32_dummy_targets(base);
        let begin = phase12_pe_internal_canvas_begin_frame_thunk(base, &targets)
            .expect("canvasBeginFrame thunk");
        let present =
            phase12_pe_internal_canvas_present_thunk(base, &targets).expect("canvasPresent thunk");
        let blur = phase12_pe_internal_canvas_backdrop_blur_thunk(base, &targets)
            .expect("canvasBackdropBlur thunk");
        let blur_v3 = phase12_pe_internal_canvas_backdrop_blur_v3_thunk(base, &targets)
            .expect("canvasBackdropBlurV3 thunk");

        // SetMapMode(MM_TEXT) keeps the MM_ANISOTROPIC viewport origin. Every
        // physical-pixel path must therefore follow it with
        // SetViewportOrgEx(dc, 0, 0, NULL) before clearing/copying/blurring.
        for (name, thunk, dc_load) in [
            ("begin", &begin, &[0x48, 0x89, 0xf9][..]),
            ("present", &present, &[0x48, 0x89, 0xf1][..]),
            ("blur", &blur, &[0x48, 0x8b, 0x8c, 0x24, 0x80, 0, 0, 0][..]),
            ("blur-v3", &blur_v3, &[0x48, 0x8b, 0x4c, 0x24, 0x60][..]),
        ] {
            let mut reset = dc_load.to_vec();
            reset.extend_from_slice(&[0x31, 0xd2, 0x45, 0x31, 0xc0, 0x45, 0x31, 0xc9, 0xe8]);
            assert!(
                thunk
                    .windows(reset.len())
                    .any(|window| window == reset.as_slice()),
                "{name} must reset the viewport origin before physical pixel work"
            );
        }

        for api in [
            "canvasBeginFrame",
            "canvasPresent",
            "canvasBackdropBlur",
            "canvasBackdropBlurV3",
        ] {
            let imports = phase12_pe_loader_import_symbols(&[api.to_string()]);
            assert!(
                imports.iter().any(|symbol| symbol == "SetViewportOrgEx"),
                "{api} must retain SetViewportOrgEx in its closed import set"
            );
        }
    }

    #[test]
    fn pe_runtime_canvas_v3_imports_and_thunks_are_closed_to_real_win32_bytes() {
        let requested = [
            "windowDpi",
            "windowRefreshHz",
            "windowState",
            "windowSetState",
            "canvasSetQuality",
            "canvasTextCentered",
            "canvasShadowRoundRect",
            "canvasRoundRectAlpha",
            "canvasRoundRectGradient",
            "canvasBackdropBlurV3",
            "canvasSetFrameMode",
            "canvasFrameDeltaMs",
            "canvasPollResize",
            "canvasSetViewport",
            "canvasPointerX",
            "canvasPointerY",
            "canvasBeginFrame",
            "canvasPresent",
        ]
        .into_iter()
        .map(str::to_string)
        .collect::<Vec<_>>();
        let imports = phase12_pe_loader_import_symbols(&requested);
        for symbol in [
            "GetDpiForWindow",
            "GetDeviceCaps",
            "IsIconic",
            "IsZoomed",
            "CreateFontW",
            "DrawTextW",
            "MultiByteToWideChar",
            "SetMapMode",
            "SetWindowExtEx",
            "SetViewportExtEx",
            "SetViewportOrgEx",
            "DPtoLP",
            "QueryPerformanceCounter",
            "QueryPerformanceFrequency",
            "MonitorFromWindow",
            "GetMonitorInfoW",
            "CreateDCW",
            "Sleep",
            "AlphaBlend",
            "GradientFill",
        ] {
            assert!(imports.contains(&symbol.to_string()), "missing {symbol}");
        }
        for legacy_ansi in ["CreateFontA", "DrawTextA"] {
            assert!(
                !imports.contains(&legacy_ansi.to_string()),
                "Canvas V3 text leaked legacy ANSI import {legacy_ansi}"
            );
        }
        for symbol in &requested {
            assert!(
                !imports.contains(symbol),
                "abstract runtime import leaked: {symbol}"
            );
        }
        assert_eq!(phase12_pe_import_dll("AlphaBlend"), "MSIMG32.dll");
        assert_eq!(phase12_pe_import_dll("GradientFill"), "MSIMG32.dll");

        let spec = Phase12PeWin32RuntimeSpec::from_requested(&requested);
        let base = 0x0000_0001_4000_1000_u64;
        let mut targets = phase12_pe_win32_dummy_targets(base);
        let mut bytes = Vec::new();
        phase12_pe_append_win32_runtime_thunks(&spec, base, &mut targets, &mut bytes)
            .expect("Canvas V3 PE thunks");
        assert_eq!(bytes.len(), phase12_pe_win32_runtime_thunk_len(&spec));
        assert!(
            bytes.len() > 3_000,
            "V3 surface must emit substantial machine code"
        );
        for symbol in requested {
            assert!(
                targets.contains_key(&symbol),
                "missing thunk target for {symbol}"
            );
        }
        for key in [
            b"nC.canvas.physical.w\0".as_slice(),
            b"nC.canvas.logical.w\0".as_slice(),
            b"nC.canvas.viewport.mode\0".as_slice(),
            b"nC.canvas.frame.mode\0".as_slice(),
            b"nC.canvas.delta\0".as_slice(),
        ] {
            assert!(bytes.windows(key.len()).any(|window| window == key));
        }
    }

    #[test]
    fn pe_canvas_v3_4k_layout_resize_and_viewport_math_are_overflow_safe() {
        let (stride, byte_size) = phase12_canvas_bgra32_layout(3840, 2160).expect("4K BGRA32");
        assert_eq!(stride, 15_360);
        assert_eq!(byte_size, 33_177_600);
        assert!(byte_size < u32::MAX as usize);
        assert!(phase12_canvas_bgra32_layout(i32::MAX, i32::MAX).is_none());

        let exact =
            phase12_canvas_viewport_transform(1920, 1080, 3840, 2160, 1).expect("exact 2x fit");
        assert_eq!(
            exact,
            Phase12CanvasViewportTransform {
                viewport_width: 3840,
                viewport_height: 2160,
                origin_x: 0,
                origin_y: 0,
            }
        );
        let fit = phase12_canvas_viewport_transform(1920, 1080, 3840, 2400, 1).unwrap();
        assert_eq!((fit.viewport_width, fit.viewport_height), (3840, 2160));
        assert_eq!((fit.origin_x, fit.origin_y), (0, 120));
        let fill = phase12_canvas_viewport_transform(1920, 1080, 3840, 2400, 2).unwrap();
        assert_eq!((fill.viewport_width, fill.viewport_height), (4266, 2400));
        assert_eq!((fill.origin_x, fill.origin_y), (-213, 0));

        let fit_before = phase12_canvas_viewport_transform(1920, 1080, 3840, 2400, 1).unwrap();
        let fit_after = phase12_canvas_viewport_transform(1920, 1080, 2560, 1600, 1).unwrap();
        assert_eq!(
            phase12_canvas_inverse_pointer(1920, 1080, fit_before, 1920, 1200),
            Some((960, 540))
        );
        assert_eq!(
            phase12_canvas_inverse_pointer(1920, 1080, fit_after, 1280, 800),
            Some((960, 540)),
            "fit hit-testing must remain inverse-correct after resize"
        );
        assert_eq!(
            phase12_canvas_inverse_pointer(1920, 1080, fit_after, 1280, 0),
            Some((960, -60)),
            "letterbox bars intentionally map outside logical bounds"
        );

        let base = 0x0000_0001_4000_1000_u64;
        let targets = phase12_pe_win32_dummy_targets(base);
        let begin = phase12_pe_internal_canvas_begin_frame_thunk(base, &targets)
            .expect("dynamic Canvas V3 begin-frame thunk");
        for key in [
            b"nC.canvas.physical.w\0".as_slice(),
            b"nC.canvas.physical.h\0",
        ] {
            assert!(begin.windows(key.len()).any(|window| window == key));
        }
        assert!(
            begin
                .windows(4)
                .any(|window| window == [0x48, 0xf7, 0xf9, 0x89]),
            "fit/fill viewport must contain signed 64-bit division"
        );

        let open = phase12_pe_internal_window_open_thunk(base, &targets)
            .expect("resizable Win32 window-open thunk");
        assert!(
            open.windows(6)
                .any(|window| window == [0x41, 0xb9, 0, 0, 0xcf, 0x10]),
            "windowOpen must preserve WS_OVERLAPPEDWINDOW|WS_VISIBLE"
        );
    }

    #[test]
    fn pe_canvas_v3_qpc_deadlines_preserve_high_fps_presets() {
        let frequency = 10_000_000_u64;
        for requested in [60_u32, 120, 144, 240] {
            let ticks = phase12_qpc_interval_ticks(frequency, requested).unwrap();
            let effective = frequency as f64 / ticks as f64;
            let relative_error = (effective - f64::from(requested)).abs() / f64::from(requested);
            assert!(
                relative_error < 0.0001,
                "{requested} Hz drifted to {effective:.6} Hz"
            );
        }

        let requested = [
            "canvasSetFrameMode".to_string(),
            "canvasPresent".to_string(),
        ];
        let imports = phase12_pe_loader_import_symbols(&requested);
        assert!(imports.contains(&"QueryPerformanceCounter".to_string()));
        assert!(imports.contains(&"QueryPerformanceFrequency".to_string()));
        assert!(imports.contains(&"GetDeviceCaps".to_string()));
        assert!(imports.contains(&"MonitorFromWindow".to_string()));
        assert!(imports.contains(&"GetMonitorInfoW".to_string()));
        assert!(imports.contains(&"CreateDCW".to_string()));
        assert!(imports.contains(&"Sleep".to_string()));
        assert!(!imports.contains(&"GetTickCount64".to_string()));

        let base = 0x0000_0001_4000_1000_u64;
        let targets = phase12_pe_win32_dummy_targets(base);
        let refresh = phase12_pe_internal_window_refresh_hz_thunk(base, &targets)
            .expect("current-monitor refresh thunk");
        assert!(
            refresh
                .windows(5)
                .any(|window| window == [0xba, 2, 0, 0, 0]),
            "refresh query must use MONITOR_DEFAULTTONEAREST"
        );
        assert!(
            refresh
                .windows(8)
                .any(|window| window == [0xc7, 0x44, 0x24, 0x30, 104, 0, 0, 0]),
            "refresh query must initialize MONITORINFOEXW"
        );
    }

    #[test]
    fn pe_canvas_v3_blur_profile_matches_host_quality_formula() {
        assert_eq!(phase12_canvas_blur_profile(0, 30, 4), Some((2, 9)));
        assert_eq!(phase12_canvas_blur_profile(1, 30, 4), Some((4, 5)));
        assert_eq!(phase12_canvas_blur_profile(2, 30, 4), Some((4, 5)));
        assert_eq!(phase12_canvas_blur_profile(2, 256, 99), Some((8, 5)));
        assert_eq!(phase12_canvas_blur_profile(1, 0, 4), Some((4, 1)));
        assert!(phase12_canvas_blur_profile(1, -1, 4).is_none());
        assert!(phase12_canvas_blur_profile(1, 16, 0).is_none());

        let base = 0x0000_0001_4000_1000_u64;
        let targets = phase12_pe_win32_dummy_targets(base);
        let bytes = phase12_pe_internal_canvas_backdrop_blur_v3_thunk(base, &targets)
            .expect("Canvas V3 blur thunk");
        assert!(bytes
            .windows(b"nC.canvas.quality\0".len())
            .any(|window| window == b"nC.canvas.quality\0"));
        assert!(
            bytes.windows(3).any(|window| window == [0x8d, 0x0c, 0x3f]),
            "PE64 blur must derive divisor from effective_passes*2"
        );
        assert!(
            bytes
                .windows(6)
                .any(|window| window == [0x81, 0xfe, 0, 1, 0, 0]),
            "PE64 blur must cap radius at 256"
        );
    }

    #[test]
    fn pe_canvas_text_is_strict_utf8_to_utf16_and_never_uses_ansi_gdi() {
        let requested = ["canvasText", "canvasTextStyled", "canvasTextCentered"]
            .into_iter()
            .map(str::to_string)
            .collect::<Vec<_>>();
        let imports = phase12_pe_loader_import_symbols(&requested);
        for wide in [
            "MultiByteToWideChar",
            "CreateFontW",
            "TextOutW",
            "DrawTextW",
        ] {
            assert!(imports.contains(&wide.to_string()), "missing {wide}");
        }
        for ansi in ["CreateFontA", "TextOutA", "DrawTextA"] {
            assert!(
                !imports.contains(&ansi.to_string()),
                "Unicode Canvas text leaked {ansi}"
            );
        }

        let spec = Phase12PeWin32RuntimeSpec::from_requested(&requested);
        let base = 0x0000_0001_4000_1000_u64;
        let mut targets = phase12_pe_win32_dummy_targets(base);
        let mut bytes = Vec::new();
        phase12_pe_append_win32_runtime_thunks(&spec, base, &mut targets, &mut bytes)
            .expect("Unicode Canvas PE thunks");
        let cp_utf8 = [0xb9, 0xe9, 0xfd, 0, 0];
        let strict_flags = [0xba, 8, 0, 0, 0];
        assert!(bytes.windows(cp_utf8.len()).any(|window| window == cp_utf8));
        assert!(bytes
            .windows(strict_flags.len())
            .any(|window| window == strict_flags));
        let wide_face = "Segoe UI\0"
            .encode_utf16()
            .flat_map(u16::to_le_bytes)
            .collect::<Vec<_>>();
        assert!(bytes
            .windows(wide_face.len())
            .any(|window| window == wide_face));

        for sample in ["Configuración", "Dónde", "Jöns", "°C"] {
            let decoded = std::str::from_utf8(sample.as_bytes()).expect("valid UTF-8 fixture");
            let utf16 = decoded.encode_utf16().collect::<Vec<_>>();
            assert_eq!(String::from_utf16(&utf16).unwrap(), sample);
            assert!(sample.as_bytes().iter().any(|byte| !byte.is_ascii()));
        }
        let invalid_utf8 = vec![0xc3, 0x28];
        assert!(std::str::from_utf8(&invalid_utf8).is_err());
    }

