    #[test]
    fn x86_64_scalar_extended_encoder_bytes() {
        assert_eq!(x86_64_bytes("adc", &["rax", "rbx"]), vec![0x48, 0x11, 0xd8]);
        assert_eq!(
            x86_64_bytes("sbb", &["rax", "1"]),
            vec![0x48, 0x83, 0xd8, 0x01]
        );
        assert_eq!(
            x86_64_bytes("shl", &["rax", "3"]),
            vec![0x48, 0xc1, 0xe0, 0x03]
        );
        assert_eq!(
            x86_64_bytes("shrd", &["rax", "rbx", "cl"]),
            vec![0x48, 0x0f, 0xad, 0xd8]
        );
        assert_eq!(
            x86_64_bytes("imul", &["rax", "rbx", "7"]),
            vec![0x48, 0x6b, 0xc3, 0x07]
        );
        assert_eq!(x86_64_bytes("bswap", &["r8"]), vec![0x49, 0x0f, 0xc8]);
        assert_eq!(
            x86_64_bytes("popcnt", &["rax", "rbx"]),
            vec![0xf3, 0x48, 0x0f, 0xb8, 0xc3]
        );
        assert_eq!(
            x86_64_bytes("bt", &["rax", "5"]),
            vec![0x48, 0x0f, 0xba, 0xe0, 0x05]
        );
        assert_eq!(
            x86_64_bytes("crc32", &["rax", "rbx"]),
            vec![0xf2, 0x48, 0x0f, 0x38, 0xf1, 0xc3]
        );
        assert_eq!(x86_64_bytes("rep", &["movsb"]), vec![0xf3, 0xa4]);
        assert_eq!(
            x86_64_bytes("lock", &["xadd qword [rax]", "rbx"]),
            vec![0xf0, 0x48, 0x0f, 0xc1, 0x18]
        );
        assert_eq!(
            x86_64_bytes("lock", &["cmpxchg qword [rdi]", "rsi"]),
            vec![0xf0, 0x48, 0x0f, 0xb1, 0x37]
        );
        assert_eq!(
            x86_64_bytes("xadd", &["byte ptr [rax]", "bl"]),
            vec![0x0f, 0xc0, 0x18]
        );
        assert_eq!(
            x86_64_bytes("xadd", &["word ptr [rax]", "bx"]),
            vec![0x66, 0x0f, 0xc1, 0x18]
        );
        assert_eq!(
            x86_64_bytes("xadd", &["word ptr fs:[rax]", "bx"]),
            vec![0x64, 0x66, 0x0f, 0xc1, 0x18]
        );
        assert_eq!(
            x86_64_bytes("xadd", &["dword ptr [rax]", "ebx"]),
            vec![0x0f, 0xc1, 0x18]
        );
        assert_eq!(
            x86_64_bytes("cmpxchg", &["byte ptr [rdi]", "sil"]),
            vec![0x40, 0x0f, 0xb0, 0x37]
        );
        assert_eq!(
            x86_64_bytes("cmpxchg", &["word ptr [rdi]", "si"]),
            vec![0x66, 0x0f, 0xb1, 0x37]
        );
        assert_eq!(
            x86_64_bytes("cmpxchg8b", &["qword ptr [rax]"]),
            vec![0x0f, 0xc7, 0x08]
        );
        assert_eq!(
            x86_64_bytes("cmpxchg16b", &["xmmword ptr [rax]"]),
            vec![0x48, 0x0f, 0xc7, 0x08]
        );
        assert_eq!(
            x86_64_bytes("lock", &["cmpxchg8b qword ptr [rax]"]),
            vec![0xf0, 0x0f, 0xc7, 0x08]
        );
        assert_eq!(
            x86_64_bytes("lock", &["cmpxchg16b xmmword ptr [rax]"]),
            vec![0xf0, 0x48, 0x0f, 0xc7, 0x08]
        );
        assert_eq!(
            x86_64_bytes("lock", &["add qword ptr [rax]", "rbx"]),
            vec![0xf0, 0x48, 0x01, 0x18]
        );
        assert_eq!(
            x86_64_bytes("lock", &["add qword ptr [rax]", "1"]),
            vec![0xf0, 0x48, 0x83, 0x00, 0x01]
        );
        assert_eq!(
            x86_64_bytes("lock", &["inc qword ptr [rax]"]),
            vec![0xf0, 0x48, 0xff, 0x00]
        );
        assert_eq!(
            x86_64_bytes("lock", &["neg qword ptr [rax]"]),
            vec![0xf0, 0x48, 0xf7, 0x18]
        );
        assert_eq!(
            x86_64_bytes("lock", &["bts qword ptr [rax]", "rbx"]),
            vec![0xf0, 0x48, 0x0f, 0xab, 0x18]
        );
        assert_eq!(
            x86_64_bytes("lea", &["rdi", "[rel packet_table]"]),
            vec![0x48, 0x8d, 0x3d, 0x00, 0x00, 0x00, 0x00]
        );
        assert_eq!(
            x86_64_bytes("lea", &["rax", "[rip+8]"]),
            vec![0x48, 0x8d, 0x05, 0x08, 0x00, 0x00, 0x00]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword [rip+16]"]),
            vec![0x48, 0x8b, 0x05, 0x10, 0x00, 0x00, 0x00]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword [rsi*4+0x12345678]"]),
            vec![0x48, 0x8b, 0x04, 0xb5, 0x78, 0x56, 0x34, 0x12]
        );
        assert_eq!(
            x86_64_bytes("mov", &["qword [rdi*8+16]", "rax"]),
            vec![0x48, 0x89, 0x04, 0xfd, 0x10, 0x00, 0x00, 0x00]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr fs:[rbx+8]"]),
            vec![0x64, 0x48, 0x8b, 0x43, 0x08]
        );
        assert_eq!(
            x86_64_bytes("mov", &["qword ptr gs:[r12+r13*8+0x7f]", "rax"]),
            vec![0x65, 0x4b, 0x89, 0x44, 0xec, 0x7f]
        );
        assert_eq!(
            x86_64_bytes("lea", &["r10", "qword ptr [r9+r11*4-16]"]),
            vec![0x4f, 0x8d, 0x54, 0x99, 0xf0]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [0x12345678]"]),
            vec![0x48, 0x8b, 0x04, 0x25, 0x78, 0x56, 0x34, 0x12]
        );
        assert_eq!(
            x86_64_bytes("mov", &["qword ptr [0x12345678]", "rax"]),
            vec![0x48, 0x89, 0x04, 0x25, 0x78, 0x56, 0x34, 0x12]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [packet_table]"]),
            vec![0x48, 0x8b, 0x04, 0x25, 0x00, 0x00, 0x00, 0x00]
        );
        assert_eq!(
            x86_64_bytes("mov", &["qword ptr [packet_table+8]", "rax"]),
            vec![0x48, 0x89, 0x04, 0x25, 0x08, 0x00, 0x00, 0x00]
        );
        assert_eq!(
            x86_64_bytes("lea", &["rdi", "[packet_table-4]"]),
            vec![0x48, 0x8d, 0x3c, 0x25, 0xfc, 0xff, 0xff, 0xff]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rel packet_table]"]),
            vec![0x48, 0x8b, 0x05, 0x00, 0x00, 0x00, 0x00]
        );
        assert_eq!(
            x86_64_bytes("mov", &["qword ptr [rel packet_table]", "rax"]),
            vec![0x48, 0x89, 0x05, 0x00, 0x00, 0x00, 0x00]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr fs:[rel packet_table]"]),
            vec![0x64, 0x48, 0x8b, 0x05, 0x00, 0x00, 0x00, 0x00]
        );
        assert_eq!(
            x86_64_bytes("mov", &["al", "moffs8 [0x1122334455667788]"]),
            vec![0xa0, 0x88, 0x77, 0x66, 0x55, 0x44, 0x33, 0x22, 0x11]
        );
        assert_eq!(
            x86_64_bytes("mov", &["eax", "moffs32 [0x1122334455667788]"]),
            vec![0xa1, 0x88, 0x77, 0x66, 0x55, 0x44, 0x33, 0x22, 0x11]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "moffs64 [0x1122334455667788]"]),
            vec![0x48, 0xa1, 0x88, 0x77, 0x66, 0x55, 0x44, 0x33, 0x22, 0x11]
        );
        assert_eq!(
            x86_64_bytes("mov", &["moffs64 [0x1122334455667788]", "rax"]),
            vec![0x48, 0xa3, 0x88, 0x77, 0x66, 0x55, 0x44, 0x33, 0x22, 0x11]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "moffs64 gs:[0x1122334455667788]"]),
            vec![0x65, 0x48, 0xa1, 0x88, 0x77, 0x66, 0x55, 0x44, 0x33, 0x22, 0x11]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [r13]"]),
            vec![0x49, 0x8b, 0x45, 0x00]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rbp]"]),
            vec![0x48, 0x8b, 0x45, 0x00]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rsp]"]),
            vec![0x48, 0x8b, 0x04, 0x24]
        );
    }

    #[test]
    fn x86_64_kernel_return_contract_and_sized_integer_forms_encode() {
        assert_eq!(x86_64_bytes("cmp", &["eax", "0"]), vec![0x83, 0xf8, 0x00]);
        assert_eq!(
            x86_64_bytes("movzx", &["eax", "al"]),
            vec![0x0f, 0xb6, 0xc0]
        );
        assert_eq!(
            x86_64_bytes("imul", &["eax", "eax", "20299"]),
            vec![0x69, 0xc0, 0x4b, 0x4f, 0x00, 0x00]
        );

        assert_eq!(
            x86_64_bytes("movzx", &["ax", "bl"]),
            vec![0x66, 0x0f, 0xb6, 0xc3]
        );
        assert_eq!(
            x86_64_bytes("movzx", &["eax", "bx"]),
            vec![0x0f, 0xb7, 0xc3]
        );
        assert_eq!(
            x86_64_bytes("movzx", &["r9d", "r8b"]),
            vec![0x45, 0x0f, 0xb6, 0xc8]
        );
        assert_eq!(
            x86_64_bytes("cmp", &["r8d", "-1"]),
            vec![0x41, 0x83, 0xf8, 0xff]
        );
        assert_eq!(
            x86_64_bytes("add", &["spl", "1"]),
            vec![0x40, 0x80, 0xc4, 0x01]
        );
        assert_eq!(
            x86_64_bytes("imul", &["ax", "bx", "300"]),
            vec![0x66, 0x69, 0xc3, 0x2c, 0x01]
        );
        assert_eq!(
            try_encode_x86_64_instruction(&inst("add", &["ah", "r8b"]))
                .expect("invalid high-byte combination is not a diagnostic"),
            None
        );
    }

    #[test]
    fn x86_64_signed_and_unsigned_field_extensions_encode_register_and_memory_forms() {
        assert_eq!(
            x86_64_bytes("movsx", &["rax", "al"]),
            vec![0x48, 0x0f, 0xbe, 0xc0]
        );
        assert_eq!(
            x86_64_bytes("movsx", &["ecx", "word ptr [r8 + 2]"]),
            vec![0x41, 0x0f, 0xbf, 0x48, 0x02]
        );
        assert_eq!(
            x86_64_bytes("movsxd", &["rax", "eax"]),
            vec![0x48, 0x63, 0xc0]
        );
        assert_eq!(
            x86_64_bytes("movsxd", &["r9", "dword ptr [r10 + 4]"]),
            vec![0x4d, 0x63, 0x4a, 0x04]
        );
        assert_eq!(
            x86_64_bytes("movzx", &["r10d", "byte ptr [r11 + 1]"]),
            vec![0x45, 0x0f, 0xb6, 0x53, 0x01]
        );
    }

    #[test]
    fn kernel_wrapper_i386_setcc_and_aarch64_stack_displacements_encode() {
        assert_eq!(i386_bytes("sete", &["al"]), vec![0x0f, 0x94, 0xc0]);
        assert_eq!(i386_bytes("setne", &["dl"]), vec![0x0f, 0x95, 0xc2]);

        let store = vec![0xfe, 0x07, 0x00, 0xf9];
        let load = vec![0xfe, 0x07, 0x40, 0xf9];
        assert_eq!(aarch64_bytes("str", &["x30", "[sp + 8]"]), store);
        assert_eq!(aarch64_bytes("str", &["x30", "[sp, #8]"]), store);
        assert_eq!(aarch64_bytes("ldr", &["x30", "[sp + 8]"]), load);
        assert_eq!(aarch64_bytes("ldr", &["x30", "[sp, #8]"]), load);
        assert_eq!(
            aarch64_bytes("str", &["w0", "[sp + 4]"]),
            vec![0xe0, 0x07, 0x00, 0xb9]
        );
    }

