    #[test]
    fn i386_msvc_machine_source_emits_and_reimports_real_coff() {
        let source = r#"win32_bridge[@machine] {
    target:
        arch: i386;
        abi: i386-msvc;
        object: coff;
        endian: little;
        pointerWidth: 32;
        profile: userland;
    extern:
        _main:
    symbol:
        bridge:
            section: .text;
            binding: global;
            type: routine;
    entry:
        bridge;
    proc:
        bridge:
    instr:
        call _main;
        ret;
    verify:
        target;
        encoding;
        object;
    seal:
        artifact: object;
        require: verified;
}"#;
        let audit = parse_machine_source("win32_bridge.nm", source);
        assert!(!audit.has_errors(), "{:?}", audit.diagnostics);
        let object = emit_object_bytes(&audit, "coff").expect("i386 COFF emission");
        assert_eq!(classify_object_bytes(&object), ("coff", true));
        assert_eq!(object_arch_for_bytes(&object), "i386");
        assert_eq!(read_u16(&object, 0), 0x014c);

        let native = phase12_coff_native_object_unit("win32_bridge.obj", &object)
            .expect("i386 COFF reimport");
        assert_eq!(native.unit.arch, "i386");
        assert!(native.dynamic_imports.contains(&"_main".to_string()));
        assert_eq!(native.unit.relocations.len(), 1);
        assert_eq!(native.unit.relocations[0].kind, "call-near32");
    }

