    #[test]
    fn macho_link_validation_defers_dso_handle_to_the_finalizer() {
        let unit = Phase12ObjectUnit {
            arch: "aarch64".to_string(),
            entry: Some("_main".to_string()),
            text: [0x9000_0000_u32.to_le_bytes(), 0xf940_0000_u32.to_le_bytes()].concat(),
            text_align: 4,
            rodata: (0_u8..16).collect(),
            rodata_align: 16,
            data: Vec::new(),
            data_align: 1,
            bss_size: 0,
            bss_align: 1,
            sections: Vec::new(),
            symbols: vec![Phase12ObjectSymbol {
                name: "_main".to_string(),
                section: ".text".to_string(),
                offset: 0,
                global: true,
            }],
            relocations: vec![
                Phase12ObjectRelocation {
                    section: ".text".to_string(),
                    offset: 0,
                    kind: "aarch64-adr-got-page".to_string(),
                    symbol: "___dso_handle".to_string(),
                    addend: 0,
                },
                Phase12ObjectRelocation {
                    section: ".text".to_string(),
                    offset: 4,
                    kind: "aarch64-ld64-got-lo12-nc".to_string(),
                    symbol: "___dso_handle".to_string(),
                    addend: 0,
                },
            ],
        };
        let input = Phase12LinkInput {
            path: "dso.o".to_string(),
            source: None,
            object_format: "macho".to_string(),
            link_unit_origin: "test".to_string(),
            bytes: Vec::new(),
            hash: hash_bytes(b"dso.o"),
            dynamic_imports: Vec::new(),
            unit: Some(unit),
        };
        let image = phase12_link_image(&[input]).expect("linker-defined dso handle");
        assert_eq!(image.rodata_align, 16);
        let executable =
            phase12_macho64_os_executable_bytes(&image).expect("Mach-O dso finalization");
        assert!(phase12_is_macho64_executable(&executable));
        let const_section = phase12_macho_section_specs(&executable)
            .into_iter()
            .find(|section| section.name == "__const")
            .expect("material __const section");
        assert_eq!(const_section.align, 16);
        assert_eq!(const_section.offset % 16, 0);
    }

    #[test]
    fn macho_arm64_relocations_and_import_stubs_are_material() {
        assert_eq!(
            phase12_macho_relocation_kind_for_arch("aarch64", 2, true, 2),
            Some("aarch64-call26")
        );
        assert_eq!(
            phase12_macho_relocation_kind_for_arch("aarch64", 3, true, 2),
            Some("aarch64-adr-prel-pg-hi21")
        );
        assert_eq!(
            phase12_macho_relocation_kind_for_arch("aarch64", 4, false, 2),
            Some("aarch64-pageoff12")
        );
        assert_eq!(phase12_macho_arm64_addend(0x0000_0008), 8);
        assert_eq!(phase12_macho_arm64_addend(0x00ff_fff8), -8);

        let rel = Phase12LinkedRelocation {
            section: "text".into(),
            offset: 0,
            kind: "aarch64-pageoff12".into(),
            symbol: "value".into(),
            addend: 0,
        };
        let mut add = 0x9100_0000_u32.to_le_bytes().to_vec();
        phase12_apply_aarch64_pageoff12(&mut add, &rel, 0x123).expect("ADD PAGEOFF12");
        assert_eq!((read_u32(&add, 0) >> 10) & 0xfff, 0x123);

        let mut ldr = 0xf940_0000_u32.to_le_bytes().to_vec();
        phase12_apply_aarch64_pageoff12(&mut ldr, &rel, 0x128).expect("LDR PAGEOFF12");
        assert_eq!((read_u32(&ldr, 0) >> 10) & 0xfff, 0x25);

        let stubs = phase12_macho_stubs_bytes_at("aarch64", 2, 0x1_0000_2000, 0x1_0000_4000)
            .expect("arm64 Mach-O stubs");
        assert_eq!(stubs.len(), 24);
        assert_eq!(read_u32(&stubs, 8), 0xd61f_0200);
        assert_eq!(read_u32(&stubs, 20), 0xd61f_0200);
    }

    #[test]
    fn macho_clang_section_ordinals_link_as_local_symbols() {
        if Command::new("clang").arg("--version").output().is_err() {
            return;
        }
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock")
            .as_nanos();
        let root = env::temp_dir().join(format!("ncc-macho-section-reloc-{nonce}"));
        fs::create_dir_all(&root).expect("create Mach-O test directory");
        let source = root.join("section_reloc.ll");
        let object = root.join("section_reloc.o");
        fs::write(
            &source,
            "target triple = \"x86_64-apple-darwin\"\n@text = private unnamed_addr constant [14 x i8] c\"section-reloc\\00\", align 1\ndeclare void @consume(ptr)\ndefine i32 @main() {\n  call void @consume(ptr @text)\n  ret i32 0\n}\n",
        )
        .expect("write Mach-O test source");
        let output = Command::new("clang")
            .args([
                "--target=x86_64-apple-darwin",
                "-O3",
                "-x",
                "ir",
                "-c",
                source.to_string_lossy().as_ref(),
                "-o",
                object.to_string_lossy().as_ref(),
            ])
            .output()
            .expect("run clang Mach-O target compiler");
        assert!(
            output.status.success(),
            "clang failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );

        let bytes = fs::read(&object).expect("read Clang Mach-O object");
        let native = phase12_macho_native_object_unit(object.to_string_lossy().as_ref(), &bytes)
            .expect("import Clang Mach-O object");
        assert!(
            native
                .unit
                .relocations
                .iter()
                .any(|relocation| relocation.symbol.starts_with("$macho.section.")),
            "fixture must contain a local Mach-O section-ordinal relocation"
        );
        let input = Phase12LinkInput {
            path: object.display().to_string(),
            source: Some(source.display().to_string()),
            object_format: "macho".into(),
            link_unit_origin: "native_object".into(),
            hash: hash_bytes(&bytes),
            bytes,
            dynamic_imports: native.dynamic_imports,
            unit: Some(native.unit),
        };
        phase12_link_image(&[input]).expect("link Clang Mach-O section ordinals");
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn i386_pic_gotpc_gotoff_and_got32x_have_exact_linker_semantics() {
        assert_eq!(
            phase12_elf_relocation_kind("i386", 9),
            Some("i386-gotoff32")
        );
        assert_eq!(
            phase12_elf_relocation_kind("i386", 10),
            Some("i386-gotpc32")
        );
        assert_eq!(phase12_elf_relocation_kind("i386", 43), Some("got32"));

        let rel = Phase12LinkedRelocation {
            section: "text".into(),
            offset: 0,
            kind: "i386-gotoff32".into(),
            symbol: "$elf.section.7".into(),
            addend: -4,
        };
        let mut text = vec![0_u8; 4];
        phase12_apply_i386_gotoff32(&mut text, &mut [], &mut [], &rel, 0x0010_1800, 0x0010_2000)
            .expect("R_386_GOTOFF must encode S + A - GOT");
        assert_eq!(i32::from_le_bytes(text.try_into().unwrap()), -0x804);

        let symbols = vec![Phase12NativeSymbol {
            name: "_GLOBAL_OFFSET_TABLE_".into(),
            section: None,
            offset: 0,
            global: true,
            undefined: true,
        }];
        let relocations = vec![Phase12ObjectRelocation {
            section: ".text".into(),
            offset: 0,
            kind: "i386-gotpc32".into(),
            symbol: "_GLOBAL_OFFSET_TABLE_".into(),
            addend: 0,
        }];
        assert!(phase12_native_imports_from_symbols_and_relocs(&symbols, &relocations).is_empty());
    }

    #[test]
    fn macho_nlist64_reads_section_ordinal_from_the_real_byte() {
        let mut bytes = vec![0_u8; 96];
        bytes[0..4].copy_from_slice(&0xfeedfacf_u32.to_le_bytes());
        bytes[16..20].copy_from_slice(&1_u32.to_le_bytes());
        bytes[20..24].copy_from_slice(&24_u32.to_le_bytes());
        bytes[32..36].copy_from_slice(&2_u32.to_le_bytes());
        bytes[36..40].copy_from_slice(&24_u32.to_le_bytes());
        bytes[40..44].copy_from_slice(&64_u32.to_le_bytes());
        bytes[44..48].copy_from_slice(&1_u32.to_le_bytes());
        bytes[48..52].copy_from_slice(&80_u32.to_le_bytes());
        bytes[52..56].copy_from_slice(&8_u32.to_le_bytes());
        bytes[64..68].copy_from_slice(&1_u32.to_le_bytes());
        bytes[68] = 0x0e;
        bytes[69] = 2;
        bytes[70..72].copy_from_slice(&0_u16.to_le_bytes());
        bytes[72..80].copy_from_slice(&0x1010_u64.to_le_bytes());
        bytes[80..88].copy_from_slice(b"\0local\0\0");

        let specs = vec![Phase12MachoSectionSpec {
            index: 2,
            name: "__bss".into(),
            segment: "__DATA".into(),
            addr: 0x1000,
            size: 0x100,
            offset: 0,
            align: 16,
            reloc_offset: 0,
            reloc_count: 0,
            flags: 1,
        }];
        let section_map =
            BTreeMap::from([(2_usize, (".bss".to_string(), 0x20_usize, vec![0; 0x100]))]);
        let symbols = phase12_macho_symbols(&bytes, &specs, &section_map);
        assert_eq!(symbols.len(), 2, "one nlist and one section anchor");
        assert_eq!(symbols[0].name, "local");
        assert_eq!(symbols[0].section.as_deref(), Some(".bss"));
        assert_eq!(symbols[0].offset, 0x30);
        assert!(!symbols[0].undefined);
    }

    #[test]
    fn macho_native_globals_publish_one_abi_neutral_alias() {
        let mut symbols = vec![
            Phase12ObjectSymbol {
                name: "_main".into(),
                section: ".text".into(),
                offset: 4,
                global: true,
            },
            Phase12ObjectSymbol {
                name: "___ncc_kernel_set_boot_info".into(),
                section: ".text".into(),
                offset: 8,
                global: true,
            },
            Phase12ObjectSymbol {
                name: "___local".into(),
                section: ".bss".into(),
                offset: 16,
                global: false,
            },
        ];
        phase12_macho_add_canonical_global_aliases(&mut symbols);
        assert!(symbols.iter().any(|symbol| symbol.name == "main"));
        assert!(symbols
            .iter()
            .any(|symbol| symbol.name == "__ncc_kernel_set_boot_info"));
        assert!(!symbols.iter().any(|symbol| symbol.name == "__local"));
    }

    #[test]
    fn aarch64_scaled_lo12_and_riscv_compressed_control_relocations_patch_bits() {
        for (reloc_type, kind) in [
            (278, "aarch64-ldst8-abs-lo12-nc"),
            (284, "aarch64-ldst16-abs-lo12-nc"),
            (285, "aarch64-ldst32-abs-lo12-nc"),
            (286, "aarch64-ldst64-abs-lo12-nc"),
            (299, "aarch64-ldst128-abs-lo12-nc"),
        ] {
            assert_eq!(
                phase12_elf_relocation_kind("aarch64", reloc_type),
                Some(kind)
            );
        }
        for (arch, reloc_type, kind) in [
            ("riscv32", 44, "riscv-rvc-branch"),
            ("riscv32", 45, "riscv-rvc-jump"),
            ("riscv64", 44, "riscv-rvc-branch"),
            ("riscv64", 45, "riscv-rvc-jump"),
        ] {
            assert_eq!(phase12_elf_relocation_kind(arch, reloc_type), Some(kind));
        }
        assert_eq!(phase12_elf_relocation_kind("riscv64", 1), Some("abs32"));
        assert_eq!(phase12_elf_relocation_kind("riscv64", 3), None);

        let rel = Phase12LinkedRelocation {
            section: "text".into(),
            offset: 0,
            kind: "test".into(),
            symbol: "target".into(),
            addend: 0,
        };
        let mut aarch64 = 0x39400000_u32.to_le_bytes().to_vec();
        phase12_apply_aarch64_ldst_lo12(&mut aarch64, &rel, 0x123, 1).expect("byte-scaled lo12");
        assert_eq!(read_u32(&aarch64, 0), 0x39400000 | (0x123 << 10));
        assert!(phase12_apply_aarch64_ldst_lo12(&mut aarch64, &rel, 0x123, 8).is_err());

        let text_va = 0x1000;
        let mut rvc_branch = 0xc001_u16.to_le_bytes().to_vec();
        phase12_apply_riscv_rvc_branch(&mut rvc_branch, &rel, text_va + 2, text_va)
            .expect("RVC branch +2");
        assert_eq!(read_u16(&rvc_branch, 0), 0xc009);
        let mut rvc_jump = 0xa001_u16.to_le_bytes().to_vec();
        phase12_apply_riscv_rvc_jump(&mut rvc_jump, &rel, text_va + 2, text_va)
            .expect("RVC jump +2");
        assert_eq!(read_u16(&rvc_jump, 0), 0xa009);
    }

