    #[test]
    fn linked_bss_units_preserve_each_input_alignment() {
        let make_input = |path: &str, unit: Phase12ObjectUnit| Phase12LinkInput {
            path: path.into(),
            source: None,
            object_format: "elf64".into(),
            link_unit_origin: "test".into(),
            bytes: Vec::new(),
            hash: hash_bytes(path.as_bytes()),
            dynamic_imports: Vec::new(),
            unit: Some(unit),
        };
        let first = make_input(
            "first.o",
            Phase12ObjectUnit {
                arch: "aarch64".into(),
                entry: Some("kmain".into()),
                text: vec![0xc0, 0x03, 0x5f, 0xd6],
                text_align: 4,
                rodata: Vec::new(),
                rodata_align: 1,
                data: vec![1, 2, 3, 4],
                data_align: 4,
                bss_size: 4,
                bss_align: 4,
                sections: Vec::new(),
                symbols: vec![
                    Phase12ObjectSymbol {
                        name: "kmain".into(),
                        section: ".text".into(),
                        offset: 0,
                        global: true,
                    },
                    Phase12ObjectSymbol {
                        name: "first_bss".into(),
                        section: ".bss".into(),
                        offset: 0,
                        global: true,
                    },
                ],
                relocations: Vec::new(),
            },
        );
        let second = make_input(
            "second.o",
            Phase12ObjectUnit {
                arch: "aarch64".into(),
                entry: None,
                text: Vec::new(),
                text_align: 1,
                rodata: Vec::new(),
                rodata_align: 1,
                data: Vec::new(),
                data_align: 1,
                bss_size: 8,
                bss_align: 16,
                sections: Vec::new(),
                symbols: vec![Phase12ObjectSymbol {
                    name: "second_bss".into(),
                    section: ".bss".into(),
                    offset: 0,
                    global: true,
                }],
                relocations: Vec::new(),
            },
        );
        let image = phase12_link_image(&[first, second]).expect("aligned BSS link");
        assert_eq!(image.bss_size, 24);
        assert_eq!(image.bss_align, 16);
        assert_eq!(image.symbols["first_bss"].offset, 0);
        assert_eq!(image.symbols["second_bss"].offset, 16);

        let executable = phase12_elf64_os_executable_bytes(&image, "aarch64-unknown-linux-gnu")
            .expect("aligned AArch64 ELF64 executable");
        let bss = elf_section_specs(&executable)
            .into_iter()
            .find(|section| section.name == ".bss")
            .expect("final ELF must contain .bss");
        let bss_addr = 0x400000_u64 + bss.offset as u64;
        assert_eq!(bss.align, 16);
        assert_eq!(bss_addr % 16, 0);
        let phoff = read_u64(&executable, 32) as usize;
        let phnum = read_u16(&executable, 56) as usize;
        let data_segment = (0..phnum)
            .map(|index| phoff + index * 56)
            .find(|offset| {
                read_u32(&executable, *offset) == 1 && read_u32(&executable, *offset + 4) == 6
            })
            .expect("final ELF must contain an RW PT_LOAD");
        let segment_va = read_u64(&executable, data_segment + 16);
        let filesz = read_u64(&executable, data_segment + 32);
        let memsz = read_u64(&executable, data_segment + 40);
        assert_eq!(memsz, bss_addr + bss.size as u64 - segment_va);
        assert!(
            memsz > filesz,
            "PT_LOAD memsz must include aligned NOBITS storage"
        );
    }

    #[test]
    fn final_elf_executables_preserve_material_section_alignment() {
        let image = |arch: &str| Phase12LinkedImage {
            arch: arch.to_string(),
            entry: "main".to_string(),
            text: vec![0xc3],
            text_align: 32,
            rodata: vec![0x5a; 32],
            rodata_align: 32,
            data: vec![0xa5; 64],
            data_align: 64,
            bss_size: 0,
            bss_align: 1,
            sections: Vec::new(),
            dynamic_imports: Vec::new(),
            null_symbols: BTreeSet::new(),
            symbols: BTreeMap::from([(
                "main".to_string(),
                Phase12LinkedSymbol {
                    section: "text".to_string(),
                    offset: 0,
                },
            )]),
            relocations: Vec::new(),
        };

        let elf64 = phase12_elf64_os_executable_bytes(&image("x86_64"), "x86_64-unknown-linux-gnu")
            .expect("aligned ELF64 executable");
        for (name, expected_align) in [(".text", 32_u64), (".rodata", 32), (".data", 64)] {
            let section = elf_section_specs(&elf64)
                .into_iter()
                .find(|section| section.name == name)
                .unwrap_or_else(|| panic!("ELF64 must contain {name}"));
            assert_eq!(section.align, expected_align);
            assert_eq!(section.offset as u64 % expected_align, 0);
        }

        let elf32 = phase12_elf32_os_executable_bytes(&image("i386"), "i386-unknown-linux-gnu")
            .expect("aligned ELF32 executable");
        for (name, expected_align) in [(".text", 32_u64), (".rodata", 32), (".data", 64)] {
            let section = elf32_section_specs(&elf32)
                .into_iter()
                .find(|section| section.name == name)
                .unwrap_or_else(|| panic!("ELF32 must contain {name}"));
            assert_eq!(section.align, expected_align);
            assert_eq!(section.offset as u64 % expected_align, 0);
        }
    }

    #[test]
    fn machine_immediates_parse_encode_and_reject_without_truncation() {
        assert_eq!(parse_int("0b1010"), Some(10));
        assert_eq!(parse_int("-0b1010"), Some(-10));
        assert_eq!(parse_int("$0x2a"), Some(42));
        assert_eq!(parse_int("#0o52"), Some(42));
        assert_eq!(parse_int("1_000_000"), Some(1_000_000));
        assert!(machine_immediate_fits_storage_bits(-128, 8));
        assert!(machine_immediate_fits_storage_bits(255, 8));
        assert!(!machine_immediate_fits_storage_bits(256, 8));
        assert!(machine_immediate_fits_storage_bits(
            i128::from(u64::MAX),
            64
        ));
        assert!(!machine_immediate_fits_storage_bits(
            i128::from(u64::MAX) + 1,
            64
        ));

        assert_eq!(
            x86_64_bytes("mov", &["rax", "-1"]),
            vec![0x48, 0xb8, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff]
        );
        assert_eq!(
            x86_64_bytes("mov", &["r8", "0xffff_ffff_ffff_ffff"]),
            vec![0x49, 0xb8, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "0b1010"]),
            vec![0x48, 0xb8, 0x0a, 0, 0, 0, 0, 0, 0, 0]
        );
        assert_eq!(
            x86_64_bytes("add", &["rax", "$0b1000_0000"]),
            vec![0x48, 0x81, 0xc0, 0x80, 0x00, 0x00, 0x00]
        );

        let too_large =
            try_encode_x86_64_instruction(&inst("mov", &["rax", "0x1_0000_0000_0000_0000"]))
                .expect_err("imm64 overflow must be rejected");
        assert_eq!(too_large.code, "E_MACHINE_IMMEDIATE_RANGE_001");

        let audit = parse_x86_64_instr_for_register_test("mov rax, 0x1_0000_0000_0000_0000");
        assert!(audit_has_code(&audit, "E_MACHINE_IMMEDIATE_RANGE_001"));
    }

    #[test]
    fn x86_64_rel_memory_mov_emits_pcrel_relocation() {
        let source = r#"
rareRelMachine[@machine] {
    target:
        arch: x86_64;
        abi: sysv64;
        object: elf64;
        endian: little;
        pointerWidth: 64;
        profile: userland;

    symbol:
        main:
            section: .text;
            binding: global;
            type: routine;

    entry:
        main;

    proc:
        main:

    instr:
        mov rax, qword ptr [rel packet_table];
        ret;

    data:
        packet_table:
            dq 0;

    seal:
        artifact: object;
        require: verified;
}
"#;
        let audit = parse_machine_source("<rare-rel-test>", source);
        assert!(audit.diagnostics.is_empty(), "{:?}", audit.diagnostics);
        let relocs = relocation_ir(&audit);
        assert_eq!(relocs.len(), 1);
        assert_eq!(relocs[0].section, ".text");
        assert_eq!(relocs[0].offset, 3);
        assert_eq!(relocs[0].symbol, "packet_table");
        assert_eq!(relocs[0].addend, -4);
        assert!(matches!(
            relocs[0].kind,
            ncc_ir::BackendObjectRelocationKindIR::PcRel32
        ));
    }

    #[test]
    fn x86_64_rip_relative_encoder_and_relocation_matrix() {
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rip-128]"]),
            vec![0x48, 0x8b, 0x05, 0x80, 0xff, 0xff, 0xff]
        );
        assert_eq!(
            x86_64_bytes("mov", &["qword ptr [rip+0x7fffffff]", "rax"]),
            vec![0x48, 0x89, 0x05, 0xff, 0xff, 0xff, 0x7f]
        );
        assert_eq!(
            x86_64_bytes("lea", &["r10", "[rip-0x80000000]"]),
            vec![0x4c, 0x8d, 0x15, 0x00, 0x00, 0x00, 0x80]
        );
        assert_eq!(
            x86_64_bytes("lea", &["rdi", "[rel packet_table+8]"]),
            vec![0x48, 0x8d, 0x3d, 0x00, 0x00, 0x00, 0x00]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr fs:[rel packet_table+8]"]),
            vec![0x64, 0x48, 0x8b, 0x05, 0x00, 0x00, 0x00, 0x00]
        );
        assert!(try_encode_x86_64_instruction(&inst(
            "mov",
            &["rax", "qword ptr [rip+0x80000000]"]
        ))
        .expect("rip disp32 overflow must be rejected")
        .is_none());
        assert!(
            try_encode_x86_64_instruction(&inst("mov", &["rax", "qword ptr [rip+rax]"]))
                .expect("rip+register must not be accepted as symbolic RIP-relative")
                .is_none()
        );

        let source = r#"
ripRelativeMachine[@machine] {
    target:
        arch: x86_64;
        abi: sysv64;
        object: elf64;
        endian: little;
        pointerWidth: 64;
        profile: userland;

    symbol:
        main:
            section: .text;
            binding: global;
            type: routine;

    entry:
        main;

    proc:
        main:

    instr:
        mov rax, qword ptr [rel packet_table+8];
        lea rdi, [rip+packet_table-4];
        mov qword ptr [packet_table+rip+16], rax;
        ret;

    data:
        packet_table:
            dq 0;

    seal:
        artifact: object;
        require: verified;
}
"#;
        let audit = parse_machine_source("<rip-relative-test>", source);
        assert!(audit.diagnostics.is_empty(), "{:?}", audit.diagnostics);
        let relocs = relocation_ir(&audit);
        assert_eq!(relocs.len(), 3);

        assert_eq!(relocs[0].section, ".text");
        assert_eq!(relocs[0].offset, 3);
        assert_eq!(relocs[0].symbol, "packet_table");
        assert_eq!(relocs[0].addend, 4);
        assert!(matches!(
            relocs[0].kind,
            ncc_ir::BackendObjectRelocationKindIR::PcRel32
        ));

        assert_eq!(relocs[1].section, ".text");
        assert_eq!(relocs[1].offset, 10);
        assert_eq!(relocs[1].symbol, "packet_table");
        assert_eq!(relocs[1].addend, -8);
        assert!(matches!(
            relocs[1].kind,
            ncc_ir::BackendObjectRelocationKindIR::PcRel32
        ));

        assert_eq!(relocs[2].section, ".text");
        assert_eq!(relocs[2].offset, 17);
        assert_eq!(relocs[2].symbol, "packet_table");
        assert_eq!(relocs[2].addend, 12);
        assert!(matches!(
            relocs[2].kind,
            ncc_ir::BackendObjectRelocationKindIR::PcRel32
        ));
    }

    #[test]
    fn x86_64_absolute_moffs_encoder_matrix() {
        assert_eq!(
            x86_64_bytes("mov", &["al", "moffs8 [0]"]),
            vec![0xa0, 0, 0, 0, 0, 0, 0, 0, 0]
        );
        assert_eq!(
            x86_64_bytes("mov", &["moffs8 [0]", "al"]),
            vec![0xa2, 0, 0, 0, 0, 0, 0, 0, 0]
        );
        assert_eq!(
            x86_64_bytes("mov", &["ax", "moffs16 [0x1234]"]),
            vec![0x66, 0xa1, 0x34, 0x12, 0, 0, 0, 0, 0, 0]
        );
        assert_eq!(
            x86_64_bytes("mov", &["moffs16 [0x1234]", "ax"]),
            vec![0x66, 0xa3, 0x34, 0x12, 0, 0, 0, 0, 0, 0]
        );
        assert_eq!(
            x86_64_bytes("mov", &["eax", "moffs32 [0x11223344]"]),
            vec![0xa1, 0x44, 0x33, 0x22, 0x11, 0, 0, 0, 0]
        );
        assert_eq!(
            x86_64_bytes("mov", &["moffs32 [0x11223344]", "eax"]),
            vec![0xa3, 0x44, 0x33, 0x22, 0x11, 0, 0, 0, 0]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "moffs64 [0x1122334455667788]"]),
            vec![0x48, 0xa1, 0x88, 0x77, 0x66, 0x55, 0x44, 0x33, 0x22, 0x11]
        );
        assert_eq!(
            x86_64_bytes("mov", &["moffs64 [0x1122334455667788]", "rax"]),
            vec![0x48, 0xa3, 0x88, 0x77, 0x66, 0x55, 0x44, 0x33, 0x22, 0x11]
        );
        assert_eq!(
            x86_64_bytes("mov", &["eax", "moffs32 fs:[0x10]"]),
            vec![0x64, 0xa1, 0x10, 0, 0, 0, 0, 0, 0, 0]
        );
        assert_eq!(
            x86_64_bytes("mov", &["moffs64 gs:[0xffff_ffff_ffff_ffff]", "rax"]),
            vec![0x65, 0x48, 0xa3, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff]
        );
        assert!(
            try_encode_x86_64_instruction(&inst("mov", &["rbx", "moffs64 [0]"]))
                .expect("moffs load must be accumulator-only")
                .is_none()
        );
        assert!(
            try_encode_x86_64_instruction(&inst("mov", &["rax", "moffs32 [0]"]))
                .expect("moffs width must match accumulator width")
                .is_none()
        );
        assert!(
            try_encode_x86_64_instruction(&inst("mov", &["rax", "moffs64 [-1]"]))
                .expect("negative absolute address must be rejected")
                .is_none()
        );
        assert!(try_encode_x86_64_instruction(&inst(
            "mov",
            &["rax", "moffs64 [0x1_0000_0000_0000_0000]"]
        ))
        .expect("moffs absolute address must fit u64")
        .is_none());
        assert!(
            parse_x86_memory_operand("qword ptr [0x1122334455667788]").is_none(),
            "absolute moffs must remain explicit and not be parsed as ModRM/SIB memory"
        );
    }

    #[test]
    fn x86_64_segment_override_encoder_matrix() {
        let segments: [(&str, u8); 6] = [
            ("es", 0x26),
            ("cs", 0x2e),
            ("ss", 0x36),
            ("ds", 0x3e),
            ("fs", 0x64),
            ("gs", 0x65),
        ];

        for (segment, prefix) in segments {
            let op = format!("qword ptr {segment}:[rax]");
            assert_eq!(
                x86_64_bytes("mov", &["rax", &op]),
                vec![prefix, 0x48, 0x8b, 0x00],
                "{segment} base load"
            );
            assert_eq!(
                x86_64_bytes("mov", &[&op, "rax"]),
                vec![prefix, 0x48, 0x89, 0x00],
                "{segment} base store"
            );

            let sib_op = format!("qword ptr {segment}:[r9+r11*8+0x7f]");
            assert_eq!(
                x86_64_bytes("mov", &["r10", &sib_op]),
                vec![prefix, 0x4f, 0x8b, 0x54, 0xd9, 0x7f],
                "{segment} full SIB load"
            );

            let rel_op = format!("qword ptr {segment}:[rel packet_table+8]");
            assert_eq!(
                x86_64_bytes("mov", &["rax", &rel_op]),
                vec![prefix, 0x48, 0x8b, 0x05, 0, 0, 0, 0],
                "{segment} RIP-relative symbolic load"
            );

            let direct_op = format!("qword ptr {segment}:[packet_table+8]");
            assert_eq!(
                x86_64_bytes("mov", &["rax", &direct_op]),
                vec![prefix, 0x48, 0x8b, 0x04, 0x25, 0x08, 0, 0, 0],
                "{segment} direct symbolic load"
            );
        }

        assert_eq!(
            x86_64_bytes("xadd", &["word ptr fs:[rax]", "bx"]),
            vec![0x64, 0x66, 0x0f, 0xc1, 0x18]
        );
        assert_eq!(
            x86_64_bytes("lock", &["add qword ptr fs:[rax]", "1"]),
            vec![0xf0, 0x64, 0x48, 0x83, 0x00, 0x01]
        );
        assert_eq!(
            x86_64_bytes("lock", &["cmpxchg16b xmmword ptr gs:[rax]"]),
            vec![0xf0, 0x65, 0x48, 0x0f, 0xc7, 0x08]
        );
        assert_eq!(
            x86_64_bytes("mov", &["ax", "moffs16 cs:[0x1234]"]),
            vec![0x2e, 0x66, 0xa1, 0x34, 0x12, 0, 0, 0, 0, 0, 0]
        );
        assert_eq!(
            x86_64_bytes("mov", &["moffs32 ds:[0x10]", "eax"]),
            vec![0x3e, 0xa3, 0x10, 0, 0, 0, 0, 0, 0, 0]
        );
        assert!(
            try_encode_x86_64_instruction(&inst("lea", &["rax", "qword ptr fs:[rax]"]))
                .expect("lea must reject segment-qualified memory")
                .is_none()
        );
        assert!(
            try_encode_x86_64_instruction(&inst("mov", &["rax", "qword ptr hs:[rax]"]))
                .expect("unknown segment override must be rejected")
                .is_none()
        );
        assert!(
            try_encode_x86_64_instruction(&inst("mov", &["rax", "qword ptr fs:gs:[rax]"]))
                .expect("stacked segment overrides must be rejected")
                .is_none()
        );
    }

    #[test]
    fn x86_64_stack_relative_encoder_matrix() {
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rsp]"]),
            vec![0x48, 0x8b, 0x04, 0x24]
        );
        assert_eq!(
            x86_64_bytes("mov", &["qword ptr [rsp]", "rax"]),
            vec![0x48, 0x89, 0x04, 0x24]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rsp+127]"]),
            vec![0x48, 0x8b, 0x44, 0x24, 0x7f]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rsp-128]"]),
            vec![0x48, 0x8b, 0x44, 0x24, 0x80]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rsp+128]"]),
            vec![0x48, 0x8b, 0x84, 0x24, 0x80, 0, 0, 0]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rsp-129]"]),
            vec![0x48, 0x8b, 0x84, 0x24, 0x7f, 0xff, 0xff, 0xff]
        );
        assert_eq!(
            x86_64_bytes("lea", &["r10", "qword ptr [rsp+0x20]"]),
            vec![0x4c, 0x8d, 0x54, 0x24, 0x20]
        );
        assert_eq!(
            x86_64_bytes("mov", &["qword ptr fs:[rsp+0x20]", "rax"]),
            vec![0x64, 0x48, 0x89, 0x44, 0x24, 0x20]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rsp+rsi*2+0x20]"]),
            vec![0x48, 0x8b, 0x44, 0x74, 0x20]
        );
        assert_ne!(
            x86_64_bytes("mov", &["rax", "qword ptr [rsp]"]),
            x86_64_bytes("mov", &["rax", "qword ptr [rbp]"])
        );
        assert!(
            try_encode_x86_64_instruction(&inst("mov", &["rax", "qword ptr [rsp*2]"]))
                .expect("rsp cannot be an index-only stack operand")
                .is_none()
        );
        assert!(try_encode_x86_64_instruction(&inst(
            "mov",
            &["rax", "qword ptr [rsp+0x80000000]"]
        ))
        .expect("stack displacement must stay inside signed i32")
        .is_none());
    }

    #[test]
    fn x86_64_frame_relative_encoder_matrix() {
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rbp]"]),
            vec![0x48, 0x8b, 0x45, 0x00]
        );
        assert_eq!(
            x86_64_bytes("mov", &["qword ptr [rbp]", "rax"]),
            vec![0x48, 0x89, 0x45, 0x00]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rbp+127]"]),
            vec![0x48, 0x8b, 0x45, 0x7f]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rbp-128]"]),
            vec![0x48, 0x8b, 0x45, 0x80]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rbp+128]"]),
            vec![0x48, 0x8b, 0x85, 0x80, 0, 0, 0]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rbp-129]"]),
            vec![0x48, 0x8b, 0x85, 0x7f, 0xff, 0xff, 0xff]
        );
        assert_eq!(
            x86_64_bytes("lea", &["r10", "qword ptr [rbp-0x20]"]),
            vec![0x4c, 0x8d, 0x55, 0xe0]
        );
        assert_eq!(
            x86_64_bytes("mov", &["qword ptr ss:[rbp-0x8]", "rax"]),
            vec![0x36, 0x48, 0x89, 0x45, 0xf8]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rbp+rsi*2]"]),
            vec![0x48, 0x8b, 0x44, 0x75, 0x00]
        );
        assert_eq!(
            x86_64_bytes("mov", &["rax", "qword ptr [rbp+rsi*2+0x20]"]),
            vec![0x48, 0x8b, 0x44, 0x75, 0x20]
        );
        assert_eq!(
            x86_64_bytes("mov", &["r10", "qword ptr [r13]"]),
            vec![0x4d, 0x8b, 0x55, 0x00]
        );
        assert_ne!(
            x86_64_bytes("mov", &["rax", "qword ptr [rbp]"]),
            x86_64_bytes("mov", &["rax", "qword ptr [rsp]"])
        );
        assert!(try_encode_x86_64_instruction(&inst(
            "mov",
            &["rax", "qword ptr [rbp+0x80000000]"]
        ))
        .expect("frame displacement must stay inside signed i32")
        .is_none());
        assert!(
            try_encode_x86_64_instruction(&inst("lea", &["rax", "qword ptr ss:[rbp]"]))
                .expect("lea must reject segment-qualified frame memory")
                .is_none()
        );
        assert!(
            try_encode_x86_64_instruction(&inst("mov", &["rax", "qword ptr [rbp+rsp*2]"]))
                .expect("rsp cannot be used as an index in frame-relative SIB")
                .is_none()
        );
    }

    #[test]
    fn x86_64_direct_memory_symbol_emits_abs32_relocation() {
        let source = r#"
directMemoryMachine[@machine] {
    target:
        arch: x86_64;
        abi: sysv64;
        object: elf64;
        endian: little;
        pointerWidth: 64;
        profile: userland;

    symbol:
        main:
            section: .text;
            binding: global;
            type: routine;

    entry:
        main;

    proc:
        main:

    instr:
        mov rax, qword ptr [packet_table];
        lea rdi, [packet_table+8];
        ret;

    data:
        packet_table:
            dq 0;

    seal:
        artifact: object;
        require: verified;
}
"#;
        let audit = parse_machine_source("<direct-memory-test>", source);
        assert!(audit.diagnostics.is_empty(), "{:?}", audit.diagnostics);
        let relocs = relocation_ir(&audit);
        assert_eq!(relocs.len(), 2);
        assert_eq!(relocs[0].section, ".text");
        assert_eq!(relocs[0].offset, 4);
        assert_eq!(relocs[0].symbol, "packet_table");
        assert_eq!(relocs[0].addend, 0);
        assert!(matches!(
            relocs[0].kind,
            ncc_ir::BackendObjectRelocationKindIR::Abs32
        ));
        assert_eq!(relocs[1].section, ".text");
        assert_eq!(relocs[1].offset, 12);
        assert_eq!(relocs[1].symbol, "packet_table");
        assert_eq!(relocs[1].addend, 8);
        assert!(matches!(
            relocs[1].kind,
            ncc_ir::BackendObjectRelocationKindIR::Abs32
        ));
    }

