    #[test]
    fn i386_external_call_relocations_follow_intervening_instruction_bytes() {
        let source = r#"
i386CallRelocs[@machine] {
    target:
        arch: i386;
        abi: i386-sysv;
        object: elf32;
        endian: little;
        pointerWidth: 32;
        profile: userland;

    extern:
        first:
        second:

    symbol:
        main:
            section: .text;
            binding: global;
            type: routine;

    entry:
        main;

    proc:
        main:

    instr:
        call first;
        push eax;
        call second;
        add esp, 4;
        ret;

    verify:
        target;
        encoding;
        object;

    seal:
        artifact: object;
        require: verified;
}
"#;
        let mut audit = parse_machine_source("<i386-call-relocations>", source);
        validate_machine(&mut audit);
        let instructions = audit.instructions.clone();
        audit.encoded_bytes =
            encode_instructions_for_arch("i386", &instructions, &mut audit.diagnostics);
        assert!(audit.diagnostics.is_empty(), "{:?}", audit.diagnostics);
        assert_eq!(
            audit.encoded_bytes,
            vec![0xe8, 0, 0, 0, 0, 0x50, 0xe8, 0, 0, 0, 0, 0x83, 0xc4, 0x04, 0xc3,]
        );
        let relocs = relocation_ir(&audit);
        assert_eq!(relocs.len(), 2);
        assert_eq!(relocs[0].offset, 1);
        assert_eq!(relocs[0].symbol, "first");
        assert_eq!(relocs[1].offset, 7);
        assert_eq!(relocs[1].symbol, "second");
    }

    #[test]
    fn aarch64_base_extended_encoder_bytes() {
        let mut diagnostics = Vec::new();
        let bytes = encode_aarch64_instructions(
            &[
                inst("add", &["x0", "x1", "x2"]),
                inst("b.eq", &["8"]),
                inst("cbnz", &["x0", "8"]),
                inst("mul", &["x0", "x1", "x2"]),
                inst("ldrb", &["w0", "[x1, 3]"]),
                inst("ldur", &["x0", "[x1, #-8]"]),
                inst("stur", &["w2", "[x3, #12]"]),
                inst("svc", &["0"]),
                inst("yield", &[]),
                inst("wfi", &[]),
            ],
            &mut diagnostics,
        );
        assert!(diagnostics.is_empty(), "{diagnostics:?}");
        assert_eq!(
            bytes,
            vec![
                0x20, 0x00, 0x02, 0x8b, // add x0,x1,x2
                0x40, 0x00, 0x00, 0x54, // b.eq 8
                0x40, 0x00, 0x00, 0xb5, // cbnz x0,8
                0x20, 0x7c, 0x02, 0x9b, // mul x0,x1,x2
                0x20, 0x0c, 0x40, 0x39, // ldrb w0,[x1,3]
                0x20, 0x80, 0x5f, 0xf8, // ldur x0,[x1,#-8]
                0x62, 0xc0, 0x00, 0xb8, // stur w2,[x3,#12]
                0x01, 0x00, 0x00, 0xd4, // svc #0
                0x3f, 0x20, 0x03, 0xd5, // yield
                0x7f, 0x20, 0x03, 0xd5, // wfi
            ]
        );
    }

