    #[test]
    fn riscv32_imac_extended_encoder_bytes() {
        let mut diagnostics = Vec::new();
        let bytes = encode_riscv32_instructions(
            &[
                inst("add", &["a0", "a0", "a1"]),
                inst("addi", &["a0", "a0", "1"]),
                inst("slli", &["a0", "a0", "3"]),
                inst("lb", &["a0", "0(a1)"]),
                inst("sb", &["a0", "4(a1)"]),
                inst("beq", &["a0", "a1", "8"]),
                inst("jal", &["ra", "16"]),
                inst("csrrw", &["a0", "0x300", "a1"]),
                inst("lr.w.aq", &["a0", "(a1)"]),
                inst("amoadd.w.aqrl", &["a0", "a2", "(a1)"]),
                inst("c.li", &["a0", "1"]),
            ],
            &mut diagnostics,
        );
        assert!(diagnostics.is_empty(), "{diagnostics:?}");
        assert_eq!(
            bytes,
            vec![
                0x33, 0x05, 0xb5, 0x00, // add a0,a0,a1
                0x13, 0x05, 0x15, 0x00, // addi a0,a0,1
                0x13, 0x15, 0x35, 0x00, // slli a0,a0,3
                0x03, 0x85, 0x05, 0x00, // lb a0,0(a1)
                0x23, 0x82, 0xa5, 0x00, // sb a0,4(a1)
                0x63, 0x04, 0xb5, 0x00, // beq a0,a1,8
                0xef, 0x00, 0x00, 0x01, // jal ra,16
                0x73, 0x95, 0x05, 0x30, // csrrw a0,0x300,a1
                0x2f, 0xa5, 0x05, 0x14, // lr.w.aq a0,(a1)
                0x2f, 0xa5, 0xc5, 0x06, // amoadd.w.aqrl a0,a2,(a1)
                0x05, 0x45, // c.li a0,1
            ]
        );
    }

