            assert_eq!(encode("wfi", &[]), 0x10500073u32.to_le_bytes());
            assert_eq!(encode("sret", &[]), 0x10200073u32.to_le_bytes());
            assert_eq!(encode("mret", &[]), 0x30200073u32.to_le_bytes());
            assert_eq!(encode("sfence.vma", &[]), 0x12000073u32.to_le_bytes());
            assert_eq!(encode("sfence.vma", &["a0"]), 0x12050073u32.to_le_bytes());
