    #[test]
    fn riscv_local_control_targets_resolve_and_external_jal_keeps_relocation_placeholder() {
        let instructions = vec![
            inst("beq", &["a0", "a1", "done"]),
            inst("jal", &["ra", "done"]),
            inst("nop", &[]),
            inst("label", &["done"]),
            inst("ret", &[]),
        ];
        let mut diagnostics = Vec::new();
        let bytes = encode_riscv32_instructions(&instructions, &mut diagnostics);
        assert!(diagnostics.is_empty(), "{diagnostics:?}");
        let expected_branch =
            encode_riscv_branch(&inst("beq", &["a0", "a1", "12"])).expect("resolved branch");
        let expected_jal = encode_riscv_jal(&inst("jal", &["ra", "8"])).expect("resolved jal");
        assert_eq!(read_u32(&bytes, 0), expected_branch);
        assert_eq!(read_u32(&bytes, 4), expected_jal);

        diagnostics.clear();
        let external = encode_riscv32_instructions(
            &[inst("jal", &["ra", "external_symbol"])],
            &mut diagnostics,
        );
        assert!(diagnostics.is_empty(), "{diagnostics:?}");
        assert_eq!(external, 0x0000_00ef_u32.to_le_bytes());
    }

    #[test]
    fn x86_virtualization_decoder_recovers_every_declared_opcode() {
        let cases = [
            (vec![0xf3, 0x0f, 0xc7, 0x30], "vmxon"),
            (vec![0x66, 0x0f, 0xc7, 0x30], "vmclear"),
            (vec![0x0f, 0xc7, 0x30], "vmptrld"),
            (vec![0x0f, 0xc7, 0x38], "vmptrst"),
            (vec![0x0f, 0x78, 0xd8], "vmread"),
            (vec![0x0f, 0x79, 0xc3], "vmwrite"),
            (vec![0x66, 0x0f, 0x38, 0x80, 0x03], "invept"),
            (vec![0x66, 0x0f, 0x38, 0x81, 0x03], "invvpid"),
            (vec![0x66, 0x0f, 0x38, 0x82, 0x03], "invpcid"),
            (vec![0x0f, 0x01, 0xc1], "vmcall"),
            (vec![0x0f, 0x01, 0xc4], "vmxoff"),
            (vec![0x0f, 0x01, 0xc2], "vmlaunch"),
            (vec![0x0f, 0x01, 0xc3], "vmresume"),
            (vec![0x0f, 0x01, 0xd8], "vmrun"),
            (vec![0x0f, 0x01, 0xd9], "vmmcall"),
            (vec![0x0f, 0x01, 0xda], "vmload"),
            (vec![0x0f, 0x01, 0xdb], "vmsave"),
            (vec![0x0f, 0x01, 0xdc], "stgi"),
            (vec![0x0f, 0x01, 0xdd], "clgi"),
            (vec![0x0f, 0x01, 0xdf], "invlpga"),
        ];
        for (bytes, expected) in cases {
            let decoded = decode_one_x86_64_instruction(&bytes, 0)
                .unwrap_or_else(|| panic!("failed to decode {expected}"));
            assert_eq!(decoded.mnemonic, expected);
            assert_eq!(decoded.length, bytes.len());
            assert_eq!(decoded.feature_family, "virtualization");
        }
    }

