    #[test]
    fn cross_arch_decoders_recover_backend_emitted_return_sequences() {
        let (aarch64, aarch64_unknown) =
            decode_aarch64_instructions(&[0xe0, 0x03, 0x1f, 0x2a, 0xc0, 0x03, 0x5f, 0xd6]);
        assert!(aarch64_unknown.is_empty(), "{aarch64_unknown:?}");
        assert_eq!(
            aarch64
                .iter()
                .map(|instruction| instruction.mnemonic.as_str())
                .collect::<Vec<_>>(),
            ["mov", "ret"]
        );

        let (riscv64, riscv64_unknown) = decode_riscv64_instructions(&[0x01, 0x45, 0x82, 0x80]);
        assert!(riscv64_unknown.is_empty(), "{riscv64_unknown:?}");
        assert_eq!(
            riscv64
                .iter()
                .map(|instruction| instruction.mnemonic.as_str())
                .collect::<Vec<_>>(),
            ["c.li", "c.ret"]
        );

        let (riscv32, riscv32_unknown) = decode_riscv32_instructions(&[0x01, 0x45, 0x82, 0x80]);
        assert!(riscv32_unknown.is_empty(), "{riscv32_unknown:?}");
        assert_eq!(
            riscv32
                .iter()
                .map(|instruction| instruction.mnemonic.as_str())
                .collect::<Vec<_>>(),
            ["c.li", "c.ret"]
        );

        let (thumb, thumb_unknown) =
            decode_thumb_instructions(&[0x00, 0xb5, 0xff, 0xf7, 0xfe, 0xff, 0x00, 0xbd]);
        assert!(thumb_unknown.is_empty(), "{thumb_unknown:?}");
        assert_eq!(
            thumb
                .iter()
                .map(|instruction| instruction.mnemonic.as_str())
                .collect::<Vec<_>>(),
            ["push", "bl", "pop"]
        );
    }

